  [1] = "en", [2] = "es", [3] = "fr", [4] = "de", [5] = "it",
  [6] = "pt", [7] = "nl", [8] = "pl", [9] = "sv", [10] = "cs",
  [11] = "ro", [12] = "tr", [13] = "ru", [14] = "uk",
  [15] = "zh-Hans", [16] = "zh-Hant", [17] = "ja", [18] = "ko",
  [19] = "vi", [20] = "id",
