  chat_auto_follow  = true,    -- stream follows bottom until user scrolls upward
  _chat_scroll_prev_y = nil,   -- prior chat scroll position for user intent detection
  scroll_to_top     = false,   -- set true to smooth-scroll chat to top
  scroll_to_msg     = nil,    -- message index to smooth-scroll to (top of viewport)
  scroll_to_msg_frames = nil, -- frame counter for scroll_to_msg auto-expiry
  from_card         = false,   -- true when current send was triggered by a welcome card
  logo_alpha        = 0,       -- 0..1 alpha for bottom-right mini logo fade
  _top_logo_visible = true,    -- true until welcome screen scrolls away
  script_open       = true,    -- false triggers shutdown in loop()
  screen_reader_mode = RA.launch_screen_reader_mode == true,
  screen_reader_startup_intent = RA.launch_screen_reader_mode == true
    or RA.prefer_screen_reader_enabled(),
  startup_first_frame_submitted = false,
  startup_post_paint_phase = "legacy_cleanup",
  -- Session start timestamp. Captured once at script load for the
  -- Feedback diagnostic report's "Session uptime" line -- helps
  -- triage bugs where staleness / memory growth after long runs
  -- matters (e.g. "after 6h the UI froze").
  session_start_ts  = reaper.time_precise(),
  send_time         = nil,     -- time_precise() at curl launch; for watchdog
  timeout_extensions = 0,      -- # of "Extend by Ns" clicks against the current
                               -- in-flight curl. Reset to 0 in Net.fire_curl
                               -- since send_time is reset there too -- previous
                               -- extensions are baked into history. Used by UI
                               -- to display poll_timeout + extensions*EXTEND_BY_SECS.
  -- Token accumulators (reset each script run)
  session_tok_in    = 0,
  session_tok_out   = 0,
  session_tok_out_visible = 0,
  session_tok_out_reasoning = 0,
  session_output_usage_calls = 0,
  session_output_split_calls = 0,
  session_cost      = 0,       -- cumulative USD cost for the session
  session_cost_unknown = false, -- one settled call lacked exact accounting
  -- curl/poll state
  curl_pid          = nil,     -- truthy while a request is pending, nil when idle
  curl_debug        = nil,     -- structured diagnostics for the in-flight curl
  request_lane      = nil,     -- "engine" or "curl" for the active Net request
  engine_handle     = nil,     -- active MBH_Http handle table, engine lane only
  google_interactions_conversation = nil, -- committed Engine-owned continuity
  google_interactions_pending = nil, -- settled request awaiting Lua acceptance
  google_interactions_context_cache = nil, -- memoized context revision inputs
  engine_accumulator = nil,    -- provider stream accumulator, engine lane only
  engine_inference_v1 = false, -- active Engine lane uses MBH_InferenceV1*
  engine_settled_metadata = nil, -- detached ABI2 metadata awaiting settled parse
  engine_artifact_retry_deadline = nil, -- local file-read deadline after settlement
  engine_status_retry_used = false, -- one local status-read retry per ABI2 request
  engine_raw_parts  = nil,     -- non-streaming engine response chunks
  engine_streaming  = false,   -- current request uses provider SSE streaming
  engine_had_payload = false,  -- any event or raw byte reached Lua
  engine_display_idx = nil,    -- provisional assistant display row
  engine_revising   = false,   -- validator repair is visibly replacing a stream
  last_response_was_streamed = false,
  engine_fallback_reason = nil,
  curl_launch_result_class = nil, -- coarse Windows launcher result for diagnostics
  curl_os_pid       = nil,     -- OS PID of in-flight curl process (for Cancel kill)
  curl_exited_clean = false,   -- true once exit code 0 has been observed; response
                               -- parsing must wait for this so partial writes are
                               -- never mistaken for complete JSON.
  kill_pending      = false,   -- Cancel was clicked but tmp.pid hadn't appeared
                               -- yet; main loop retries the kill until it lands.
  kill_pending_until = 0,      -- deadline (time_precise) for kill_pending retry
  last_poll_time    = 0,       -- timestamp of last poll-loop file check
  pending_provider_idx = nil,  -- provider index snapshot at send time (for response parsing)
  pending_model_idx    = nil,  -- model index snapshot at send time
  pending_thinking_idx = nil,  -- thinking index snapshot at send time
  pending_pricing_at_utc = nil, -- Unix timestamp captured when the request starts
  pending_pricing_snapshot = nil, -- detached immutable rates for settlement
  pending_jsfx_intent  = nil,  -- mirror of CTX.prompt_indicates_jsfx for the in-flight
                               -- turn, so the JSFX validator-retry path can rebuild the
                               -- snapshot with the same minimal-tracks trim used on the
                               -- first request
  pending_drum_edit_intent = nil, -- mirrors CTX.prompt_indicates_drum_edit
                                  -- so retry snapshot rebuilds keep the
                                  -- Dynamic Split settings context
  -- Retry state for provider overload auto-retry
  retry_count       = 0,
  retry_max         = CFG.MAX_RETRIES,
  retry_scheduled   = false,
  retry_fire_time   = 0,
  retry_saved_body  = nil,     -- saved request body for retry
  retry_saved_provider_idx = nil,
  retry_saved_model_idx    = nil,
  retry_saved_thinking_idx = nil,
  schannel_revocation_retry_pending = false,
  schannel_revocation_retry_used = false,
  schannel_revocation_original_error = nil,
  validator_retry_cap_streak = 0, -- consecutive turns ended by validator retry cap
  pending_attachments     = nil,  -- snapshot of attachments for rebuild retries
  -- API reference. Single physical file (Resources/API_Ref.md)
  -- with seven SECTION-marker buckets (core, extended, items, envelopes,
  -- take_fx, routing, tempo). One loader populates the cache; each bucket
  -- is still served individually via CTX.docs / CTX.docs_extended /
  -- CTX.docs_section.
  api_ref_message        = nil, -- pinned API ref message, or nil
  api_ref_section_cache  = nil, -- {[bucket]=content} parsed from the API ref file; lazy-init
  api_ref_loaded         = nil, -- bool: true after the API ref file has been read (success or fail)
  _api_ref_section_err   = nil, -- {[bucket]=err_string} per-bucket error map; lazy-init
  -- MIDI reference (auto-injected when user prompt contains "midi", or
  -- on-demand via <context_needed>midi</context_needed>). Mirrors api_ref:
  -- once set, prepended to every request as a synthetic user/assistant pair.
  -- Body content lives in API_Ref.md (SECTION:midi); served via CTX.midi.
  midi_ref_message  = nil,     -- pinned MIDI ref message, or nil
  -- Theme reference (on-demand via <context_needed>theme</context_needed>).
  -- Auto-injected when user prompt contains "theme" + color-related keywords.
  -- Once set, prepended to every request as a synthetic message, like api_ref.
  -- Body content lives in API_Ref.md (SECTION:theme); served via CTX.theme.
  theme_ref_message = nil,     -- pinned theme ref message, or nil
  -- Gemini explicit context cache (paid tier only, when api_ref is loaded).
  -- Caches system_instruction (including Custom Instructions when enabled) +
  -- api_ref priming exchange to reduce per-turn input token cost. Created
  -- lazily at send time; deleted on invalidation.
  gemini_cache_name     = nil, -- e.g. "cachedContents/abc123"
  gemini_cache_model    = nil, -- model id the cache is bound to
  gemini_cache_signature = nil, -- source fingerprint for system/custom prefs + api_ref
  gemini_cache_sig_sys = nil,   -- memo input for gemini_cache_source_signature
  gemini_cache_sig_ref = nil,   -- memo input for gemini_cache_source_signature
  gemini_cache_sig_value = nil, -- memo output for gemini_cache_source_signature
  gemini_cache_expires  = 0,   -- os.time() epoch seconds when cache expires
  -- Native explicit-cache state. Lua retains only the opaque Engine token and
  -- nonsecret exact binding. The provider cache name and API key never cross
  -- this boundary.
  gemini_cache_engine_handle = nil,
  gemini_cache_engine_token = nil,
  gemini_cache_engine_binding = nil,
  gemini_cache_engine_restore_attempted = false,
  gemini_cache_engine_cleanup_handles = {},
  gemini_cache_creating   = false, -- true while a cache-create curl is in flight
  gemini_cache_create_aborted = false, -- true when an in-flight create was invalidated
  gemini_cache_started_at = 0,     -- time_precise() when cache-create curl launched (watchdog)
  gemini_cache_last_state = nil,   -- request-time cache diagnostics for bench/details
  gemini_cache_last_used  = false, -- true when the last Gemini body used cachedContent
  gemini_cache_last_create_reason = nil, -- last explicit-cache create outcome/blocker
  openai_prompt_cache_key = nil, -- persisted routing-affinity key for OpenAI prompt cache
  openai_safety_identifier = nil, -- domain-separated hash sent only to hosted OpenAI
  last_cache_poll_time    = 0,     -- throttle for cache-create response polling
  -- Script save state
  saved_script_path = nil,
  open_actions_modal = false,
  js_hint_shown     = false,
  -- Wrap cache
  wrap_cache        = {},
  -- API key state
  api_key           = nil,     -- decoded API key for the active provider (convenience alias)
  api_key_map       = {},      -- decoded per-provider keys: {anthropic=key, openai=key, google=key, ...}
                               -- (distinct from the `api_keys` screen-state namespace)
  key_install_moved = false,   -- true if key decode failed due to moved install
  key_test_pending  = false,   -- true while validation request is in flight
  key_test_provider = nil,     -- provider id being tested (for multi-key validation)
  key_test_armed    = nil,     -- {provider, armed_at}: deferred fire when curl_pid was busy at fire_key_test time; loop fires it once curl clears (30s ceiling)
  gemini_paid_tier    = nil,   -- nil=unknown, true=paid, false=free
  gemini_tier_pending = false, -- true while tier test is in flight
  show_gemini_free_warn = false, -- triggers free-tier warning popup next frame
  open_no_tracks_warn   = false, -- triggers no-tracks-selected popup next frame
  -- Context follow-up state
  pending_orig_prompt    = nil,    -- bare user text, saved for follow-up resend
  pending_output_note    = nil,    -- exact same-turn Lua guidance reused by validator retries
  pending_typed_action_expected = false, -- true when a typed-action contract was appended to this turn
  pending_typed_action_response_format = false, -- true when OpenAI response_format should emit raw typed-action JSON
  pending_typed_action_profile = nil, -- optional model-scoped typed-action strengthening profile key
  pending_typed_action_lua_generation = nil, -- generation-only request linked to its exact source edit
  pending_answer_only_followup = nil, -- true when this turn suppresses snapshot/static/sticky context
  pending_starter_card_key = nil, -- exact informational card using the same lightweight context lane
  pending_snapshot       = nil,    -- snapshot from original send
  docs_already_sent      = false,  -- one-shot guard per turn
  docs_extended_already_sent = false,  -- one-shot guard per turn (extended)
  docs_section_sent      = {},     -- {[section]=true} per-turn dedup; mirrors plugin_ref_sent
                                   -- shape so a repeat <context_needed>docs:envelopes</context_needed>
                                   -- silently dedups instead of refetching
  docs_fetched_session   = false,  -- session-level flag: docs has been inlined
                                   -- into history at least once this chat.
                                   -- Used by the docs-gate to know whether
                                   -- reaper.* in a reply was guessed or was
                                   -- grounded in the reference. Survives until
                                   -- session clear / factory reset.
  session_already_sent   = false,
  tracks_already_sent    = false,
  fx_params_already_sent = false,
  plugin_ref_sent          = {},   -- set of plugin names sent this turn (dedup per-name, not turn-wide)
  plugin_ref_failed        = {},   -- names whose curated pack lookup failed integrity this turn
  plugin_ref_generic_fallback_attempted = false,
  plugin_ref_generic_fallback_name = nil,
  pending_resolves         = {},   -- queue of resolve:Type tokens deferred when a popup blocks the loop
  pending_plugin_ref_names = {},   -- plugin_ref names accumulated before a popup bailed the parse loop
  pending_pref_plugin_types= {},   -- preferred_plugins types accumulated before a popup bailed the parse loop
  turn_retries         = {},      -- per-turn retry/call counters and one-shot guards; see S._turn_retry_keys
  fx_list_already_sent   = false,
  fx_chains_already_sent = false,
  track_flags_already_sent = false,
  fx_chains_live_retry_active = false,
  track_flags_live_retry_active = false,
  fx_chains_live_retry_header = nil,
  midi_already_sent      = false,
  pref_plugins_sent        = {},   -- set of pref-plugin types sent this turn (per-type dedup)
  pref_plugins_unresolved  = {},   -- requested pref types that returned no saved preference
  theme_already_sent     = false,
  fx_inspect_sent         = {},     -- normalized names successfully pinned this turn
  prompt_bundle_sent       = {},   -- set of prompt-bundle names sent in this session (per-name, NOT reset per turn -- bundles are system-prompt content and stay pinned until Clear)
  prompt_bundle_cache      = nil,  -- {[name]=formatted payload} parsed from Resources/Prompts.md; lazy-init
  prompt_bundle_variant_cache = nil, -- internal plugin full/add_only renderings; lazy-init
  plugin_bundle_variant    = nil,  -- currently pinned plugin payload: "add_only" or "full"
  prompts_loaded           = nil,  -- bool: true after the prompts file has been read (success or fail)
  _prompt_bundle_err       = nil,  -- {[name]=err_string} per-bundle error map; lazy-init
  _prompt_bundle_variant_err = nil, -- plugin compact-render validation error; lazy-init
  pending_display_idx    = nil,    -- index into display_messages for current user msg
  pending_project        = nil,    -- captured project pointer at send time
  pending_local_escalation = nil,  -- exact local-answer request binding while active
  local_escalation_seq   = 0,      -- monotonic request token for local-answer escalation
  turn_budget_confirmation = nil,  -- deferred next model call awaiting explicit consent
  open_turn_budget_confirmation = false, -- one-shot visual-modal open request
  turn_budget_confirm_focus_cancel = false, -- safe initial keyboard focus
  -- Resolve-type popup (Phase 5b): blocks the round when the user has no
  -- preference set for a requested plugin type. resolve_popup carries
  -- { type = "eq"|"compressor"|... } while the modal is open; nil otherwise.
  -- open_resolve_popup is a one-shot flag consumed inside the render frame
  -- to call ImGui.OpenPopup (must be invoked from the render pass).
  resolve_popup          = nil,
  open_resolve_popup     = false,
  resolve_pending_resume = nil,
  resolve_pending_type   = nil,    -- popup type stashed by typed-pick (since popup state is cleared early so the "Waiting for selection" UI clears during the scan)
  resolve_pending_saved_choice = false,
  resolve_resume_guard_type = nil,
  approved_stock_fallback_refs = nil,
  turn_only_stock_sticky_keys = {},
  turn_only_stock_approved_refs = nil,
  resolve_popup_text     = "",    -- text-field buffer for custom plugin name
  resolve_popup_error    = nil,   -- inline error message (install-failed, no-match)
  -- Autocomplete (Phase 5d): list of top matches for the current buffer.
  -- _matches: array of canonical FX names (strings). _sel: 1-based index
  -- into _matches of the currently-highlighted row, or 0 for "none" (in
  -- which case Enter falls back to submitting the raw buffer text).
  -- _last_filter: the buffer value used to build _matches (cache key, so
  -- we only re-run the match scan when the text actually changed).
  resolve_popup_matches     = {},
  resolve_popup_sel         = 0,
  resolve_popup_last_filter = nil,
  -- Attachment queue
  attachments       = {},
  attach_error      = nil,
  attach_error_time = 0,
}

