function S.reset_turn_retries()
  local previous = rawget(S, "turn_retries")
  local restore = type(previous) == "table"
    and previous.typed_action_escalation_restore or nil
  local guard = type(previous) == "table"
    and previous.temporary_provider_selection_guard or nil
  local next_values = {}
  -- A failed hidden restore must keep its saved-selection guard reachable.
  -- Preserve the pair together, and discard either orphan independently.
  if type(restore) == "table" and type(guard) == "table" then
    next_values.typed_action_escalation_restore = restore
    next_values.temporary_provider_selection_guard = guard
  end
  rawset(S, "turn_retries", next_values)
end

setmetatable(S, {
  __index = function(t, k)
    local keys = rawget(t, "_turn_retry_keys")
    if keys and keys[k] then
      local values = rawget(t, "turn_retries")
      if type(values) == "table" and values[k] ~= nil then return values[k] end
      local defaults = rawget(t, "_turn_retry_defaults") or {}
      return defaults[k]
    end
  end,
  __newindex = function(t, k, v)
    local keys = rawget(t, "_turn_retry_keys")
    if keys and keys[k] then
      local values = rawget(t, "turn_retries")
      if type(values) ~= "table" then
        values = {}
        rawset(t, "turn_retries", values)
      end
      values[k] = v
    else
      rawset(t, k, v)
    end
  end,
})

do
  local clean_boot = reaper.GetExtState(CFG.EXT_NS, "factory_reset_clean_boot")
  if clean_boot == "1" then
    S._factory_reset_clean_boot = true
    S._suppress_geometry_save = true
    S._suppress_os_theme_cache = true
    reaper.DeleteExtState(CFG.EXT_NS, "factory_reset_clean_boot", false)
    reaper.DeleteExtState(CFG.EXT_NS, "factory_reset_clean_boot", true)
  end
end

if S.screen_reader_startup_intent and not S.screen_reader_mode then
  if RA.screen_reader_action_cmd and RA.screen_reader_action_cmd ~= 0 then
    -- Non-persistent breadcrumb: the Screen Reader action runs in its own Lua
    -- state, so this is the only way it can tell a preference-driven redirect
    -- apart from a direct action run. The consumer deletes it.
    reaper.SetExtState(CFG.EXT_NS, "sr_entry_via", "startup_flag", false)
    reaper.defer(function()
      reaper.Main_OnCommand(RA.screen_reader_action_cmd, 0)
    end)
    return
  end
  S.screen_reader_startup_intent = false
  S.screen_reader_missing_action_fallback = true
  local msg = RA.early_t(
    "Screen Reader Mode is preferred, but the Screen Reader action could not be found.\n\n" ..
    "Starting the standard ReaAssist window instead. To restore automatic Screen Reader startup, repair or reinstall ReaAssist.",
    "Se prefiere el modo lector de pantalla, pero no se pudo encontrar la acción del lector de pantalla.\n\n" ..
    "Se abrirá la ventana estándar de ReaAssist. Para restaurar el inicio automático del lector de pantalla, repara o reinstala ReaAssist.")
  if reaper.osara_outputMessage then
    pcall(reaper.osara_outputMessage, msg)
  else
    reaper.ShowMessageBox(msg, RA.early_t(
      "ReaAssist - Screen Reader Mode",
      "ReaAssist - Modo de lector de pantalla"), 0)
  end
end

S.INSTANCE_ID = string.format("%.6f_%d", time_precise(), math.random(100000, 999999))

function RA.instance_file_suffix()
  local raw = tostring((S and S.INSTANCE_ID) or (CMD_ID or "session"))
  raw = raw:gsub("[^%w%-_]", "_")
  if raw == "" then raw = "session" end
  return "inst_" .. raw
end

function RA.temp_live_marker_path(instance_suffix)
  local suffix = tostring(instance_suffix or RA.instance_file_suffix())
  suffix = suffix:gsub("[^%w%-_]", "_")
  if suffix == "" then suffix = "inst_session" end
  return RA.TEMP_DIR .. "reaassist_live_" .. suffix .. ".txt"
end

function RA.write_temp_live_marker(now)
  local path = RA.temp_live_marker_path()
  local ok_f, f = pcall(io.open, path, "w")
  if not ok_f or not f then return false end
  local stamp = tostring(now or time_precise())
  local ok_w = pcall(function() f:write(stamp) end)
  local ok_c = pcall(function() f:close() end)
  return ok_w and ok_c
end

function RA.temp_instance_suffix_from_name(filename)
  local s = tostring(filename or "")
  return s:match("[_%.](inst_[%w%-_]+)%.[^%.]+$")
    or s:match("^reaassist_live_(inst_[%w%-_]+)%.txt$")
    or s:match("[_%.](inst_[%w%-_]+)$")
end

function RA.is_windows_reserved_name(name)
  local n = tostring(name or ""):upper()
  return n == "CON" or n == "PRN" or n == "AUX" or n == "NUL"
    or n:match("^COM[1-9]$") ~= nil
    or n:match("^LPT[1-9]$") ~= nil
end

function RA.temp_instance_is_live(instance_suffix, now)
  if not instance_suffix or instance_suffix == "" then return false end
  local path = RA.temp_live_marker_path(instance_suffix)
  local ok_f, f = pcall(io.open, path, "r")
  if not ok_f or not f then return false end
  local raw = f:read("*a")
  f:close()
  local stamp = tonumber(raw)
  if not stamp then return false end
  -- reaper.time_precise() is process-local but boot-anchored on supported
  -- REAPER platforms, so two ReaAssist processes can compare live-marker
  -- ages. If that ever changes upstream, cross-process sweeps must move to
  -- wall-clock timestamps.
  local age = math.abs((now or time_precise()) - stamp)
  return age <= 15
end

-- IS THAT PROCESS STILL THERE, ASKED OF THE OPERATING SYSTEM (Codex round 42,
-- B2.3s).
-- =============================================================================
-- The live marker above answers "was that instance scheduled in the last
-- fifteen seconds". It is a good proof of LIFE and it is not a proof of DEATH,
-- because a machine that suspends stops refreshing markers without stopping
-- being alive. Every round from 41 back to 8 rested the lock's staleness rule
-- on that one signal, so a sleeping process could have its lock taken and wake
-- up mutating beside the instance that took it. Round 42 ruled that the class
-- cannot be closed by checking harder at each mutation, because a check and the
-- act it authorizes are two instructions and a suspension fits between any two.
--
-- So the rule changes rather than the checking: A LIVING PROCESS IS NEVER
-- DEPOSED. Reclaim needs a death certificate, and this is where one is issued.
-- Three answers, and only one of them permits a reclaim:
--
--   "alive"    the recorded instance is provably still there.
--   "dead"     the recorded instance is provably gone. The dead write nothing,
--              so taking their lock cannot produce two writers.
--   "unknown"  neither could be proven. Nothing is reclaimed and the caller
--              surfaces the stop, which is this codebase's ratified answer for
--              an undecidable state (the quarantine gate, rounds 18 to 24).
--
-- THE CERTIFICATE IS A FILE HANDLE, NOT A TIMESTAMP, and that is the whole
-- reason this can answer a question the marker cannot. Every instance opens a
-- life file at startup and HOLDS it open for as long as the process runs
-- (RA.life_open). Holding is a fact about the kernel rather than about our
-- memory or our clock: a suspended process still holds its handles, and a
-- process that dies for any reason at all has them closed by the operating
-- system. Nothing in this app has to notice the death for the evidence to
-- change.
--
-- MEASURED ON THIS PROJECT'S OWN INSTALL (B2.3s), from inside REAPER's Lua,
-- against a life file a genuinely separate process was holding open:
--
--   absent            io.open -> nil,      os.rename(p, p) -> false, errno 2
--   present, held     io.open -> handle,   os.rename(p, p) -> false
--   present, free     io.open -> handle,   os.rename(p, p) -> true (a no-op)
--
-- The ERRNO of the refusal is NOT the discriminator and must not be used as
-- one. REAPER's own C runtime reports errno 2 for a file another process holds,
-- which is the same number it reports for a file that is not there; the
-- project's bundled Lua reports 13 for the same file. What is stable on both,
-- and is what this reads, is the PAIR: whether the file could be opened, and
-- whether it could be renamed onto itself. A rename that SUCCEEDS is the only
-- thing that certifies death, and a rename cannot succeed against a handle the
-- kernel is holding for a living process. Every other combination is
-- deliberately not a death.
--
-- THE PROBE IS NON-DESTRUCTIVE. It is the same rename-onto-itself that
-- RA.path_present has used since B2.2d: on success the file keeps its name, its
-- bytes and its handles, so asking this question never changes the answer.
--
-- WINDOWS AND POSIX PART HERE, honestly. Windows share modes are what make the
-- handle observable; POSIX unlink and rename do not consult open descriptors,
-- so the same probe would call every living POSIX owner dead, which is the
-- exact defect this round exists to remove. POSIX therefore records a real
-- process identity in the life file instead (pid plus the process start time,
-- so a recycled pid cannot inherit a dead instance's authority) and proves
-- death by asking the process table. That lane cannot be run against a POSIX
-- kernel on the machine this was written on, so it is proven at its seam
-- (RA.process_exec) rather than end to end, exactly as journal_link_no_clobber
-- is; where it cannot answer it answers "unknown", which reclaims nothing.
function RA.temp_life_path(instance_suffix)
  local suffix = tostring(instance_suffix or RA.instance_file_suffix())
  suffix = suffix:gsub("[^%w%-_]", "_")
  if suffix == "" then suffix = "inst_session" end
  return RA.TEMP_DIR .. "reaassist_life_" .. suffix .. ".lock"
end

-- The one place this lane shells out, named so a test can stand in front of it.
-- ExecProcess answers "exitcode\nstdout", or nothing at all when the process
-- could not be started, and nothing at all is "cannot tell" here like any other
-- unanswered question.
function RA.process_exec(cmd)
  if not (reaper and type(reaper.ExecProcess) == "function") then return nil end
  local ok, result = pcall(reaper.ExecProcess, cmd, 5000)
  if not ok then return nil end
  return result
end

-- What this process IS, on a host where a held handle proves nothing. One
-- shell, once per process: POSIX system() forks /bin/sh as a direct child of
-- REAPER, so $PPID inside it is this REAPER process. The start time rides along
-- because a pid on its own can be recycled, and an instance that died must not
-- be able to borrow the liveness of whatever process inherited its number.
function RA.posix_process_descriptor()
  if RA.IS_WINDOWS then return nil end
  local out = RA.TEMP_DIR .. "reaassist_proc_" .. RA.instance_file_suffix()
    .. ".txt"
  os.remove(out)
  pcall(os.execute, "p=$PPID; { echo \"pid $p\"; "
    .. "echo \"start $(ps -o lstart= -p $p 2>/dev/null)\"; } > "
    .. Shell.sh_quote(out) .. " 2>/dev/null")
  local f = io.open(out, "rb")
  if not f then return nil end
  local raw = f:read("*a"); f:close()
  os.remove(out)
  if type(raw) ~= "string" or not raw:match("pid%s+%d+") then return nil end
  return (raw:gsub("%s+$", ""))
end

-- Open this process's life file and KEEP IT OPEN. The handle is the evidence,
-- so it is deliberately never closed: the operating system closes it when this
-- process ends, which is precisely the event a stranger needs to observe. Held
-- in RA so nothing collects it.
function RA.life_open()
  if RA._life_handle then return true end
  local path = RA.temp_life_path()
  local descriptor = "reaassist life " .. RA.instance_file_suffix()
  local posix = RA.posix_process_descriptor()
  if posix then descriptor = descriptor .. "\n" .. posix end
  local ok_f, f = pcall(io.open, path, "wb")
  if not ok_f or not f then return false end
  local ok_w = pcall(function()
    assert(f:write(descriptor .. "\n"))
    assert(f:flush())
  end)
  if not ok_w then
    pcall(function() f:close() end)
    return false
  end
  RA._life_handle = f
  return true
end

-- The POSIX half: is the recorded pid still the process that recorded it?
-- `ps` is asked rather than `kill -0`, because kill refuses a process owned by
-- another user and a refusal is not a death.
function RA.posix_process_liveness(raw)
  local pid = tostring(raw):match("pid%s+(%d+)")
  local recorded = tostring(raw):match("start%s+([^\n]*)")
  if not pid then return "unknown" end
  local answer = RA.process_exec("/bin/sh -c "
    .. Shell.sh_quote("ps -o lstart= -p " .. pid .. " 2>/dev/null"))
  if type(answer) ~= "string" then return "unknown" end
  local code = tonumber(answer:match("^%s*(%-?%d+)"))
  local body = answer:gsub("^%s*%-?%d+[^\n]*\n?", ""):gsub("^%s+", "")
    :gsub("%s+$", "")
  if code == 0 and body ~= "" then
    if recorded == nil then return "unknown" end
    recorded = recorded:gsub("^%s+", ""):gsub("%s+$", "")
    if recorded == "" then return "unknown" end
    if body == recorded then return "alive" end
    -- Same number, different process: the instance that recorded it is gone.
    return "dead"
  end
  -- `ps` says no such process (exit 1, nothing printed). Anything else, a
  -- shell that could not run it included, is not an answer.
  if code == 1 and body == "" then return "dead" end
  return "unknown"
end

-- Is the process behind that instance suffix still running? Never called for
-- our own suffix in anger; the short-circuit is there so a caller cannot ask
-- the disk a question it already knows the answer to.
function RA.process_liveness(instance_suffix)
  local suffix = tostring(instance_suffix or "")
  if suffix == "" then return "unknown" end
  if suffix == RA.instance_file_suffix() then return "alive" end
  local path = RA.temp_life_path(suffix)
  local f = io.open(path, "rb")
  if not f then return "unknown" end
  local raw = f:read("*a") or ""
  f:close()
  -- It has to be THAT instance's life file. A stray file at the name proves
  -- nothing about anybody, and a reclaim is too expensive to spend on one.
  if not tostring(raw):find("reaassist life " .. suffix, 1, true) then
    return "unknown"
  end
  if RA.IS_WINDOWS then
    if os.rename(path, path) then return "dead" end
    return "alive"
  end
  return RA.posix_process_liveness(raw)
end

-- The whole question, in the order that costs least. A fresh marker is a
-- process that was scheduled a moment ago, which is proof of life and needs no
-- probe at all; only a stale marker is worth asking the operating system about.
function RA.instance_liveness(instance_suffix, now)
  local suffix = tostring(instance_suffix or "")
  if suffix == "" then return "unknown" end
  if suffix == RA.instance_file_suffix() then return "alive" end
  if RA.temp_instance_is_live(suffix, now) then return "alive" end
  return RA.process_liveness(suffix)
end

do
  -- Stale lock timeout: how long before a lock from a (presumed-crashed)
  -- prior instance is considered abandoned. Set short so the user can
  -- relaunch the script almost immediately after a REAPER crash. The live
  -- instance refreshes its lock every loop frame, so 15s is plenty of margin
  -- against false positives even on a heavily loaded machine.
  local STALE_LOCK_SECS = 15
  local existing_lock = reaper.GetExtState(CFG.EXT_NS, "running")
  if existing_lock ~= "" then
    -- Lock format: "instance_id|timestamp"
    local lock_time = tonumber(existing_lock:match("|(.+)$"))
    local now = time_precise()
    local age = lock_time and math.abs(now - lock_time) or math.huge
    if age < STALE_LOCK_SECS then
      -- Lock is fresh: another instance is genuinely running. Signal it to close
      -- and pass our instance ID so the running instance can verify the request.
      reaper.SetExtState(CFG.EXT_NS, "request_close", S.INSTANCE_ID, false)
      set_toolbar(false)
      return
    end
    -- Lock is stale or non-numeric: claim it for this instance (fall through).
  end
  reaper.SetExtState(CFG.EXT_NS, "running",
    S.INSTANCE_ID .. "|" .. tostring(time_precise()), false)
  reaper.DeleteExtState(CFG.EXT_NS, "request_close", false)
  set_toolbar(true)
end

-- =============================================================================
-- API key obfuscation
-- =============================================================================
-- Keys are XOR-encoded against the REAPER install path before storage in
-- ExtState. This prevents accidental key leakage when users share portable
-- installs or sync config files to another machine -- the encoded value
-- decodes to garbage on any machine with a different GetExePath().
--
-- This is NOT encryption. The deobfuscation logic is visible in this source
-- file. It protects against *accidental* exposure, not intentional theft.

-- Machine-specific anchor: REAPER's executable directory. Stable across
-- sessions on the same machine, different on every other machine.
Key = {}
Key.ANCHOR = reaper.GetExePath()

-- XOR helper: pure-arithmetic implementation that works in any Lua version
-- without requiring bit/bit32 libraries (which REAPER may not expose).
-- Operates on byte values (0-255) so only needs to XOR 8 bits.
function Key.byte_xor(a, b)
  local result = 0
  local bit_val = 1
  for _ = 1, 8 do
    local a_bit = a % 2
    local b_bit = b % 2
    if a_bit ~= b_bit then result = result + bit_val end
    a = math_floor(a / 2)
    b = math_floor(b / 2)
    bit_val = bit_val * 2
  end
  return result
end

-- Key.xor_with_anchor(str) -> string
-- XORs each byte of str against the corresponding byte in the anchor,
-- cycling the anchor if str is longer. Returns a raw byte string.
function Key.xor_with_anchor(str)
  local anchor = Key.ANCHOR
  local anchor_len = #anchor
  local out = {}
  for i = 1, #str do
    local s_byte = str:byte(i)
    local a_byte = anchor:byte(((i - 1) % anchor_len) + 1)
    out[i] = str_char(Key.byte_xor(s_byte, a_byte))
  end
  return tbl_concat(out)
end

-- Magic prefix prepended to the plaintext before XOR encoding. On decode, its
-- presence confirms the install path has not changed. Without it, a moved
-- install would produce garbage on decode and we'd have no way to distinguish
-- "corrupted" from "wrong anchor" -- previously this caused the key to be
-- permanently erased on a temporary install-path change.
local KEY_MAGIC = "RA1\0"

-- Key.encode(plain_key) -> hex string suitable for ExtState storage
-- Encodes a plain-text API key into a hex-encoded, machine-locked blob.
-- Prepends KEY_MAGIC so decode can verify the anchor matched.
function Key.encode(plain_key)
  local xored = Key.xor_with_anchor(KEY_MAGIC .. plain_key)
  local hex = {}
  for i = 1, #xored do
    hex[i] = str_format("%02x", xored:byte(i))
  end
  return tbl_concat(hex)
end

-- Key.decode(hex_string) -> plain_key or nil
-- Reverses Key.encode. Returns nil if the hex string is malformed or the
-- magic prefix is absent (install path changed). Does NOT erase the stored
-- key on failure -- the caller decides what to do.
function Key.decode(hex_str)
  -- Validate hex format (even length, only hex chars).
  if #hex_str % 2 ~= 0 or hex_str:match("[^0-9a-fA-F]") then
    return nil
  end
  local bytes = {}
  for i = 1, #hex_str, 2 do
    bytes[#bytes + 1] = str_char(tonumber(hex_str:sub(i, i + 1), 16))
  end
  local decoded = Key.xor_with_anchor(tbl_concat(bytes))
  -- Verify magic prefix. If absent, the anchor (install path) has changed
  -- and the decode produced garbage. Return nil but leave the stored blob
  -- intact so restoring the original path recovers the key.
  if decoded:sub(1, #KEY_MAGIC) ~= KEY_MAGIC then
    return nil
  end
  return decoded:sub(#KEY_MAGIC + 1)
end

-- Key.save(plain_key, extstate_key) -- encodes and persists to ExtState.
-- extstate_key defaults to the active provider's key_extstate.
function Key.save(plain_key, extstate_key)
  extstate_key = extstate_key or PROVIDERS.active().key_extstate
  reaper.SetExtState(CFG.EXT_NS, extstate_key, Key.encode(plain_key), true)
end

-- Key.clear(extstate_key) -- removes key from ExtState.
-- extstate_key defaults to the active provider's key_extstate.
function Key.clear(extstate_key)
  extstate_key = extstate_key or PROVIDERS.active().key_extstate
  reaper.DeleteExtState(CFG.EXT_NS, extstate_key, true)
end

function Key._literal_pattern(s)
  return tostring(s or ""):gsub("([^%w])", "%%%1")
end

function Key.prefixes_for(provider)
  if not provider then return nil end
  if provider.key_prefixes then return provider.key_prefixes end
  if provider.key_prefix and provider.key_prefix ~= "" then
    return { provider.key_prefix }
  end
  return nil
end

function Key.prefix_label(provider)
  if provider and provider.key_prefix_label then
    return provider.key_prefix_label
  end
  local prefixes = Key.prefixes_for(provider)
  if not prefixes or #prefixes == 0 then return "" end
  if #prefixes == 1 then return prefixes[1] end
  return tbl_concat(prefixes, " or ")
end

function Key.matches_known_prefix(key, provider)
  local prefixes = Key.prefixes_for(provider)
  if not prefixes or #prefixes == 0 then return true end
  for _, prefix in ipairs(prefixes) do
    if key:match("^" .. Key._literal_pattern(prefix)) then
      return true
    end
  end
  return false
end

function Key.matches_excluded_prefix(key, provider)
  if not provider or not provider.key_exclude then return false end
  if type(provider.key_exclude) == "string" then
    return key:match("^" .. Key._literal_pattern(provider.key_exclude)) ~= nil
  end
  for _, prefix in ipairs(provider.key_exclude) do
    if key:match("^" .. Key._literal_pattern(prefix)) then
      return true
    end
  end
  return false
end

-- =============================================================================
-- First-run full-screen flow
-- =============================================================================
-- On first launch, the main UI is hidden and the user is walked through two
-- full-window screens before reaching the chat: a Terms of Use / disclaimer
-- screen, then an API key entry screen. Once both are complete the main UI
-- replaces them for the rest of this session and all future sessions.
--
-- api_keys.screen is the single source of truth for which screen is active:
--   "tos"       -- Terms of Use / disclaimer screen (shown first if not yet
--                  accepted at the current TOS version)
--   "api_key"   -- API key entry screen (shown when TOS is accepted but no
--                  valid API key is stored)
--   nil         -- main chat UI (TOS accepted AND key present)
--
-- TOS acceptance is persisted in Config.json as a version string. Bumping
-- api_keys.tos_version below will force every user to re-accept on next
-- launch (use this only when the disclaimer text changes substantively).
--
-- All state for the API keys / first-run setup flow. This single table holds
-- the screen-routing flag, the TOS acceptance state, the API key entry
-- buffers/validation, and the custom LLM section state. Kept in one table
-- to stay under Lua's per-function 200-local limit.
api_keys = {
  -- Current screen: "tos" / "first_run" / "settings" / subpage / nil.
  screen         = nil,
  -- Per-screen state for the API key entry screen.
  key_bufs       = {},     -- per-provider input buffers: {[1]="", [2]="", [3]=""}
  key_errors     = {},     -- per-provider validation errors: {[1]=nil, [2]=nil, [3]=nil}
  key_warnings   = {},     -- per-provider advisory messages that do not block testing
  key_error      = nil,    -- general inline error string, or nil
  key_validating = false,  -- true while a test API call is in flight
  key_validating_idx = nil, -- which provider index is being validated (nil = none)
  key_focused    = false,  -- true after the input field has been auto-focused once
  is_reentry     = false,  -- true when opened via Settings button (not first launch)
  -- Multi-key test state (Test API Keys button).
  test_queue       = {},     -- list of {idx, prov} to test sequentially
  test_results     = {},     -- collected results: {[prov_id]={ok=bool, label=str, error=str}}
  show_test_results = false, -- true = open the results popup next frame
  -- Single-key validation error popup state.
  show_key_error_popup = false,   -- true = open error popup next frame
  key_error_provider   = nil,     -- provider label for the error popup
  key_error_detail     = nil,     -- human-readable error message
  key_error_hint       = nil,     -- how-to-fix hint
  key_error_url        = nil,     -- console URL for the provider (clickable link)
  key_error_url_label  = nil,     -- display text for the URL
  key_test_recovery    = nil,     -- response-specific recovery shared with Screen Reader Mode
  -- TOS persistence.
  tos_version    = "8",
  -- Disclaimer text shown on the first-run TOS screen. When this text
  -- changes substantively, bump tos_version above to force re-acceptance.
  tos_text = string.format([[
YOUR PRIVACY
API keys are stored locally using reversible XOR obfuscation tied to your REAPER install path. This is not encryption and not an OS credential vault; a person or process with access to your REAPER settings and the ReaAssist source can recover the keys. They are never sent to the author. Chat data is sent only to your chosen provider to fulfill your request. To provide relevant help, ReaAssist may send session data included in your prompt, such as track names, routing, and project settings. ReaAssist does not access, transmit, or create audio files. You may use a local LLM to keep all data offline and on your machine. Basic anonymous diagnostics are enabled by default and used to help improve the service. They can be turned off in Settings. The previewable manual feedback/report flows still show the exact bytes before sending.

SECURITY & SAFEGUARDS
ReaAssist scans generated code for potentially high-risk operations, such as file system changes or shell commands, and requires your confirmation before flagged code can run. Project backups can be created before execution, and REAPER Undo history is preserved. No project changes are made without your approval.

TERMS & LIABILITY
ReaAssist is provided "as is," without warranties of any kind, express or implied, including merchantability or fitness for a particular purpose. Generated code may contain errors or unintended results. You are responsible for reviewing code before execution. You are also responsible for your provider's terms, privacy practices, availability, and API charges. Some requests may be retried or escalated to a stronger model from the same provider when needed, which can increase API charges. Displayed cost estimates are approximate only.

Copyright %s Michael Briggs. All rights reserved. ReaAssist is proprietary software; redistribution, resale, repackaging, and presenting this software as your own (modified or unmodified) are prohibited without prior written permission.

By clicking "I Agree," you confirm that you have read and agree to these Terms of Use.]], os.date("%Y")),
}

function api_keys.tos_is_accepted()
  if Store and Store.tos_is_accepted then
    return Store.tos_is_accepted(api_keys.tos_version)
  end
  return reaper.GetExtState(CFG.EXT_NS, "tos_accepted_version")
    == api_keys.tos_version
end
function api_keys.mark_tos_accepted()
  if S then
    S._factory_reset_clean_boot = false
    S._suppress_geometry_save = false
    S._suppress_os_theme_cache = false
  end
  if Store and Store.mark_tos_accepted then
    Store.mark_tos_accepted(api_keys.tos_version)
    return
  end
end

