-- One-time OpenAI model migration for the GPT-5.6 rollout. Full GPT-5.4 moves
-- to Terra. Retired nano and Mini selections move to Luna, whose current price
-- and tested performance make it the default. GPT-5.6 rows load their None
-- defaults, so thinking choices tuned for the retired rows are discarded.
do
  if not (S and S._factory_reset_clean_boot)
     and not Store.migration_fired("openai_gpt_56_model_v1") then
    local doc = Store.config_doc()
    doc.selection = type(doc.selection) == "table" and doc.selection or {}
    doc.selection.model_id_by_provider =
      type(doc.selection.model_id_by_provider) == "table"
      and doc.selection.model_id_by_provider or {}
    doc.selection.thinking_idx_by_provider_model =
      type(doc.selection.thinking_idx_by_provider_model) == "table"
      and doc.selection.thinking_idx_by_provider_model or {}

    local old_model = doc.selection.model_id_by_provider.openai
    if old_model == "gpt-5.4" then
      doc.selection.model_id_by_provider.openai = "gpt-5.6-terra"
    elseif old_model == "gpt-5.4-nano"
        or old_model == "gpt-5.4-mini" then
      doc.selection.model_id_by_provider.openai = "gpt-5.6-luna"
    end

    doc.selection.thinking_idx_by_provider_model["openai/gpt-5.4"] = nil
    doc.selection.thinking_idx_by_provider_model["openai/gpt-5.4-nano"] = nil
    doc.selection.thinking_idx_by_provider_model["openai/gpt-5.4-mini"] = nil
    reaper.DeleteExtState(CFG.EXT_NS,
      "thinking_idx_openai_gpt-5.4", true)
    reaper.DeleteExtState(CFG.EXT_NS,
      "thinking_idx_openai_gpt-5.4-nano", true)
    reaper.DeleteExtState(CFG.EXT_NS,
      "thinking_idx_openai_gpt-5.4-mini", true)

    -- Legacy installs may still persist only the old 1-based picker index.
    -- Old nano (1) and Mini (2) both land on Luna (1); old full (3) lands on
    -- Terra (2). A saved model id takes priority and also handles a GPT-5.6
    -- selection whose original rollout sentinel was never recorded.
    local old_idx = tonumber(
      reaper.GetExtState(CFG.EXT_NS, "model_idx_openai"))
    local selected_model = doc.selection.model_id_by_provider.openai
    if selected_model == "gpt-5.6-luna" then
      reaper.SetExtState(CFG.EXT_NS, "model_idx_openai", "1", true)
    elseif selected_model == "gpt-5.6-terra" then
      reaper.SetExtState(CFG.EXT_NS, "model_idx_openai", "2", true)
    elseif selected_model == "gpt-5.6-sol" then
      reaper.SetExtState(CFG.EXT_NS, "model_idx_openai", "3", true)
    elseif old_idx == 1 or old_idx == 2 then
      reaper.SetExtState(CFG.EXT_NS, "model_idx_openai", "1", true)
    elseif old_idx == 3 then
      reaper.SetExtState(CFG.EXT_NS, "model_idx_openai", "2", true)
    end

    doc.migrations = type(doc.migrations) == "table" and doc.migrations or {}
    doc.migrations.openai_gpt_56_model_v1 = true
    -- Fresh upgrades already use the three-row catalog mapping above. Mark the
    -- follow-up migration complete so its four-row index conversion is skipped.
    doc.migrations.openai_gpt_56_luna_default_v2 = true
    local err = Store.write_json_atomic(RA.CONFIG_PATH, doc, true)
    if err then
      Store._notify_write_failure("Config.json", err)
    end
  end
end

-- One-time OpenAI follow-up migration for installations that already ran the
-- original four-row GPT-5.6 rollout. Mini moves to Luna None. Existing Luna,
-- Terra, and Sol selections keep their model while their stored picker indexes
-- shift to the new three-row catalog.
do
  if not (S and S._factory_reset_clean_boot)
     and not Store.migration_fired("openai_gpt_56_luna_default_v2") then
    local doc = Store.config_doc()
    doc.selection = type(doc.selection) == "table" and doc.selection or {}
    doc.selection.model_id_by_provider =
      type(doc.selection.model_id_by_provider) == "table"
      and doc.selection.model_id_by_provider or {}
    doc.selection.thinking_idx_by_provider_model =
      type(doc.selection.thinking_idx_by_provider_model) == "table"
      and doc.selection.thinking_idx_by_provider_model or {}

    local selected_model = doc.selection.model_id_by_provider.openai
    if selected_model == "gpt-5.4-mini" then
      selected_model = "gpt-5.6-luna"
      doc.selection.model_id_by_provider.openai = selected_model
    end
    doc.selection.thinking_idx_by_provider_model["openai/gpt-5.4-mini"] = nil
    reaper.DeleteExtState(CFG.EXT_NS,
      "thinking_idx_openai_gpt-5.4-mini", true)

    local old_idx = tonumber(
      reaper.GetExtState(CFG.EXT_NS, "model_idx_openai"))
    if selected_model == "gpt-5.6-luna" then
      reaper.SetExtState(CFG.EXT_NS, "model_idx_openai", "1", true)
    elseif selected_model == "gpt-5.6-terra" then
      reaper.SetExtState(CFG.EXT_NS, "model_idx_openai", "2", true)
    elseif selected_model == "gpt-5.6-sol" then
      reaper.SetExtState(CFG.EXT_NS, "model_idx_openai", "3", true)
    elseif old_idx == 1 or old_idx == 2 then
      reaper.SetExtState(CFG.EXT_NS, "model_idx_openai", "1", true)
    elseif old_idx == 3 then
      reaper.SetExtState(CFG.EXT_NS, "model_idx_openai", "2", true)
    elseif old_idx == 4 then
      reaper.SetExtState(CFG.EXT_NS, "model_idx_openai", "3", true)
    end

    doc.migrations = type(doc.migrations) == "table" and doc.migrations or {}
    doc.migrations.openai_gpt_56_luna_default_v2 = true
    local err = Store.write_json_atomic(RA.CONFIG_PATH, doc, true)
    if err then
      Store._notify_write_failure("Config.json", err)
    end
  end
end

-- One-time Gemini 3.6 Flash migration. Move saved Flash 3.5 and older Flash
-- Preview selections to the current Flash row. Clear only the retired models'
-- thinking keys so other Gemini selections and thinking choices remain
-- unchanged. Mark the two older Gemini migrations at the same time so direct
-- upgrades need one config write.
-- Write the targeted selection patch directly instead of calling
-- Store.save_config() here; provider/model prefs are not fully populated until
-- MODELS.refresh below, and save_config would rebuild selection too early.
do
  if not (S and S._factory_reset_clean_boot)
     and not Store.migration_fired("google_flash_36_model_v1") then
    local doc = Store.config_doc()
    local selection_before = doc.selection
    local migrations_before = doc.migrations
    doc.selection = type(doc.selection) == "table" and doc.selection or {}
    local model_map_before = doc.selection.model_id_by_provider
    local thinking_map_before = doc.selection.thinking_idx_by_provider_model
    doc.selection.model_id_by_provider =
      type(doc.selection.model_id_by_provider) == "table"
      and doc.selection.model_id_by_provider or {}
    doc.selection.thinking_idx_by_provider_model =
      type(doc.selection.thinking_idx_by_provider_model) == "table"
      and doc.selection.thinking_idx_by_provider_model or {}
    local old_model = doc.selection.model_id_by_provider.google
    local old_flash_pref = doc.selection.thinking_idx_by_provider_model[
      "google/gemini-3.5-flash"]
    local old_preview_pref = doc.selection.thinking_idx_by_provider_model[
      "google/gemini-3-flash-preview"]
    if old_model == "gemini-3.5-flash"
       or old_model == "gemini-3-flash-preview" then
      doc.selection.model_id_by_provider.google = "gemini-3.6-flash"
    end
    doc.selection.thinking_idx_by_provider_model[
      "google/gemini-3.5-flash"] = nil
    doc.selection.thinking_idx_by_provider_model[
      "google/gemini-3-flash-preview"] = nil
    doc.migrations = type(doc.migrations) == "table" and doc.migrations or {}
    local marker_35_before = doc.migrations.google_flash_35_model_v1
    local marker_min_before = doc.migrations.google_flash_35_minimal_default_v1
    local marker_36_before = doc.migrations.google_flash_36_model_v1
    doc.migrations.google_flash_35_model_v1 = true
    doc.migrations.google_flash_35_minimal_default_v1 = true
    doc.migrations.google_flash_36_model_v1 = true
    local err = Store.write_json_atomic(RA.CONFIG_PATH, doc, true)
    if err then
      S._google_flash_36_migration_failed = true
      if type(selection_before) ~= "table" then
        doc.selection = selection_before
      else
        doc.selection = selection_before
        doc.selection.model_id_by_provider = model_map_before
        doc.selection.thinking_idx_by_provider_model = thinking_map_before
        if type(model_map_before) == "table" then
          model_map_before.google = old_model
        end
        if type(thinking_map_before) == "table" then
          thinking_map_before["google/gemini-3.5-flash"] = old_flash_pref
          thinking_map_before["google/gemini-3-flash-preview"] =
            old_preview_pref
        end
      end
      if type(migrations_before) ~= "table" then
        doc.migrations = migrations_before
      else
        doc.migrations = migrations_before
        migrations_before.google_flash_35_model_v1 = marker_35_before
        migrations_before.google_flash_35_minimal_default_v1 =
          marker_min_before
        migrations_before.google_flash_36_model_v1 = marker_36_before
      end
      Store._notify_write_failure("Config.json", err)
    else
      reaper.DeleteExtState(CFG.EXT_NS,
        "thinking_idx_google_gemini-3.5-flash", true)
      reaper.DeleteExtState(CFG.EXT_NS,
        "thinking_idx_google_gemini-3-flash-preview", true)
    end
  end
end

-- One-time Gemini catalog-order compatibility. Flash 3.7 is an optional row
-- between Flash 3.6 and Pro 3.1. Preserve a released index-only Pro selection,
-- which used row 3 before the optional model was added. Saved model ids remain
-- authoritative and are mapped to their current row without changing models.
do
  if not (S and S._factory_reset_clean_boot)
     and not (S and S._google_flash_36_migration_failed)
     and Store.migration_fired("google_flash_36_model_v1")
     and not Store.migration_fired("google_flash_37_optional_catalog_v1") then
    local doc = Store.config_doc()
    local selection_before = doc.selection
    local migrations_before = doc.migrations
    doc.selection = type(doc.selection) == "table" and doc.selection or {}
    local model_map_before = doc.selection.model_id_by_provider
    doc.selection.model_id_by_provider =
      type(doc.selection.model_id_by_provider) == "table"
      and doc.selection.model_id_by_provider or {}
    local selected_model = doc.selection.model_id_by_provider.google
    local old_idx = tonumber(reaper.GetExtState(
      CFG.EXT_NS, "model_idx_google"))
    if selected_model == nil and old_idx == 3 then
      selected_model = "gemini-3.1-pro-preview"
      doc.selection.model_id_by_provider.google = selected_model
    end
    doc.migrations = type(doc.migrations) == "table" and doc.migrations or {}
    local marker_before = doc.migrations.google_flash_37_optional_catalog_v1
    doc.migrations.google_flash_37_optional_catalog_v1 = true
    local err = Store.write_json_atomic(RA.CONFIG_PATH, doc, true)
    if err then
      if type(selection_before) ~= "table" then
        doc.selection = selection_before
      else
        doc.selection = selection_before
        doc.selection.model_id_by_provider = model_map_before
      end
      if type(migrations_before) ~= "table" then
        doc.migrations = migrations_before
      else
        doc.migrations = migrations_before
        migrations_before.google_flash_37_optional_catalog_v1 = marker_before
      end
      Store._notify_write_failure("Config.json", err)
    else
      local current_idx = ({
        ["gemini-3.5-flash-lite"] = 1,
        ["gemini-3.6-flash"] = 2,
        ["gemini-3.7-flash"] = 3,
        ["gemini-3.1-pro-preview"] = 4,
      })[selected_model]
      if current_idx then
        reaper.SetExtState(CFG.EXT_NS, "model_idx_google",
          tostring(current_idx), true)
      end
    end
  end
end

-- One-time Gemini model-id migration. Flash 3.8 replaces the optional Flash
-- 3.7 row. Preserve its Low-or-higher thinking preference because both models
-- expose the same supported thinking levels.
do
  if not (S and S._factory_reset_clean_boot)
     and not Store.migration_fired("google_flash_38_model_v1") then
    local doc = Store.config_doc()
    doc.selection = type(doc.selection) == "table" and doc.selection or {}
    doc.selection.model_id_by_provider =
      type(doc.selection.model_id_by_provider) == "table"
      and doc.selection.model_id_by_provider or {}
    doc.selection.thinking_idx_by_provider_model =
      type(doc.selection.thinking_idx_by_provider_model) == "table"
      and doc.selection.thinking_idx_by_provider_model or {}
    local model_map = doc.selection.model_id_by_provider
    local thinking_map = doc.selection.thinking_idx_by_provider_model
    local old_model = model_map.google
    local old_key = "google/gemini-3.7-flash"
    local new_key = "google/gemini-3.8-flash"
    local old_pref = thinking_map[old_key]
    local new_pref = thinking_map[new_key]
    if old_model == "gemini-3.7-flash" then
      model_map.google = "gemini-3.8-flash"
    end
    if thinking_map[new_key] == nil then
      thinking_map[new_key] = thinking_map[old_key]
        or tonumber(reaper.GetExtState(CFG.EXT_NS,
          "thinking_idx_google_gemini-3.7-flash"))
    end
    thinking_map[old_key] = nil
    doc.migrations = type(doc.migrations) == "table" and doc.migrations or {}
    local marker_before = doc.migrations.google_flash_38_model_v1
    doc.migrations.google_flash_38_model_v1 = true
    local err = Store.write_json_atomic(RA.CONFIG_PATH, doc, true)
    if err then
      model_map.google = old_model
      thinking_map[old_key] = old_pref
      thinking_map[new_key] = new_pref
      doc.migrations.google_flash_38_model_v1 = marker_before
      Store._notify_write_failure("Config.json", err)
    else
      if model_map.google == "gemini-3.8-flash" then
        reaper.SetExtState(CFG.EXT_NS, "model_idx_google", "3", true)
      end
      local old_ext = reaper.GetExtState(
        CFG.EXT_NS, "thinking_idx_google_gemini-3.7-flash")
      if old_ext ~= ""
         and reaper.GetExtState(
           CFG.EXT_NS, "thinking_idx_google_gemini-3.8-flash") == "" then
        reaper.SetExtState(
          CFG.EXT_NS, "thinking_idx_google_gemini-3.8-flash", old_ext, true)
      end
      reaper.DeleteExtState(
        CFG.EXT_NS, "thinking_idx_google_gemini-3.7-flash", true)
    end
  end
end

-- One-time Gemini 3.5 Flash-Lite migration. Keep users on the Lite row and
-- carry their explicit thinking preference to the replacement model. The row
-- index is unchanged, so legacy index-only installs already land correctly.
do
  if not (S and S._factory_reset_clean_boot)
     and not Store.migration_fired("google_flash_lite_35_model_v1") then
    local doc = Store.config_doc()
    doc.selection = type(doc.selection) == "table" and doc.selection or {}
    doc.selection.model_id_by_provider =
      type(doc.selection.model_id_by_provider) == "table"
      and doc.selection.model_id_by_provider or {}
    doc.selection.thinking_idx_by_provider_model =
      type(doc.selection.thinking_idx_by_provider_model) == "table"
      and doc.selection.thinking_idx_by_provider_model or {}

    if doc.selection.model_id_by_provider.google
       == "gemini-3.1-flash-lite" then
      doc.selection.model_id_by_provider.google = "gemini-3.5-flash-lite"
    end

    local old_key = "google/gemini-3.1-flash-lite"
    local new_key = "google/gemini-3.5-flash-lite"
    local old_ext = reaper.GetExtState(
      CFG.EXT_NS, "thinking_idx_google_gemini-3.1-flash-lite")
    local new_ext = reaper.GetExtState(
      CFG.EXT_NS, "thinking_idx_google_gemini-3.5-flash-lite")
    local migrated_thinking =
      doc.selection.thinking_idx_by_provider_model[new_key]
      or tonumber(new_ext)
      or doc.selection.thinking_idx_by_provider_model[old_key]
      or tonumber(old_ext)
    if doc.selection.thinking_idx_by_provider_model[new_key] == nil then
      doc.selection.thinking_idx_by_provider_model[new_key] = migrated_thinking
    end
    doc.selection.thinking_idx_by_provider_model[old_key] = nil

    if new_ext == "" and migrated_thinking ~= nil then
      reaper.SetExtState(CFG.EXT_NS,
        "thinking_idx_google_gemini-3.5-flash-lite",
        tostring(migrated_thinking), true)
    end
    reaper.DeleteExtState(CFG.EXT_NS,
      "thinking_idx_google_gemini-3.1-flash-lite", true)

    doc.migrations = type(doc.migrations) == "table" and doc.migrations or {}
    doc.migrations.google_flash_lite_35_model_v1 = true
    local err = Store.write_json_atomic(RA.CONFIG_PATH, doc, true)
    if err then
      Store._notify_write_failure("Config.json", err)
    end
  end
end

