      "google/gemini-3.5-flash"] = nil
    reaper.DeleteExtState(CFG.EXT_NS,
      "thinking_idx_google_gemini-3.5-flash", true)
    doc.migrations = type(doc.migrations) == "table" and doc.migrations or {}
    doc.migrations.google_flash_35_minimal_default_v1 = true
    local err = Store.write_json_atomic(RA.CONFIG_PATH, doc, true)
    if err then
      Store._notify_write_failure("Config.json", err)
    end
  end
end

-- =============================================================================
-- Provider + Model selector
-- =============================================================================
-- prefs.provider_idx selects the active AI service (1-based index into PROVIDERS).
-- prefs.model_idx selects the model within that provider (1-based).
-- Both persist in Config.json. Legacy ExtState model indices are read once
-- during upgrade so switching providers still remembers each provider's
-- last-used model.
--
-- MODELS is a dynamic proxy that always reflects the active provider's model list.
-- All existing code that reads MODELS[prefs.model_idx], MODELS.active_id(), and
-- MODELS.calc_cost() continues to work unchanged.
MODELS = {}

-- Load provider_idx (default 1 = Claude for existing and new users).
-- Helper: load an ExtState integer index into a 1..#list range, falling
-- back to `default` on a missing / corrupt / out-of-range value. Used
-- for the four index-into-list prefs below; standalone clamps remain
-- inline for cloud_request_timeout (MIN/MAX in CFG).
local function _prefs_load_idx(key, default, list)
  local v = tonumber(reaper.GetExtState(CFG.EXT_NS, key)) or default
  if v < 1 or v > #list then v = default end
  return v
end

-- Re-read after startup migrations. The earlier Screen Reader initialization
-- protects an unsupported saved tuple from incidental migration writes. This
-- pass makes the runtime tuple reflect any permitted legacy migration.
if S.screen_reader_mode and ScreenReaderLegacy
    and ScreenReaderLegacy.initialize then
  ScreenReaderLegacy.initialize(Store, PROVIDERS, prefs, S, reaper, CFG)
end

prefs.provider_idx = (S.screen_reader_mode and ScreenReaderLegacy
    and ScreenReaderLegacy.provider_idx
    and ScreenReaderLegacy.provider_idx(PROVIDERS))
  or Store.config_provider_idx(
    _prefs_load_idx("provider_idx", 1, PROVIDERS))

-- Load cloud_request_timeout (default CFG.CLOUD_TIMEOUT_DEFAULT = 180s). Clamp
-- to [CLOUD_TIMEOUT_MIN, CLOUD_TIMEOUT_MAX] so a corrupt ExtState value can't
-- break the watchdog.
prefs.cloud_request_timeout = tonumber(
  reaper.GetExtState(CFG.EXT_NS, "cloud_request_timeout"))
  or CFG.CLOUD_TIMEOUT_DEFAULT
if prefs.cloud_request_timeout < CFG.CLOUD_TIMEOUT_MIN
   or prefs.cloud_request_timeout > CFG.CLOUD_TIMEOUT_MAX then
  prefs.cloud_request_timeout = CFG.CLOUD_TIMEOUT_DEFAULT
end

prefs.turn_cost_limit_usd = tonumber(
  reaper.GetExtState(CFG.EXT_NS, "turn_cost_limit_usd"))
  or CFG.TURN_COST_LIMIT_DEFAULT
if prefs.turn_cost_limit_usd < CFG.TURN_COST_LIMIT_MIN
   or prefs.turn_cost_limit_usd > CFG.TURN_COST_LIMIT_MAX then
  prefs.turn_cost_limit_usd = CFG.TURN_COST_LIMIT_DEFAULT
end

prefs.turn_token_limit = tonumber(
  reaper.GetExtState(CFG.EXT_NS, "turn_token_limit"))
  or CFG.TURN_TOKEN_LIMIT_DEFAULT
if prefs.turn_token_limit < CFG.TURN_TOKEN_LIMIT_MIN
   or prefs.turn_token_limit > CFG.TURN_TOKEN_LIMIT_MAX then
  prefs.turn_token_limit = CFG.TURN_TOKEN_LIMIT_DEFAULT
end

-- Load ui_scale_idx (default 3 = Auto). Manual choices scale the full layout.
prefs.ui_scale_idx = _prefs_load_idx("ui_scale_idx", 3, CFG.UI_SCALE_OPTIONS)
function RA.SC(px)
  return math.floor(px * CFG.UI_SCALE_OPTIONS[prefs.ui_scale_idx] + 0.5)
end

-- =============================================================================
-- V5 FONT ATLAS -- Inter (5 weights) + JetBrains Mono (3 weights), shipped as
-- TTFs in Resources/fonts/. ReaImGui 0.10+ API: CreateFontFromFile takes no
-- size argument (it was dropped); the pixel size is specified per-PushFont and
-- ReaImGui re-rasterizes via FreeType on the fly, so one font handle per
-- weight renders crisply at any size. inter_reg is attached first so
-- the ReaImGui default-font slot resolves to Inter Regular for any
-- PushFont(ctx, nil, size) call.
