-- =============================================================================
-- Utility: Key.mask
-- =============================================================================
-- Returns a masked display of the API key matching each provider's console format:
--   Anthropic: first 15 chars + "..." + last 4     e.g. "sk-ant-api03-75f...iwAA"
--   OpenAI:    literal "sk-..." + last 4           e.g. "sk-...KVwA"
--   Google:    "..." + last 4                      e.g. "..._U0M"
--   Custom / unknown: Anthropic-style long prefix (most informative fallback)
-- For very short keys (unlikely), returns the full key unmasked.
function Key.mask(key, provider_id)
  if not key then return "" end
  if #key <= 8 then return key end
  if provider_id == "google" then
    return "..." .. key:sub(-4)
  elseif provider_id == "openai" then
    return "sk-..." .. key:sub(-4)
  end
  if #key <= 19 then return key end
  return key:sub(1, 15) .. "..." .. key:sub(-4)
end

-- =============================================================================
-- Utility: Key.validate_format
-- =============================================================================
-- Checks whether a string looks like a plausible API key for a given provider
-- before sending it to the network. This catches common mistakes:
--   - pasting a URL instead of a key
--   - partial clipboard pastes
--   - random text or sentences
--   - pasting the wrong provider's key
-- Returns true if the format is plausible, false + reason string otherwise.
-- provider defaults to the active provider if omitted.
function Key.validate_format(key, provider)
  provider = provider or PROVIDERS.active()
  -- Custom providers: key is OPTIONAL (many custom endpoints run without auth).
  -- Skip prefix and length checks; only enforce no-whitespace if a key is set.
  if provider.is_custom then
    if key and #key > 0 and key:match("%s") then
      return false, "Key contains spaces or newlines. Please paste the key "
        .. "as a single unbroken string."
    end
    return true
  end
  if not key or #key == 0 then
    return false, "No key was entered."
  end
  -- Reject keys containing whitespace (multi-line paste, trailing newlines).
  if key:match("%s") then
    return false, "Key contains spaces or newlines. Please paste the key "
      .. "as a single unbroken string."
  end
  if key:match("^https?://") or key:match("://") then
    return false, "This looks like a URL, not an API key."
  end
  -- Check for wrong-provider keys first (e.g. Claude key pasted in OpenAI field).
  if Key.matches_excluded_prefix(key, provider) then
    return false, "This looks like a different provider's key."
  end
  if #key < (provider.key_min_len or 30) then
    return false, "Key appears too short (only " .. #key .. " characters). "
      .. "This may be an incomplete paste."
  end
  if not Key.matches_known_prefix(key, provider) then
    local prefix_label = Key.prefix_label(provider)
    if provider.key_prefix_warning_only then
      return true, "Unrecognized " .. provider.label
        .. " key prefix. ReaAssist will try it with the provider."
    end
    return false, "Key does not start with \"" .. prefix_label .. "\". "
      .. provider.label .. " API keys usually begin with this prefix."
  end
  return true
end

UI = {}

-- Per-model hover descriptions shown in the V5 model dropdown. Keyed by model
-- id (not label) so renaming a label doesn't silently desync the text.
-- Source of truth for the strings: Dev/Model_Info.md ("Model dropdown
-- tooltips" section). Format is uniform across all rows:
--   "[Identity]. Use [Level] thinking. [Note]."
-- Identity is one phrase (cheapest / cheap / recommended default / premium);
-- the level names the recommended thinking pick (DeepSeek's "Non-Thinking"
-- already includes the word "thinking" so the suffix is dropped); the note
-- redirects weak combos or calls out a quality property of strong ones.
UI.MODEL_TIPS = {
  ["claude-haiku-4-5"]               = "Lowest-cost Claude. Use High thinking. Choose Sonnet None for complex work.",
  ["claude-sonnet-5"]                = "Default Claude for this app. Use None thinking. Raise the level only if a request struggles.",
  ["claude-opus-5"]                  = "Premium Claude. Use None thinking. Best tested Opus balance of quality, speed, and cost.",
  ["gpt-5.6-luna"]                   = "Default GPT for this app. Use None thinking. Fastest and lowest-cost GPT-5.6 tested.",
  ["gpt-5.6-terra"]                  = "Balanced GPT-5.6. Use None thinking. Choose it when Luna struggles.",
  ["gpt-5.6-sol"]                    = "Premium GPT-5.6. Use None thinking. Choose it for difficult work when capability matters more than cost.",
  ["gemini-3.5-flash-lite"]          = "Lowest-cost Gemini. Use Low thinking. Choose it for budget-sensitive work; Flash 3.6 Minimal is stronger overall.",
  ["gemini-3.6-flash"]               = "Default Gemini for this app. Use Minimal thinking. Best tested balance of quality, speed, and cost.",
  ["gemini-3.8-flash"]               = "Optional Gemini model. Use Low thinking. It matched Flash 3.7 while using fewer tokens and costing less in testing.",
  ["gemini-3.1-pro-preview"]         = "Premium Gemini preview. Use Medium thinking. Capacity can be unreliable; Flash 3.6 Minimal is safer for coding.",
  ["deepseek-flash"]                 = "DeepSeek's latest Flash model. Use Non-Thinking. Supports images; off-peak rates are half the peak rates.",
}

function UI.model_tip(model)
  if not model then return nil end
  local behavior_id = tostring(model.behavior_alias or model.id or "")
  local fallback = UI.MODEL_TIPS[model.id] or UI.MODEL_TIPS[behavior_id]
  if not fallback then return nil end
  if I18N and I18N.t then
    local key = "mode.model_tip." .. tostring(model.id)
    local text = I18N.t(key)
    if type(text) == "string" and text ~= "" and text ~= key then
      return text
    end
    if behavior_id ~= tostring(model.id) then
      key = "mode.model_tip." .. behavior_id
      text = I18N.t(key)
      if type(text) == "string" and text ~= "" and text ~= key then
        return text
      end
    end
  end
  return fallback
end

