-- source of the explanatory copy.
UI.COMBO_TONES = {
  anthropic = {
    ["claude-sonnet-5"] = {
      high = "warn",
    },
  },
  google = {
    ["gemini-3.1-pro-preview"] = {
      LOW = "warn",
      MEDIUM = "warn",
      HIGH = "warn",
    },
  },
  deepseek = {},
}

-- Look up the explainer line for the current (provider, model, thinking) pick.
-- Returns the string from UI.COMBO_HINTS or nil if any layer is absent (custom
-- provider, missing thinking_level, uncovered combo). Callers render nothing
-- when nil.
function UI.combo_hint(provider, model, thinking_level)
  if not (provider and model) then return nil end
  if provider.is_custom then return nil end
  local p_tbl = UI.COMBO_HINTS[provider.id];  if not p_tbl then return nil end
  -- A renamed model keeps its hints under the behavior id the rest of its
  -- per-model tables are keyed by, the way UI.model_tip resolves MODEL_TIPS
  -- and Code.model_guidance_profile resolves its prompt block. DeepSeek Flash
  -- ships as `deepseek-flash` with the behavior alias `deepseek-v4-flash`, and
  -- the translated hint in every shipped language pack is keyed by the alias.
  local model_id = tostring(model.id or "")
  local behavior_id = tostring(model.behavior_alias or model.id or "")
  local m_tbl, hint_id = p_tbl[model_id], model_id
  if not m_tbl then m_tbl, hint_id = p_tbl[behavior_id], behavior_id end
  if not m_tbl then return nil end
  local key = thinking_level and thinking_level.value
  if not key then return nil end
  local fallback = m_tbl[key]
  if not fallback then return nil end
  if I18N and I18N.t then
    local prefix = "mode.combo_hint." .. tostring(provider.id) .. "."
    local i18n_key = prefix .. model_id .. "." .. tostring(key)
    local text = I18N.t(i18n_key)
    if type(text) == "string" and text ~= "" and text ~= i18n_key then
      return text
    end
    if hint_id ~= model_id then
      i18n_key = prefix .. hint_id .. "." .. tostring(key)
      text = I18N.t(i18n_key)
      if type(text) == "string" and text ~= "" and text ~= i18n_key then
        return text
      end
    end
  end
  return fallback
end

-- Look up the visual tone for the current (provider, model, thinking) pick.
-- Returns "warn" for combos that should carry the triangle-alert badge, or nil
-- for normal rows. Custom providers are skipped because their model/tuning
-- semantics are user-defined.
function UI.combo_tone(provider, model, thinking_level)
  if not (provider and model) then return nil end
  if provider.is_custom then return nil end
  local p_tbl = UI.COMBO_TONES[provider.id]; if not p_tbl then return nil end
  -- Same key resolution as UI.combo_hint: the badge has to follow the copy.
  local m_tbl = p_tbl[model.id]
    or p_tbl[tostring(model.behavior_alias or model.id or "")]
  if not m_tbl then return nil end
  local key = thinking_level and thinking_level.value
  if not key then return nil end
  return m_tbl[key]
end


-- Floating toast: a top-level rounded bubble near the bottom-center of the
-- ReaAssist window. Draws its OWN window on top of whatever's below, so it's
-- visible regardless of scroll position or which settings page is current.
-- Animation: 180ms fade-in, 1.6s hold, 500ms fade-out (2.3s total).
-- Sticky=true skips the hold/fade-out and keeps the toast visible until the
-- caller replaces it (by firing another show_float_toast) or clears it
-- (S.float_toast = nil). Used by the Settings "Check for Updates" button
-- to show "Checking for updates..." throughout the async manifest fetch.
function UI.show_float_toast(text, kind, sticky)
  local now = reaper.time_precise()
  local FADE_IN, HOLD, FADE_OUT = 0.18, 1.6, 0.5
  S.float_toast = {
    text            = text,
    kind            = kind or "ok",  -- "ok" (green) | "warn" (amber) | "err" (red)
    sticky          = sticky == true,
    start_at        = now,
    fade_in_end_at  = now + FADE_IN,
    hold_end_at     = now + FADE_IN + HOLD,
    fade_out_end_at = now + FADE_IN + HOLD + FADE_OUT,
    fade_in_s       = FADE_IN,
    fade_out_s      = FADE_OUT,
  }
end
if Store and Store.flush_user_notice then Store.flush_user_notice() end

-- =============================================================================
-- Utility: UI.open_url
-- =============================================================================
-- Opens a URL in the user's default browser. Tries SWS CF_ShellExecute first
-- (available when the SWS extension is installed), then falls back to
-- platform-native commands.
function UI._safe_shell_url(url)
  local safe = tostring(url or ""):gsub("[^%w%-%.%_%~%:%/%?%#%[%]%@%!%&%*%+%,%;%=%{%}%%]", "")
  -- Keep real percent-encoded octets (%20, %7B, etc.) but drop stray percent
  -- signs so Windows cmd fallback cannot expand %ENV_VAR% after sanitization.
  safe = safe:gsub("%%(%x%x)", "\31%1")
  safe = safe:gsub("%%", "")
  safe = safe:gsub("\31(%x%x)", "%%%1")
  return safe
end

function UI.open_url(url)
  url = tostring(url or "")
  -- Only allow http(s) / mailto: / tel: URLs. Reject file://, javascript:,
  -- data:, and other schemes that could execute local code or inject
  -- content. mailto: + tel: are safe schemes handled by the OS shell
  -- (mail client / dialer) and are used by the Credits screen's contact
  -- links.
  if not (url:match("^https?://")
       or url:match("^mailto:")
       or url:match("^tel:")) then
    return false
  end
  if reaper.CF_ShellExecute then
    local ok, result = pcall(reaper.CF_ShellExecute, url)
    return ok and result ~= false
  else
    -- Sanitise: strip any characters that could enable shell injection.
    -- Excluded: $, (, ), `, ", \, ', non-printable chars, and stray percent.
    -- $() = command substitution on Unix; %VAR% = expansion on Windows;
    -- backtick/backslash/quotes could break quoting boundaries.
    local safe = UI._safe_shell_url(url)
    if safe == "" then return false end
    local result, _, code
    if RA.IS_WINDOWS then
      result, _, code = os.execute('start "" "' .. safe .. '"')
    elseif RA.IS_MACOS then
      -- Single quotes disable all shell interpretation (no $(), no \, no `).
      result, _, code = os.execute(
        "open '" .. safe .. "' >/dev/null 2>&1 &")
    else
      -- Single quotes disable all shell interpretation (no $(), no \, no `).
      result, _, code = os.execute(
        "xdg-open '" .. safe .. "' >/dev/null 2>&1 &")
    end
    return result == true or result == 0 or code == 0
  end
end

function UI.open_path(path)
  path = tostring(path or "")
  if path == "" or path:find("[%z\r\n]") then return false end
  if reaper.CF_ShellExecute then
    local ok, result = pcall(reaper.CF_ShellExecute, path)
    return ok and result ~= false
  end

  local result, _, code
  if RA.IS_WINDOWS then
    -- cmd.exe expands %VAR% even inside double quotes, and quotes cannot be
    -- escaped portably in the `start "" "<path>"` form. A path containing % or "
    -- would silently open the wrong location, so refuse it rather than mangle it;
    -- CF_ShellExecute (checked above) handles such paths safely when present.
    if path:find('[%"%%]') then return false end
    result, _, code = os.execute('start "" "' .. path .. '"')
  elseif RA.IS_MACOS then
    result, _, code = os.execute(
      "open " .. Shell.sh_quote(path) .. " >/dev/null 2>&1 &")
  else
    result, _, code = os.execute(
      "xdg-open " .. Shell.sh_quote(path) .. " >/dev/null 2>&1 &")
  end
  return result == true or result == 0 or code == 0
end

-- =============================================================================
-- Attachment system (base64, file I/O, screenshot, clipboard, attach helpers)
-- =============================================================================
-- Wrapped in do...end to keep internal helpers out of the main-chunk local
-- count (Lua 5.x limit: 200 locals per function/chunk).
Attach = {}
do -- attachment system scope

local b64_chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
Attach.base64_encode = function(data, start_pos, end_pos)
  if not data or #data == 0 then return "" end
  start_pos = start_pos or 1
  end_pos   = end_pos   or #data
  local out = {}
  local i = start_pos
  while i <= end_pos - 2 do
    local a, b, c = str_byte(data, i, i + 2)
    local n = a * 65536 + b * 256 + c
    out[#out+1] = str_sub(b64_chars, math_floor(n / 262144) + 1, math_floor(n / 262144) + 1)
    out[#out+1] = str_sub(b64_chars, math_floor(n / 4096) % 64 + 1, math_floor(n / 4096) % 64 + 1)
    out[#out+1] = str_sub(b64_chars, math_floor(n / 64) % 64 + 1, math_floor(n / 64) % 64 + 1)
    out[#out+1] = str_sub(b64_chars, n % 64 + 1, n % 64 + 1)
    i = i + 3
  end
  local remain = end_pos - i + 1
  if remain == 2 then
    local a, b = str_byte(data, i, i + 1)
    local n = a * 65536 + b * 256
    out[#out+1] = str_sub(b64_chars, math_floor(n / 262144) + 1, math_floor(n / 262144) + 1)
    out[#out+1] = str_sub(b64_chars, math_floor(n / 4096) % 64 + 1, math_floor(n / 4096) % 64 + 1)
    out[#out+1] = str_sub(b64_chars, math_floor(n / 64) % 64 + 1, math_floor(n / 64) % 64 + 1)
    out[#out+1] = "="
  elseif remain == 1 then
    local a = str_byte(data, i)
    local n = a * 65536
    out[#out+1] = str_sub(b64_chars, math_floor(n / 262144) + 1, math_floor(n / 262144) + 1)
    out[#out+1] = str_sub(b64_chars, math_floor(n / 4096) % 64 + 1, math_floor(n / 4096) % 64 + 1)
    out[#out+1] = "=="
  end
  return tbl_concat(out)
end

-- Chunked base64 encoder for large attachments. Pure Lua base64 over a 10MB
-- file is ~13M operations and freezes the UI thread for hundreds of ms in a
-- single synchronous pass -- catastrophic for low-latency audio. Instead we
-- pre-encode at attach time, processing one ~256KB chunk per main-loop frame
-- via Attach.pump_encoding(). The Send button stays disabled until every
-- binary attachment has finished encoding.
--
-- Chunk size is 3-byte aligned (every base64 group is 3 input bytes -> 4
-- output chars) so each chunk produces padding-free output that can be
-- concatenated directly. The very last chunk may include 1-2 leftover bytes
-- and gets the standard '='/'==' padding from base64_encode.
local B64_CHUNK_BYTES = math_floor(256 * 1024 / 3) * 3  -- ~256KB, 3-aligned

-- Attach.pump_encoding() -- called once per main-loop frame.
-- Encodes one chunk for the first attachment that still needs encoding.
-- Returns true while any work remains, false when all attachments are done.
Attach.pump_encoding = function()
  if Attach.pump_native_media then Attach.pump_native_media() end
  for _, att in ipairs(S.attachments) do
    if att.kind ~= "text" and not att.b64
        and type(att.data) == "string"
        and att.native_media_state ~= "loading"
        and att.native_media_state ~= "ready"
        and att.native_media_state ~= "consumed" then
      if not att.b64_pos then
        att.b64_pos   = 1
        att.b64_parts = {}
      end
      local len       = #att.data
      local remaining = len - att.b64_pos + 1
      local take      = (remaining <= B64_CHUNK_BYTES) and remaining or B64_CHUNK_BYTES
      att.b64_parts[#att.b64_parts+1] = Attach.base64_encode(att.data, att.b64_pos, att.b64_pos + take - 1)
      att.b64_pos = att.b64_pos + take
      if att.b64_pos > len then
        -- Encoding complete: flatten to a single string and free the source
        -- bytes so we don't carry around two copies of a 10MB file in memory.
        att.b64       = tbl_concat(att.b64_parts)
        att.b64_parts = nil
        att.b64_pos   = nil
        att.data      = nil
      end
      return true  -- one chunk per frame is enough
    end
  end
  return false
end

-- Attach.all_encoded() -- true when every binary attachment has finished
-- base64 encoding. Used by the Send button can_send check to block sending
-- until pre-encoding completes.
Attach.all_encoded = function()
  for _, att in ipairs(S.attachments) do
    if att.kind == "image" and att.native_media_state == "loading" then
      return false
    end
    if att.kind ~= "text" and att.native_media_state ~= "ready"
        and att.native_media_state ~= "consumed" and not att.b64 then
      return false
    end
  end
  return true
end

-- Attach.encoding_progress() -> {bytes_done, bytes_total} or nil if no work
-- pending. Used by the attachment strip to draw a progress indicator.
Attach.encoding_progress = function()
  local done, total = 0, 0
  local any_pending = false
  for _, att in ipairs(S.attachments) do
    if att.kind ~= "text" then
      if att.native_media_state == "loading"
          or att.native_media_state == "ready"
          or att.native_media_state == "consumed" then
        local bytes = math_max(0, tonumber(att.size_bytes) or 0)
        total = total + bytes
        if att.native_media_state == "loading" then
          any_pending = true
        else
          done = done + bytes
        end
      elseif att.b64 then
        -- Already encoded -- we no longer have att.data, but we tracked the
        -- byte count by counting base64 chars * 3 / 4 (close enough for the
        -- progress display).
        local approx_bytes = math_floor(#att.b64 * 3 / 4)
        done  = done  + approx_bytes
        total = total + approx_bytes
      else
        any_pending = true
        local len = #(att.data or "")
        total = total + len
        done  = done  + (att.b64_pos or 1) - 1
      end
    end
  end
  if not any_pending then return nil end
  return done, total
end

-- =============================================================================
-- Attachment utilities
-- =============================================================================
-- Supported image MIME types for the AI provider vision endpoints.
local IMAGE_EXTENSIONS = {
  jpg = "image/jpeg", jpeg = "image/jpeg", png = "image/png",
  gif = "image/gif", webp = "image/webp",
}
-- Text file extensions that are read as UTF-8 text and sent as text blocks.
local TEXT_EXTENSIONS = {
  lua = true, txt = true, csv = true, py = true, js = true, ts = true,
  json = true, xml = true, html = true, css = true, md = true, yaml = true,
  yml = true, ini = true, cfg = true, conf = true, sh = true, bat = true,
  log = true, rpp = true, reascript = true, c = true, cpp = true, h = true,
  jsfx = true, ["jsfx-inc"] = true, eel = true,
}
local REFUSED_BINARY_EXTENSIONS = {
  zip = true,
}

-- get_file_extension(path) -> lowercase extension without dot, or ""
local function get_file_extension(path)
  local ext = path:match("%.([^%.]+)$")
  return ext and ext:lower() or ""
end

-- get_filename(path) -> filename with extension
local function get_filename(path)
  return path:match("[^\\/]+$") or path
end

-- Maximum size (bytes) for text attachments. Files larger than this are
-- rejected to avoid blowing up token budgets and provider context windows.
local TEXT_ATTACH_MAX_BYTES = 2 * 1024 * 1024  -- 2 MiB

local function text_attachment_size_admitted(size_bytes)
  return type(size_bytes) == "number" and size_bytes >= 0
    and size_bytes <= TEXT_ATTACH_MAX_BYTES
end

-- is_likely_binary(path) -> true if the file appears to be binary.
-- Reads the first 512 bytes and checks for null bytes, which are absent
-- in well-formed UTF-8 / ASCII text but common in binary formats.
local function is_likely_binary(path)
  local f = io.open(path, "rb")
  if not f then return false end
  local head = f:read(512)
  f:close()
  if not head then return false end
  return head:find("\0") ~= nil
end

-- classify_file(path) -> "image", "pdf", "text", or "unsupported" + media_type
-- Files with a recognised text extension, unknown extension, or no extension
-- are treated as text only when the binary sniff passes. Binary-looking files
-- stay unsupported so they are not shoved into the prompt as garbage.
local function classify_file(path)
  local ext = get_file_extension(path)
  if IMAGE_EXTENSIONS[ext] then return "image", IMAGE_EXTENSIONS[ext] end
  if ext == "pdf" then return "pdf", "application/pdf" end
  if TEXT_EXTENSIONS[ext] then return "text", nil end
  if REFUSED_BINARY_EXTENSIONS[ext] then return "unsupported", nil end
  -- Unknown/extensionless: attempt a binary sniff. If the file looks like text,
  -- allow it; otherwise reject it as unsupported.
  if not is_likely_binary(path) then return "text", nil end
  return "unsupported", nil
end

-- read_file_binary(path) -> data string or nil, error
local function read_file_binary(path)
  local f, err = io.open(path, "rb")
  if not f then return nil, err end
  local data = f:read("*a")
  f:close()
  return data
end

local function file_size_bytes(path)
  local file = io.open(path, "rb")
  if not file then return nil end
  local size = file:seek("end")
  file:close()
  return tonumber(size)
end

-- read_file_text(path) -> text string or nil, error
local function read_file_text(path)
  local f, err = io.open(path, "r")
  if not f then return nil, err end
  local text = f:read("*a")
  f:close()
  return text
end

-- read_image_dimensions(data, media_type) -> width, height or nil, nil
-- Reads pixel dimensions from PNG/JPEG/GIF/WebP file headers without
-- decoding the full image. Returns nil if the format is unrecognized.
local function read_image_dimensions(data, media_type)
  if not data or #data < 24 then return nil, nil end

  -- PNG: bytes 1-8 are signature, IHDR chunk starts at byte 9.
  -- Width at bytes 17-20, height at bytes 21-24 (big-endian uint32).
  if media_type == "image/png" then
    if str_sub(data, 1, 4) == "\137PNG" then
      local w = str_byte(data,17)*16777216 + str_byte(data,18)*65536
             + str_byte(data,19)*256 + str_byte(data,20)
      local h = str_byte(data,21)*16777216 + str_byte(data,22)*65536
             + str_byte(data,23)*256 + str_byte(data,24)
      if w > 0 and h > 0 then return w, h end
    end
  end

  -- JPEG: scan for SOF0/SOF2 marker (0xFF 0xC0 or 0xFF 0xC2).
  -- Height at marker+5 (2 bytes), width at marker+7 (2 bytes), big-endian.
  if media_type == "image/jpeg" then
    local pos = 1
    local len = #data
    while pos < len - 10 do
      if str_byte(data, pos) == 0xFF then
        local marker = str_byte(data, pos + 1)
        if marker == 0xC0 or marker == 0xC2 then
          local h = str_byte(data, pos+5)*256 + str_byte(data, pos+6)
          local w = str_byte(data, pos+7)*256 + str_byte(data, pos+8)
          if w > 0 and h > 0 then return w, h end
        end
        -- Skip to next marker using segment length
        if marker ~= 0x00 and marker ~= 0xFF and marker ~= 0xD8 and marker ~= 0xD9 then
          if pos + 3 <= len then
            local seg_len = str_byte(data, pos+2)*256 + str_byte(data, pos+3)
            -- A valid JPEG segment includes the 2-byte length field
            -- itself; seg_len < 2 is malformed and would either loop
            -- forever (seg_len = 0) or rewind into the marker we just
            -- read. Bail rather than risk the loop on hostile input.
            if seg_len < 2 then break end
            pos = pos + 2 + seg_len
          else
            break
          end
        else
          pos = pos + 1
        end
      else
        pos = pos + 1
      end
    end
  end

  -- GIF: width at bytes 7-8, height at bytes 9-10 (little-endian uint16).
  if media_type == "image/gif" then
    if str_sub(data, 1, 3) == "GIF" then
      local w = str_byte(data,7) + str_byte(data,8)*256
      local h = str_byte(data,9) + str_byte(data,10)*256
      if w > 0 and h > 0 then return w, h end
    end
  end

  -- WebP: "RIFF" at 1-4, "WEBP" at 9-12. VP8 chunk has dimensions.
  if media_type == "image/webp" then
    if str_sub(data, 1, 4) == "RIFF" and str_sub(data, 9, 12) == "WEBP" then
      local chunk = str_sub(data, 13, 16)
      if chunk == "VP8 " and #data >= 30 then
        -- Lossy VP8: width at 27-28, height at 29-30 (little-endian, masked)
        local w = (str_byte(data,27) + str_byte(data,28)*256) % 16384
        local h = (str_byte(data,29) + str_byte(data,30)*256) % 16384
        if w > 0 and h > 0 then return w, h end
      elseif chunk == "VP8L" and #data >= 26 then
        -- Lossless VP8L: packed bits at byte 22-25
        local b1,b2,b3,b4 = str_byte(data,22,25)
        local w = (b1 + (b2 % 64) * 256) + 1
        local h = (math_floor(b2/64) + b3*4 + (b4 % 16)*1024) + 1
        if w > 0 and h > 0 then return w, h end
      end
    end
  end

  return nil, nil
end

-- Estimate token cost for an attachment. Returns estimated tokens (number).
-- Images: based on pixel dimensions (tokens ~ width*height/750).
-- PDFs: ~1500 tokens per page; estimated from file size (~50KB per page).
-- Text: ~4 chars per token.
local function estimate_attachment_tokens(attachment)
  if attachment.kind == "image" then
    -- Try to read actual dimensions from the image header.
    -- Claude resizes images so the longest side is at most 1568px before
    -- calculating tokens. Apply the same scaling here for accuracy.
    local w, h = read_image_dimensions(attachment.data, attachment.media_type)
    if w and h then
      local MAX_SIDE = 1568
      if w > MAX_SIDE or h > MAX_SIDE then
        local scale = MAX_SIDE / math_max(w, h)
        w = math_floor(w * scale)
        h = math_floor(h * scale)
      end
      return math_max(85, math_floor(w * h / 750))
    end
    -- Fallback: rough estimate from file size (conservative 2 bytes/pixel
    -- for PNG screenshots which compress heavily).
    local pixels = (tonumber(attachment.size_bytes)
      or #(attachment.data or "")) / 2
    return math_max(85, math_floor(pixels / 750))
  elseif attachment.kind == "pdf" then
    local pages = math_max(1, math_floor(#attachment.data / 50000))
    return pages * 1500
  elseif attachment.kind == "text" then
    return math_floor(#attachment.data / 4)
  end
  return 0
end

-- Estimate USD cost for attachment tokens given the current model.
local function estimate_attachment_cost(tokens)
  local model = MODELS[prefs.model_idx]
  if not model then return 0 end
  return MODELS.calc_cost(model, tokens, 0, 0, 0)
end

-- Max attachment size (bytes) -- warn above 5MB, reject above 10MB.
-- Claude resizes images internally, so >10MB rarely adds value.
local ATTACH_WARN_BYTES  = 5 * 1024 * 1024
local ATTACH_MAX_BYTES   = 10 * 1024 * 1024
local ATTACH_MAX_COUNT   = 10  -- max attachments per message

-- Native image imports are capability-owned Engine resources. Successfully
-- admitted images remain path and metadata only in Lua and use an Engine-only
-- dispatch. A terminal import failure may deliberately read a fresh legacy
-- copy before send. Consumed resources never enter curl replay.
local native_media_records = {}
local native_media_temp_serial = 0

local function native_media_engine_usable()
  if S.screen_reader_mode or type(Engine) ~= "table"
      or type(Engine.input_media_create) ~= "function"
      or type(Engine.input_media_status) ~= "function"
      or type(Engine.input_media_close) ~= "function"
      or type(Engine.usable) ~= "function" then
    return false
  end
  local ok, usable = pcall(Engine.usable)
  return ok and usable == true
end

local function native_media_provider_supported()
  local provider = type(PROVIDERS) == "table"
    and type(PROVIDERS.active) == "function" and PROVIDERS.active() or nil
  if type(provider) ~= "table" then return false end
  local model = type(MODELS) == "table" and MODELS[prefs.model_idx] or nil
  if provider.is_custom == true then
    if provider.is_native_custom ~= true then return false end
    for _, modality in ipairs(type(model) == "table"
        and model.input_modalities or {}) do
      if modality == "image" then return true end
    end
    return false
  end
  if provider.id ~= "openai" and provider.id ~= "anthropic"
      and provider.id ~= "google" and provider.id ~= "deepseek"
      and provider.id ~= "openrouter" then
    return false
  end
  if provider.id == "deepseek" then
    for _, modality in ipairs(type(model) == "table"
        and model.input_modalities or {}) do
      if modality == "image" then return true end
    end
    return false
  end
  return true
end

local function native_media_remove_temp(record)
  if type(record) == "table" and type(record.temp_path) == "string"
      and record.temp_path ~= "" then
    os.remove(record.temp_path)
    record.temp_path = nil
  end
end

local function native_media_close_record(record)
  if type(record) ~= "table" or record.closed == true then return end
  record.closed = true
  local handle = record.handle
  if type(handle) == "table" and type(Engine) == "table"
      and type(Engine.input_media_close) == "function" then
    pcall(Engine.input_media_close, handle)
  end
  native_media_remove_temp(record)
  if type(record.attachment) == "table" then
    record.attachment.native_media_handle = nil
    if record.attachment.native_media_state ~= "consumed" then
      record.attachment.native_media_state = "closed"
    end
  end
end

local function native_media_preserve_capture(path)
  native_media_temp_serial = native_media_temp_serial + 1
  local stem, ext = tostring(path or ""):match("^(.*)(%.[^%.\\/]+)$")
  if not stem then stem, ext = tostring(path or ""), ".png" end
  local instance = tostring(S.INSTANCE_ID or "instance"):gsub("[^%w_-]", "_")
  local preserved = stem .. ".input_media_" .. instance .. "_"
    .. tostring(native_media_temp_serial) .. ext
  if os.rename(path, preserved) then return preserved end
  return nil
end

Attach.begin_native_media = function(attachment, source_path, temp_path)
  if type(attachment) ~= "table" or attachment.kind ~= "image"
      or type(source_path) ~= "string" or source_path == "" then
    return false
  end
  if not native_media_engine_usable()
      or not native_media_provider_supported() then
    return false
  end
  attachment.native_media_attempted = true
  local ok, handle, failure = pcall(Engine.input_media_create,
    source_path, attachment.media_type)
  if not ok or type(handle) ~= "table" then
    attachment.native_media_state = "failed"
    attachment.native_media_error = type(failure) == "table"
      and tostring(failure.error or failure.state or "create_refused")
      or "create_refused"
    return false
  end
  local record = {
    attachment = attachment,
    handle = handle,
    temp_path = temp_path,
    source_path = source_path,
    closed = false,
  }
  attachment.native_media_handle = handle
  attachment.native_media_state = "loading"
  attachment.native_media_record = record
  native_media_records[#native_media_records + 1] = record
  return true
end

local function native_media_attachment_is_owned(attachment)
  for _, list in ipairs({S.attachments, S.pending_attachments}) do
    if type(list) == "table" then
      for _, candidate in ipairs(list) do
        if candidate == attachment then return true end
      end
    end
  end
  return false
end

Attach.pump_native_media = function()
  for index = #native_media_records, 1, -1 do
    local record = native_media_records[index]
    local attachment = record.attachment
    if record.closed == true then
      tbl_remove(native_media_records, index)
    elseif not native_media_attachment_is_owned(attachment) then
      native_media_close_record(record)
      tbl_remove(native_media_records, index)
    elseif type(record.handle) == "table"
        and record.handle.consumed == true then
      attachment.native_media_state = "consumed"
      native_media_remove_temp(record)
    elseif attachment.native_media_state == "loading" then
      local ok, status = pcall(Engine.input_media_status, record.handle)
      if ok and type(status) == "table" and status.state == "ready" then
        attachment.native_media_state = "ready"
        native_media_remove_temp(record)
      elseif ok and type(status) == "table" and status.state == "consumed" then
        attachment.native_media_state = "consumed"
        native_media_remove_temp(record)
      elseif not ok or type(status) ~= "table" or status.state == "failed"
          or status.state == "closed" then
        local data = read_file_binary(record.source_path)
        attachment.native_media_state = type(data) == "string"
          and #data > 0 and "legacy" or "failed"
        attachment.native_media_error = type(status) == "table"
          and tostring(status.error or status.state or "import_failed")
          or "import_failed"
        if attachment.native_media_state == "legacy" then
          attachment.data = data
        else
          S.attach_error = RA.t("attach.error.import_failed", nil,
            "ReaAssist could not import this image. Remove it and attach it again.")
          S.attach_error_time = time_precise()
        end
        native_media_close_record(record)
        tbl_remove(native_media_records, index)
      end
    end
  end
end

Attach.close_all_native_media = function()
  for index = #native_media_records, 1, -1 do
    native_media_close_record(native_media_records[index])
    native_media_records[index] = nil
  end
end

-- Replaces only image data in the newest canonical user message. This keeps
-- capabilities and source paths outside JSON while preserving earlier turns.
Attach.native_input_plan = function(input_json, attachments)
  local images = {}
  for _, attachment in ipairs(attachments or {}) do
    if attachment.kind == "image" then images[#images + 1] = attachment end
  end
  if #images == 0 then return input_json, nil end
  for _, attachment in ipairs(images) do
    if attachment.native_media_state ~= "ready"
        or type(attachment.native_media_handle) ~= "table" then
      if attachment.native_media_attempted == true then
        return nil, nil, "native_input_media_unavailable"
      end
      return input_json, nil
    end
  end
  if type(RA) ~= "table" or type(RA.JSON) ~= "table"
      or type(RA.JSON.decode) ~= "function"
      or type(RA.JSON.encode) ~= "function" then
    return nil, nil, "native_input_media_json_unavailable"
  end
  local ok_decode, decoded = pcall(RA.JSON.decode, input_json)
  if not ok_decode or type(decoded) ~= "table" then
    return nil, nil, "native_input_media_json_invalid"
  end
  local messages = type(decoded.messages) == "table" and decoded.messages
    or type(decoded.contents) == "table" and decoded.contents or nil
  local newest = messages and messages[#messages] or nil
  if type(newest) ~= "table" then
    return nil, nil, "native_input_media_message_missing"
  end
  local next_image = 1
  local function rewrite(value)
    if type(value) ~= "table" then return value end
    local is_image = value.type == "image_url"
      and type(value.image_url) == "table"
      and type(value.image_url.url) == "string"
      and value.image_url.url:match("^data:image/[^;]+;base64,") ~= nil
    is_image = is_image or (value.type == "image"
      and type(value.source) == "table" and value.source.type == "base64"
      and type(value.source.media_type) == "string"
      and value.source.media_type:match("^image/") ~= nil)
    is_image = is_image or (value.type == "inline_data"
      and type(value.mime_type) == "string"
      and value.mime_type:match("^image/") ~= nil)
    if value.type == "input_media" and type(value.index) == "number" then
      next_image = next_image + 1
      return value
    end
    if is_image then
      local index = next_image
      next_image = next_image + 1
      return {type = "input_media", index = index - 1}
    end
    if #value > 0 then
      for index = 1, #value do value[index] = rewrite(value[index]) end
    else
      local keys = {}
      for key in pairs(value) do keys[#keys + 1] = key end
      table.sort(keys, function(a, b) return tostring(a) < tostring(b) end)
      for _, key in ipairs(keys) do value[key] = rewrite(value[key]) end
    end
    return value
  end
  rewrite(newest)
  if next_image - 1 ~= #images then
    return nil, nil, "native_input_media_placeholder_mismatch"
  end
  local ok_encode, rewritten = pcall(RA.JSON.encode, decoded)
  if not ok_encode or type(rewritten) ~= "string" or rewritten == "" then
    return nil, nil, "native_input_media_json_encode_failed"
  end
  local handles = {}
  for index, attachment in ipairs(images) do
    handles[index] = attachment.native_media_handle
  end
  return rewritten, handles
end

Attach.native_media_index = function(attachments, target)
  if not native_media_provider_supported() then return nil end
  local index = 0
  for _, attachment in ipairs(attachments or {}) do
    if attachment.kind == "image" then
      if attachment == target then
        if attachment.native_media_state == "ready"
            and type(attachment.native_media_handle) == "table" then
          return index
        end
        return nil
      end
      index = index + 1
    end
  end
  return nil
end


Attach.prepare_native_media_for_provider = function(attachments)
  local has_native = false
  for _, attachment in ipairs(attachments or {}) do
    if attachment.kind == "image"
        and (attachment.native_media_state == "loading"
          or attachment.native_media_state == "ready") then
      has_native = true
      break
    end
  end
  if not has_native then return true end
  if native_media_provider_supported() then return true end
  local transitioned = false
  for _, attachment in ipairs(attachments or {}) do
    if attachment.kind == "image"
        and (attachment.native_media_state == "loading"
          or attachment.native_media_state == "ready") then
      local record = attachment.native_media_record
      local data = type(record) == "table"
        and read_file_binary(record.source_path) or nil
      if type(data) == "string" and #data > 0 then
        attachment.data = data
        attachment.native_media_state = "legacy"
        transitioned = true
      else
        attachment.native_media_state = "failed"
        S.attach_error = "This native image cannot be sent through the selected Custom or Local provider. Remove it and attach it again."
        S.attach_error_time = time_precise()
      end
      if type(record) == "table" then native_media_close_record(record) end
    end
  end
  if transitioned then
    S.attach_error = "Provider changed. ReaAssist is preparing a fresh legacy image copy. Send again when encoding finishes."
    S.attach_error_time = time_precise()
  end
  return false, transitioned and "input_media_legacy_preparing"
    or "input_media_provider_unsupported"
end

Attach.aggregate_limit_bytes = function()
  local image_limits = type(Engine) == "table"
    and type(Engine.inference_image_limits) == "function"
    and Engine.inference_image_limits() or nil
  local aggregate_limit = type(image_limits) == "table"
    and tonumber(image_limits.aggregate_bytes) or nil
  if aggregate_limit and aggregate_limit >= 1 then
    return math_floor(aggregate_limit)
  end
  local request_limit = type(Engine) == "table"
    and type(Engine.inference_request_body_limit) == "function"
    and Engine.inference_request_body_limit() or 64 * 1024 * 1024
  if type(request_limit) ~= "number" or request_limit < 1024 * 1024 then
    request_limit = 64 * 1024 * 1024
  end
  -- Reserve 10 MiB for JSON, prompts, and message history, then account for
  -- the 4:3 base64 expansion. The final encoded-body check remains exact.
  return math_max(1,
    math_floor((request_limit - 10 * 1024 * 1024) * 3 / 4))
end

Attach.aggregate_source_bytes = function(extra_bytes)
  local total = math_max(0, tonumber(extra_bytes) or 0)
  for _, att in ipairs(S.attachments) do
    local size = tonumber(att.size_bytes)
    if not size and type(att.data) == "string" then size = #att.data end
    if not size and type(att.b64) == "string" then
      size = math_floor(#att.b64 * 3 / 4)
    end
    total = total + math_max(0, size or 0)
  end
  return total
end

Attach.aggregate_admitted = function(extra_bytes)
  return Attach.aggregate_source_bytes(extra_bytes)
    <= Attach.aggregate_limit_bytes()
end

Attach.set_aggregate_error = function()
  S.attach_error = RA.t("attach.error.aggregate_limit", nil,
    "Attachments are too large for one request. Remove an attachment or use smaller files.")
  S.attach_error_time = time_precise()
end

-- =============================================================================
-- Screenshot capture
-- =============================================================================
-- Captures the screen to a temporary PNG file for use as an attachment.
-- Windows: uses PowerShell + .NET GDI to capture the REAPER main window
--   region specifically when Engine or js_ReaScriptAPI window probing exists;
--   otherwise it falls back to the full primary screen.
-- macOS: uses the built-in screencapture utility (silent, no shutter sound).
--   This captures all screens, not just the REAPER window -- macOS does not
--   expose a simple per-window capture via shell without extra dependencies.
-- Linux: tries common desktop capture tools (grim, gnome-screenshot,
--   spectacle, scrot, ImageMagick import), capturing the full screen.
-- Returns the PNG file path on success, or nil + error string.
local function capture_screenshot()
  local png_path = tmp.screenshot

  if RA.IS_WINDOWS then
    local hwnd = reaper.GetMainHwnd()
    if not hwnd then return nil, "Could not find REAPER main window." end

    local ps_script
    local window_get_rect = RA.preferred_platform_api(
      "MBH_Window_GetRect", "JS_Window_GetRect")
    if window_get_rect then
      local _, left, top, right, bottom = window_get_rect(hwnd)
      local w = right - left
      local h = bottom - top
      if w <= 0 or h <= 0 then return nil, "Invalid window dimensions." end
      -- Minimized REAPER on Windows reports rect coords near (-32000,
      -- -32000) -- the standard ShowWindow(SW_MINIMIZE) sentinel. The
      -- positive w/h above passes the previous guard, but CopyFromScreen
      -- from those coordinates produces a uniformly black bitmap that
      -- attaches as a useless screenshot. Treat any far-off-screen
      -- origin as minimized/hidden and refuse the capture so the user
      -- gets a clear error instead of a black image.
      if left < -10000 or top < -10000 then
        return nil, "REAPER window is minimized or off-screen. "
          .. "Restore it before taking a screenshot."
      end
      ps_script = str_format(
        "Add-Type -AssemblyName System.Drawing; "
        .. "$bmp = New-Object System.Drawing.Bitmap(%d, %d); "
        .. "$g = [System.Drawing.Graphics]::FromImage($bmp); "
        .. "$g.CopyFromScreen(%d, %d, 0, 0, $bmp.Size); "
        .. "$g.Dispose(); "
        .. "$bmp.Save('%s', [System.Drawing.Imaging.ImageFormat]::Png); "
        .. "$bmp.Dispose(); "
        .. "Write-Output 'OK'",
        w, h, left, top, png_path:gsub("'", "''"))
    else
      ps_script =
        "Add-Type -AssemblyName System.Drawing; "
        .. "Add-Type -AssemblyName System.Windows.Forms; "
        .. "$bounds = [System.Windows.Forms.Screen]::PrimaryScreen.Bounds; "
        .. "$bmp = New-Object System.Drawing.Bitmap($bounds.Width, $bounds.Height); "
        .. "$g = [System.Drawing.Graphics]::FromImage($bmp); "
        .. "$g.CopyFromScreen($bounds.Location, [System.Drawing.Point]::Empty, $bounds.Size); "
        .. "$g.Dispose(); "
        .. "$bmp.Save('" .. png_path:gsub("'", "''") .. "', "
        .. "[System.Drawing.Imaging.ImageFormat]::Png); "
        .. "$bmp.Dispose(); "
        .. "Write-Output 'OK'"
    end

    local ps_cmd = 'powershell -NoProfile -WindowStyle Hidden -Command "' .. ps_script .. '"'
    local result = reaper.ExecProcess(ps_cmd, 10000)
    if not result or not result:match("OK") then
      os.remove(png_path)
      return nil, "Screenshot capture failed. PowerShell returned: "
        .. tostring(result and result:sub(1, 200) or "nil")
    end

    local f = io.open(png_path, "rb")
    if f then
      local size = f:seek("end")
      f:close()
      if size and size > 0 then
        return png_path
      end
    end
    os.remove(png_path)
    return nil, "Screenshot produced an empty file."

  elseif RA.IS_MACOS then
    -- screencapture -x: silent (no shutter sound). Captures all screens.
    -- Absolute path because REAPER's os.execute / ExecProcess on some
    -- macOS configs (notably Tahoe) doesn't reliably resolve PATH-based
    -- binaries; mirrors the /usr/bin/curl pattern in the installer.
    local sq_path = "'" .. png_path:gsub("'", "'\\''") .. "'"
    local ok, _, code = os.execute("/usr/sbin/screencapture -x " .. sq_path)
    if ok then
      local f = io.open(png_path, "rb")
      if f then
        local size = f:seek("end")
        f:close()
        if size and size > 0 then return png_path end
      end
    end
    os.remove(png_path)
    -- Surface the actionable cause via a modal popup. Since macOS 10.15,
    -- screencapture from a child process is denied when the parent app
    -- (REAPER) lacks Screen Recording permission -- with no Lua-level
    -- error, the file just never appears or comes back empty. The
    -- transient inline error in the attachment row is too short to fit
    -- the recovery steps, so use reaper.MB to deliver them.
    reaper.MB(
      RA.t("attach.screenshot.macos_permission_popup", {
        code = tostring(code or "?"),
      }, "Screenshot capture failed (exit " .. tostring(code or "?") .. ").\n\n"
        .. "On macOS this usually means REAPER does not have Screen Recording "
        .. "permission. To grant it:\n\n"
        .. "1. Open System Settings > Privacy & Security > Screen Recording.\n"
        .. "2. Enable REAPER in the list.\n"
        .. "3. Quit and reopen REAPER (macOS requires this before the new "
        .. "permission takes effect).\n"
        .. "4. Try the screenshot attachment again.\n\n"
        .. "On macOS Sequoia / Tahoe you may also see a one-time \"bypass "
        .. "the system private window picker\" prompt the first time the "
        .. "capture runs -- click Allow."),
      "ReaAssist", 0)
    return nil, RA.t("attach.error.screenshot_failed_popup", nil,
      "Screenshot capture failed (see popup for details).")
  elseif RA.IS_LINUX then
    local q_path = Shell.sh_quote(png_path)
    local cmds = {
      "command -v grim >/dev/null 2>&1 && grim " .. q_path,
      "command -v gnome-screenshot >/dev/null 2>&1 && gnome-screenshot -f " .. q_path,
      "command -v spectacle >/dev/null 2>&1 && spectacle -b -n -o " .. q_path,
      "command -v scrot >/dev/null 2>&1 && scrot " .. q_path,
      "command -v import >/dev/null 2>&1 && import -window root " .. q_path,
    }
    for _, cmd in ipairs(cmds) do
      os.remove(png_path)
      local ok = os.execute(cmd)
      if ok then
        local f = io.open(png_path, "rb")
        if f then
          local size = f:seek("end")
          f:close()
          if size and size > 0 then return png_path end
        end
      end
    end
    os.remove(png_path)
    return nil, RA.t("attach.error.screenshot_linux_unsupported", nil,
      "Screenshot capture on Linux needs grim, gnome-screenshot, spectacle, "
      .. "scrot, or ImageMagick import.")
  end

  return nil, RA.t("attach.error.screenshot_linux_unsupported", nil,
    "Screenshot capture is not available on this platform.")
end

-- =============================================================================
-- Clipboard image paste
-- =============================================================================
-- Checks if the clipboard contains an image and returns it as a PNG file path.
-- Windows: uses PowerShell with .NET to read the clipboard.
-- macOS: uses osascript to read clipboard image data and write it as PNG.
-- Linux: tries image/png clipboard targets via wl-paste (Wayland) or xclip.
local function get_clipboard_image()
  local png_path = tmp.clipboard

  if RA.IS_WINDOWS then
    local ps_cmd = 'powershell -NoProfile -WindowStyle Hidden -Command "'
      .. "Add-Type -AssemblyName System.Windows.Forms; "
      .. "Add-Type -AssemblyName System.Drawing; "
      .. "$img = [System.Windows.Forms.Clipboard]::GetImage(); "
      .. "if ($img -ne $null) { "
      .. "$img.Save('" .. png_path:gsub("'", "''") .. "', "
      .. "[System.Drawing.Imaging.ImageFormat]::Png); "
      .. "Write-Output 'OK' "
      .. '} else { Write-Output \'EMPTY\' }"'

    local result = reaper.ExecProcess(ps_cmd, 5000)
    if result and result:match("OK") then
      local f = io.open(png_path, "rb")
      if f then
        local size = f:seek("end")
        f:close()
        if size and size > 0 then return png_path end
      end
    end
    os.remove(png_path)
    return nil

  elseif RA.IS_MACOS then
    -- Use osascript to grab clipboard image data as PNG and write to file.
    local sq_path = png_path:gsub("'", "'\\''")
    local cmd = "osascript -e '"
      .. 'try\n'
      .. '  set imgData to the clipboard as «class PNGf»\n'
      .. '  set fp to open for access POSIX file "' .. sq_path .. '" with write permission\n'
      .. '  set eof fp to 0\n'
      .. '  write imgData to fp\n'
      .. '  close access fp\n'
      .. '  return "OK"\n'
      .. 'on error\n'
      .. '  return "EMPTY"\n'
      .. "end try'"
    local handle = io.popen(cmd)
    if handle then
      local result = handle:read("*a")
      handle:close()
      if result and result:match("OK") then
        local f = io.open(png_path, "rb")
        if f then
          local size = f:seek("end")
          f:close()
          if size and size > 0 then return png_path end
        end
      end
    end
    os.remove(png_path)
    return nil
  elseif RA.IS_LINUX then
    local q_path = Shell.sh_quote(png_path)
    local cmds = {
      "command -v wl-paste >/dev/null 2>&1 && wl-paste --type image/png > " .. q_path,
      "command -v xclip >/dev/null 2>&1 && xclip -selection clipboard -t image/png -o > " .. q_path,
    }
    for _, cmd in ipairs(cmds) do
      os.remove(png_path)
      local ok = os.execute(cmd)
      if ok then
        local f = io.open(png_path, "rb")
        if f then
          local size = f:seek("end")
          f:close()
          if size and size > 0 then return png_path end
        end
      end
    end
    os.remove(png_path)
    return nil
  end

  return nil
end

-- Attach.file(path) -> true on success, false + sets S.attach_error on failure.
-- Reads the file, classifies it, estimates cost, and adds to the queue.
Attach.file = function(path)
  if #S.attachments >= ATTACH_MAX_COUNT then
    S.attach_error = (RA and RA.t and RA.t("attach.error.max_count",
      { count = ATTACH_MAX_COUNT },
      str_format("Maximum %d attachments per message.", ATTACH_MAX_COUNT)))
      or str_format("Maximum %d attachments per message.", ATTACH_MAX_COUNT)
    S.attach_error_time = time_precise()
    return false
  end

  local kind, media_type = classify_file(path)

  if kind == "unsupported" then
    local ext = get_file_extension(path)
    local ext_text = ext ~= "" and (" (." .. ext .. ")") or ""
    S.attach_error = (RA and RA.t and RA.t("attach.error.unsupported_type",
      { ext = ext_text },
      str_format("Unsupported file type%s. Supported: images, PDFs, and common text formats.",
        ext ~= "" and (" (." .. ext .. ")") or "")))
      or str_format("Unsupported file type%s. Supported: images, PDFs, and common text formats.",
        ext ~= "" and (" (." .. ext .. ")") or "")
    S.attach_error_time = time_precise()
    return false
  end

  -- A visual Engine image stays path and metadata only in Lua. The Engine
  -- validates and reads it on its worker. Read bytes here only when native
  -- admission is unavailable or synchronously refused.
  if kind == "image" and native_media_engine_usable() then
    local native_size = file_size_bytes(path)
    if not native_size or native_size < 1 then
      S.attach_error = "Could not read image metadata."
      S.attach_error_time = time_precise()
      return false
    end
    if native_size > ATTACH_MAX_BYTES then
      S.attach_error = str_format("File too large (%.1f MB, max %d MB).",
        native_size / 1048576, ATTACH_MAX_BYTES / 1048576)
      S.attach_error_time = time_precise()
      return false
    end
    if not Attach.aggregate_admitted(native_size) then
      Attach.set_aggregate_error()
      return false
    end
    local native_entry = {
      kind = kind, name = get_filename(path), media_type = media_type,
      path = path, size_bytes = native_size,
    }
    native_entry.tokens = estimate_attachment_tokens(native_entry)
    native_entry.cost = estimate_attachment_cost(native_entry.tokens)
    S.attachments[#S.attachments + 1] = native_entry
    if Attach.begin_native_media(native_entry, path, nil) then return true end
    tbl_remove(S.attachments, #S.attachments)
  end

  local data, err
  if kind == "text" then
    data, err = read_file_text(path)
  else
    data, err = read_file_binary(path)
  end

  if not data then
    S.attach_error = (RA and RA.t and RA.t("attach.error.read_failed",
      { error = tostring(err) }, "Could not read file: " .. tostring(err)))
      or ("Could not read file: " .. tostring(err))
    S.attach_error_time = time_precise()
    return false
  end

  -- Text-specific size cap: prevents token budget blow-ups from large logs,
  -- data files, etc. Binary attachments (images, PDFs) use the general cap.
  if kind == "text" and not text_attachment_size_admitted(#data) then
    local size_kb = str_format("%.0f", #data / 1024)
    local max_kb = str_format("%d", TEXT_ATTACH_MAX_BYTES / 1024)
    S.attach_error = (RA and RA.t and RA.t("attach.error.text_too_large",
      { size = size_kb, max = max_kb },
      str_format("Text file too large (%.0f KB, max %d KB).",
        #data / 1024, TEXT_ATTACH_MAX_BYTES / 1024)))
      or str_format("Text file too large (%.0f KB, max %d KB).",
        #data / 1024, TEXT_ATTACH_MAX_BYTES / 1024)
    S.attach_error_time = time_precise()
    return false
  end

  if #data > ATTACH_MAX_BYTES then
    local size_mb = str_format("%.1f", #data / 1048576)
    local max_mb = str_format("%d", ATTACH_MAX_BYTES / 1048576)
    S.attach_error = (RA and RA.t and RA.t("attach.error.file_too_large",
      { size = size_mb, max = max_mb },
      str_format("File too large (%.1f MB, max %d MB).",
        #data / 1048576, ATTACH_MAX_BYTES / 1048576)))
      or str_format("File too large (%.1f MB, max %d MB).",
        #data / 1048576, ATTACH_MAX_BYTES / 1048576)
    S.attach_error_time = time_precise()
    return false
  end

  if #data == 0 then
    S.attach_error = (RA and RA.t and RA.t("attach.error.empty_file", nil,
      "File is empty.")) or "File is empty."
    S.attach_error_time = time_precise()
    return false
  end

  if not Attach.aggregate_admitted(#data) then
    Attach.set_aggregate_error()
    return false
  end

  local entry = {
    kind       = kind,
    name       = get_filename(path),
    data       = data,
    media_type = media_type,
    path       = path,
    size_bytes = #data,
  }
  entry.tokens = estimate_attachment_tokens(entry)
  entry.cost   = estimate_attachment_cost(entry.tokens)

  S.attachments[#S.attachments+1] = entry

  if #data > ATTACH_WARN_BYTES then
    local size_mb = str_format("%.1f", #data / 1048576)
    local cost = MODELS.format_cost(entry.cost)
    S.attach_error = (RA and RA.t and RA.t("attach.warning.large_file",
      { size = size_mb, cost = cost },
      str_format("Large file (%.1f MB), estimated cost: %s",
        #data / 1048576, cost)))
      or str_format("Large file (%.1f MB), estimated cost: %s",
        #data / 1048576, cost)
    S.attach_error_time = time_precise()
  end

  return true
end

local function attach_captured_png(png_path, name, empty_error)
  local size = file_size_bytes(png_path)
  if not size or size < 1 then
    os.remove(png_path)
    S.attach_error = empty_error
    S.attach_error_time = time_precise()
    return false
  end
  if size > ATTACH_MAX_BYTES then
    os.remove(png_path)
    S.attach_error = str_format("Image too large (%.1f MB, max %d MB).",
      size / 1048576, ATTACH_MAX_BYTES / 1048576)
    S.attach_error_time = time_precise()
    return false
  end
  if not Attach.aggregate_admitted(size) then
    os.remove(png_path)
    Attach.set_aggregate_error()
    return false
  end
  if native_media_engine_usable() then
    local retained = native_media_preserve_capture(png_path)
    if retained then
      local entry = {
        kind = "image", name = name, media_type = "image/png",
        path = nil, size_bytes = size,
      }
      entry.tokens = estimate_attachment_tokens(entry)
      entry.cost = estimate_attachment_cost(entry.tokens)
      S.attachments[#S.attachments + 1] = entry
      if Attach.begin_native_media(entry, retained, retained) then return true end
      tbl_remove(S.attachments, #S.attachments)
      png_path = retained
    end
  end
  local data = read_file_binary(png_path)
  os.remove(png_path)
  if not data or #data == 0 then
    S.attach_error = empty_error
    S.attach_error_time = time_precise()
    return false
  end
  local entry = {
    kind = "image", name = name, data = data, media_type = "image/png",
    path = nil, size_bytes = #data,
  }
  entry.tokens = estimate_attachment_tokens(entry)
  entry.cost = estimate_attachment_cost(entry.tokens)
  S.attachments[#S.attachments + 1] = entry
  return true
end

Attach.screenshot = function()
  if #S.attachments >= ATTACH_MAX_COUNT then
    S.attach_error = str_format("Maximum %d attachments per message.",
      ATTACH_MAX_COUNT)
    S.attach_error_time = time_precise()
    return false
  end
  local png_path, err = capture_screenshot()
  if not png_path then
    S.attach_error = tostring(err or "Screenshot failed.")
    S.attach_error_time = time_precise()
    return false
  end
  local name = (RA and RA.t and RA.t("attach.name.screenshot", nil,
    "Screenshot")) or "Screenshot"
  return attach_captured_png(png_path, name,
    "Screenshot produced an empty file.")
end

Attach.clipboard = function()
  if #S.attachments >= ATTACH_MAX_COUNT then
    S.attach_error = str_format("Maximum %d attachments per message.",
      ATTACH_MAX_COUNT)
    S.attach_error_time = time_precise()
    return false
  end
  local png_path = get_clipboard_image()
  if not png_path then
    S.attach_error = "No image found in clipboard."
    S.attach_error_time = time_precise()
    return false
  end
  return attach_captured_png(png_path, "Clipboard image",
    "Clipboard image is empty.")
end

end -- attachment system scope

-- =============================================================================
-- System prompt
-- =============================================================================
-- Loaded from System_Prompt.md at startup. {VERSION} is replaced
-- with CFG.VERSION.
--
-- Power-user override: if System_Prompt_Custom.md exists in the
-- same Resources/ folder, it is loaded INSTEAD of the stock prompt. The
-- custom file is not in the update manifest, so it survives updates and
-- is never touched by repair. The stock file may still change across
-- updates; Updater._apply_finish detects that and queues a one-time toast
-- on next launch reminding the user to review the new stock prompt.
local SYSTEM_PROMPT
local SYSTEM_PROMPT_IS_CUSTOM = false
-- Loads the system prompt at the kick-off block (after the bootstrap
-- critical-files check has run) so a missing or token-gutted stock prompt
-- can route into bootstrap recovery instead of returning from the main
-- chunk before recovery has a chance to render. Returns true on success;
-- on failure either sets S.bootstrap_active (stock missing/corrupt, repair
-- can fix it) or shows a message box (custom override is the user's file
-- and bootstrap cannot restore it).
local function load_system_prompt()
  local stock_path  = RA.RESOURCES_DIR .. "System_Prompt.md"
  local custom_path = RA.RESOURCES_DIR .. "System_Prompt_Custom.md"
  local prompt_path = stock_path
  if reaper.file_exists(custom_path) then
    prompt_path = custom_path
    SYSTEM_PROMPT_IS_CUSTOM = true
  end
  local f = io.open(prompt_path, "r")
  if not f then
    if SYSTEM_PROMPT_IS_CUSTOM then
      reaper.ShowMessageBox(
        RA.early_t(
          "Could not load system prompt file:\n" .. prompt_path
          .. "\n\nPlease make sure System_Prompt.md is in the "
          .. "Resources/ subfolder next to ReaAssist.lua.",
          "No se pudo cargar el archivo de instrucciones del sistema:\n" .. prompt_path
          .. "\n\nComprueba que System_Prompt.md esté en la subcarpeta "
          .. "Resources/ junto a ReaAssist.lua."),
        "ReaAssist", 0)
      return false
    end
    S.bootstrap_active = true
    S.bootstrap_missing[#S.bootstrap_missing + 1] =
      "Resources/System_Prompt.md"
    -- Log only; do NOT call Updater._set_failure here. _set_failure
    -- populates update.last_error, which Bootstrap.loop's view selector
    -- reads as "the last repair attempt failed" and routes straight to
    -- render_failed -- skipping the normal recovery prompt that lets
    -- the user click Repair. This is a load-time detection of a
    -- recoverable file (downloading it again will fix it), not a
    -- failed repair, so we leave last_error alone and let the
    -- bootstrap_active + bootstrap_missing entries drive render_prompt.
    Log.line("BOOTSTRAP",
      "system_prompt_load: System_Prompt.md missing; "
      .. "routing to recovery prompt.")
    return false
  end
  local raw = f:read("*a"); f:close()
  -- Strip the HTML comment header (<!-- ... -->) lines so they don't leak
  -- into the prompt sent to the API.
  raw = raw:gsub("<!%-%-.-%-%->\n?", "")
  local sws_required_prompt =
    REQUIRE_SWS_EXTENSION and not SupportExtFlag("optoutsws")
  if sws_required_prompt then
    local sws_rewrite_pattern =
      "%- Extension APIs: avoid SWS %(CF_%*%), js_ReaScriptAPI %(JS_%*%), and other non%-core extension functions unless the user explicitly requests them or the script first checks the function exists %(e%.g%. if reaper%.CF_GetClipboard then %.%.%. end%) and shows a clear error if missing%."
    local sws_rewrite_replacement =
      "- Extension APIs: SWS Extension is available and required in this build. Treat documented SWS APIs (`CF_*`, `BR_*`, `NF_*`, `FNG_*`) as available after requesting `docs:sws` when needed. js_ReaScriptAPI (`JS_*`) and other non-core extension functions remain optional unless the user explicitly requests them or the script first checks the function exists and shows a clear error if missing."
    local sws_rewrite_n
    raw, sws_rewrite_n = raw:gsub(sws_rewrite_pattern,
      sws_rewrite_replacement, 1)
    if sws_rewrite_n == 0 then
      Log.line("PROMPT",
        "system_prompt_load: SWS prompt rewrite anchor not found")
      if not SYSTEM_PROMPT_IS_CUSTOM then
        S.bootstrap_active = true
        S.bootstrap_missing[#S.bootstrap_missing + 1] =
          "Resources/System_Prompt.md (corrupt)"
        Log.line("BOOTSTRAP",
          "system_prompt_load: System_Prompt.md corrupt "
          .. "(missing SWS rewrite anchor); routing to recovery prompt.")
        return false
      end
    end
  end
  SYSTEM_PROMPT = raw:gsub("{VERSION}", CFG.VERSION)
  if sws_required_prompt then
    SYSTEM_PROMPT = SYSTEM_PROMPT .. [[

SWS DOCS ROUTING:
- Before using SWS-only calls, SWS/S&M startup actions, or SWS/S&M menu/action workflows, request <context_needed>docs:sws</context_needed> unless that section is already present in context.
- Prefer native REAPER APIs when they are equally direct; use SWS for clipboard, mouse cursor context, GUID helpers, loudness analysis, SWS notes, FX-chain window helpers, SWS/S&M startup actions, and other APIs/workflows documented in docs:sws.
]]
  end
  -- Tamper guard for the SHIPPED prompt only: if the stock file has been
  -- gutted, partially truncated, or replaced with junk, route into bootstrap
  -- recovery so repair can restore it. Custom overrides bypass this check;
  -- power users may legitimately rewrite the branding in their own copy.
  --
  -- We require multiple structural anchors (not just the product token) so
  -- a partial corruption that still contains "ReaAssist" somewhere in the
  -- file passes through and produces one bad chat session before the SHA
  -- repair check catches it on the next launch. The anchors below are the
  -- prompt's load-bearing section headers; if any one is missing, the file
  -- is structurally broken and unsafe to feed to a model.
  if not SYSTEM_PROMPT_IS_CUSTOM then
    local required_anchors = {
      CFG._PRODUCT,
      "CORE BEHAVIOR:",
      "CONTEXT BUCKETS",
      "API REF REQUIREMENT",
      "PROMPT BUNDLES",
    }
    for _, anchor in ipairs(required_anchors) do
      if not SYSTEM_PROMPT:find(anchor, 1, true) then
        S.bootstrap_active = true
        S.bootstrap_missing[#S.bootstrap_missing + 1] =
          "Resources/System_Prompt.md (corrupt)"
        -- Log only; see the parallel comment on the missing-file branch
        -- above for why we do NOT call Updater._set_failure here. The
        -- specific anchor is preserved in the debug log for triage.
        Log.line("BOOTSTRAP", string.format(
          "system_prompt_load: System_Prompt.md corrupt "
          .. "(missing anchor %q); routing to recovery prompt.",
          anchor))
        return false
      end
    end
  end
  -- Log custom-prompt usage so support can rule it in/out when triaging
  -- "weird model output" reports. No-op if debug logging is disabled.
  if SYSTEM_PROMPT_IS_CUSTOM then
    Log.line("PROMPT",
      "Using System_Prompt_Custom.md (override active)")
  end
  return true
end

-- CTX is a plain global (cross-file shared state; its `= {}` initializer
-- runs later in this file). Code.auto_save_jsfx invalidates the installed-FX
-- cache after saving a new plugin by touching CTX, which is harmless before
-- the initializer because the touch happens inside a function body, not at
-- load time.

Code = {}

-- Forward declaration so Code.ensure_preferred_from_chains can call
-- _is_fabfilter_ident after RA.load_context pulls the Context.lua binding back
-- into this chunk-local slot. Without this forward decl, Lua's parser treats
-- the call site as a global lookup and the call resolves to nil at runtime.
local _is_fabfilter_ident

-- =============================================================================
-- Utility: Code.safe_write / Code.quiet_write
-- =============================================================================
-- Writes content to a file path with crash- and failure-safe semantics:
--   1. Write to <path>.tmp.<instance>, checking both f:write and f:close
--      for nil+err
--      returns (not just thrown errors -- short writes/disk full/permission
--      failures come back that way in Lua, not as exceptions).
--   2. Rename any existing <path> to <path>.bak.<instance> so the original
--      is preserved.
--   3. Rename <path>.tmp.<instance> -> <path>. If that fails, restore from .bak.
--   4. On success, remove the instance-scoped .bak.
-- The original file is never destroyed unless the replacement is in place.
-- Code.safe_write returns true on success, and shows a message box and returns
-- false on failure. Code.quiet_write performs the identical write and returns
-- false plus the error text instead of showing anything, for a write whose
-- failure the caller absorbs on its own. The quiet form exists for an OPTIONAL
-- dispatch, one whose caller runs the original candidate when nothing was
-- sent: a request that was never required must not put a modal file error in
-- front of the user. Every other write keeps the modal.
function Code._write_atomically(path, content, quiet)
  local function report(key, fields, fallback)
    local message = RA.t(key, fields, fallback)
    if quiet ~= true then
      reaper.ShowMessageBox(message,
        RA.t("file_error.title", nil, "ReaAssist - File Error"), 0)
    end
    return false, message
  end
  local atomic_suffix = (RA and RA.instance_file_suffix)
    and ("." .. RA.instance_file_suffix()) or ""
  local tmp_path = path .. ".tmp" .. atomic_suffix
  local bak_path = path .. ".bak" .. atomic_suffix
  -- The deploy lock, read immediately before the open. This one returns
  -- without the modal: rule 4 of the deploy lock contract says the refusal
  -- must not be an error the user has to dismiss, and the notice path has
  -- already said the one sentence that explains it.
  local deploy_block = DeployLock and DeployLock.blocks
    and DeployLock.blocks(path) or nil
  if deploy_block then return false, deploy_block end
  local f, err = io.open(tmp_path, "wb")
  if not f then
    return report("file_error.write", {
      path = tmp_path,
      error = tostring(err),
    }, "Could not write file:\n" .. tmp_path .. "\n\n" .. tostring(err))
  end
  local w_ok, w_err = pcall(function()
    local ok, perr = f:write(content)
    if not ok then error(perr or "write returned nil", 0) end
  end)
  local c_ok, c_err = pcall(function()
    local ok, perr = f:close()
    if not ok then error(perr or "close returned nil", 0) end
  end)
  if not w_ok or not c_ok then
    os.remove(tmp_path)
    return report("file_error.write_temp_failed", {
      path = tmp_path,
      error = tostring(w_err or c_err),
    }, "Failed writing temp file:\n" .. tmp_path .. "\n\n"
      .. tostring(w_err or c_err))
  end
  -- Preserve the original until the new file is definitely in place. Windows
  -- os.rename fails when the destination exists, so move the original out of
  -- the way first. os.rename returns nil when the source does not exist (a
  -- fresh write); had_original tracks that so restoration is only attempted
  -- when there was actually something to restore.
  os.remove(bak_path)
  local had_original = os.rename(path, bak_path)
  local ok_r, ren_err = os.rename(tmp_path, path)
  if not ok_r then
    if had_original then os.rename(bak_path, path) end
    os.remove(tmp_path)
    return report("file_error.finalize", {
      path = path,
      error = tostring(ren_err),
    }, "Could not finalize file:\n" .. path .. "\n\n" .. tostring(ren_err))
  end
  os.remove(bak_path)
  return true
end

-- The modal form. The single return value is the contract every existing
-- caller reads, several of them as `== true`.
function Code.safe_write(path, content)
  return (Code._write_atomically(path, content, false))
end

-- The silent form, for an optional dispatch. Returns false plus the error
-- text so the caller can log it under its own tag.
function Code.quiet_write(path, content)
  return Code._write_atomically(path, content, true)
end

-- =============================================================================
-- Utility: Code.derive_filename
-- =============================================================================
-- Suggests a .lua filename from code content without an API call.
-- Strategy (in priority order):
--   1. Last useful Undo_EndBlock label:
--      "ReaAssist: Create 20 tracks" -> "Create 20 tracks.lua"
--   2. First useful comment: "-- My Script" -> "My Script.lua"
--   3. The source request, when the response message provides it.
--   4. First function name: "local function do_thing()" -> "do_thing.lua"
--   5. Fallback: "reaassist_script.lua"
-- Result is safe for all OSes: filesystem-unsafe chars stripped,
-- spaces preserved, length capped at 60 chars.
-- Shared filename sanitizer: strip filesystem-unsafe chars, collapse whitespace,
-- cap at 60 chars. Returns cleaned string (caller appends extension).
local function sanitize_filename(s, fallback)
  s = s:gsub('[<>:"/\\|%?%*]', ""):gsub("%s+", " "):gsub("^ +", ""):gsub(" +$", "")
  -- Strip trailing dots/spaces (Windows truncates them silently, breaking
  -- subsequent open-by-name lookups).
  s = s:gsub("[%. ]+$", "")
  if #s > 60 then s = s:sub(1, 60):gsub("[%. ]+$", "") end
  if s == "" then s = fallback end
  -- Reject Windows reserved device names. Match the stem before any extension
  -- the caller will append, so "CON" alone is enough to trigger.
  if RA.is_windows_reserved_name(s) then s = s .. "_" end
  return s
end

function Code.derive_filename(code, request_text)
  code = tostring(code or "")
  local function generic_label(text)
    local lower = tostring(text or ""):lower()
      :gsub("^reaassist:%s*", ""):match("^%s*(.-)%s*$") or ""
    return lower == "" or lower == "reaassist" or lower == "script"
      or lower == "action" or lower == "protected plug-in control action"
      or lower == "protected plugin control action"
      or lower == "reaassist protected plug-in control action"
      or lower == "reaassist protected plugin control action"
  end

  local function failure_label(text)
    local lower = tostring(text or ""):lower()
      :gsub("^reaassist:%s*", ""):match("^%s*(.-)%s*$") or ""
    return lower:match("^fail%w*%f[%W]") ~= nil
      or lower:match("^error%f[%W]") ~= nil
      or lower:match("^could not%f[%W]") ~= nil
      or lower:match("^unable to%f[%W]") ~= nil
      or lower:match("^cancel?l?ed%f[%W]") ~= nil
      or lower:match("^invalid%f[%W]") ~= nil
      or lower:match("^missing%f[%W]") ~= nil
  end

  -- 1. Prefer the last usable Undo_EndBlock label. Generated scripts often
  --    close an early failure branch before the final successful action label.
  local undo_label = nil
  for _, label in code:gmatch(
      "Undo_EndBlock%s*%(%s*([\"'])(.-)%1%s*,") do
    if not generic_label(label) and not failure_label(label) then
      undo_label = label
    end
  end
  if undo_label then
    undo_label = undo_label:gsub("^ReaAssist:%s*", "")
    return sanitize_filename(undo_label, "reaassist_script") .. ".lua"
  end

  -- 2. First useful comment.
  local function internal_comment(text)
    local lower = tostring(text or ""):lower()
    lower = lower:gsub("^%s+", ""):gsub("%s+$", "")
    return lower:match("^helper:") ~= nil
      or lower:find("plugin_ref", 1, true) ~= nil
      or lower:find("protected plug%-in control", 1, false) ~= nil
      or lower:find("self%-contained", 1, false) ~= nil
      or lower:find("macro contract", 1, true) ~= nil
      or lower:find("runtime source", 1, true) ~= nil
      or lower:find("binary search", 1, true) ~= nil
      or lower:match("^band%s*%d") ~= nil
  end
  for raw in (tostring(code or ""):gsub("\r\n", "\n"):gsub("\r", "\n")
      .. "\n"):gmatch("([^\n]*)\n") do
    local comment = raw:match("^%s*%-%-+%s*(.-)%s*$")
    if comment and comment ~= "" and not comment:match("^!")
        and not internal_comment(comment) then
      return sanitize_filename(comment, "reaassist_script") .. ".lua"
    end
  end

  -- 3. The source request. Remove conversational filler so numeric settings
  -- near the end are less likely to be lost to the filename length cap.
  local request_name = tostring(request_text or "")
    :gsub("[%c]+", " "):match("^%s*(.-)%s*$") or ""
  if request_name ~= "" then
    request_name = request_name
      :gsub("^[Pp]lease%s+", "")
      :gsub("^[Cc]an you%s+", "")
      :gsub("^[Cc]ould you%s+", "")
      :gsub("^[Ww]ould you%s+", "")
      :gsub("%f[%a][Tt]he%f[%A]", "")
      :gsub("%f[%a][Mm]y%f[%A]", "")
      :gsub("%f[%a][Aa]n?%f[%A]", "")
      :gsub("%f[%a][Aa]nd%f[%A]", "")
      :gsub("%f[%a][Tt]o%f[%A]", "")
      :gsub("%f[%a][Oo]f%f[%A]", "")
      :gsub("%s+", " "):match("^%s*(.-)%s*$") or ""
    if request_name ~= "" then
      return sanitize_filename(request_name, "reaassist_script") .. ".lua"
    end
  end

  -- 4. First function name (covers local function and bare function forms).
  local fn_name = code:match("local%s+function%s+([%w_]+)%s*%(")
               or code:match("^function%s+([%w_]+)%s*%(")
  if fn_name then return sanitize_filename(fn_name, "reaassist_script") .. ".lua" end

  -- 5. Fallback.
  return "reaassist_script.lua"
end

-- =============================================================================
-- Utility: Code.derive_filename_jsfx
-- =============================================================================
-- Suggests a filename from JSFX code content.
-- Uses the desc: line if present, otherwise falls back to a generic name.
function Code.derive_filename_jsfx(code)
  local desc = code:match("^%s*desc:%s*(.-)%s*[\r\n]")
  if desc and desc ~= "" then return sanitize_filename(desc, "reaassist_effect") .. ".jsfx" end
  return "reaassist_effect.jsfx"
end

-- =============================================================================
-- Code.inject_output_ceiling -- runaway-feedback containment layer
-- =============================================================================
-- Defense-in-depth on top of the JSFX validator. The validator catches every
-- known runaway pattern at static-analysis time; this injection adds a hard
-- post-DSP cap on spl0..spl7 in case a future evasion slips through. Cap is
-- user-disableable via the injected slider (drag to 40 = bypass).
--
-- See implementation contract in this conversation's design v2.1-final
-- (gitignored notes). Key points enforced here:
--
--   * JSFX side uses `options:gmem=ReaAssist_Ceiling` (header directive),
--     NOT `gmem_attach()` (which is Lua-side only). Host script calls
--     `reaper.gmem_attach("ReaAssist_Ceiling")` to read the same namespace.
--
--   * Section-aware injection only. Append-only, no rewrites.
--     - Header: insert slider declaration; merge `gmem=ReaAssist_Ceiling`
--       into existing options: line OR insert a new options: line.
--     - @init: append init block (or create section if absent).
--     - @slider: append recompute block (or create section if absent).
--     - @sample: append clamp+engagement block.
--
--   * Bail conditions skip injection (ship original, log warning):
--       - 0 or 2+ @sample sections
--       - source contains `import` directive
--       - source uses `_ra_` identifier prefix already
--       - source already has `options:gmem=...` (any value)
--       - source uses `gmem[...]` anywhere (would silently rebind to our
--         private namespace and break intentional cross-plugin gmem)
--       - all slider slots 1..256 are used
--       - ExtState slot allocator wedged or exhausted
--
--   * Per-FILE alert/mute identity (not per-instance). Multiple track
--     instances of the same saved JSFX file share one gmem block. Documented
--     v1 trade-off; per-instance identity is v2 work.
--
--   * gmem layout (per-file block at base B, stride 8):
--       B+0: engagement flag (set by JSFX, cleared by host on poll)
--       B+1: cumulative engagement-sample count (lifetime)
--       B+2: time_precise() of most recent engagement
--       B+3: running consecutive-engagement count (for sustained-trip mute)
--       B+4: muted latch (set by JSFX after sustained trip; cleared by host
--            on user reset, or by JSFX when slider goes to 40 = off)
--       B+5..B+7: reserved
--     Global: gmem[0] = schema version, gmem[1] = "any engagement" sentinel.
--
--   * Allocation is monotonic via State.json (`ceiling_next_base`). Starts at
--     8, increments by 8 per save. Slot 0..7 reserved for global metadata.
--     No reuse in v1 (heartbeat/lease scheme deferred). Re-saving the same
--     LLM-generated source ultimately writes a NEW file with a numeric
--     suffix (slot differs => content differs => existing dedup misses).
--     Acceptable v1 trade-off; can add original-content dedup later.
do

local CEILING_NS          = "ReaAssist_Ceiling"
local CEILING_NEXT_BASE   = "ceiling_next_base"
local CEILING_SLOTS_KEY   = "ceiling_slots"
local CEILING_BASE_START  = 8
local CEILING_STRIDE      = 8
local CEILING_BASE_LIMIT  = 8000000  -- well under gmem's 8M cap; defensive
local CEILING_DB_DEFAULT  = 20       -- dBFS, slider default
local CEILING_DB_OFF      = 40       -- slider value at which clamp/mute bypass
local SLIDER_SLOT_MAX     = 256

-- gmem layout offsets (within a slot's 8-deep block; matches the JSFX
-- injection's writes -- keep these in lockstep with render_injection_blocks).
local CEILING_GMEM_ENGFLAG  = 0   -- per-slot engagement flag (set by JSFX)
local CEILING_GMEM_ENGCOUNT = 1   -- per-slot lifetime engagement-sample count
local CEILING_GMEM_MUTE     = 4   -- per-slot mute latch (0/1)
local CEILING_GMEM_GLOBAL_ENG = 1 -- gmem[1] -- global "any-instance engagement"
                                  -- sentinel; cheap-poll fast path. Slot 1 is
                                  -- inside the 0..7 reserved global block, NOT
                                  -- inside a per-slot allocation (allocations
                                  -- start at slot 8).

-- Public so host poll can reference symbolic names.
Code.CEILING_NS              = CEILING_NS
Code.CEILING_GMEM_MUTE       = CEILING_GMEM_MUTE
Code.CEILING_GMEM_ENGFLAG    = CEILING_GMEM_ENGFLAG
Code.CEILING_GMEM_ENGCOUNT   = CEILING_GMEM_ENGCOUNT
Code.CEILING_GMEM_GLOBAL_ENG = CEILING_GMEM_GLOBAL_ENG

-- Replace comment bodies and string literal contents with spaces so token
-- scans (`gmem[`, `import`, `_ra_`, `options:gmem=`) don't match inside
-- strings or comments. Approximate but conservative -- false positives
-- on bail-condition checks just make us bail more often, which is safe.
local function scrub_jsfx(src)
  local out = src:gsub("/%*(.-)%*/", function(body)
    return "/*" .. body:gsub("[^\n\r]", " ") .. "*/"
  end)
  out = out:gsub("//[^\r\n]*", function(s) return string.rep(" ", #s) end)
  out = out:gsub('"([^"\r\n]*)"', function(body)
    return '"' .. string.rep(" ", #body) .. '"'
  end)
  out = out:gsub("'([^'\r\n]*)'", function(body)
    return "'" .. string.rep(" ", #body) .. "'"
  end)
  return out
end

-- Split a string into lines without terminators. Trailing newline produces
-- no empty final element.
local function split_lines(s)
  local out = {}
  for line in (s .. "\n"):gmatch("([^\r\n]*)\r?\n") do
    out[#out + 1] = line
  end
  if out[#out] == "" then out[#out] = nil end
  return out
end

-- Allocate a gmem base for this save. State-backed, monotonic. Returns
-- the base (>=8, multiple of 8) or nil + reason on failure.
local function allocate_ceiling_slot()
  if Store and Store.reserve_ceiling_base then
    return Store.reserve_ceiling_base(
      CEILING_BASE_START, CEILING_STRIDE, CEILING_BASE_LIMIT)
  end
  local cur_str = reaper.GetExtState(CFG.EXT_NS, CEILING_NEXT_BASE)
  local cur = tonumber(cur_str)
  if not cur or cur < CEILING_BASE_START then cur = CEILING_BASE_START end
  if cur >= CEILING_BASE_LIMIT then
    return nil, "ExtState slot allocator exhausted"
  end
  -- Persist next base BEFORE returning so a crash mid-save still consumes
  -- the slot rather than handing the same slot to the next call.
  reaper.SetExtState(CFG.EXT_NS, CEILING_NEXT_BASE,
                     tostring(cur + CEILING_STRIDE), true)
  return cur
end

-- ============================================================================
-- Slot metadata tracking
-- ============================================================================
-- Each successful injection records the slot it allocated alongside the
-- saved file path, the JSFX `desc:` name, and the allocation timestamp.
-- The host's defer poll loop iterates this list to know which gmem slots
-- to read when checking for engaged/muted JSFX.
--
-- Storage: State.json `output_ceiling.slots` value, with legacy ExtState
-- fallback for older installs. Allocation is monotonic so the array grows
-- but never reuses slots.

-- Pull the recorded slot list. Empty array if not yet written.
function Code.ceiling_get_slots()
  if Store and Store.ceiling_slots then return Store.ceiling_slots() end
  local raw = reaper.GetExtState(CFG.EXT_NS, CEILING_SLOTS_KEY)
  if not raw or raw == "" then return {} end
  local ok, decoded = pcall(JSON.decode, raw)
  if not ok or type(decoded) ~= "table" then return {} end
  return decoded
end

-- Append a new slot entry to the list. info comes from
-- Code.inject_output_ceiling; saved_path is the path Code.auto_save_jsfx
-- wrote (may be nil if the JSFX was not saved -- e.g. JSFX-only response
-- without a Lua companion -- in which case we skip the record entirely
-- since there's no on-disk file to diagnose later).
function Code.ceiling_record_slot(info, saved_path, desc)
  if not info or not info.slot_base or not saved_path then return end
  local list = Code.ceiling_get_slots()
  list[#list + 1] = {
    slot      = info.slot_base,
    file      = saved_path,
    desc      = desc or "",
    alloc_ts  = os.time(),
  }
  if Store and Store.save_ceiling_slots then
    Store.save_ceiling_slots(list)
  else
    local enc = JSON.encode(list)
    if enc then reaper.SetExtState(CFG.EXT_NS, CEILING_SLOTS_KEY, enc, true) end
  end
end

-- Forget the slot whose recorded file is `path`. Called when the user
-- Reset-All-then-clears or when a saved file is detected missing during a
-- poll (orphaned slot). Allocation never reuses the slot index, so this
-- only prunes the metadata; gmem state for the slot stays whatever the
-- last write left it as.
function Code.ceiling_forget_slot_for_path(path)
  if not path or path == "" then return end
  local list = Code.ceiling_get_slots()
  local kept = {}
  for _, e in ipairs(list) do
    if e.file ~= path then kept[#kept + 1] = e end
  end
  if #kept ~= #list then
    if Store and Store.save_ceiling_slots then
      Store.save_ceiling_slots(kept)
    else
      reaper.SetExtState(CFG.EXT_NS, CEILING_SLOTS_KEY, JSON.encode(kept), true)
    end
  end
end

-- Bulk garbage-collect slots in ExtState. Drops any entry whose:
--   (a) recorded file is missing from disk, OR
--   (b) file exists but no longer contains `_ra_slot = <N>;` matching
--       the recorded slot (file was overwritten or re-injected with
--       a different slot allocation).
--
-- Caller MUST have already called `reaper.gmem_attach(CEILING_NS)`
-- so the per-slot mute mirror clears land on the right region. In
-- practice the only caller is the poll loop, which attaches before
-- doing anything else.
--
-- Scans each file in chunks for the `_ra_slot` marker. The injector may
-- append @init after a long JSFX header, so a fixed header read can falsely
-- prune live slots. Allocation is monotonic so pruned slot indices are
-- never reused; this just trims the metadata + gmem cruft.
--
-- Returns the number of slots pruned (0 if everything still valid).
function Code.ceiling_gc_slots()
  local list = Code.ceiling_get_slots()
  if #list == 0 then return 0 end
  local kept = {}
  local pruned = 0
  for _, e in ipairs(list) do
    local keep = false
    if e.file and e.file ~= "" and e.slot then
      local f = io.open(e.file, "rb")
      if f then
        -- Match `_ra_slot = N;` (whitespace tolerant). The injector
        -- emits exactly this in the injected @init block.
        local pat = "_ra_slot%s*=%s*" .. tostring(e.slot) .. "%s*;"
        local scan = ""
        while true do
          local chunk = f:read(32768)
          if not chunk or chunk == "" then break end
          scan = scan .. chunk
          if scan:find(pat) then
            keep = true
            break
          end
          if #scan > 128 then scan = scan:sub(-128) end
        end
        f:close()
      end
    end
    if keep then
      kept[#kept + 1] = e
    else
      pruned = pruned + 1
      -- Zero the mute mirror so an orphaned `1` doesn't pollute any
      -- future allocation that happens to land on a neighbour slot.
      -- Best-effort: if gmem_write isn't available, the metadata
      -- prune still happens.
      if reaper.gmem_write then
        reaper.gmem_write(e.slot + CEILING_GMEM_MUTE, 0)
      end
    end
  end
  if pruned > 0 then
    if Store and Store.save_ceiling_slots then
      Store.save_ceiling_slots(kept)
    else
      reaper.SetExtState(CFG.EXT_NS, CEILING_SLOTS_KEY,
        JSON.encode(kept), true)
    end
    if Log and Log.line then
      Log.line("CEILING-GC",
        ("pruned %d stale slot(s); kept %d"):format(pruned, #kept))
    end
  end
  return pruned
end

-- Host-side mute clear: write gmem[slot+4] = 0. Caller must have
-- previously called `reaper.gmem_attach(CEILING_NS)`.
function Code.ceiling_clear_mute(slot)
  if not slot or slot < CEILING_BASE_START then return end
  reaper.gmem_write(slot + CEILING_GMEM_MUTE, 0)
end

-- Render the three injection blocks parameterised on slot base + slider id.
--
-- Slider semantics (UX simplification, 2026-04-29 follow-up):
-- The slider value is ALWAYS the ceiling level in dBFS. There is no magic
-- "off" position. At the slider's max (40 dBFS = 100x linear), the ceiling
-- is so permissive that real audio in normal use never reaches it -- so
-- 40 is "effectively off" without needing a special bypass code path.
-- This avoids the earlier "is 40 really off, or just at +40 dBFS?" UX
-- confusion: now it's unambiguously "the ceiling is at this dBFS value,
-- always."
--
-- The mute latch is cleared on ANY slider change. Touching the control =
-- explicit user acknowledgement that they've seen something happened and
-- want to continue. Simpler than a dedicated reset position on the slider.
--
-- We avoid a `1e30`-style "infinity" literal here because REAPER's JSFX
-- parser rejected it in some contexts (observed: bare `1e30` inside a
-- ternary RHS produced `@init: syntax error`). Always-compute via pow()
-- is defensible regardless of the literal-parsing rules.
local function render_injection_blocks(slot, slider_n)
  -- @init resets local mute state AND clears the gmem mirror slots for
  -- this allocation. Without the gmem clear, gmem state from a previous
  -- session (gmem persists in REAPER project files) could lie to the
  -- host's poll loop on reopen -- the JSFX's _ra_muted is fresh-zero but
  -- gmem[slot+4] could still carry an old `1` from a prior run.
  local INIT_INJ = ([[
// --- ReaAssist output ceiling (auto-injected; do not edit) ---
_ra_slot = %d;
_ra_mute_samples = srate * 0.05;
_ra_sus = 0;
_ra_muted = 0;
_ra_prev_slider = slider%d;
_ra_ceil_lin = pow(10, slider%d/20);
gmem[_ra_slot+0] = 0;
gmem[_ra_slot+1] = 0;
gmem[_ra_slot+4] = 0;
// ----------------------------------------------------------]])
    :format(slot, slider_n, slider_n)

  -- @slider recompute. Mute state cleared via local _ra_muted on any
  -- slider change. gmem[slot+4] is mirrored so a slider-driven reset
  -- stays consistent with the host's view (host poll reads gmem).
  local SLIDER_INJ = ([[
// --- ReaAssist output ceiling recompute (auto-injected) ---
_ra_ceil_lin = pow(10, slider%d/20);
_ra_changed = slider%d != _ra_prev_slider ? 1 : 0;
_ra_muted = _ra_changed ? 0 : _ra_muted;
_ra_sus = _ra_changed ? 0 : _ra_sus;
_ra_prev_slider = slider%d;
gmem[_ra_slot+4] = _ra_muted;
// ----------------------------------------------------------]])
    :format(slider_n, slider_n, slider_n)

  -- NOTE: a previous version injected an @block section to clear the mute
  -- latch on any transport stop edge. Both the && form and a nested-ternary
  -- form caused the per-sample mute logic to stop working entirely, even
  -- though the inner clear should never have fired during sustained
  -- playback. The mechanism remains unidentified -- possibly a section-
  -- ordering quirk specific to this user's REAPER build.
  --
  -- Stop-edge auto-clear is therefore deferred to the host-side path: once
  -- the gmem poll loop lands (next §9 step), the host can write
  -- gmem[B+4] = 0 from Lua when it observes a transport stop, achieving
  -- the same UX without injecting @block code into the JSFX.
  --
  -- Until then, the user can clear a latched mute by moving the ceiling
  -- slider (the @slider injection clears on any slider change). Returning
  -- nil here makes the create-or-append logic in inject_output_ceiling
  -- below skip @block entirely.
  local BLOCK_INJ = nil

  -- @sample: per-channel ceiling clamp + sustained-trip mute.
  --
  -- This block is structurally identical to a standalone test JSFX that
  -- the user verified WORKS (the same logic, in plain globals, not gmem,
  -- with single-line OR-chains). The mute decision uses local _ra_muted
  -- as the source of truth; gmem writes are pure host-visibility mirrors
  -- (the `@slider` inj also writes through to gmem on user reset).
  -- Slot layout matches the host-side poll constants in
  -- `Net.ceiling_*` -- keep in lockstep.
  --   gmem[_ra_slot+0]: engagement flag (set on any engaged sample;
  --                     host clears after consuming the alert)
  --   gmem[_ra_slot+1]: cumulative engagement-sample count (lifetime)
  --   gmem[_ra_slot+4]: mute mirror (latches when _ra_muted goes 1)
  --   gmem[1]:          global "any-instance engagement" sentinel,
  --                     allows host's defer poll to skip the per-slot
  --                     scan when nothing has fired anywhere
  --
  -- The host-side reset (Reset Mute button in the popup) writes
  -- gmem[slot+4] = 0 directly. The injection's @slider section also
  -- mirrors _ra_muted -> gmem[slot+4] every slider change so a slider
  -- nudge from the JSFX side stays consistent with gmem.
  local SAMPLE_INJ = [[
// --- ReaAssist output ceiling (auto-injected; do not edit) ---
_ra_muted ? (
  spl0 = 0; spl1 = 0; spl2 = 0; spl3 = 0;
  spl4 = 0; spl5 = 0; spl6 = 0; spl7 = 0;
) : (
  _ra_eng = (abs(spl0) > _ra_ceil_lin) || (abs(spl1) > _ra_ceil_lin) || (abs(spl2) > _ra_ceil_lin) || (abs(spl3) > _ra_ceil_lin) || (abs(spl4) > _ra_ceil_lin) || (abs(spl5) > _ra_ceil_lin) || (abs(spl6) > _ra_ceil_lin) || (abs(spl7) > _ra_ceil_lin);
  spl0 = abs(spl0) > _ra_ceil_lin ? max(-_ra_ceil_lin, min(_ra_ceil_lin, spl0)) : spl0;
  spl1 = abs(spl1) > _ra_ceil_lin ? max(-_ra_ceil_lin, min(_ra_ceil_lin, spl1)) : spl1;
  spl2 = abs(spl2) > _ra_ceil_lin ? max(-_ra_ceil_lin, min(_ra_ceil_lin, spl2)) : spl2;
  spl3 = abs(spl3) > _ra_ceil_lin ? max(-_ra_ceil_lin, min(_ra_ceil_lin, spl3)) : spl3;
  spl4 = abs(spl4) > _ra_ceil_lin ? max(-_ra_ceil_lin, min(_ra_ceil_lin, spl4)) : spl4;
  spl5 = abs(spl5) > _ra_ceil_lin ? max(-_ra_ceil_lin, min(_ra_ceil_lin, spl5)) : spl5;
  spl6 = abs(spl6) > _ra_ceil_lin ? max(-_ra_ceil_lin, min(_ra_ceil_lin, spl6)) : spl6;
  spl7 = abs(spl7) > _ra_ceil_lin ? max(-_ra_ceil_lin, min(_ra_ceil_lin, spl7)) : spl7;
  _ra_sus = _ra_eng ? _ra_sus + 1 : max(0, _ra_sus - 1);
  _ra_muted = _ra_sus >= _ra_mute_samples ? 1 : _ra_muted;
  // Host-visibility mirrors. Mute logic above already used the local
  // _ra_muted for the per-sample decision; these writes just expose the
  // state to the Lua-side host poll loop.
  gmem[_ra_slot+0] = _ra_eng ? 1 : gmem[_ra_slot+0];
  gmem[_ra_slot+1] = _ra_eng ? gmem[_ra_slot+1] + 1 : gmem[_ra_slot+1];
  gmem[_ra_slot+4] = _ra_muted;
  gmem[1] = _ra_eng ? 1 : gmem[1];
);
// ----------------------------------------------------------]]

  return INIT_INJ, SLIDER_INJ, BLOCK_INJ, SAMPLE_INJ
end

-- Main entry point. Returns (injected_src, info_table) on success, or
-- (nil, skip_reason_string) on bail. Caller is responsible for shipping
-- the original source on bail.
function Code.inject_output_ceiling(src)
  if type(src) ~= "string" or src == "" then
    return nil, "empty source"
  end

  -- Idempotency: if the source already has our injection markers, ship it
  -- back unmodified. Lets the response-handler path inject for the chat
  -- display AND lets auto_save_jsfx call inject again (as a defense) without
  -- double-injecting or burning a second slot allocation.
  if src:find("// --- ReaAssist output ceiling", 1, true) then
    return nil, "already injected"
  end

  -- Split into lines (preserve content; we'll rejoin with \n on output).
  local lines = split_lines(src)
  if #lines == 0 then return nil, "empty source" end

  -- Locate section markers (`@<word>` at column 0).
  local sections = {}        -- ordered list: { name, marker_line }
  local sections_by_name = {}
  for i, line in ipairs(lines) do
    local kw = line:match("^@(%w+)")
    if kw then
      local entry = { name = kw, marker_line = i }
      sections[#sections + 1] = entry
      sections_by_name[kw] = sections_by_name[kw] or {}
      table.insert(sections_by_name[kw], entry)
    end
  end

  -- Compute body ranges: section i's body is lines [marker_line+1 .. next_marker_line-1].
  for i, sec in ipairs(sections) do
    sec.body_start = sec.marker_line + 1
    sec.body_end = (i < #sections) and (sections[i + 1].marker_line - 1) or #lines
  end
  local header_end = (#sections > 0) and (sections[1].marker_line - 1) or #lines

  -- Bail: must have exactly one @sample.
  local sample_entries = sections_by_name.sample
  if not sample_entries then return nil, "no @sample section" end
  if #sample_entries > 1 then return nil, "multiple @sample sections" end

  -- Bail: forbidden tokens in scrubbed source.
  local scrubbed = scrub_jsfx(src)
  if scrubbed:match("[^%w_]import%s") or scrubbed:match("^import%s") then
    return nil, "import directive present"
  end
  if scrubbed:match("[^%w_]_ra_") or scrubbed:match("^_ra_") then
    return nil, "source uses _ra_ identifier prefix"
  end
  if scrubbed:match("options:[^\r\n]*gmem%s*=") then
    return nil, "existing options:gmem= directive"
  end
  if scrubbed:match("gmem%s*%[") then
    return nil, "source already uses gmem[]"
  end

  -- Pick a free slider slot. Also bail if the LLM emitted any slider whose
  -- name suggests it's already trying to be an output ceiling/limit/cap --
  -- shipping a duplicate would put two same-purpose sliders in the UI.
  -- The Prompts.md OUTPUT STAGE rule forbids the LLM from doing this; this
  -- bail is the runtime defense if the rule is violated.
  local used_sliders = {}
  for _, line in ipairs(lines) do
    local n, name = line:match("^slider(%d+):[^>]*>(.*)$")
    if n then
      used_sliders[tonumber(n)] = true
      -- Match patterns like "Safety Output Ceiling", "Output Ceiling",
      -- "Output Limiter", "Master Out", "Final Gain". Lowercased for
      -- case-insensitive comparison. Conservative -- false positives just
      -- skip the injection, which is safer than colliding with a real
      -- output-control slider the LLM legitimately added on user request.
      local lname = (name or ""):lower()
      if lname:find("output ceiling", 1, true)
         or lname:find("output limit", 1, true)
         or lname:find("output cap", 1, true)
         or lname:find("safety ceiling", 1, true)
         or (lname:find("safety", 1, true) and lname:find("output", 1, true)) then
        return nil, "source already declares an output-ceiling slider: \""
          .. (name or "") .. "\""
      end
    end
  end
  local slider_n
  for i = 1, SLIDER_SLOT_MAX do
    if not used_sliders[i] then slider_n = i; break end
  end
  if not slider_n then
    return nil, "all slider slots 1.." .. SLIDER_SLOT_MAX .. " used"
  end

  -- Allocate gmem slot. Persists ExtState before any source mutation; safe
  -- to reach this point only after ALL bail conditions cleared.
  local slot, alloc_err = allocate_ceiling_slot()
  if not slot then return nil, alloc_err end

  -- Locate or merge the header `options:` line.
  local options_line_idx
  for i = 1, header_end do
    if lines[i]:match("^options:") then options_line_idx = i; break end
  end
  if options_line_idx then
    -- In-place edit: append " gmem=ReaAssist_Ceiling" (space-separated per
    -- JSFX options syntax; not comma).
    lines[options_line_idx] = lines[options_line_idx] .. " gmem=" .. CEILING_NS
  end

  -- Build the injection plan. Each entry: { after_line = N, lines = {...} }.
  -- Apply by walking the original line array once and inserting AFTER each
  -- target line. Multiple entries with the same after_line are concatenated
  -- in plan order.
  local plan = {}
  local function add_after(line_no, content_lines)
    plan[line_no] = plan[line_no] or {}
    for _, l in ipairs(content_lines) do
      plan[line_no][#plan[line_no] + 1] = l
    end
  end

  -- Header: options line (if not merged) + slider declaration. The slider
  -- value is unconditionally the ceiling level in dBFS -- no magic "off"
  -- position. Max value (CEILING_DB_OFF dBFS = high linear gain) is
  -- effectively off because real audio in normal use never reaches it.
  --
  -- Collision protection lives in the bail conditions above (specifically
  -- the "safety/output/ceiling slider already present" check). The bundle
  -- forbids the LLM from emitting any output-control slider; the bail is
  -- the runtime defense if it slips through anyway.
  local slider_line = ("slider%d:%d<0,%d,1>Safety Output Ceiling (dBFS)")
    :format(slider_n, CEILING_DB_DEFAULT, CEILING_DB_OFF)
  local header_block = {}
  if not options_line_idx then
    header_block[#header_block + 1] = "options:gmem=" .. CEILING_NS
  end
  header_block[#header_block + 1] = slider_line
  add_after(header_end, header_block)

  -- Render section blocks.
  local INIT_INJ, SLIDER_INJ, BLOCK_INJ, SAMPLE_INJ =
    render_injection_blocks(slot, slider_n)

  local function find_sec(name)
    return sections_by_name[name] and sections_by_name[name][1] or nil
  end

  -- @init injection.
  local init_sec = find_sec("init")
  local created_init = false
  if init_sec then
    add_after(init_sec.body_end, split_lines(INIT_INJ))
  else
    -- No @init -- create one immediately after our header insertions
    -- (which go after `header_end`). Both go through add_after(header_end).
    -- Plan-order ensures: [options/slider header_block] [@init] [INIT_INJ].
    add_after(header_end, { "@init" })
    add_after(header_end, split_lines(INIT_INJ))
    created_init = true
  end

  -- @slider injection.
  local slider_sec = find_sec("slider")
  local created_slider = false
  if slider_sec then
    add_after(slider_sec.body_end, split_lines(SLIDER_INJ))
  else
    -- Create @slider just before @sample's marker line.
    local sample_sec = find_sec("sample")
    add_after(sample_sec.marker_line - 1, { "@slider" })
    add_after(sample_sec.marker_line - 1, split_lines(SLIDER_INJ))
    created_slider = true
  end

  -- @block injection (transport-edge mute clear). v1: skipped entirely;
  -- BLOCK_INJ is nil. See render_injection_blocks for rationale.
  local created_block = false
  if BLOCK_INJ then
    local block_sec = find_sec("block")
    if block_sec then
      add_after(block_sec.body_end, split_lines(BLOCK_INJ))
    else
      local sample_sec = find_sec("sample")
      add_after(sample_sec.marker_line - 1, { "@block" })
      add_after(sample_sec.marker_line - 1, split_lines(BLOCK_INJ))
      created_block = true
    end
  end

  -- @sample injection (always present per bail check above).
  local sample_sec = find_sec("sample")
  add_after(sample_sec.body_end, split_lines(SAMPLE_INJ))

  -- Walk original lines and apply insertions.
  local out = {}
  -- Insert any `after_line = 0` content first (before line 1).
  if plan[0] then
    for _, l in ipairs(plan[0]) do out[#out + 1] = l end
  end
  for i = 1, #lines do
    out[#out + 1] = lines[i]
    if plan[i] then
      for _, l in ipairs(plan[i]) do out[#out + 1] = l end
    end
  end

  -- desc: line lookup -- caller (host poll, popup, diagnose path) wants
  -- the user-facing name without re-parsing.
  local desc = src:match("^%s*desc:%s*(.-)%s*[\r\n]") or ""

  return table.concat(out, "\n"), {
    slot_base       = slot,
    slider_num      = slider_n,
    merged_options  = options_line_idx ~= nil,
    created_init    = created_init,
    created_slider  = created_slider,
    created_block   = created_block,
    desc            = desc,
  }
end

end  -- close ceiling-injection scope

-- =============================================================================
-- Utility: Code.auto_save_jsfx
-- =============================================================================
-- Silently saves JSFX code to Effects/ReaAssist/<derived_name>.jsfx.
-- Returns the saved path on success, nil on failure.
--
-- Filename is derived from `code` directly. The output-ceiling injection
-- step now runs at chat-display time in Code.inject_output_ceiling, BEFORE
-- this function is called -- so by the time auto_save_jsfx sees `code`, it
-- already contains the injected ceiling slider, options:gmem= line, and
-- @init/@slider/@block/@sample blocks. The desc: line is untouched by
-- injection, so filename derivation produces the same name either way.
--
-- Dedup compares full content. Two saves of the same LLM source allocate
-- different gmem slots at injection time, so re-saving produces a new
-- numeric-suffixed file rather than reusing the existing one. v1 trade-off.
function Code.auto_save_jsfx(code)
  reaper.RecursiveCreateDirectory(JSFX_DIR, 0)
  local base_name = Code.derive_filename_jsfx(code)

  local name = base_name
  local stem = base_name:match("^(.+)%.jsfx$") or base_name
  local dest = JSFX_DIR .. RA.SEP .. name
  -- Check existing files: if one has identical content, return it (no duplicate).
  -- If content differs, skip past it and try the next numeric suffix.
  local n = 1
  local f = io.open(dest, "r")
  while f do
    local existing = f:read("*a")
    f:close()
    if existing == code then
      -- Exact same content already on disk -- reuse it.
      return dest, "ReaAssist/" .. name
    end
    n = n + 1
    name = stem .. "_" .. n .. ".jsfx"
    dest = JSFX_DIR .. RA.SEP .. name
    f = io.open(dest, "r")
  end
  local ok = Code.safe_write(dest, code)
  if ok then
    -- Refresh JSFX list so TrackFX_AddByName can find it immediately.
    if reaper.EnumInstalledFX then
      reaper.EnumInstalledFX(-1)
    end
    -- Invalidate our cached installed-FX list so a follow-up
    -- <context_needed>fx_list:...</context_needed> for the newly saved
    -- plugin actually sees it instead of reporting "not installed".
    CTX._installed_fx_list = nil
    return dest, "ReaAssist/" .. name
  end
  return nil
end

function Code.auto_save_lua(code, request_text)
  code = tostring(code or "")
  if code == "" then return nil end

  local base_name = Code.derive_filename(code, request_text)
  if not base_name:lower():match("%.lua$") then base_name = base_name .. ".lua" end
  reaper.RecursiveCreateDirectory(RA.SCRIPT_SAVE_DIR, 0)

  local name = base_name
  local stem = base_name:match("^(.+)%.lua$") or base_name
  local dest = RA.SCRIPT_SAVE_DIR .. RA.SEP .. name
  local n = 1
  local f = io.open(dest, "r")
  while f do
    f:close()
    n = n + 1
    local suffix = " " .. tostring(n)
    local numbered_stem = stem
    if #numbered_stem + #suffix > 60 then
      numbered_stem = numbered_stem:sub(1, 60 - #suffix)
        :gsub("[%. ]+$", "")
      if numbered_stem == "" then numbered_stem = "reaassist_script" end
    end
    name = numbered_stem .. suffix .. ".lua"
    dest = RA.SCRIPT_SAVE_DIR .. RA.SEP .. name
    f = io.open(dest, "r")
  end

  if Code.safe_write(dest, code) then
    return dest, "Script: ReaAssist/" .. name, name
  end
  return nil
end

-- =============================================================================
-- ReEQ bundled-install support
-- =============================================================================
-- ReEQ (by Justin Johnson, MIT) is bundled with ReaAssist and installed on
-- demand at the standard ReaPack location so sessions remain portable: anyone
-- with ReEQ from ReaPack will resolve the same `ReJJ/ReEQ/ReEQ.jsfx` path.
--
-- The bundled source lives in <script>/Resources/ReEQ/ and contains:
--   ReEQ.jsfx, Dependencies/{firhalfband,spectrum,svf_filter}.jsfx-inc
-- The full MIT notice is in the main app LICENSE.txt.
--
-- After install we call EnumInstalledFX(-1) so TrackFX_AddByName finds the
-- new JSFX immediately (the FX Browser does not visually refresh until REAPER
-- restarts, but plugin lookup by path works right away).

local REEQ_SRC_DIR  = RA.RESOURCES_DIR .. "ReEQ"
local REEQ_DEST_DIR = reaper.GetResourcePath() .. RA.SEP .. "Effects" .. RA.SEP .. "ReJJ" .. RA.SEP .. "ReEQ"
local REEQ_DEPS     = { "firhalfband.jsfx-inc", "spectrum.jsfx-inc", "svf_filter.jsfx-inc" }

-- Returns true iff the canonical ReEQ.jsfx file is present at the ReaPack path.
function Code.is_reeq_installed()
  local f = io.open(REEQ_DEST_DIR .. RA.SEP .. "ReEQ.jsfx", "r")
  if f then f:close(); return true end
  return false
end

-- Internal: copies a single file if the destination doesn't already exist.
-- Returns true on success (including "already present" no-op), false + err on failure.
local function reeq_copy_file(src, dest)
  local existing = io.open(dest, "r")
  if existing then existing:close(); return true end  -- idempotent: don't overwrite
  local sf, err = io.open(src, "rb")
  if not sf then return false, "Cannot read " .. src .. ": " .. tostring(err) end
  local data = sf:read("*a"); sf:close()
  local df, derr = io.open(dest, "wb")
  if not df then return false, "Cannot write " .. dest .. ": " .. tostring(derr) end
  -- Check write/close return values. A short write (disk full mid-copy)
  -- or a close failure (filesystem flush error) used to leave a corrupt
  -- destination but return true; Code.is_reeq_installed() then sees the
  -- file exists and short-circuits any reinstall, so the user is stuck
  -- with a broken JSFX until they manually delete it. Remove the partial
  -- file on failure so a reinstall can recover.
  local wok, werr = df:write(data)
  local cok, cerr = df:close()
  if not wok or not cok then
    os.remove(dest)
    return false, "Write failed for " .. dest .. ": "
      .. tostring(werr or cerr or "unknown")
  end
  return true
end

-- Installs the bundled ReEQ to {resource_path}/Effects/ReJJ/ReEQ/.
-- Idempotent: skips files that already exist at the destination.
-- Returns (true, nil) on success or (false, error_message) on failure.
function Code.install_reeq()
  -- Sanity check that the bundled source is present.
  local probe = io.open(REEQ_SRC_DIR .. RA.SEP .. "ReEQ.jsfx", "r")
  if not probe then
    return false, "Bundled ReEQ source not found at " .. REEQ_SRC_DIR
  end
  probe:close()

  -- Create destination tree.
  reaper.RecursiveCreateDirectory(REEQ_DEST_DIR .. RA.SEP .. "Dependencies", 0)

  local ok, err = reeq_copy_file(REEQ_SRC_DIR .. RA.SEP .. "ReEQ.jsfx",
                                 REEQ_DEST_DIR .. RA.SEP .. "ReEQ.jsfx")
  if not ok then return false, err end
  -- Copy dependencies.
  for _, dep in ipairs(REEQ_DEPS) do
    ok, err = reeq_copy_file(REEQ_SRC_DIR  .. RA.SEP .. "Dependencies" .. RA.SEP .. dep,
                             REEQ_DEST_DIR .. RA.SEP .. "Dependencies" .. RA.SEP .. dep)
    if not ok then return false, err end
  end

  -- Force REAPER to rescan installed FX so AddByName finds ReEQ immediately.
  -- Same trick used by Code.auto_save_jsfx; the FX Browser doesn't visually
  -- refresh, but lookup-by-path works right away.
  if reaper.EnumInstalledFX then reaper.EnumInstalledFX(-1) end
  CTX._installed_fx_list = nil

  -- Re-run fallback chains now that ReEQ is on disk. Fills pref_types.eq
  -- with the first chain candidate that's installed (ReEQ if the user has
  -- no FabFilter EQ) so the Preferred Plugins page reflects it and preempt
  -- injection fires for "eq" keywords from now on. No-op if the user
  -- already has an EQ preference set.
  Code.ensure_preferred_from_chains()

  return true, nil
end

-- =============================================================================
-- Fallback chains: auto-assign preferred plugins from Plugin_Pack.md
-- =============================================================================
-- PLUGIN AUTO-ASSIGN / POPUP FLOW
-- -------------------------------
-- Single source of truth: the ```chains block in Resources/Plugin_Pack.md.
-- Line format:
--   type: chain1 | chain2 | ... || stock-fallback [optional alias]
--
-- AUTO-ASSIGN CHAIN (left of `||`):
--   Walked at startup by Code.ensure_preferred_from_chains (and again after
--   install_reeq invalidates the FX list cache). First installed entry wins
--   and is written to pref_types[type]. Appears on the Preferred Plugins
--   page. Only high-quality third-party picks belong here -- they commit
--   users silently. Stock REAPER plugins are NEVER in chains.
--
-- STOCK FALLBACK (right of `||`):
--   Offered by the resolve popup as a one-click "Use <name> instead" button
--   when no chain entry is installed and the model emits resolve:<type>.
--   Used for THIS TURN ONLY -- never saved to pref_types, never shown on
--   the Preferred Plugins page. The popup fires again next time the type
--   comes up. Users who want a stock plugin permanent must type it into the
--   Preferred Plugins page themselves.
--
-- DISPLAY ALIAS (in brackets after any entry):
--   Optional. Overrides the button label for stock fallbacks. Example:
--     JS: Liteon/deesser [JSFX De-esser]
--   Shows as "Use JSFX De-esser instead" on the popup button.
--
-- LINE FORMAT EXAMPLES:
--   eq: Pro-Q 4 | ReJJ/ReEQ/ReEQ.jsfx || ReaEQ      -- 2-entry chain + stock
--   chorus:  || JS: SStillwell/chorus_stereo [JSFX Chorus]
--                                                    -- stock-only type
--   custom_thing: MyPlugin                           -- chain-only (rare)
--
-- TO ADD A NEW AUTO-ASSIGN CANDIDATE: add to the matching chain line in
-- Plugin_Pack.md. Entries are format-agnostic (just the plugin name); the
-- resolver tries VST3 > VSTi > VST > AU > CLAP. JSFX entries use the full
-- relative path (e.g. ReJJ/ReEQ/ReEQ.jsfx, or JS: vendor/file for stock).
--
-- TO ADD A NEW PLUGIN TYPE: add to PREF_PLUGIN_DEFAULTS, PREF_PLUGIN_ALIASES,
-- VALID_RESOLVE_TYPES, and add a chain line in Plugin_Pack.md. The popup
-- picks up the stock fallback automatically via Code.get_stock_fallback.
-- See Dev/Plugin Scanner Script/README.md for the full integration recipe.
-- -----------------------------------------------------------------------------

-- Raw plug-in pack file state. The explicit public states are unattempted,
-- ready, released and error. Reading is an internal phase so callers cannot
-- mistake an in-flight file for an available cache.
function Code.plugin_pack_raw_record()
  Code._plugin_pack_file = Code._plugin_pack_file or {
    state = "unattempted",
    path = RA.RESOURCES_DIR .. "Plugin_Pack.md",
  }
  return Code._plugin_pack_file
end

function Code.plugin_pack_raw_begin()
  local raw = Code.plugin_pack_raw_record()
  if raw.state == "ready" then return true end
  if raw.state == "released" then
    return false, "Plugin pack raw content was released after derivation."
  end
  if raw.state == "error" then return false, raw.error end
  if raw.phase == "reading" then return true end
  local file, open_err = io.open(raw.path, "rb")
  if not file then
    raw.state = "error"
    raw.error = "Plugin_Pack.md not found at " .. raw.path
      .. ": " .. tostring(open_err)
    return false, raw.error
  end
  raw.phase = "reading"
  raw.file = file
  raw.chunks = {}
  raw.bytes = 0
  return true
end

function Code.plugin_pack_raw_step(max_bytes)
  local raw = Code.plugin_pack_raw_record()
  if raw.state == "ready" then return true end
  local ok, begin_err = Code.plugin_pack_raw_begin()
  if not ok then return false, begin_err end
  local amount = math.max(1, math.min(tonumber(max_bytes) or 65536, 65536))
  local chunk, read_err = raw.file:read(amount)
  if chunk and #chunk > 0 then
    raw.chunks[#raw.chunks + 1] = chunk
    raw.bytes = raw.bytes + #chunk
    if #chunk == amount then return false, "pending", #chunk end
  elseif read_err then
    raw.file:close()
    raw.file = nil
    raw.chunks = nil
    raw.phase = nil
    raw.state = "error"
    raw.error = "Could not read Plugin_Pack.md: " .. tostring(read_err)
    return false, raw.error
  end
  raw.file:close()
  raw.file = nil
  -- Git and Windows editors may materialize this maintained text file with
  -- CRLF. Normalize in memory so harmless line-ending style cannot disable
  -- plug-in guidance or break the format parser.
  raw.content = tbl_concat(raw.chunks):gsub("\r\n", "\n"):gsub("\r", "\n")
  raw.chunks = nil
  raw.phase = nil
  raw.state = "ready"
  return true, nil, chunk and #chunk or 0
end

function Code.get_plugin_pack_content()
  local raw = Code.plugin_pack_raw_record()
  if raw.state == "ready" then return raw.content, nil end
  if raw.state == "released" then
    return nil, "Plugin pack raw content was released after derivation."
  end
  if raw.state == "error" then
    return nil, raw.error or "Plugin pack raw content is unavailable."
  end
  Code.plugin_pack_raw_begin()
  return nil, "Plugin pack content is still loading."
end

function Code.release_plugin_pack_content()
  local raw = Code.plugin_pack_raw_record()
  if raw.file then raw.file:close(); raw.file = nil end
  raw.content = nil
  raw.chunks = nil
  raw.phase = nil
  if raw.state ~= "error" then raw.state = "released" end
end

function Code.plugin_pack_dev_integrity_override()
  local resource = reaper and reaper.GetResourcePath
    and tostring(reaper.GetResourcePath() or "") or ""
  resource = resource:gsub("/", "\\"):gsub("\\+$", ""):lower()
  if resource ~= "c:\\reaper - test" then return false end
  local value = reaper and reaper.GetExtState
    and tostring(reaper.GetExtState(
      CFG.EXT_NS, "dev_plugin_pack_integrity_override") or "") or ""
  return value == "1"
end

function Code.plugin_pack_manifest_hash()
  -- manifest.json travels with the body it describes (decision 10a.1).
  local manifest_path = RA.APP_DIR .. "manifest.json"
  local file, open_err = io.open(manifest_path, "rb")
  if not file then
    return nil, "local manifest unavailable: " .. tostring(open_err)
  end
  local raw, read_err = file:read("*a")
  file:close()
  if not raw then
    return nil, "local manifest unreadable: " .. tostring(read_err)
  end
  if not (RA.JSON and type(RA.JSON.decode) == "function") then
    return nil, "manifest decoder unavailable"
  end
  local manifest, decode_err = RA.JSON.decode(raw)
  if type(manifest) ~= "table" then
    return nil, "local manifest invalid: " .. tostring(decode_err)
  end
  local found = nil
  for _, entry in ipairs(manifest.files or {}) do
    if type(entry) == "table"
        and entry.name == "Resources/Plugin_Pack.md" then
      if found then return nil, "local manifest has duplicate pack entries" end
      found = tostring(entry.sha256 or ""):lower()
    end
  end
  if not found or not found:match("^[0-9a-f]+$") or #found ~= 64 then
    return nil, "local manifest has no valid Plugin_Pack.md checksum"
  end
  return found
end

function Code.fire_plugin_pack_native_sha(path)
  os.remove(tmp.plugin_pack_sha_out)
  os.remove(tmp.plugin_pack_sha_exit)
  os.remove(tmp.plugin_pack_sha_ps)
  if not path or path == "" then return false end
  if RA.IS_WINDOWS then
    if not (reaper and reaper.ExecProcess) then return false end
    for _, character in ipairs({'"', '<', '>', '|'}) do
      if path:find(character, 1, true)
          or tmp.plugin_pack_sha_out:find(character, 1, true)
          or tmp.plugin_pack_sha_exit:find(character, 1, true)
          or tmp.plugin_pack_sha_ps:find(character, 1, true) then
        return false
      end
    end
    local script = string.format(
[[$ErrorActionPreference = 'Stop'
$exitPath = '%s'
$utf8 = New-Object System.Text.UTF8Encoding($false)
try {
  $sha = [System.Security.Cryptography.SHA256]::Create()
  $stream = [System.IO.File]::Open('%s',
    [System.IO.FileMode]::Open,
    [System.IO.FileAccess]::Read,
    [System.IO.FileShare]::ReadWrite)
  try {
    $hash = $sha.ComputeHash($stream)
    $hex = ([System.BitConverter]::ToString($hash)).Replace('-', '').ToLowerInvariant()
  } finally {
    $stream.Dispose()
    $sha.Dispose()
  }
  [System.IO.File]::WriteAllText('%s', $hex, $utf8)
  [System.IO.File]::WriteAllText($exitPath, '0', $utf8)
  exit 0
} catch {
  try { [System.IO.File]::WriteAllText($exitPath, '1', $utf8) } catch {}
  exit 1
}
]],
      Shell.ps_escape(tmp.plugin_pack_sha_exit),
      Shell.ps_escape(path),
      Shell.ps_escape(tmp.plugin_pack_sha_out))
    local script_file = io.open(tmp.plugin_pack_sha_ps, "wb")
    if not script_file then return false end
    script_file:write("\239\187\191")
    script_file:write(script)
    script_file:close()
    local command_line = string.format(
      'powershell -NoProfile -ExecutionPolicy Bypass -File """%s"""',
      tmp.plugin_pack_sha_ps)
    local launch = string.format(
      'powershell -NoProfile -WindowStyle Hidden'
      .. ' -Command "Start-Process cmd -ArgumentList \'/c %s\''
      .. ' -WindowStyle Hidden"',
      Shell.ps_escape(command_line))
    reaper.ExecProcess(launch, 5000)
  else
    local command = string.format(
      "(if command -v sha256sum >/dev/null 2>&1; then "
      .. "sha256sum %s | awk '{print $1}' > %s; rc=$?; "
      .. "elif command -v shasum >/dev/null 2>&1; then "
      .. "shasum -a 256 %s | awk '{print $1}' > %s; rc=$?; "
      .. "else rc=127; fi; echo $rc > %s) &",
      Shell.sh_quote(path), Shell.sh_quote(tmp.plugin_pack_sha_out),
      Shell.sh_quote(path), Shell.sh_quote(tmp.plugin_pack_sha_out),
      Shell.sh_quote(tmp.plugin_pack_sha_exit))
    os.execute(command)
  end
  return true
end

function Code.plugin_pack_integrity_to_lua(reason)
  local state = Code._plugin_pack_integrity
  if not state or state.state ~= "pending" then return end
  state.method = "lua"
  state.fallback_reason = reason
  state.lua_sha_state = nil
  os.remove(tmp.plugin_pack_sha_out)
  os.remove(tmp.plugin_pack_sha_exit)
  os.remove(tmp.plugin_pack_sha_ps)
end

-- STARTUP_PLUGIN_PACK_ENGINE_SHA_BEGIN
function Code.plugin_pack_engine_sha(path)
  if not ReaAssistEngineSessionEnabled() then return nil, "screen reader mode" end
  if type(path) ~= "string" or path == "" or path:find("\0", 1, true)
      or not (reaper and type(reaper.MBH_SHA256File) == "function") then
    return nil, "engine checksum unavailable"
  end
  if type(reaper.APIExists) == "function" then
    local probe_ok, exists = pcall(reaper.APIExists, "MBH_SHA256File")
    if not probe_ok or exists ~= true then
      return nil, "engine checksum unavailable"
    end
  end
  local ok, result_ok, digest = pcall(reaper.MBH_SHA256File, path)
  if not ok or result_ok ~= true or type(digest) ~= "string"
      or #digest ~= 64 then
    return nil, "engine checksum failed"
  end
  digest = digest:lower()
  if not digest:match("^[0-9a-f]+$") then
    return nil, "engine checksum malformed"
  end
  return digest
end
-- STARTUP_PLUGIN_PACK_ENGINE_SHA_END

-- STARTUP_PLUGIN_PACK_NATIVE_GATE_BEGIN
function Code.plugin_pack_native_allowed(opts)
  if type(opts) == "table" and opts.avoid_process == true then return false end
  if S and S.screen_reader_mode ~= true then
    if S.startup_first_frame_submitted ~= true
        or S.startup_post_paint_phase ~= "done" then
      return false
    end
  end
  return true
end
-- STARTUP_PLUGIN_PACK_NATIVE_GATE_END

function Code.start_plugin_pack_integrity(opts)
  if Code._plugin_pack_integrity then return Code._plugin_pack_integrity end
  local state = {
    state = "pending",
    started_at = time_precise(),
    path = RA.RESOURCES_DIR .. "Plugin_Pack.md",
  }
  Code._plugin_pack_integrity = state
  if Code.plugin_pack_dev_integrity_override() then
    state.state = "verified"
    state.method = "dev_override"
    state.override = true
    state.elapsed_ms = 0
    return state
  end
  local expected, manifest_err = Code.plugin_pack_manifest_hash()
  if not expected then
    state.state = "unavailable"
    state.method = "manifest"
    state.reason = manifest_err
    state.elapsed_ms = (time_precise() - state.started_at) * 1000
    return state
  end
  state.expected_hash = expected
  local engine_digest, engine_reason = Code.plugin_pack_engine_sha(state.path)
  if engine_digest then
    state.method = "engine"
    Code.plugin_pack_integrity_finish(engine_digest)
    return state
  end
  state.engine_fallback_reason = engine_reason
  local native_allowed = Code.plugin_pack_native_allowed(opts)
  state.method = native_allowed and Code.fire_plugin_pack_native_sha(state.path)
    and "native" or "lua"
  if not native_allowed then
    state.native_skipped_reason = type(opts) == "table" and opts.avoid_process
      and "startup checksum process disabled"
      or "first visual frame pending"
  end
  return state
end

function Code.plugin_pack_integrity_finish(actual)
  local state = Code._plugin_pack_integrity
  if not state then return end
  actual = actual and tostring(actual):lower() or nil
  state.actual_hash = actual
  state.elapsed_ms = (time_precise() - state.started_at) * 1000
  if not actual or #actual ~= 64 then
    state.state = "unavailable"
    state.reason = "checksum unavailable"
  elseif actual == state.expected_hash then
    state.state = "verified"
  else
    state.state = "mismatch"
    state.reason = "installed pack checksum does not match the local manifest"
  end
  state.lua_sha_state = nil
  os.remove(tmp.plugin_pack_sha_out)
  os.remove(tmp.plugin_pack_sha_exit)
  os.remove(tmp.plugin_pack_sha_ps)
end

-- STARTUP_PLUGIN_PACK_METHOD_GUARD_BEGIN
function Code.plugin_pack_integrity_method_supported(method)
  return method == "native" or method == "lua"
end
-- STARTUP_PLUGIN_PACK_METHOD_GUARD_END

function Code.plugin_pack_integrity_tick(content, deadline)
  local state = Code.start_plugin_pack_integrity()
  if state.state ~= "pending" then return true, state end
  if not Code.plugin_pack_integrity_method_supported(state.method) then
    state.state = "unavailable"
    state.invalid_method = true
    state.reason = "checksum method unavailable"
    state.elapsed_ms = (time_precise() - state.started_at) * 1000
    return true, state
  end
  if state.method == "native" then
    local timeout = tonumber(CFG.UPDATE_NATIVE_SHA_TIMEOUT) or 15
    if (time_precise() - state.started_at) > timeout then
      Code.plugin_pack_integrity_to_lua("native checksum timeout")
    else
      local exit_file = io.open(tmp.plugin_pack_sha_exit, "r")
      if not exit_file then return false, state end
      local exit_text = exit_file:read("*a")
      exit_file:close()
      local exit_code = tonumber(tostring(exit_text):match("(%d+)"))
      if not exit_code then return false, state end
      if exit_code ~= 0 then
        Code.plugin_pack_integrity_to_lua(
          "native checksum exited " .. tostring(exit_code))
      else
        local output_file = io.open(tmp.plugin_pack_sha_out, "r")
        local output = output_file and output_file:read("*a") or nil
        if output_file then output_file:close() end
        local actual = output and output:match("([0-9a-fA-F]+)") or nil
        if actual and #actual == 64 then
          Code.plugin_pack_integrity_finish(actual)
          return true, state
        end
        Code.plugin_pack_integrity_to_lua("native checksum output missing")
      end
    end
  end
  if state.method ~= "lua" or not content then return false, state end
  if not (RA.sha256_create and RA.sha256_step and RA.sha256_finalize) then
    state.state = "unavailable"
    state.reason = "incremental Lua checksum unavailable"
    state.elapsed_ms = (time_precise() - state.started_at) * 1000
    return true, state
  end
  if not state.lua_sha_state then
    state.lua_sha_state = RA.sha256_create(content)
  end
  local tick_deadline = tonumber(deadline) or (time_precise() + 0.005)
  local done = false
  repeat
    done = RA.sha256_step(state.lua_sha_state, 16)
  until done or time_precise() >= tick_deadline
  if not done then return false, state end
  Code.plugin_pack_integrity_finish(
    RA.sha256_finalize(state.lua_sha_state))
  return true, state
end

function Code.plugin_pack_integrity_status()
  return Code._plugin_pack_integrity or { state = "unattempted" }
end

-- Parse fallback chains only after Context.lua has verified and structurally
-- validated the installed pack. The returned table becomes part of the one
-- derived owner and this function does not cache a second copy.
function Code.parse_plugin_pack_chains(content)
  local output = {}
  local block = tostring(content or ""):match("```chains%s*\n(.-)\n```")
  if not block then return nil, "no ```chains block found" end
  local function parse_entry(value)
    value = value:match("^%s*(.-)%s*$") or ""
    if value == "" then return nil end
    local name, alias = value:match("^(.-)%s*%[(.-)%]%s*$")
    if name and alias and name ~= "" then
      return {
        name = name:match("^%s*(.-)%s*$"),
        alias = alias:match("^%s*(.-)%s*$"),
      }
    end
    return { name = value }
  end
  for line in block:gmatch("[^\n]+") do
    local stripped = line:match("^%s*(.-)%s*$") or ""
    if stripped ~= "" and stripped:sub(1, 1) ~= "#" then
      local type_key, rest = line:match("^%s*([%w_]+)%s*:%s*(.*)$")
      if type_key and rest then
        local chain_text, stock_text = rest:match("^(.-)%s*||%s*(.+)$")
        if not chain_text then chain_text, stock_text = rest, nil end
        local chain = {}
        for entry in chain_text:gmatch("[^|]+") do
          local parsed = parse_entry(entry)
          if parsed then chain[#chain + 1] = parsed.name end
        end
        local parsed_stock = stock_text and parse_entry(stock_text) or nil
        local stock = parsed_stock and {
          add = parsed_stock.name,
          alias = parsed_stock.alias,
        } or nil
        if #chain > 0 or stock then
          output[type_key] = { chain = chain, stock = stock }
        end
      end
    end
  end
  return output
end

function Code.get_fallback_chains()
  local owner = CTX and CTX._plugin_pack_owner or nil
  if owner and owner.ready and type(owner.fallback_chains) == "table" then
    return owner.fallback_chains
  end
  return {}
end

-- Code.get_stock_fallback and Code.is_curated_plugin are installed by
-- Resources/Context.lua because they read plugin-reference aliases loaded there.

-- Format preference for format-agnostic chain entries. Plugins installed in
-- multiple formats are resolved in this order so VST3 wins over CLAP, etc.
local CHAIN_FORMAT_PREFIXES = {
  "VST3:", "VST3i:", "VSTi:", "VST:", "AU:", "AUi:", "CLAP:", "CLAPi:",
}

-- Test whether a chain entry (plugin name or JSFX path) is installed on the
-- system by searching the enumerated FX list. Returns the full enumerated
-- name on match, or nil. JSFX paths match exactly; plugin names use a
-- case-insensitive substring match plus format-prefix preference.
function Code.resolve_chain_entry(entry, installed_list)
  -- Bundled-ReEQ fallback: check the filesystem regardless of what
  -- installed_list contains. EnumInstalledFX on macOS has been observed
  -- to omit our installed ReEQ.jsfx even after a REAPER restart while
  -- the file is unambiguously present at the canonical install path.
  -- Same coverage gap that the resolve handler already works around
  -- via Code.is_reeq_installed (mid-session filesystem check); we
  -- apply it to the chain walk too so the auto-pref slot populates
  -- without requiring a chat round-trip. Runs before the empty-list
  -- guard so it works even on a fresh launch where EnumInstalledFX
  -- hasn't returned any rows yet.
  if entry == "ReJJ/ReEQ/ReEQ.jsfx" and Code.is_reeq_installed() then
    return entry
  end
  if not installed_list or #installed_list == 0 then return nil end
  if entry:find("/", 1, true) then
    for _, inst in ipairs(installed_list) do
      if inst == entry or inst == "JS: " .. entry then return inst end
    end
    return nil
  end
  local entry_lower = entry:lower()
  local best, best_rank = nil, math.huge
  for _, inst in ipairs(installed_list) do
    if inst:lower():find(entry_lower, 1, true) then
      local rank = math.huge
      for i, p in ipairs(CHAIN_FORMAT_PREFIXES) do
        if inst:sub(1, #p) == p then rank = i; break end
      end
      if rank < best_rank then best, best_rank = inst, rank end
    end
  end
  return best
end

-- Walk every fallback chain and auto-assign pref_types[type] to the first
-- installed entry, ONLY when no existing preference is set. Never overwrites
-- user choices. Called at script load and after installing bundled plugins.
-- Idempotent; returns count of types newly assigned this call.
function Code.ensure_preferred_from_chains()
  local chains = Code.get_fallback_chains()
  if not next(chains) then return 0 end
  CTX.populate_installed_fx()
  local installed = CTX._installed_fx_list or {}
  local cache = FXCache.load()
  cache.preferred_types = cache.preferred_types or {}
  local hide_ff = reaper.GetExtState(CFG.EXT_NS, "dev_hide_fabfilter") == "1"
  -- Dev-only HideFabFilter override: when the flag is on AND the cached
  -- pref for a type is a FabFilter ident (Pro-Q 4 / Pro-C 3 / ...), treat
  -- the cached value as empty so the chain walk falls through to the next
  -- resolvable alternative (ReEQ for eq, etc.). This makes "Hide FabFilter"
  -- actually simulate a no-FabFilter install instead of just hiding the
  -- value at display time. The override is SESSION-ONLY: ephemeral_originals
  -- captures the pre-override values so we can restore them before
  -- persisting to disk -- toggling HideFabFilter back off must restore the
  -- user's real preferred plugin (e.g. Pro-Q 4) cleanly.
  local ephemeral_originals = {}
  local assigned = 0
  local sorted_types = {}
  for k in pairs(chains) do sorted_types[#sorted_types+1] = k end
  table.sort(sorted_types)
  for _, type_key in ipairs(sorted_types) do
    local original = cache.preferred_types[type_key]
    local existing = original
    local overridden = false
    if hide_ff and existing and existing ~= ""
        and _is_fabfilter_ident(existing) then
      existing = ""
      overridden = true
    end
    if not existing or existing == "" then
      local chain_list = chains[type_key].chain or {}
      for _, entry in ipairs(chain_list) do
        if Code.resolve_chain_entry(entry, installed) then
          -- Canonicalize the chain-entry form to AddByName-ready prefixed
          -- form before storing. Chain entries are intentionally format-
          -- agnostic ("Twin 3"), but the model + TrackFX_AddByName work
          -- more reliably with the prefixed form ("VST3i: Twin 3").
          local canonical = FXCache.canonicalize_identifier(type_key, entry)
          cache.preferred_types[type_key] = canonical
          Log.line("PREF", str_format(
            "auto-assigned preferred_types.%s = %s%s%s",
            type_key, canonical,
            (canonical ~= entry) and " (canonicalized from " .. entry .. ")" or "",
            overridden and " (ephemeral; hide_fabfilter override of "
              .. tostring(original) .. ")" or " (from chain)"))
          assigned = assigned + 1
          if overridden then ephemeral_originals[type_key] = original end
          break
        end
      end
    end
  end
  -- One-time-per-session migration of any legacy bare-name entries that
  -- this run didn't touch (entries that already had a value when this
  -- function was called, so the chain-walk above skipped them). Runs
  -- after the chain assignment so newly-assigned entries are already
  -- canonical and the migration finds nothing to do for them.
  FXCache.canonicalize_all_preferred_types()
  if assigned > 0 then
    if next(ephemeral_originals) then
      -- Snapshot-and-restore: write the rolled-back values to disk, then
      -- re-apply the in-memory overrides so the rest of the session keeps
      -- using the simulated alternatives. Both `cache` and the table held
      -- in FXCache._fx_cache_mem are the same Lua table, so restoring
      -- `cache.preferred_types[k]` also updates the module-level cache
      -- that FXCache.load returns to other callers.
      --
      -- Save is wrapped in pcall and the in-memory restore runs
      -- unconditionally: if FXCache.save errors mid-write (disk full /
      -- permission failure surfaces a message-box from Code.safe_write),
      -- we still want the session to keep simulating "no FabFilter".
      -- Without unconditional restore, an error here would leave
      -- cache.preferred_types[k] at the original FabFilter ident (the
      -- value we just swapped in for the save), silently breaking the
      -- HideFabFilter override until the next ReaAssist relaunch.
      local in_memory_values = {}
      for k in pairs(ephemeral_originals) do
        in_memory_values[k] = cache.preferred_types[k]
      end
      for k, original_v in pairs(ephemeral_originals) do
        cache.preferred_types[k] = original_v
      end
      -- FXCache.save returns nil on success or an error STRING on failure
      -- (it does not raise). pcall therefore returns (true, err_string) on
      -- the failure path, so the previous `if not ok` guard alone never
      -- caught a normal save error. Capture the function's return value
      -- too and log when it's non-nil, otherwise the operator triaging a
      -- "HideFabFilter override didn't persist" report would see no log
      -- breadcrumb at all.
      local ok, save_ret = pcall(FXCache.save, cache)
      for k, mem_v in pairs(in_memory_values) do
        cache.preferred_types[k] = mem_v
      end
      if not ok then
        Log.line("PREF", "FXCache.save raised during HideFabFilter "
                       .. "rollback; in-memory override preserved: "
                       .. tostring(save_ret))
      elseif save_ret then
        Log.line("PREF", "FXCache.save failed during HideFabFilter "
                       .. "rollback; in-memory override preserved: "
                       .. tostring(save_ret))
      end
    else
      local save_err = FXCache.save(cache)
      if save_err then
        Log.line("PREF", "FXCache.save failed (HideFabFilter assign): "
                       .. tostring(save_err))
      end
    end
  end
  return assigned
end

-- =============================================================================
-- Utility: Code._save_generated (internal)
-- =============================================================================
-- Shared save-dialog + write flow used by Code.save_file and
-- Code.save_file_jsfx. Opens a native save dialog through the Engine or the
-- legacy js_ReaScriptAPI fallback. Otherwise it uses GetUserInputs and strips path
-- separators from the input so the user cannot escape opts.base_dir.
-- Returns the saved path on success, or nil plus a reason on cancellation/error.
function Code._save_generated(code, suggested_name, opts)
  local dest_path
  local save_dialog
  if RA and type(RA.preferred_platform_api) == "function" then
    save_dialog = RA.preferred_platform_api(
      "MBH_Dialog_BrowseForSaveFile", "JS_Dialog_BrowseForSaveFile")
  end
  if not save_dialog then
    save_dialog = reaper.ReaAssist_Native_JS_Dialog_BrowseForSaveFile
      or reaper.JS_Dialog_BrowseForSaveFile
  end
  if S and S.screen_reader_mode then
    save_dialog = nil
  end
  if save_dialog then
    local ok, ret, path = pcall(save_dialog,
      opts.dialog_title, opts.base_dir, suggested_name, opts.filter)
    if not ok then
      if Log and Log.line then
        Log.line("SAVE", "save dialog failed: " .. tostring(ret))
      end
      return nil, "dialog_failed"
    end
    if ret ~= 1 or not path or path == "" then return nil, "cancelled" end
    -- Lower-case the path before matching ext_pattern. Filesystems on
    -- Windows / macOS preserve the typed case, so a user who picks
    -- "MyScript.LUA" in the dialog used to fall through the case-
    -- sensitive `%.lua$` pattern and we'd append .lua, producing the
    -- ugly double-extension MyScript.LUA.lua.
    if not path:lower():match(opts.ext_pattern) then path = path .. opts.ext end
    dest_path = path
  else
    local ret, name = reaper.GetUserInputs(
      opts.fallback_title, 1, opts.fallback_label, suggested_name)
    if not ret or name == "" then return nil, "cancelled" end
    if not name:lower():match(opts.ext_pattern) then name = name .. opts.ext end
    name = name:match("[^\\/]+$") or name
    dest_path = opts.base_dir .. RA.SEP .. name
  end
  if Code.safe_write(dest_path, code) then return dest_path end
  return nil, "write_failed"
end

-- Save JSFX code to REAPER's Effects folder (thin wrapper over _save_generated).
function Code.save_file_jsfx(code, suggested_name)
  return Code._save_generated(code, suggested_name, {
    dialog_title   = (RA and RA.t and RA.t(
      "code.save_jsfx.dialog_title", nil, "Save JSFX Effect"))
      or "Save JSFX Effect",
    base_dir       = reaper.GetResourcePath() .. RA.SEP .. "Effects",
    filter         = (RA and RA.t and RA.t("code.save_jsfx.filter", nil,
      "JSFX files (.jsfx)\0*.jsfx\0All files\0*.*\0"))
      or "JSFX files (.jsfx)\0*.jsfx\0All files\0*.*\0",
    ext            = ".jsfx",
    ext_pattern    = "%.jsfx$",
    fallback_title = (RA and RA.t and RA.t(
      "code.save_jsfx.fallback_title", nil, "Save JSFX")) or "Save JSFX",
    fallback_label = (RA and RA.t and RA.t("code.save_jsfx.fallback_label",
      nil, "Filename (saved to REAPER Effects folder):,extrawidth=260"))
      or "Filename (saved to REAPER Effects folder):,extrawidth=260",
  })
end

-- Save Lua script to REAPER's Scripts folder (thin wrapper over _save_generated).
function Code.save_file(code, suggested_name)
  return Code._save_generated(code, suggested_name, {
    dialog_title   = (RA and RA.t and RA.t(
      "code.save_lua.dialog_title", nil, "Save Lua Script"))
      or "Save Lua Script",
    base_dir       = reaper.GetResourcePath() .. RA.SEP .. "Scripts",
    filter         = (RA and RA.t and RA.t("code.save_lua.filter", nil,
      "Lua files (.lua)\0*.lua\0All files\0*.*\0"))
      or "Lua files (.lua)\0*.lua\0All files\0*.*\0",
    ext            = ".lua",
    ext_pattern    = "%.lua$",
    fallback_title = (RA and RA.t and RA.t(
      "code.save_lua.fallback_title", nil, "Save Script")) or "Save Script",
    fallback_label = (RA and RA.t and RA.t("code.save_lua.fallback_label",
      nil, "Filename (saved to REAPER Scripts folder):,extrawidth=260"))
      or "Filename (saved to REAPER Scripts folder):,extrawidth=260",
  })
end

-- Strips API keys and secrets from URLs/error strings before they reach the
-- UI. Covers ?key= / &key= style query params (case-insensitive) and Bearer
-- tokens in headers. Lua patterns do not support alternation, so each secret
-- name is scrubbed with its own gsub; an earlier "one-pattern" attempt used a
-- pipe character that matches literally, so it never fired.
local SCRUB_KEYS = {
  "[Kk][Ee][Yy]",
  "[Tt][Oo][Kk][Ee][Nn]",
  "[Ss][Ee][Cc][Rr][Ee][Tt]",
  "[Aa][Pp][Ii][_]?[Kk][Ee][Yy]",
  "[Aa][Cc][Cc][Ee][Ss][Ss][_][Tt][Oo][Kk][Ee][Nn]",
  "[Pp][Aa][Ss][Ss][Ww][Oo][Rr][Dd]",
}
-- Shared scrubber: both Log.add_error and Diag.add_error route error
-- strings through this before display / storage. SCRUB_KEYS stays a
-- local because nothing else references it.
function Log.scrub_url_secrets(s)
  if not s then return s end
  for _, name in ipairs(SCRUB_KEYS) do
    s = s:gsub("([?&]" .. name .. "=)[^&%s\"']+", "%1***")
  end
  s = s:gsub("([Bb]earer%s+)[^%s\"']+", "%1***")
  return s
end

-- Queue an error message into S.display_messages as an assistant turn,
-- flip S.status to "error", clear in-flight timers, and scroll to bottom.
-- Optional link_url/link_label render a clickable URL beneath the text.
-- Optional `recovery` renders inline recovery buttons scoped by provider/model
-- metadata on the message. `extra` can stamp recovery-specific payload such as
-- a saved prompt or fallback model id.
function Log.add_error(msg, link_url, link_label, recovery, extra)
  S.status             = "error"
  S.send_time          = nil
  S.request_start_time = nil
  if type(Net) == "table"
     and type(Net._set_pending_request_status) == "function" then
    Net._set_pending_request_status("failed",
      recovery or (type(extra) == "table" and extra.recovery_kind), {
        error_kind = type(extra) == "table" and extra.error_kind or nil,
      })
  end
  local pending_request = S.pending_display_idx
    and S.display_messages[S.pending_display_idx] or nil
  local entry = {
    role       = "assistant",
    content    = Log.scrub_url_secrets(msg),
    link_url   = link_url,
    link_label = link_label,
    recovery   = recovery,
    request_status = pending_request
      and type(pending_request.request_status) == "table"
      and type(Diag) == "table"
      and type(Diag.sanitize_request_status) == "function"
      and Diag.sanitize_request_status(pending_request.request_status) or nil,
  }
  if recovery == "token_limit" or recovery == "google_model_capacity" then
    local p = PROVIDERS.active()
    entry.provider_id = p and p.id or nil
  end
  if type(extra) == "table" then
    for k, v in pairs(extra) do entry[k] = v end
  end
  if entry.recovery_kind == nil and recovery ~= nil then
    entry.recovery_kind = recovery
  end
  if entry.assistant_response_status == nil then
    entry.assistant_response_status = (recovery == "token_limit")
      and "empty" or "error"
  end
  if entry.code_block_present == nil then entry.code_block_present = false end
  if entry.validation_status == nil then entry.validation_status = "not_applicable" end
  if entry.error_kind == nil and recovery == "token_limit" then
    entry.error_kind = "model_no_usable_answer"
    entry.error_debug = entry.error_debug or {
      failure_kind = "model_empty_response",
      recovery_kind = recovery,
    }
  end
  if entry.run_status == nil then
    if entry.assistant_response_status == "empty" then
      entry.run_status = "no_usable_answer"
    elseif entry.error_kind ~= nil or entry.error_debug ~= nil then
      entry.run_status = "provider_failed"
    else
      entry.run_status = "request_error"
    end
  end
  if type(Net) == "table"
      and type(Net._resolve_local_escalation) == "function" then
    Net._resolve_local_escalation("failed", entry)
  end
  S.display_messages[#S.display_messages+1] = entry
  S.scroll_to_bottom = true
end

-- =============================================================================
-- Diag -- Diagnostic report builder for bug reports
-- =============================================================================
-- Captures recent code-execution errors and assembles a plain-text diagnostic
-- report the user can copy to their clipboard and paste into a bug report.

-- Schema version stamped into every saved FX cache file. Bump when the
-- on-disk structure changes in a way old code can't safely read. Files
-- with an unsupported or malformed version are discarded cleanly on load
-- (fresh scan rebuilds the cache rather than silently misreading it). Known
-- v1 and unversioned legacy shapes migrate without losing preferred types.
-- Declared here (above Diag) because Diag.build_report reads it for the
-- diagnostic report's Plugin System section.
local FXCACHE_VERSION = 2

Diag = { errors = {}, MAX_ERRORS = 20 }

function Diag.add_error(msg, traceback, code)
  local code_text = code and tostring(code) or nil
  local code_excerpt = nil
  if code_text then
    code_excerpt = Diag._utf8_safe_prefix_bytes
      and Diag._utf8_safe_prefix_bytes(code_text, 500)
      or code_text:sub(1, 500)
    if #code_text > 500 then code_excerpt = code_excerpt .. "..." end
  end
  local entry = {
    time = os.date("%Y-%m-%d %H:%M:%S"),
    msg  = Log.scrub_url_secrets(tostring(msg)),
    traceback = traceback and Log.scrub_url_secrets(tostring(traceback)) or nil,
    code = code_excerpt,
  }
  Diag.errors[#Diag.errors + 1] = entry
  if #Diag.errors > Diag.MAX_ERRORS then
    table.remove(Diag.errors, 1)
  end
end

-- opts (optional table):
--   skip_followup_note = true  -- omit the trailing "For detailed bugs..."
--                                 guidance paragraph. Used when the report
--                                 is embedded in a pre-filled email body
--                                 that already surfaces its own log-attach
--                                 instruction, so the two don't repeat.
function Diag.build_report(opts)
  local parts = {}
  -- Small pcall wrapper so a broken / missing extension probe can't
  -- crash the report build mid-stream.
  local function _try(fn) local ok, v = pcall(fn); if ok then return v end end
  -- On / Off formatter -- normalises booleans (and nil) to the
  -- ON / OFF convention the rest of the header already uses for
  -- "Auto model" / "Debug logging".
  local function _onoff(v) return v and "ON" or "OFF" end
  local function _utf8_prefix(text, max_bytes)
    text = tostring(text or "")
    if Diag and type(Diag._utf8_safe_prefix_bytes) == "function" then
      return Diag._utf8_safe_prefix_bytes(text, max_bytes)
    end
    return text:sub(1, max_bytes)
  end

  parts[#parts + 1] = "=== ReaAssist Diagnostic Report ==="
  parts[#parts + 1] = ""
  parts[#parts + 1] = "ReaAssist version: " .. CFG.VERSION
  parts[#parts + 1] = "REAPER version:    " .. tostring(reaper.GetAppVersion())
  parts[#parts + 1] = "OS:                " .. tostring(reaper.GetOS())
  local client_context = _try(function()
    if Diag and Diag.client_context then return Diag.client_context() end
  end) or {}
  parts[#parts + 1] = "Language:          "
    .. tostring(client_context.language_code or "unknown")
  parts[#parts + 1] = "Language pack:     "
    .. tostring(client_context.language_pack_version or "unknown")
  parts[#parts + 1] = "Interface mode:    "
    .. tostring(client_context.interface_mode or "unknown")
  local display = type(client_context.display_context) == "table"
    and client_context.display_context or {}
  local function _dimensions(width, height)
    if width and height then return tostring(width) .. " x " .. tostring(height) end
    return "unknown"
  end
  parts[#parts + 1] = "Display capture:    " .. tostring(display.status or "unavailable")
  parts[#parts + 1] = "Display logical:    "
    .. _dimensions(display.display_logical_width, display.display_logical_height)
  parts[#parts + 1] = "Display platform:   "
    .. _dimensions(display.display_platform_width, display.display_platform_height)
  parts[#parts + 1] = "Work area logical:  "
    .. _dimensions(display.work_area_logical_width, display.work_area_logical_height)
  parts[#parts + 1] = "Work area platform: "
    .. _dimensions(display.work_area_platform_width, display.work_area_platform_height)
  parts[#parts + 1] = "Window logical:     "
    .. _dimensions(display.window_logical_width, display.window_logical_height)
  parts[#parts + 1] = "Window platform:    "
    .. _dimensions(display.window_platform_width, display.window_platform_height)
  parts[#parts + 1] = "Display DPI:        "
    .. (display.dpi_scale_percent and tostring(display.dpi_scale_percent) .. "%" or "unknown")
  parts[#parts + 1] = "REAPER DPI:         "
    .. (display.reaper_dpi_scale_percent
      and tostring(display.reaper_dpi_scale_percent) .. "%" or "unknown")
  parts[#parts + 1] = "Interface Size:     "
    .. (display.interface_size_percent
      and tostring(display.interface_size_percent) .. "%" or "unknown")
    .. " (" .. tostring(display.interface_size_mode or "unknown") .. ")"
  parts[#parts + 1] = "Size remembered:    "
    .. _onoff(display.interface_size_remembered == true)
  parts[#parts + 1] = "SR visual text:     "
    .. (display.screen_reader_text_size_percent
      and tostring(display.screen_reader_text_size_percent) .. "%" or "unknown")
  -- ReaImGui version -- UI / rendering bugs hinge on this. Probe
  -- covers a few possible shapes across ReaImGui releases.
  local imgui_ver = _try(function()
    if not ImGui then return nil end
    if ImGui.ImGui_GetVersion then
      return select(1, ImGui.ImGui_GetVersion())
    end
    if ImGui.ReaImGui_Version then return ImGui.ReaImGui_Version end
  end)
  parts[#parts + 1] = "ReaImGui version:  " .. (imgui_ver and tostring(imgui_ver) or "unknown")
  parts[#parts + 1] = "Provider:          " .. (PROVIDERS.active().label or "unknown")
  parts[#parts + 1] = "Model:             " .. (MODELS.active_id() or "unknown")
  local p = PROVIDERS.active()
  if p.thinking_levels and p.thinking_levels[prefs.thinking_idx] then
    parts[#parts + 1] = "Thinking:          " .. p.thinking_levels[prefs.thinking_idx].label
  end
  -- Gemini paid-tier flag -- only meaningful when the active provider
  -- is Google, since it gates which models are visible and controls
  -- the "free tier data may be used for training" advisory.
  if p and p.id == "google" then
    parts[#parts + 1] = "Gemini paid tier:  " .. _onoff(S.gemini_paid_tier)
  end
  parts[#parts + 1] = "Debug logging:     " .. _onoff(prefs.debug_logging)
  if prefs.debug_logging then
    parts[#parts + 1] = "Log file:          " .. Log.path
    local f = io.open(Log.path, "r")
    if f then
      local size = f:seek("end") or 0
      f:close()
      parts[#parts + 1] = "Log file size:     " .. size .. " bytes"
    end
  end
  -- Current page / screen (which UI view the user was on when they copied
  -- the report). Useful for UI-specific bug reports.
  local screen = "chat"
  if api_keys.screen then
    screen = api_keys.screen
  elseif S.show_bug_report then screen = "bug_report"
  elseif S.show_help       then screen = "help"
  elseif S.show_credits    then screen = "credits"
  end
  parts[#parts + 1] = "Current screen:    " .. screen
  -- Session uptime -- seconds -> human-readable. Helps triage "UI
  -- froze after 6h" / "memory balloon" / long-session issues.
  local uptime_s = math_floor((reaper.time_precise() - (S.session_start_ts or reaper.time_precise())) + 0.5)
  local function _fmt_uptime(sec)
    if sec < 60 then return sec .. "s" end
    if sec < 3600 then
      return string.format("%dm %02ds", math_floor(sec / 60), sec % 60)
    end
    local h = math_floor(sec / 3600)
    local m = math_floor((sec % 3600) / 60)
    return string.format("%dh %02dm", h, m)
  end
  parts[#parts + 1] = "Session uptime:    " .. _fmt_uptime(uptime_s)
  local startup_first_frame = tonumber(S.startup_first_frame_ms)
  parts[#parts + 1] = "First frame:       "
    .. (startup_first_frame
      and string.format("%.1f ms", startup_first_frame) or "unknown")
  local startup_marks = {}
  if type(Startup) == "table" and type(Startup.marks) == "table" then
    for index, mark in ipairs(Startup.marks) do
      if index > 32 then break end
      if type(mark) == "table" and type(mark.label) == "string"
          and tonumber(mark.elapsed_ms) and tonumber(mark.delta_ms) then
        startup_marks[#startup_marks + 1] = string.format("%s=%.1f/%.1fms",
          mark.label, tonumber(mark.delta_ms), tonumber(mark.elapsed_ms))
      end
    end
  end
  parts[#parts + 1] = "Startup phases:    "
    .. (#startup_marks > 0 and table.concat(startup_marks, "; ") or "unknown")
  parts[#parts + 1] = ""

  -- Required + optional REAPER extensions. Missing / old extensions
  -- cause a long tail of "button did nothing" / "file dialog didn't
  -- open" bugs that are otherwise a pain to diagnose.
  parts[#parts + 1] = "--- Extensions ---"
  local sws_ok  = reaper.CF_GetSWSVersion ~= nil
  local sws_ver = sws_ok and _try(function() return reaper.CF_GetSWSVersion("") end) or nil
  parts[#parts + 1] = "SWS:               " ..
    (sws_ok and (sws_ver and tostring(sws_ver) or "installed") or "not installed")
  local js_ver = _try(function() return reaper.JS_ReaScriptAPI_Version and reaper.JS_ReaScriptAPI_Version() end)
  parts[#parts + 1] = "js_ReaScriptAPI:   " ..
    (js_ver and tostring(js_ver) or "not installed")
  -- Probe the specific calls ReaAssist uses, so a partially-working
  -- extension (e.g. old SWS / JS build missing a newer symbol) shows
  -- up here too rather than reading as "fully installed."
  parts[#parts + 1] = "CF_ShellExecute:   " ..
    _onoff(reaper.CF_ShellExecute ~= nil)
  parts[#parts + 1] = "CF_LocateInExplorer: " ..
    _onoff(reaper.CF_LocateInExplorer ~= nil)
  parts[#parts + 1] = "JS_Dialog_BrowseForSaveFile: " ..
    _onoff(reaper.JS_Dialog_BrowseForSaveFile ~= nil)
  parts[#parts + 1] = "Native UI helper: " ..
    _onoff(type(RA.engine_js_subset_available) == "function"
      and RA.engine_js_subset_available())
  local engine_desc = _try(function()
    return type(Engine) == "table" and type(Engine.describe) == "function"
      and Engine.describe() or nil
  end)
  local engine_status = "not installed"
  if type(engine_desc) == "table" and engine_desc.present == true then
    engine_status = tostring(engine_desc.version or "installed")
    if engine_desc.pinned_to_curl == true then
      engine_status = engine_status .. " (session using curl)"
    end
  end
  parts[#parts + 1] = "Native helper:     " .. engine_status
  local engine_support = _try(function()
    return type(Diag) == "table"
      and type(Diag.engine_support_summary) == "function"
      and Diag.engine_support_summary() or nil
  end)
  if type(engine_support) == "table" then
    local support_lines = type(Diag.engine_support_report_lines) == "function"
      and Diag.engine_support_report_lines(engine_support) or {}
    for _, line in ipairs(support_lines) do
      parts[#parts + 1] = line
    end
  end
  parts[#parts + 1] = ""

  -- User preferences
  parts[#parts + 1] = "--- Preferences ---"
  parts[#parts + 1] = "Auto-run:          " .. _onoff(prefs.auto_run)
  parts[#parts + 1] = "Auto-backup:       " .. _onoff(prefs.auto_backup)
  parts[#parts + 1] = "Stream responses:  " .. _onoff(prefs.stream_responses ~= false)
  local reasoning_mode = prefs.reasoning_display_mode
  if reasoning_mode ~= "off" and reasoning_mode ~= "summaries"
      and reasoning_mode ~= "provider_visible" then
    reasoning_mode = prefs.show_reasoning_summaries == true
      and "summaries" or "off"
  end
  parts[#parts + 1] = "Reason display:    " .. tostring(reasoning_mode)
  parts[#parts + 1] = "Include snapshot:  " .. _onoff(prefs.include_snapshot)
  parts[#parts + 1] = "Include API ref:   " .. _onoff(prefs.include_api_ref)
  parts[#parts + 1] = "Max history turns: " .. CFG.MAX_HISTORY_TURNS
  -- Cloud request timeout (seconds) -- affects "request hung" /
  -- "503 / timeout" bug reports directly.
  if prefs.cloud_request_timeout then
    parts[#parts + 1] = "Cloud timeout:     " .. tostring(prefs.cloud_request_timeout) .. "s"
  end
  parts[#parts + 1] = "API ref loaded:    " .. _onoff(
    S.api_ref_section_cache and S.api_ref_section_cache.core ~= nil)
  parts[#parts + 1] = "UI theme:          " .. tostring(prefs.theme or "default")
  local scale_val = CFG.UI_SCALE_OPTIONS[prefs.ui_scale_idx or 3] or 1.0
  parts[#parts + 1] = str_format("UI scale:          %.2fx", scale_val)
  -- API keys configured per provider (without revealing the keys). Helps
  -- diagnose "Test API Keys fails" or wrong-provider-selected reports.
  local configured = {}
  for _, pk in ipairs(PROVIDERS) do
    if S.api_key_map and S.api_key_map[pk.id] and S.api_key_map[pk.id] ~= "" then
      configured[#configured+1] = pk.label or pk.id
    end
  end
  parts[#parts + 1] = "API keys set:      " ..
    (#configured > 0 and tbl_concat(configured, ", ") or "(none)")
  parts[#parts + 1] = ""

  -- Plugin system state (chains, preferences, FX cache). Critical for
  -- diagnosing plugin-resolve / popup / auto-assign bugs.
  parts[#parts + 1] = "--- Plugin System ---"
  local ok_chains, chains = pcall(Code.get_fallback_chains)
  if ok_chains and chains then
    local chain_types = {}
    for k in pairs(chains) do chain_types[#chain_types+1] = k end
    table.sort(chain_types)
    parts[#parts + 1] = "Fallback chains loaded: " .. #chain_types
      .. (#chain_types > 0 and " (" .. tbl_concat(chain_types, ", ") .. ")" or "; check Plugin_Pack.md")
  else
    parts[#parts + 1] = "Fallback chains:        ERROR loading"
  end
  local ok_cache, fx_cache = pcall(FXCache.load)
  if ok_cache and fx_cache then
    local pref_types = fx_cache.preferred_types or {}
    local pref_keys = {}
    for k in pairs(pref_types) do pref_keys[#pref_keys+1] = k end
    table.sort(pref_keys)
    if #pref_keys == 0 then
      parts[#parts + 1] = "Preferred plugins:      (none set)"
    else
      parts[#parts + 1] = "Preferred plugins:"
      for _, k in ipairs(pref_keys) do
        parts[#parts + 1] = "  " .. k .. " = " .. tostring(pref_types[k])
      end
    end
    local plugin_count = 0
    for _ in pairs(fx_cache.plugins or {}) do
      plugin_count = plugin_count + 1
    end
    parts[#parts + 1] = "FX cache size:          " .. plugin_count .. " plugins scanned"
  end
  if CTX._installed_fx_list then
    parts[#parts + 1] = "Installed FX enumerated: " .. #CTX._installed_fx_list
  else
    parts[#parts + 1] = "Installed FX enumerated: (not populated yet this session)"
  end
  if ok_cache and fx_cache then
    parts[#parts + 1] = "FX cache schema:        v" .. tostring(fx_cache._version or "?")
      .. " (expected v" .. FXCACHE_VERSION .. ")"
  end
  -- Plugin_Pack.md status. Missing / unreadable file breaks chains + curated
  -- injection; size signals whether it looks truncated.
  local ref_path = RA.RESOURCES_DIR .. "Plugin_Pack.md"
  local rf = io.open(ref_path, "r")
  if rf then
    local sz = rf:seek("end") or 0
    rf:close()
    parts[#parts + 1] = "Plugin_Pack.md:         present (" .. sz .. " bytes)"
  else
    parts[#parts + 1] = "Plugin_Pack.md:         MISSING at " .. ref_path
  end
  parts[#parts + 1] = ""

  -- Recent Lua/runtime errors. Provider/request errors are stored on chat
  -- messages and appear in the Recent Chat section below.
  if #Diag.errors > 0 then
    parts[#parts + 1] = "--- Recent Lua/Runtime Errors (" .. #Diag.errors .. ") ---"
    for i, e in ipairs(Diag.errors) do
      parts[#parts + 1] = ""
      parts[#parts + 1] = "[" .. i .. "] " .. e.time
      parts[#parts + 1] = "  Error: " .. e.msg
      if e.traceback then
        parts[#parts + 1] = "  Traceback: " .. e.traceback
      end
      if e.code then
        parts[#parts + 1] = "  Code snippet: " .. e.code
      end
    end
  else
    parts[#parts + 1] = "--- No recent Lua/runtime errors ---"
    if S.status == "error" then
      parts[#parts + 1] =
        "Current chat status is error; see Recent Chat below for provider/request details."
    end
  end
  parts[#parts + 1] = ""

  -- Recent chat (last 5 exchanges, truncated) with details metadata.
  -- Trailing blank moved INSIDE the `if` so an empty chat doesn't
  -- leave a stray double-blank between "No recent errors" above and
  -- "Session State" below.
  if #S.display_messages > 0 then
    parts[#parts + 1] = "--- Recent Chat (last 5 exchanges, truncated) ---"
    local start = math.max(1, #S.display_messages - 9)
    for i = start, #S.display_messages do
      local m = S.display_messages[i]
      local content = m.content or ""
      if #content > 300 then content = _utf8_prefix(content, 300) .. "..." end
      parts[#parts + 1] = ""
      parts[#parts + 1] = "[" .. (m.role or "?") .. "] " .. content
      -- Include exchange details when available (context sent, tokens, cost).
      local details = {}
      if m.ctx_label then
        local report_context = type(Diag.sanitize_context_label) == "function"
          and Diag.sanitize_context_label(m.ctx_label, m.attach_names)
          or "contextual"
        details[#details + 1] = "context: contextual"
        details[#details + 1] = "context_components: " .. report_context
      end
      if m.request_status_text then
        details[#details + 1] = "request: " .. m.request_status_text
      end
      if m.model_label then details[#details + 1] = "model: " .. m.model_label end
      if m.error_kind  then details[#details + 1] = "error: " .. m.error_kind end
      if m.tok_in      then details[#details + 1] = "in: " .. m.tok_in end
      if m.tok_out     then details[#details + 1] = "out: " .. m.tok_out end
      if m.tok_cache_read and m.tok_cache_read > 0 then
        details[#details + 1] = "cache_read: " .. m.tok_cache_read
      end
      if m.tok_cache_create and m.tok_cache_create > 0 then
        details[#details + 1] = "cache_create: " .. m.tok_cache_create
      end
      if m.cost_unknown then
        details[#details + 1] = "cost: Unknown"
      elseif m.cost and m.cost > 0 then
        if m.free_tier and MODELS and MODELS.format_cost then
          details[#details + 1] = "cost: Free Tier (would have been ~"
            .. MODELS.format_cost(m.cost) .. ")"
        elseif MODELS and MODELS.format_cost then
          details[#details + 1] = "cost: " .. MODELS.format_cost(m.cost)
        else
          details[#details + 1] = str_format("cost: $%.4f", m.cost)
        end
      end
      if m.fx_cache_label then
        details[#details + 1] = "fx_cache: " .. m.fx_cache_label
      end
      if #details > 0 then
        parts[#parts + 1] = "  [" .. tbl_concat(details, " | ") .. "]"
      end
      -- Include generated code block if present (truncated).
      if m.code_block then
        local code = m.code_block
        if #code > 800 then
          code = _utf8_prefix(code, 800) .. "\n  ...(truncated)"
        end
        parts[#parts + 1] = "  Code block:"
        for cline in code:gmatch("[^\n]+") do
          parts[#parts + 1] = "    " .. cline
        end
      end
    end
    parts[#parts + 1] = ""
  end

  -- Status
  parts[#parts + 1] = "--- Session State ---"
  parts[#parts + 1] = "Status: " .. tostring(S.status)
  parts[#parts + 1] = "Messages: " .. #S.display_messages
  parts[#parts + 1] = "History turns: " .. #S.history
  -- In-flight request state. Only meaningful while a request is
  -- actually pending -- `S.send_time` is non-nil for the duration of
  -- the curl call and cleared on completion. Catches "my send is
  -- stuck" reports where the watchdog hasn't tripped yet.
  if S.send_time then
    local elapsed = reaper.time_precise() - S.send_time
    parts[#parts + 1] = str_format("In-flight request: started %.1fs ago", elapsed)
  end

  -- Resolve popup state: useful for diagnosing "popup didn't fire" reports.
  if S.resolve_popup then
    parts[#parts + 1] = "Resolve popup: ACTIVE (type=" ..
      tostring(S.resolve_popup.type) .. ")"
  elseif S.open_resolve_popup then
    parts[#parts + 1] = "Resolve popup: pending open"
  else
    parts[#parts + 1] = "Resolve popup: inactive"
  end

  -- Pending request state: captures an in-flight or stuck turn.
  local pending_bits = {}
  if S.pending_orig_prompt then pending_bits[#pending_bits+1] = "orig_prompt" end
  if S.pending_snapshot    then pending_bits[#pending_bits+1] = "snapshot"    end
  if S.pending_code        then pending_bits[#pending_bits+1] = "code"        end
  if S.pending_resolves and #S.pending_resolves > 0 then
    pending_bits[#pending_bits+1] = "queued_resolves=" ..
      tbl_concat(S.pending_resolves, ",")
  end
  if #pending_bits > 0 then
    parts[#parts + 1] = "Pending turn state: " .. tbl_concat(pending_bits, ", ")
  end

  -- Sticky context keys pinned this session (e.g. plugin_ref:Pro-Q 4). Shows
  -- what the preempt / resolve flow injected so "model got wrong params"
  -- reports can be traced.
  if S.sticky_context and next(S.sticky_context) then
    local sticky_keys = {}
    for k in pairs(S.sticky_context) do sticky_keys[#sticky_keys+1] = k end
    table.sort(sticky_keys)
    parts[#parts + 1] = "Sticky context pinned: " ..
      tbl_concat(sticky_keys, ", ")
  end

  -- Last script execution result (from the most recent generated-code run).
  -- Captures compile + runtime errors from user-run code. Errors get cleared
  -- on next send, so a non-nil here means "the last thing the user saw".
  if S.last_run_error and S.last_run_error ~= "" then
    parts[#parts + 1] = "Last script error: " .. tostring(S.last_run_error)
  end

  -- FX scan state: catches stuck/in-flight rescans.
  if fx_cache_ui and fx_cache_ui.rescan and fx_cache_ui.rescan.active then
    parts[#parts + 1] = "FX scan in progress: " ..
      tostring(fx_cache_ui.rescan.ident or "?")
  end
  if pref_plugins and pref_plugins.scan and pref_plugins.scan.active then
    parts[#parts + 1] = "Preferred-plugins scan in progress: " ..
      tostring(pref_plugins.scan.phase or "?")
  end

  -- Update-check state: "why isn't my update showing" reports.
  if update and update.state and update.state ~= "idle" then
    parts[#parts + 1] = "Update check state: " .. tostring(update.state)
      .. (update.remote_version and (" (remote v" .. update.remote_version .. ")") or "")
  end

  -- Follow-up note block. Skipped when the caller (the Feedback page's
  -- email flow) embeds this report inside an email body that already
  -- surfaces a tailored log-attach instruction of its own -- printing
  -- both creates redundant back-to-back "please attach the log" text.
  -- Default behaviour (used by the standalone Copy button) keeps the
  -- note in so a hand-pasted report carries the instruction with it.
  if not (opts and opts.skip_followup_note) then
    parts[#parts + 1] = ""
    parts[#parts + 1] = "For detailed bugs (wrong model output, multi-turn issues, API errors),"
    parts[#parts + 1] = "also attach the debug log: " .. Log.path
    parts[#parts + 1] = "Enable \"Enable Advanced Log\" on the Report a Bug page if it's off, reproduce, then send."
  end
  parts[#parts + 1] = ""
  parts[#parts + 1] = "=== End Report ==="
  return tbl_concat(parts, "\n")
end

-- =============================================================================
-- Context bucket functions
-- =============================================================================
-- Each takes a project pointer (proj) captured at send time and returns a
-- plain-text string describing a slice of that project's state. Track indices
-- are reported as 1-based for the assistant's benefit (REAPER API is 0-based).
-- =============================================================================
-- Unified FX parameter cache (JSON)
-- =============================================================================
-- Persists plugin parameter metadata (names, indices, defaults, enum values)
-- to FX_Cache.json. Two top-level maps:
--
--   preferred_types  -- user preferences (one plugin per type). Values are
--                       the chain-entry form (format-agnostic), e.g.
--                       "Pro-Q 4" or "ReJJ/ReEQ/ReEQ.jsfx". Populated either
--                       by Code.ensure_preferred_from_chains at startup or
--                       by user edits on the Preferred Plugins page.
--   plugins          -- live-scanned param data keyed by full enumerated FX
--                       name (e.g. "VST3: Pro-Q 4"). Only populated by
--                       user-triggered scans for non-curated plugins.
--
-- Structure:
--   {
--     "preferred_types": { "eq": "Pro-Q 4", ... },
--     "plugins": {
--       "VST3: Some Plugin": {
--         "param_count": 234,
--         "max_group": 24,
--         "params": [
--           { "idx": 0, "name": "1 Frequency", "default": 0.3040,
--             "display": "100.0 Hz" },
--           { "idx": 5, "name": "1 Shape", "default": 0.0,
--             "display": "Bell", "enum": ["Bell","Low Cut",...] }
--         ]
--       }
--     }
--   }


FXCache = {}

-- In-memory cache. Loaded lazily on first access, invalidated on save.
local _fx_cache_mem = nil

function FXCache.fresh()
  return { _version = FXCACHE_VERSION, preferred_types = {}, plugins = {} }
end

function FXCache.preferred_types_valid(value)
  if type(value) ~= "table" then return false end
  for key, ident in pairs(value) do
    if type(key) ~= "string" or type(ident) ~= "string" then return false end
  end
  return true
end

-- An unversioned file is migrated only when it has the exact historical
-- top-level shape. This salvages genuine pre-version preference data without
-- treating an arbitrary JSON object as an FX cache.
function FXCache.unversioned_shape_valid(data)
  if type(data) ~= "table"
      or not FXCache.preferred_types_valid(data.preferred_types)
      or (data.plugins ~= nil and type(data.plugins) ~= "table") then
    return false
  end
  for key in pairs(data) do
    if key ~= "preferred_types" and key ~= "plugins" then return false end
  end
  return true
end

-- Normalize decoded on-disk data without performing I/O.
-- Returns: cache, needs_persist, disposition.
function FXCache.normalize_loaded(data)
  if type(data) ~= "table" then
    return FXCache.fresh(), false, "invalid_root"
  end

  if data._version == FXCACHE_VERSION then
    if not FXCache.preferred_types_valid(data.preferred_types)
        or type(data.plugins) ~= "table" then
      return FXCache.fresh(), false, "invalid_current"
    end
    return data, false, "current"
  end

  local version = data._version
  local legacy_valid = false
  if version == 1 then
    legacy_valid = FXCache.preferred_types_valid(data.preferred_types)
      and (data.plugins == nil or type(data.plugins) == "table")
  elseif version == nil then
    legacy_valid = FXCache.unversioned_shape_valid(data)
  end
  if legacy_valid then
    return {
      _version = FXCACHE_VERSION,
      preferred_types = data.preferred_types,
      plugins = {},
    }, true, version == nil and "legacy_unversioned" or "v1"
  end

  if version == 1 or version == nil then
    return FXCache.fresh(), false, "invalid_legacy"
  end
  return FXCache.fresh(), false, "unsupported_version"
end

function FXCache.load()
  if _fx_cache_mem then return _fx_cache_mem end
  local ok_f, f = pcall(io.open, RA.FX_CACHE_PATH, "r")
  if not ok_f or not f then
    -- Stamp _version on every fresh-table return so the schema invariant
    -- doesn't depend on a save round-trip to land. Earlier shape varied
    -- per branch (no-file / empty / corrupt / schema-mismatch) which left
    -- a brief window where _fx_cache_mem._version was nil.
    _fx_cache_mem = FXCache.fresh()
    return _fx_cache_mem
  end
  local content = f:read("*a")
  f:close()
  if not content or content == "" then
    _fx_cache_mem = FXCache.fresh()
    return _fx_cache_mem
  end
  local data, err = JSON.decode(content)
  if not data then
    -- Surface the parse error to the debug log. Without this, the user
    -- silently loses their cache on a truncated or corrupted file with
    -- no breadcrumb to triage from -- only the schema-mismatch branch
    -- below logged.
    Log.line("FX_CACHE", "JSON decode failed (" .. tostring(err)
      .. "); discarding cache")
    _fx_cache_mem = FXCache.fresh()
    return _fx_cache_mem
  end

  local normalized, needs_persist, disposition = FXCache.normalize_loaded(data)
  _fx_cache_mem = normalized
  if needs_persist then
    local retained = 0
    for _ in pairs(normalized.preferred_types) do retained = retained + 1 end
    local ok_save, save_err = pcall(FXCache.save, normalized)
    if not ok_save then
      _fx_cache_mem = normalized
      Log.line("FX_CACHE", "migrated " .. disposition .. " cache to v"
        .. FXCACHE_VERSION .. " in memory; retained " .. retained
        .. " preferred types, but persistence raised: " .. tostring(save_err))
    elseif save_err then
      _fx_cache_mem = normalized
      Log.line("FX_CACHE", "migrated " .. disposition .. " cache to v"
        .. FXCACHE_VERSION .. " in memory; retained " .. retained
        .. " preferred types, but persistence failed: " .. tostring(save_err))
    else
      Log.line("FX_CACHE", "migrated " .. disposition .. " cache to v"
        .. FXCACHE_VERSION .. "; retained " .. retained
        .. " preferred types and cleared stale plugin scans")
    end
    return _fx_cache_mem
  end

  if disposition ~= "current" then
    Log.line("FX_CACHE", "rejected cache (" .. tostring(disposition)
      .. ", file=" .. tostring(data._version) .. ", expected="
      .. FXCACHE_VERSION .. "); starting fresh")
  end
  return _fx_cache_mem
end

function FXCache.save(cache)
  cache = cache or _fx_cache_mem
  if not cache then return "No cache data to save." end
  -- Stamp the schema version so future builds can reject old files cleanly.
  cache._version = FXCACHE_VERSION
  local json_str, err = JSON.encode(cache, "  ")
  if not json_str then return "JSON encode failed: " .. tostring(err) end
  -- Atomic write: instance-scoped temp file + rename. AV scanners and abrupt
  -- exits can otherwise leave the 60+ KB cache JSON half-written, breaking
  -- parse on the next session.
  local write_err = Store.atomic_write_file(RA.FX_CACHE_PATH, json_str .. "\n",
    { suffix = Store._atomic_write_suffix() })
  if write_err then return write_err end
  _fx_cache_mem = cache
  return nil  -- success
end

function FXCache.get_plugin(identifier)
  local cache = FXCache.load()
  return cache.plugins[identifier]
end

-- Look up a plugin by fuzzy-matching the identifier against cache keys.
-- Uses bidirectional case-insensitive substring match (each direction catches
-- both "Pro-Q 4" in "VST3: Pro-Q 4 (FabFilter)" and vice versa).
function FXCache.find_plugin(name)
  local cache = FXCache.load()
  -- Exact match first.
  if cache.plugins[name] then return name, cache.plugins[name] end
  -- Fuzzy match against all cached identifiers. Pick the longest
  -- matching key (most specific) instead of `pairs`-first match: when
  -- two cached plugins share a common substring (e.g. "Pro-Q" and
  -- "Pro-Q 4 (FabFilter)") `pairs` order is hash-bucket-dependent, so
  -- the same lookup could pick either across saves/reloads. CTX.fx_params
  -- attaches the cached plugin's enum/range data via this lookup, so
  -- non-deterministic resolution corrupts the [enum: ...] annotation
  -- sent to the model.
  local name_lower = name:lower()
  local best_ident, best_data, best_len = nil, nil, -1
  for ident, data in pairs(cache.plugins) do
    local ident_lower = ident:lower()
    if ident_lower:find(name_lower, 1, true)
       or name_lower:find(ident_lower, 1, true) then
      if #ident > best_len then
        best_ident, best_data, best_len = ident, data, #ident
      end
    end
  end
  return best_ident, best_data
end

-- Mutation counter bumped whenever cache.plugins or cache.preferred_types
-- changes. Lets render-side code cheaply cache lists derived from these
-- (FX cache settings page, preempt scans) and invalidate on change
-- without having to thread invalidation calls through every mutator.
FXCache._mutation_count = 0

function FXCache.put_plugin(identifier, params_list, param_count, max_group, needs_deep_scan)
  local cache = FXCache.load()
  cache.plugins[identifier] = {
    param_count      = param_count or 0,
    max_group        = max_group or 0,
    params           = params_list,
    needs_deep_scan  = needs_deep_scan or nil,
  }
  FXCache._mutation_count = FXCache._mutation_count + 1
  return FXCache.save(cache)
end

function FXCache.remove_plugin(identifier)
  local cache = FXCache.load()
  cache.plugins[identifier] = nil
  FXCache._mutation_count = FXCache._mutation_count + 1
  return FXCache.save(cache)
end

function FXCache.clear_plugins()
  local cache = FXCache.load()
  cache.plugins = {}
  FXCache._mutation_count = FXCache._mutation_count + 1
  return FXCache.save(cache)
end

-- Wipe all type->plugin mappings. Used by the "Clear All" button on the
-- Preferred Plugins page. Does NOT touch cache.plugins (scanned param data
-- stays intact so we don't have to re-scan everything when the user reconfigures).
function FXCache.clear_preferred_types()
  local cache = FXCache.load()
  cache.preferred_types = {}
  FXCache._mutation_count = FXCache._mutation_count + 1
  return FXCache.save(cache)
end

-- Canonicalize an identifier to AddByName-ready form by resolving against
-- the installed-FX list (REAPER 7.42+'s EnumInstalledFX). Chain-entry form
-- ("Twin 3", "Pro-Q 4") is portable across plugin-format namespaces and is
-- what shows up in .RfxChain files, but TrackFX_AddByName works most
-- reliably with the prefixed form ("VST3i: Twin 3"). The model also picks
-- the right plugin format when it sees the prefix instead of guessing.
--
-- Returns (canonical, was_upgraded) where was_upgraded is true if the
-- input was normalized. Bare chain-entry forms resolve to prefixed forms,
-- and prefixed identifiers drop REAPER's trailing vendor suffix because
-- TrackFX_AddByName expects "VST3: Pro-Q 4", not
-- "VST3: Pro-Q 4 (FabFilter)".
-- If no match in installed-FX, or the FX list isn't available (REAPER < 7.42),
-- returns the identifier unchanged apart from safe prefixed-form cleanup.
--
-- type_key is used as a tie-breaker when multiple format variants of the
-- same plugin are installed (e.g., Twin 3 as both VST3i and AUi on Mac):
-- "synth" prefers instrument-variant prefixes (*i:); other types prefer
-- effect-variant prefixes. Without type_key, picks the first match.
local _ADDBYNAME_PREFIXES = {
  "VST3i", "VST3", "VSTi", "VST",
  "AUi", "AU",
  "CLAPi", "CLAP",
  "LV2i", "LV2",
  "DXi", "DX",
  "JS",
}
local _INSTRUMENT_PREFIXES = {
  VST3i = true, VSTi = true, AUi = true, CLAPi = true,
  LV2i = true, DXi = true,
}
local _INSTRUMENT_TYPES = { synth = true }

local function _split_addbyname_identifier(identifier)
  local prefix = identifier:match("^([A-Za-z][A-Za-z0-9]*):")
  if not prefix then return nil, nil end
  for _, p in ipairs(_ADDBYNAME_PREFIXES) do
    if prefix == p then
      local rest = identifier:match("^[A-Za-z][A-Za-z0-9]*:%s*(.+)$")
      return prefix, rest
    end
  end
  return nil, nil
end

local function _strip_vendor_suffix(name)
  -- "VST3: Pro-Q 4 (FabFilter)" -> "VST3: Pro-Q 4". Chain-entry form
  -- doesn't include the vendor, so the canonical form drops it too.
  return (name:gsub("%s*%(.-%)%s*$", ""))
end

-- Classify only authoritative stock fallback identifiers. Curated third-party
-- chains describe normal defaults, not an exclusive product taxonomy, so a
-- user may intentionally assign one of those plug-ins to another role.
function FXCache.preferred_identifier_type(identifier)
  if not Code or type(Code.get_fallback_chains) ~= "function" then return nil end
  local function normalized_name(value)
    value = tostring(value or ""):match("^%s*(.-)%s*$") or ""
    local _, rest = _split_addbyname_identifier(value)
    value = _strip_vendor_suffix(rest or value)
    return (value:match("^%s*(.-)%s*$") or value):lower()
  end
  local wanted = normalized_name(identifier)
  if wanted == "" then return nil end
  local found
  for type_key, spec in pairs(Code.get_fallback_chains() or {}) do
    local stock = type(spec) == "table" and type(spec.stock) == "table"
      and spec.stock.add or nil
    if stock and normalized_name(stock) == wanted then
      type_key = tostring(type_key or ""):lower()
      if found and found ~= type_key then return nil end
      found = type_key
    end
  end
  return found
end

function FXCache.preferred_type_plausible(type_key, identifier)
  local actual = FXCache.preferred_identifier_type(identifier)
  local expected = tostring(type_key or ""):lower()
  if expected == "compressor" and actual == "multiband_compressor" then
    return true, actual
  end
  return actual == nil or actual == expected, actual
end

function FXCache.canonicalize_identifier(type_key, identifier)
  if not identifier or identifier == "" then return identifier, false end
  local prefixed_prefix, prefixed_rest = _split_addbyname_identifier(identifier)
  if prefixed_prefix and prefixed_rest then
    local stripped = _strip_vendor_suffix(prefixed_rest)
    stripped = stripped:match("^%s*(.-)%s*$") or stripped
    if stripped ~= "" then
      local canonical = prefixed_prefix .. ": " .. stripped
      return canonical, canonical ~= identifier
    end
    return identifier, false
  end
  if not CTX or not CTX.populate_installed_fx then return identifier, false end
  CTX.populate_installed_fx()
  local installed = CTX._installed_fx_list
  if not installed or #installed == 0 then return identifier, false end

  local target = _strip_vendor_suffix(identifier)
  target = (target:match("^%s*(.-)%s*$") or target):lower()
  local prefer_instrument = type_key and _INSTRUMENT_TYPES[type_key:lower()] or false
  -- Match against the bare base name (after stripping the AddByName prefix
  -- and a trailing " (Vendor)" suffix), then return the cleaned prefixed
  -- form. The installed list is still the source of truth for the format
  -- prefix, but vendor text is display metadata that breaks AddByName on
  -- some VST3 plugins.
  local best, best_rank = nil, -1
  for _, full in ipairs(installed) do
    local prefix, rest = full:match("^([A-Za-z][A-Za-z0-9]*):%s*(.+)$")
    if prefix and rest then
      local base = _strip_vendor_suffix(rest):lower()
      if base == target then
        local is_instr = _INSTRUMENT_PREFIXES[prefix] == true
        -- Rank prefers (instrument-match for synth-type), then prefers
        -- earlier-in-list (which is roughly REAPER's preferred load order
        -- via _ADDBYNAME_PREFIXES).
        local rank = (prefer_instrument == is_instr) and 1000 or 0
        for i, p in ipairs(_ADDBYNAME_PREFIXES) do
          if prefix == p then rank = rank + (#_ADDBYNAME_PREFIXES - i); break end
        end
        if rank > best_rank then
          best, best_rank = full, rank
        end
      end
    end
  end
  if best then
    local canonical = FXCache.canonicalize_identifier(type_key, best)
    return canonical, canonical ~= identifier
  end
  return identifier, false
end

function FXCache.set_preferred_type(type_key, identifier)
  local plausible, actual =
    FXCache.preferred_type_plausible(type_key, identifier)
  if not plausible then
    return str_format(
      "Cannot save %s as %s; this plug-in is classified as %s.",
      tostring(identifier), tostring(type_key), tostring(actual))
  end
  -- Canonicalize before storing so the on-disk form is AddByName-ready.
  -- Logs the upgrade once (per write) so the operator sees that the legacy
  -- bare-name input was upgraded.
  local canonical, upgraded = FXCache.canonicalize_identifier(type_key, identifier)
  if upgraded then
    Log.line("PREF", str_format(
      "preferred_types.%s = %s -> %s (canonicalized on save)",
      type_key, identifier, canonical))
  end
  local cache = FXCache.load()
  cache.preferred_types[type_key] = canonical
  FXCache._mutation_count = FXCache._mutation_count + 1
  return FXCache.save(cache)
end

-- One-time-per-session migration. Walks cache.preferred_types and upgrades
-- any bare chain-entry forms ("Twin 3") to AddByName-ready prefixed form
-- ("VST3i: Twin 3") via FXCache.canonicalize_identifier. Logs each upgrade
-- as `preferred_types.<type> = old -> new` so legacy data drift is visible
-- once. Saves the cache only if any entry was actually upgraded.
--
-- Idempotent: a second call after the first does nothing because every
-- entry is already prefixed. Safe to call from multiple entry points
-- (Code.ensure_preferred_from_chains startup, render-side first paint).
function FXCache.canonicalize_all_preferred_types()
  if FXCache._canonicalized_session then return 0 end
  if not CTX or not CTX.populate_installed_fx then return 0 end
  CTX.populate_installed_fx()
  if not CTX._installed_fx_list or #CTX._installed_fx_list == 0 then
    -- REAPER < 7.42 or empty FX library. Defer; another call may succeed
    -- once the list is populated. Don't mark as done.
    return 0
  end
  local cache = FXCache.load()
  local upgraded_count = 0
  for type_key, identifier in pairs(cache.preferred_types or {}) do
    local plausible, actual =
      FXCache.preferred_type_plausible(type_key, identifier)
    if not plausible then
      Log.line("PREF", str_format(
        "ignored implausible preferred_types.%s = %s (classified as %s); "
          .. "kept saved value",
        type_key, identifier, tostring(actual)))
    else
      local canonical, upgraded =
        FXCache.canonicalize_identifier(type_key, identifier)
      if upgraded then
        Log.line("PREF", str_format(
          "preferred_types.%s = %s -> %s (canonicalized on load)",
          type_key, identifier, canonical))
        cache.preferred_types[type_key] = canonical
        upgraded_count = upgraded_count + 1
      end
    end
  end
  FXCache._canonicalized_session = true
  if upgraded_count > 0 then
    FXCache._mutation_count = FXCache._mutation_count + 1
    local save_err = FXCache.save(cache)
    if save_err then Store._notify_write_failure("FX cache", save_err) end
  end
  return upgraded_count
end

function FXCache.get_preferred_types()
  local cache = FXCache.load()
  return cache.preferred_types
end

function FXCache.invalidate()
  _fx_cache_mem = nil
  FXCache._mutation_count = (FXCache._mutation_count or 0) + 1
  -- Clear the session migration flag too so a fresh load (e.g., after a
  -- corrupt-cache reset, an external edit, or a manual reload) will
  -- re-run canonicalization on whatever's now on disk.
  FXCache._canonicalized_session = nil
end

-- =============================================================================
-- Context bucket builders (CTX)
-- =============================================================================
-- Stored in a table to conserve top-level local variable slots
-- (Lua 5.x 200-local limit). Each function takes (proj) and returns a string.
-- =============================================================================
-- Context sidecar load (eager, fail-closed)
-- =============================================================================
-- Loads the request-context runtime into a narrow environment. If it cannot load,
-- fallbacks keep startup/recovery usable while guarded send paths fail closed
-- before they depend on missing context helpers.
RA.Context = RA.Context or { loaded = false, error = nil }

function RA.context_unavailable_message(action)
  local suffix = action and tostring(action) or "before building context"
  return "Context runtime unavailable; repair or update ReaAssist " .. suffix .. "."
end

function RA.context_loaded()
  return RA.Context and RA.Context.loaded == true
end

function RA.fail_context_unavailable(action, status)
  local msg = RA.context_unavailable_message(action)
  if Log and Log.add_error then Log.add_error(msg) end
  if S then
    S.status = status or "idle"
    S.scroll_to_bottom = true
  end
  return false
end

function RA.install_context_fallbacks(reason)
  RA.Context = RA.Context or {}
  RA.Context.loaded = false
  RA.Context.error = tostring(reason or "unknown error")
  if Log and Log.line then
    Log.line("CONTEXT", "Context.lua unavailable: " .. RA.Context.error)
  end

  -- Keep every main-file call site callable in degraded mode. Public send paths
  -- still block on RA.context_loaded(), so these stubs are for recovery and
  -- defensive cleanup rather than a partial context runtime.
  CTX = CTX or {}
  CTX._installed_fx_list = CTX._installed_fx_list or {}
  CTX._installed_fx_list_deduped = CTX._installed_fx_list_deduped or {}
  CTX._installed_fx_entries = CTX._installed_fx_entries or {}
  _is_fabfilter_ident = _is_fabfilter_ident or function() return false end

  local function unavailable(action)
    return RA.context_unavailable_message(action)
  end
  local function unavailable_err(action)
    return nil, unavailable(action)
  end
  local function false_unavailable(action)
    return false, unavailable(action)
  end

  function CTX.reaper_version()
    return "REAPER version: " .. tostring(reaper.GetAppVersion and reaper.GetAppVersion() or "unknown")
  end
  function CTX.reaassist_version()
    return "ReaAssist version: " .. tostring(CFG.VERSION or "unknown")
  end
  function CTX.extension_status()
    return unavailable("before reading extension status")
  end
  function CTX.ai_selection_status()
    return unavailable("before reading AI selection")
  end
  function CTX.reaassist_settings_status()
    return unavailable("before reading ReaAssist settings")
  end
  function CTX.diagnostics_status()
    return unavailable("before reading diagnostics settings")
  end
  function CTX.local_read_answer()
    return nil
  end
  function CTX.preempt_buckets_for_prompt()
    return nil
  end
  function CTX.build_snapshot()
    return unavailable("before building project context")
  end
  CTX.PLUGIN_REF_ALIASES = CTX.PLUGIN_REF_ALIASES or {}
  CTX.CHAIN_PHRASE_HINTS = CTX.CHAIN_PHRASE_HINTS or {}
  function CTX.resolve_pending_project()
    return reaper.EnumProjects and reaper.EnumProjects(-1) or 0
  end
  function CTX.docs_section_list() return "" end
  function CTX.curated_for_ident() return nil end

  function CTX.docs() return unavailable_err("before loading REAPER docs") end
  function CTX.docs_section_canonical() return nil end
  function CTX.docs_extended() return unavailable_err("before loading extended docs") end
  function CTX.docs_section() return unavailable_err("before loading docs sections") end
  function CTX.recent_reaper_changes() return unavailable_err("before loading recent changes") end
  function CTX.prompt_bundle() return unavailable_err("before loading prompt bundles") end
  function CTX.midi() return unavailable_err("before loading MIDI reference") end
  function CTX.theme() return unavailable_err("before loading theme reference") end
  function CTX.plugin_ref() return unavailable_err("before loading plugin reference") end
  function CTX.installed_fx() return unavailable_err("before reading installed FX") end
  function CTX.preferred_plugins() return unavailable_err("before reading preferred plugins") end
  function CTX.fx_params() return unavailable_err("before scanning FX parameters") end
  function CTX.fx_inspect_load() return nil, nil, nil, unavailable("before inspecting FX") end
  function CTX.format_fx_params() return unavailable("before formatting FX parameters") end
  function CTX.scan_fx_params() return {}, 0, 0, false end
  function CTX.scan_fx_params_deep_body() return false_unavailable("before deep-scanning FX parameters") end

  function CTX.fx_filter_parse(payload)
    return { name = tostring(payload or "") }
  end
  function CTX.fx_filter_key(filters)
    local parts = {}
    if type(filters) == "table" then
      for i, entry in ipairs(filters) do
        parts[i] = type(entry) == "table" and tostring(entry.name or "") or tostring(entry or "")
      end
    end
    return table.concat(parts, "/")
  end
  function CTX.fx_filter_names_only(filters)
    local names = {}
    if type(filters) == "table" then
      for _, entry in ipairs(filters) do
        names[#names + 1] = type(entry) == "table" and tostring(entry.name or "") or tostring(entry or "")
      end
    end
    return names
  end
  function CTX.fx_name_matches() return false end
  function CTX.populate_installed_fx()
    CTX._installed_fx_list = {}
    CTX._installed_fx_list_deduped = {}
    CTX._installed_fx_entries = {}
    return false
  end
  function CTX.ensure_plugin_pack_cache() return false end
  function CTX.ensure_plugin_ref_cache()
    return CTX.ensure_plugin_pack_cache()
  end

  function CTX.load_pref_plugins() return false end
  function CTX.save_pref_plugins() return unavailable("before saving preferred plugins") end
  function CTX.pref_plugins_scan_start()
    if pref_plugins and pref_plugins.scan then
      pref_plugins.scan.active = false
      pref_plugins.scan.status = unavailable("before scanning preferred plugins")
    end
    return false
  end
  function CTX.pref_plugins_scan_read()
    if pref_plugins and pref_plugins.scan then pref_plugins.scan.active = false end
    return false
  end
  function CTX.start_deep_scan(opts)
    if type(opts) == "table" and type(opts.on_cancel) == "function" then
      opts.on_cancel("context_runtime_unavailable")
    end
    return false
  end
  function CTX.pump_deep_scan()
    if deep_scan then deep_scan.active = false end
    return false
  end
  function CTX.cancel_deep_scan()
    if deep_scan then deep_scan.active = false end
    return false
  end

  Theme = Theme or {}
  Theme.restore_backups = Theme.restore_backups or function() end
  Theme.save_to_file = Theme.save_to_file or function()
    return false, unavailable("before saving theme changes")
  end

  label_to_type_key = label_to_type_key or function(label)
    local canonical = tostring(label or "")
    canonical = (canonical:match("^%s*(.-)%s*$") or ""):lower()
    canonical = canonical:gsub("[%s%-]+", "_")
    return (PREF_PLUGIN_ALIASES and PREF_PLUGIN_ALIASES[canonical]) or canonical
  end
  pref_plugins_best_match = pref_plugins_best_match or function() return nil, 0 end
  pref_plugins_rank_matches = pref_plugins_rank_matches or function() return {} end

  Code = Code or {}
  Code.is_curated_plugin = Code.is_curated_plugin or function() return false end
  Code.get_stock_fallback = Code.get_stock_fallback or function() return nil end
end

function RA.load_context()
  RA.Context = RA.Context or {}
  local path = RA.RESOURCES_DIR .. "Context.lua"
  local env = setmetatable({
    CTX = CTX or {},
    str_format = str_format,
    tbl_concat = tbl_concat,
    read_file_text = read_file_text,
    math_floor = math_floor,
    math_min = math_min,
    math_max = math_max,
    time_precise = time_precise,
    R_CountTracks = R_CountTracks,
    R_GetTrack = R_GetTrack,
    R_GetTrackName = R_GetTrackName,
    R_CountTrackMediaItems = R_CountTrackMediaItems,
    R_GetMediaTrackInfo_Value = R_GetMediaTrackInfo_Value,
    R_IsTrackSelected = R_IsTrackSelected,
    R_TrackFX_GetCount = R_TrackFX_GetCount,
    R_TrackFX_GetFXName = R_TrackFX_GetFXName,
    R_TrackFX_GetNumParams = R_TrackFX_GetNumParams,
    R_TrackFX_GetParamName = R_TrackFX_GetParamName,
    R_TrackFX_GetParam = R_TrackFX_GetParam,
    R_TrackFX_GetFormattedParamValue = R_TrackFX_GetFormattedParamValue,
    R_CountSelectedMediaItems = R_CountSelectedMediaItems,
    R_GetSelectedMediaItem = R_GetSelectedMediaItem,
    R_GetMediaItemInfo_Value = R_GetMediaItemInfo_Value,
    R_GetMediaItem_Track = R_GetMediaItem_Track,
    R_EnumProjectMarkers3 = R_EnumProjectMarkers3,
    R_CountProjectMarkers = R_CountProjectMarkers,
    PREF_PLUGIN_ALIASES = PREF_PLUGIN_ALIASES,
  }, { __index = _G })
  local chunk, load_err = loadfile(path, "t", env)
  if not chunk then
    RA.install_context_fallbacks(load_err)
    return false
  end
  local ok, err = pcall(chunk)
  if not ok then
    RA.install_context_fallbacks(err)
    return false
  end

  CTX = env.CTX or CTX
  _is_fabfilter_ident = env._is_fabfilter_ident or _is_fabfilter_ident
  Theme = env.Theme or Theme
  label_to_type_key = env.label_to_type_key or label_to_type_key
  pref_plugins_best_match = env.pref_plugins_best_match or pref_plugins_best_match
  pref_plugins_rank_matches = env.pref_plugins_rank_matches or pref_plugins_rank_matches

  local required = {
    { "CTX.docs", CTX and CTX.docs },
    { "CTX.docs_section_canonical", CTX and CTX.docs_section_canonical },
    { "CTX.docs_section_list", CTX and CTX.docs_section_list },
    { "CTX.preempt_buckets_for_prompt", CTX and CTX.preempt_buckets_for_prompt },
    { "CTX.build_snapshot", CTX and CTX.build_snapshot },
    { "CTX.resolve_pending_project", CTX and CTX.resolve_pending_project },
    { "CTX.curated_for_ident", CTX and CTX.curated_for_ident },
    { "CTX.CHAIN_PHRASE_HINTS", CTX and CTX.CHAIN_PHRASE_HINTS, "table" },
    { "_is_fabfilter_ident", _is_fabfilter_ident },
    { "Theme.restore_backups", Theme and Theme.restore_backups },
    { "Theme.save_to_file", Theme and Theme.save_to_file },
    { "label_to_type_key", label_to_type_key },
    { "pref_plugins_best_match", pref_plugins_best_match },
    { "pref_plugins_rank_matches", pref_plugins_rank_matches },
    { "Code.is_curated_plugin", Code and Code.is_curated_plugin },
    { "Code.get_stock_fallback", Code and Code.get_stock_fallback },
  }
  for _, item in ipairs(required) do
    if type(item[2]) ~= (item[3] or "function") then
      RA.install_context_fallbacks("missing required context symbol: " .. item[1])
      return false
    end
  end

  RA.Context.loaded = true
  RA.Context.error = nil
  return true
end

Startup.mark("context_load_start")
RA.load_context()
Startup.mark("context_load_done")

-- A marker owned by the installation can suppress every network-backed update
-- lane. This is separate from the saved preference because development and
-- test installs may intentionally differ from the published manifest. The
-- completeness sentinel remains active and can still stop a session if a
-- required file is actually missing.
RA.UPDATE_CHECKS_DISABLED_MARKER = "disable_update_checks.flag"
function RA.update_checks_disabled_by_marker()
  local f = io.open(RA.DATA_DIR .. RA.UPDATE_CHECKS_DISABLED_MARKER, "rb")
  if not f then return false end
  f:close()
  return true
end
RA.UPDATE_CHECKS_DISABLED = RA.update_checks_disabled_by_marker()
if RA.UPDATE_CHECKS_DISABLED then
  CFG.UPDATE_BASE_URL = ""
  if Log and Log.line then
    Log.line("UPDATE", "update and support-file maintenance disabled by Data\\"
      .. RA.UPDATE_CHECKS_DISABLED_MARKER)
  end
end

-- =============================================================================
-- Auto-update module
-- =============================================================================
-- Non-blocking update checker. At most one ATTEMPT per session, after the
-- first request (when prefs.update_check is on and UPDATE_BASE_URL is
-- configured; a session that never sends a request never arms it), and the
-- attempt is what is bounded rather than the check: the trigger marks the
-- session fired before calling check_start, and check_start returns without
-- fetching anything when the updater or a font or language download is
-- already busy, with no retry that session. When it does get through it
-- fires an async curl for manifest.json;
-- if a newer version exists the UI offers "Update Available". Each file
-- is fetched, SHA-256 verified against the manifest, and written to the
-- script directory (any hash mismatch rolls back the whole update). An
-- organic check failure stays silent (update.state = "idle"); only a
-- user-forced Repair surfaces errors via Updater._set_failure.
-- Manifest schema: see .tools/gen_manifest.py.

-- =============================================================================
-- SHA-256 (pure Lua, no external dependencies)
-- =============================================================================
-- Minimal implementation for update integrity verification. Operates on
-- 8-bit byte strings via string.byte and Lua 5.3+ integer operators.
-- Compression uses operators directly to avoid per-bit-operation calls.
--
-- Two interfaces:
--   sha256_hash(msg)              -- single-shot. Off the per-frame hot
--                                    path: startup journal recovery (rare
--                                    crash-resolution) and sidecars via
--                                    RA.sha256_hex. The apply pipeline
--                                    itself verifies staged files with the
--                                    native hasher (chunked pure-Lua as
--                                    fallback), never single-shot.
--   _SHA.create(content)          -- chunked: returns state ready for step().
--   _SHA.step(state, max_blocks)  -- process up to N 64-byte blocks; returns
--                                    true when state is exhausted.
--   _SHA.finalize(state)          -- return hex digest of completed state.
--
-- Large files can still cause a visible hitch in single-shot mode.
-- The chunked interface lets
-- Updater.tick_sha_diff process work for a per-frame time budget
-- (CFG.UPDATE_SHA_TIME_BUDGET), spreading the same total work across
-- many frames so each frame stays inside the budget regardless of CPU.
local sha256_hash
local _SHA = {}
do
  local band   = load("return function(a,b) return a & b end")()
  local rshift = load("return function(a,n) return (a >> n) & 0xFFFFFFFF end")()

  local K = {
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5,
    0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
    0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3,
    0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
    0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc,
    0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7,
    0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13,
    0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3,
    0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5,
    0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
    0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208,
    0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
  }

  -- Build incremental state from a plain content string. Pre-pads the
  -- message to a 64-byte boundary so subsequent step() calls only need
  -- to compress complete 64-byte blocks (no partial-block bookkeeping
  -- across calls). Pre-padding cost is O(n) memcpy, negligible vs the
  -- compression work that follows.
  function _SHA.create(content)
    local len = #content
    local extra = 64 - ((len + 9) % 64)
    if extra == 64 then extra = 0 end
    local msg = content .. "\128" .. ("\0"):rep(extra + 4)
       .. string.char(
            band(rshift(len * 8, 24), 0xFF),
            band(rshift(len * 8, 16), 0xFF),
            band(rshift(len * 8, 8), 0xFF),
            band(len * 8, 0xFF))
    return {
      msg = msg,
      pos = 1,                        -- next byte (1-indexed) to compress
      h0  = 0x6a09e667, h1 = 0xbb67ae85,
      h2  = 0x3c6ef372, h3 = 0xa54ff53a,
      h4  = 0x510e527f, h5 = 0x9b05688c,
      h6  = 0x1f83d9ab, h7 = 0x5be0cd19,
    }
  end

  -- Process up to max_blocks complete 64-byte chunks starting at
  -- state.pos. Updates state.h0..h7 and advances state.pos. Returns
  -- true when all blocks have been compressed (state ready for
  -- finalize), false when more remain. Pass math.huge to drain all
  -- remaining blocks in one call (single-shot mode).
  function _SHA.step(state, max_blocks)
    local msg = state.msg
    local total = #msg
    local h0, h1, h2, h3 = state.h0, state.h1, state.h2, state.h3
    local h4, h5, h6, h7 = state.h4, state.h5, state.h6, state.h7
    local pos = state.pos
    local processed = 0
    while pos <= total and processed < max_blocks do
      local W = {}
      for t = 1, 16 do
        local b = pos + (t - 1) * 4
        W[t] = (string.byte(msg, b) << 24)
             + (string.byte(msg, b + 1) << 16)
             + (string.byte(msg, b + 2) << 8)
             + string.byte(msg, b + 3)
      end
      for t = 17, 64 do
        local x, y = W[t-15], W[t-2]
        local s0 = (((x >> 7) | (x << 25)) ~ ((x >> 18) | (x << 14)) ~ (x >> 3)) & 0xFFFFFFFF
        local s1 = (((y >> 17) | (y << 15)) ~ ((y >> 19) | (y << 13)) ~ (y >> 10)) & 0xFFFFFFFF
        W[t] = (W[t-16] + s0 + W[t-7] + s1) & 0xFFFFFFFF
      end
      local a, b, c, d, e, f, g, h = h0, h1, h2, h3, h4, h5, h6, h7
      for t = 1, 64 do
        local S1 = (((e >> 6) | (e << 26)) ~ ((e >> 11) | (e << 21)) ~ ((e >> 25) | (e << 7))) & 0xFFFFFFFF
        local ch = (e & f) ~ ((~e) & g)
        local temp1 = (h + S1 + ch + K[t] + W[t]) & 0xFFFFFFFF
        local S0 = (((a >> 2) | (a << 30)) ~ ((a >> 13) | (a << 19)) ~ ((a >> 22) | (a << 10))) & 0xFFFFFFFF
        local maj = (a & b) ~ (a & c) ~ (b & c)
        local temp2 = (S0 + maj) & 0xFFFFFFFF
        h = g; g = f; f = e; e = (d + temp1) & 0xFFFFFFFF
        d = c; c = b; b = a; a = (temp1 + temp2) & 0xFFFFFFFF
      end
      h0 = (h0 + a) & 0xFFFFFFFF; h1 = (h1 + b) & 0xFFFFFFFF
      h2 = (h2 + c) & 0xFFFFFFFF; h3 = (h3 + d) & 0xFFFFFFFF
      h4 = (h4 + e) & 0xFFFFFFFF; h5 = (h5 + f) & 0xFFFFFFFF
      h6 = (h6 + g) & 0xFFFFFFFF; h7 = (h7 + h) & 0xFFFFFFFF
      pos = pos + 64
      processed = processed + 1
    end
    state.h0, state.h1, state.h2, state.h3 = h0, h1, h2, h3
    state.h4, state.h5, state.h6, state.h7 = h4, h5, h6, h7
    state.pos = pos
    return pos > total
  end

  function _SHA.finalize(state)
    return string.format("%08x%08x%08x%08x%08x%08x%08x%08x",
      state.h0, state.h1, state.h2, state.h3,
      state.h4, state.h5, state.h6, state.h7)
  end

  sha256_hash = function(msg)
    local s = _SHA.create(msg)
    _SHA.step(s, math.huge)
    return _SHA.finalize(s)
  end
end

-- Expose the updater's SHA helpers to sidecars. Diag.lua uses them when
-- available for feedback-upload integrity, and falls back internally if absent.
RA.sha256_hex = sha256_hash
RA.sha256_create = function(content) return _SHA.create(content) end
RA.sha256_step = function(state, max_blocks) return _SHA.step(state, max_blocks) end
RA.sha256_finalize = function(state) return _SHA.finalize(state) end

-- =============================================================================
-- Local deterministic action modules
-- =============================================================================
-- These sidecars hold focused, non-LLM feature implementations that are too
-- substantial to keep in ReaAssist.lua. They are non-critical at startup:
-- a missing/corrupt module disables that local action but must not prevent the
-- chat UI, updater, or recovery flow from loading.
RA.Local = RA.Local or {}
do
  local path = RA.RESOURCES_DIR .. "Local" .. RA.SEP .. "init.lua"
  if RA._file_exists(path) then
    local ok, modules = pcall(dofile, path)
    if ok and type(modules) == "table" then
      for name, module in pairs(modules) do
        RA.Local[name] = module
      end
    elseif type(Log) == "table" and type(Log.line) == "function" then
      Log.line("LOCAL",
        "Optional local module loader failed; local-only features disabled.")
    end
  end
end

-- Cross-chunk namespace. The UI file's Update-Available and File-
-- Integrity dialogs call Updater.download_start / Updater.force_reinstall,
-- so this table must be a plain global (chunk-local `local` would make
-- it invisible to the dofile'd UI chunk). The state table next to it is
-- lowercase `update`.
Updater = {}

function Updater.url_encode_path(path)
  return tostring(path or ""):gsub("([^%w%-%._~/])", function(ch)
    return string.format("%%%02X", string.byte(ch))
  end)
end

-- Build a download URL. `base` is optional: manifest fetches always use
-- the live CFG.UPDATE_BASE_URL (mutable main, cache-busted by
-- fire_get_to), while payload downloads pass the base returned by
-- payload_base_url below so releases fetch from their immutable tag.
function Updater.url_for(filename, base)
  base = tostring(base or CFG.UPDATE_BASE_URL or ""):gsub("/+$", "")
  return base .. "/" .. Updater.url_encode_path(filename)
end

-- Payload base derivation (tag-pinned downloads). The manifest is
-- fetched cache-busted from mutable `main`, but GitHub's raw CDN caches
-- payload URLs for minutes, so right after a release push a fresh
-- manifest can reference payloads the CDN still serves stale: sha_verify
-- failures, false repair popups, and a TOCTOU when a release lands
-- between the manifest fetch and the downloads. Fetching payloads from
-- the release TAG removes all of that: the tag ref is immutable and, by
-- release-flow ordering (tag pushed before main moves), resolvable by
-- the time any manifest references its version.
--
-- Gates (ALL must hold, anything else falls back to today's behavior):
--   1. manifest version is exactly three digit components -- public
--      releases only. Four-component test-branch versions and anything
--      malformed stay on the configured base.
--   2. no dev update override is active (the ExtState override rewrites
--      the base and must keep full control).
--   3. the live base equals the LITERAL stock GitHub main base below.
--      This must be a hardcoded literal, not a startup snapshot: the
--      UpdateSmoke harness patches the UPDATE_BASE_URL constant in the
--      installed source (no ExtState involved), and a snapshot would
--      capture the patched value and derive nonexistent tag URLs for
--      its fake candidate versions. A custom or test-branch base fails
--      this comparison the same way. If the shipped default base ever
--      changes, this literal must change with it; until then the gate
--      simply stays off, which is the safe direction.
-- The host and path template are hardcoded; only the digit-validated
-- version string is interpolated. Both spellings end in ReaAssist/App:
-- payload names come from the App-relative body manifest, so the base they
-- hang off has to be the App view too, at the tag exactly as on main.
--
-- The repair purpose uses the same derivation deliberately: a repair
-- for version X fetches tag vX, which is immutable and is exactly the
-- tree the manifest describing X was generated from, so repairs can no
-- longer be poisoned by a mid-repair release or CDN propagation lag.
function Updater.payload_base_url(manifest_version)
  local version = tostring(manifest_version or "")
  if version:match("^%d+%.%d+%.%d+$")
      and CFG.UPDATE_OVERRIDE_MODE == nil
      and CFG.UPDATE_BASE_URL == "https://raw.githubusercontent.com/"
        .. "michaelbriggsaudio/mbriggs-reaper/main/ReaAssist/App" then
    return "https://raw.githubusercontent.com/michaelbriggsaudio/"
      .. "mbriggs-reaper/refs/tags/v" .. version .. "/ReaAssist/App"
  end
  return CFG.UPDATE_BASE_URL
end

-- Stamp a structured failure reason onto the update state so the
-- Bootstrap repair prompt can show the user *why* the last attempt
-- failed instead of silently re-rendering the Repair button. Also
-- emits a Log.line so the active debug log records the same
-- detail for post-mortem.
function Updater._set_failure(step, err)
  update.last_step  = step
  update.last_error = err
  Log.line("UPDATE", string.format("fail [%s]: %s",
                                   tostring(step), tostring(err)))
end

-- True when the updater is mid-flight on a fetch, verification, download,
-- or apply. Centralises the busy-state predicate that gates re-entry on
-- force_reinstall, manual_check, the chat-piggyback check_start, and the
-- UI's ver_busy / busy disabled-button flags. A single helper means a
-- future state addition only needs to land in one place rather than five
-- separate condition lists.
function Updater.is_busy()
  return update.state == "checking"
      or update.state == "verifying"
      or update.state == "downloading_batch"
      or update.state == "verifying_download"
      or update.state == "applying"
end

function Updater.font_download_busy()
  return OptionalFonts and OptionalFonts.is_busy and OptionalFonts.is_busy()
end

function Updater.language_download_busy()
  return LangPacks and LangPacks.is_busy and LangPacks.is_busy()
end

-- Compare two semver strings numerically. Returns true if remote > local.
function Updater.is_newer(remote_ver, local_ver)
  local function parse(v)
    local parts = {}
    for n in v:gmatch("(%d+)") do parts[#parts+1] = tonumber(n) end
    return parts
  end
  local r, l = parse(remote_ver), parse(local_ver)
  for i = 1, math_max(#r, #l) do
    local rv, lv = r[i] or 0, l[i] or 0
    if rv > lv then return true end
    if rv < lv then return false end
  end
  return false
end

-- Fire an async curl GET. Writes response to out_path, exit code to exit_path.
-- Returns true if launched, false if URL is empty or launch fails.
function RA.fire_get_to(url, out_path, exit_path, timeout, send_state, log_tag, opts)
  if not url or url == "" then return false end
  if send_state then send_state.request_url = tostring(url or "") end
  os.remove(out_path)
  os.remove(exit_path)
  opts = type(opts) == "table" and opts or {}
  -- Cache-busting: append a unix-time query parameter to the URL.
  -- GitHub's raw CDN keys on URL, so a unique timestamp guarantees a
  -- cache miss on every check. This eliminates the propagation race we
  -- have hit during rapid test-branch iteration where a new manifest
  -- and its updated file SHAs can be cached separately, leading to
  -- false repair popups on first launch after an update push.
  --
  -- We previously also sent Cache-Control / Pragma no-cache headers,
  -- but on Windows the literal double quotes around those header
  -- values broke the outer PowerShell -Command argument parse: the
  -- inner `"` terminated PowerShell's -Command string early, curl
  -- never ran, and the manual update check toasted "Could not reach
  -- update server" on every press. The timestamp query alone is
  -- sufficient (a CDN cannot serve a cached response for a URL it has
  -- never seen before), so the headers were dropped.
  -- Content-addressed payload downloads can opt out because their SHA-256
  -- verification already rejects stale or corrupted bytes, and keeping the
  -- URL stable lets CDNs serve large fonts/lang packs/update files from cache.
  if opts.cache_bust == false then
    if send_state then send_state.request_url_with_cache_bust = nil end
  else
    local sep = url:find("?", 1, true) and "&" or "?"
    -- Cache-bust query: combine os.time() seconds with time_precise()
    -- millisecond fraction so two fetches inside the same second still
    -- produce distinct URLs. Pure os.time() collides on rapid Retry
    -- clicks (the v0.9.8.22 CDN-propagation fix encourages users to
    -- click Retry repeatedly), and a duplicate URL re-hits whatever
    -- the CDN has cached for that key, defeating the whole point.
    local ms = math.floor((time_precise() % 1) * 1000)
    url = url .. sep .. "_=" .. tostring(os.time())
                    .. string.format("%03d", ms)
    if send_state then send_state.request_url_with_cache_bust = url end
  end
  timeout = timeout or CFG.UPDATE_CURL_TIMEOUT
  log_tag = log_tag or "NET"
  -- -f (both platforms below) makes curl exit nonzero (22) on HTTP >= 400
  -- instead of writing the error body to out_path with exit 0. Without it
  -- a 404/500 page lands in the output file and gets misclassified
  -- downstream as a malformed manifest or a SHA-256 mismatch; with it the
  -- poll() error branch reports the network/server failure it actually is.
  --
  -- opts.retry: payload downloads opt in to bounded retries for transient
  -- errors (timeouts, connection resets, HTTP 408/429/5xx). curl applies
  -- --max-time PER ATTEMPT, not across the whole run (verified: 3 attempts
  -- at --max-time 3 took ~12 s wall), so unbounded retries could blow past
  -- the Updater.poll watchdog (UPDATE_CURL_TIMEOUT + 10 = 25 s from
  -- send_time). --retry-max-time 5 closes the retry window instead: a
  -- retry may only START while total elapsed time is under 5 s, so the
  -- worst case is a retry starting just before 5 s that runs one full
  -- 15 s attempt (~20 s), leaving ~5 s of watchdog budget for process
  -- launch overhead. A first attempt that itself times out (15 s) already
  -- exceeds the window and never retries, so the pure-timeout case costs
  -- the same as before. Manifest checks stay single-attempt to keep the
  -- once-per-session check light. --retry-connrefused is deliberately not
  -- used: macOS system curl older than 7.52 treats it as a hard usage
  -- error, and connection-refused failures are instant anyway.
  local retry_flags = opts.retry and " --retry 2 --retry-max-time 5" or ""
  if type(opts.max_bytes) == "number" and opts.max_bytes > 0 then
    retry_flags = retry_flags .. " --max-filesize " .. tostring(math.floor(opts.max_bytes))
  end
  if RA.IS_WINDOWS then
    -- Defensive guard limited to characters that cannot legitimately
    -- appear in a valid Windows path OR a valid URL: " < > | are all
    -- reserved by Windows filenames and are also invalid in URLs (or,
    -- for ", a quote-terminator that would break the inner cmd arg
    -- parse). Other cmd-significant chars (& ^ ( ) %) ARE valid in
    -- Windows paths ("Program Files (x86)", user dirs like "R&D")
    -- and in URL query strings; the triple-quoted argument passing
    -- protects them, so we must NOT reject them or update / repair
    -- would silently fail for users on those paths.
    for _, c in ipairs({'"', '<', '>', '|'}) do
      if url:find(c, 1, true)
          or out_path:find(c, 1, true)
          or exit_path:find(c, 1, true) then
        Log.line(log_tag, string.format(
          "fire_get: refusing to launch with cmd-unsafe character '%s' "
          .. "in URL or path", c))
        return false
      end
    end
    local cmd_line = str_format(
      'curl -sf --connect-timeout 10 --max-time %d%s'
      .. ' "%s" -o """%s"""'
      .. ' & call echo ^%%errorlevel^%% > """%s"""',
      timeout, retry_flags, url, out_path, exit_path)
    local ps_cmd = str_format(
      'powershell -NoProfile -WindowStyle Hidden'
      .. ' -Command "Start-Process cmd -ArgumentList \'/c %s\''
      .. ' -WindowStyle Hidden"',
      Shell.ps_escape(cmd_line))
    reaper.ExecProcess(ps_cmd, 5000)
  else
    -- Single-quote the URL on POSIX shells. Double quotes still allow
    -- $(...) and `...` command substitution, so a malicious or malformed
    -- manifest filename baked into the URL could execute. is_safe_filename
    -- already blocks shell-sensitive characters, but quoting cleanly here
    -- closes the gap as defense-in-depth.
    local cmd = str_format(
      '(curl -sf --connect-timeout 10 --max-time %d%s'
      .. ' %s -o %s ; echo $? > %s) &',
      timeout, retry_flags, Shell.sh_quote(url), Shell.sh_quote(out_path),
      Shell.sh_quote(exit_path))
    os.execute(cmd)
  end
  -- NOTE: Neither ExecProcess nor os.execute reliably indicate launch failure,
  -- so send_time is set unconditionally. If the process never started, the
  -- watchdog in Updater.poll() will time out after UPDATE_CURL_TIMEOUT + 10s.
  if send_state then send_state.send_time = time_precise() end
  return true
end

function Updater.fire_get(url, out_path, exit_path, opts)
  return RA.fire_get_to(url, out_path, exit_path,
    CFG.UPDATE_CURL_TIMEOUT, update, "UPDATE", opts)
end

LangPacks = LangPacks or { download = { state = "idle" } }

function LangPacks._t(key, values, fallback)
  return (RA and RA.t and RA.t(key, values, fallback)) or fallback or key
end

function LangPacks._display_language(code)
  local idx = CFG and CFG.legacy_idx_for_language_code
    and CFG.legacy_idx_for_language_code(code)
  return (idx and CFG and CFG.prompt_language_name_for_idx
      and CFG.prompt_language_name_for_idx(idx))
    or tostring(code or "")
end

function LangPacks.is_busy()
  local d = LangPacks.download or {}
  return d.state == "index_downloading"
      or d.state == "ui_downloading"
end

function LangPacks.ensure_dirs()
  if I18N and I18N.ensure_cache_dirs then return I18N.ensure_cache_dirs() end
  if not (reaper and reaper.RecursiveCreateDirectory) then return false end
  if not (RA and RA.LANG_DIR and RA.LANG_UI_DIR
      and RA.LANG_FONT_DIR and RA.LANG_TMP_DIR) then return false end
  reaper.RecursiveCreateDirectory(RA.LANG_DIR, 0)
  reaper.RecursiveCreateDirectory(RA.LANG_UI_DIR, 0)
  reaper.RecursiveCreateDirectory(RA.LANG_FONT_DIR, 0)
  reaper.RecursiveCreateDirectory(RA.LANG_TMP_DIR, 0)
  return true
end

function LangPacks.ensure_dir(kind)
  if I18N and I18N.ensure_cache_dir then return I18N.ensure_cache_dir(kind) end
  if not (reaper and reaper.RecursiveCreateDirectory) then return false end
  kind = tostring(kind or "root")
  local dir
  if kind == "root" then
    dir = RA and RA.LANG_DIR
  elseif kind == "ui" then
    dir = RA and RA.LANG_UI_DIR
  elseif kind == "fonts" then
    dir = RA and RA.LANG_FONT_DIR
  elseif kind == "tmp" then
    dir = RA and RA.LANG_TMP_DIR
  end
  if not dir then return false end
  reaper.RecursiveCreateDirectory(dir, 0)
  return true
end

function LangPacks._tmp_path(name, ext)
  LangPacks.ensure_dir("tmp")
  local dir = (I18N and I18N.tmp_pack_dir and I18N.tmp_pack_dir())
    or (RA and RA.LANG_TMP_DIR)
    or (RA and RA.TEMP_DIR)
    or ""
  local suffix = (RA and RA.instance_file_suffix and RA.instance_file_suffix())
    or tostring(S and S.INSTANCE_ID or "session")
  return dir .. "lang_" .. tostring(name or "pack") .. "_"
    .. suffix .. tostring(ext or ".tmp")
end

function LangPacks._cleanup_tmp_paths(d)
  d = type(d) == "table" and d or {}
  if d.out_path then pcall(os.remove, d.out_path) end
  if d.exit_path then pcall(os.remove, d.exit_path) end
end

function LangPacks.cleanup_stale_tmp()
  local dir = (I18N and I18N.tmp_pack_dir and I18N.tmp_pack_dir())
    or (RA and RA.LANG_TMP_DIR)
  if not (dir and reaper and reaper.EnumerateFiles) then return end
  local sep = dir:sub(-1) == "/" or dir:sub(-1) == "\\"
  sep = sep and "" or (RA and RA.SEP or package.config:sub(1, 1))
  local now = time_precise()
  local idx = 0
  while true do
    local name = reaper.EnumerateFiles(dir, idx)
    if not name then break end
    local tracked = tostring(name):match("^lang_")
      or tostring(name):match("^font_")
    local inst_suffix = tracked and RA.temp_instance_suffix_from_name(name)
      or nil
    if tracked and inst_suffix
        and not RA.temp_instance_is_live(inst_suffix, now) then
      pcall(os.remove, dir .. sep .. name)
    else
      idx = idx + 1
    end
  end
end

function LangPacks.cleanup_legacy_help_dir_once()
  local key = "lang_help_cache_removed_v1"
  if Store and Store.migration_fired and Store.migration_fired(key) then
    return false, "done"
  end
  local root = RA and RA.LANG_DIR
  if not (root and root ~= "") then return false, "missing_root" end
  local sep = RA and RA.SEP or package.config:sub(1, 1)
  local dir = root .. "help" .. sep
  local path = dir:gsub("[/\\]+$", "")
  local root_clean = root:gsub("[/\\]+$", "")
  if root_clean == "" or path:sub(1, #root_clean + 1) ~= root_clean .. sep then
    return false, "unsafe_path"
  end
  local function remove_tree_contents(target_dir)
    if not (reaper and type(reaper.EnumerateFiles) == "function") then return end
    local target_sep = target_dir:sub(-1) == "/" or target_dir:sub(-1) == "\\"
    target_sep = target_sep and "" or sep
    local files = {}
    local idx = 0
    while true do
      local name = reaper.EnumerateFiles(target_dir, idx)
      if not name then break end
      files[#files + 1] = name
      idx = idx + 1
    end
    for _, name in ipairs(files) do
      pcall(os.remove, target_dir .. target_sep .. name)
    end
    if type(reaper.EnumerateSubdirectories) ~= "function" then return end
    local dirs = {}
    idx = 0
    while true do
      local name = reaper.EnumerateSubdirectories(target_dir, idx)
      if not name then break end
      dirs[#dirs + 1] = name
      idx = idx + 1
    end
    for _, name in ipairs(dirs) do
      local child = target_dir .. target_sep .. name
      remove_tree_contents(child)
      pcall(os.remove, child:gsub("[/\\]+$", ""))
    end
  end
  remove_tree_contents(dir)
  if os.remove(path) ~= true then
    if RA and RA.IS_WINDOWS and reaper and type(reaper.ExecProcess) == "function" then
      local ps_path = path:gsub("'", "''")
      local cmd = "powershell -NoProfile -WindowStyle Hidden"
        .. " -Command \"Remove-Item -LiteralPath '"
        .. ps_path
        .. "' -Recurse -Force -ErrorAction SilentlyContinue\""
      pcall(reaper.ExecProcess, cmd, 5000)
    else
      local sq = "'" .. path:gsub("'", "'\\''") .. "'"
      os.execute("rmdir " .. sq .. " >/dev/null 2>&1")
    end
  end
  if Store and Store.set_migration_fired then Store.set_migration_fired(key) end
  return true
end

if LangPacks and LangPacks.cleanup_stale_tmp then
  LangPacks.cleanup_stale_tmp()
end
if LangPacks and LangPacks.cleanup_legacy_help_dir_once then
  LangPacks.cleanup_legacy_help_dir_once()
end

function LangPacks._read_file(path)
  local f = io.open(path, "rb")
  if not f then return nil end
  local raw = f:read("*a")
  f:close()
  return raw
end

function LangPacks._copy_file(src, dest)
  local rf, rerr = io.open(src, "rb")
  if not rf then return false, rerr end
  local wf, werr = io.open(dest, "wb")
  if not wf then rf:close(); return false, werr end
  while true do
    local chunk, read_err = rf:read(65536)
    if not chunk then
      if read_err then
        rf:close(); wf:close(); os.remove(dest)
        return false, read_err
      end
      break
    end
    local ok, err = wf:write(chunk)
    if not ok then
      rf:close(); wf:close()
      os.remove(dest)
      return false, err
    end
  end
  local read_closed, read_close_err = rf:close()
  local write_closed, write_close_err = wf:close()
  if not read_closed or not write_closed then
    os.remove(dest)
    return false, read_close_err or write_close_err or "close_failed"
  end
  return true
end

function LangPacks._write_file(path, raw)
  local staged = LangPacks._tmp_path("index-write", ".json")
  local f, err = io.open(staged, "wb")
  if not f then return false, err end
  local ok, werr = f:write(raw or "")
  local closed, close_err = f:close()
  if not ok or not closed then
    os.remove(staged)
    return false, werr or close_err or "write_failed"
  end
  local installed, install_err = LangPacks._install_file(staged, path)
  if not installed then os.remove(staged) end
  return installed, install_err
end

function LangPacks._install_file(src, dest)
  if not (RA and RA.path_present and RA.instance_file_suffix) then
    return false, "cache_identity_unavailable"
  end
  LangPacks._cache_install_seq = (LangPacks._cache_install_seq or 0) + 1
  local suffix = string.format("%010d", os.time()) .. "."
    .. RA.instance_file_suffix() .. "." .. tostring(LangPacks._cache_install_seq)
  local tmp_path = dest .. ".pending." .. suffix
  local backup = dest .. ".bak." .. suffix
  if RA.path_present(tmp_path) or RA.path_present(backup) then
    return false, "cache_attempt_collision"
  end
  local ok_stage, stage_err = os.rename(src, tmp_path)
  if not ok_stage then
    local ok_copy, copy_err = LangPacks._copy_file(src, tmp_path)
    if not ok_copy then return false, copy_err or stage_err end
    os.remove(src)
  end
  local had_prior = RA.path_present(dest)
  if had_prior then
    local saved, save_err = os.rename(dest, backup)
    if not saved then
      os.remove(tmp_path)
      return false, save_err or "cache_preserve_failed"
    end
  end
  local ok_mv, mv_err = os.rename(tmp_path, dest)
  if not ok_mv then
    os.remove(tmp_path)
    -- Keep this backup readable after a crash or failed rename. A competing
    -- instance may own the primary now, so recovery never writes over it.
    return false, mv_err or "move_failed"
  end
  if had_prior then os.remove(backup) end
  -- A completed primary makes this instance's older attempts unnecessary.
  -- Other instances retain ownership of their recovery files.
  if reaper and type(reaper.EnumerateFiles) == "function" then
    local dir, name = dest:match("^(.*[/\\])([^/\\]+)$")
    if dir then
      local stale = {}
      reaper.EnumerateFiles(dir, -1)
      for index = 0, 4095 do
        local candidate = reaper.EnumerateFiles(dir, index)
        if not candidate then break end
        for _, kind in ipairs({ ".bak.", ".pending." }) do
          local prefix = name .. kind
          if candidate:sub(1, #prefix) == prefix then
            local tail = candidate:sub(#prefix + 1)
            local stamp, identity, sequence = tail:match("^(%d+)%.(inst_[%w_%-]+)%.(%d+)$")
            if stamp and identity == RA.instance_file_suffix() and tonumber(sequence) < LangPacks._cache_install_seq then
              stale[#stale + 1] = dir .. candidate
            end
          end
        end
      end
      for _, path in ipairs(stale) do os.remove(path) end
    end
  end
  return true
end

function LangPacks._safe_url(url)
  url = tostring(url or "")
  if not url:match("^https://") then return nil end
  if url:find('"', 1, true) or url:find("<", 1, true)
      or url:find(">", 1, true) or url:find("|", 1, true) then
    return nil
  end
  return url
end

function LangPacks._file_size(path)
  local f = path and io.open(path, "rb") or nil
  if not f then return nil end
  local size = f:seek("end")
  f:close()
  return size
end

function LangPacks._kind_label(d, step)
  d = type(d) == "table" and d or {}
  local kind = tostring(d.kind or d.pending_kind or "")
  local state = tostring(d.last_state or d.state or "")
  step = tostring(step or "")
  if kind == "index" or state == "index_downloading"
      or step == "index" or step == "index_launch" then
    return "language index"
  end
  return "language pack"
end

function LangPacks._cap(text)
  return (tostring(text or ""):gsub("^%l", string.upper))
end

function LangPacks._friendly_failure(step, err, d)
  step = tostring(step or "")
  err = tostring(err or "Language pack download failed.")
  local kind = LangPacks._kind_label(d, step)
  local exit_code = d and d.curl_exit_code
  if step == "download" then
    if exit_code then
      return string.format("%s download failed (curl exit %s).",
        LangPacks._cap(kind), tostring(exit_code))
    end
    if err:find("timed out", 1, true) then
      return string.format("%s download timed out after %d seconds.",
        LangPacks._cap(kind),
        (CFG and CFG.LANG_DOWNLOAD_TIMEOUT or 30))
    end
    return string.format("%s download failed.", LangPacks._cap(kind))
  elseif step == "index" then
    return "Language index downloaded but could not be read: " .. err
  elseif step == "metadata" then
    return "Language pack metadata is unavailable or incompatible: " .. err
  elseif step == "verify" then
    return "Downloaded " .. kind .. " failed verification: " .. err
  elseif step == "validate" then
    return "Downloaded " .. kind .. " could not be parsed: " .. err
  elseif step == "install" then
    return "Downloaded " .. kind .. " could not be installed: " .. err
  elseif step:find("launch", 1, true) then
    return LangPacks._cap(kind) .. " download could not start."
  end
  return err
end

function LangPacks._failure_detail(d, step, err, extra)
  d = type(d) == "table" and d or {}
  local detail = {
    code = tostring(d.last_code or d.code or d.pending_code or ""),
    state = tostring(d.last_state or d.state or ""),
    kind = LangPacks._kind_label(d, step),
    step = tostring(step or ""),
    error = tostring(err or ""),
    url = tostring(d.request_url or d.url or ""),
    url_cache_bust = tostring(d.request_url_with_cache_bust or ""),
    curl_exit = d.curl_exit_code,
    expected_bytes = d.entry and d.entry.bytes or nil,
    actual_bytes = d.actual_bytes or LangPacks._file_size(d.out_path),
    sha256 = d.entry and d.entry.sha256 or nil,
  }
  if type(extra) == "table" then
    for k, v in pairs(extra) do detail[k] = v end
  end
  return detail
end

function LangPacks.diagnostic_text(d)
  d = type(d) == "table" and d or LangPacks.download or {}
  local detail = type(d.last_detail) == "table" and d.last_detail or {}
  local lines = {
    "ReaAssist language download diagnostic",
    "version=" .. tostring(CFG and CFG.VERSION or ""),
    "os=" .. tostring(reaper and reaper.GetOS and reaper.GetOS() or ""),
    "utc=" .. tostring(os.date and os.date("!%Y-%m-%dT%H:%M:%SZ") or ""),
    "code=" .. tostring(detail.code or d.last_code or d.code or d.pending_code or ""),
    "kind=" .. tostring(detail.kind or ""),
    "state=" .. tostring(detail.state or d.state or ""),
    "step=" .. tostring(detail.step or d.last_step or ""),
    "error=" .. tostring(detail.error or d.last_raw_error or d.last_error or ""),
    "display_error=" .. tostring(d.last_error or ""),
    "url=" .. tostring(detail.url or d.request_url or ""),
    "url_cache_bust=" .. tostring(detail.url_cache_bust
      or d.request_url_with_cache_bust or ""),
    "curl_exit=" .. tostring(detail.curl_exit or d.curl_exit_code or ""),
    "expected_bytes=" .. tostring(detail.expected_bytes or ""),
    "actual_bytes=" .. tostring(detail.actual_bytes or ""),
    "sha256=" .. tostring(detail.sha256 or ""),
  }
  return table.concat(lines, "\n")
end

function LangPacks._sha_ok(raw, expected)
  expected = tostring(expected or ""):lower()
  if not expected:match("^[0-9a-f]+$") or #expected ~= 64 then return false end
  if not (RA and RA.sha256_hex) then return false end
  return tostring(RA.sha256_hex(raw or "")):lower() == expected
end

function LangPacks._parse_version(v)
  local parts = {}
  for n in tostring(v or ""):gmatch("(%d+)") do
    parts[#parts + 1] = tonumber(n) or 0
  end
  return parts
end

function LangPacks._version_cmp(a, b)
  local av = LangPacks._parse_version(a)
  local bv = LangPacks._parse_version(b)
  for i = 1, math_max(#av, #bv) do
    local ai, bi = av[i] or 0, bv[i] or 0
    if ai < bi then return -1 end
    if ai > bi then return 1 end
  end
  return 0
end

function LangPacks._app_compatible(entry)
  if type(entry) ~= "table" then return false end
  local current = tostring(CFG and CFG.VERSION or "0")
  if entry.app_min and LangPacks._version_cmp(current, entry.app_min) < 0 then
    return false
  end
  local app_max = tostring(entry.app_max or "")
  if app_max ~= "" then
    if app_max:match("^%d+%.x$") then
      local major = tonumber(current:match("^(%d+)")) or 0
      local wanted = tonumber(app_max:match("^(%d+)")) or -1
      if major ~= wanted then return false end
    elseif LangPacks._version_cmp(current, app_max) > 0 then
      return false
    end
  end
  return true
end

function LangPacks.remote_ui_entry(code)
  if not (I18N and I18N.remote_index) then return nil, "missing_index" end
  code = tostring(code or "")
  local lang = I18N.remote_index.languages
    and I18N.remote_index.languages[code]
  local ui = type(lang) == "table" and lang.ui or nil
  if type(ui) ~= "table" then return nil, "missing_ui" end
  if lang.status and lang.status ~= "complete" then return nil, "incomplete" end
  if ui.schema ~= (I18N.PACK_SCHEMA or 1) then return nil, "schema" end
  if ui.source_revision ~= I18N.SOURCE_REVISION then return nil, "source_revision" end
  if not LangPacks._safe_url(ui.url) then return nil, "url" end
  if not tonumber(ui.bytes) or tonumber(ui.bytes) <= 0
      or tonumber(ui.bytes) > (I18N.MAX_UI_PACK_BYTES or (1024 * 1024)) then
    return nil, "size"
  end
  if not tostring(ui.sha256 or ""):lower():match("^[0-9a-f]+$")
      or #tostring(ui.sha256 or "") ~= 64 then
    return nil, "sha"
  end
  if not LangPacks._app_compatible(ui) then return nil, "app" end
  return ui
end

function LangPacks.status_for_code(code)
  code = tostring(code or "")
  local d = LangPacks.download or {}
  if d.code == code and d.state == "ui_downloading" then return "downloading" end
  if d.pending_code == code and d.state == "index_downloading" then
    return "downloading"
  end
  local has_catalog = I18N and I18N.catalog_available
    and I18N.catalog_available(code)
  if has_catalog then
    return "installed"
  end
  if d.last_code == code and d.state == "failed" then return "failed" end
  if code ~= "" and code ~= "en" and code ~= "qps-ploc"
      and I18N and not I18N.remote_index
      and CFG and CFG.is_valid_language_code
      and CFG.is_valid_language_code(code) then
    return "download"
  end
  local entry = LangPacks.remote_ui_entry(code)
  if entry then return "download" end
  return "unavailable"
end

function LangPacks.label_for_code(code, base_label)
  local status = LangPacks.status_for_code(code)
  local lang = I18N and I18N.remote_index and I18N.remote_index.languages
    and I18N.remote_index.languages[tostring(code or "")]
  local cfg_lang = CFG and CFG.language_for_code
    and CFG.language_for_code(code)
  local label = tostring((type(lang) == "table" and (lang.native_label
      or lang.english_label))
    or (type(cfg_lang) == "table" and (cfg_lang.label_native
      or cfg_lang.label_en or cfg_lang.prompt_name))
    or base_label or code or "")
  if status == "download" then
    return label
  elseif status == "downloading" then
    return label .. " (" .. LangPacks._t("settings.lang.downloading_suffix", nil,
      "Downloading...") .. ")"
  elseif status == "failed" then
    return label .. " (" .. LangPacks._t("settings.lang.retry_suffix", nil,
      "Retry") .. ")"
  end
  return label
end

function LangPacks._failure_is_quiet_refresh(code)
  local d = LangPacks.download or {}
  if not (d.is_refresh or d.pending_refresh) then return false end
  code = tostring(code or d.code or d.pending_code or "")
  if code == "" then return false end
  return I18N and I18N.catalog_available and I18N.catalog_available(code)
end

function LangPacks._set_failure(code, step, err, detail)
  local d = LangPacks.download or {}
  local previous_state = d.state
  d.last_state = previous_state
  d.state = "failed"
  d.last_code = code or d.code or d.pending_code
  d.last_step = step
  d.last_raw_error = tostring(err or "Language pack download failed.")
  d.last_detail = LangPacks._failure_detail(d, step, d.last_raw_error, detail)
  d.last_error = LangPacks._friendly_failure(step, d.last_raw_error, d)
  d.quiet_refresh = LangPacks._failure_is_quiet_refresh(d.last_code) or nil
  if d.last_code then
    d.status_text = LangPacks._t("settings.lang.failed_detail", {
      language = LangPacks._display_language(d.last_code),
      current = LangPacks._display_language(I18N and I18N.lang_code
        and I18N.lang_code() or "en"),
      detail = d.last_error,
    }, "Language pack download failed. " .. d.last_error)
  else
    d.status_text = LangPacks._t("settings.lang.index_failed_detail", {
      detail = d.last_error,
    }, "Could not check language packs. " .. d.last_error)
  end
  LangPacks.download = d
  if d.last_code and UI and UI.show_float_toast and not d.quiet_refresh then
    UI.show_float_toast(d.status_text)
  end
  if Log and Log.line then
    local det = d.last_detail or {}
    Log.line("LANG", string.format(
      "fail [%s/%s/%s]: %s url=%s curl=%s bytes=%s/%s",
      tostring(d.last_code), tostring(previous_state), tostring(step),
      tostring(d.last_error), tostring(det.url or ""),
      tostring(det.curl_exit or ""), tostring(det.actual_bytes or ""),
      tostring(det.expected_bytes or "")))
  end
  LangPacks._cleanup_tmp_paths(d)
end

function LangPacks._store_index(raw)
  if type(raw) ~= "string" or raw == "" then return false, "empty" end
  if #raw > (I18N.MAX_INDEX_BYTES or (128 * 1024)) then
    return false, "oversize"
  end
  local doc, err = I18N._json_decode(raw)
  if type(doc) ~= "table" or doc.schema ~= (I18N.PACK_SCHEMA or 1)
      or type(doc.languages) ~= "table" then
    return false, err or "invalid_index"
  end
  local path = I18N.index_path and I18N.index_path()
  if not path then return false, "missing_index_path" end
  LangPacks.ensure_dir("root")
  local ok, werr = LangPacks._write_file(path, raw)
  if not ok and Log and Log.line then
    Log.line("LANG", "verified index cache write failed: " .. tostring(werr or "write_failed"))
  end
  I18N.remote_index = doc
  return true
end

function LangPacks.start_index_download(pending_code, force, pending_refresh)
  if not (I18N and I18N._json_decode and I18N.index_path) then
    return false, "i18n_unavailable"
  end
  if I18N.remote_index and not force then return true end
  if LangPacks.is_busy() then return false, "busy" end
  local out_path = LangPacks._tmp_path("index", ".json")
  local exit_path = LangPacks._tmp_path("index", ".exit")
  LangPacks.download = {
    state = "index_downloading",
    kind = "index",
    pending_code = pending_code,
    pending_refresh = pending_refresh and true or nil,
    out_path = out_path,
    exit_path = exit_path,
    status_text = LangPacks._t("settings.lang.checking", nil,
      "Checking languages..."),
  }
  local url = (I18N and I18N.INDEX_URL)
    or "https://reaassist.app/lang/v1.6/index.json"
  LangPacks.download.url = url
  local ok = RA.fire_get_to(url, out_path, exit_path,
    CFG.LANG_DOWNLOAD_TIMEOUT, LangPacks.download, "LANG")
  if not ok then
    LangPacks._set_failure(pending_code, "index_launch",
      "Language index download could not start.")
    return false, LangPacks.download.last_error
  end
  return true
end

function LangPacks.ensure_index()
  if I18N and I18N.remote_index then return true end
  local d = LangPacks.download or {}
  if d.state == "failed" and not d.last_code then return false end
  if LangPacks.is_busy() then return false end
  return LangPacks.start_index_download(nil, false)
end

function LangPacks.cached_ui_matches_entry(code, entry)
  if not (I18N and I18N.cached_ui_pack_path) then return false, "i18n" end
  entry = type(entry) == "table" and entry or nil
  if not entry then return false, "entry" end
  local cache = LangPacks._ui_match_cache and LangPacks._ui_match_cache[code]
  if cache and cache.sha256 == entry.sha256 and cache.bytes == entry.bytes then
    return cache.ok, cache.reason
  end
  local path = I18N.cached_ui_pack_path(code)
  local raw = path and LangPacks._read_file(path) or nil
  local ok, reason = true, nil
  if not raw or raw == "" then
    ok, reason = false, "missing"
  elseif entry.bytes and #raw ~= tonumber(entry.bytes) then
    ok, reason = false, "bytes"
  elseif entry.sha256 and not LangPacks._sha_ok(raw, entry.sha256) then
    ok, reason = false, "sha"
  end
  LangPacks._ui_match_cache = LangPacks._ui_match_cache or {}
  LangPacks._ui_match_cache[code] = {
    sha256 = entry.sha256,
    bytes = entry.bytes,
    ok = ok,
    reason = reason,
  }
  return ok, reason
end

function LangPacks.refresh_language_if_stale(code)
  code = tostring(code or "")
  if code == "" or code == "en" or code == "qps-ploc" then
    return true, "bundled"
  end
  local entry, entry_err = LangPacks.remote_ui_entry(code)
  if not entry then return false, entry_err or "unavailable" end
  local fresh = LangPacks.cached_ui_matches_entry(code, entry)
  if fresh then return true, "current" end
  return LangPacks.start_language_download(code, true)
end

function LangPacks.ensure_active_language_current()
  if LangPacks._active_refresh_started then return false, "done" end
  if LangPacks.is_busy() then return false, "busy" end
  local code = prefs and tostring(prefs.language_code or "") or ""
  if code == "" or code == "en" or code == "qps-ploc" then
    LangPacks._active_refresh_started = true
    return true, "bundled"
  end
  if CFG and CFG.is_valid_language_code and not CFG.is_valid_language_code(code) then
    LangPacks._active_refresh_started = true
    return false, "invalid"
  end
  LangPacks._active_refresh_started = true
  return LangPacks.start_index_download(code, true, true)
end

function LangPacks.start_language_download(code, force)
  code = tostring(code or "")
  if not force and I18N and I18N.catalog_available
      and I18N.catalog_available(code) then
    return true, "installed"
  end
  if LangPacks.is_busy() then return false, "busy" end
  if not (I18N and I18N.remote_index) then
    local ok, err = LangPacks.start_index_download(code, true, false)
    return false, err or (ok and "index_downloading" or "index_failed")
  end
  local entry, entry_err = LangPacks.remote_ui_entry(code)
  if not entry then
    LangPacks._set_failure(code, "metadata", entry_err or "unavailable")
    return false, entry_err or "unavailable"
  end
  local out_path = LangPacks._tmp_path("ui_" .. code, ".json")
  local exit_path = LangPacks._tmp_path("ui_" .. code, ".exit")
  local language = LangPacks._display_language(code)
  LangPacks.download = {
    state = "ui_downloading",
    kind = "ui",
    code = code,
    entry = entry,
    is_refresh = force and true or nil,
    out_path = out_path,
    exit_path = exit_path,
    status_text = LangPacks._t("settings.lang.downloading", {
      language = language,
    }, "Downloading language pack..."),
  }
  LangPacks.download.url = entry.url
  if UI and UI.show_float_toast then
    UI.show_float_toast(LangPacks.download.status_text)
  end
  local ok = RA.fire_get_to(entry.url, out_path, exit_path,
    CFG.LANG_DOWNLOAD_TIMEOUT, LangPacks.download, "LANG",
    { cache_bust = false })
  if not ok then
    LangPacks._set_failure(code, "launch",
      "Language pack download could not start.")
    return false, LangPacks.download.last_error
  end
  return true
end

function LangPacks._activate_language(code)
  local idx = CFG and CFG.legacy_idx_for_language_code
    and CFG.legacy_idx_for_language_code(code)
  if idx then prefs.reply_language_idx = idx end
  prefs.language_code = code
  if S and S.wrap_cache then S.wrap_cache = {} end
end

function LangPacks._finish_ui_download()
  local d = LangPacks.download or {}
  local entry = d.entry or {}
  local raw = LangPacks._read_file(d.out_path)
  d.actual_bytes = raw and #raw or LangPacks._file_size(d.out_path)
  if not raw or raw == "" then
    LangPacks._set_failure(d.code, "verify", "Downloaded pack was empty.",
      { actual_bytes = d.actual_bytes or 0 })
    return
  end
  if #raw > (I18N.MAX_UI_PACK_BYTES or (1024 * 1024)) then
    LangPacks._set_failure(d.code, "verify", "Downloaded pack was too large.",
      { actual_bytes = #raw })
    return
  end
  if entry.bytes and #raw ~= tonumber(entry.bytes) then
    LangPacks._set_failure(d.code, "verify",
      string.format("Downloaded pack size was %d bytes, expected %d.",
        #raw, tonumber(entry.bytes) or 0),
      { actual_bytes = #raw, expected_bytes = tonumber(entry.bytes) or 0 })
    return
  end
  if not LangPacks._sha_ok(raw, entry.sha256) then
    LangPacks._set_failure(d.code, "verify",
      "Downloaded pack checksum did not match.",
      { actual_bytes = #raw })
    return
  end
  local catalog, parse_err = I18N.parse_ui_pack_json(raw, d.code)
  if not catalog then
    LangPacks._set_failure(d.code, "validate", parse_err or "invalid_pack")
    return
  end
  if catalog._meta.source_revision ~= entry.source_revision
      or catalog._meta.source_revision ~= I18N.SOURCE_REVISION then
    LangPacks._set_failure(d.code, "validate", "source_revision")
    return
  end
  local dest = I18N.cached_ui_pack_path and I18N.cached_ui_pack_path(d.code)
  if not dest then
    LangPacks._set_failure(d.code, "install", "Missing pack cache path.")
    return
  end
  LangPacks.ensure_dir("ui")
  local ok_install, install_err = LangPacks._install_file(d.out_path, dest)
  if not ok_install then
    LangPacks._set_failure(d.code, "install", install_err or "move_failed")
    return
  end
  I18N.catalogs[d.code] = catalog
  if I18N._cached_pack_miss then I18N._cached_pack_miss[d.code] = nil end
  if LangPacks._ui_match_cache then LangPacks._ui_match_cache[d.code] = nil end
  LangPacks._activate_language(d.code)
  d.state = "done"
  d.last_code = d.code
  d.status_text = LangPacks._t(d.is_refresh and "settings.lang.updated_toast"
      or "settings.lang.installed_toast", {
    language = LangPacks._display_language(d.code),
  }, d.is_refresh and "Language pack updated." or "Language pack installed.")
  if UI and UI.show_float_toast then UI.show_float_toast(d.status_text) end
  LangPacks._cleanup_tmp_paths(d)
end

function LangPacks.poll()
  local d = LangPacks.download
  if not d or d.state == "idle" or d.state == "done" or d.state == "failed" then
    return
  end
  if not d.send_time then
    LangPacks._set_failure(d.code or d.pending_code, "download",
      "Language pack download did not launch.")
    return
  end
  if (time_precise() - d.send_time) > (CFG.LANG_DOWNLOAD_TIMEOUT + 10) then
    LangPacks._set_failure(d.code or d.pending_code, "download",
      "Language pack download timed out.",
      { timeout_seconds = CFG.LANG_DOWNLOAD_TIMEOUT })
    return
  end
  local ef = io.open(d.exit_path, "r")
  if not ef then return end
  local exit_str = ef:read("*a"); ef:close()
  local exit_code = tonumber(exit_str:match("(%d+)"))
  if not exit_code then return end
  d.curl_exit_code = exit_code
  if exit_code ~= 0 then
    LangPacks._set_failure(d.code or d.pending_code, "download",
      "Language pack download failed.", { curl_exit = exit_code })
    return
  end
  if d.state == "index_downloading" then
    local raw = LangPacks._read_file(d.out_path)
    d.actual_bytes = raw and #raw or LangPacks._file_size(d.out_path)
    local ok, err = LangPacks._store_index(raw)
    if not ok then
      LangPacks._set_failure(d.pending_code, "index", err or "invalid_index",
        { actual_bytes = d.actual_bytes or 0 })
      return
    end
    local pending_code = d.pending_code
    LangPacks._cleanup_tmp_paths(d)
    LangPacks.download = { state = "idle" }
    if pending_code then
      if d.pending_refresh then
        LangPacks.refresh_language_if_stale(pending_code)
      else
        LangPacks.start_language_download(pending_code)
      end
    end
    return
  end
  if d.state == "ui_downloading" then LangPacks._finish_ui_download() end
end

-- Poll for completion of the current async curl. Returns "done", "waiting", or "error".
function Updater.poll()
  if not update.send_time then return "error" end
  -- Watchdog: give up after timeout + generous slack.
  if (time_precise() - update.send_time) > (CFG.UPDATE_CURL_TIMEOUT + 10) then
    return "error"
  end
  -- io.open returns nil + err on failure; never throws. Direct call
  -- keeps the control flow flat.
  local ef = io.open(tmp.update_exit, "r")
  if not ef then return "waiting" end
  local exit_str = ef:read("*a"); ef:close()
  local exit_code = tonumber(exit_str:match("(%d+)"))
  if not exit_code then return "waiting" end
  if exit_code ~= 0 then return "error" end
  return "done"
end

-- Read and parse the response file. Returns parsed table plus the exact raw
-- bytes so manifest.json can participate in the same verified transaction as
-- every file it describes.
function Updater.read_response()
  local f = io.open(tmp.update_out, "rb")
  if not f then return nil end
  local raw = f:read("*a"); f:close()
  if not raw or #raw < 2 then return nil end
  local data, err = JSON.decode(raw)
  if not data or type(data) ~= "table" then return nil end
  return data, raw
end

-- Add the fetched manifest itself to the in-memory file list. Release
-- manifests intentionally omit a self-hash because embedding that hash would
-- be circular. Hashing the exact fetched bytes here gives update, repair,
-- staging verification, journaling, and startup recovery one consistent source
-- of truth without changing the persisted manifest format.
-- =============================================================================
-- Native extension delivery is separate from the app file list.
-- Refuse a bundled manifest before queuing files, even on an unknown target.
function Updater.app_files_exclude_native(manifest)
  for _, entry in ipairs(manifest.files) do
    local name = type(entry) == "table" and tostring(entry.name or ""):lower() or ""
    local base = name:match("([^/]+)$") or name
    if name:sub(1, 17) == "resources/engine/"
        or name:sub(1, 21) == "app/resources/engine/"
        or base:match("^reaper_mbriggs_helper%-") then
      return false, "native extension is listed as an app file"
    end
  end
  return true
end

function Updater.attach_manifest_payload(manifest, raw)
  if type(manifest) ~= "table" or type(manifest.files) ~= "table"
      or type(raw) ~= "string" or #raw < 2 then
    return false, "missing manifest bytes or files list"
  end
  local filename = tostring(CFG.UPDATE_MANIFEST or "")
  if filename == "" then return false, "missing manifest filename" end
  -- Duplicate names are refused HERE, on the fetched bytes, before anything is
  -- staged and long before apply_start writes a journal. A fetched manifest is
  -- external input: gen_manifest cannot produce a duplicate, but nothing in
  -- this process saw gen_manifest run, and what arrives is whatever the server
  -- and the network handed over. Two entries naming one destination make the
  -- second entry's swap consume staging the first already used and its .bak
  -- the previous version, which is the same ambiguity journal_valid refuses.
  -- Without this check the refusal still happened, at apply_start, where the
  -- journal it had just written failed its own ownership re-read and the user
  -- was told another ReaAssist instance was applying an update. That message
  -- was wrong about the cause and wrong about the fix (Codex round 18,
  -- deviation 4 rejected).
  --
  -- Case-insensitively, and the self-entry check with it, because the
  -- destination folds case on Windows: `Resources/UI.lua` and
  -- `Resources/ui.lua` are one file there, and a `Manifest.json` entry is the
  -- manifest.
  local seen = {}
  for _, entry in ipairs(manifest.files) do
    if type(entry) == "table" and type(entry.name) == "string" then
      local key = entry.name:lower()
      if key == filename:lower() then
        return false, "manifest file list contains a self-entry"
      end
      if seen[key] then
        return false, "duplicate file name " .. entry.name
      end
      seen[key] = true
    end
  end
  -- The launchers section gets the same treatment on the same bytes, and for
  -- the same reason: it names files at the PACKAGE root, which is the one
  -- place outside the updater's App-relative zone this body ever writes. An
  -- allowlist of two, exact and case-folded, refused here before anything is
  -- staged rather than at the queue where the message would be about
  -- something else (section 3b).
  local launchers_ok, launchers_why = Updater.launchers_section(manifest)
  if not launchers_ok then return false, launchers_why end
  local native_ok, native_why = Updater.app_files_exclude_native(manifest)
  if not native_ok then return false, native_why end
  manifest.files[#manifest.files + 1] = {
    name = filename,
    sha256 = sha256_hash(raw),
    inline_bytes = raw,
  }
  return true
end

function Updater.is_manifest_only_repair(diff)
  if type(diff) ~= "table" then return false end
  local filename = tostring(CFG.UPDATE_MANIFEST or "")
  if filename == "" then return false end
  local missing = type(diff.missing) == "table" and diff.missing or {}
  local mismatched = type(diff.mismatched) == "table" and diff.mismatched or {}
  if #missing + #mismatched ~= 1 then return false end
  return missing[1] == filename or mismatched[1] == filename
end

-- Force a reinstall: bypass version check, daily cap, and snooze.
-- Re-entry guard: bail when a curl is already in flight. Without it, a
-- double-click on Bootstrap's Repair button (which stays rendered during
-- "checking" because Bootstrap's state dispatcher falls through to
-- render_prompt on unknown states) would double-fire the curl while the
-- first one is still writing to tmp.update_out / tmp.update_exit,
-- corrupting the read.
function Updater.force_reinstall()
  if CFG.UPDATE_BASE_URL == "" then return false end
  if Updater.uninstall_barrier and Updater.uninstall_barrier() then
    return false
  end
  if Updater.is_busy() then return false end
  if Updater.font_download_busy() then return false end
  if Updater.language_download_busy() then return false end
  update.force = true
  update.popup_opened = false
  update.silent_manifest_repair = false
  update._silent_manifest_manual = false
  -- Clear stale failure metadata from a previous attempt. Without this,
  -- a Retry-after-failed click inherits the prior failure's last_step /
  -- last_error / repair_missing / repair_mismatched / action_was_repair
  -- values until the new check_poll result lands. The Update Failed
  -- dialog branches its copy on update.last_step (sha_verify gets the
  -- CDN-propagation message; everything else gets the generic copy), so
  -- a brief frame with a stale last_step could flash the wrong message.
  -- Mirror download_start's clean-slate pattern (download_queue,
  -- applied_files, skipped_count) for the failure-display fields too.
  update.last_step         = nil
  update.last_error        = nil
  update.repair_missing    = nil
  update.repair_mismatched = nil
  update.action_was_repair = nil
  local url = Updater.url_for(CFG.UPDATE_MANIFEST)
  if Updater.fire_get(url, tmp.update_out, tmp.update_exit) then
    update.state = "checking"
    return true
  end
  return false
end

-- Start the manifest check. Called from loop() on the first idle->waiting
-- chat-send edge in the session, so PowerShell is already warm from the
-- chat's curl and this check's ExecProcess cost is ~200ms instead of
-- 1-3s cold. No 24h throttle: the session flag
-- `update._session_check_fired` already prevents multiple fires per
-- session, and gating the fetch itself would prevent repair detection
-- too; we NEED a fresh manifest every session to compute the local-
-- vs-remote SHA diff. The update-nag snooze is honored lower in the
-- pipeline (check_poll's available branch) so it only suppresses the
-- "Update Available" popup, never the repair flow. Stamp
-- update_last_check here so any future consumer that wants a "time of
-- most recent successful fetch" reading has one.
function Updater.check_start()
  if CFG.UPDATE_BASE_URL == "" then return end
  if not prefs.update_check then return end
  if Updater.uninstall_barrier and Updater.uninstall_barrier() then return end
  -- Busy guard: the chat-piggyback fires on the first idle->waiting
  -- transition of the session, but a user could already have launched
  -- a manual Check / Repair in the same window. Without this guard the
  -- piggyback would fire a second curl that shares tmp.update_out /
  -- tmp.update_exit with the in-flight one, racing the manifest check
  -- against a download and corrupting the read.
  if Updater.is_busy() then return end
  if Updater.font_download_busy() then return end
  if Updater.language_download_busy() then return end
  update.silent_manifest_repair = false
  update._silent_manifest_manual = false
  Store.set_update_last_check(os.time())
  local url = Updater.url_for(CFG.UPDATE_MANIFEST)
  if Updater.fire_get(url, tmp.update_out, tmp.update_exit) then
    update.state = "checking"
  end
end

-- User-initiated check, wired to the "Check for Updates" button in
-- Settings. Bypasses the 24h throttle and the snooze (user is explicitly
-- asking). It also reads no preference at all, which is the whole of plan
-- section 7: check_start above is gated on prefs.update_check and this is
-- not, so turning automatic checks off means "I update manually" and never
-- "I have no way to check". The settings copy states that, so a gate added
-- here would make two shipped strings false.
-- Unlike force_reinstall it does NOT set update.force = true:
-- if the server is on the same version and SHAs match, we want to show
-- a friendly "You're up to date" toast instead of misleadingly offering
-- a reinstall. Bumps the throttle timestamp so the chat-piggyback does
-- not immediately re-fire the check on the user's next send.
function Updater.manual_check()
  if CFG.UPDATE_BASE_URL == "" then
    UI.show_float_toast(RA.t("update.toast.url_missing", nil,
      "Update URL not configured"), "err")
    return false
  end
  if Updater.uninstall_barrier and Updater.uninstall_barrier() then
    return false
  end
  if Updater.is_busy() then return false end
  if Updater.font_download_busy() then
    UI.show_float_toast(RA.t("settings.font.finish_download_first", nil,
      "Finish the font download first"), "err")
    return false
  end
  if Updater.language_download_busy() then
    UI.show_float_toast(RA.t("settings.lang.finish_download_first", nil,
      "Finish the language pack download first"), "err")
    return false
  end
  update.silent_manifest_repair = false
  update._silent_manifest_manual = false
  Store.set_update_last_check(os.time())
  update._manual = true
  -- Reset popup_opened so the "Update Available" dialog re-fires when
  -- this manual check finds an update. Without this, a sequence of
  -- (auto-fire piggyback shows popup -> Later -> manual check) would
  -- silently re-set state = "available" but the auto-show guard
  -- (`not update.popup_opened`) would suppress the popup the user
  -- explicitly asked to re-trigger. Same pattern as force_reinstall.
  update.popup_opened = false
  -- Sticky "Checking..." toast appears instantly so the user's click
  -- has immediate visual feedback during the PowerShell + curl round
  -- trip. check_poll replaces or clears this toast on every non-
  -- waiting result (up-to-date -> "up to date" toast; update or repair
  -- available -> cleared so the popup carries the feedback alone;
  -- error -> replaced with a specific error toast).
  UI.show_float_toast(RA.t("update.toast.checking", nil,
    "Checking for updates..."), "ok", true)
  local url = Updater.url_for(CFG.UPDATE_MANIFEST)
  if Updater.fire_get(url, tmp.update_out, tmp.update_exit) then
    update.state = "checking"
    return true
  end
  update._manual = false
  UI.show_float_toast(RA.t("update.toast.start_failed", nil,
    "Update check failed to start"), "err")
  return false
end

-- Missing-or-invalid manifest restore (Distribution Unification Plan 3b,
-- migration rule 2).
-- =============================================================================
-- The canonical manifest lives beside the body it describes, and the launcher
-- stages the exact verified bytes as the last entry of the same journaled
-- transaction that installs the body, so a fresh install always finishes with
-- one. What that does not cover is a manifest that goes missing or turns
-- unreadable AFTERWARDS. From up in the launcher that is invisible: it falls
-- back to its frozen critical list, finds the body present, and launches, so
-- its probe never restores anything and the install runs with no record of
-- itself. The body is the only thing in a position to notice, so it does.
--
-- Nothing new is downloaded to fix it, and there is no second downloader
-- here. The existing manifest fetch already carries the exact fetched bytes
-- as a payload entry of the manifest they describe, and the existing SHA diff
-- already recognises a manifest-only difference and heals it through the
-- silent verified apply. The one thing missing was something to start that
-- fetch when nothing else would: the session check fires on the first chat
-- send of a session, so a user who never sends one, or whose manifest went
-- missing after it fired, waited forever. A fetch that comes back NEWER than
-- the running version needs nothing special either: the ordinary update flow
-- lands a manifest as part of the update, which is the same repair by
-- another road.
--
-- Whether the local manifest is usable at all. Deliberately the same three
-- fields check_poll demands of a fetched one, so "unreadable here" and
-- "unusable there" mean the same thing, plus the entries themselves.
--
-- The entries matter because of what this manifest is FOR. It is the record
-- of what this install contains: the SHA diff hashes what it names, the
-- repair queue downloads what it names, and decision 10a.3 has the per-tick
-- sentinel and the launcher probe reading their critical-file list out of it.
-- A manifest whose file list is empty, or whose entries carry a name nothing
-- may resolve or a checksum nothing can compare, cannot answer any of those
-- questions, so calling it healthy just means the damage goes unnoticed
-- forever: nothing else in the body ever looks.
function Updater.local_manifest_intact()
  local name = tostring(CFG.UPDATE_MANIFEST or "")
  if name == "" then return true end
  local f = io.open(Updater.local_path_for(name), "rb")
  if not f then return false, "missing" end
  local raw = f:read("*a"); f:close()
  if not raw or #raw < 2 then return false, "empty" end
  local ok, data = pcall(JSON.decode, raw)
  if not ok or type(data) ~= "table" or type(data.version) ~= "string"
      or type(data.files) ~= "table" then
    return false, "unreadable"
  end
  -- A manifest describing no files describes no install. Every shipped
  -- manifest names the whole package; an empty list is a truncated or
  -- half-written file, not a valid one.
  if #data.files == 0 then return false, "empty file list" end
  local seen = {}
  for _, entry in ipairs(data.files) do
    if type(entry) ~= "table" then return false, "malformed entry" end
    if type(entry.name) ~= "string"
        or not Updater.is_safe_filename(entry.name) then
      return false, "unsafe entry name"
    end
    -- Two entries for one destination, exactly or by case alone, and the
    -- repair queue would download the same file twice and the journal that
    -- records the swap could not say which of them landed. This file is
    -- external input like any other fetched manifest (it IS a fetched
    -- manifest, kept on disk), so the same rule attach_manifest_payload
    -- applies to the bytes off the wire applies to the bytes off the disk.
    local key = entry.name:lower()
    if seen[key] then return false, "duplicate entry name" end
    seen[key] = true
    -- Same shape the journal demands, and for the same reason: 64 hex
    -- digits, case-insensitively, because every consumer compares with
    -- :lower() applied.
    if not Updater.journal_sha_ok(entry.sha256) then
      return false, "malformed entry checksum"
    end
  end
  -- The launchers section, on the disk copy, exactly as attach_manifest_payload
  -- validates it on the bytes off the wire. This file IS a fetched manifest,
  -- kept, and the two checks have to agree or a manifest the wire refused
  -- could still be read as healthy from disk.
  local launchers_ok, launchers_why = Updater.launchers_section(data)
  if not launchers_ok then return false, launchers_why end
  return true
end

-- Probe, and start the ordinary manifest fetch when the probe says the local
-- copy is gone or unusable. Called once at startup and then from the
-- updater's per-frame lane, which is what makes it a retry rather than a
-- single shot; the probe itself runs at most once per UPDATE_MANIFEST_RETRY
-- window, so the steady-state cost of a healthy install is one comparison
-- per frame.
--
-- NOT gated on the automatic update-check preference, and that is a ruling
-- rather than an oversight. Codex round 17 objected that this lane fetches
-- the same mutable manifest an update check fetches, and that check_poll
-- enters the ordinary update flow whenever the server turns out to be newer,
-- so with automatic checks off it was an automatic update check under another
-- name. Michael's decision (plan section 11, B2.2a): a damaged install heals,
-- and it heals to the LATEST release rather than back to the version it
-- happens to be running. Converging on latest is the point, not a side
-- effect, so the ordinary machinery behind this fetch is left exactly as it
-- is, prompts included. Nothing here builds a second, quieter upgrade path.
--
-- What keeps that honest is the damage gate below: local_manifest_intact has
-- to say the install is damaged before a single byte goes out. A healthy
-- install with automatic checks off makes NO network contact from this lane,
-- ever, which is the promise the preference is actually making. The
-- disclosure that a damaged install fetches repair data and is brought
-- current is not owed by this function but by the screen that offers the
-- preference, and work package B2.5 has since paid it: both halves are in
-- settings.pref.update_check.tooltip_v2 and a11y.sr.update_check.meaning_v2,
-- the damaged case and the intact one. Anything here that changes when this
-- lane fires, or what it heals to, changes what those two strings owe.
--
-- It stays quiet on its own account: no popup, no toast, nothing to dismiss
-- from this function, and a manifest-only difference finishes through the
-- silent verified apply with no visible state at all.
--
-- Offline is the ordinary case here rather than an error, so no path in this
-- function reports failure. fire_get refusing to start, curl failing, and an
-- unreachable server all land back on the cadence with the session
-- untouched, and check_poll's organic branch (neither manual nor forced) is
-- already silent for exactly that reason.
function Updater.try_manifest_restore()
  if CFG.UPDATE_BASE_URL == "" then return false end
  if Updater.uninstall_barrier and Updater.uninstall_barrier() then
    return false
  end
  if update.state ~= "idle" then return false end
  if Updater.is_busy() then return false end
  if Updater.font_download_busy() or Updater.language_download_busy() then
    return false
  end
  local now = os.time()
  if update._manifest_restore_at and now < update._manifest_restore_at then
    return false
  end
  local intact, why = Updater.local_manifest_intact()
  update._manifest_restore_at = now + (CFG.UPDATE_MANIFEST_RETRY or 300)
  -- The damage gate. Everything this lane is allowed to do downstream rests
  -- on it, so it is the one line here that must never become conditional on
  -- anything else.
  if intact then return false end
  if not Updater.fire_get(Updater.url_for(CFG.UPDATE_MANIFEST),
      tmp.update_out, tmp.update_exit) then
    return false
  end
  update.state = "checking"
  Log.line("UPDATE", string.format(
    "manifest restore: local %s is %s; fetching a fresh copy quietly.",
    tostring(CFG.UPDATE_MANIFEST), tostring(why)))
  return true
end

-- Per-tick completeness sentinel (Distribution Unification Plan section 3,
-- decision 10a.3).
-- =============================================================================
-- Release N+1 shrinks the ReaPack package to the two launchers, and a ReaPack
-- sync can fire while ReaAssist is running. A pre-N session that syncs
-- straight to N+1 therefore has the files under it deleted mid-session, and
-- everything ReaAssist loads lazily (the sidecar modules, the prompt corpus)
-- would fail at the moment the user next asked for something. Codex round 2
-- ruled that the app has to notice instead: verify its critical file set
-- before accepting or continuing work, and on failure preserve the visible
-- session, refuse new work, and ask for a restart.
--
-- The design constraints are what make this cheap enough to run every frame:
--
--   * Existence only. No hashing. A file that is present but corrupt is the
--     repair lane's problem and always was; a file that is GONE is the one a
--     running session cannot survive.
--   * One probe per tick, round-robin. A ten-entry list at REAPER's frame
--     rate is a full sweep several times a second, at one io call per frame,
--     which is less work than the heartbeat already does.
--   * One dialog, then a state. The sentinel latches: it says its piece once
--     and every later tick returns immediately, so a session cannot be buried
--     under a dialog per frame.
--
-- The list ships in the manifest (decision 10a.3), so the definition travels
-- per release instead of being frozen into rarely-changed code, and the
-- launcher probe reads the same flags. The fallback is the launcher's own
-- frozen list, used when no manifest is readable, which is exactly the
-- division of labour the repair lane wants: a missing MANIFEST is
-- try_manifest_restore's job and this sentinel simply falls back, while a
-- missing critical FILE is the sentinel's and the repair lane cannot see it
-- (its probe reads the manifest, not the files the manifest names).
--
-- Mirrors FALLBACK_CRITICAL in Dev/Launcher/launcher_template.lua. The two
-- are pinned against each other in the tests, so a launcher rebuild that
-- changed one and not the other fails there rather than in the field.
Updater.SENTINEL_FALLBACK_CRITICAL = {
  "ReaAssist.lua",
  "Resources/UI.lua",
  "Resources/Context.lua",
  "Resources/Diag.lua",
  "Resources/Engine.lua",
  "Resources/I18N.lua",
  "Resources/CodeRuntime.lua",
  "Resources/Relaunch.lua",
  "Resources/System_Prompt.md",
  "Resources/Prompts.md",
  "Resources/API_Ref.md",
}

-- The list this session watches, built once and cached. Manifest entries
-- flagged critical win; the frozen fallback stands in when no manifest is
-- readable, and that case is remembered so a manifest restored later in the
-- session is picked up on the next full round rather than never.
--
-- The manifest itself is never watched even if it somehow flags itself: it is
-- the repair lane's subject, and a sentinel that latched on it would block
-- the session the repair lane was about to heal quietly.
function Updater.sentinel_files()
  if update._sentinel_files then return update._sentinel_files end
  local names, seen = {}, {}
  local manifest_name = tostring(CFG.UPDATE_MANIFEST or "")
  local function add(name)
    if type(name) ~= "string" or name == "" then return end
    if name == manifest_name then return end
    if not Updater.is_safe_filename(name) then return end
    if seen[name] then return end
    seen[name] = true
    names[#names + 1] = name
  end
  local from_fallback = true
  local f = manifest_name ~= ""
    and io.open(Updater.local_path_for(manifest_name), "rb") or nil
  if f then
    local raw = f:read("*a"); f:close()
    local ok, data = pcall(JSON.decode, raw)
    if ok and type(data) == "table" and type(data.files) == "table" then
      for _, entry in ipairs(data.files) do
        if type(entry) == "table" and entry.critical == true then
          add(entry.name)
        end
      end
      if #names > 0 then from_fallback = false end
    end
  end
  if from_fallback then
    for _, name in ipairs(Updater.SENTINEL_FALLBACK_CRITICAL) do add(name) end
  end
  -- The launcher forces the file it is about to compile into the list
  -- whatever the manifest said (Host.with_body_main). Same rule here, for the
  -- same reason: in Screen Reader mode the entry point is the Screen Reader
  -- body, which the shipped critical set need not name.
  --
  -- Startup intent alone decides this, NOT the saved preference. The Screen
  -- Reader entry point supports being run directly from the Action List by a
  -- user whose preference is off, and that session is running out of the same
  -- file as any other Screen Reader session. Requiring the preference to agree
  -- gave exactly those direct-action launches the weaker watch list, on the
  -- one lane where losing the entry point mid-session is least recoverable
  -- (Codex round 18 should-fix). is_safe_filename and the manifest exclusion
  -- above still apply, and the visual lane is unaffected because its intent
  -- flag is false.
  if S.screen_reader_startup_intent then
    add("ReaAssist_Screen_Reader_Mode.lua")
  end
  update._sentinel_from_fallback = from_fallback
  update._sentinel_files = names
  return names
end

-- Whether this session has already refused. Read by the send path.
function Updater.sentinel_blocked()
  return update.sentinel_missing ~= nil
end

-- The message shown when work is refused. Named separately so the dialog and
-- the chat-side refusal say the same thing.
function Updater.sentinel_message()
  return RA.t("sentinel.incomplete", nil,
    "Part of the ReaAssist installation is missing, so ReaAssist has "
    .. "stopped taking new work.\n\nYour session is still here and nothing "
    .. "has been changed. Close ReaAssist and open it again: it restores "
    .. "the missing files on the way back up.")
    .. "\n\nMissing: " .. tostring(update.sentinel_missing)
end

-- Refuse one piece of work, in the chat, without touching the session.
function Updater.sentinel_refuse()
  if Log and Log.add_error then Log.add_error(Updater.sentinel_message()) end
  if S then
    S.status = "idle"
    S.scroll_to_bottom = true
  end
  return false
end

-- One existence probe, per tick, in round-robin order. Returns true on the
-- tick that latches the refusal, false every other time.
function Updater.sentinel_tick()
  -- FOLDERS AN INTERRUPTED REMOVAL LEFT UNDER A NAME OF ITS OWN, PUT BACK
  -- (work package B2.4c, Codex round 50). This is the first thing in the body
  -- that runs on every session of both surfaces: the standard loop and the
  -- Screen Reader loop each pump this tick, so one call site covers both, and
  -- it is placed above every early return because a session that is refusing
  -- work for another reason is still a session that should put the user's
  -- folders back. The consumer carries its own once-guard and its own refusal
  -- while a removal is running in this window.
  --
  -- IT CANNOT RUN EARLIER THAN THE BODY. An interrupted removal leaves an
  -- ACTIVE marker and the launcher refuses that outright, so the door into
  -- here is the one the marker's own words describe: delete the marker, run an
  -- action, and the body that starts is what does the putting back. Asked
  -- defensively so a body sliced without the uninstaller behaves exactly as it
  -- did before.
  if Updater.uninstall_claim_recover then
    Updater.uninstall_claim_recover({ once = true, announce = true })
  end
  if update.sentinel_missing ~= nil then return false end
  -- An uninstall removes the critical files on purpose. Latching the "files
  -- are missing, restart ReaAssist" refusal on top of the uninstall report
  -- would be the app alarming about the thing the user just asked it to do.
  if Updater.uninstall_barrier and Updater.uninstall_barrier() then
    return false
  end
  -- An apply moves a live file aside on one tick and swaps its replacement in
  -- on a later one, so a critical file is legitimately absent between those
  -- two ticks. Anything the updater is mid-flight on owns its own files.
  if Updater.is_busy() then return false end
  -- Bootstrap recovery is already downloading the missing set through
  -- force_reinstall, and its own screen is a better place to be than this
  -- one.
  if S.bootstrap_active then return false end
  local files = Updater.sentinel_files()
  local total = #files
  if total == 0 then return false end
  local idx = (update._sentinel_idx or 0) + 1
  if idx > total then
    idx = 1
    -- A round completed on the fallback list: look for a manifest again, in
    -- case the repair lane landed one since.
    if update._sentinel_from_fallback then update._sentinel_files = nil end
  end
  update._sentinel_idx = idx
  local name = files[idx]
  local path = Updater.local_path_for(name)
  if reaper.file_exists and reaper.file_exists(path) then return false end
  -- Second opinion before latching. Blocking a session is expensive enough
  -- that one API's answer is not worth acting on alone.
  local probe = io.open(path, "rb")
  if probe then probe:close(); return false end
  update.sentinel_missing = name
  Log.line("SENTINEL", string.format(
    "critical file %s is gone from a running session; refusing new work "
    .. "and asking for a restart.", tostring(name)))
  reaper.MB(Updater.sentinel_message(), "ReaAssist", 0)
  return true
end

-- =============================================================================
-- SHA-256 verification pipeline (native subprocess + pure-Lua fallback)
-- =============================================================================
-- start_sha_diff preflights the manifest in pure Lua (classifying each entry
-- as missing / locked-skip / readable) and then prefers a native SHA-256
-- subprocess (PowerShell Get-FileHash on Windows; sha256sum / shasum -a 256
-- on POSIX) over the pure-Lua incremental hasher. Native is hundreds of MB/s
-- vs ~1 MB/s pure-Lua, so on a ~3.6 MB manifest the verify tail drops from
-- 5-12 s to well under 1 s.
--
-- The pure-Lua path remains as the reliability floor. It runs when:
--   * The native launcher couldn't start (PowerShell missing, AV block,
--     no sha256sum / shasum on POSIX, paths-file write error)
--   * tick_native_sha hits a non-zero exit, watchdog timeout, or
--     suspicious output (preflighted file readable but missing from
--     native output)
-- Each tick_sha_diff call compresses up to s.budget seconds of SHA work
-- (CFG.UPDATE_SHA_TIME_BUDGET for background piggyback,
-- CFG.UPDATE_SHA_TIME_BUDGET_MANUAL for manual / forced) at the 64-byte SHA
-- block level, so REAPER stays responsive even if every file has to be
-- hashed in-Lua. The main loop pumps either tick_native_sha or
-- tick_sha_diff once per frame while update.state == "verifying", same
-- shape as "checking" / "downloading_batch" / "applying".
--
-- download_start (the post-Update-Now path) consumes the precomputed diff and
-- never hashes the whole manifest synchronously on the UI thread.

-- Begin SHA verification. Caller passes the parsed manifest plus the
-- snapshotted manual / forced flags (so tick_*_sha -> _complete can branch
-- on the same intent that check_poll captured). Two-phase pipeline:
--
--   1) Preflight (in this function, in pure Lua): walk manifest, classify
--      each entry as missing / locked-skip / readable. Missing entries are
--      recorded directly in s.diff.missing; locked ones are logged and
--      skipped (preserving today's "AV / editor lock = treat as intact"
--      semantics so transient locks don't produce false Repair-Available
--      popups). Readable entries are collected into s.to_hash[].
--
--   2) Hash (deferred across frames): prefer native SHA-256 via PowerShell
--      Get-FileHash on Windows or sha256sum / shasum -a 256 on POSIX;
--      native is hundreds of MB/s vs ~1 MB/s pure-Lua, so on a ~3.6 MB
--      manifest the verify tail drops from 5-12 s to well under 1 s. Pure-
--      Lua remains the reliability floor: if the native subprocess fails
--      to launch, exits non-zero, watchdog-times-out, or produces output
--      that doesn't match preflight, _native_to_lua_fallback flips
--      s.mode = "lua_fallback" and tick_sha_diff walks s.to_hash from
--      idx 1 to recompute from a known-good code path.
--
-- Sets state = "verifying" so the main loop knows to pump the right tick
-- function each frame (tick_native_sha when s.mode == "native";
-- tick_sha_diff when s.mode == "lua" or "lua_fallback").
function Updater.start_sha_diff(manifest, manual, forced, purpose)
  local diff = { missing = {}, mismatched = {}, locked = {}, unverifiable = {} }
  local to_hash = {}            -- list of { path, entry }
  local path_to_entry = {}      -- absolute path -> entry, for native parse

  -- Re-ask ReaPack before the walk, because the walk is what decides which
  -- launchers this pass is responsible for.
  Updater.launcher_owner_refresh()

  for idx, entry in ipairs(manifest.files or {}) do
    if type(entry) == "table" and type(entry.name) == "string"
        and type(entry.sha256) == "string"
        and Updater.is_safe_filename(entry.name) then
      local path = Updater.local_path_for(entry.name)
      local f, open_err = io.open(path, "rb")
      if not f then
        if reaper.file_exists and reaper.file_exists(path) then
          -- Locked: tracked separately instead of dropped. The repair
          -- purpose still treats locked as intact (transient AV / editor
          -- locks must not cause false Repair-Available popups); the
          -- update purpose queues locked files for download so a
          -- persistent lock becomes an explicit apply failure instead of
          -- a silently stale file. See _sha_diff_complete.
          diff.locked[#diff.locked+1] = entry.name
          Log.line("UPDATE", string.format(
            "start_sha_diff preflight: %s exists but open failed: %s "
            .. "(likely AV / editor lock; recording as locked)",
            path, tostring(open_err)))
        else
          diff.missing[#diff.missing+1] = entry.name
        end
      else
        f:close()
        to_hash[#to_hash+1] = { path = path, entry = entry }
        path_to_entry[path] = entry
      end
    else
      -- Malformed manifest entry, or a name this body will not join onto the
      -- install root. Nothing hashes it and nothing downloads it, in either
      -- purpose, so it is recorded rather than dropped: an ordinary session
      -- still ignores it (download_start rejects malformed entries again
      -- before queueing anything), but a standing quarantine gate has to know
      -- that the pass it is waiting on did not cover the whole manifest
      -- (Codex round 20, blocker 1).
      diff.unverifiable[#diff.unverifiable+1] =
        (type(entry) == "table" and type(entry.name) == "string")
          and entry.name or string.format("manifest entry %d", idx)
    end
  end

  -- The launchers, on the same terms and against the other root.
  --
  -- Only the unowned ones reach here (serviceable_launchers drops the rest),
  -- and only on an install that has the topology: a flat pre-restructure
  -- install has no launcher at that path, only the body, and hashing the body
  -- against a launcher's checksum would report the install broken forever.
  --
  -- Each one is hashed through a KEYED stand-in for its manifest entry rather
  -- than the entry itself, so every classification site below files it under
  -- Updater.launcher_key(name) without knowing launchers exist. That is what
  -- keeps the body's `ReaAssist.lua` and the launcher's apart in lists that are
  -- keyed by name, and the absolute paths differ so the native hasher's
  -- path-to-entry map cannot confuse them either.
  if Updater.launcher_topology_active() then
    for _, entry in ipairs(Updater.serviceable_launchers(manifest)) do
      local keyed = {
        name   = Updater.launcher_key(entry.name),
        sha256 = entry.sha256,
      }
      local path = Updater.launcher_path(entry.name)
      local f, open_err = io.open(path, "rb")
      if not f then
        if reaper.file_exists and reaper.file_exists(path) then
          diff.locked[#diff.locked+1] = keyed.name
          Log.line("UPDATE", string.format(
            "start_sha_diff preflight: %s exists but open failed: %s "
            .. "(likely AV / editor lock; recording as locked)",
            path, tostring(open_err)))
        else
          diff.missing[#diff.missing+1] = keyed.name
        end
      else
        f:close()
        to_hash[#to_hash+1] = { path = path, entry = keyed }
        path_to_entry[path] = keyed
      end
    end
  end

  update._sha_diff = {
    manifest      = manifest,
    files         = manifest.files,
    to_hash       = to_hash,
    path_to_entry = path_to_entry,
    lua_idx       = 1,             -- pure-Lua walker pointer into to_hash
    cur           = nil,           -- in-flight per-file SHA state (lua mode)
    diff          = diff,
    manual        = manual,
    forced        = forced,
    purpose       = purpose or "repair",
    -- Higher per-frame budget when the user is actively waiting (manual
    -- check or forced repair). Background piggyback checks
    -- (manual = forced = nil/false) keep the conservative default because
    -- they run while the user reads the chat response and any visible
    -- stutter is undesirable. Only consulted by tick_sha_diff -- the
    -- native path runs out-of-process and has no per-frame budget concern.
    budget        = (manual or forced) and CFG.UPDATE_SHA_TIME_BUDGET_MANUAL
                                       or  CFG.UPDATE_SHA_TIME_BUDGET,
    started_at    = time_precise(),
    mode          = "lua",         -- overridden to "native" if subprocess launches
  }

  -- All entries were missing / locked / unsafe: nothing to hash, finalize.
  if #to_hash == 0 then
    Updater._sha_diff_complete()
    return
  end

  -- Try native first. If launch fails (no PowerShell, AV block, file write
  -- error, missing POSIX tool), stay in "lua" mode and the main loop's
  -- verifying branch will pump tick_sha_diff() from lua_idx 1.
  if Updater.fire_native_sha(to_hash) then
    update._sha_diff.mode             = "native"
    update._sha_diff.native_send_time = time_precise()
  end

  update.state = "verifying"
end

-- Launch a native SHA-256 hasher subprocess for every path in to_hash.
-- Writes one "<hex>\t<input path>" line per file to tmp.update_sha_out
-- and the inner-process exit code to tmp.update_sha_exit. Returns true if
-- the launch was attempted, false on prerequisite failure (paths-file
-- write error, defensive quote rejection, PS-script write error).
--
-- Detached via the same Start-Process cmd pattern as fire_get on Windows
-- and a backgrounded subshell on POSIX, so the main thread only pays
-- launcher startup (~200 ms warm PowerShell) -- not the hash duration --
-- and tick_native_sha polls tmp.update_sha_exit each frame for completion.
--
-- The Windows path emits the verbatim INPUT path (not Get-FileHash's
-- $_.Path) so tick_native_sha's exact-match lookup in path_to_entry can't
-- be defeated by provider-side casing or normalization. Output is written
-- via .NET StreamWriter with UTF-8(no-BOM) for predictable encoding
-- across PowerShell 5 / 7 / redirection differences.
function Updater.fire_native_sha(to_hash)
  os.remove(tmp.update_sha_in)
  os.remove(tmp.update_sha_out)
  os.remove(tmp.update_sha_exit)
  os.remove(tmp.update_sha_ps)

  -- Write absolute paths, one per line, UTF-8.
  local pf, pf_err = io.open(tmp.update_sha_in, "wb")
  if not pf then
    Log.line("UPDATE", "fire_native_sha: paths-file open failed: "
                       .. tostring(pf_err))
    return false
  end
  for _, item in ipairs(to_hash) do
    pf:write(item.path)
    pf:write("\n")
  end
  pf:close()

  if RA.IS_WINDOWS then
    -- Defensive guard limited to characters that cannot legitimately
    -- appear in a valid Windows path: " < > | are all reserved by
    -- Windows filenames. Other cmd-significant chars (& ^ ( ) %) ARE
    -- valid in Windows paths ("Program Files (x86)", "R&D", etc.) and
    -- the triple-quoted argument passing protects them; rejecting
    -- them would silently break update / repair for valid users. See
    -- fire_get for the same guard on the manifest-fetch path.
    for _, c in ipairs({'"', '<', '>', '|'}) do
      if tmp.update_sha_in:find(c, 1, true)
          or tmp.update_sha_out:find(c, 1, true)
          or tmp.update_sha_exit:find(c, 1, true)
          or tmp.update_sha_ps:find(c, 1, true) then
        Log.line("UPDATE", string.format(
          "fire_native_sha: refusing to launch with cmd-unsafe "
          .. "character '%s' in tmp paths", c))
        return false
      end
    end

    -- The PS script: read paths, hash each via Get-FileHash, write
    -- "<hex>\t<input path>" to the output file. Per-file try/catch so a
    -- single bad file (locked / deleted between preflight and hash)
    -- doesn't lose the rest -- tick_native_sha's missing-from-output
    -- triage handles those cases.
    local ps_script = string.format(
[[$ErrorActionPreference = 'Continue'
$exitPath = '%s'
$utf8 = New-Object System.Text.UTF8Encoding($false)
try {
  function Get-Sha256Hex([string]$Path) {
    $sha = [System.Security.Cryptography.SHA256]::Create()
    $stream = [System.IO.File]::Open($Path,
      [System.IO.FileMode]::Open,
      [System.IO.FileAccess]::Read,
      [System.IO.FileShare]::ReadWrite)
    try {
      $hash = $sha.ComputeHash($stream)
      return ([System.BitConverter]::ToString($hash)).Replace('-', '').ToLowerInvariant()
    } finally {
      $stream.Dispose()
      $sha.Dispose()
    }
  }
  $paths = Get-Content -LiteralPath '%s' -Encoding UTF8
  $writer = New-Object System.IO.StreamWriter('%s', $false, $utf8)
  try {
    foreach ($p in $paths) {
      $hex = $null
      for ($i = 0; $i -lt 10; $i++) {
        try {
          $hex = Get-Sha256Hex -Path $p
          break
        } catch {
          if ($i -eq 9) { $hex = $null } else { Start-Sleep -Milliseconds 100 }
        }
      }
      if ($hex) {
        $writer.WriteLine($hex + "`t" + $p)
      }
    }
  } finally {
    $writer.Close()
  }
  [System.IO.File]::WriteAllText($exitPath, '0', $utf8)
  exit 0
} catch {
  try {
    [System.IO.File]::WriteAllText($exitPath, '1', $utf8)
  } catch {
  }
  exit 1
}
]],
      Shell.ps_escape(tmp.update_sha_exit), Shell.ps_escape(tmp.update_sha_in),
      Shell.ps_escape(tmp.update_sha_out))

    -- Write the .ps1 with a UTF-8 BOM so PowerShell 5 reads it as UTF-8
    -- unambiguously (PS5 default file encoding is the system codepage;
    -- PS7 defaults to UTF-8). Matters when paths contain non-ASCII (e.g.
    -- a user dir with Unicode characters).
    local sf, sf_err = io.open(tmp.update_sha_ps, "wb")
    if not sf then
      Log.line("UPDATE", "fire_native_sha: PS-script open failed: "
                         .. tostring(sf_err))
      return false
    end
    sf:write("\239\187\191")
    sf:write(ps_script)
    sf:close()

    -- Inner cmd: run the PS script via -File (no script-content quoting
    -- needed -- avoids the inner-PS / cmd / outer-PS triple escape) and
    -- capture the inner PS's exit code via cmd's %errorlevel%.
    local cmd_line = string.format(
      'powershell -NoProfile -ExecutionPolicy Bypass'
      .. ' -File """%s"""',
      tmp.update_sha_ps)

    -- Outer PS: detach via Start-Process so ExecProcess's positive
    -- timeout only waits for PS to spawn cmd (~200 ms warm), not for
    -- the actual hashing. Same pattern as fire_get.
    local ps_cmd = string.format(
      'powershell -NoProfile -WindowStyle Hidden'
      .. ' -Command "Start-Process cmd -ArgumentList \'/c %s\''
      .. ' -WindowStyle Hidden"',
      Shell.ps_escape(cmd_line))
    reaper.ExecProcess(ps_cmd, 5000)
  else
    -- POSIX: prefer sha256sum (GNU; standard on Linux), fall back to
    -- shasum -a 256 (Perl; standard on macOS). exit 127 if neither is
    -- installed -- tick_native_sha falls back to pure-Lua. tr '\n' '\0'
    -- piped to xargs -0 so paths with spaces survive the shell split.
    local cmd = string.format(
      "(if command -v sha256sum >/dev/null 2>&1; then "
      .. "tr '\\n' '\\0' < %s | xargs -0 sha256sum > %s; rc=$?; "
      .. "elif command -v shasum >/dev/null 2>&1; then "
      .. "tr '\\n' '\\0' < %s | xargs -0 shasum -a 256 > %s; rc=$?; "
      .. "else rc=127; fi; echo $rc > %s) &",
      Shell.sh_quote(tmp.update_sha_in), Shell.sh_quote(tmp.update_sha_out),
      Shell.sh_quote(tmp.update_sha_in), Shell.sh_quote(tmp.update_sha_out),
      Shell.sh_quote(tmp.update_sha_exit))
    os.execute(cmd)
  end

  return true
end

-- One tick of the native-hash poll path. Called by the main loop each
-- frame while update.state == "verifying" and s.mode == "native". Reads
-- tmp.update_sha_exit; on completion (exit 0) parses tmp.update_sha_out,
-- triages each preflighted file against the parsed output, and either
-- commits results to s.diff or falls back to lua. On non-zero exit /
-- watchdog timeout / read failure / suspicious output (preflighted file
-- readable but missing from native output), transitions to lua_fallback
-- and lets tick_sha_diff take over from a known-good code path.
function Updater.tick_native_sha()
  local s = update._sha_diff
  if not s then return end

  -- Watchdog: native hashing of ~3.6 MB completes in well under a second;
  -- 15 s + 5 s slack covers cold spawn, slow disks, AV scanning. Beyond
  -- that, fall back rather than wait further.
  if s.native_send_time
      and (time_precise() - s.native_send_time)
          > (CFG.UPDATE_NATIVE_SHA_TIMEOUT + 5) then
    Log.line("UPDATE", "tick_native_sha: watchdog timeout, "
                       .. "falling back to pure-Lua verify")
    Updater._native_to_lua_fallback()
    return
  end

  -- Read exit file. While the inner process is still running, the file
  -- doesn't exist (cmd's `& echo %errorlevel% > exit` only runs after
  -- powershell returns). The race window where it exists but isn't
  -- fully written is small; tonumber(nil) -> nil makes us wait one more
  -- frame on partial reads.
  local ef = io.open(tmp.update_sha_exit, "r")
  if not ef then return end
  local exit_str = ef:read("*a"); ef:close()
  local exit_code = tonumber(exit_str:match("(%d+)"))
  if not exit_code then return end

  if exit_code ~= 0 then
    Log.line("UPDATE", string.format(
      "tick_native_sha: native hasher exited %d, "
      .. "falling back to pure-Lua verify", exit_code))
    Updater._native_to_lua_fallback()
    return
  end

  local of, of_err = io.open(tmp.update_sha_out, "rb")
  if not of then
    Log.line("UPDATE", "tick_native_sha: output read failed: "
                       .. tostring(of_err) .. ", falling back")
    Updater._native_to_lua_fallback()
    return
  end
  local raw = of:read("*a"); of:close()
  -- Defensive UTF-8 BOM strip. The PS script writes via UTF-8(no-BOM)
  -- StreamWriter so this should never trigger, but POSIX redirection
  -- behaves differently across platforms and stripping is harmless.
  if raw:sub(1, 3) == "\239\187\191" then raw = raw:sub(4) end

  -- Parse: "<64 hex>(whitespace)<path>". Both PS-pinned tab-separated
  -- output and POSIX two-space-separated output match this pattern.
  local hash_by_path = {}
  for line in raw:gmatch("[^\r\n]+") do
    local hex, rest = line:match("^([0-9a-fA-F]+)[ \t]+(.+)$")
    if hex and #hex == 64 and rest then
      hash_by_path[rest] = hex:lower()
    end
  end

  -- Triage each preflighted file. Hold mismatched / additional_missing /
  -- locked in local tables so a fallback decision can discard them
  -- cleanly -- the lua fallback redoes the comparison from scratch and we
  -- don't want partial native results leaking into its diff.
  local mismatched = {}
  local additional_missing = {}
  local locked = {}
  local suspicious = false
  for _, item in ipairs(s.to_hash) do
    local local_hash = hash_by_path[item.path]
    if local_hash then
      if local_hash ~= item.entry.sha256:lower() then
        mismatched[#mismatched+1] = item.entry.name
      end
    else
      -- Native produced no hash for this preflight-readable file. Triage:
      --   * file gone now: native saw a delete race -> record as missing
      --   * file present but locked now: AV / lock race -> record as
      --     locked (consumed per purpose by _sha_diff_complete)
      --   * file present and readable now: native should have hashed it
      --     but didn't -- output is suspicious, fall back to lua so the
      --     whole result set gets recomputed from a known-good path.
      local exists = (reaper.file_exists and reaper.file_exists(item.path))
      if not exists then
        additional_missing[#additional_missing+1] = item.entry.name
      else
        local f = io.open(item.path, "rb")
        if not f then
          locked[#locked+1] = item.entry.name
          Log.line("UPDATE", string.format(
            "tick_native_sha: %s preflight readable but locked now "
            .. "(recording as locked)", item.path))
        else
          f:close()
          Log.line("UPDATE", string.format(
            "tick_native_sha: %s readable but missing from native output "
            .. "(suspicious, falling back to pure-Lua verify)",
            item.path))
          suspicious = true
          break
        end
      end
    end
  end

  if suspicious then
    Updater._native_to_lua_fallback()
    return
  end

  -- Commit results to s.diff and finalize.
  for _, name in ipairs(mismatched) do
    s.diff.mismatched[#s.diff.mismatched+1] = name
  end
  for _, name in ipairs(additional_missing) do
    s.diff.missing[#s.diff.missing+1] = name
  end
  for _, name in ipairs(locked) do
    s.diff.locked[#s.diff.locked+1] = name
  end
  Updater._sha_diff_complete()
end

-- Switch from native mode to pure-Lua fallback. Reset the lua walker
-- pointer so tick_sha_diff re-walks s.to_hash from the start. Intentionally
-- does NOT clear s.diff -- preflight-derived missing/locked entries remain
-- valid (they're filesystem facts, not native-tool output) and
-- s.diff.mismatched plus any triage-time locked entries are empty at this
-- point because tick_native_sha only mutates s.diff after a successful
-- triage commit.
function Updater._native_to_lua_fallback()
  local s = update._sha_diff
  if not s then return end
  s.mode    = "lua_fallback"
  s.lua_idx = 1
  s.cur     = nil
end

-- One tick of incremental pure-Lua SHA verification. Called by the main
-- loop each frame while update.state == "verifying" and s.mode == "lua"
-- or "lua_fallback". Walks s.to_hash[] (preflighted readable files) so
-- classification work is not duplicated -- start_sha_diff already filed
-- missing / unsafe / locked entries.
--
-- State machine:
--   * No current file (s.cur == nil): pop the next entry from to_hash.
--     Race-handle the rare case where preflight saw the file readable
--     but it's locked now (record in s.diff.locked, mirroring
--     start_sha_diff) and the rare nil-read race (treat as locked).
--   * Current file in flight: compress one tick's worth of blocks. When
--     the state is exhausted, finalize, compare to manifest hash, append
--     to s.diff.mismatched on miss, advance lua_idx.
-- When lua_idx walks past #to_hash with no s.cur set, hand off to _complete.
function Updater.tick_sha_diff()
  local s = update._sha_diff
  if not s then return end
  local to_hash = s.to_hash

  if not s.cur then
    while s.lua_idx <= #to_hash do
      local item = to_hash[s.lua_idx]
      local f, open_err = io.open(item.path, "rb")
      if not f then
        s.diff.locked[#s.diff.locked+1] = item.entry.name
        Log.line("UPDATE", string.format(
          "tick_sha_diff: %s preflight readable but open failed: %s "
          .. "(likely AV / editor lock; recording as locked)",
          item.path, tostring(open_err)))
        s.lua_idx = s.lua_idx + 1
      else
        local content = f:read("*a")
        f:close()
        if content then
          s.cur = { entry = item.entry, state = _SHA.create(content) }
          break
        else
          s.diff.locked[#s.diff.locked+1] = item.entry.name
          Log.line("UPDATE", string.format(
            "tick_sha_diff: %s opened but read returned nil "
            .. "(treating as locked)", item.path))
          s.lua_idx = s.lua_idx + 1
        end
      end
    end
    if not s.cur then
      Updater._sha_diff_complete()
      return
    end
  end

  -- File in flight: compress as many 16-block chunks as fit inside the
  -- per-tick time budget. The chunk size is small enough that the budget
  -- check stays meaningful on slow hardware (one chunk ~= 1 ms on a
  -- commodity CPU; would-be 5+ ms on a very old CPU still stops after a
  -- single chunk, which is still better than the previous 192-block
  -- fixed budget would have been on the same hardware).
  local tick_start = time_precise()
  local budget = s.budget or CFG.UPDATE_SHA_TIME_BUDGET
  local done
  repeat
    done = _SHA.step(s.cur.state, 16)
    if done then break end
  until (time_precise() - tick_start) >= budget
  if done then
    local local_hash = _SHA.finalize(s.cur.state)
    if local_hash ~= s.cur.entry.sha256:lower() then
      s.diff.mismatched[#s.diff.mismatched+1] = s.cur.entry.name
    end
    s.cur     = nil
    s.lua_idx = s.lua_idx + 1
  end
end

-- The manifest entries a finished pass neither verified nor queued for
-- replacement, split by why (Codex round 20, blocker 1).
--
-- Two ways in. A file that is on disk and cannot be READ is recorded as
-- locked, and the repair purpose skips locked files on purpose: a transient
-- antivirus or editor lock must not raise a Repair-Available popup on an
-- install nobody has any reason to doubt. The update purpose does not skip
-- them, because download_start folds locked files into the queue and the apply
-- either replaces them or fails out loud, so nothing there is left unaccounted
-- for. And an entry start_sha_diff would not act on at all is hashed by
-- nothing and downloaded by nothing in either purpose.
--
-- The standing quarantine gate and first-install bootstrap consult this.
-- Everywhere else the lenient behaviour above is the shipped one and stays
-- exactly as it was.
function Updater.unverified_entries(diff, purpose)
  local unreadable, unverifiable = {}, {}
  if purpose ~= "update" then
    for _, name in ipairs((type(diff) == "table" and diff.locked) or {}) do
      unreadable[#unreadable+1] = name
    end
  end
  for _, name in ipairs((type(diff) == "table" and diff.unverifiable) or {}) do
    unverifiable[#unverifiable+1] = name
  end
  return unreadable, unverifiable
end

-- A first-install bootstrap may reach a clean body without applying a file in
-- this process. This happens when the launcher or a prior bootstrap instance
-- finished the install immediately before this instance completed its full
-- check. A clean check must relaunch so startup can load the verified UI and
-- mark the first launch complete. An incomplete check must stay on the setup
-- surface and name what could not be verified.
function Updater.first_install_verification_incomplete(unreadable,
                                                       unverifiable, elapsed)
  local function listed(names)
    local lines = {}
    for i = 1, math.min(#names, 8) do
      lines[#lines+1] = "  " .. Updater.display_name(names[i])
    end
    if #names > 8 then
      lines[#lines+1] = string.format("  and %d more", #names - 8)
    end
    return table.concat(lines, "\n")
  end
  local parts = {
    "ReaAssist could not check every installed file, so setup cannot finish.",
  }
  if #unreadable > 0 then
    parts[#parts+1] = (#unreadable == 1
        and "This file could not be read:"
        or  "These files could not be read:")
      .. "\n" .. listed(unreadable)
      .. "\n\nAnother program, such as antivirus, a backup tool or an open "
      .. "editor, may be holding " .. (#unreadable == 1 and "it" or "them")
      .. " open."
  end
  if #unverifiable > 0 then
    parts[#parts+1] = (#unverifiable == 1
        and "This entry in the update manifest could not be checked:"
        or  "These entries in the update manifest could not be checked:")
      .. "\n" .. listed(unverifiable)
  end
  parts[#parts+1] = "Nothing was changed. Close anything that has these files "
    .. "open, then retry setup."
  update.silent_manifest_repair  = false
  update._silent_manifest_manual = false
  update.restart_after = nil
  update.restart_fired = nil
  update.state = "failed"
  Updater._set_failure("install_verify", table.concat(parts, "\n\n"))
  local total = #unreadable + #unverifiable
  Log.line("UPDATE", string.format(
    "first-install check finished in %.2fs without covering %d manifest "
    .. "entr%s (%d unreadable, %d not checkable); setup remains open.",
    elapsed or 0, total, total == 1 and "y" or "ies",
    #unreadable, #unverifiable))
end

-- Apply the result of a completed incremental SHA diff. Same branch logic as
-- the inline block that lived in check_poll before the refactor: a non-empty
-- diff transitions to "repair_available" with the popup, an empty diff
-- transitions to "idle" with the manual-check toast (or silence for the
-- piggyback). Clears update._sha_diff so a stale snapshot can never leak
-- into a later check.
function Updater._sha_diff_complete()
  local s = update._sha_diff
  if not s then return end
  local diff     = s.diff
  local manifest = s.manifest
  local manual   = s.manual
  local forced   = s.forced
  local purpose  = s.purpose or "repair"
  local elapsed  = time_precise() - (s.started_at or time_precise())
  local first_install = S and S.bootstrap_active == true
    and S.bootstrap_install_mode == true
  update._sha_diff = nil

  -- Ahead of both purposes, because a standing gate changes what an unchecked
  -- entry means (Codex round 20, blocker 1). The gate is waiting for somebody
  -- to vouch for this install, and this pass is the only thing that can; an
  -- entry it could not read or would not act on is precisely the entry a
  -- half-finished rename is most likely to have left behind. Neither outcome
  -- below may be reached with one of those outstanding: the clean branch would
  -- clear the record having skipped it, and the repair branch would clear at
  -- its commit point having repaired around it.
  if S and S.quarantine_gate then
    local unreadable, unverifiable = Updater.unverified_entries(diff, purpose)
    if #unreadable > 0 or #unverifiable > 0 then
      Updater.quarantine_repair_incomplete(unreadable, unverifiable, elapsed)
      return
    end
  end
  if first_install then
    local unreadable, unverifiable = Updater.unverified_entries(diff, purpose)
    if #unreadable > 0 or #unverifiable > 0 then
      Updater.first_install_verification_incomplete(
        unreadable, unverifiable, elapsed)
      return
    end
  end

  if purpose == "update" then
    update.silent_manifest_repair = false
    update._silent_manifest_manual = false
    update.state             = "available"
    update.remote_version    = manifest.version
    update.manifest          = manifest
    update.update_missing    = diff.missing
    update.update_mismatched = diff.mismatched
    -- Locked files ride in their own list for the update purpose:
    -- download_start folds them into the queue. Re-downloading a file
    -- that might have matched anyway is harmless and cheap; the apply
    -- stage's rename retry absorbs a transient lock, and a persistent
    -- lock becomes an explicit "rename" failure instead of a version
    -- bump that silently keeps old code in the locked file. Kept apart
    -- from update_mismatched so logs and diagnostics stay truthful
    -- (mismatched means "hashed and differed"; locked means "unreadable,
    -- queued defensively").
    update.update_locked     = diff.locked
    Log.line("UPDATE", string.format(
      "sha_diff complete in %.2fs: remote v%s newer than installed v%s; "
      .. "%d file(s) differ (%d missing, %d mismatched, %d locked).",
      elapsed, tostring(manifest.version), tostring(CFG.VERSION),
      #diff.missing + #diff.mismatched + #diff.locked,
      #diff.missing, #diff.mismatched, #diff.locked))
    if manual then S.float_toast = nil end
    if not forced and not manual then
      local snooze = Store.update_snooze()
      if snooze and os.time() < snooze then
        update.popup_opened = true
      end
    end
    return
  end

  -- Repair purpose: locked files stay OUT of the repair count and the
  -- repair queue. Transient AV / editor locks must not cause false
  -- Repair-Available popups, and a repair that cannot read a file to
  -- prove it broken has no business overwriting it. A genuinely
  -- corrupted-and-locked file heals on a later check once the lock
  -- clears (or through the update purpose above on the next release).
  local repair_count = #diff.missing + #diff.mismatched
  if repair_count > 0 then
    update.state          = "repair_available"
    update.remote_version = manifest.version  -- same as CFG.VERSION; kept
                                              -- for consistent popup format
    update.manifest       = manifest
    update.repair_missing    = diff.missing
    update.repair_mismatched = diff.mismatched
    -- Not under a standing quarantine gate. The silent lane applies one file
    -- and deliberately vouches for nothing else, which is exactly why
    -- _apply_finish excludes it from clearing the gate; routing the gate's own
    -- repair through it would leave the gate up forever with nothing left to
    -- fix. The ordinary repair flow runs instead, visibly, and commits.
    if Updater.is_manifest_only_repair(diff)
        and not (S and S.quarantine_gate) then
      update.silent_manifest_repair = true
      update._silent_manifest_manual = manual == true or forced == true
      update.show_dialog = false
      update.popup_opened = false
      if manual then S.float_toast = nil end
      Log.line("UPDATE", string.format(
        "sha_diff complete in %.2fs: only %s needs transition repair; "
        .. "starting silent verified self-heal.", elapsed,
        tostring(CFG.UPDATE_MANIFEST)))
      Updater.try_silent_manifest_repair()
      return
    end
    update.silent_manifest_repair = false
    update._silent_manifest_manual = false
    Log.line("UPDATE", string.format(
      "sha_diff complete in %.2fs: version matches (%s) but %d files "
      .. "need repair (%d missing, %d mismatched; %d locked skipped).",
      elapsed, manifest.version, repair_count,
      #diff.missing, #diff.mismatched, #diff.locked))
    -- Match the "available" branch: clear the sticky "Checking..."
    -- toast so the repair popup is the sole visual feedback.
    if manual then S.float_toast = nil end
  else
    update.silent_manifest_repair = false
    update._silent_manifest_manual = false
    if first_install then
      -- The install became complete before this process needed to apply
      -- anything. Relaunch through the verified sidecar so the next startup
      -- loads UI.lua and records first_launch_complete. Without this branch,
      -- install mode stays on its minimal Installing surface forever.
      update.state = "done"
      update.applied_files = update.applied_files or {}
      if reaper.file_exists(RELAUNCHER_PATH) then
        update.restart_after = time_precise() + 1.5
        update.restart_fired = false
      else
        update.restart_after = nil
        update.restart_fired = nil
      end
    else
      update.state = "idle"  -- already up to date and all files intact
    end
    Log.line("UPDATE", string.format(
      "sha_diff complete in %.2fs: version matches (%s) and all files "
      .. "intact (%d locked skipped).", elapsed, manifest.version,
      #diff.locked))
    -- A standing quarantine gate ends here too, and this is the answer it was
    -- waiting for. The gate means nobody had verified the install since an
    -- unreadable record touched it; a full pass over every manifest entry that
    -- finds each one matching its published hash IS that verification, and
    -- there is no apply to reach _apply_finish's clear with. Refusing to
    -- clear on a clean result would gate the launch forever precisely because
    -- the install turned out to be healthy (B2.2d requirement 4).
    if S and S.quarantine_gate then Updater.quarantine_repair_verified() end
    -- Stamp the last-successful-check time so the footer's version-
    -- number tooltip can show "Up to date (checked X ago)" instead
    -- of the generic "Click to check for updates" copy. Applies to
    -- both manual checks (Settings button / footer link) and the
    -- auto-fired piggyback check after the first chat response.
    update._last_ok_at = os.time()
    -- Manual check (Settings button / version-number link) with no
    -- action needed -> give the user explicit feedback that their
    -- click did something. Auto-fired checks stay silent.
    if manual then
      UI.show_float_toast(
        "ReaAssist is up to date (v" .. CFG.VERSION .. ")", "ok")
    end
  end
end

function Updater.check_poll()
  local result = Updater.poll()
  if result == "waiting" then return end
  -- Snapshot-and-clear both one-shot flags before any return path so a
  -- single force_reinstall / manual_check call cannot leak into a
  -- later organic check. Without this, update.force stayed true after
  -- consumption, and subsequent startup checks were misclassified as
  -- "available" even when the user was already on the current version,
  -- feeding the wrong action_was_repair bool into download_start's
  -- completion copy. _manual follows the same snapshot pattern so the
  -- "You're up to date" toast only fires for the check the user just
  -- clicked, not any later one.
  local forced = update.force
  update.force = false
  local manual = update._manual
  update._manual = false
  if result == "error" then
    -- Network / curl failure. Only surface as a failure when the user
    -- explicitly forced this check (Repair button): organic startup
    -- checks fail silently so offline launches do not nag the user.
    if forced then
      Updater._set_failure("manifest_fetch",
        "Could not reach update server (network error or timeout).\n\n"
        .. "Please enable your network connection if it is disabled.")
    end
    -- Manual Settings button: replace the sticky "Checking..." toast
    -- with a transient error message so the user sees explicit failure
    -- feedback on their explicit action.
    if manual then
      UI.show_float_toast(
        "Could not reach update server\nCheck your network connection",
        "err")
    end
    update.state = "idle"
    return
  end
  -- Parse manifest.
  local manifest, manifest_raw = Updater.read_response()
  if not manifest
    or type(manifest.version) ~= "string"
    or type(manifest.files) ~= "table" then
    -- Distinguish empty / near-empty response (connection dropped
    -- silently, typical of offline on Windows where DNS cache may let
    -- curl exit with status 0 even though no bytes were received) from
    -- a body that actually contained something but wasn't valid JSON.
    -- Empty body is surfaced as a connection error so the user's toast
    -- / Bootstrap error message points at the likely cause instead of
    -- blaming the server for "malformed" output.
    local body_size = 0
    local bf = io.open(tmp.update_out, "rb")
    if bf then
      bf:seek("end")
      body_size = bf:seek("cur")
      bf:close()
    end
    local empty = (body_size < 2)
    if forced then
      if empty then
        Updater._set_failure("manifest_fetch",
          "Could not reach update server (no response received).\n\n"
          .. "Please enable your network connection if it is disabled.")
      else
        Updater._set_failure("manifest_parse",
          "Update server returned a malformed manifest "
          .. "(missing version or files field).")
      end
    end
    if manual then
      if empty then
        UI.show_float_toast(
          "Could not reach update server\nCheck your network connection",
          "err")
      else
        UI.show_float_toast(
          "Update server returned a malformed response", "err")
      end
    end
    update.state = "idle"
    return
  end
  local manifest_ok, manifest_err = Updater.attach_manifest_payload(
    manifest, manifest_raw)
  if not manifest_ok then
    if forced then
      Updater._set_failure("manifest_parse",
        "Update server returned an unusable manifest ("
          .. tostring(manifest_err) .. ").")
    end
    if manual then
      UI.show_float_toast(
        "Update server returned a malformed response", "err")
    end
    update.state = "idle"
    return
  end
  -- Three-way version compare so we never repair against an older manifest
  -- (which would effectively downgrade the install). Equality via the
  -- "neither newer" rule because is_newer parses numerically (so "1.0.0"
  -- and "1.0.0.0" compare equal even though string == would say false).
  update.update_missing = nil
  update.update_mismatched = nil
  update.update_locked = nil
  local remote_newer = Updater.is_newer(manifest.version, CFG.VERSION)
  local remote_older = Updater.is_newer(CFG.VERSION, manifest.version)
  if remote_newer then
    -- A newer version is on the server. The update flow handles this case --
    -- first compute the changed-file set asynchronously, then show
    -- "Update Available". That moves the SHA work before the prompt so
    -- clicking Update Now can immediately enter the download UI.
    Updater.start_sha_diff(manifest, manual, forced, "update")
  elseif not remote_older then
    -- Versions match. But the local install may still have missing or
    -- corrupted files (user deleted something, disk error, partial copy).
    -- Normally we run the per-file SHA diff to find them, deferred across
    -- frames so REAPER stays responsive (synchronous diff would freeze
    -- the UI for ~100-500 ms hashing ~5-6 MB of fonts and large .lua
    -- files). See Updater.start_sha_diff / tick_sha_diff for the
    -- incremental machine.
    --
    -- Bootstrap fast-path: when this check fired from the Bootstrap
    -- repair button (`update._bootstrap_repair == true`), we already
    -- know which files are missing/broken from the critical-files probe
    -- at startup -- skip the SHA verify entirely and route directly to
    -- repair_available with the known list. The trade-off: SHA-level
    -- corruption in non-critical files won't be caught by THIS repair,
    -- but the next non-bootstrap launch's normal SHA verify will.
    if update._bootstrap_repair then
      update._bootstrap_repair = nil
      update.manifest          = manifest
      update.remote_version    = manifest.version
      -- S.bootstrap_missing entries can carry a " (load error)" suffix
      -- (added by the font-load probe) that is presentation-only and
      -- not part of the manifest filename; strip before queueing.
      local missing = {}
      for _, name in ipairs(S.bootstrap_missing or {}) do
        local clean = name:gsub("%s*%(load error%)$", "")
        missing[#missing + 1] = clean
      end
      update.repair_missing    = missing
      update.repair_mismatched = {}
      update.state             = "repair_available"
      Log.line("UPDATE", string.format(
        "check_poll: bootstrap fast-path armed; queueing %d known-broken "
        .. "file(s) without SHA verify.", #missing))
      if manual then S.float_toast = nil end
    else
      Updater.start_sha_diff(manifest, manual, forced)
    end
  elseif forced then
    -- Remote manifest is older than installed AND user explicitly asked to
    -- reinstall. Repairing against an older manifest would effectively
    -- downgrade the install; refuse with a specific failure so the
    -- "Update Failed" dialog can surface the cause.
    Updater._set_failure("manifest_version", string.format(
      "Update server returned manifest v%s, older than installed v%s. "
      .. "Refusing to repair against an older manifest.",
      tostring(manifest.version), tostring(CFG.VERSION)))
    update.state = "failed"
  else
    -- Remote manifest is older than installed and the user didn't force a
    -- reinstall. Most likely a CDN propagation race or a stale branch.
    -- Skip silently for auto-fire piggyback checks; surface a brief toast
    -- for explicit manual checks so the user knows the click was processed.
    update.state = "idle"
    Log.line("UPDATE", string.format(
      "Remote manifest is older (v%s) than installed (v%s); "
      .. "skipping repair check.",
      tostring(manifest.version), tostring(CFG.VERSION)))
    if manual then
      UI.show_float_toast(
        "Update server returned an older manifest; try again later.",
        "err", true)
    end
  end
end

-- Historical development journals can name these bundled files during
-- recovery. New download lists reject them in app_files_exclude_native.
-- Keep filename validation separate from admission of a new download list.
local UPDATER_ENGINE_NATIVE_FILES = {
  ["Resources/Engine/win-x64/reaper_mbriggs_helper-x64.dll"] = true,
  ["Resources/Engine/win-arm64/reaper_mbriggs_helper-arm64.dll"] = true,
  ["Resources/Engine/mac-arm64/reaper_mbriggs_helper-arm64.dylib"] = true,
  ["Resources/Engine/mac-x64/reaper_mbriggs_helper-x86_64.dylib"] = true,
  ["Resources/Engine/linux-x64/reaper_mbriggs_helper-x86_64.so"] = true,
  ["Resources/Engine/linux-arm64/reaper_mbriggs_helper-aarch64.so"] = true,
}

-- Validate a manifest filename: no path traversal, no absolute paths, safe extension.
-- Forward-slash subpaths are allowed (e.g. "Resources/UI.lua",
-- "Resources/ReEQ/Dependencies/svf_filter.jsfx-inc") so the manifest can mirror
-- the on-disk layout. Backslashes, leading slashes, drive letters, and any
-- ".." or hidden ("."-prefixed) path segments are rejected.
function Updater.is_safe_filename(name)
  if type(name) ~= "string" or name == "" then return false end
  -- Strict allowlist: only ASCII alphanumerics, spaces, underscore,
  -- hyphen, dot, and forward slash. Blocks shell-sensitive characters
  -- ($, `, &, ?, #, ;, parens, quotes, etc.) before they ever reach a
  -- curl command line or a local path. The remaining checks below run
  -- after the allowlist as defense-in-depth.
  if not name:match("^[A-Za-z0-9_./ %-]+$") then return false end
  -- Reject backslashes, leading /, drive letters (absolute paths).
  if name:match("^/") or name:match("^%a:") then return false end
  if name:find("\\", 1, true) then return false end
  -- Validate each forward-slash-separated path segment.
  for segment in (name .. "/"):gmatch("([^/]*)/") do
    if segment == "" or segment == "." or segment == ".." then return false end
    if segment:sub(1, 1) == "." then return false end  -- hidden dotfiles/dirs
    if segment:sub(1, 1) == " " or segment:sub(-1) == " " then return false end
  end
  -- The final segment is the filename itself.
  local base_name = name:match("([^/]+)$") or name
  -- Reject Windows reserved device names (CON, PRN, AUX, NUL, COM1-9, LPT1-9).
  local base = base_name:match("^([^%.]+)") or ""
  if RA.is_windows_reserved_name(base) then return false end
  -- Allow only known safe extensions.
  local ext = base_name:match("%.([^%.]+)$")
  if not ext then return false end
  local safe = {
    lua=true, md=true, txt=true, jsfx=true, ["jsfx-inc"]=true,
    json=true, png=true, csv=true, pdf=true,
    -- .ttf added in Stage 3.4: Resources/fonts/*.ttf are part of the
    -- distributable install (the bootstrap critical-files check verifies
    -- them at launch), so the download pipeline has to accept them.
    ttf=true,
  }
  if safe[ext:lower()] then return true end
  return UPDATER_ENGINE_NATIVE_FILES[name] == true
end

-- Join a manifest-shaped name ("Resources/X.md") onto a root, using the host
-- OS separator. The two callers below are the only ones: which root a name
-- belongs to is the whole question, and neither of them should be spelling
-- the separator swap itself.
function Updater.name_under(root, filename)
  local rel = filename
  if RA.SEP ~= "/" then rel = rel:gsub("/", RA.SEP) end
  return root .. rel
end

-- Resolve a manifest filename ("Resources/X.md") to an absolute local path
-- using the host OS separator. Centralized so the SHA-diff verifier and
-- the apply pipeline (the write target) agree on the layout.
--
-- Every manifest name resolves under the app root. That is the whole of the
-- updater's zone: what it hashes, what it stages, what it swaps in, and what
-- orphan removal is allowed to reach. The package root above it holds Data/,
-- Recovery/ and the two ReaPack-owned launchers, and no manifest name can
-- name its way out of App/ because is_safe_filename refuses `..` and
-- absolute paths before this function ever sees one.
--
-- Journal entries are the one thing that does NOT resolve here: a journal
-- records what some earlier run was applying, and a pre-restructure run
-- meant its names package-relative. Updater.journal_path_for is the resolver
-- for those.
function Updater.local_path_for(filename)
  return Updater.name_under(RA.APP_DIR, filename)
end

-- =============================================================================
-- Launcher ownership and the launchers manifest section
-- =============================================================================
-- The two entrypoints at the PACKAGE root are the action identities and can
-- never move (Distribution Unification section 2). Everything else about them
-- is conditional, and this is where the condition is decided.
--
-- Who owns them is a property of the INSTALL, not of the product. A ReaPack
-- install has them registered to the package, and ReaPack keeps them alive on
-- its own: a same-version sync reinstalls a registered file that has been
-- deleted from disk (measured against real ReaPack 1.2.6, section 3a row E4).
-- A website or manual install has no owner at all, and those users only ever
-- get a launcher fix from the app. So the app services the second kind and
-- never writes the first kind.
--
-- Per launcher, never per install. One of each is a real state: a user can
-- sync a package carrying only the standard launcher and have the Screen
-- Reader one restored by the app, or the reverse.
--
-- The question has FOUR answers and only one of them permits a write (Codex
-- round 25, B2.3 blocker 1). An earlier revision had two, folding "somebody
-- else's package owns this" and "the question could not be answered" into
-- unowned on the reasoning that being wrong towards owned strands a user. That
-- reasoning was rejected, and rightly: unowned is a POSITIVE finding (ReaPack
-- answered, and no package claims the file), while a foreign owner and a failed
-- lookup are the absence of a finding. Writing on the absence of a finding
-- overwrites a file this app did not install, on the say-so of a call that
-- failed.
--
--   unowned   ReaPack answered and no package owns the file, OR ReaPack is not
--             installed at all (section 2: nothing else is going to keep the
--             launchers alive, so the app is the only thing that can). The one
--             state that may be hashed, queued, journaled or written.
--   owned     an exact registry-identity match: this is our ReaPack package's
--             copy. Never written; ReaPack reinstalls it on the next sync.
--   foreign   a non-nil owner whose identity is not ours. Never written, and
--             said out loud, because the way back for that user is not the same
--             as for ours.
--   unknown   GetOwner raised, GetEntryInfo raised, GetEntryInfo declined to
--             describe the entry, or the ownership API is in a shape this body
--             cannot use (reapack_api_state below). Never written, and never
--             reported as though the answer were known.
--
-- The two refusing states are not blocking states. Standing on a file this body
-- is forbidden to write would gate an install forever over something it cannot
-- fix, which is the same wrong the ReaPack-owned case already avoids, so they
-- surface as advisories with copy of their own rather than as failures.
Updater.OWNERSHIP_UNOWNED = "unowned"
Updater.OWNERSHIP_OWNED   = "owned"
Updater.OWNERSHIP_FOREIGN = "foreign"
Updater.OWNERSHIP_UNKNOWN = "unknown"

-- The three shapes the ownership API itself can be in (reapack_api_state).
-- Only the first is an absence this body may act on.
Updater.REAPACK_API_ABSENT        = "absent"
Updater.REAPACK_API_READY         = "ready"
Updater.REAPACK_API_INDETERMINATE = "indeterminate"

Updater.LAUNCHER_FILES = {
  "ReaAssist.lua",
  "ReaAssist_Screen_Reader_Mode.lua",
}

-- The registry key ReaPack answers with, in full. Package and category alone
-- are not the whole key (section 3, "Registry identity"): a different index
-- publishing a category and package with our names is a different package, and
-- its files are not ours to service or to leave alone on our say-so.
Updater.REAPACK_INDEX    = "mbriggs-reaper"
Updater.REAPACK_CATEGORY = "ReaAssist"
Updater.REAPACK_PACKAGE  = "ReaAssist.lua"
-- ReaPack's Package::ScriptType. The type is part of the key and the API hands
-- it back as an integer, so it is compared as one; anything else is a package
-- of a kind we do not publish and therefore not ours.
Updater.REAPACK_TYPE_SCRIPT = 1

function Updater.is_launcher_name(name)
  if type(name) ~= "string" then return false end
  for _, known in ipairs(Updater.LAUNCHER_FILES) do
    if name == known then return true end
  end
  return false
end

-- Where a launcher lives: the package root, always, and never the app root.
function Updater.launcher_path(name)
  return Updater.name_under(RA.PACKAGE_DIR, name)
end

-- The name a launcher travels under inside the updater's own lists.
--
-- After the restructure one filename means two files (section 3b): the body's
-- App-relative `ReaAssist.lua` and the launcher at the package root. The diff
-- lists, the repair filesets and the queue lookup are all keyed by name, so a
-- launcher carries a qualified key through them. The prefix contains a colon,
-- which Updater.is_safe_filename refuses outright, so a key can never be
-- mistaken for a manifest name or joined onto a root by accident.
function Updater.launcher_key(name)
  return "launcher:" .. tostring(name)
end

function Updater.key_is_launcher(key)
  return type(key) == "string" and key:sub(1, 9) == "launcher:"
end

-- What a key is called when a person reads it. The prefix is an internal
-- disambiguator and means nothing to the user, whose install has exactly one
-- file with that name that they have ever seen.
function Updater.display_name(key)
  if Updater.key_is_launcher(key) then return key:sub(10) end
  return tostring(key)
end

-- The package-root download base for a given App base.
--
-- Launcher names are package-relative and every other name the updater
-- downloads is App-relative, so the two hang off different bases. The App base
-- is the configured one (and, for a release, the tag-pinned one), and the
-- package base is its parent -- derived rather than configured, so the two can
-- never be pointed at different releases.
--
-- Returns nil when the base does not end in `/App`, which is the pre-N shape.
-- That is a refusal, not a fallback: guessing a parent for a base that is not
-- the App view would build launcher URLs out of a directory nobody published.
function Updater.package_base_url(base)
  local b = tostring(base or ""):gsub("/+$", "")
  local parent = b:match("^(.+)/App$")
  if parent and parent ~= "" then return parent end
  return nil
end

-- What shape is the ReaPack ownership API in on this REAPER? THREE answers, and
-- the difference between two of them is the difference between writing a
-- launcher and leaving it alone (Codex round 26, B2.3b blocker 1).
--
-- This used to answer one boolean, and false collapsed four different worlds
-- into one: ReaPack genuinely not installed, APIExists itself raising, a
-- PARTIAL API (GetOwner there and a sibling missing), and a name reported
-- present but not bound. launcher_owner_probe then read every false as
-- "ReaPack absent", which is a POSITIVE finding of unowned, so three shapes
-- that answer nothing at all ended up permitting a write.
--
--   "absent"        CONFIRMED not there. APIExists is callable, it answered
--                   FALSE for ReaPack_GetOwner without raising, and the field
--                   is not bound either. That is the one absence that is a
--                   finding: no ReaPack means no owner (section 2), so the
--                   launchers are the app's to keep alive.
--   "ready"         all three functions confirmed present AND bound.
--   "indeterminate" everything else. Never a finding, so never a write.
--
-- WHY THE ANSWER IS ANCHORED ON GetOwner. It is the only entry point: with no
-- GetOwner there is no handle, so GetEntryInfo and FreeEntry can never be
-- called and their presence cannot change any outcome. A confirmed-absent
-- GetOwner is therefore sufficient on its own and the siblings are not
-- consulted in that branch at all. The moment GetOwner IS there the siblings
-- become load-bearing and both must be confirmed too, because a probe missing
-- FreeEntry has to leak an entry for the life of the session and a probe
-- missing GetEntryInfo has to decide on an entry it cannot read. Partial is
-- indeterminate, deliberately: half an API answers half a question.
--
-- The contradiction is indeterminate too. APIExists saying false about a name
-- that IS bound is not a machine this body understands, and reading it as
-- "ReaPack is not installed" would write a launcher on the strength of a
-- disagreement.
--
-- Returns the state plus a short reason for the log and the advisory.
function Updater.reapack_api_state()
  if type(reaper) ~= "table" then
    return Updater.REAPACK_API_INDETERMINATE, "no reaper table to ask"
  end
  if type(reaper.APIExists) ~= "function" then
    -- Nothing here can CONFIRM an absence, and an unconfirmed absence is not
    -- one. Fail closed rather than infer ReaPack's absence from REAPER's.
    return Updater.REAPACK_API_INDETERMINATE,
      "reaper.APIExists is not available, so nothing can be confirmed"
  end
  local ok_owner, owner_present = pcall(reaper.APIExists, "ReaPack_GetOwner")
  if not ok_owner then
    return Updater.REAPACK_API_INDETERMINATE, "APIExists raised for "
      .. "ReaPack_GetOwner"
  end
  if not owner_present then
    if type(reaper.ReaPack_GetOwner) == "function" then
      return Updater.REAPACK_API_INDETERMINATE,
        "APIExists says ReaPack_GetOwner is absent while it is bound"
    end
    return Updater.REAPACK_API_ABSENT,
      "ReaPack ownership API not present"
  end
  for _, fn in ipairs({ "ReaPack_GetOwner", "ReaPack_GetEntryInfo",
                        "ReaPack_FreeEntry" }) do
    local ok, present = pcall(reaper.APIExists, fn)
    if not ok then
      return Updater.REAPACK_API_INDETERMINATE, "APIExists raised for " .. fn
    end
    if not present then
      return Updater.REAPACK_API_INDETERMINATE, fn .. " is missing while "
        .. "ReaPack_GetOwner is present, so the answer would cost a leak or "
        .. "an unreadable entry"
    end
    if type(reaper[fn]) ~= "function" then
      return Updater.REAPACK_API_INDETERMINATE, fn .. " is reported present "
        .. "but is not bound"
    end
  end
  return Updater.REAPACK_API_READY, "ReaPack ownership API present"
end

-- Ask ReaPack who owns one launcher file. Returns one of the four states above
-- plus a short reason for the log and for the user-facing advisory.
--
-- ReaPack_GetOwner returns an opaque entry handle plus an error string, and
-- every non-nil handle has to be released with ReaPack_FreeEntry -- including
-- the path where reading it raises, which is why the read is pcall'd into a
-- table and the free happens before anything is decided. Leaking one leaks for
-- the life of the REAPER session.
--
-- ReaPack_GetEntryInfo's returns, in order:
--   retval, repo, category, package, description, type, version, author,
--   pinned, file_count
-- The pcall wrapper shifts all of them by one, which is why they are read out
-- of an indexed table here rather than into named locals. (Dev/ReaPackSmoke's
-- probe made exactly that mistake and has been corrected; it now prints the
-- whole identity tuple so a live run can check these constants against a real
-- registry.)
-- WHO OWNS THE FILE AT THIS PATH, asked of any path rather than of a launcher.
--
-- Split out of launcher_owner_probe for the legacy-cleanup lane, which has to
-- ask the same question about files that are not launchers, and split rather
-- than copied so there is one answer and not two that can disagree. Everything
-- below the path was already path-generic; only the resolution of a launcher
-- NAME to a launcher PATH belonged to the caller, and that is all that stayed
-- there. The launcher lane's answers, details and logging are unchanged, and a
-- harness row holds the two together on every one of the four states.
function Updater.reapack_owner_of(path)
  -- ReaPack CONFIRMED absent is a positive unowned (section 2), and it is the
  -- only absence that is. A ReaPack that is there and will not answer, an
  -- APIExists that raises, and a half-present API are all indeterminate, and an
  -- indeterminate API is unknown rather than writable (Codex round 26).
  local api, api_detail = Updater.reapack_api_state()
  if api == Updater.REAPACK_API_ABSENT then
    return Updater.OWNERSHIP_UNOWNED, api_detail
  end
  if api ~= Updater.REAPACK_API_READY then
    return Updater.OWNERSHIP_UNKNOWN, api_detail
  end
  local ok_owner, entry = pcall(reaper.ReaPack_GetOwner, path)
  if not ok_owner then
    return Updater.OWNERSHIP_UNKNOWN, "ReaPack_GetOwner raised"
  end
  if not entry then
    return Updater.OWNERSHIP_UNOWNED, "no ReaPack package owns this file"
  end
  local info = { pcall(reaper.ReaPack_GetEntryInfo, entry) }
  pcall(reaper.ReaPack_FreeEntry, entry)
  if not info[1] then
    return Updater.OWNERSHIP_UNKNOWN, "ReaPack_GetEntryInfo raised"
  end
  if info[2] ~= true then
    return Updater.OWNERSHIP_UNKNOWN, "ReaPack_GetEntryInfo declined"
  end
  local repo, category, package, ptype =
    tostring(info[3]), tostring(info[4]), tostring(info[5]), info[7]
  if repo == Updater.REAPACK_INDEX
      and category == Updater.REAPACK_CATEGORY
      and package == Updater.REAPACK_PACKAGE
      and tonumber(ptype) == Updater.REAPACK_TYPE_SCRIPT then
    return Updater.OWNERSHIP_OWNED,
      "owned by " .. repo .. "/" .. category .. "/" .. package
  end
  return Updater.OWNERSHIP_FOREIGN, string.format(
    "owned by a different package (%s/%s/%s type %s), so not ours",
    repo, category, package, tostring(ptype))
end

-- Which of the four states this LAUNCHER is in. The launcher path is the only
-- thing this adds; every answer comes from the shared core above.
function Updater.launcher_owner_probe(name)
  return Updater.reapack_owner_of(Updater.launcher_path(name))
end

-- Clear the per-session ownership answers so the next question re-asks
-- ReaPack.
--
-- Called at the two points that decide, and no others: the start of a check's
-- SHA pass, which decides which launchers get hashed, and the start of
-- download_start, which decides which get queued. The second is not
-- redundant. A user can install or remove ReaPack between the check and the
-- click, and writing a launcher ReaPack owns is the one outcome this whole
-- mechanism exists to prevent, so the answer is refreshed immediately before
-- it is acted on.
--
-- Neither of them is the last word. The queue is built before the download
-- runs, and a synchronization inside that window can change the answer again,
-- so the swap itself asks once more through launcher_writable_now, which does
-- not read this cache at all.
function Updater.launcher_owner_refresh()
  Updater._launcher_owner = nil
end

-- Which of the four states this launcher is in, cached for the session.
-- Returns the state plus the detail that produced it.
--
-- Cached because the answer costs an extension call and a registry lookup per
-- file and is asked from the SHA walk, the queue build and the serviceability
-- gate within one pass. Computed lazily, so a session that never runs the
-- updater and never hits a quarantine gate never asks at all.
function Updater.launcher_ownership(name)
  Updater._launcher_owner = Updater._launcher_owner or {}
  local cached = Updater._launcher_owner[name]
  if cached == nil then
    local state, detail = Updater.launcher_owner_probe(name)
    cached = { state = state, detail = detail }
    Updater._launcher_owner[name] = cached
    Log.line("UPDATE", string.format(
      "launcher ownership: %s is %s (%s)", name, state, tostring(detail)))
  end
  return cached.state, cached.detail
end

-- May this body write this launcher? Only a confirmed unowned one, ever.
function Updater.launcher_writable(name)
  return Updater.launcher_ownership(name) == Updater.OWNERSHIP_UNOWNED
end

-- The same question at the destructive moment, deliberately NOT from the cache
-- (Codex round 25, B2.3 blocker 1).
--
-- The queue is built before the download runs and the swap happens after it,
-- and a ReaPack synchronization inside that window can hand a queued launcher
-- an owner. Every package-root swap therefore re-asks here, immediately before
-- it touches the file, and a launcher that is no longer confirmed unowned is
-- skipped rather than written.
--
-- The fresh answer replaces the cached one, so everything asked afterwards in
-- this session (the serviceability gate, the advisory the user reads) is
-- looking at what was true at the moment that mattered rather than at what was
-- true when the queue was built.
function Updater.launcher_writable_now(name)
  local state, detail = Updater.launcher_owner_probe(name)
  Updater._launcher_owner = Updater._launcher_owner or {}
  Updater._launcher_owner[name] = { state = state, detail = detail }
  return state == Updater.OWNERSHIP_UNOWNED, state, detail
end

-- The launchers section of a manifest, or a refusal.
--
-- Section 3b: unowned-launcher servicing uses a section of its own carrying
-- package-root-relative paths, and it is an ALLOWLIST OF TWO rather than a
-- second namespace. That is what makes it structurally incapable of naming an
-- App-relative file: there is nothing to name but the two launchers, so no
-- entry here can ever resolve to a body file, and no body file can be serviced
-- from the package root by mistake.
--
-- Returns the validated list (possibly empty) plus nil, or nil plus a reason.
-- Absent is legal and means this release services no launchers.
function Updater.launchers_section(manifest)
  if type(manifest) ~= "table" then return nil, "manifest is not a table" end
  local list = manifest.launchers
  if list == nil then return {}, nil end
  if type(list) ~= "table" then return nil, "launchers is not a table" end
  local pair_count = 0
  for _ in pairs(list) do pair_count = pair_count + 1 end
  if pair_count ~= #list then return nil, "launchers is not a plain array" end
  local seen = {}
  local out = {}
  for idx, entry in ipairs(list) do
    if type(entry) ~= "table" then
      return nil, string.format("launcher entry %d is not a table", idx)
    end
    if type(entry.name) ~= "string" then
      return nil, string.format("launcher entry %d has no name", idx)
    end
    -- Exact, against the two known paths. Not is_safe_filename, which would
    -- accept any well-formed name and hand the package root a namespace.
    if not Updater.is_launcher_name(entry.name) then
      return nil, "launchers names " .. entry.name
        .. ", which is not one of the two launcher paths"
    end
    -- Case-folded with the exact check, because the destination folds case on
    -- Windows and two entries for one file make the swap ambiguous in exactly
    -- the way journal_valid refuses.
    local key = entry.name:lower()
    if seen[key] then
      return nil, "duplicate launcher name " .. entry.name
    end
    seen[key] = true
    if not Updater.journal_sha_ok(entry.sha256) then
      return nil, "malformed checksum for launcher " .. entry.name
    end
    out[#out + 1] = entry
  end
  return out, nil
end

-- The launchers this body will act on for a given manifest: validated, and
-- filtered to the ones the app is allowed to write.
--
-- Anything but a CONFIRMED unowned launcher is dropped here, before anything
-- hashes it or queues it, so no later stage has to remember the rule. A section
-- that fails validation drops everything, loudly, because a manifest that gets
-- this section wrong is not a manifest to take launcher paths from.
--
-- Confirmed is the operative word since round 25: a foreign owner and a lookup
-- that failed are both dropped here too, and each one says which it was, so a
-- launcher that goes unserviced is never silently unserviced.
function Updater.serviceable_launchers(manifest)
  local list, why = Updater.launchers_section(manifest)
  if not list then
    Log.line("UPDATE", "launchers section refused: " .. tostring(why))
    return {}
  end
  local out = {}
  for _, entry in ipairs(list) do
    local state, detail = Updater.launcher_ownership(entry.name)
    if state == Updater.OWNERSHIP_UNOWNED then
      out[#out + 1] = entry
    else
      Log.line("UPDATE", string.format(
        "launcher servicing: %s is not serviceable by this body (%s: %s)",
        entry.name, state, tostring(detail)))
    end
  end
  return out
end

-- Does this install have the launcher topology at all?
--
-- The two roots are one directory on a pre-restructure install (see
-- RA.package_dir_for), and there the launchers do not exist yet: the file at
-- that path is the body itself. Every launcher-shaped question is answered
-- "not applicable" there rather than guessed, because writing a launcher into
-- a flat root would write it on top of the body.
function Updater.launcher_topology_active()
  return RA.PACKAGE_DIR ~= RA.APP_DIR
end

-- Is this launcher doing its job? Present at the package root, and carrying
-- the marker that makes a file a launcher rather than merely a file with that
-- name (RA.file_holds_launcher). A missing file and a file that is not a
-- launcher are the same failure to a user trying to start ReaAssist from the
-- Action List.
function Updater.launcher_serviceable(name)
  return RA.file_holds_launcher(Updater.launcher_path(name))
end

-- Where one queued download lands. The single place the two roots meet in the
-- apply pipeline: an entry carrying root = "package" is one of the two
-- launchers and resolves at the package root, and everything else is a
-- manifest name under App/. Staging, the swap and the journal stamp all read
-- this, so none of them can disagree about which root an entry belongs to.
function Updater.queue_dest(entry)
  if type(entry) == "table" and entry.root == "package" then
    return Updater.launcher_path(entry.filename)
  end
  return Updater.local_path_for(entry.filename)
end

-- The manifest this install currently claims to be, decoded, or nil.
--
-- Lives here rather than beside local_manifest_intact because of its one
-- caller: startup journal recovery, which finishes the gate's authorized repair
-- long before an update session or a fetched manifest exists, and which needs
-- to know whether this release carries a replacement for a launcher that is not
-- there (Codex round 25, B2.3 blocker 2). local_manifest_intact answers whether
-- the file is usable and nothing about what is in it, and the caller needs what
-- is in it.
--
-- Nothing is validated beyond decoding, deliberately: the one consumer feeds it
-- to launcher_gate_state, whose launchers_section validates the only part of it
-- that is read, and every failure here means the same thing as a missing
-- manifest -- no known replacement -- which is the advisory answer rather than
-- the blocking one. Wrapped end to end so a startup path can never be taken
-- down by a half-written file.
function Updater.local_manifest_read()
  local name = tostring((CFG and CFG.UPDATE_MANIFEST) or "")
  if name == "" then return nil end
  if type(JSON) ~= "table" or type(JSON.decode) ~= "function" then return nil end
  local ok, data = pcall(function()
    local f = io.open(Updater.local_path_for(name), "rb")
    if not f then return nil end
    local raw = f:read("*a")
    f:close()
    if not raw or #raw < 2 then return nil end
    local decoded = JSON.decode(raw)
    if type(decoded) ~= "table" then return nil end
    return decoded
  end)
  if not ok then return nil end
  return data
end
-- close launcher ownership scope

-- Paths the orphan-cleanup pass must never delete, even if a manifest
-- listed them in removed_files. System_Prompt_Custom.md is the documented
-- power-user override -- the loader prefers it over the stock prompt and
-- it's intentionally untracked so updates don't touch it. The legacy
-- Resources/ entries protect users during the migration window.
--
-- The Data/ entries are the reframe this table needed after the restructure
-- (B2.3, plan section 3b). They were written when the app root and the package
-- root were one directory and `Data/Config.json` in removed_files really did
-- name the user's config. They cannot now: every name here is resolved by
-- Updater.local_path_for, which joins under App/, and Data/ is a sibling of
-- App/ at the package root. `Data/Config.json` would name App/Data/Config.json,
-- which nothing creates and nothing reads.
--
-- They are KEPT rather than deleted, and the reason is the layout this body
-- still has to run in. RA.package_dir_for resolves FLAT whenever no
-- marker-verified launcher sits above the body -- a pre-restructure install
-- mid-migration, a hand-copied tree, the regression workspace -- and there the
-- two roots are the same directory and these names reach the real files again.
-- The migration window is exactly when a manifest carrying a stale
-- removed_files entry can meet a flat install, so the cost of keeping them is
-- five table entries and the cost of dropping them is a user's config.
local PROTECTED_FROM_REMOVAL = {
  ["Resources/System_Prompt_Custom.md"] = true,
  ["Resources/Debug.log"]                = true,
  ["Resources/FX_Cache.json"]            = true,
  -- Historical on a two-level install (structurally unreachable, see above),
  -- live on a flat one.
  ["Data/Config.json"]                   = true,
  ["Data/Providers.json"]                = true,
  ["Data/State.json"]                    = true,
  ["Data/Debug.log"]                     = true,
  ["Data/FX_Cache.json"]                 = true,
}

local REMOVABLE_TOP_LEVEL_COMPANIONS = {
  ["ReaAssist - Screen Reader Mode.lua"] = true,
  ["ReaAssist_ScreenReaderMode.lua"]     = true,
}

-- Predicate gating per-path orphan deletes. All four checks must hold:
--   1. is_safe_filename: path-traversal, absolute paths, backslashes,
--      hidden segments, and non-allowlisted extensions all rejected here.
--   2. Inside ReaAssist's install zone: ReaAssist.lua, known retired
--      top-level companion scripts, the three top-level docs, or anything
--      under Resources/. Anything else is out of scope for the package and
--      never something we shipped.
--   3. Not in PROTECTED_FROM_REMOVAL: user-override + runtime artifacts.
--   4. Not also in the current manifest's files list: defensive double-
--      lock against an inconsistent manifest where a path appears in both
--      `files` and `removed_files`. gen_manifest.py guards against this
--      at authoring time; this is belt-and-suspenders.
--
-- The two launchers are NOT in this zone, and nothing here had to be added to
-- keep them out (B2.3, plan section 3b: protection by namespace separation,
-- superseding the earlier "PROTECTED_FROM_REMOVAL gains both launchers"
-- line). Every name this predicate approves is handed to
-- Updater.local_path_for by the caller, which joins it under App/, and the
-- launchers are at the package root above it. So `ReaAssist.lua` in
-- removed_files means the BODY -- and check 4 refuses it, because the body is
-- in every manifest's files list -- and `ReaAssist_Screen_Reader_Mode.lua`
-- means the App-relative Screen Reader body, which is likewise always listed.
-- Neither spelling can reach a launcher, whatever a manifest says, because
-- there is no name in this namespace that resolves to the package root. The
-- launchers section is the only thing that names those two paths, it is an
-- allowlist of two, and it never removes anything.
function Updater.should_remove_orphan(name, current_files)
  if type(name) ~= "string" then return false end
  if not Updater.is_safe_filename(name) then return false end
  -- Preserve historical bundled files that an older installer may still own.
  -- The compact download cache lives under the shared Data/mbriggs_helper tree.
  if name:lower():sub(1, 17) == "resources/engine/" then return false end
  if current_files and current_files[name] then return false end
  local owned =
       name == "ReaAssist.lua"
    or REMOVABLE_TOP_LEVEL_COMPANIONS[name] == true
    or name == "CHANGELOG.md"
    or name == "LICENSE.txt"
    or name == "README.md"
    or name:sub(1, 10) == "Resources/"
  if not owned then return false end
  if PROTECTED_FROM_REMOVAL[name] then return false end
  return true
end

function Updater.download_start()
  -- Accept both triggers: "available" (new version on server) and
  -- "repair_available" (version matches but some files are missing or
  -- corrupted locally). The download pipeline and SHA-diff logic are
  -- identical for both; only the popup messaging differs.
  if (update.state ~= "available" and update.state ~= "repair_available")
      or not update.manifest then return end
  -- NOT WHILE THIS WINDOW IS REMOVING THE INSTALL (work package B2.4). The
  -- apply lock already stops another instance's download, because an uninstall
  -- holds it for its whole run. It cannot stop THIS one: acquire_apply_lock
  -- adopts a lock already carrying this instance's name, by design, so an
  -- update started here during an uninstall would pass the lock and write into
  -- a tree being taken apart. Asked defensively so a body sliced without the
  -- uninstaller behaves exactly as it did before.
  if Updater.uninstall_barrier and Updater.uninstall_barrier() then
    Log.line("UPDATE", "download_start: refused; this window is removing "
      .. "ReaAssist from this install.")
    return
  end
  if Updater.font_download_busy() then
    if UI and UI.show_float_toast then
      UI.show_float_toast(RA.t("settings.font.finish_download_first", nil,
        "Finish the font download first"), "err")
    end
    return
  end
  if Updater.language_download_busy() then
    if UI and UI.show_float_toast then
      UI.show_float_toast(RA.t("settings.lang.finish_download_first", nil,
        "Finish the language pack download first"), "err")
    end
    return
  end
  -- Exclusive apply lock, taken BEFORE any staging mutation: a second
  -- instance sharing this install fails here instead of clobbering the
  -- first one's staging files or journal.
  if not Updater.acquire_apply_lock() then
    -- TWO REFUSALS, AND ONLY ONE OF THEM ENDS BY WAITING (Codex round 42,
    -- B2.3s). A lock held by an instance this launch can SEE is the ordinary
    -- one, and waiting is the whole fix. A lock whose owner cannot be proven
    -- alive or dead is not: since the reclaim rule became "never depose a
    -- living process", such a lock stands until somebody who can see the
    -- machine decides, and telling that user to wait would have them waiting
    -- for a process that may not exist. So it names the claim and the instance
    -- on it, and asks for the clear only they can authorize, which is the same
    -- offer the startup surface makes for the same state.
    if Updater._apply_lock_undecidable ~= nil then
      -- AND WHEN THE PROBE COULD NOT SEE INTO THE FOLDER AT ALL (Codex round
      -- 44, B2.3u), there is no claim to name and no removal to ask for: what
      -- is true is that the folder cannot be opened, and that is what is said.
      if Updater._apply_lock_undecidable_kind == "blocked" then
        Updater._set_failure("apply_lock_undecidable",
          "ReaAssist cannot look inside the folder where it keeps the claim "
          .. "that says an update is in progress, so it cannot tell whether "
          .. "another copy of ReaAssist is applying one on this install. It "
          .. "has not started one and nothing was changed.\n\n"
          .. "The folder is here:\n"
          .. tostring(Updater._apply_lock_undecidable_path
            or "(the ReaAssist log names it)") .. "\n\n"
          .. "Every name in that folder answers the same way whether something "
          .. "is there or not. Give your account permission to open it, then "
          .. "try again.")
        update.state = "failed"
        return
      end
      -- Both lines come from the acquisition, which is the only thing that
      -- looked at the name. The claim is the artifact the protocol actually
      -- built (a file on Windows, a folder on POSIX) rather than the base name,
      -- because this copy asks the user to remove it by hand and has to name
      -- what they will see (Codex round 43, B2.3t).
      Updater._set_failure("apply_lock_undecidable",
        "ReaAssist cannot tell whether another copy of ReaAssist is still "
        .. "applying an update on this install, so it has not started one and "
        .. "nothing was changed.\n\n"
        .. "The claim is here:\n"
        .. tostring(Updater._apply_lock_undecidable_path
          or "(the ReaAssist log names it)") .. "\n\n"
        .. "It was recorded by:\n"
        .. tostring(Updater._apply_lock_undecidable ~= ""
          and Updater._apply_lock_undecidable
          or "a copy of ReaAssist whose name could not be read") .. "\n\n"
        .. "Close any other REAPER window that is running ReaAssist and try "
        .. "again. If you are sure no other copy of ReaAssist is running on "
        .. "this computer, delete the "
        .. (Updater._apply_lock_undecidable_kind == "folder" and "folder"
          or "file")
        .. " named above and try again.")
      update.state = "failed"
      return
    end
    Updater._set_failure("apply_lock",
      "Another ReaAssist instance is applying an update on this "
      .. "install. Let it finish, then retry.")
    update.state = "failed"
    return
  end
  -- Re-ask ReaPack immediately before the queue is built. The check that
  -- produced these lists may have run minutes ago and a launcher this app is
  -- forbidden to write is the one thing that must not end up in the queue.
  Updater.launcher_owner_refresh()
  -- Remember which trigger started the session so the "done" view can
  -- say "Updated to vX" vs "Restored N files" accurately.
  update.action_was_repair = (update.state == "repair_available")
  update.download_queue = {}
  -- Whatever the LAST transaction's ownership fence declined belongs to that
  -- transaction. A failed apply never reaches _apply_finish, so without this
  -- the next attempt would report a skip it did not make, and report it twice
  -- if it made the same one again.
  update._launcher_skipped = nil
  update.applied_files = {}  -- track successfully written files for rollback
  update.skipped_count  = 0  -- files whose local SHA already matches manifest
  -- When entering from repair_available OR an update prompt produced by
  -- the check-time SHA diff, we already know which files are missing or
  -- mismatched. Reuse those lists instead of re-hashing the entire
  -- manifest synchronously after the user clicks the button. Trade-off:
  -- corruption introduced in the few seconds between the diff completing
  -- and the click would not be caught here, but the next launch's SHA
  -- check would catch it.
  local repair_fileset = nil
  if update.action_was_repair
      and update.repair_missing
      and update.repair_mismatched then
    repair_fileset = {}
    for _, n in ipairs(update.repair_missing)    do repair_fileset[n] = true end
    for _, n in ipairs(update.repair_mismatched) do repair_fileset[n] = true end
  end
  local update_fileset = nil
  if not update.action_was_repair
      and update.update_missing
      and update.update_mismatched then
    update_fileset = {}
    for _, n in ipairs(update.update_missing)    do update_fileset[n] = true end
    for _, n in ipairs(update.update_mismatched) do update_fileset[n] = true end
    -- Locked files join the update queue: their content could not be
    -- verified at check time, so treating them as intact would let a
    -- version bump ship with silently stale code in whichever file the
    -- AV scanner happened to be holding. The apply stage re-downloads
    -- and swaps them like any changed file; its rename retry absorbs a
    -- transient lock and a persistent lock fails loudly.
    for _, n in ipairs(update.update_locked or {}) do
      update_fileset[n] = true
    end
  end
  -- Payload URLs use the tag-pinned base when the release gates allow it
  -- (see payload_base_url). This applies to update, repair, and
  -- bootstrap-forced queues alike; the manifest fetch that produced
  -- update.manifest stays on the configured main base regardless.
  local payload_base = Updater.payload_base_url(update.manifest.version)
  for _, entry in ipairs(update.manifest.files) do
    local filename, expected_hash
    if type(entry) == "table" and entry.name and entry.sha256 then
      filename      = entry.name
      expected_hash = entry.sha256
    else
      -- Reject manifests without per-file SHA-256 hashes. All production
      -- manifests must use the {name, sha256} format for integrity
      -- verification. Route through _set_failure so the Update Failed
      -- dialog has a real reason to display instead of the generic
      -- "(unknown)" the empty fields would produce.
      Updater._set_failure("manifest_file",
        "Manifest entry missing required SHA-256 hash")
      Updater.release_apply_lock()
      update.state = "failed"
      return
    end
    if not Updater.is_safe_filename(filename) then
      Updater._set_failure("manifest_file",
        "Unsafe filename in manifest: " .. tostring(filename))
      Updater.release_apply_lock()
      update.state = "failed"
      return
    end
    if repair_fileset then
      -- Repair path: queue only files the SHA diff flagged. Everything else
      -- already matched per the diff and is safe to skip without re-hashing.
      if repair_fileset[filename] then
        update.download_queue[#update.download_queue+1] = {
          filename = filename,
          url      = Updater.url_for(filename, payload_base),
          sha256   = expected_hash,
          inline_bytes = entry.inline_bytes,
        }
      else
        update.skipped_count = update.skipped_count + 1
      end
    elseif update_fileset then
      -- Version-bump path after check-time SHA diff: queue only files
      -- already proven different so the Update Now click can jump
      -- straight into the download UI instead of synchronously hashing
      -- every manifest entry.
      if update_fileset[filename] then
        update.download_queue[#update.download_queue+1] = {
          filename = filename,
          url      = Updater.url_for(filename, payload_base),
          sha256   = expected_hash,
          inline_bytes = entry.inline_bytes,
        }
      else
        update.skipped_count = update.skipped_count + 1
      end
    else
      -- Legacy/impossible state: modern check paths compute repair_fileset or
      -- update_fileset before the button is shown. If a stale state reaches
      -- here without that diff, do not synchronously hash the whole manifest on
      -- the UI thread; queue the file and rely on post-download SHA verify.
      update.download_queue[#update.download_queue+1] = {
        filename = filename,
        url      = Updater.url_for(filename, payload_base),
        sha256   = expected_hash,
        inline_bytes = entry.inline_bytes,
      }
    end
  end
  -- The launchers, queued from their own section and against the package base
  -- (section 3b). Three gates in front of every one of them, and all three
  -- have to hold: the install has the topology, the section named this exact
  -- path, and ReaPack does not own it. serviceable_launchers enforces the last
  -- two; a ReaPack-owned launcher never reaches this loop even when the
  -- section lists it, which is the invariant the whole mechanism exists for.
  --
  -- Keyed lookup, so an entry in the filesets for the launcher never matches
  -- the body of the same name and vice versa. A queue with no fileset in front
  -- of it (the legacy fall-through above) does NOT sweep the launchers in:
  -- that path exists for a stale state that predates the diff, and a launcher
  -- written on the strength of a state nobody computed is exactly the write
  -- this section is careful about.
  if Updater.launcher_topology_active() then
    local package_base = Updater.package_base_url(payload_base)
    local launchers = Updater.serviceable_launchers(update.manifest)
    if #launchers > 0 and not package_base then
      Log.line("UPDATE", string.format(
        "download_start: %d launcher(s) listed but the payload base %q is not "
        .. "the App view, so no package-root URL can be derived; skipping "
        .. "launcher servicing this run.", #launchers, tostring(payload_base)))
      launchers = {}
    end
    for _, entry in ipairs(launchers) do
      local key = Updater.launcher_key(entry.name)
      local wanted = (repair_fileset and repair_fileset[key])
        or (update_fileset and update_fileset[key])
      if wanted then
        update.download_queue[#update.download_queue+1] = {
          filename = entry.name,
          root     = "package",
          url      = Updater.url_for(entry.name, package_base),
          sha256   = entry.sha256,
        }
      elseif repair_fileset or update_fileset then
        update.skipped_count = update.skipped_count + 1
      end
    end
  end
  -- If every file already matches (user manually swapped files, or re-invoked
  -- an update that already ran), close the popup and stay idle -- the
  -- manifest version stamp is handled by the next startup check. Surface a
  -- short toast so the click on "Update Now" doesn't silently appear to do
  -- nothing; without it the popup just disappears and the user has no
  -- confirmation that the action completed.
  if #update.download_queue == 0 then
    Log.line("UPDATE", string.format(
      "download_start: all %d manifest files already match local SHA; "
      .. "nothing to download.", update.skipped_count))
    Updater.release_apply_lock()
    update.show_dialog = false
    update.state       = "idle"
    if UI and UI.show_float_toast then
      UI.show_float_toast(RA.t("update.toast.up_to_date", nil,
        "Already up to date"), "ok")
    end
    return
  end
  Log.line("UPDATE", string.format(
    "download_start: %d files to download, %d already up to date.",
    #update.download_queue, update.skipped_count))
  -- Stage A of the transactional apply: every file downloads to a staged
  -- sibling of its destination first; no live file is touched until the
  -- whole staging set has been verified (stage B) and journaled (stage
  -- C). Pre-create parent directories (fresh installs need the
  -- Resources/ tree before curl can write into it) and clear any stale
  -- staging leftovers from an interrupted prior batch.
  --
  -- THE SIBLING NAME CARRIES THIS ACQUISITION (Codex round 42, B2.3s blocker
  -- 2). The lock was taken above, so there is an acquisition to name, and every
  -- path built here belongs to it alone: the detached curl below can only be
  -- pointed at these, the verify only reads these, the cleanup only removes
  -- these, and a second instance staging the same manifest file at the same
  -- instant is writing a different file. The removal on the last line is
  -- therefore ours by construction rather than by hope.
  update._staging_tag = Updater.staging_tag()
  for _, entry in ipairs(update.download_queue) do
    local dest = Updater.queue_dest(entry)
    entry.staged = Updater.staging_path(dest, update._staging_tag)
    local parent = dest:match("^(.*)[\\/][^\\/]+$")
    if parent and parent ~= "" then
      reaper.RecursiveCreateDirectory(parent, 0)
    end
    os.remove(entry.staged)
  end
  update.download_idx = 1
  update._staged_done = 0
  update._batch = {
    started_at  = time_precise(),
    refire_used = false,
    watchdog    = CFG.UPDATE_BATCH_WATCHDOG_BASE
                + CFG.UPDATE_BATCH_WATCHDOG_PER_FILE * #update.download_queue,
  }
  local remote_queue, inline_err =
    Updater.stage_inline_entries(update.download_queue)
  if not remote_queue then
    update._batch = nil
    Updater._download_verify_fail("download_stage", inline_err)
    return
  end
  if #remote_queue == 0 then
    Updater.download_verify_start()
    return
  end
  if not Updater.fire_batch_download(remote_queue) then
    update._batch = nil
    Updater._delete_all_staged()
    Updater._set_failure("download_start",
      "Could not start the update download.")
    Updater.release_apply_lock()
    update.state = "failed"
    return
  end
  update.state = "downloading_batch"
end

function Updater.settle_silent_manifest_failure()
  if update.silent_manifest_repair ~= true or update.state ~= "failed" then
    return false
  end
  Log.line("UPDATE", string.format(
    "silent manifest transition repair deferred after failure [%s]: %s",
    tostring(update.last_step), tostring(update.last_error)))
  Updater.release_apply_lock()
  update.state = "idle"
  update.last_step = nil
  update.last_error = nil
  update.show_dialog = false
  update.popup_opened = false
  update.force = false
  update.applied = false
  update.restart_after = nil
  update.restart_fired = nil
  update.action_was_repair = nil
  update.repair_missing = nil
  update.repair_mismatched = nil
  update.silent_manifest_repair = false
  update._silent_manifest_manual = false
  update._batch = nil
  update._dl_verify = nil
  update._apply = nil
  update.download_queue = {}
  update.applied_files = {}
  return true
end

function Updater.try_silent_manifest_repair()
  if update.silent_manifest_repair ~= true
      or update.state ~= "repair_available" then
    return false
  end
  if Updater.font_download_busy() or Updater.language_download_busy() then
    return false
  end
  Updater.download_start()
  if Updater.settle_silent_manifest_failure() then return false end
  return update.state ~= "repair_available"
end

-- Rollback all successfully written files. For files that existed before
-- the update (bak_existed=true), restore the .bak. For fresh-install adds
-- (bak_existed=false), just delete the dest -- there is no prior version
-- to restore, and renaming a nonexistent .bak over dest silently deletes
-- it, leaving the user with neither a working file nor a recoverable
-- backup if the next update file fails.
--
-- When a journal is active (rollback mid-apply), the journal's phase is
-- flipped to "rolling_back" and written BEFORE the first disk mutation:
-- startup recovery completes a "rolling_back" journal in the rollback
-- direction unconditionally, so a crash at ANY point during this
-- function can never be misread as an interrupted apply and rolled
-- forward over half-restored files. Each entry likewise flips to
-- rolled_back before its dest is touched (the phase marker already
-- forces the direction; per-entry status is informational). The journal
-- is deleted at the end once the in-memory state has fully resolved.
--
-- Returns true when the rollback ran (marked and mutated, or nothing to
-- do) and false when it bailed: on the marker write, or mid-walk when a
-- launcher's supersession could not be recorded (Codex round 27). Callers
-- MUST skip their staged-file cleanup on false: the untouched staging is
-- part of the recovery state the bail preserves (deleting it would let the
-- next launch's dest-hash reclassification misread an unchanged-content
-- pending file as a landed fresh add and delete it). Both bails leave the
-- journal on disk for startup recovery to finish.
function Updater.rollback()
  if not update.applied_files then return true end
  local journal = update._journal
  if journal then
    -- Ownership fence, same rule as apply_tick's per-swap fence: if
    -- the on-disk journal is no longer ours, another instance took
    -- over after our liveness lease expired, and its state is
    -- authoritative. Mutate nothing and bail exactly like the
    -- marker-failure path (callers skip their staged cleanup on
    -- false). The fence-then-write pair here (this read, then the
    -- rolling_back marker write) is the same revalidation boundary as
    -- the apply side's.
    --
    -- Invalid and absent both land here as nil, and that is right for a fence
    -- (Codex round 22, B2.2g blocker 2): this asks "is the journal on disk
    -- still ours", both answers are no, and the response to no is to mutate
    -- nothing and bail. A fence is fail-closed on either, so the two do not
    -- need separating; the caller that DID need it is apply_start, which
    -- writes rather than bails.
    -- The lock is asked as well as the record (Codex round 41, B2.3r). A
    -- reclaimed lock is the EARLIER event: the record at the journal path is
    -- still this instance's until the winner writes over it, so a rollback that
    -- only read the record would mutate for as long as the winner took to get
    -- there. Both questions, one bail, and it is the bail this path already had.
    local current = Updater.journal_read()
    if not Updater.journal_writers_excluded() or not current
        or current.instance ~= RA.instance_file_suffix() then
      Log.line("UPDATE",
        "rollback: another ReaAssist instance took over this update; "
        .. "leaving all files untouched.")
      update.last_error = (update.last_error or "The update failed.")
        .. "\n\nNote: another ReaAssist instance took over this "
        .. "update; no further files were changed by this one."
      update._journal = nil
      update.applied_files = {}
      return false
    end
    journal.phase = "rolling_back"
    if not Updater.journal_write(journal) then
      -- No durable direction marker means NO disk mutation at all:
      -- rolling back without it lets a later launch misread the
      -- half-restored state (an unchanged-content file with a consumed
      -- .bak reads as a landed-before-journal fresh add and would be
      -- deleted). Leave the applied files, their .baks, the staging,
      -- and the phase-"applying" journal exactly as they are; startup
      -- recovery owns the rollback from here, and its own marker-write
      -- failure defers the launch rather than mutating. A Retry click
      -- is safe because apply_start will not start over a record that
      -- changed something, and the applied files with their .baks beside
      -- them are exactly that (Codex round 28, B2.3e). This used to rest
      -- on apply_start's own journal write failing in the same disk-full
      -- situation, which was true of this bail and of no other.
      Log.line("UPDATE",
        "rollback: could not write the rolling_back marker; leaving all "
        .. "files and the journal untouched (startup recovery completes "
        .. "the rollback on the next launch).")
      update.last_error = (update.last_error or "The update failed.")
        .. "\n\nNote: the rollback could not be recorded safely, so the "
        .. "changed files were left in place. ReaAssist will finish "
        .. "recovering them automatically the next time it starts."
      update._journal = nil
      update.applied_files = {}
      return false
    end
  end
  -- Track restore failures so we can surface them via update.last_error.
  -- Rollback runs because some EARLIER step already failed, so last_step
  -- and last_error are typically already set at this point. We only
  -- overwrite them if a restore failure produces a worse situation than
  -- the original failure (i.e. a file the user had before the update is
  -- now gone with no .bak to recover from), which is the one rollback
  -- failure mode that genuinely requires manual attention.
  local restore_failures = {}
  local superseded = {}
  local deferred = {}
  for i = #update.applied_files, 1, -1 do
    -- And before every entry, not only at the top of the walk (Codex round 41,
    -- B2.3r). This loop restores files and drops backups one entry at a time,
    -- and a lock reclaimed halfway through it must stop the rest: what has been
    -- put back stays put back, the record on disk still describes the rest, and
    -- startup recovery finishes the same rollback from the same marker.
    if not Updater.journal_writers_excluded() then
      Log.line("UPDATE",
        "rollback: this instance no longer holds the exclusive apply lock, so "
        .. "it stopped where it stood; nothing further was restored, dropped "
        .. "or recorded.")
      update.last_error = (update.last_error or "The update failed.")
        .. "\n\nNote: another ReaAssist instance took over this "
        .. "update; no further files were changed by this one."
      update._journal = nil
      update.applied_files = {}
      return false
    end
    local applied = update.applied_files[i]
    local dest = applied.path
    -- THE OWNERSHIP FENCE, IN THIS DIRECTION TOO (Codex round 26, blocker 1B).
    --
    -- An earlier revision fenced only the forward swap, on the reasoning that
    -- restoring a .bak puts back the bytes that were there rather than writing
    -- ours. That reasoning was rejected and it was wrong, because it looked at
    -- the source of the bytes instead of at the file being written. A ReaPack
    -- synchronization landing AFTER this transaction took its backup makes the
    -- file at the package root ReaPack's current launcher; the restore deletes
    -- that file and puts an older one in its place. The fresh-add branch below
    -- is worse still: it deletes ReaPack's launcher outright.
    --
    -- So every package-root write here asks the same uncached question the
    -- forward direction asks, immediately before it acts, and a launcher that
    -- is no longer confirmed unowned is LEFT EXACTLY AS IT IS. The rest of the
    -- rollback proceeds; a body update is not held hostage by a launcher that
    -- stopped being this body's.
    --
    -- What is dropped is our own backup, which is neither the launcher nor a
    -- file anyone else owns: it is the copy this transaction moved aside
    -- minutes ago and can no longer put anywhere. Leaving it would strand a
    -- stray .bak at the package root and would leave a later recovery walk
    -- reading "restore not yet performed" about a restore that must never
    -- happen.
    --
    -- DROPPING IT NEEDS TWO THINGS, AND ONLY TWO (Codex round 27).
    --
    -- The first is a CONFIRMED answer. Owned and foreign are findings: another
    -- package holds this file, so the copy at the package root is that
    -- package's and the backup beside it is superseded. UNKNOWN is not a
    -- finding at all -- the API raised, or declined, or was not there to ask --
    -- and treating it as supersession abandons the user's only copy of the
    -- previous launcher over an extension hiccup. So unknown DEFERS: the entry
    -- stays applied, the .bak stays, the journal stays, this walk leaves that
    -- one file alone and the journal is kept, and the next launch asks again
    -- with an API that may well answer. Nothing is lost by waiting.
    --
    -- The second is a DURABLE record of the supersession. The skip write used
    -- to be fired and forgotten, and the chain a lost one opens ends with the
    -- launcher deleted: a locked primary fails the write while the completed
    -- .tmp holds the true state, the cleanup at the end of this walk deletes
    -- that .tmp and cannot delete the locked primary, and the stale primary
    -- that survives still says "applied" with no .bak -- so the next launch's
    -- rollback completion hands a fresh-add launcher to a fence that may by
    -- then answer unowned, and deletes it. So the write is judged, and on false
    -- NOTHING is cleaned: the .bak stays, the journal stays as it was found,
    -- and this walk stops where it stands rather than continuing to mutate
    -- files whose statuses it cannot record. The next launch re-runs the
    -- rollback from the journal, re-asks the fence and re-attempts the write.
    local left_alone = false
    if applied.root == "package" and applied.name then
      local writable, state, detail = Updater.launcher_writable_now(applied.name)
      if not writable then
        left_alone = true
        if state ~= Updater.OWNERSHIP_OWNED
            and state ~= Updater.OWNERSHIP_FOREIGN then
          -- Not an answer. Preserve everything and come back to it.
          deferred[#deferred + 1] = {
            name = applied.name,
            reason = Updater.launcher_left_alone_reason("deferred", state),
            detail = detail,
          }
          Log.line("UPDATE", string.format(
            "rollback: could not find out who owns %s (%s: %s), so the entry, "
            .. "its backup and the journal were all left exactly as they are; "
            .. "the rest of the rollback continues and the next launch asks "
            .. "again.", applied.name, tostring(state), tostring(detail)))
        else
          local reason = Updater.launcher_left_alone_reason("superseded", state)
          local entry
          for _, jf in ipairs(journal and journal.files or {}) do
            if jf.root == "package" and jf.name == applied.name
                and jf.status == "applied" then
              entry = jf
              break
            end
          end
          if entry then
            entry.status      = "skipped"
            entry.skip_reason = reason
            entry.skip_detail = detail and tostring(detail):sub(1, 200) or nil
            if not Updater.journal_write(journal) then
              -- Put the in-memory entry back the way it was found, so the one
              -- account of this transaction that still exists anywhere says
              -- what is actually on disk.
              entry.status = "applied"
              entry.skip_reason, entry.skip_detail = nil, nil
              Log.line("UPDATE", string.format(
                "rollback: %s is no longer this body's to put back, but that "
                .. "could not be recorded; leaving its backup, the journal and "
                .. "every remaining file exactly as they are (startup recovery "
                .. "re-asks and finishes this on the next launch).",
                applied.name))
              update.last_error = (update.last_error or "The update failed.")
                .. "\n\nNote: ReaAssist could not record what it did with one "
                .. "of the actions that start it, so it changed nothing "
                .. "further and left the update recovery state in place. "
                .. "ReaAssist will finish recovering automatically the next "
                .. "time it starts."
              update._journal = nil
              update.applied_files = {}
              return false
            end
          end
          -- Only now, with the supersession on disk (or with no journal to put
          -- it in, which means no later walk exists to misread the backup).
          os.remove(dest .. ".bak")
          superseded[#superseded + 1] =
            { name = applied.name, reason = reason, detail = detail }
          Log.line("UPDATE", string.format(
            "rollback: %s is no longer confirmed unowned (%s: %s), so it was "
            .. "left as it stands and its backup was dropped; the rest of the "
            .. "rollback continues.", applied.name, tostring(state),
            tostring(detail)))
        end
      end
    end
    -- AND THEN THE FILE ITSELF, BEFORE ANYTHING IS REMOVED (Codex round 34,
    -- B2.3k blocker 1). The ownership fence above asks who owns this name; this
    -- asks whether the bytes at it are still the ones this transaction wrote
    -- minutes ago. They are two different questions and both have to answer
    -- before a removal, because the fence is silent about every destination
    -- that is not a launcher and says nothing at all about content.
    --
    -- The order is fixed by what each one licenses. Ownership first, always: a
    -- launcher ReaPack has synchronized over is NOT a stranger, it is a file
    -- with an owner, and the supersede path above has already left it alone and
    -- dropped the backup by the time this runs. So everything reaching here is
    -- either an ordinary body file or a launcher confirmed to be nobody's, and
    -- a mismatch on one of those is somebody else's file at our destination.
    --
    -- A STRANGER STOPS THE WALK WHERE IT STANDS, which is the shape this
    -- function already uses for a supersession it could not record: nothing
    -- further is mutated, the journal is kept exactly as it is (phase
    -- rolling_back, so the next launch resumes in this direction), every .bak
    -- and every staged copy stays, and false is the return that tells callers
    -- to leave the staging alone too. Not a pre-pass, deliberately: a record
    -- being rolled back has already changed something by definition, so there
    -- is no start-over lane here to protect the way there is in the walk that
    -- rolls an interrupted apply forward.
    --
    -- UNVERIFIABLE HOLDS ONE ENTRY AND ONLY ONE. A destination that cannot be
    -- read is what a lock looks like, and the established answer to a lock is
    -- to leave that entry alone, count it, keep the journal and retry on the
    -- next launch. Its status is not flipped and its .bak is not touched, which
    -- is the applied-with-backup pair the completion walk reads as "restore not
    -- yet performed", so nothing has to be recorded for the retry to find it.
    local hold = false
    if not left_alone then
      local verdict = Updater.applied_dest_verdict(dest, applied.sha256)
      if verdict == Updater.DEST_STRANGER then
        Log.line("UPDATE", string.format(
          "rollback: %s is not the file this update put there, so nothing was "
          .. "undone and nothing was cleaned up; the journal, every backup and "
          .. "all staging are exactly as they were.", dest))
        update.last_error = (update.last_error or "The update failed.")
          .. "\n\nNote: a file ReaAssist did not put there is sitting where "
          .. "ReaAssist had already written one of its own:\n" .. dest
          .. "\n\nThat file was not moved, renamed or deleted, and this "
          .. "update's record, its backups and its downloaded files were kept. "
          .. "Move that file somewhere else, then close ReaAssist and open it "
          .. "again to finish recovering."
        update._journal = nil
        update.applied_files = {}
        return false
      elseif verdict ~= Updater.DEST_OURS
          and verdict ~= Updater.DEST_ABSENT then
        hold = true
        restore_failures[#restore_failures + 1] = dest
        Log.line("UPDATE", string.format(
          "rollback: could not read %s to check that it is still the file "
          .. "this update put there (locked?), so the entry, its backup and "
          .. "its status were all left exactly as they are; the journal is "
          .. "kept and the next launch tries again.", dest))
      end
    end
    if not left_alone and not hold then
      if journal then
        for _, jf in ipairs(journal.files or {}) do
          if jf.status == "applied"
              and Updater.journal_entry_path(journal, jf) == dest then
            jf.status = "rolled_back"
            break
          end
        end
        -- Follows the entry fence above within the same call; a takeover
        -- landing between the fence and this write is bounded by one
        -- restore, tolerated by the winner's completion walk.
        Updater.journal_write(journal)
      end
      local removed_ok = os.remove(dest)
      if applied.bak_existed then
        local bak_path = dest .. ".bak"
        local ok, err = os.rename(bak_path, dest)
        if not ok then
          Log.line("UPDATE", string.format(
            "rollback restore failed for %s: %s "
            .. "(.bak still on disk; manual recovery may be needed)",
            dest, tostring(err)))
          restore_failures[#restore_failures + 1] = dest
        end
      elseif not removed_ok
          and reaper.file_exists and reaper.file_exists(dest) then
        -- Fresh-install add whose delete failed on a still-present file:
        -- a lock. Counted so the journal is retained for the next-launch
        -- retry below.
        Log.line("UPDATE", string.format(
          "rollback: could not remove fresh-install add %s (locked)",
          dest))
        restore_failures[#restore_failures + 1] = dest
      end
    end
  end
  if journal then
    if #restore_failures == 0 and #deferred == 0 then
      Updater.journal_delete()
    else
      -- Keep the journal (phase rolling_back) so the next launch's
      -- idempotent completion retries the failed restores once the
      -- transient lock clears -- and, since round 27, re-asks the ownership
      -- question for every launcher this walk could not get an answer about.
      -- A deferred entry is still "applied" with its .bak beside it, which is
      -- exactly the shape that completion reads as "restore not yet
      -- performed", so the retry needs nothing recorded to find it.
      --
      -- And nothing in this session can take it away again: the failure this
      -- rollback ends in offers a Retry, Retry is force_reinstall, and
      -- apply_start refuses to start over a record that changed something
      -- however recently this instance wrote it (Codex round 28, B2.3e).
      Log.line("UPDATE", string.format(
        "rollback: %d restore failure(s) and %d launcher(s) deferred for want "
        .. "of an ownership answer; journal kept so startup recovery retries "
        .. "on the next launch.", #restore_failures, #deferred))
    end
    update._journal = nil
  end
  update.applied_files = {}
  -- The user is told about a launcher this rollback left alone, and it goes on
  -- update.last_error rather than on S.launcher_notice, because a rollback ends
  -- in the Update Failed view and that view is what reads last_error. (The
  -- notice field is the SUCCESS surface: setting it here would say nothing now
  -- and then reappear on top of a later successful update in the same session.)
  --
  -- One list rather than two calls, because the message builder groups by
  -- reason and two calls would produce two dialogs' worth of paragraphs about
  -- the same pair of files. A superseded launcher and a deferred one are
  -- different paragraphs within it, in that order.
  if #superseded > 0 or #deferred > 0 then
    local told = {}
    for _, item in ipairs(superseded) do told[#told + 1] = item end
    for _, item in ipairs(deferred) do told[#told + 1] = item end
    Updater.launcher_notice_log(told)
    local message = Updater.launcher_advisory_message(told)
    if message then
      update.last_error = (update.last_error or "The update failed.")
        .. "\n\n" .. message
    end
  end
  if #restore_failures > 0 then
    -- Append a manual-attention note to the existing failure message so
    -- the Update Failed dialog surfaces both the original cause and the
    -- restore problem. Don't replace last_error/last_step -- the original
    -- failure step is the right pointer for the user; the restore note
    -- just adds urgency.
    local note = string.format(
      "\n\nNote: rollback could not restore %d previous file%s "
      .. "(.bak file%s left on disk for manual recovery): %s",
      #restore_failures,
      #restore_failures == 1 and "" or "s",
      #restore_failures == 1 and "" or "s",
      table.concat(restore_failures, ", "))
    update.last_error = (update.last_error or "(no prior error)") .. note
  end
  return true
end

-- Quote a value for a curl --config file. Values are wrapped in double
-- quotes (curl's config parser recognizes \\ and \" escapes inside
-- them). Windows path separators are converted to forward slashes first
-- (curl and the OS both accept them), so no backslash escapes are ever
-- needed in practice; the gsub below is defense-in-depth.
function Updater._curl_cfg_quote(value)
  local v = tostring(value or ""):gsub("\\", "/"):gsub('"', '\\"')
  return '"' .. v .. '"'
end

-- Stage payload bytes captured during the manifest fetch without performing a
-- second network request. Other entries remain in the returned remote queue.
-- This keeps the installed manifest byte-for-byte aligned with the hashes used
-- to select and verify the rest of the transaction.
function Updater.stage_inline_entries(entries)
  local remote = {}
  for _, entry in ipairs(entries or {}) do
    if type(entry.inline_bytes) == "string" then
      local f, open_err = io.open(entry.staged, "wb")
      if not f then
        return nil, "Could not stage fetched " .. tostring(entry.filename)
          .. ": " .. tostring(open_err)
      end
      local ok, write_err = f:write(entry.inline_bytes)
      local close_ok, close_err = f:close()
      if not ok or close_ok == nil then
        os.remove(entry.staged)
        return nil, "Could not stage fetched " .. tostring(entry.filename)
          .. ": " .. tostring(write_err or close_err)
      end
    else
      remote[#remote + 1] = entry
    end
  end
  return remote
end

-- Launch ONE detached curl process that downloads every queued entry to
-- its staged path, driven by a --config file (sidesteps Windows command-
-- length limits and keeps the single-exit-file polling contract: cmd
-- writes one exit code after the whole run). Global flags mirror
-- fire_get_to's payload flags: -f turns HTTP >= 400 into a nonzero exit
-- instead of an error body, and the bounded retry window absorbs
-- transient per-transfer failures. --fail-early is deliberately absent
-- so one failed transfer does not abandon the rest; stage B's hash pass
-- is the per-file authority either way. Returns true if the launch was
-- attempted, false on prerequisite failure.
function Updater.fire_batch_download(entries)
  os.remove(tmp.update_batch_cfg)
  os.remove(tmp.update_batch_exit)
  local cf, cf_err = io.open(tmp.update_batch_cfg, "wb")
  if not cf then
    Log.line("UPDATE", "fire_batch_download: config open failed: "
                       .. tostring(cf_err))
    return false
  end
  cf:write("silent\n")
  cf:write("fail\n")
  cf:write("connect-timeout = 10\n")
  cf:write(string.format("max-time = %d\n", CFG.UPDATE_CURL_TIMEOUT))
  cf:write("retry = 2\n")
  cf:write("retry-max-time = 5\n")
  for _, entry in ipairs(entries) do
    cf:write("url = " .. Updater._curl_cfg_quote(entry.url) .. "\n")
    cf:write("output = " .. Updater._curl_cfg_quote(entry.staged) .. "\n")
  end
  cf:close()

  if RA.IS_WINDOWS then
    -- Same cmd-unsafe character guard as fire_get / fire_native_sha.
    -- Entry URLs and staged paths already passed is_safe_filename and
    -- live inside the install zone; the tmp paths are ours. Belt and
    -- suspenders only.
    for _, c in ipairs({'"', '<', '>', '|'}) do
      if tmp.update_batch_cfg:find(c, 1, true)
          or tmp.update_batch_exit:find(c, 1, true) then
        Log.line("UPDATE", string.format(
          "fire_batch_download: refusing to launch with cmd-unsafe "
          .. "character '%s' in tmp paths", c))
        return false
      end
    end
    -- Detached via the same Start-Process cmd pattern as fire_get, so
    -- the main thread only pays launcher startup, never a visible cmd
    -- window, and batch_download_poll reads the exit file each frame.
    local cmd_line = str_format(
      'curl --config """%s"""'
      .. ' & call echo ^%%errorlevel^%% > """%s"""',
      tmp.update_batch_cfg, tmp.update_batch_exit)
    local ps_cmd = str_format(
      'powershell -NoProfile -WindowStyle Hidden'
      .. ' -Command "Start-Process cmd -ArgumentList \'/c %s\''
      .. ' -WindowStyle Hidden"',
      Shell.ps_escape(cmd_line))
    reaper.ExecProcess(ps_cmd, 5000)
  else
    local cmd = str_format(
      '(curl --config %s ; echo $? > %s) &',
      Shell.sh_quote(tmp.update_batch_cfg),
      Shell.sh_quote(tmp.update_batch_exit))
    os.execute(cmd)
  end
  return true
end

-- Remove every staged .new file for the current queue. Called on any
-- failure before stage C so an aborted transaction leaves no staging
-- litter; live files are never touched by stages A/B.
function Updater._delete_all_staged()
  for _, entry in ipairs(update.download_queue or {}) do
    if entry.staged then os.remove(entry.staged) end
  end
end

-- Shared hard-failure path for stages A/B: staged files are deleted,
-- the failure is stamped for the Update Failed dialog, the apply lock
-- is released, and no live file has been modified (rollback is
-- unnecessary by construction).
function Updater._download_verify_fail(step, err)
  Updater._delete_all_staged()
  update._batch     = nil
  update._dl_verify = nil
  Updater._set_failure(step, err)
  Updater.release_apply_lock()
  update.state = "failed"
end

-- Poll the in-flight batch download (stage A). Progress comes from
-- counting staged files that exist on disk; completion from the single
-- exit file. curl's exit code is logged but not authoritative: without
-- --fail-early a nonzero exit only means at least one transfer failed,
-- and stage B decides per file.
function Updater.batch_download_poll()
  local b = update._batch
  if not b then
    Updater._download_verify_fail("download_batch",
      "batch_download_poll entered with no batch state.")
    return
  end
  local staged_done = 0
  for _, entry in ipairs(update.download_queue) do
    if reaper.file_exists and reaper.file_exists(entry.staged) then
      staged_done = staged_done + 1
    end
  end
  update._staged_done = staged_done
  update.download_idx = staged_done + 1

  local ef = io.open(tmp.update_batch_exit, "r")
  if ef then
    local exit_str = ef:read("*a"); ef:close()
    local exit_code = tonumber(exit_str:match("(%-?%d+)"))
    if exit_code then
      Log.line("UPDATE", string.format(
        "batch download finished (curl exit %d, %d/%d staged files "
        .. "present); verifying staged files.",
        exit_code, staged_done, #update.download_queue))
      Updater.download_verify_start()
      return
    end
  end

  if (time_precise() - b.started_at) > b.watchdog then
    Updater._download_verify_fail("download_batch", string.format(
      "The update download did not finish within %d seconds "
      .. "(%d of %d files arrived). Check your connection and retry.",
      math.floor(b.watchdog), staged_done, #update.download_queue))
  end
end

-- Begin stage B: hash every staged file BEFORE any live file is
-- touched. Prefers the native hasher subprocess (same fire/poll
-- machinery the repair scan uses) with the budgeted chunked pure-Lua
-- walker as fallback. Entries whose staged file is missing go straight
-- onto the failed list for the single re-fire round.
function Updater.download_verify_start()
  update.state = "verifying_download"
  local to_hash = {}
  local failed  = {}
  for _, entry in ipairs(update.download_queue) do
    if reaper.file_exists and reaper.file_exists(entry.staged) then
      to_hash[#to_hash+1] = { path = entry.staged, entry = entry }
    else
      failed[#failed+1] = entry
    end
  end
  update._dl_verify = {
    to_hash    = to_hash,
    failed     = failed,        -- entries needing re-download
    mismatch   = false,         -- true when any failure was a hash mismatch
    ok         = {},            -- verified entries (feed the marker check)
    lua_idx    = 1,
    cur        = nil,
    mode       = "lua",
    -- The user is actively watching the update dialog here, so the
    -- pure-Lua fallback gets the manual (higher) per-frame budget.
    budget     = CFG.UPDATE_SHA_TIME_BUDGET_MANUAL,
    started_at = time_precise(),
  }
  if #to_hash == 0 then
    Updater._download_verify_hashes_done()
    return
  end
  if Updater.fire_native_sha(to_hash) then
    update._dl_verify.mode             = "native"
    update._dl_verify.native_send_time = time_precise()
  end
end

-- All staged hashes are in. Route: re-fire the failed subset once,
-- hard-fail after the second round, or advance to the marker check and
-- stage C when everything verified.
function Updater._download_verify_hashes_done()
  local v = update._dl_verify
  if not v then return end
  if #v.failed > 0 then
    local names = {}
    for i = 1, math.min(#v.failed, 6) do
      names[#names+1] = tostring(v.failed[i].filename)
    end
    local name_list = table.concat(names, ", ")
      .. (#v.failed > 6 and ", ..." or "")
    if not update._batch.refire_used then
      -- One bounded second chance: transient CDN staleness, a dropped
      -- connection mid-batch, or an AV lock on a staged file all
      -- present as missing/mismatched staged files. Delete the bad
      -- staging outputs and re-fire ONE more batch for just those
      -- entries; everything already verified stays staged.
      Log.line("UPDATE", string.format(
        "staged verify: %d file(s) failed (%s); re-firing one batch "
        .. "for the failed subset.", #v.failed, name_list))
      local refire = v.failed
      for _, entry in ipairs(refire) do os.remove(entry.staged) end
      update._batch.refire_used = true
      update._batch.started_at  = time_precise()
      update._batch.watchdog    = CFG.UPDATE_BATCH_WATCHDOG_BASE
        + CFG.UPDATE_BATCH_WATCHDOG_PER_FILE * #refire
      update._dl_verify = nil
      local remote_refire, inline_err = Updater.stage_inline_entries(refire)
      if not remote_refire then
        Updater._download_verify_fail("download_stage", inline_err)
        return
      end
      if #remote_refire == 0 then
        Updater.download_verify_start()
        return
      end
      if not Updater.fire_batch_download(remote_refire) then
        Updater._download_verify_fail("download_batch",
          "Could not restart the update download.")
        return
      end
      update.state = "downloading_batch"
      return
    end
    -- Second round already used: hard fail. Step name keeps the
    -- existing dialog copy honest: sha_verify routes to the
    -- CDN-propagation message, download to the generic network copy.
    local step = v.mismatch and "sha_verify" or "download"
    Updater._download_verify_fail(step, string.format(
      "%d file(s) failed download verification after a retry: %s",
      #v.failed, name_list))
    return
  end
  -- Every staged file hashed clean; run the content marker check over staged
  -- .lua files (one per frame, they can be MB-sized reads) before stage C
  -- touches anything live. Body files carry CFG.VERSION. The two permanent
  -- launchers intentionally do not, so package-root entries use the launcher
  -- identity marker plus the mode-specific marker for their exact filename.
  v.phase      = "markers"
  v.marker_idx = 1
  v.markers    = {}
  for _, entry in ipairs(v.ok) do
    if tostring(entry.filename):match("%.lua$") then
      v.markers[#v.markers+1] = entry
    end
  end
end

-- One frame of the staged .lua marker check. This is a secondary sanity check
-- after SHA verification. Body files require CFG.VERSION. Package-root files
-- must be one of the two known launchers, carry the shared launcher identity,
-- and carry the marker specific to that launcher. This catches a manifest that
-- hashes the wrong legitimate launcher under the other launcher's filename.
-- Re-downloading cannot fix a bad manifest, so rejection is a hard failure
-- with a distinct content_verify step for the dialog copy.
function Updater._download_verify_marker_tick()
  local v = update._dl_verify
  if not v then return end
  local entry = v.markers[v.marker_idx]
  if not entry then
    update._dl_verify = nil
    Updater.apply_start()
    return
  end
  local f, f_err = io.open(entry.staged, "rb")
  local content = f and f:read("*a") or nil
  if f then f:close() end
  if not content then
    Updater._download_verify_fail("download", string.format(
      "Could not re-open staged %s for the content check: %s",
      tostring(entry.filename), tostring(f_err)))
    return
  end
  local required = "CFG.VERSION"
  local required_label = "CFG.VERSION marker"
  if entry.root == "package" then
    local identity = "The shipped path is an action identity"
      .. " and can never move"
    if entry.filename == "ReaAssist.lua" then
      required = 'local LAUNCHER_MODE = "standard"'
      required_label = "standard launcher mode marker"
    elseif entry.filename == "ReaAssist_Screen_Reader_Mode.lua" then
      required = 'rawset(_G, "ReaAssist_LAUNCHER_MODE", "sr")'
      required_label = "Screen Reader launcher delegation marker"
    else
      Updater._download_verify_fail("content_verify", string.format(
        "Downloaded package-root Lua file %s is not a known ReaAssist "
        .. "launcher (rejected as an invalid update target).",
        tostring(entry.filename)))
      return
    end
    if not content:find(identity, 1, true) then
      Updater._download_verify_fail("content_verify", string.format(
        "Downloaded %s is missing the launcher identity marker "
        .. "(rejected as likely-corrupt or non-ReaAssist content).",
        tostring(entry.filename)))
      return
    end
  end
  if not content:find(required, 1, true) then
    Updater._download_verify_fail("content_verify", string.format(
      "Downloaded %s is missing the %s "
      .. "(rejected as likely-corrupt or non-ReaAssist content).",
      tostring(entry.filename), required_label))
    return
  end
  v.marker_idx = v.marker_idx + 1
end

-- One tick of stage B. Native mode polls the hasher subprocess's exit
-- file (with the same watchdog + fallback triage the repair scan
-- uses); lua mode compresses budgeted chunks per frame. The marker
-- phase runs after all hashes land.
function Updater.download_verify_tick()
  local v = update._dl_verify
  if not v then return end
  if v.phase == "markers" then
    Updater._download_verify_marker_tick()
    return
  end

  if v.mode == "native" then
    if v.native_send_time
        and (time_precise() - v.native_send_time)
            > (CFG.UPDATE_NATIVE_SHA_TIMEOUT + 5) then
      Log.line("UPDATE", "download_verify: native watchdog timeout, "
                         .. "falling back to pure-Lua verify")
      v.mode    = "lua_fallback"
      v.lua_idx = 1
      v.cur     = nil
      return
    end
    local ef = io.open(tmp.update_sha_exit, "r")
    if not ef then return end
    local exit_str = ef:read("*a"); ef:close()
    local exit_code = tonumber(exit_str:match("(%d+)"))
    if not exit_code then return end
    if exit_code ~= 0 then
      Log.line("UPDATE", string.format(
        "download_verify: native hasher exited %d, "
        .. "falling back to pure-Lua verify", exit_code))
      v.mode    = "lua_fallback"
      v.lua_idx = 1
      v.cur     = nil
      return
    end
    local of, of_err = io.open(tmp.update_sha_out, "rb")
    if not of then
      Log.line("UPDATE", "download_verify: output read failed: "
                         .. tostring(of_err) .. ", falling back")
      v.mode    = "lua_fallback"
      v.lua_idx = 1
      v.cur     = nil
      return
    end
    local raw = of:read("*a"); of:close()
    if raw:sub(1, 3) == "\239\187\191" then raw = raw:sub(4) end
    local hash_by_path = {}
    for line in raw:gmatch("[^\r\n]+") do
      local hex, rest = line:match("^([0-9a-fA-F]+)[ \t]+(.+)$")
      if hex and #hex == 64 and rest then
        hash_by_path[rest] = hex:lower()
      end
    end
    -- Triage against local tables first so a fallback decision cannot
    -- leak partial results (same pattern as tick_native_sha).
    local ok_entries, failed_entries = {}, {}
    local mismatch, suspicious = false, false
    for _, item in ipairs(v.to_hash) do
      local local_hash = hash_by_path[item.path]
      if local_hash then
        if local_hash == item.entry.sha256:lower() then
          ok_entries[#ok_entries+1] = item.entry
        else
          mismatch = true
          failed_entries[#failed_entries+1] = item.entry
        end
      else
        -- No native hash for a staged file we just saw on disk. Gone
        -- now -> failed (re-download). Locked now -> failed too (these
        -- are OUR fresh staging files; a persistent lock fails the
        -- retry round with the AV message). Present and readable ->
        -- suspicious output, recompute everything in pure Lua.
        local f = io.open(item.path, "rb")
        if f then
          f:close()
          suspicious = true
          break
        end
        failed_entries[#failed_entries+1] = item.entry
      end
    end
    if suspicious then
      Log.line("UPDATE", "download_verify: staged file readable but "
        .. "missing from native output; falling back to pure-Lua verify")
      v.mode    = "lua_fallback"
      v.lua_idx = 1
      v.cur     = nil
      return
    end
    for _, entry in ipairs(ok_entries) do v.ok[#v.ok+1] = entry end
    for _, entry in ipairs(failed_entries) do
      v.failed[#v.failed+1] = entry
    end
    v.mismatch = v.mismatch or mismatch
    Updater._download_verify_hashes_done()
    return
  end

  -- Pure-Lua path (mode "lua" or "lua_fallback"): budgeted chunked
  -- hashing, one staged file in flight at a time.
  if not v.cur then
    while v.lua_idx <= #v.to_hash do
      local item = v.to_hash[v.lua_idx]
      local f = io.open(item.path, "rb")
      local content = f and f:read("*a") or nil
      if f then f:close() end
      if content then
        v.cur = { entry = item.entry, state = _SHA.create(content) }
        break
      end
      -- Vanished or locked between staging and verify: fail it into
      -- the re-fire round rather than skipping it as intact (these are
      -- staged downloads, not user files; "unreadable" can never mean
      -- "fine").
      v.failed[#v.failed+1] = item.entry
      v.lua_idx = v.lua_idx + 1
    end
    if not v.cur then
      Updater._download_verify_hashes_done()
      return
    end
  end
  local tick_start = time_precise()
  local budget = v.budget or CFG.UPDATE_SHA_TIME_BUDGET
  local done
  repeat
    done = _SHA.step(v.cur.state, 16)
    if done then break end
  until (time_precise() - tick_start) >= budget
  if done then
    local local_hash = _SHA.finalize(v.cur.state)
    if local_hash == v.cur.entry.sha256:lower() then
      v.ok[#v.ok+1] = v.cur.entry
    else
      v.mismatch = true
      v.failed[#v.failed+1] = v.cur.entry
    end
    v.cur     = nil
    v.lua_idx = v.lua_idx + 1
  end
end

-- Fire auto-restart if the download pipeline is in "done" state, the
-- restart delay has elapsed, and we have not already fired. Called from
-- both the main loop and Bootstrap.loop so either flow auto-restarts
-- after a successful apply. Single-fire via update.restart_fired so we
-- only invoke Main_OnCommand once.
--
-- Fires the external relauncher action (registered at startup) and
-- closes ourselves. Firing Main_OnCommand on ReaAssist's own CMD_ID
-- from inside our still-running defer chain triggers REAPER's
-- re-entrance handling -- the action "is already running" -- and the
-- single-instance handshake interprets that as a toggle-off, exiting
-- the new instance immediately. The relauncher is a separate script
-- with its own action id, so invoking it from here does NOT hit that
-- re-entrance path. It waits for our "running" ExtState to clear,
-- re-registers ReaAssist via AddRemoveReaScript, and fires a fresh
-- Main_OnCommand on ReaAssist from its own context.
--
-- Updater._apply_finish only sets update.restart_after when the
-- relauncher file is present on disk, so by the time we reach this
-- function the on-demand AddRemoveReaScript call should succeed.
function Updater.try_auto_restart()
  if update.state ~= "done" then return end
  if not update.restart_after or update.restart_fired then return end
  if time_precise() < update.restart_after then return end
  update.restart_fired = true
  local ok = Updater.fire_relauncher_now(S.screen_reader_mode and "sr" or "standard")
  if not ok then update.restart_after = nil end
  return ok
end

-- Shared helper: fires the relauncher script in its own Lua state, then
-- closes the current ReaAssist instance. Used by:
--   * try_auto_restart (post-update success)
--   * Render._factory_reset_execute (UI file -- relauncher path is
--     local to this file, so the UI can't fire it directly)
-- Returns true on success, false if the relauncher couldn't be
-- registered (caller can fall back to a "close and reopen" prompt).
function Updater.fire_relauncher_now(mode)
  if not RA._file_exists(RELAUNCHER_PATH) then return false end
  mode = mode or "standard"
  if mode ~= "sr" and mode ~= "standard" then return false end
  if (type(S.INSTANCE_ID) ~= "string" or S.INSTANCE_ID == ""
      or S.INSTANCE_ID:find("|", 1, true)) then return false end
  -- Lazy-register the relauncher action right before firing it. Keeps
  -- the Actions list uncluttered for sessions where no auto-restart
  -- ever happens. AddRemoveReaScript is synchronous and the returned
  -- cmd_id is immediately usable from Main_OnCommand. commit=false so
  -- the registration is session-only (vanishes when REAPER closes).
  local cmd_id = reaper.AddRemoveReaScript(true, 0, RELAUNCHER_PATH, false)
  if cmd_id and cmd_id ~= 0 then
    -- Tag both modes so an older caller with no request is distinguishable.
    -- Explicit visual switches and resets use the standard entry point.
    local request = S.INSTANCE_ID .. "|" .. mode
    reaper.SetExtState(CFG.EXT_NS, "relaunch_mode", request, false)
    local fired = pcall(reaper.Main_OnCommand, cmd_id, 0)
    if not fired then
      if reaper.GetExtState(CFG.EXT_NS, "relaunch_mode") == request then
        reaper.DeleteExtState(CFG.EXT_NS, "relaunch_mode", false)
      end
      return false
    end
    S.script_open = false
    return true
  end
  return false
end

-- =============================================================================
-- Transactional apply: journal (stage C) + startup recovery
-- =============================================================================
-- The journal is the crash-recovery contract for stage C. It is written
-- BEFORE the first rename, updated after every applied file (atomic
-- write-to-tmp-then-rename so a torn write can never corrupt it), marked
-- committed after orphan cleanup, and deleted only after the .baks are
-- gone. Startup recovery (resolve_journal_at_startup below) rolls an
-- interrupted apply forward when every remaining staged file is present
-- and hash-valid, and rolls it back otherwise, so a crash mid-batch can
-- no longer boot a mixed release or strand its .baks.

-- Exclusive apply lock. One shared lock gates the whole
-- download->verify->apply pipeline: acquired at the top of
-- download_start before any staging mutation, released on every
-- terminal path (done, failed, rollback) and at exit. A stale lock
-- (dead owner per the live-marker check) is reclaimed like a stale
-- journal.
--
-- The claim is OS-atomic on both platforms, claim-then-rename flavored:
--   * Windows: write a private instance-suffixed claim FILE carrying
--     our id, then os.rename it onto the lock name. Windows rename
--     refuses to clobber an existing target, so a successful rename IS
--     the acquisition; exactly one of any number of racing claimants
--     wins.
--   * POSIX: mkdir a private instance-suffixed claim DIRECTORY, write
--     the owner file INSIDE it, then os.rename the directory onto
--     <lock>.d. rename(2) is atomic for directories and fails when the
--     target exists non-empty, and the winner's lock directory always
--     carries its owner file, so no ownerless shared state exists at
--     any instant. (The shared lock dir is never empty while held, so
--     rename(2)'s replace-an-empty-target case cannot fire against a
--     held lock.)
-- The journal ownership verify in apply_start and the first-frame
-- re-verify in apply_tick remain as defense in depth (e.g. against a
-- hand-deleted lock file mid-apply), no longer as the primary guard.
--
-- ONE CLAIM SHAPE PER PLATFORM, AND THE PLATFORM PICKS IT (Codex round 44,
-- B2.3u).
-- -----------------------------------------------------------------------------
-- The two protocols above used to be three, because a CAPABILITY chose between
-- them: the wbx fast path (C fopen exclusive-create) ran ahead of both, so a
-- runtime whose fopen accepts "wbx" claimed the flat name and a runtime whose
-- fopen does not claimed the directory, on the same platform, at the same
-- install. Nothing made those two shapes exclude each other. Two runtimes
-- sharing one install with different fopen builds (REAPER's Lua beside another
-- embedding, or two REAPER versions) could each hold a live claim in a
-- different shape, and the reader that decides authority looks at the flat name
-- first while the clear used to remove BOTH, so one holder could erase the
-- other's protection and the two-writers state reopened underneath it.
--
-- So the shape is the PLATFORM's now, and a capability may only choose how the
-- platform's one shape is created:
--   * POSIX is the claim DIRECTORY, always. mkdir is atomic on every POSIX
--     filesystem and asks nothing of fopen, so every process on that install
--     builds the same artifact whatever its Lua was compiled against.
--   * Windows is the flat name, always, and its two ways of creating it are
--     exclusive ON THAT ONE NAME: fopen "wbx" fails with EEXIST when the name
--     exists (C11 exclusive-create), and Windows rename refuses to clobber an
--     existing target, which is the very property the rename claim rests on. A
--     wbx-capable runtime and a rename-claim runtime therefore contend for the
--     same artifact and exactly one wins, so that pair needs no canonicalizing.
-- The wbx probe stays, on the Windows lane, where it is a fast path to the same
-- artifact rather than a different one.
--
-- AND NO SECOND SHAPE MAY BE BUILT BESIDE A FIRST. The claim asks what is
-- standing at the shared name before it creates anything, in the same order
-- every other reader asks it, and refuses if any shape answers. A pre-B2.3u
-- body's lock, of either shape, is therefore honored rather than doubled, and
-- the clear removes only the shape it can name as the holder's own.

-- WHAT THE LOCK IS CARRYING RIGHT NOW, VERBATIM (Codex round 41, B2.3r).
-- =============================================================================
-- The lock file holds an ACQUISITION identity, not merely an owner id: the
-- instance suffix, then a separator, then a nonce this acquisition minted. The
-- suffix says which process, and the nonce says which taking of the lock, which
-- is the difference between "our kind of instance holds it" and "the run of
-- ours that is standing here holds it".
--
-- Read raw and compared whole. Everything that has to know whether it still
-- owns the lock compares this against the identity it minted, so a lock that is
-- gone, emptied, renamed or carrying somebody else's identity all answer the
-- same way: not ours.
--
-- The flat lock file (the Windows claim) or the POSIX lock directory's owner
-- file, in that order, exactly as the owner read has always looked for them.
--
-- AND IT SAYS WHICH ONE IT READ (Codex round 44, B2.3u). The order is the
-- canonical one for the whole lane: a flat claim outranks a directory claim,
-- and it has to, because the only body that can still build a second shape
-- beside ours is a pre-B2.3u one, whose fopen-capable branch builds the flat
-- name and which has no fence to stand down with. So the flat claimant keeps
-- authority and OUR holder yields, which is the only way round that leaves one
-- writer. The second return names the artifact the answer came out of, so the
-- release can give back the shape it is really holding instead of clearing
-- whatever is at the name.
function Updater._lock_identity(path)
  local raw = Updater._lock_read_claim(path)
  if raw ~= nil then return raw, path end
  local lock_dir = path .. ".d"
  raw = Updater._lock_read_claim(lock_dir .. "/owner")
  if raw ~= nil then return raw, lock_dir end
  return nil
end

-- The identity written into ONE named claim, read raw and trimmed. Split out of
-- the read above because release and the reclaim have to ask a shape BY NAME
-- rather than take whichever answers first: the one they may remove is the one
-- carrying their own identity, and the other one is somebody else's protection.
function Updater._lock_read_claim(p)
  local f = io.open(p, "rb")
  if not f then return nil end
  local raw = f:read("*a"); f:close()
  if type(raw) ~= "string" then return nil end
  raw = raw:match("^%s*(.-)%s*$")
  if raw == "" then return nil end
  return raw
end

-- WHICH SHAPES ARE CARRYING THIS IDENTITY, asked of BOTH rather than of the
-- first that answers. A claim of ours can be standing underneath a claim we do
-- not own (a pre-B2.3u body taking the flat name while we hold the directory),
-- and in that state the identity read above answers with the stranger's, which
-- is right for authority and wrong for release: ours is still ours to give
-- back, and leaving it would strand the install behind a lock nobody will hand
-- over.
--
-- AND THE ANSWER IS A LIST, WHICH IT STAYS NOW THAT THE GUARD IS GONE (Codex
-- round 46, B2.3w). B2.3v's POSIX claim stood in two artifacts of its own and
-- this had to be plural to give both of them back; the guard was removed this
-- round, so a claim THIS body takes is one artifact again and on every ordinary
-- launch the list has exactly one entry in it. It stays a list because the rule
-- it carries is about the shapes a NAME can be carrying rather than about how
-- many this protocol builds: whatever put them there, a caller entitled to one
-- shape of an identity is entitled to every shape of it, and handing back half
-- of a claim would leave a lock standing in a name nobody will give up again. A
-- singular answer would have to look at one shape first and stop, and the
-- branch it did not take would be the wrong one exactly when it mattered.
--
-- The order is REMOVAL order, canonical claim first, so a name carrying both
-- shapes keeps the flat one occupied for as long as the directory is coming
-- apart.
function Updater._lock_artifacts_of(path, identity)
  if type(identity) ~= "string" or identity == "" then return {} end
  return Updater._lock_artifacts_where(path, identity, false)
end

-- The same question asked about an INSTANCE rather than about one taking of the
-- lock, for the single caller entitled to ask it that way: a reclaim has proven
-- a named instance gone, and every artifact carrying that instance's name is
-- that instance's. Matching the owner rather than the whole identity is what
-- lets one lawful reclaim take a dead holder's whole claim instead of leaving
-- half of it standing for the launch after this one to puzzle over.
function Updater._lock_artifacts_owned(path, owner)
  if type(owner) ~= "string" or owner == "" then return {} end
  return Updater._lock_artifacts_where(path, owner, true)
end

function Updater._lock_artifacts_where(path, want, by_owner)
  local out = {}
  local lock_dir = path .. ".d"
  local function carries(p)
    local id = Updater._lock_read_claim(p)
    if id == nil then return false end
    if by_owner then return id:match("inst_[%w%-_]+") == want end
    return id == want
  end
  if carries(lock_dir .. "/owner") then out[#out + 1] = lock_dir end
  if carries(path) then out[#out + 1] = path end
  return out
end

-- WHAT IS STANDING AT THE SHARED LOCK NAME, AND WHERE IT ACTUALLY IS (Codex
-- round 43, B2.3t).
-- =============================================================================
-- Two questions used to be one, and both of the answers were wrong on a branch.
--
-- PRESENCE, and it has to fail closed. The two failures an acquisition can
-- suffer look identical from the return value and lead opposite ways: a lock
-- this launch could not CREATE is disk or permissions, and a lock it could not
-- TAKE is company, or since B2.3s company nobody here can judge. Telling a user
-- with a full disk that another copy of ReaAssist is holding their install
-- would be a wall with no door in it, so the two are separated, and this is the
-- separation. It asked io.open, which cannot tell a lock that is NOT THERE from
-- one this launch may not read: a lock antivirus has open with no sharing, or
-- one whose ACL somebody tightened, answered absent, and the acquisition took
-- the could-not-create road and said another instance was applying. That is the
-- one class of lock most likely to need the stop that offers a way out. So the
-- probe is RA.path_present, which this whole lane has used since B2.2d and
-- which treats a definitive ENOENT as the only absence: unreadable, locked and
-- unlistable all answer PRESENT, and only a name with nothing at it lets the
-- deferred road stay open.
--
-- IDENTITY OF THE ARTIFACT, which is a different fact from presence and is what
-- the two recovery surfaces put in front of the user. The claim protocol makes
-- a flat FILE on Windows and on the wbx fast path, and a DIRECTORY (<lock>.d,
-- with the owner file inside it) on POSIX. A dialog that asks somebody to
-- delete a lock by hand has to name the thing they will actually see in their
-- file manager, and until this round both surfaces named the unsuffixed base
-- path, which does not exist at all on the POSIX branch. So presence answers
-- WITH the artifact and with the word for what kind of thing it is, and every
-- surface takes both from here rather than respelling the base name.
--
-- Nothing at the name returns nil, which is the could-not-create case and keeps
-- its own ending.
--
-- AND A THIRD ANSWER, FOR THE PLACE WHERE NEITHER OF THE OTHER TWO IS TRUE
-- (Codex round 44, B2.3u). The fail-closed probe reads every error that is not
-- a definitive ENOENT as presence, which is right, and on POSIX there is one
-- condition that returns such an error for EVERY name in a directory whether
-- something is there or not: a parent that denies SEARCH permission. open(2)
-- and rename(2) both specify EACCES when "search permission is denied on a
-- component of the path prefix", before either of them has looked at the leaf.
-- So presence answered yes at an empty name, the artifact was reported as the
-- flat file, and the copy asked the user to delete a file that need not exist,
-- over a directory they could not open anyway: fail-safe, and an instruction
-- that cannot be followed, which is the class round 43 was about.
--
-- The discriminator is A NAME THAT CANNOT EXIST. Nothing in this body ever
-- creates <lock>.seen.<instance>, and the instance suffix carries a random
-- tail, so nothing else has put one there either. Under a parent this process
-- can search it is a definitive ENOENT and the probe is sighted; under a parent
-- it cannot search it gives back the same non-ENOENT the lock name gave, and
-- that is proof the answer is about the DIRECTORY rather than about the lock.
-- Then the honest thing to name is the directory and the permission, not a
-- file, so the kind is "blocked" and both surfaces say so.
--
-- ONE ARTIFACT IS NAMED, BECAUSE ONE IS WHAT A CLAIM IS AGAIN (Codex round 46,
-- B2.3w). B2.3v's guard put a second artifact beside the POSIX claim and both
-- surfaces had to name the pair; the guard is gone, so a claim this body takes
-- is the one shape its platform builds and the answer is the single one every
-- surface has always spelled. The flat-first order is the authority order: if a
-- stranger's flat claim is ever standing over our directory, that claimant
-- outranks us and the artifact answer follows the authority.
function Updater._lock_artifact(path)
  local blind = Updater._lock_unsearchable_parent(path)
  if blind ~= nil then return blind, "blocked" end
  if RA.path_present(path) then return path, "file" end
  local lock_dir = path .. ".d"
  -- The directory is the artifact; its owner file is asked as well because a
  -- directory whose listing is refused can still open a child by name (B2.2h),
  -- and either answer means a claim is standing.
  if RA.path_present(lock_dir) or RA.path_present(lock_dir .. "/owner") then
    return lock_dir, "folder"
  end
  return nil
end

-- The name that cannot exist, and the folder its answer is really about. Nil
-- when this process can see into the lock's directory, which is every ordinary
-- launch and every case the earlier rounds measured: a lock held by another
-- process with no sharing still sits in a directory whose empty names answer
-- ENOENT, so that one keeps its own file-shaped answer above.
function Updater._lock_unsearchable_parent(path)
  local parent = tostring(path):match("^(.*)[/\\]")
  -- A bare name has no parent to accuse, so it keeps the ordinary answers.
  if parent == nil or parent == "" then return nil end
  if RA.path_present(path .. ".seen." .. RA.instance_file_suffix()) then
    return parent
  end
  return nil
end

function Updater._lock_present(path)
  return Updater._lock_artifact(path) ~= nil
end

-- Owner id: which INSTANCE holds the lock, without the acquisition nonce. The
-- acquisition protocol asks this (is the holder alive, is the holder us) and
-- the startup resolver asks it to tell a live contender from a lock it could
-- not create. The nonce never joins the instance suffix's character class, so
-- an identity minted before B2.3r and one minted since read the same way here.
-- The artifact comes back with it (Codex round 44, B2.3u), so a caller entitled
-- to clear this owner's claim clears the shape the owner was actually read out
-- of and leaves any other one alone.
function Updater._lock_owner(path)
  local raw, artifact = Updater._lock_identity(path)
  local owner = raw and raw:match("inst_[%w%-_]+") or nil
  if owner == nil then return nil end
  return owner, artifact
end

-- Our own leftover claim file/dir, which are ours whatever is standing at the
-- shared lock name. A crash between claim-write and rename strands one, and a
-- release that gave nothing back still sweeps its own.
function Updater._lock_claim_clear(path)
  os.remove(path .. ".claim." .. RA.instance_file_suffix())
  local claim_dir = path .. ".d.claim." .. RA.instance_file_suffix()
  os.remove(claim_dir .. "/owner")
  os.remove(claim_dir)
end

-- Remove ONE claim: the shape named, and never the other one (Codex round 44,
-- B2.3u). It used to remove both, on the reasoning that only one of them can
-- exist on a given platform. That was true only while the shape was the
-- platform's, and until this round a capability chose it, so both could stand
-- at once and this was the instruction that erased the other holder's
-- protection: a release or a lawful reclaim of the flat claim took a live
-- directory claim with it. Both call sites can name the shape they are
-- entitled to (release the one carrying its own identity, the reclaim the one
-- whose owner it proved dead), and a caller that cannot name one removes
-- nothing shared, which is the fail-safe answer.
--
-- Our own leftover claim file/dir go either way: they are ours whatever is
-- standing at the shared name.
function Updater._lock_clear(path, artifact)
  if artifact == path then
    os.remove(path)
  elseif artifact == path .. ".d" then
    os.remove(path .. ".d/owner")
    os.remove(path .. ".d")
  end
  Updater._lock_claim_clear(path)
end

function Updater._lock_try_create(path, identity)
  -- Returns true when this call atomically claimed the lock for us, with
  -- `identity` (this acquisition's, minted by the caller) written into the lock
  -- from the first instant it exists under the shared name. Defaulted to the
  -- bare instance suffix so a caller that has no acquisition to name still
  -- produces a lock the owner read understands.
  identity = tostring(identity or RA.instance_file_suffix())
  -- ONE CLAIM AT THE SHARED NAME, WHATEVER SHAPE IT IS IN (Codex round 44,
  -- B2.3u). Asked before anything is created, in the canonical order every
  -- other reader uses, so a claim already standing is never doubled by a second
  -- shape beside it. The atomic create below still decides the race between two
  -- claimants of the SAME shape; this decides the one thing an atomic create on
  -- one name cannot see, which is a claim living under another name. It also
  -- honors a pre-B2.3u body's lock of either shape, which is the migration this
  -- round has to carry: during a handoff an old body and a new one share the
  -- install, and the old one's claim is a claim.
  if Updater._lock_artifact(path) ~= nil then return false end
  if not RA.IS_WINDOWS then
    -- POSIX: claim-then-rename, directory flavored, and it is the ONLY shape
    -- here now. Build a PRIVATE instance-suffixed claim directory with the
    -- owner file already inside it, then atomically rename it onto the shared
    -- lock directory. rename(2) is atomic for directories and fails when the
    -- target exists non-empty, so exactly one claimant wins, and the winning
    -- lock directory carries its owner file from the first instant it exists
    -- under the shared name: no ownerless window. mkdir asks nothing of this
    -- runtime's fopen, which is why it can be everyone's.
    if Updater._lock_shape_logged ~= true then
      Updater._lock_shape_logged = true
      Log.line("UPDATE", "apply lock: the claim on this platform is the "
        .. "directory beside the lock name, taken by mkdir and rename.")
    end
    local lock_dir = path .. ".d"
    local claim_dir = path .. ".d.claim." .. RA.instance_file_suffix()
    os.remove(claim_dir .. "/owner")
    os.remove(claim_dir)
    local ok = os.execute("mkdir " .. Shell.sh_quote(claim_dir)
      .. " 2>/dev/null")
    if ok ~= true and ok ~= 0 then return false end
    local f = io.open(claim_dir .. "/owner", "wb")
    if not f then os.remove(claim_dir); return false end
    local w_ok = pcall(function() assert(f:write(identity)) end)
    local c_ok = pcall(function() assert(f:close()) end)
    if not w_ok or not c_ok then
      os.remove(claim_dir .. "/owner")
      os.remove(claim_dir)
      return false
    end
    if not os.rename(claim_dir, lock_dir) then
      os.remove(claim_dir .. "/owner")
      os.remove(claim_dir)
      return false
    end
    -- ASKED AGAIN NOW THAT WE HOLD ONE. The question above and the rename are
    -- two instructions, and the flat name is the one a pre-B2.3u body can take
    -- between them. If one appeared, this launch gives back the directory it
    -- just won rather than stand beside it: what we remove here is our own, the
    -- newcomer's claim is untouched, and the acquisition goes on to read the
    -- owner it just found and treat it as the company it is.
    --
    -- RESTORED IN PLACE OF THE MIGRATION GUARD (Codex round 46, B2.3w). B2.3v
    -- replaced this with an exclusive create at the flat name, on the reasoning
    -- that a check and the instruction it authorizes are two instructions. The
    -- guard is gone this round because the actor it answered needs a POSIX Lua
    -- whose fopen takes the exclusive-create mode and no REAPER has one, and
    -- the objection does not apply to this re-check anyway: what it authorizes
    -- is the removal of THIS launch's own directory, which nothing else can be
    -- holding, and the stranger's claim is what it stands down for rather than
    -- what it writes over.
    if RA.path_present(path) then
      os.remove(lock_dir .. "/owner")
      os.remove(lock_dir)
      return false
    end
    return true
  end
  -- Windows: one flat artifact, two ways of creating it, and both of them are
  -- exclusive on that one name, so a runtime with fopen "wbx" and a runtime
  -- without it contend for the same thing and exactly one wins.
  if Updater._wbx_supported == nil then
    local probe = path .. ".probe"
    os.remove(probe)
    local ok, pf = pcall(io.open, probe, "wbx")
    Updater._wbx_supported = ok and true or false
    if ok and pf then pf:close() end
    os.remove(probe)
    Log.line("UPDATE", "apply lock: the claim on this platform is the file at "
      .. "the lock name; fopen exclusive-create "
      .. (Updater._wbx_supported and "available"
          or "unavailable; using the atomic rename claim"))
  end
  if Updater._wbx_supported then
    local ok, f = pcall(io.open, path, "wbx")
    if not ok or not f then return false end
    local w_ok = pcall(function() assert(f:write(identity)) end)
    pcall(function() f:close() end)
    if not w_ok then os.remove(path); return false end
    return true
  end
  -- Atomic rename claim. A crash between claim-write and rename can
  -- strand a tiny .claim.<instance> file in Data/Temp; our own is
  -- cleared on the next attempt and Data/Temp is disposable.
  local claim = path .. ".claim." .. RA.instance_file_suffix()
  os.remove(claim)
  local f = io.open(claim, "wb")
  if not f then return false end
  local w_ok = pcall(function() assert(f:write(identity)) end)
  local c_ok = pcall(function() assert(f:close()) end)
  if not w_ok or not c_ok then os.remove(claim); return false end
  if not os.rename(claim, path) then
    os.remove(claim)
    return false
  end
  return true
end

-- WHETHER THIS PROCESS TOOK THE LOCK, AND WHICH TAKING OF IT (Codex round 40,
-- B2.3q; fenced in round 41, B2.3r).
-- =============================================================================
-- B2.3q made this an in-process flag on the reasoning that the question is not
-- "does a lock file exist" but "did THIS process take the lock and still have
-- it". The first half of that is right and the second half was not asked. A
-- process whose live marker goes stale (a sleeping machine, a walk that outruns
-- the fifteen-second bound) has its lock RECLAIMED under it by the acquisition
-- below, and a flag in its memory cannot know that happened. It went on
-- believing it held a lock somebody else was holding.
--
-- So the flag stays and stops being the answer. It is one of three things the
-- authority test asks, and the load-bearing one is physical: the identity
-- minted here is written INTO the lock, and every mutation re-reads the lock
-- and requires it to still name this acquisition
-- (Updater.journal_writers_excluded).
--
-- `_apply_lock_revoked` is what makes losing it permanent. A holder that
-- discovers the lock is no longer its own never mutates again on that
-- acquisition, even if the lock frees a moment later: its classification, its
-- staged decisions and its whole picture of the disk were taken before the
-- theft, and the only sound thing left to do with them is stop. Only a fresh
-- successful acquisition clears it, because a fresh acquisition is a fresh
-- picture.
Updater._apply_lock_held = false
Updater._apply_lock_token = nil
Updater._apply_lock_revoked = false
Updater._apply_lock_seq = 0
-- Set by an acquisition that refused to reclaim because it could not tell
-- whether the recorded owner is alive. Read by the two roads into this lock so
-- each can surface the stop on its own surface; cleared by the next attempt.
--
-- The artifact travels with the owner (Codex round 43, B2.3t). Both surfaces
-- ask the user to remove the claim by hand, so both have to name the thing that
-- is really on disk: the acquisition is the only thing that looked, and a
-- surface re-probing later would be answering about a different instant.
-- `_kind` is the word for it, already spelled the way the copy says it.
Updater._apply_lock_undecidable = nil
Updater._apply_lock_undecidable_path = nil
Updater._apply_lock_undecidable_kind = nil

-- One identity per taking of the lock. The instance suffix says which process
-- and the tail says which acquisition: a counter that cannot repeat inside a
-- process. Across processes the suffix is already unique (it carries this
-- instance's start time and a random tail), so the counter has only its own
-- process to distinguish itself within, and that is exactly the case a bare
-- suffix could not tell apart: a walk that was deposed and a later download by
-- the same process must not share an authority.
--
-- The separator is deliberately outside the instance suffix's character class,
-- so the owner read still stops at the suffix and everything that only wants to
-- know WHICH INSTANCE holds the lock reads exactly what it always read.
function Updater._apply_lock_mint()
  Updater._apply_lock_seq = (Updater._apply_lock_seq or 0) + 1
  return RA.instance_file_suffix() .. "#" .. tostring(Updater._apply_lock_seq)
end

-- MAY THIS LOCK BE TAKEN FROM THE INSTANCE THAT IS HOLDING IT (Codex round 42,
-- B2.3s).
-- =============================================================================
-- Until this round the answer was "if its live marker has aged out", and that
-- is a question about a clock rather than about a process. A machine that
-- suspends stops refreshing markers without stopping running, so the rule
-- deposed living processes, and every fence B2.3q and B2.3r added downstream
-- was catching the consequences of a theft that should never have been allowed.
-- Round 42 ruled the class unclosable that way: a check and the destructive
-- instruction it authorizes are two instructions, and a suspension fits between
-- any two of them.
--
-- So the theft is what goes. A stale marker is now only the trigger to ASK, and
-- the asking is RA.instance_liveness, which answers from the operating system
-- rather than from a timestamp. Only "dead" permits a reclaim, and the dead
-- write nothing, so the two-writers state this whole lane has been chasing
-- since round 40 is not reachable for a living process at all.
--
-- AN UNREADABLE OR OWNERLESS LOCK IS NO LONGER RECLAIMABLE, and that is a
-- deliberate change of direction. It used to be swept as stale-equivalent, on
-- the reasoning that our own protocol never produces one, so one can only be
-- tampering or corruption. True, and it is not a reason to take it: there is no
-- instance named, so there is nobody whose death can be proven, and a lock we
-- cannot attribute may still be a living instance's. Release has treated an
-- unreadable lock this way since B2.3r; acquisition now agrees with it.
function Updater._lock_owner_liveness(owner)
  if owner == nil or owner == "" then return "unknown" end
  if owner == RA.instance_file_suffix() then return "alive" end
  -- A body sliced without the liveness lane cannot prove anything, and
  -- "cannot prove" is never a reclaim.
  if type(RA.instance_liveness) ~= "function" then return "unknown" end
  local verdict = RA.instance_liveness(owner)
  if verdict == "alive" or verdict == "dead" then return verdict end
  return "unknown"
end

function Updater.acquire_apply_lock()
  local path = tmp.update_lock
  local identity = Updater._apply_lock_mint()
  Updater._apply_lock_undecidable = nil
  Updater._apply_lock_undecidable_path = nil
  Updater._apply_lock_undecidable_kind = nil
  -- Two rounds: the second exists so ONE lock whose owner is provably dead can
  -- be reclaimed; a second failure means a contender that took it in between.
  for _ = 1, 2 do
    if Updater._lock_try_create(path, identity) then
      Updater._apply_lock_token = identity
      Updater._apply_lock_revoked = false
      Updater._apply_lock_held = true
      return true
    end
    local owner = Updater._lock_owner(path)
    if owner == RA.instance_file_suffix() then
      -- Already ours under the shared name. Adopt the identity that is ON
      -- DISK rather than the one just minted: the lock is the record of who
      -- holds it, and an in-memory identity the lock does not carry would fail
      -- its own authority test a moment later.
      Updater._apply_lock_token = Updater._lock_identity(path)
      Updater._apply_lock_revoked = false
      Updater._apply_lock_held = true
      return true
    end
    local verdict = Updater._lock_owner_liveness(owner)
    if verdict == "alive" then
      Log.line("UPDATE", "apply lock: " .. tostring(owner) .. " still holds it "
        .. "and is still running, so it keeps it; this launch does nothing to "
        .. "the records it is working on.")
      return false
    end
    if verdict ~= "dead" then
      -- A refusal with NOTHING at the name is not company at all: it is a lock
      -- this launch could not create, which is disk or permissions, and it has
      -- its own ending on both surfaces. Saying "another copy may be holding
      -- your install" to a user with a full disk would be a wall with no door.
      -- Asked fail-closed since B2.3t: a claim this launch may not READ is
      -- standing company, not an empty name, and it used to take this road.
      if not Updater._lock_present(path) then
        Log.line("UPDATE", "apply lock: nothing stands at " .. tostring(path)
          .. " and this launch could not create one there.")
        return false
      end
      -- What is standing there, for the two surfaces that name it. Presence is
      -- this same answer read as a yes or no, so the two cannot disagree.
      local artifact, kind = Updater._lock_artifact(path)
      -- The one state nothing here may decide. Named for the caller, which
      -- surfaces the stop and offers the user the clear only they can
      -- authorize; the lock is left exactly where it stands, as evidence. The
      -- artifact goes with it, because "delete this" has to name the file or
      -- the folder that is really there.
      Updater._apply_lock_undecidable = owner or ""
      Updater._apply_lock_undecidable_path = artifact
      Updater._apply_lock_undecidable_kind = kind
      if kind == "blocked" then
        Log.line("UPDATE", "apply lock: nothing in " .. tostring(artifact)
          .. " can be seen from this launch (every name in it answers the "
          .. "same way whether it is there or not), so whether a claim is "
          .. "standing cannot be decided here and nothing was reclaimed.")
      else
        Log.line("UPDATE", "apply lock: the " .. tostring(kind) .. " at "
          .. tostring(artifact) .. " is held by "
          .. tostring(owner ~= nil and owner ~= "" and owner
            or "an owner this launch could not read")
          .. " and this launch cannot prove whether that instance is still "
          .. "running, so the lock stands and nothing was reclaimed.")
      end
      return false
    end
    Log.line("UPDATE", "apply lock: " .. tostring(owner) .. " is provably gone "
      .. "(its life handle is closed), so its lock is reclaimed.")
    -- ONLY THE SHAPES WHOSE OWNER WAS PROVEN DEAD. A shape beside them carrying
    -- ANOTHER name belongs to somebody whose death nothing here has proven, and
    -- taking it would be the deposition of a living process this lane removed in
    -- B2.3s by the back door. The next round of this loop asks that survivor's
    -- owner the same liveness question on its own merits.
    --
    -- Every artifact naming the dead instance, though, and not merely the one
    -- the owner happened to be read out of (Codex round 45, B2.3v; kept when
    -- the guard went in round 46, B2.3w). Taking one shape and leaving another
    -- one standing in the same dead instance's name would send the acquisition
    -- into its second round to prove the same death over again and then hand
    -- back a refusal for a lock nobody holds. This body builds one shape per
    -- claim, so on an ordinary launch the list has one entry; what the loop
    -- costs is nothing and what it buys is that no arrangement of shapes at
    -- this name can leave half a dead instance's claim behind.
    for _, artifact in ipairs(Updater._lock_artifacts_owned(path, owner)) do
      Updater._lock_clear(path, artifact)
    end
  end
  return false
end

function Updater.release_apply_lock()
  local path = tmp.update_lock
  local mine = Updater._apply_lock_token
  -- Give back the lock THIS ACQUISITION is carrying, and nothing else.
  --
  -- A holder that was deposed while it was away has no lock to give back: what
  -- is at that name belongs to the instance that took it, and leaving with it
  -- would hand the install to a third instance in the middle of the second
  -- one's work. That now covers an UNREADABLE lock too, which the owner-id rule
  -- used to sweep as stale-equivalent. A lock that cannot be read is the worst
  -- moment to guess: the claim protocol never produces an ownerless window, so
  -- one is tampering or a transient hold rather than an abandoned lock, and
  -- neither is ours to tidy away.
  --
  -- Our own claim leftovers go either way, because they are ours whatever is
  -- standing at the shared name.
  --
  -- AND IT GIVES BACK A SHAPE, NOT A NAME (Codex round 44, B2.3u). The question
  -- is asked of both shapes and answered with the one carrying OUR identity,
  -- which does two things the old spelling could not. It never removes the
  -- other shape, so a holder handing its own claim back cannot take a second
  -- holder's protection with it. And it still finds ours when a pre-B2.3u body
  -- has taken the flat name over the directory we are holding: that stranger
  -- outranks us for authority, and our own directory is still ours to hand
  -- back rather than leave standing over an install nobody can update.
  --
  -- AND IT GIVES BACK EVERY SHAPE THAT IS ITS OWN (Codex round 45, B2.3v; kept
  -- when the guard went in round 46, B2.3w). Handing back one shape and leaving
  -- another one carrying this same identity would leave a lock standing in this
  -- acquisition's name over an install it has finished with, and the next
  -- launch would have to prove this instance dead before it could update. One
  -- claim is one artifact again, so the list has one entry on an ordinary
  -- launch; the rule is what is plural, not the claim.
  local artifacts = Updater._lock_artifacts_of(path, mine)
  if #artifacts > 0 then
    for _, artifact in ipairs(artifacts) do
      Updater._lock_clear(path, artifact)
    end
  else
    Updater._lock_claim_clear(path)
  end
  Updater._apply_lock_held = false
  Updater._apply_lock_token = nil
  -- `_apply_lock_revoked` is deliberately NOT cleared here. Handing the lock
  -- back is not the same as being entitled to mutate again, and only a fresh
  -- successful acquisition is.
end

function Updater.journal_path()
  return tmp.update_journal
end

-- WHERE A DOWNLOAD WAITS, AND WHOSE IT IS (Codex round 42, B2.3s blocker 2).
-- =============================================================================
-- Staging used to be one fixed name per destination, `<dest>.new`, shared by
-- every instance on the install and fenced by nothing after the lock was taken.
-- That was the second half of the round-42 finding and it is worse than the
-- first, because the writer that matters here is not even ours to check: the
-- batch download is a DETACHED curl process pointed at those paths by a config
-- file, and a detached process cannot ask whether its parent still holds a
-- lock. A downloader deposed mid-download had curl writing into the new owner's
-- staging, and its own cleanup deleting it.
--
-- So the name carries the acquisition that made it. A downloader can only ever
-- write into, verify, consume and clean the staging of the acquisition it is
-- running under, and curl needs no check at all because it is physically unable
-- to be pointed anywhere else: the only paths in its config are this
-- acquisition's. Two instances staging the same file at the same instant are
-- writing two different files.
--
-- The stamp travels IN THE JOURNAL (`staging`), because the transaction that
-- consumes the staging can be finished by a launch that comes after the process
-- that staged it. A record with no stamp is a pre-B2.3s one, or a
-- pre-restructure handoff, and its staging is the bare sibling name its writer
-- used; that is why the tag is optional here rather than required.
--
-- Orphans are answered by AUTHORITY rather than by age. The apply lock is held
-- for exactly as long as an acquisition's staging is alive, so a lock standing
-- on this install means somebody's staging is in use and none of it is a
-- stranger's to remove; with no lock standing, no downloader exists and what is
-- left belongs to nobody. That is guard 5 on the startup sweep, and it is the
-- same authority the reclaim rule rests on, one step removed.
function Updater.staging_tag_ok(tag)
  return type(tag) == "string" and tag:match("^inst_[%w%-_]+~%d+$") ~= nil
end

-- Which instance staged it, read back out of the tag. `~` stands where the
-- lock's `#` stands, outside the instance suffix's character class for exactly
-- the same reason: so the owner can still be separated from the acquisition.
function Updater.staging_tag_owner(tag)
  if not Updater.staging_tag_ok(tag) then return nil end
  return tag:match("^(inst_[%w%-_]+)~%d+$")
end

-- This acquisition's identity, spelled for a filename. Nil when there is no
-- acquisition to name, which is the honest answer for a caller that has not
-- taken the lock: it stages into the bare name and is refused everything else.
function Updater.staging_tag(token)
  local tag = tostring(token or Updater._apply_lock_token or ""):gsub("#", "~")
  if Updater.staging_tag_ok(tag) then return tag end
  return nil
end

function Updater.staging_path(dest, tag)
  if Updater.staging_tag_ok(tag) then
    return tostring(dest) .. ".new." .. tag
  end
  return tostring(dest) .. ".new"
end

-- One entry's staged copy, resolved against the root its journal's writer used
-- AND against the acquisition that staged it. Every reader of a staged file in
-- the recovery walk comes through here, so none of them can disagree about
-- which transaction's download it is looking at.
function Updater.journal_staged_path(j, jf)
  return Updater.staging_path(Updater.journal_entry_path(j, jf),
    type(j) == "table" and j.staging or nil)
end

-- ARE COMPETING JOURNAL WRITERS EXCLUDED RIGHT NOW (Codex round 40, B2.3q).
-- =============================================================================
-- Every mutation of the journal in this body happens while the exclusive apply
-- lock is held: download_start takes it before any staging or journal write and
-- keeps it through the whole download/verify/apply pipeline, and since B2.3q
-- resolve_journal_at_startup takes it around the whole of the recovery walk,
-- which is the other writer. So a lane that asks this and gets true knows that
-- no other instance can write a journal underneath it, and one that gets false
-- knows only that it cannot say what is happening to the files it is looking
-- at.
--
-- The quarantine movers ask it because a rename is not a compare-and-swap.
-- Reading a record, deciding it may be moved, and moving it are three moments,
-- and the primitives available here cannot make the last two into one. Mutual
-- exclusion is what this filesystem does offer, and holding it across the whole
-- classify-to-rename interval is the same guarantee by a different road.
--
-- HOLDING IT IS A FACT ABOUT THE DISK, NOT ABOUT OUR MEMORY (Codex round 41,
-- B2.3r). B2.3q answered this with the in-process flag alone, and the flag
-- cannot see the one event that matters: liveness expires after fifteen
-- seconds, the acquisition reclaims a lock whose owner looks dead, and the
-- owner that looked dead was only asleep. It wakes with the flag still true and
-- goes on classifying, writing and renaming beside the instance that took the
-- lock from it. Two processes, one recovery record, both certain they are
-- alone.
--
-- So the question is asked of the lock. This acquisition minted an identity,
-- the lock is carrying it, and every mutation re-reads the lock and requires it
-- to still say so. A lock that is gone, emptied, or carrying another
-- acquisition's identity is the same answer: not ours, and never ours again on
-- this acquisition (Updater._apply_lock_revoke).
--
-- COST, deliberately paid. One small file read per mutation. The mutations
-- guarded here are journal writes, journal deletions, adoptions and renames on
-- a recovery or apply path: a handful per transaction, none of them per tick,
-- and the thing being bought is that a deposed process cannot touch the new
-- owner's record.
--
-- THE MARKER REFRESH IN FRONT OF IT is the other half, and it is what keeps an
-- honest walk from being deposed at all. The live marker is written once at
-- startup and refreshed every frame by the main loop; the recovery walk runs
-- BEFORE that loop exists, so a walk lasting longer than the staleness bound
-- used to age out while it was working. Refreshing here, at every point that is
-- about to mutate, means a walk that is running stays live for as long as it
-- keeps running. It cannot close the window on its own, because a suspended
-- machine outlasts any refresh, and it does not have to: a suspended process
-- executes nothing between one instruction and the next, and the fence below is
-- what meets it when it wakes.
function Updater.journal_writers_excluded()
  if Updater._apply_lock_revoked == true then return false end
  if Updater._apply_lock_held ~= true then return false end
  -- Said before the lock is asked about, because the only reason another
  -- instance would take this lock is that this process looked dead.
  RA.write_temp_live_marker()
  local mine = Updater._apply_lock_token
  if type(mine) ~= "string" or mine == "" then
    Updater._apply_lock_revoke("this acquisition minted no identity")
    return false
  end
  local on_disk = Updater._lock_identity(tmp.update_lock)
  if on_disk ~= mine then
    Updater._apply_lock_revoke("the lock now says " ..
      tostring(on_disk or "nothing at all") .. " and this acquisition is "
      .. tostring(mine))
    return false
  end
  return true
end

-- LOSING THE LOCK IS PERMANENT FOR THE HOLDER THAT LOST IT (Codex round 41,
-- B2.3r). Not "until the lock frees": a walk deposed halfway through classified
-- the disk before the theft, and every decision it is holding is a statement
-- about an install another instance has been working on since. So the flag goes
-- down, the identity goes, and the revocation stands until a fresh acquisition
-- mints a new one. Callers do not retry inline; they end, and the launch after
-- this one (or the instance that took the lock) resolves what is on disk with
-- the machinery that already resolves an interrupted transaction.
function Updater._apply_lock_revoke(reason)
  if Updater._apply_lock_revoked == true then return end
  Updater._apply_lock_revoked = true
  Updater._apply_lock_held = false
  Updater._apply_lock_token = nil
  Log.line("UPDATE", "apply lock: this process no longer holds the exclusive "
    .. "apply lock it took (" .. tostring(reason) .. "); nothing further may "
    .. "be written, moved or removed on this acquisition.")
end

-- Which root a journal's names belong to, and why the journal has to say.
-- =============================================================================
-- The journal lives at Data/Temp/update_journal.json under the PACKAGE root,
-- which is the same absolute path before and after the restructure: Data/ did
-- not move. So the new body can find, and must correctly interpret, a journal
-- a pre-restructure body left behind. Their names mean different things.
--
-- A pre-restructure body resolved manifest names against its own directory,
-- which was the package root, and that is what release N's handoff manifest
-- is written for: `ReaAssist.lua` there is the launcher at the package root
-- and `App/ReaAssist.lua` is the body. This body resolves manifest names
-- under App/. Hand this body a pre-restructure journal and read its names
-- the new way and both halves go wrong at once: `App/ReaAssist.lua` becomes
-- App/App/ReaAssist.lua, and the launcher name `ReaAssist.lua` is taken for
-- the body. Recovery would then hunt staging that is not there, conclude the
-- entry is a fresh add, and delete a destination it never installed. Section
-- 3b, migration rule 1.
--
-- The discriminator is the schema number, and it is exact rather than
-- heuristic:
--
--   schema 1  the only writer is a pre-restructure body, which had no App/
--             to write and no `root` field to write it in. Names are
--             PACKAGE-relative.
--   schema 2  written only here, only ever with root = "app". Names are
--             APP-relative.
--
-- It cannot misfire in either direction because no version of this file ever
-- wrote the other one's stamp: a schema-1 journal carrying a `root` field, or
-- a schema-2 journal without root = "app", is not a shape anything shipped
-- produces, so journal_read refuses it outright and startup recovery disposes
-- of it rather than guessing. Guessing is the one thing that is not available
-- here, because both wrong answers mutate files under a root their journal
-- never described.
--
-- On a flat install the two roots are the same directory, so a schema-1
-- journal resolves exactly where its writer meant either way; the
-- distinction only starts to matter once the launcher-replacement boundary
-- has been crossed, which is precisely when a handoff journal can exist.
function Updater.journal_root_dir(j)
  if type(j) == "table" and j.schema == 2 then return RA.APP_DIR end
  return RA.PACKAGE_DIR
end

-- Resolve one journal entry's name against the root its writer used.
function Updater.journal_path_for(j, filename)
  return Updater.name_under(Updater.journal_root_dir(j), filename)
end

-- Resolve one journal ENTRY, which is not always the same question.
--
-- A schema-2 journal is App-relative, and that is still true of every entry it
-- describes except the two launchers. Those live at the package root and their
-- names collide with body names by design: `ReaAssist.lua` under App/ is the
-- body and `ReaAssist.lua` at the package root is the launcher (section 3b),
-- so the entry has to SAY which, and it says it with root = "package".
--
-- The say-so is bounded by journal_valid, which accepts that field only on a
-- schema-2 entry and only when the name is one of the two launcher paths. An
-- entry can therefore name its way to the package root and nowhere else, and
-- an entry with no root field resolves exactly as it always did.
function Updater.journal_entry_path(j, jf)
  if type(jf) == "table" then
    if jf.root == "package" then
      return Updater.name_under(RA.PACKAGE_DIR, jf.name)
    end
    return Updater.journal_path_for(j, jf.name)
  end
  return Updater.journal_path_for(j, jf)
end

-- Every value the two enumerated journal fields can hold, as safe-lists
-- rather than deny-lists. Work package A closed three findings that all came
-- from reasoning about states nobody had enumerated, so these are written out
-- from the writers rather than inferred: `phase` is set in exactly three
-- places (apply_start writes "applying", _apply_finish writes "committed",
-- and both rollback markers write "rolling_back"), and `status` in exactly
-- four (apply_start writes "pending", the per-swap write and both recovery
-- reclassifications write "applied", the runtime rollback writes
-- "rolled_back", and the FOUR package-root ownership fences write "skipped").
-- A pre-restructure body wrote the first three.
--
-- "skipped" is new in B2.3b and means one exact thing: THIS BODY MAY NOT WRITE
-- THIS PACKAGE-ROOT DESTINATION, SO IT WAS LEFT EXACTLY AS IT IS. It is not
-- "failed" and not "pending" -- the transaction is fine and there is no work
-- outstanding for that entry -- and the difference matters to both recovery
-- directions, which is why it is a status of its own rather than a reused one.
-- Reusing "pending" would have recovery roll it forward, and reusing "applied"
-- would have a rollback delete a file this body never wrote.
--
-- FOUR fences write it since round 26, not two, and the widening is deliberate.
-- The forward direction's two (the live swap, the recovery roll-forward) reach
-- it before any backup was taken. The backward direction's two (the runtime
-- rollback, the recovery rollback completion) reach it AFTER a swap already
-- landed, when ownership changed between the backup and the undo; there the
-- meaning is that the launcher on disk is no longer this body's to put back, so
-- the .bak is dropped instead of restored. Both origins want precisely the same
-- thing from every later walk -- leave the destination alone, drop the
-- sidecars -- so they are one status rather than two that behave identically.
-- What differs between them is only what the USER is told, and that rides on
-- skip_reason / skip_detail below rather than on the status.
--
-- The two backward fences write it only on a CONFIRMED owner (round 27), and
-- only once the write has landed. Writing it is what makes the .bak
-- disposable, so an unconfirmed answer must not produce one: an entry the
-- backward direction could not get an answer about is left applied, with its
-- backup, for a later walk to ask about again. That is not a skip and is not
-- recorded as one.
--
-- skip_reason and skip_detail are the reason, persisted. Without them a skip
-- recorded by a session that then crashed is a decision nobody can explain: the
-- launch that finishes the transaction knows a launcher was left alone and
-- cannot say why, and the advisory that ratified judgement 2 made universal
-- goes missing on exactly the path that most needs it. They are written with
-- the status, permitted only with it, and read only to build that message.
--
-- skip_reason holds the advisory key rather than the raw ownership state, and
-- that is the point: the state alone cannot say which DIRECTION the fence was
-- facing, and the two read completely differently to a user ("ReaAssist did not
-- update this action" against "ReaAssist did not put this action back"). A
-- journal kept for a retry is re-read by a later launch that was not there when
-- the decision was made, so the direction has to be on the entry or it is lost.
--
-- FIVE, not six, and the missing one is the point (Codex round 27). The
-- forward direction skips on all three refusing states, because not writing a
-- file costs nothing and there is no backup in play yet. The backward direction
-- may only ever record a skip it has CONFIRMED, because recording one is what
-- authorizes dropping the user's backup. An unknown answer coming back is not a
-- skip at all: the entry stays as it was, the sidecars stay, and the walk comes
-- back to it, so there is nothing to persist and `superseded_unknown` is a
-- reason no fence can produce.
Updater.JOURNAL_SKIP_REASONS = {
  skipped_reapack    = true, skipped_foreign    = true,
  skipped_unknown    = true, superseded_reapack = true,
  superseded_foreign = true,
}
Updater.JOURNAL_PHASES = {
  applying = true, rolling_back = true, committed = true,
}
Updater.JOURNAL_STATUSES = {
  pending = true, applied = true, rolled_back = true, skipped = true,
}

-- The two vocabularies are not independent, and validating them separately
-- accepts combinations no writer can produce (Codex round 18). Enumerated from
-- the same writers, in the order a transaction moves through them:
--
--   applying      pending, applied, skipped.
--                 apply_start stamps every entry pending under this phase and
--                 apply_tick flips them to applied one swap at a time, so a
--                 half-applied batch is exactly this mixture. skipped joins it
--                 because the ownership fence writes that status mid-walk,
--                 under this phase, and recovery has to be able to read the
--                 journal it wrote. rolled_back cannot appear: both rollback
--                 paths write the rolling_back phase marker BEFORE touching
--                 any entry, precisely so a crash between the two cannot be
--                 read as an apply.
--   rolling_back  pending, applied, rolled_back, skipped.
--                 The runtime rollback walks applied entries newest-first,
--                 flipping each to rolled_back before its dest is touched, so
--                 an interrupted rollback holds all three at once. Entries the
--                 apply never reached stay pending, and one it declined stays
--                 skipped: a rollback has nothing to undo for a swap that
--                 never happened. Since round 26 a rollback can also PRODUCE
--                 skipped under this phase, when a launcher it applied stopped
--                 being this body's to put back before the undo reached it.
--   committed     applied and skipped, and nothing else.
--                 _apply_finish writes this phase only after apply_tick has
--                 walked past the last queued file, which means every entry is
--                 already applied or was skipped. A committed journal with a
--                 pending entry is the shape that matters most here: the
--                 committed branch of recovery deletes every entry's .bak AND
--                 its .new, so a pending entry reaching it loses both the
--                 previous version and the staged replacement, and recovery
--                 then reports the transaction finished and lets the launch
--                 continue. Nothing ever wrote that combination, so nothing is
--                 lost by refusing it. A skipped entry reaching it loses only
--                 the staged copy it no longer has a use for.
Updater.JOURNAL_PHASE_STATUSES = {
  applying     = { pending = true, applied = true, skipped = true },
  rolling_back = { pending = true, applied = true, rolled_back = true,
                   skipped = true },
  committed    = { applied = true, skipped = true },
}

-- Every field either writer puts in a journal, and nothing else. Written out
-- from the writers the same way the two vocabularies above are, and refused
-- the same way: a key nobody wrote is a journal this body did not produce, and
-- the one function that reads these files renames over installed code on their
-- say-so. `root` is schema 2's alone and `quarantine_token` is too; both are
-- checked as pairs below rather than by presence here.
Updater.JOURNAL_FIELDS = {
  schema = true, root = true, instance = true, target_version = true,
  phase = true, files = true, quarantine_token = true, staging = true,
}
-- `root` is the entry-level counterpart of the journal-level one: schema 2's
-- alone, permitted only on the two launcher names, and checked as a pair with
-- both below rather than by presence here.
-- skip_reason and skip_detail join them as the skip's persisted reason, checked
-- as a pair with the status below rather than by presence here.
-- `dest_existed` is schema 2's alone as well, for the same reason: it is
-- apply_start's pre-mutation observation of the destination, and the body that
-- wrote schema 1 had neither the field nor the fence that reads it.
Updater.JOURNAL_ENTRY_FIELDS = {
  name = true, sha256 = true, status = true, bak_existed = true, root = true,
  skip_reason = true, skip_detail = true, dest_existed = true,
}

-- Checksum shape. 64 hex digits, which is the only length a SHA-256 hex
-- digest has. Case is NOT part of the shape: every site that consumes a
-- recorded hash compares it with `:lower()` applied (the SHA diff, the batch
-- verifier, the staged verifier and recovery's own file_hash_ok), so an
-- uppercase digest is a shape production already accepts and recovers from
-- correctly. Refusing it here would fail a journal closed over a difference
-- that changes nothing, and failing closed costs the user their recovery.
function Updater.journal_sha_ok(sha)
  if type(sha) ~= "string" then return false end
  return #sha == 64 and sha:match("^%x+$") ~= nil
end

-- The four answers to "is the file at this destination still the one this
-- transaction put there".
Updater.DEST_OURS         = "ours"
Updater.DEST_ABSENT       = "absent"
Updater.DEST_STRANGER     = "stranger"
Updater.DEST_UNVERIFIABLE = "unverifiable"

-- THE ONE QUESTION EVERY UNDO AND EVERY CLEANUP HAS TO ASK FIRST (Codex round
-- 34, B2.3k blocker 1).
--
-- Rounds 30 and 33 closed the two directions a destination can DISAGREE with
-- the record before this transaction touched it. The direction neither of them
-- reaches is the one where the record is right and the disk moved AFTERWARDS: a
-- file this transaction landed, replaced by something else while the recovery
-- state was still outstanding. Every path that undoes or cleans up reads that
-- destination as its own work, because its own record says it wrote there, and
-- undoing our own write is what a rollback is for. A to B and back to A, one
-- layer below the swap, and what goes is a file nothing in the record has ever
-- seen.
--
-- The record carries the payload hash for every entry, so the question has an
-- exact answer rather than a guess, and it is asked immediately before the act
-- rather than remembered from earlier.
--
-- FOUR ANSWERS, AND THE LAST TWO ARE NOT THE SAME THING. "ours" is a positive
-- finding and the only one that permits a removal. "absent" is the destination
-- not being there at all, which is nothing to protect and nothing to stop for.
-- "stranger" is a positive finding the other way: the file reads, it hashes,
-- and it is not what this transaction wrote. "unverifiable" is the ABSENCE of a
-- finding -- a destination that cannot be read, an entry with no usable hash, a
-- host with no hashing at all -- and a file that could not be read is not proof
-- of a stranger, exactly as the recovery arc has always held that a locked file
-- never counts as verified. It is not proof of ours either, so nothing acts on
-- it: callers hold that entry and come back to it on the next launch.
function Updater.applied_dest_verdict(path, sha)
  if reaper.file_exists and not reaper.file_exists(path) then
    return Updater.DEST_ABSENT
  end
  -- No usable hash means no question can be asked, which is not the same as
  -- an answer of no. Fail closed.
  if not Updater.journal_sha_ok(sha) then
    return Updater.DEST_UNVERIFIABLE
  end
  if type(sha256_hash) ~= "function" then
    return Updater.DEST_UNVERIFIABLE
  end
  local f = io.open(path, "rb")
  -- A lock, a permissions refusal, or (on a host with no file_exists) a file
  -- that is simply not there. None of the three is a stranger.
  if not f then return Updater.DEST_UNVERIFIABLE end
  local content = f:read("*a")
  f:close()
  if type(content) ~= "string" then return Updater.DEST_UNVERIFIABLE end
  if sha256_hash(content) == tostring(sha):lower() then
    return Updater.DEST_OURS
  end
  return Updater.DEST_STRANGER
end

-- Whether a decoded journal is one this body may WALK. Recovery is the one
-- function in the updater that mutates live files on a file's say-so, and it
-- resolves names, joins them onto a root and renames over them, so every
-- field it reads is validated here before any entry is walked. There is no
-- partial acceptance: a journal that fails any check below is INVALID as a
-- whole, because the fields cross-reference (a name says where to write, a
-- status says which direction, a checksum says whether the staged copy is
-- usable) and half-trusting one of them is how a wrong root or a wrong
-- direction gets chosen.
--
-- Returns true, or false plus a short reason for the log.
function Updater.journal_valid(data)
  if type(data) ~= "table" then return false, "not a table" end
  -- Schema and root are checked as a pair, and only the two combinations
  -- something actually shipped are accepted (see journal_root_dir): a
  -- pre-restructure schema-1 journal, which never carried a root field,
  -- and our own schema-2 journal, which always carries root = "app".
  if data.schema == 1 then
    if data.root ~= nil then return false, "schema 1 carrying a root field" end
  elseif data.schema == 2 then
    if data.root ~= "app" then
      return false, "schema 2 whose root is not \"app\""
    end
  else
    return false, "unsupported schema " .. tostring(data.schema)
  end
  for key in pairs(data) do
    if not Updater.JOURNAL_FIELDS[key] then
      return false, "unknown journal field " .. tostring(key)
    end
  end
  -- The repair identity, optional and schema 2's alone. A pre-restructure
  -- body never wrote it, so a schema-1 journal carrying one is not a shape
  -- anything shipped, exactly like a schema-1 journal carrying a root. When
  -- it is there it is compared against the standing quarantine's token, so
  -- its shape is checked here rather than at the comparison.
  if data.quarantine_token ~= nil then
    if data.schema ~= 2 then
      return false, "schema 1 carrying a quarantine_token"
    end
    if not Updater.quarantine_token_ok(data.quarantine_token) then
      return false, "malformed quarantine_token"
    end
  end
  -- The acquisition that staged this transaction's downloads (Codex round 42,
  -- B2.3s). Schema 2's alone, for the same reason the root field is: a
  -- pre-restructure body staged into the bare sibling name and had no
  -- acquisition identity to stamp. Checked for shape here rather than where it
  -- is used, because it is joined onto a destination path and renamed over.
  if data.staging ~= nil then
    if data.schema ~= 2 then
      return false, "schema 1 carrying a staging tag"
    end
    if not Updater.staging_tag_ok(data.staging) then
      return false, "malformed staging tag " .. tostring(data.staging)
    end
  end
  if type(data.instance) ~= "string" or data.instance == "" then
    return false, "instance is not a non-empty string"
  end
  if type(data.phase) ~= "string" or not Updater.JOURNAL_PHASES[data.phase] then
    return false, "phase is not one of ours: " .. tostring(data.phase)
  end
  if data.target_version ~= nil and type(data.target_version) ~= "string" then
    return false, "target_version is not a string"
  end
  if type(data.files) ~= "table" then return false, "files is not a table" end
  -- A JSON object decoded where an array was expected has a length of zero
  -- and a non-zero pair count. Recovery walks with ipairs, so such a journal
  -- would silently look empty and be resolved as a no-op transaction.
  local pair_count = 0
  for _ in pairs(data.files) do pair_count = pair_count + 1 end
  if pair_count ~= #data.files then
    return false, "files is not a plain array"
  end
  local seen = {}
  for _, jf in ipairs(data.files) do
    if type(jf) ~= "table" then return false, "an entry is not a table" end
    for key in pairs(jf) do
      if not Updater.JOURNAL_ENTRY_FIELDS[key] then
        return false, "unknown entry field " .. tostring(key)
      end
    end
    -- Both schemas, one rule. A schema-1 name is package-relative and a
    -- schema-2 name is App-relative, but either is joined onto a root and
    -- renamed over, so traversal, absolute paths, backslashes, hidden
    -- segments, reserved device names and unknown extensions are all refused
    -- here exactly as they are for a manifest name.
    if type(jf.name) ~= "string" or not Updater.is_safe_filename(jf.name) then
      return false, "unsafe entry name " .. tostring(jf.name)
    end
    -- The package-root escape, and the whole of it. An entry may resolve
    -- outside App/ only by saying root = "package", only under schema 2 (a
    -- pre-restructure body wrote neither the field nor a two-root install), and
    -- only for one of the two launcher paths. There is nothing else at that
    -- root this body writes, so an allowlist of two is the exact permission,
    -- and it is what makes a package-rooted entry structurally incapable of
    -- naming an App-relative file (section 3b).
    if jf.root ~= nil then
      if data.schema ~= 2 then
        return false, "schema 1 entry carrying a root field: " .. jf.name
      end
      if jf.root ~= "package" then
        return false, "entry root is not \"package\" for " .. jf.name
      end
      if not Updater.is_launcher_name(jf.name) then
        return false, "package-rooted entry names " .. jf.name
          .. ", which is not one of the two launcher paths"
      end
    end
    -- Case-insensitively, because the destination is. Windows folds
    -- `Resources/UI.lua` and `Resources/ui.lua` onto one file, so two entries
    -- differing only in case are two entries for one destination on the
    -- platform most of these installs run on, and the ambiguity below is
    -- exactly the same. Refusing a case-only pair costs nothing on a
    -- case-sensitive filesystem either: no manifest ships one.
    --
    -- Qualified by root, because the name alone stopped identifying the
    -- destination: `ReaAssist.lua` App-relative and `ReaAssist.lua` at the
    -- package root are two files, and a transaction that replaces the body and
    -- its launcher in one go legitimately holds both. Two entries sharing a
    -- name AND a root are still the same destination twice and still refused.
    local key = (jf.root or "app") .. "\0" .. jf.name:lower()
    if seen[key] then
      -- Two entries for one destination make the .bak and .new state
      -- ambiguous: the second walk sees the first walk's consumed backup and
      -- reads it as "already restored".
      return false, "duplicate entry name " .. jf.name
    end
    seen[key] = true
    if not Updater.journal_sha_ok(jf.sha256) then
      return false, "malformed checksum for " .. jf.name
    end
    if type(jf.status) ~= "string"
        or not Updater.JOURNAL_STATUSES[jf.status] then
      return false, "status is not one of ours for " .. jf.name .. ": "
        .. tostring(jf.status)
    end
    local allowed = Updater.JOURNAL_PHASE_STATUSES[data.phase]
    if not (allowed and allowed[jf.status]) then
      return false, "status " .. jf.status .. " cannot appear in phase "
        .. data.phase .. " for " .. jf.name
    end
    -- Only a package-rooted entry can be skipped, because only one thing ever
    -- writes that status: the ownership fence in front of a launcher swap. A
    -- body entry carrying it would tell recovery to leave a file alone that
    -- nothing else is going to finish, which is a silently stale install, so
    -- it is refused here rather than honoured.
    if jf.status == "skipped" and jf.root ~= "package" then
      return false, "skipped is only for a package-rooted entry, not "
        .. jf.name
    end
    -- The skip's reason travels with the skip and only with it. It is what the
    -- launch that finishes an interrupted transaction says to the user about a
    -- launcher it left alone, so an entry carrying it under any other status is
    -- a journal nothing here wrote, and a key outside the six a fence can
    -- produce would describe a decision that cannot have happened.
    if jf.skip_reason ~= nil or jf.skip_detail ~= nil then
      if jf.status ~= "skipped" then
        return false, "skip_reason/skip_detail on a " .. tostring(jf.status)
          .. " entry: " .. jf.name
      end
      if not Updater.JOURNAL_SKIP_REASONS[jf.skip_reason] then
        return false, "skip_reason is not one a fence can produce for "
          .. jf.name .. ": " .. tostring(jf.skip_reason)
      end
      if jf.skip_detail ~= nil and type(jf.skip_detail) ~= "string" then
        return false, "skip_detail is not a string for " .. jf.name
      end
    end
    -- bak_existed says which rollback an entry gets: true restores the .bak,
    -- false deletes the destination because the entry was a fresh-install add
    -- and there is nothing to restore. Both rollback walks read it, so both
    -- states that a rollback can act on have to carry it. They always do:
    -- apply_tick writes status and bak_existed together in the same statement
    -- pair when a file lands, recovery's reclassification and roll-forward do
    -- the same, and rolled_back is only ever reached from applied. An applied
    -- entry without it is therefore not a journal anything wrote, and reading
    -- the absence as false would delete a file whose previous version is
    -- sitting in a .bak beside it.
    if jf.status == "applied" or jf.status == "rolled_back" then
      if type(jf.bak_existed) ~= "boolean" then
        return false, "bak_existed is required for " .. jf.status
          .. " entry " .. jf.name
      end
    elseif jf.bak_existed ~= nil and type(jf.bak_existed) ~= "boolean" then
      -- Pending entries may carry it or not; a non-boolean is readable as
      -- neither.
      return false, "bak_existed is not a boolean for " .. jf.name
    end
    -- dest_existed is the other boolean about the same destination, asked at
    -- the other end of the transaction: bak_existed says what the swap did, and
    -- this says what the swap found. Schema 2's alone, exactly like root.
    --
    -- Shape-checked here and REQUIRED nowhere here, which is deliberate. No
    -- part of recovery reads it: a journal without it is still one both walks
    -- can carry to completion in either direction, and refusing it at this
    -- level would turn a transaction that could have been finished into a
    -- quarantined install over a field the walk never asks for. The one reader
    -- that does ask is journal_changed_nothing, and it treats an absent
    -- observation as no proof and refuses, which puts the cost of the missing
    -- field where it belongs: one restart, rather than the user's only record.
    if jf.dest_existed ~= nil then
      if data.schema ~= 2 then
        return false, "schema 1 entry carrying a dest_existed field: "
          .. jf.name
      end
      if type(jf.dest_existed) ~= "boolean" then
        return false, "dest_existed is not a boolean for " .. jf.name
      end
    end
  end
  return true
end

-- Parse ONE journal path. Returns the journal table on success, or nil plus a
-- reason: "absent" (nothing there) or "invalid" (something is there and this
-- body must not walk it), and for "invalid" also why. The two are deliberately
-- distinguishable, because they lead to opposite startup outcomes: nothing to
-- do, versus stop.
--
-- THE RAW BYTES COME BACK LAST, on the success path only, so the reason slots
-- keep their meaning either way (Codex round 39, B2.3p). A caller that is going
-- to MOVE what it read has to be able to prove, at the moment of the move, that
-- the file at that name is still the one it classified, and the bytes every one
-- of those questions was answered out of are what that proof is made of.
function Updater.journal_parse(p)
  local f = io.open(p, "rb")
  if not f then
    -- Absent, or present and unreadable? They lead to opposite outcomes
    -- (carry on versus stop), so the same fail-closed probe the quarantine
    -- gate uses decides it here too. A journal that is on disk but locked
    -- or permission-denied describes a transaction nobody has resolved,
    -- and reading it as absent starts an ordinary session against a
    -- possibly half-swapped install -- the exact failure B2.2d closes one
    -- layer up.
    if RA.path_present(p) then return nil, "invalid", "unreadable" end
    return nil, "absent"
  end
  local raw = f:read("*a"); f:close()
  if not raw or raw == "" then return nil, "invalid", "empty file" end
  local ok_decode, data = pcall(JSON.decode, raw)
  if not ok_decode then return nil, "invalid", "decode failed" end
  local ok, why = Updater.journal_valid(data)
  if not ok then return nil, "invalid", why end
  return data, nil, nil, raw
end

-- Read the journal WITHOUT changing anything on disk: the authorization read
-- (Codex round 20, blocker 2).
--
-- Contract: this renames nothing, writes nothing and deletes nothing. It opens
-- the two journal paths for reading, parses and validates what it finds, and
-- returns it. The one filesystem call it makes that is not a read is
-- RA.path_present's rename of a path onto itself, which keeps the name, the
-- bytes and the handles and exists only to tell ENOENT from EACCES.
--
-- Returns the journal plus the path it was found at; or nil plus "invalid",
-- the path that failed and why; or nil plus "absent". Callers must test the
-- first value, because the second means different things either way.
--
-- The quarantine gate needs this. Deciding whether a journal is the repair the
-- gate authorized is a question about a file, and answering it must not change
-- that file: journal_read's adoption renamed an orphaned .tmp into the primary
-- path before any token had been accepted, so the read that was only supposed
-- to look had already moved the evidence.
function Updater.journal_peek()
  local path = Updater.journal_path()
  local data, reason, why = Updater.journal_parse(path)
  if data then return data, path end
  if reason == "invalid" then
    Log.line("UPDATE",
      "journal_read: refusing the journal at " .. tostring(path)
      .. " (" .. tostring(why) .. ")")
    return nil, "invalid", path, why
  end
  -- The .tmp sibling counts only when the primary is truly ABSENT. A
  -- present-but-invalid primary means the .tmp (if any) is a stale
  -- earlier snapshot; the caller preserves both.
  local orphan, tmp_reason, tmp_why = Updater.journal_parse(path .. ".tmp")
  if orphan then return orphan, path .. ".tmp" end
  if tmp_reason == "invalid" then
    Log.line("UPDATE",
      "journal_read: refusing the orphaned journal .tmp sibling at "
      .. tostring(path .. ".tmp") .. " (" .. tostring(tmp_why) .. ")")
    return nil, "invalid", path .. ".tmp", tmp_why
  end
  return nil, "absent"
end

-- Move an accepted orphan into the primary path.
--
-- journal_write swaps via remove-then-rename (Windows os.rename refuses to
-- clobber), so a crash between the two calls leaves ONLY
-- update_journal.json.tmp, holding a complete serialized journal. Adopting it
-- is what stops that crash window stranding recovery state.
--
-- It is a mutation, so it happens only once something has decided to act on
-- the journal it moves: the ordinary resolution path, where any valid journal
-- is walked, and the gate's path only AFTER the token matched. No-op for a
-- journal that was already at the primary path.
--
-- And it is PROVEN, not reported (Codex round 21, B2.2f fix 2). It used to
-- look at neither the primary path nor what os.rename returned, and both of
-- those blind spots are the same event: a journal arriving at the primary path
-- after the peek that authorized this one. On Windows the rename then fails,
-- os.rename refusing to clobber, and the caller walked the .tmp anyway while
-- the cleanup at the end of that walk deleted a primary nobody had vouched
-- for. On POSIX the rename would have succeeded and destroyed that primary
-- instead. So the primary is probed first and the rename is checked, and a
-- primary that is there fails the adoption: the caller peeks again and
-- authorizes what is actually on disk rather than acting on what was.
--
-- The probe is a second line of defence now rather than the only one (Codex
-- round 22, B2.2g blocker 2). The move itself refuses to clobber on both
-- platforms, so a journal arriving between the probe and the move loses the
-- race instead of being destroyed by it; the probe stays because it turns that
-- race into a clean, logged refusal one call earlier, and because it is the
-- only thing that catches a primary that is present but unmovable.
--
-- Returns true when the journal is at the primary path, including the case
-- where it already was, or false plus "primary" / "rename".
function Updater.journal_adopt(source)
  local path = Updater.journal_path()
  if type(source) ~= "string" or source == path then return true end
  -- Not while somebody else holds the lock (Codex round 41, B2.3r). An adoption
  -- renames a record onto the primary journal name, which is the name the
  -- instance holding the lock is working at. "primary" is the existing refusal
  -- for a name this call may not take, and every caller is already fail-closed
  -- on it.
  if not Updater.journal_writers_excluded() then
    Log.line("UPDATE",
      "journal_read: not adopting the orphaned journal .tmp sibling; this "
      .. "process does not hold the exclusive apply lock, so the primary "
      .. "journal name is not its to take.")
    return false, "primary"
  end
  if RA.path_present(path) then
    Log.line("UPDATE",
      "journal_read: not adopting the orphaned journal .tmp sibling; a journal "
      .. "is at " .. tostring(path) .. " that was not there when this one was "
      .. "read, so what is on disk now is not what was authorized.")
    return false, "primary"
  end
  local ok, err
  if RA.IS_WINDOWS then
    -- os.rename here is MoveFile, which fails when the destination exists.
    -- That is the no-clobber guarantee this needs, and it is atomic.
    ok, err = os.rename(source, path)
  else
    ok, err = Updater.journal_link_no_clobber(source, path)
    if ok then
      -- The link made `path` a second name for the same bytes; dropping the
      -- old name is what turns two names into a move. A removal that will not
      -- happen leaves the journal at BOTH names, which is the same leftover
      -- journal_write's own swap window can produce and is handled the same
      -- way: the peek prefers the primary, and the stale .tmp beside it is
      -- deleted with the journal when the walk resolves.
      os.remove(source)
    end
  end
  if not ok then
    Log.line("UPDATE",
      "journal_read: could not adopt the orphaned journal .tmp sibling ("
      .. tostring(err) .. "); nothing walks it.")
    return false, "rename"
  end
  Log.line("UPDATE",
    "journal_read: adopted orphaned journal .tmp sibling "
    .. "(crash between journal_write's remove and rename)")
  return true
end

-- Give `dest` to the bytes at `source` WITHOUT clobbering anything already
-- there, on macOS and Linux (Codex round 22, B2.2g blocker 2).
-- =============================================================================
-- POSIX rename(2) replaces its destination silently, so probe-then-rename is
-- not enough: a journal arriving in the window between the two calls was
-- destroyed by the rename, and the probe cannot close a window it sits on one
-- side of. Windows does not have this problem -- MoveFile refuses an existing
-- destination -- so the adoption above keeps its rename there.
--
-- link(2) is the primitive POSIX does give: it fails with EEXIST when the
-- target name exists, atomically, and `ln` without -f is exactly link(2) with
-- no unlink in front of it. So the move becomes link-then-unlink, and a
-- journal that arrives first wins the name instead of losing its bytes.
--
-- Proven by the exit code, never by looking afterwards: a link that failed
-- because the name was taken leaves a file at that name, so "is something
-- there" answers yes in both the success and the failure case and would be the
-- same blind report B2.2f removed from the caller.
--
-- macOS was measured through REAPER's ExecProcess during release-prep round
-- 204. Wrapping two independently quoted paths inside another `sh -c` quoted
-- argument made BSD ln receive the wrong argument list. Direct `/bin/ln` with
-- each path quoted separately created the hard link and returned exit 0. The
-- direct form also avoids one parser boundary. Linux uses the same executable
-- path. A filesystem that does not support hard links still fails closed, with
-- the gate standing. This blocks the main thread for the one bounded call,
-- which is why nothing but this rare orphan path uses it.
function Updater.journal_link_no_clobber(source, dest)
  local result = Updater.journal_exec("/bin/ln "
    .. Shell.sh_quote(source) .. " " .. Shell.sh_quote(dest), 5000)
  if type(result) ~= "string" then
    return false, "no answer from ln"
  end
  local code = tonumber(result:match("^%s*(%-?%d+)"))
  if code ~= 0 then
    return false, "ln refused the link (exit " .. tostring(code or "?") .. ")"
  end
  return true
end

-- The one place this lane shells out, named so a test can stand in front of it.
-- ExecProcess answers "exitcode\nstdout", or nothing at all when the process
-- could not be started, and nothing at all is a refusal here like any other.
function Updater.journal_exec(cmd, timeout_ms)
  if not (reaper and type(reaper.ExecProcess) == "function") then return nil end
  local ok, result = pcall(reaper.ExecProcess, cmd, timeout_ms or 5000)
  if not ok then return nil end
  return result
end

-- The ordinary read: peek, then adopt an orphan on the way out, because every
-- caller of this one is about to act on what it returns. Returns exactly what
-- it always did -- the journal, or nil plus "absent" / "invalid" with the
-- failing path and reason -- so the source path stays inside.
--
-- The adoption is proven here too, with the same single bounded retry the
-- gate's path uses (Codex round 21, B2.2f fix 2). An adoption that fails means
-- the disk changed since the peek, so the peek is taken again and the answer
-- is whatever is there now. In practice that second peek IS the resolution:
-- the ordinary reason an adoption fails is that a primary appeared, and a peek
-- prefers the primary, which needs no adoption at all.
--
-- A second attempt that cannot be proven either reports "invalid" naming the
-- path that would not move. That is the shape this path already has for a
-- journal it cannot resolve -- journal_parse answers the same way for one it
-- cannot read -- and every caller of this function is fail-closed on it: the
-- startup resolver preserves the file as evidence and stops the launch, the
-- two ownership fences read nil as "not ours" and mutate nothing, and
-- apply_start's foreign-journal guard stops the attempt where it stands,
-- having changed nothing, rather than writing its own journal over evidence
-- nobody has resolved (Codex round 22, B2.2g blocker 2; it did treat invalid
-- as absent until then).
function Updater.journal_read()
  for _ = 1, 2 do
    local data, source, path, why = Updater.journal_peek()
    if not data then return nil, source, path, why end
    if Updater.journal_adopt(source) then return data end
  end
  return nil, "invalid", Updater.journal_path() .. ".tmp",
    "could not be adopted into the primary journal path"
end

-- Atomically (re)write the journal: serialize to a sibling temp file,
-- then swap it in. Windows os.rename refuses to clobber, so the old
-- journal is removed first. The swap window is lossless in BOTH failure
-- modes: a crash between the remove and the rename leaves only the
-- .tmp sibling, and a FAILED final rename deliberately keeps the
-- completed .tmp on disk too. Either way journal_read adopts it and
-- the startup sweep gate treats the .tmp as a pending journal, so
-- recovery state can never be stranded and a torn journal can never be
-- produced. (Only a partial .tmp from a failed write/close is ever
-- deleted.) Returns true on success.
function Updater.journal_write(j)
  local path = Updater.journal_path()
  -- NOT UNLESS THE LOCK STILL NAMES THIS ACQUISITION (Codex round 41, B2.3r).
  -- Asked in the primitive rather than at its twelve call sites, because a
  -- fence a call site can forget is not a fence. False is the answer every one
  -- of those callers already handles, and handles by leaving the disk exactly
  -- as it found it.
  if not Updater.journal_writers_excluded() then
    Log.line("UPDATE", "journal_write: refused; this process does not hold the "
      .. "exclusive apply lock, so the record at the journal path is not its "
      .. "to write.")
    return false
  end
  local tmp_path = path .. ".tmp"
  local encoded, enc_err = JSON.encode(j, "  ")
  if not encoded then
    Log.line("UPDATE", "journal_write: encode failed: " .. tostring(enc_err))
    return false
  end
  local f, open_err = io.open(tmp_path, "wb")
  if not f then
    Log.line("UPDATE", "journal_write: open failed: " .. tostring(open_err))
    return false
  end
  local w_ok = pcall(function()
    assert(f:write(encoded))
  end)
  local c_ok = pcall(function()
    assert(f:close())
  end)
  if not w_ok or not c_ok then
    Log.line("UPDATE", "journal_write: write failed")
    os.remove(tmp_path)
    return false
  end
  os.remove(path)
  local ok_mv, mv_err = os.rename(tmp_path, path)
  if not ok_mv then
    -- Keep the completed .tmp: it is a valid journal, and the adoption
    -- path in journal_read recovers it on the next read or launch. A
    -- double swap failure (per-file write, then rolling_back marker)
    -- therefore still leaves the marker journal on disk instead of
    -- erasing both copies.
    Log.line("UPDATE", "journal_write: swap failed: " .. tostring(mv_err)
      .. " (.tmp kept for adoption)")
    return false
  end
  return true
end

-- Returns true when both names were dealt with under this acquisition's
-- authority, false when the lock is no longer ours and nothing was removed.
-- The record at the journal path is the other instance's recovery state the
-- moment the lock stops being ours, and deleting it is the one loss nothing
-- else on disk can make good (Codex round 41, B2.3r).
function Updater.journal_delete()
  if not Updater.journal_writers_excluded() then
    Log.line("UPDATE", "journal_delete: refused; this process does not hold "
      .. "the exclusive apply lock, so the record at the journal path is not "
      .. "its to remove.")
    return false
  end
  os.remove(Updater.journal_path())
  os.remove(Updater.journal_path() .. ".tmp")
  return true
end

-- Preserve a journal this body refuses to walk, instead of deleting it.
--
-- A journal that fails validation is the record of a transaction that touched
-- the user's install, and it is the only account of what that transaction was
-- doing. Deleting it (which is what this code used to do) destroys the one
-- artifact a bug report could be built from, and the install it describes is
-- exactly the install where something already went wrong.
--
-- Where it goes: Recovery/, not beside the journal in Data/Temp. Factory Reset
-- clears every file under Data/ recursively, so while the records lived there
-- a reset deleted them, and deleting the evidence was the whole of what
-- "cleared" the gate: nothing verified the install, nothing repaired it, the
-- launch simply stopped being stopped (Codex round 19, B2.2d requirement 2).
-- Recovery/ is the launcher's durable-state folder (decision 10a.2), chosen
-- for the same property this needs: Factory Reset and the Temp sweep do not
-- reach it. Nothing up there enumerates it either. The launcher touches
-- Recovery/ only by name (launcher_journal.json, launcher.lock, Body/,
-- Candidate/, Work/), and its one sweep walks Recovery/Work and removes only
-- files matching `exec.<token>.<pid>.`, so a quarantined record sitting beside
-- those names is invisible to it.
--
-- Naming: ONE quarantine slot per journal path, and the episode that owns it
-- is claimed first-come. That is deliberate over a timestamped or numbered
-- name.
-- A unique name per occurrence would let a fault that produces an invalid
-- journal on every launch fill the disk, and the FIRST invalid journal is the
-- interesting one anyway: it is the one written closest to the fault. So a
-- second invalid journal can never overwrite the first's evidence. When an
-- episode is already standing the new file is left exactly where it is,
-- unwalked, which keeps its own bytes intact too and keeps the startup sweep
-- gated on it. That check now happens once per episode, in
-- journal_quarantine_all below, before anything is created or moved: an
-- episode is the unit that owns the anchor, and asking per path would have
-- had this episode's second record refused by this episode's own first one.
--
-- Returns true when the file was moved into its slot, false when it was left
-- in place, plus the quarantine path either way.
function Updater.journal_quarantine(path, token)
  local dest = Updater.journal_quarantine_dest(path, token)
  -- The launcher creates Recovery/, but this body also runs on installs that
  -- have no launcher yet, and the folder is deliberately not created at
  -- startup. Create it here, where the one writer is. The anchor inside it is
  -- the caller's job and has already been made (or refused, which is what
  -- leaves `token` nil and sends this record to its fixed name).
  reaper.RecursiveCreateDirectory(RA.RECOVERY_DIR, 0)
  if not os.rename(path, dest) then
    Log.line("UPDATE",
      "journal quarantine: could not move " .. tostring(path) .. " aside; "
      .. "leaving it in place, unwalked.")
    return false, dest
  end
  -- The gate is up, and the rename that put it up is what gave this episode
  -- its identity. The repair the gate offers stamps that identity into its own
  -- journal, which is the only thing that lets a crash mid-repair resolve on
  -- the next launch instead of sitting behind the gate that authorized it.
  --
  -- Read back off disk rather than assumed from a rename that returned true,
  -- and read back the way a LATER launch will read it: through the scan, which
  -- is the thing that actually has to find this record again. An episode whose
  -- identity does not come back the same way it went in stands WITHOUT one
  -- (Codex round 21, B2.2f fix 1, and round 22, B2.2g blocker 1). Unstamped is
  -- the fail-closed shape: the repair still runs, only its resumability is
  -- lost, and re-offering a full pass on a healthy or half-repaired install
  -- changes nothing that a first pass did not.
  local established = Updater.quarantine_episode_establish()
  if token and established ~= token then
    Log.line("UPDATE",
      "journal quarantine: this episode's identity did not come back off "
      .. "disk, so the repair it offers writes an unstamped journal; a crash "
      .. "mid-repair re-offers that repair rather than resuming it.")
  end
  Log.line("UPDATE",
    "journal quarantine: preserved " .. tostring(path) .. " as "
    .. tostring(dest) .. " (nothing on this install was changed).")
  return true, dest
end

-- EVERY JOURNAL PATH THAT STILL HAS SOMETHING AT IT, probed rather than
-- reported (Codex round 38, B2.3o blocker 1).
--
-- Both preserving lanes move the primary and its .tmp sibling as two separate
-- renames, and one of them can land while the other is refused. What a caller
-- has to know before it promises anything is not how many records moved but
-- whether any is still LIVE, because a record left at the journal path is one
-- the offered repair's own apply_start reads (a primary) or adopts (a .tmp)
-- and then refuses. So the question is asked of the disk, in one place, and
-- both lanes build the same answer the same way.
--
-- RA.path_present is the fail-closed probe this whole lane uses: a record that
-- is there but locked or permission-denied counts as live, which is the safe
-- direction here exactly as it is everywhere else.
function Updater.journal_paths_live()
  local base = Updater.journal_path()
  local live = {}
  for _, path in ipairs({ base, base .. ".tmp" }) do
    if RA.path_present(path) then live[#live + 1] = path end
  end
  return live
end

-- Quarantine everything at the journal's two paths. Both are preserved when
-- both exist: a present-but-invalid primary makes its .tmp sibling a stale
-- earlier snapshot, and the pair of them together is what says how the write
-- that produced them was interrupted. Returns the moved and left-in-place
-- lists.
--
-- NOTHING MOVES UNLESS THE WRITERS ARE SHUT OUT (Codex round 40, B2.3q). This
-- lane does setup (a first-come check, an anchor, a mint) and then moves both
-- names on their CURRENT presence, and it cannot do otherwise: attribution is
-- unavailable to it by definition, because what it preserves is a record
-- nothing could read. Presence is only a safe basis for a move while nothing
-- can be writing, and the wider form of the check-to-rename race lived exactly
-- there: a writer finishing an initially unreadable journal during the setup
-- had its recovery state carried off by a probe that saw a file and a rename
-- that took whatever was at the name. Held exclusion is what makes the presence
-- true at the moment the rename runs, and asking here rather than trusting the
-- caller is what keeps it true if the lane ever gains a second road in.
function Updater.journal_quarantine_all()
  local base = Updater.journal_path()
  local moved, left = {}, {}
  if not Updater.journal_writers_excluded() then
    Log.line("UPDATE",
      "journal quarantine: the first-come lane was reached without the "
      .. "exclusive apply lock, so another instance could be writing at "
      .. "either journal path; nothing was preserved and nothing was moved.")
    return moved, left
  end
  -- First-come, once, across every home, and before anything is created or
  -- moved. An install that quarantined before the records moved has its
  -- evidence beside the journal, one that quarantined before B2.2h has it
  -- under a fixed name, and one that quarantined since has it behind the
  -- anchor; any of them is still the first and most interesting episode, and
  -- a new refusal must neither step over it nor add itself to it.
  --
  -- Leaving the later record where it lies is the answer for a refusal nobody
  -- has walked, which is every caller this branch has: the launch stops at the
  -- gate, no walk reads that record, and its own bytes keep themselves. A
  -- record this body HAS walked and is handing to the repair needs the other
  -- answer, because the repair's apply would be refused over it; that road is
  -- journal_quarantine_beside, which preserves it under the second head
  -- without ever asking for the standing record's name (Codex round 37,
  -- B2.3n).
  local standing = Updater.journal_quarantined()
  if standing then
    left = Updater.journal_paths_live()
    Log.line("UPDATE",
      "journal quarantine: an earlier refused journal is already preserved at "
      .. tostring(standing) .. "; leaving " .. tostring(#left)
      .. " later record(s) in place, unwalked.")
    return moved, left
  end
  -- One episode, one identity, minted before anything moves and spelled into
  -- every record this refusal preserves. Both records belong to the same
  -- interrupted write, so two identities here would mean an episode that could
  -- not say what it was called.
  --
  -- Two things have to be true before it is worth minting one, and they are
  -- different things (Codex round 23, B2.2h). The ANCHOR is what makes the
  -- record findable again, by probe, whatever any listing says. The LISTING is
  -- what makes the identity in its name readable again. Without the anchor
  -- there is nowhere for a name-carried record to go that a later launch could
  -- prove; without a listing there is nobody to read the name back. Either
  -- one missing sends the record to its fixed name under Recovery/, which is
  -- probed exactly as hard, and the episode runs identity-less: gated just the
  -- same, with an unstamped repair.
  --
  -- The check above is also what proves the anchor is EMPTY when this episode
  -- uses it. It is not there when this line is reached, so the directory
  -- created below is this episode's own and nothing can already be sitting at
  -- the name a record is about to take. That is a proof by creation rather
  -- than by an empty listing, which is the distinction the whole round is
  -- about.
  local token = nil
  if reaper and type(reaper.EnumerateFiles) == "function"
      and Updater.quarantine_anchor_create() then
    token = Updater.quarantine_token_mint()
  else
    Log.line("UPDATE",
      "journal quarantine: this install has no listable quarantine folder, so "
      .. "the record is preserved under its fixed name and this episode has "
      .. "no identity; the gate stands, and the repair it offers is not "
      .. "resumable.")
  end
  for _, path in ipairs({ base, base .. ".tmp" }) do
    if RA.path_present(path) then
      local ok, dest = Updater.journal_quarantine(path, token)
      if ok then moved[#moved + 1] = dest else left[#left + 1] = path end
    end
  end
  -- An episode that preserved nothing leaves nothing. The anchor is a gate,
  -- and a gate is for evidence: when every rename was refused the records are
  -- still at their own paths, unread, and still stopping this launch through
  -- the journal-path guard that has always watched them. An empty anchor left
  -- standing would turn a scanner holding the journal open for a moment into
  -- an install that only a full verified repair could start again. Taken away
  -- the same way the clear takes it, and if that is refused too the gate
  -- stands, which is the safe direction rather than the tidy one.
  if token and #moved == 0 and not Updater.quarantine_anchor_retire() then
    Log.line("UPDATE",
      "journal quarantine: nothing could be preserved and the empty record "
      .. "folder could not be taken away again, so the gate stands on it.")
  end
  return moved, left
end

-- PRESERVE A RECORD BESIDE EVIDENCE THAT IS ALREADY STANDING (Codex round 37,
-- B2.3n).
-- =============================================================================
-- The other half of the first-come rule, and the half that was missing. Leaving
-- a later record where it lies is right for a refusal nobody has walked: the
-- launch stops at the gate, nothing reads that record, and its bytes keep
-- themselves. It is wrong for a record this launch has walked to the end and
-- handed to the repair, because the repair's own apply_start refuses to write
-- over a live record that changed something. The gate would offer a repair, the
-- user would accept it, and the attempt would dead-end on a record that was
-- only still there out of politeness.
--
-- So the record moves, and where it moves is what keeps both rules. The
-- standing record's NAME is the thing first-come protects, and a superseded
-- record never asks for it: it goes into the same anchor under the second head,
-- with the standing episode's identity in the tail. The evidence written
-- closest to the fault is neither written over nor added to, the gate is
-- exactly as up as it was, the sweep stands down on the same anchor, and the
-- clear takes both records the same way it always took one.
--
-- WHAT ACCRUES, and why it is not the disk-filling the first-come rule refuses.
-- A new record can only appear at the journal path if something WROTE one, and
-- under a standing gate the only writer left is the repair the gate itself
-- offers: no ordinary session runs, no scheduled check runs, and no walk writes
-- a journal it is not allowed to walk. A launch that only looks preserves
-- nothing, because the record it would have preserved is already behind the
-- anchor. So the count grows by at most one small record per repair the user
-- starts and does not finish, which is a hand on a button rather than a fault
-- on a loop.
--
-- EXACTLY THE RECORDS THE CALLER PROVED, AND NOTHING AT THE OTHER NAME (Codex
-- round 39, B2.3p). This used to walk the pair itself and move whatever was at
-- either path, on the strength of a classification that had only ever opened
-- one of them. It now moves the records it is handed, each of which arrived
-- with the bytes it was attributed from, and it proves those bytes are still
-- there in the instruction before the rename.
--
-- Returns the moved and left-in-place lists, exactly as the first-come path
-- does. An empty moved list means nothing could be set aside, and the caller
-- must not claim otherwise.
function Updater.journal_quarantine_beside(plan)
  local moved, left = {}, {}
  if not Updater.journal_writers_excluded() then
    Log.line("UPDATE",
      "journal quarantine: the superseding lane was reached without the "
      .. "exclusive apply lock, so a record classified a moment ago could "
      .. "already be a different record; nothing was set aside.")
    return moved, left
  end
  local wanted = {}
  for _, state in ipairs(plan or {}) do
    if type(state) == "table" and state.state == "preserve"
        and state.excluded == true
        and type(state.path) == "string" then
      wanted[#wanted + 1] = state
    end
  end
  if #wanted == 0 then
    -- Either nothing is at the journal path, or nothing there was proven both
    -- readable and unused. Neither is a preservation, and a caller that
    -- promises one is the wall this whole arc keeps closing.
    Log.line("UPDATE",
      "journal quarantine: no record at the journal path was proven both "
      .. "readable and unused, so nothing was set aside beside the standing "
      .. "evidence.")
    return moved, left
  end
  local standing, token = Updater.journal_quarantined()
  if not standing then
    -- Nothing is standing, so there is no episode to preserve into and no
    -- name to keep clear of. The first-come path owns that record.
    Log.line("UPDATE",
      "journal quarantine: asked to preserve beside a standing episode, and "
      .. "none is standing; nothing was moved.")
    for _, state in ipairs(wanted) do left[#left + 1] = state.path end
    return moved, left
  end
  -- An episode standing on a legacy fixed-name record has no folder yet, and a
  -- superseded record belongs behind one: the anchor is what the clear renames
  -- away and what the sweep gate probes. Created and PROVEN, like everywhere
  -- else in this lane, and a host that cannot prove one keeps its record where
  -- it is rather than being told a preservation happened.
  local anchor = Updater.quarantine_anchor()
  local raised = not RA.path_present(anchor)
  if raised and not Updater.quarantine_anchor_create() then
    for _, state in ipairs(wanted) do left[#left + 1] = state.path end
    Log.line("UPDATE", string.format(
      "journal quarantine: an episode is standing at %s and this install has "
      .. "no provable folder to keep a superseded record in, so %d record(s) "
      .. "stay exactly where they are.", tostring(standing), #left))
    return moved, left
  end
  -- One supersession, one middle, spelled into both records for the reason one
  -- episode mints one identity: the primary and its .tmp sibling belong to a
  -- single interrupted write and would otherwise be unable to say so.
  local mint = Updater.quarantine_token_mint()
  for _, state in ipairs(wanted) do
    local dest = Updater.journal_superseded_dest(state.path, token, mint)
    if not Updater.journal_bytes_unchanged(state.path, state.raw) then
      -- The file at that name is no longer the record this launch read and
      -- attributed, so every answer that would authorize moving it is about
      -- something else. It stays, and the next launch reads what is there now
      -- for itself.
      left[#left + 1] = state.path
      Log.line("UPDATE",
        "journal quarantine: " .. tostring(state.path) .. " is not the record "
        .. "this launch read and attributed any more, so it is left exactly "
        .. "where it is and nothing is claimed about it.")
    -- PROBED BEFORE THE RENAME, and that probe is the whole of the
    -- no-overwrite guarantee on a POSIX host, where rename replaces what it
    -- lands on instead of refusing. Windows refuses on its own. Neither is
    -- relied on alone, because the thing on the other side of this rename is
    -- evidence.
    elseif RA.path_present(dest) or not os.rename(state.path, dest) then
      left[#left + 1] = state.path
      Log.line("UPDATE",
        "journal quarantine: could not move " .. tostring(state.path)
        .. " beside the standing evidence; it stays where it is, and the "
        .. "repair this launch would have offered cannot start over it.")
    else
      moved[#moved + 1] = dest
    end
  end
  -- Nothing landed and this call is what raised the folder, so it comes down
  -- again. An empty anchor of our own making would outlive the record it was
  -- made for and gate a later launch on nothing.
  if raised and #moved == 0 and not Updater.quarantine_anchor_retire() then
    Log.line("UPDATE",
      "journal quarantine: nothing could be preserved beside the standing "
      .. "record and the empty folder could not be taken away again.")
  end
  -- Read the episode back off disk, the way the first-come path does. Both
  -- records carry the same token, so the answer should be the one it already
  -- was; proving that rather than assuming it is what catches a supersession
  -- that cost this episode its identity.
  local established = Updater.quarantine_episode_establish()
  if token and established ~= token then
    Log.line("UPDATE",
      "journal quarantine: preserving a superseded record left this episode "
      .. "without a proven identity, so the repair it offers writes an "
      .. "unstamped journal; a crash mid-repair re-offers that repair rather "
      .. "than resuming it.")
  end
  if #moved > 0 then
    Log.line("UPDATE", string.format(
      "journal quarantine: preserved %d superseded record(s) beside the "
      .. "evidence already standing at %s, which was neither moved nor "
      .. "written over; the gate stands and the repair can start.",
      #moved, tostring(standing)))
  end
  return moved, left
end

-- WHOSE RECORD IS AT THE JOURNAL PATH, AND WHETHER THE GATE'S REPAIR MAY START
-- OVER IT (Codex round 38, B2.3o blocker 2).
-- =============================================================================
-- The standing gate outranks every journal on purpose, and exactly one journal
-- gets past it: the one the gate's own repair wrote, carrying this episode's
-- identity. Everything else leaves the gate exactly where it was. That much was
-- always right and is not what changed.
--
-- What changed is what the launch says NEXT. It offers the full verified
-- repair, and a record still lying at the journal path is one that repair's own
-- apply_start reads (a primary) or adopts (a .tmp) before it writes its own. If
-- that record changed anything, the fence refuses it at apply_unresolved, and
-- the user who did exactly what the dialog asked is back at the same gate on
-- the next launch, and the one after that. A promise into a wall, and it stood
-- one branch over from the wall B2.3n closed. The offer has to be true of the
-- state the user is actually in.
--
-- WHETHER A RECORD MAY BE SET ASIDE is a different question from whether it is
-- in the way, and it is the harder one. The move happens once, it is not
-- reversible, and what it moves may be the only account of what another process
-- is doing right now. So two things are asked in order, and nothing moves
-- unless both are answered.
--
--   CAN IT BE READ. A record this body cannot parse carries no instance field
--   and no token, so there is nothing to attribute it by and no way to ask
--   whether anybody is still using it. It stays where it is. That costs this
--   launch its repair, and that is the honest cost: the alternative is setting
--   aside a live stranger's recovery state on a shared install because this
--   launch could not open a file. A lock is one of the reasons a record will
--   not open, which is why the ending it gets asks for a reopen first.
--
--   IS ANYBODY STILL USING IT. A readable record names its writer, and the
--   live-marker question is the same one this walk already asks before it
--   touches an ordinary journal. A live owner means another instance is
--   mid-apply on this shared install, and the outcome for that already exists.
--
-- A readable record with no live owner is this install's own unfinished
-- business whatever it is stamped with, which is the rule B2.3e already
-- settled: ownership stopped being the question there too, and a dead
-- stranger's record is treated like our own because the hazard is identical.
-- Its bytes are PRESERVED rather than deleted, under a name of their own, and
-- kept until a verified repair clears the episode, so a record that turns out
-- to have belonged to some other episode is still evidence and is still named
-- to the user.
--
-- And a record the fence would PERMIT is left alone, because nothing is in the
-- way. journal_changed_nothing is the fence's own question, a transaction that
-- has changed nothing may be started over, and moving one would preserve
-- evidence of nothing at the cost of a record the next apply was entitled to
-- reuse.
--
-- ONE ANSWER PER PATH, BECAUSE THE MOVE IS PER PATH (Codex round 39, B2.3p)
-- =============================================================================
-- The two questions above were asked of ONE record and then both journal paths
-- were moved. journal_peek answers with the first valid record it finds and
-- stops, so a readable primary meant the .tmp beside it was never opened, and
-- the mover carried it off anyway. A .tmp another instance is writing right now
-- is exactly the record the live-owner question exists to protect, and it was
-- being set aside on the strength of an answer about a different file.
--
-- So each path answers for itself, out of its own bytes, and those bytes travel
-- with the answer to the mover. The two questions and the five answers are
-- unchanged; what changed is that neither of them is ever asked once and
-- applied twice.
--
-- WHAT A PAIR MEANS, and it is not the two halves added up. The primary and its
-- .tmp are the two names journal_write swaps between, so they are one writer's
-- working set rather than two independent files, and a launch that cannot
-- account for one of them cannot claim to know what is happening to the other.
-- The answers are therefore weighed in this order:
--
--   ANY PATH LIVE -> "live". Another instance is mid-apply and it is renaming
--   between exactly these two names. Nothing moves, including a sibling that
--   read as dead: that sibling is the other half of the swap that process is in
--   the middle of, and setting it aside would race the rename and buy nothing,
--   because the live path stays in the way and no repair may be promised over
--   it either way. The launch skips and the one after it settles. A proven live
--   owner also explains an unreadable sibling, which is why it is weighed
--   first: "another instance is mid-apply" is both true and retryable, where
--   the unreadable stop would send that user to support over a file somebody is
--   legitimately writing.
--
--   ANY PATH UNREADABLE, NONE LIVE -> "unreadable". A record that will not open
--   names no writer, so nobody can say whether its owner is live, and its
--   sibling inherits that ignorance for the same one-writer-two-names reason.
--   Nothing moves, nothing is offered, and the copy names what is in the way.
--   What this costs is disclosed rather than glossed: an install whose .tmp is
--   a genuinely orphaned fragment now keeps its automatic repair out of reach,
--   where the classify-one-move-both code would have swept the fragment up and
--   carried on. The exit is the ratified one for an unreadable record, which is
--   to reopen first (a lock is the reachable cause and it clears on its own)
--   and support second, and the alternative is setting aside a live stranger's
--   recovery state on a shared install because this launch could not open a
--   file.
--
--   OTHERWISE, ANY PATH THE FENCE WOULD REFUSE -> "preserve", and only those
--   paths move. A startable sibling stays exactly where it is, which is the
--   ratified answer for a record nothing is in the way of.
--
--   EVERY PRESENT PATH STARTABLE -> "startable". NOTHING AT EITHER -> "clear".
--   Both were always true and neither moves anything.
--
-- Returns the verdict, the per-path plan (an array of the states below, absent
-- paths left out), and for "live" and "unreadable" the path that decided it
-- plus, for "unreadable", why.
function Updater.gated_journal_disposition()
  local base = Updater.journal_path()
  local plan = {}
  for _, path in ipairs({ base, base .. ".tmp" }) do
    local state = Updater.journal_path_state(path)
    if state.state ~= "absent" then plan[#plan + 1] = state end
  end
  if #plan == 0 then return "clear", plan end
  for _, state in ipairs(plan) do
    if state.state == "live" then return "live", plan, state.path end
  end
  for _, state in ipairs(plan) do
    if state.state == "unreadable" then
      return "unreadable", plan, state.path, state.why
    end
  end
  for _, state in ipairs(plan) do
    if state.state == "preserve" then return "preserve", plan end
  end
  return "startable", plan
end

-- What is at ONE journal path, and whether this launch may move it. The whole
-- taxonomy above, asked of a single name, with the record and the bytes it was
-- read from carried out so the mover can prove what it is moving.
function Updater.journal_path_state(path)
  local data, reason, why, raw = Updater.journal_parse(path)
  if not data then
    if reason == "invalid" then
      return { path = path, state = "unreadable", why = why }
    end
    return { path = path, state = "absent" }
  end
  if data.instance ~= RA.instance_file_suffix()
      and RA.temp_instance_is_live(data.instance) then
    return { path = path, state = "live", record = data, raw = raw }
  end
  if Updater.journal_changed_nothing(data) then
    return { path = path, state = "startable", record = data, raw = raw }
  end
  -- WHETHER THE ANSWER WAS ARRIVED AT UNDER EXCLUSION, carried with it (Codex
  -- round 40, B2.3q). The mover already refuses to run without the lock; this
  -- is the other half of the same invariant, which is that the CLASSIFICATION
  -- justifying the move has to have happened inside the exclusion too. A
  -- verdict reached while writers were free says nothing about the file it
  -- names, however tightly the mover holds the lock afterwards, and only this
  -- state can authorize a rename.
  return { path = path, state = "preserve", record = data, raw = raw,
    excluded = Updater.journal_writers_excluded() }
end

-- EVERY LIVE JOURNAL PATH THE OFFER WOULD BE UNTRUE OVER (Codex round 38,
-- B2.3o blocker 1, narrowed by round 39).
--
-- The claim is still made on the DISK rather than on a count of renames that
-- returned true, and it is still built from the one place the pair is spelled.
-- What round 39 adds is the one exception the taxonomy proves: a path this
-- launch read for itself and found startable is a path the offered repair's own
-- apply_start is entitled to write over, so it is not in the way and its being
-- live is not a reason to promise nothing. Everything else counts, including a
-- record that arrived at a path this launch found empty, which has no plan
-- entry at all and is therefore blocking.
function Updater.journal_paths_in_the_way(plan)
  local startable = {}
  for _, state in ipairs(plan or {}) do
    if type(state) == "table" and state.state == "startable" then
      startable[tostring(state.path)] = true
    end
  end
  local blocking = {}
  for _, path in ipairs(Updater.journal_paths_live()) do
    if not startable[tostring(path)] then blocking[#blocking + 1] = path end
  end
  return blocking
end

-- THE RECORD THAT WAS CLASSIFIED IS THE RECORD THAT MOVES (Codex round 39,
-- B2.3p).
-- =============================================================================
-- Attribution and movement are two moments, and a rename moves whatever is at
-- the name in the second one. Between the two, the disposition reads a live
-- marker, the mover reads the standing episode back off disk, mints an identity
-- and may create a folder, and any of that is long enough for another process
-- to finish journal_write's swap underneath. What moved would then be a record
-- nothing had read.
--
-- So the bytes come back with the answer and are compared against the disk in
-- the instruction before the rename. What that proves is not that the file is
-- the same one in the filesystem's sense, which nothing available here can
-- express, but that the file at the name still says exactly what the record
-- this launch attributed said, and every question the attribution asked was
-- answered out of those bytes.
--
-- WHAT CLOSED THE LAST OF IT (Codex round 40, B2.3q). B2.3p left a residual and
-- called it unclosable: a rename is not a compare-and-swap, so a write landing
-- between this read and the os.rename one line later still moved a record
-- nobody classified. That reasoning was looking for the wrong primitive. There
-- is no rename-if-unchanged and holding the file open to pin it is the thing
-- that stops the rename working on Windows, both still true; but MUTUAL
-- EXCLUSION is the rename-if-unchanged this filesystem does offer, and the
-- updater already had it. Every journal writer in this body runs under the
-- exclusive apply lock, and since B2.3q the recovery walk takes that lock
-- around its whole classify-to-move interval, so there is no writer left that
-- could land in the window at all.
--
-- This comparison stays, and it is not redundant. It is what catches a record
-- that changed for a reason the lock does not cover: a hand edit, a restore
-- from a backup tool, a file the user replaced between one launch and the next.
-- A swap to byte-identical content is invisible here and is also harmless:
-- identical bytes name the same writer, the same phase and the same token, so
-- the attribution is true of whichever copy moves.
function Updater.journal_bytes_unchanged(path, raw)
  if type(raw) ~= "string" then return false end
  local f = io.open(path, "rb")
  if not f then return false end
  local now = f:read("*a")
  f:close()
  return now == raw
end

-- Where a given journal path's evidence is kept: its own filename plus
-- `.invalid`, under Recovery/, plus the episode's identity. Derived from the
-- journal's name rather than spelled out, so the homes can never end up
-- describing different files.
--
-- The name IS the identity (Codex round 22, B2.2g blocker 1)
-- =============================================================================
-- The identity used to be a file of its own, and the bottom of that design was
-- fail-open. Every lever it had was a WRITE -- write the new value, remove the
-- old one, write a marker that disowns what will not go -- and the case it
-- exists for is precisely the case where writes do not land. When all three
-- were refused, the previous episode's value stayed readable at a fixed path
-- and the next launch read it and used it. No amount of extra levers fixes
-- that, because each new one fails in the same weather as the last.
--
-- The one operation that is KNOWN to have worked is the rename below. This
-- episode exists because a record moved into Recovery/; if that move had not
-- happened there would be no gate to give an identity to. So the identity
-- rides on the rename. It is minted in memory before the move and spelled into
-- the record's own name, which makes the evidence and the identity one
-- artifact and ends the regress: there is no value anywhere for a later launch
-- to read except the name of the record it belongs to. An episode that ends
-- takes its identity with it, because clearing the record is what removes the
-- name; an identity whose record is gone is not an identity, and nothing looks
-- for one.
--
-- A nil `token` gives the fixed name, which is what the two older homes are
-- still probed for through the transition and where a record goes when this
-- install has no anchor to put one behind. Those records carry no identity, so
-- a gate standing on one runs identity-less: its repair's journal is
-- unstamped, and a crash mid-repair re-offers the repair rather than resuming
-- it.
--
-- The anchor holds the name-carried ones (Codex round 23, B2.2h)
-- =============================================================================
-- B2.2g put the identity in the record's name and left the record in
-- Recovery/, which meant finding one was a LISTING. A listing has no positive
-- success signal: reaper.EnumerateFiles answers nil for the end of the list
-- and nil for a directory it was refused, so "there are no records" and "I was
-- not allowed to look" arrive as the same value. Every consumer that read the
-- second as the first was wrong in the dangerous direction -- the startup
-- sweep deleted the .bak and .new files an invisible record was the only
-- account of, and the clear reported success and dropped the gate around it.
--
-- So the name-carried records moved INSIDE a fixed-name directory and the gate
-- became that directory's own presence, which RA.path_present answers by probe
-- and can therefore prove. Containment is the point rather than tidiness: the
-- records are behind the anchor, so clearing the anchor clears them, and
-- nothing has to be enumerated for a removal to be complete.
--
-- Measured on Windows before this was built. os.remove answers EACCES for a
-- directory whether or not it is empty, which is why the clear renames the
-- anchor away rather than removing it (and is why the fixed-name directory
-- anchor was rejected in B2.2g, when only the removal had been measured).
-- os.rename moves a directory and everything in it, and refuses with EACCES
-- while another process holds a file inside it, which is the fail-closed
-- direction. And a directory whose listing is denied by ACL still probes
-- present, still renames away, and still opens its children by name: that is
-- exactly the install the old limit described, and it now gates, clears and
-- reports honestly.
function Updater.quarantine_anchor()
  return RA.RECOVERY_DIR .. "Quarantine"
end

-- Create the anchor, and PROVE it is there before anything is told it can use
-- one. Returns true only when a later launch could find it by probe.
--
-- RecursiveCreateDirectory says nothing this can rely on, so the answer comes
-- from the probe afterwards rather than from the call. False is not a failure
-- of this lane: it means the records go to their fixed name under Recovery/,
-- which gates by probe exactly as hard, and the episode carries no identity.
-- That is the first of the layered fallbacks, and each layer fails closed.
function Updater.quarantine_anchor_create()
  if not (reaper and type(reaper.RecursiveCreateDirectory) == "function") then
    return false
  end
  pcall(reaper.RecursiveCreateDirectory, Updater.quarantine_anchor(), 0)
  return RA.path_present(Updater.quarantine_anchor())
end

-- Take the anchor away, and PROVE it went. The one thing that can bring this
-- gate down, and the only mechanism either caller uses: the clear at the end
-- of a verified repair, and an episode that turned out to preserve nothing.
--
-- By rename, because os.remove answers EACCES for a directory on Windows
-- whether or not it is empty. The rename takes everything still behind the
-- anchor with it, which is what makes the removal complete without anything
-- having been enumerated, and it is refused while another process holds a
-- record inside -- so the one thing that can stop this is the one thing that
-- should. Proven by probing the anchor afterwards rather than by what rename
-- returned.
--
-- The tombstone is emptied best-effort and then removed, which succeeds on a
-- POSIX host (remove() on an empty directory is rmdir) and is refused on
-- Windows, where an empty directory carrying a name no probe in this lane
-- asks about is left behind. None of that changes the answer: the gate came
-- down when the anchor moved.
function Updater.quarantine_anchor_retire()
  local anchor = Updater.quarantine_anchor()
  if not RA.path_present(anchor) then return true end
  local tomb = anchor .. ".cleared." .. tostring(os.time()) .. "-"
    .. tostring(math.random(0, 9999))
  if not os.rename(anchor, tomb) then return false end
  if RA.path_present(anchor) then return false end
  if reaper and type(reaper.EnumerateFiles) == "function" then
    local names = {}
    pcall(reaper.EnumerateFiles, tomb, -1)
    local idx = 0
    while true do
      local name = reaper.EnumerateFiles(tomb, idx)
      if not name then break end
      names[#names + 1] = name
      idx = idx + 1
    end
    for _, name in ipairs(names) do os.remove(tomb .. RA.SEP .. name) end
  end
  os.remove(tomb)
  return true
end

function Updater.journal_quarantine_dest(path, token)
  local name = tostring(path or ""):match("[^/\\]+$") or "update_journal.json"
  if token == nil then return RA.RECOVERY_DIR .. name .. ".invalid" end
  return Updater.quarantine_anchor() .. RA.SEP .. name .. ".invalid."
    .. tostring(token)
end

-- The fixed head of every name-carried slot for one journal path: what the
-- scan matches on, and what the startup sweep gate rebuilds for itself.
function Updater.journal_quarantine_prefix(path)
  local name = tostring(path or ""):match("[^/\\]+$") or "update_journal.json"
  return name .. ".invalid."
end

-- THE SECOND NAMESPACE BEHIND THE SAME ANCHOR (Codex round 37, B2.3n).
-- =============================================================================
-- A record this episode's own repair is about to supersede, kept as evidence
-- beside the record that is already standing rather than in place of it.
--
-- Why a second HEAD and not a second token. The token is the EPISODE's identity
-- and this record belongs to the episode that is already standing: it is the
-- journal that episode's authorized repair wrote, or one the gate refused, and
-- it is being set aside so the next repair can start. So it carries the SAME
-- token in the same place every record carries one, which keeps
-- quarantine_identity_of's answer unchanged and the next repair's journal
-- stamped. What keeps it out of the standing record's slot is the name in front
-- of that token, not the token itself.
--
-- The two heads cannot collide. The primary head ends `.invalid.` and this one
-- ends `.superseded.`, and both are built from the journal's own filename, so
-- the base journal's slots and its .tmp sibling's stay as separate as they
-- always were.
function Updater.journal_superseded_prefix(path)
  local name = tostring(path or ""):match("[^/\\]+$") or "update_journal.json"
  return name .. ".superseded."
end

-- Where a superseded record goes: the anchor, the journal's own filename, this
-- supersession's own middle, and the standing episode's identity in the place
-- every record carries it.
--
-- The middle is the CALLER's, minted once before anything moves, exactly as an
-- episode identity is: one supersession, one middle, however many records it
-- sets aside. It is not an identity of its own and nothing reads it back;
-- quarantine_token_of still reads the tail after `.invalid.`, which is the
-- episode's, because a minted middle carries no dot and so cannot be mistaken
-- for one. What it is for is a name that is not already taken, because taking
-- one would be evicting evidence.
--
-- A nil token gives a name ending `.invalid`, which is the identity-less shape:
-- an episode standing on a legacy fixed-name record has no identity to spell,
-- and a record preserved beside it carries none either.
function Updater.journal_superseded_dest(path, token, mint)
  local tail = token and ("." .. tostring(token)) or ""
  return Updater.quarantine_anchor() .. RA.SEP
    .. Updater.journal_superseded_prefix(path)
    .. tostring(mint) .. ".invalid" .. tail
end

-- The identity a slot's name carries, or nil for a legacy fixed name.
--
-- Validated exactly like the journal field of the same name: a name that does
-- not spell a token does not carry one. The token's own charset has no dot in
-- it, so the split is unambiguous however the journal itself is named.
function Updater.quarantine_token_of(path)
  local name = tostring(path or ""):match("[^/\\]+$") or ""
  local token = name:match("%.invalid%.(.+)$")
  if token and Updater.quarantine_token_ok(token) then return token end
  return nil
end

-- Every name-carried record behind the anchor, found by NAME.
--
-- A listing rather than a probe, which is the price of an identity that lives
-- in a name: nothing can test for a value it does not already know. It reads
-- directory entries and opens nothing, so every refusal this lane has been
-- proven against -- a cross-process no-sharing lock on the record, a read-only
-- attribute, permission denied on the record itself -- leaves the record's
-- name in the listing and gates exactly as hard as it did before.
--
-- What it is NOT is a way to conclude that no records exist (Codex round 23,
-- B2.2h). An empty answer here means one of two things this call cannot tell
-- apart -- the anchor is empty, or the anchor would not be listed -- so no
-- caller reads it that way. The anchor's own presence is what says whether an
-- episode is standing, and an anchor that lists empty is an episode with no
-- readable identity rather than no episode.
--
-- Started at -1, which the API documents as "invalidate cache". REAPER caches
-- a directory listing per path, and this lane reads the same directory before
-- and after a record moves into it: the establish that follows a quarantine
-- would otherwise be handed the listing taken before the rename and conclude
-- that the episode it just created has no identity. Fail-closed, but wrongly,
-- and only because of a cache.
function Updater.journal_quarantine_scan()
  local found = {}
  if not (reaper and type(reaper.EnumerateFiles) == "function") then
    return found
  end
  local anchor = Updater.quarantine_anchor()
  local base = Updater.journal_path()
  local heads, later_heads = {}, {}
  for _, journal in ipairs({ base, base .. ".tmp" }) do
    heads[#heads + 1] = Updater.journal_quarantine_prefix(journal):lower()
    later_heads[#later_heads + 1] =
      Updater.journal_superseded_prefix(journal):lower()
  end
  local later = {}
  pcall(reaper.EnumerateFiles, anchor, -1)
  local idx = 0
  while true do
    local name = reaper.EnumerateFiles(anchor, idx)
    if not name then break end
    local lower = name:lower()
    local matched = false
    for _, head in ipairs(heads) do
      -- Membership is the NAMESPACE, not the identity. Anything sitting where
      -- a record goes is treated as one, exactly as the fixed-name probe
      -- treats anything sitting at the fixed name, whatever it contains. A
      -- name whose tail does not spell a token is a record with no identity,
      -- which gates just as hard and is cleared by the same repair; refusing
      -- to see it would leave a file that blocks the sweep forever and that
      -- nothing would ever remove.
      if lower:sub(1, #head) == head then
        found[#found + 1] = anchor .. RA.SEP .. name
        matched = true
        break
      end
    end
    -- The second namespace, on the same terms (Codex round 37, B2.3n): a
    -- record this episode's own repair superseded, gating and cleared exactly
    -- like the one it stands beside.
    if not matched then
      for _, head in ipairs(later_heads) do
        if lower:sub(1, #head) == head then
          later[#later + 1] = anchor .. RA.SEP .. name
          break
        end
      end
    end
    idx = idx + 1
  end
  -- The first refusal's record leads, always. Both namespaces gate, both carry
  -- the episode's identity and both go with the same clear; what the order
  -- decides is which record the gate NAMES to the user, and that is the
  -- evidence written closest to the fault rather than one this episode's own
  -- repair set aside later.
  for _, path in ipairs(later) do found[#found + 1] = path end
  return found
end

-- The fixed-name homes that are actually on this install, asked by PROBE.
--
-- Two of them and no listing: the pre-B2.2h home under Recovery/ (where
-- Factory Reset cannot reach it) and the pre-B2.2d one beside the journal
-- itself. Both are spelled names, so both have a provable answer, and a
-- record either of them holds gates exactly as hard as one behind the anchor
-- while carrying no identity of its own.
function Updater.journal_quarantine_fixed_paths()
  local base = Updater.journal_path()
  local paths = {}
  for _, journal in ipairs({ base, base .. ".tmp" }) do
    local fixed = Updater.journal_quarantine_dest(journal)
    if RA.path_present(fixed) then paths[#paths + 1] = fixed end
  end
  for _, journal in ipairs({ base, base .. ".tmp" }) do
    local legacy = journal .. ".invalid"
    if RA.path_present(legacy) then paths[#paths + 1] = legacy end
  end
  return paths
end

-- The quarantine's identity, and the one thing a journal can say that gets it
-- past a standing gate (Codex round 19, B2.2d requirement 5).
-- =============================================================================
-- The gate outranks every journal, deliberately: a record nobody could read
-- touched this install, so no later record gets to vouch for it. That leaves
-- one hole. The repair the gate itself offers writes a journal and then swaps
-- files one rename at a time, and a crash in the middle of that leaves a
-- perfectly good journal describing a half-finished transaction that the gate
-- would refuse to walk, forever.
--
-- So the quarantine mints a token when it goes up, the record it preserves
-- carries that token in its own name, the gate-screen repair stamps the token
-- into its own journal, and a journal bearing the CURRENT token is resolved
-- before the gate decides anything. Nothing else changes: a journal with no
-- token, or with a token from an earlier quarantine episode, stays behind the
-- gate exactly as it did.
--
-- The token is an episode identity, not a secret. It only has to be different
-- from the last one, so a journal stamped for a quarantine that has already
-- been cleared cannot walk past the next one.

-- Shape, validated like every other journal field: what this mints and nothing
-- else. Bounded so a journal cannot carry an arbitrarily long string in a
-- field the gate compares, and charset-bounded so the value is safe as a
-- filename component and cannot be mistaken for a path.
function Updater.quarantine_token_ok(token)
  if type(token) ~= "string" then return false end
  if #token < 8 or #token > 128 then return false end
  return token:match("^[A-Za-z0-9_%-]+$") ~= nil
end

-- A fresh episode identity, in memory only.
--
-- Nothing is written here, which is the whole point (Codex round 22, B2.2g
-- blocker 1): this value becomes real when a record lands under a name that
-- carries it, and until then it is a candidate. Clock plus a short slice of
-- the session's own id plus a random tail. Two episodes on one install are
-- separated by a repair that cleared the first, so the clock alone would do;
-- the other two are there so it does not have to be.
--
-- Bounded hard, because this is now part of a filename and a path is a finite
-- resource: the instance id it borrows from has no length limit of its own, so
-- it is sliced, and anything that still comes out long falls back to the clock
-- alone. Every token this can produce is under 32 characters, which is what
-- the record's name grows by.
function Updater.quarantine_token_mint()
  local instance = tostring(RA.instance_file_suffix()):gsub("[^%w]", "")
  local token = string.format("q%d-%s-%04d",
    os.time(), instance:sub(1, 10), math.random(0, 9999))
  token = token:gsub("[^%w%-_]", "-")
  if not Updater.quarantine_token_ok(token) or #token > 32 then
    token = "q" .. tostring(os.time()) .. "-quarantine"
  end
  return token
end

-- The identity carried by the records standing on this install, or nil.
--
-- nil is a real answer with three causes, and they all mean the same thing to
-- every caller: this episode has no identity. Either there is no record at
-- all, or the record is a legacy fixed name from before the identity moved
-- into it, or the records disagree about which episode they belong to, which
-- is not something this is willing to guess at. An identity-less episode gates
-- exactly as hard; what it loses is resumability, because its repair's journal
-- goes out unstamped.
function Updater.quarantine_identity_of(paths)
  local token = nil
  for _, path in ipairs(paths or {}) do
    local found = Updater.quarantine_token_of(path)
    if not found then return nil end
    if token and found ~= token then return nil end
    token = found
  end
  return token
end

-- The identity PROVEN for the episode THIS process is in, or nil.
--
-- Everything that stamps or authorizes asks this one. It is set in exactly one
-- place, quarantine_episode_establish below, and that place reads the names of
-- the records that are on disk right now. Nothing else in this file assigns to
-- it, which is what makes "where could this value have come from" a question
-- with one answer.
--
-- It dies with the process on purpose. A fresh process starts with no identity
-- and re-establishes one against the gate it actually finds, so a value can
-- never be carried across a launch by anything except the record it names.
function Updater.quarantine_episode_token()
  return Updater._episode_token
end

-- Establish this process's episode identity from what is on disk, and return
-- it.
--
-- The single assignment site for _episode_token, and a re-read rather than a
-- memory: it is called when a gate goes up, when a launch finds one standing,
-- and again when one is cleared, and each time the answer is whatever the
-- records currently say. A cleared episode establishes nil, which is correct
-- and is why nothing has to remember to forget.
function Updater.quarantine_episode_establish()
  local paths = Updater.journal_quarantine_paths()
  Updater._episode_token = Updater.quarantine_identity_of(paths)
  return Updater._episode_token
end

-- The identity file this scheme replaced, and the marker that used to disown
-- it (Codex round 22, B2.2g blocker 1).
--
-- Nothing reads either one any more, so neither gates anything and neither can
-- authorize anything. They are named here only so the clear can sweep them off
-- an install that ran a body from the file-based scheme: a file called
-- update_quarantine.token sitting in Recovery/ looks like it means something,
-- and it does not.
function Updater.quarantine_legacy_identity_paths()
  return {
    RA.RECOVERY_DIR .. "update_quarantine.token",
    RA.RECOVERY_DIR .. "update_quarantine.token.stale",
  }
end

-- Every quarantine record that is actually on this install, in the order they
-- are searched. Spelled once, here, because four separate places have to agree
-- on them: the startup sweep's gate near the top of this file (which cannot
-- call into the Updater, so it rebuilds the same rule itself), the standing
-- gate in resolve_journal_at_startup, the clear below, and the gate-screen
-- repair.
--
-- Three homes, for as long as the transition lasts, and two ways of finding
-- them. A record whose name carries this episode's identity is FOUND, by
-- listing the anchor that holds it, because a name is where the identity lives
-- now and nothing can probe for a value it does not know. The two fixed-name
-- homes are PROBED exactly as they were: an install that quarantined before
-- B2.2d has its evidence beside the journal in Data/Temp, one that quarantined
-- before B2.2h has it under a fixed name in Recovery/, and either gates
-- exactly as hard as a new record while carrying no identity of its own.
--
-- A list rather than a set of names, and it can be empty, which is the change
-- callers have to know about: this used to answer "the four places a record
-- could be" and now answers "the records that are there". Empty is NOT the
-- same as "no episode is standing", and no caller may read it that way
-- (Codex round 23, B2.2h). journal_quarantined below is the one that answers
-- that question, and it asks the anchor.
function Updater.journal_quarantine_paths()
  local paths = Updater.journal_quarantine_scan()
  for _, fixed in ipairs(Updater.journal_quarantine_fixed_paths()) do
    paths[#paths + 1] = fixed
  end
  return paths
end

-- Is quarantined evidence standing? Returns the first slot found, or nil.
--
-- This is a GATE, not a report. Quarantining moves an unreadable journal out
-- of the way, and before B2.2c that was the whole of it: the next launch found
-- no journal, swept normally, and deleted the .bak and .new files the
-- quarantined record still described, while its own dialog was telling the
-- user to reopen. So the evidence outlived its subject by exactly one launch.
-- Now the evidence's presence stands in for the record it holds: the sweep
-- does not run, and startup does not continue into a session, until it is
-- cleared.
-- Fail closed on the probe too (Codex round 19, B2.2d requirement 1): the
-- question here is "is the evidence still on disk", and a record this launch
-- cannot open is still on disk. RA.path_present answers absent only for a
-- definitive ENOENT, so a locked or permission-denied slot gates exactly like
-- a readable one, and the listing that finds a name-carried record never opens
-- it at all.
--
-- And fail closed on the LISTING (Codex round 23, B2.2h). Nothing came back is
-- two answers wearing one nil -- there are no records, or this launch was not
-- allowed to look -- so it is not what decides. The anchor is. If the
-- directory the records live in is there, an episode is standing, whether or
-- not this launch can name what is behind it; the anchor itself is then the
-- record reported, and the episode has no readable identity, which is the same
-- fail-closed shape a legacy fixed-name record already had.
--
-- Returns the record and, second, the identity its name carries -- nil when
-- the standing record is a fixed name, when the records on disk disagree about
-- which episode they belong to, or when the anchor is all this launch can see.
-- Callers that only want to know whether the gate is up read the first value,
-- which is why this stays usable inside an `or` expression.
function Updater.journal_quarantined()
  local paths = Updater.journal_quarantine_paths()
  if #paths > 0 then
    return paths[1], Updater.quarantine_identity_of(paths)
  end
  local anchor = Updater.quarantine_anchor()
  if RA.path_present(anchor) then return anchor, nil end
  return nil
end

-- Clear the quarantine. Two callers, and deliberately no others:
--
--   * Updater._apply_finish, at the commit point of a full apply. That is the
--     narrowest honest signal available: a committed apply means the whole
--     download -> verify -> journal -> swap -> commit pipeline just ran to
--     completion on this install against a server manifest, under its own
--     fresh journal. Both of the updater's repair lanes end there
--     (force_reinstall and the manual check's repair flow), so a verified
--     repair is what clears the gate. The manifest-only silent repair does
--     NOT, because it applies one file and vouches for nothing else.
--   * The gate screen's own repair, through that same commit point.
--
-- Factory Reset used to be the second one, and it is not any more (Codex
-- round 19, B2.2d requirement 2). It never called this: it clears every file
-- under Data/ recursively, both slots were files in Data/Temp, and so a reset
-- deleted the evidence and the gate came down. Nothing had verified the
-- install and nothing had repaired it. That is why the records now live under
-- Recovery/, which the reset's walk does not enter: a reset with a quarantine
-- standing leaves it standing.
--
-- Nothing else in the body removes these files, and there is deliberately no
-- instruction anywhere that tells a user to move them aside by hand. The
-- launch that finds them offers the full verified repair instead.
--
-- Returns the list of records that were removed, plus the first path that
-- would not go when the episode could not be closed.
--
-- Closing the episode and removing its identity are ONE act now (Codex round
-- 22, B2.2g blocker 1). The identity is spelled in the record's own name, so
-- there is no second file to remove first, no ordering that has to hold under
-- a filesystem that says no, and no way for an identity to outlive the record
-- it belongs to: a name that is gone cannot authorize anything, and a record
-- that will not go keeps its own name and its own gate. The removal is still
-- proven rather than assumed, by probing the path afterwards, which is what
-- the round-20 finding was really about.
--
-- Every record is tried, so a stuck one does not shelter the rest, and the
-- first that would not go is what the caller names to the user.
--
-- The anchor comes down by RENAME, and that is the second half of the B2.2h
-- fix (Codex round 23). The old clear walked a listing and removed what it
-- found, so a listing that came back empty because it was refused looked
-- exactly like one that came back empty because the episode was over: the
-- clear reported success and the gate dropped around a record still sitting
-- there, openable by name. Moving the anchor aside asks nothing of a listing.
-- It takes the gate and every record behind it in one operation, and it is
-- PROVEN the way every removal in this lane is proven, by probing afterwards
-- for the thing that was supposed to be gone. Measured: os.remove cannot
-- delete a directory on Windows at all (EACCES, empty or not), a rename moves
-- one with its contents, and a rename refuses while another process holds a
-- file inside it -- so the one thing that can stop this is exactly the thing
-- that should, and it stops it in the fail-closed direction.
--
-- What is left behind is the emptied tombstone directory, because nothing
-- available here can remove a directory on Windows. It is swept of its
-- contents best-effort, it carries a name no probe in this lane asks about,
-- and it gates nothing. One per cleared episode, and an episode is a
-- catastrophe.
--
-- AND THE TOMBSTONE MAY STILL HOLD THE RECORD (Codex round 24 rider). The
-- emptying is a listing, and the install this lane was hardened for is the one
-- whose listing is refused: an anchor denied FILE_LIST_DIRECTORY keeps that
-- deny when it is renamed, so the retire's loop enumerates nothing and the
-- record travels into the tombstone with it. The gate is still correctly down
-- -- the rename was PROVEN by probing the anchor afterwards, and nothing in
-- this lane asks about the tombstone's name -- so what is retained is
-- evidence, not a hazard: it blocks no launch, authorizes nothing, and its
-- episode is over. It is swept later, best-effort, by
-- Updater.quarantine_tombstone_sweep.
function Updater.journal_quarantine_clear()
  local cleared = {}
  local stuck = nil
  local anchor = Updater.quarantine_anchor()
  if RA.path_present(anchor) then
    -- The records behind it, removed one at a time and each proven by a probe,
    -- exactly as they were before they had a folder. This is what names a
    -- stuck record to the user: the retire below can only ever report the
    -- folder, and "close whatever has this file open" is a better instruction
    -- than "close whatever has something in this folder open".
    for _, path in ipairs(Updater.journal_quarantine_scan()) do
      if os.remove(path) and not RA.path_present(path) then
        cleared[#cleared + 1] = path
      else
        stuck = stuck or path
        Log.line("UPDATE", "journal quarantine: could not clear "
          .. tostring(path) .. "; the startup gate stays up.")
      end
    end
    -- And then the anchor, which is what actually decides. A listing that came
    -- back empty because it was refused leaves the loop above with nothing to
    -- do and no way to know it; the rename takes the gate and everything the
    -- listing could not show, and the probe inside it is the proof. A record
    -- that would not go is still there, so this is refused too, and the same
    -- record is already named in `stuck`.
    if Updater.quarantine_anchor_retire() then
      if #cleared == 0 then cleared[#cleared + 1] = anchor end
    else
      stuck = stuck or anchor
      Log.line("UPDATE", "journal quarantine: could not move the preserved "
        .. "record folder at " .. tostring(anchor) .. " aside; the startup "
        .. "gate stays up.")
    end
  end
  -- The fixed-name homes, probed rather than listed, and removed one at a time
  -- exactly as they always were. Asked after the anchor so that a record still
  -- behind a stuck anchor is never picked up and deleted while its own gate is
  -- still standing.
  for _, path in ipairs(Updater.journal_quarantine_fixed_paths()) do
    if os.remove(path) and not RA.path_present(path) then
      cleared[#cleared + 1] = path
    else
      stuck = stuck or path
      Log.line("UPDATE", "journal quarantine: could not clear "
        .. tostring(path) .. "; the startup gate stays up.")
    end
  end
  -- The identity FILE the name-carried scheme replaced, swept off an install
  -- that ran a body from the older one. Best-effort on purpose: nothing reads
  -- these, so neither gates anything and neither can authorize anything, and a
  -- clear must not fail over a file that means nothing.
  for _, path in ipairs(Updater.quarantine_legacy_identity_paths()) do
    if RA.path_present(path) then os.remove(path) end
  end
  -- Re-read what the episode is now, which after a clean clear is nothing.
  Updater.quarantine_episode_establish()
  if #cleared > 0 then
    Log.line("UPDATE", string.format(
      "journal quarantine: cleared %d preserved record(s), and with them this "
      .. "episode's identity, after a committed apply; startup is no longer "
      .. "gated.", #cleared))
  end
  return cleared, stuck
end

-- The tombstone prefix: what quarantine_anchor_retire renames the anchor to,
-- minus the timestamp and the random tail that make each one unique.
function Updater.quarantine_tombstone_prefix()
  return "Quarantine.cleared."
end

-- Sweep tombstones on a later healthy launch (Codex round 24 rider).
--
-- A tombstone is an anchor whose episode is over, renamed aside by a clear
-- that proved the rename. Usually it is already empty, because the retire
-- listed it and removed what it found. On the install this lane exists for it
-- is not: a deny on FILE_LIST_DIRECTORY travels with the directory, so the
-- retire's listing came back empty and the record went into the tombstone
-- still readable by name. Once that ACL is gone the listing works, and this is
-- what notices.
--
-- Best-effort in the strict sense, and every part of that is deliberate:
--
--   * It runs only when NO gate is standing. A tombstone means an episode
--     that ended; a live episode's evidence is behind the anchor, not here,
--     and this must never be able to touch it.
--   * It removes only names in the record namespace, the same head match the
--     scan uses. Anything else in there is not ours to delete.
--   * Every removal is proven by a probe, and one that will not go is simply
--     left. There is nothing to retry and nothing to report: the file gates
--     nothing.
--   * It never blocks the launch, never sets a failure, and never tells the
--     user anything. A tombstone the user cannot see, holding a record that
--     authorizes nothing, is not a problem they have.
--   * A listing that comes back empty is not read as proof of anything --
--     that is the round-23 rule and it holds here too. It just means nothing
--     was removed this launch, which is the same outcome as an empty
--     tombstone, and neither one decides anything.
--
-- The tombstone DIRECTORY itself stays on Windows, where os.remove answers
-- EACCES for a directory whether or not it is empty. Nothing probes for it.
function Updater.quarantine_tombstone_sweep()
  if not (reaper and type(reaper.EnumerateSubdirectories) == "function"
      and type(reaper.EnumerateFiles) == "function") then
    return 0
  end
  if Updater.journal_quarantined() then return 0 end
  local head = Updater.quarantine_tombstone_prefix():lower()
  local tombs = {}
  pcall(reaper.EnumerateSubdirectories, RA.RECOVERY_DIR, -1)
  local idx = 0
  while true do
    local name = reaper.EnumerateSubdirectories(RA.RECOVERY_DIR, idx)
    if not name then break end
    if name:lower():sub(1, #head) == head then
      tombs[#tombs + 1] = RA.RECOVERY_DIR .. name
    end
    idx = idx + 1
  end
  local record_heads = {}
  local base = Updater.journal_path()
  for _, journal in ipairs({ base, base .. ".tmp" }) do
    record_heads[#record_heads + 1] =
      Updater.journal_quarantine_prefix(journal):lower()
    -- Both namespaces, because both ride into the tombstone behind the same
    -- anchor (Codex round 37, B2.3n).
    record_heads[#record_heads + 1] =
      Updater.journal_superseded_prefix(journal):lower()
  end
  local removed = 0
  for _, tomb in ipairs(tombs) do
    local victims = {}
    pcall(reaper.EnumerateFiles, tomb, -1)
    local i = 0
    while true do
      local name = reaper.EnumerateFiles(tomb, i)
      if not name then break end
      local lower = name:lower()
      for _, record_head in ipairs(record_heads) do
        if lower:sub(1, #record_head) == record_head then
          victims[#victims + 1] = tomb .. RA.SEP .. name
          break
        end
      end
      i = i + 1
    end
    for _, path in ipairs(victims) do
      if os.remove(path) and not RA.path_present(path) then
        removed = removed + 1
      end
    end
    os.remove(tomb)
  end
  if removed > 0 then
    Log.line("UPDATE", string.format(
      "journal quarantine: swept %d retained record(s) out of %d cleared "
      .. "tombstone(s); their episodes were already closed.",
      removed, #tombs))
  end
  return removed
end

-- The repair ran, and the gate is still up. Say so, loudly, before anything
-- reports success or restarts (Codex round 19, B2.2d requirement 5).
--
-- The files were repaired: the apply committed, or the verification found
-- every one of them already correct. What failed is the deletion of the
-- preserved record, and the record is what the next launch reads. Announcing
-- "Repair Complete" and restarting into a launch that is gated all over again
-- is the one outcome that would leave the user with no idea what happened, so
-- the recovery surface shows a failure with the reason, and the next launch
-- offers the same repair. Running it twice is safe: the second pass hashes
-- every file, finds nothing to change, and tries the clear again.
function Updater.quarantine_clear_failed(path)
  update.restart_after = nil
  update.restart_fired = nil
  update.state = "failed"
  -- One thing now, not two. The identity used to live beside the record and
  -- could be the one that would not go, which meant naming the wrong file sent
  -- the user to close a program that was holding something else. Since the
  -- identity is the record's own name there is only ever the record to name
  -- (Codex round 22, B2.2g blocker 1) -- or, since B2.2h, the folder holding
  -- it, which is what will not move while something has a record inside it
  -- open. Worded for both, because the user's next step is the same either
  -- way and it is exactly the right one: a rename that answers EACCES here
  -- means another process is holding the evidence.
  Updater._set_failure("quarantine_clear",
    "ReaAssist repaired the installed files, but could not remove the "
    .. "preserved update record at:\n" .. tostring(path) .. "\n\n"
    .. "That still stops ReaAssist from starting normally. Check its "
    .. "permissions, or close whatever has it open, and try again.")
  Log.line("UPDATE",
    "journal quarantine: repair finished but the record at " .. tostring(path)
    .. " could not be removed; the gate stays up and the user was told.")
end

-- The gate's repair found nothing to repair, which is an answer, not a
-- no-op (B2.2d requirement 4).
--
-- The gate stands because an update record this body could not read touched
-- the install and nothing had verified it since. A full pass over every
-- manifest entry that finds each one matching its published hash is that
-- verification. There is no apply in that case and so no _apply_finish to
-- reach the clear from, and refusing to clear here would gate the launch
-- forever for the one reason nobody would guess: the install was healthy.
--
-- Returns true when the gate came down.
function Updater.quarantine_repair_verified()
  -- Ahead of the clear, because "every file matched" is a statement about the
  -- App body and the gate has to be a statement about the install (round 20's
  -- release gate). A launcher this body is allowed to fix and has not is the
  -- one answer that keeps the record.
  local blocking, advisory = Updater.launcher_gate_state(update.manifest)
  if #blocking > 0 then
    Updater.quarantine_launcher_blocked(blocking)
    return false
  end
  local standing = select(2, Updater.journal_quarantine_clear())
    or Updater.journal_quarantined()
  if standing then
    Updater.quarantine_clear_failed(standing)
    return false
  end
  Updater.launcher_notice_set(advisory)
  S.quarantine_gate = nil
  S.quarantine_verified_clean = true
  update.applied_files = update.applied_files or {}
  update.restart_after = nil
  update.state = "done"
  Log.line("UPDATE",
    "journal quarantine: every installed file matched the current release, "
    .. "so the preserved record was cleared and the gate is down.")
  return true
end

-- The gate's repair could not check everything, which is a different answer
-- from "everything matched" (Codex round 20, blocker 1).
--
-- The clean branch used to clear the record after logging that locked files had
-- been skipped, and the repair branch would have cleared at its commit point
-- having repaired around them. Skipping is right for an ordinary background
-- repair; it is exactly wrong here. The gate stands because an update record
-- touched this install and nothing has verified it since, and a file this pass
-- could not read is the likeliest one to be what a half-finished rename left
-- behind. Clearing while naming the file nobody looked at is the one outcome
-- the gate exists to prevent.
--
-- So the pass stops here, before any apply, the record and the token stay
-- exactly where they are, and the user gets the two things that make a retry
-- actionable: which file could not be checked, and the likeliest reason. The
-- recovery surface's own button runs the same full pass again.
--
-- Stopping before the apply rather than repairing what it can is deliberate.
-- The apply would rename over the file it could not read and fail there anyway,
-- with a message about renaming rather than about the lock; and a partial
-- repair under a gate invites exactly the conclusion the gate refuses.
function Updater.quarantine_repair_incomplete(unreadable, unverifiable, elapsed)
  update.silent_manifest_repair  = false
  update._silent_manifest_manual = false
  update.restart_after = nil
  update.restart_fired = nil
  update.state = "failed"
  Updater._set_failure("quarantine_incomplete",
    Updater.quarantine_incomplete_message(unreadable, unverifiable))
  local total = #unreadable + #unverifiable
  Log.line("UPDATE", string.format(
    "journal quarantine: the full check finished in %.2fs without covering "
    .. "%d manifest entr%s (%d unreadable, %d not checkable); nothing was "
    .. "applied, the record stays, and the user was asked to retry.",
    elapsed or 0, total, total == 1 and "y" or "ies",
    #unreadable, #unverifiable))
end

-- What the recovery surface says about a check that could not finish. It names
-- the files, because "something could not be read" is not something a user can
-- act on, and the name is usually what identifies the program holding it.
function Updater.quarantine_incomplete_message(unreadable, unverifiable)
  local function listed(names)
    local lines = {}
    for i = 1, math.min(#names, 8) do
      -- Display name, so a launcher entry reads as the file the user has
      -- rather than as the qualified key the diff lists carry it under.
      lines[#lines+1] = "  " .. Updater.display_name(names[i])
    end
    if #names > 8 then
      lines[#lines+1] = string.format("  and %d more", #names - 8)
    end
    return table.concat(lines, "\n")
  end
  local parts = {
    "ReaAssist could not check every installed file, so this check cannot "
    .. "say whether the installation is complete.",
  }
  if #unreadable > 0 then
    parts[#parts+1] = (#unreadable == 1
        and "This file could not be read:"
        or  "These files could not be read:")
      .. "\n" .. listed(unreadable)
      .. "\n\nAnother program, such as antivirus, a backup tool or an open "
      .. "editor, may be holding " .. (#unreadable == 1 and "it" or "them")
      .. " open."
  end
  if #unverifiable > 0 then
    parts[#parts+1] = (#unverifiable == 1
        and "This entry in the update manifest could not be checked:"
        or  "These entries in the update manifest could not be checked:")
      .. "\n" .. listed(unverifiable)
  end
  parts[#parts+1] = "The interrupted update record has been kept and nothing "
    .. "was changed. Close anything that has these files open, then run the "
    .. "check again."
  return table.concat(parts, "\n\n")
end

-- Are both action launchers serviceable, and if not, whose problem is it?
-- =============================================================================
-- The release gate carried out of Codex round 20 into this package: clearing a
-- quarantine verified only the App body, but a schema-1 handoff touches BOTH
-- package-root launchers, so a clear that says "this install is verified" while
-- one of the two actions that start ReaAssist is missing or is not a launcher
-- has verified the wrong install. All THREE endings ask this: the repaired one
-- (_apply_finish's commit), the verified-clean one (quarantine_repair_verified)
-- and, since round 25, the authorized crash-recovery one (the `completed`
-- closure in resolve_journal_at_startup, which used to clear directly).
--
-- Serviceable means present at the package root AND carrying the launcher
-- marker (RA.file_holds_launcher). A file with the right name and the wrong
-- contents fails a user exactly as hard as a missing one, and it is the likelier
-- of the two after a half-finished handoff, where the pre-N body may still be
-- sitting at the launcher's path.
--
-- One blocking answer and four advisory ones, keyed off the ownership state so
-- each says the thing that is actually true of that install:
--
--   blocking     CONFIRMED unowned, and this release carries a replacement in
--                its launchers section. The app is allowed to fix it and the
--                repair queues it, so a clear reaching this state means the
--                file did not land. The gate stays and the user is told to run
--                the check again.
--   "unavailable" confirmed unowned and NOT in this release's launchers
--                section, or no usable manifest at all. Nothing here can
--                produce the file, so clear and name the website reinstall.
--   "reapack"    our own ReaPack package owns it. The app must not write it, so
--                standing on it forever would gate an install over a file this
--                body is forbidden to touch. The clear proceeds and the user is
--                told to re-sync in ReaPack, which does reinstall a registered
--                file that has gone missing (measured, section 3a row E4).
--   "foreign"    a DIFFERENT ReaPack package owns it. Same refusal to write and
--                the same clear, but a different way back, so it is a different
--                message rather than the ReaPack one told inaccurately.
--   "unknown"    the ownership question could not be answered at all. The one
--                thing that must not happen here is a confident message: the
--                copy says the question failed, names the call, and asks for a
--                restart and a re-check.
--
-- Only the first of those may hold the gate, and it is the only one where this
-- body could have fixed the file and did not (Codex round 25, blocker 1: a
-- foreign owner and a failed lookup are the absence of a finding, not a
-- finding of unowned).
--
-- THE PRE-N EDGE. A schema-1 handoff journal quarantined mid-transition may
-- have left legacy-era launchers, and the answer is that this check does not
-- run there at all: launcher_topology_active is false whenever the two roots
-- resolve to one directory, which is exactly the pre-restructure shape, and a
-- flat install's `ReaAssist.lua` is the body rather than a launcher. Asking
-- would fail both launchers over a topology that does not exist yet. Half
-- migrated is the case that DOES run: once either launcher has landed,
-- RA.package_dir_for reads the install as two-level, the check runs, and the
-- launcher still carrying pre-N bytes is exactly what it catches -- queued and
-- finished from the launchers section when unowned, and left to ReaPack's next
-- sync when owned. Both endings are safe because neither writes a launcher the
-- app does not own, and neither leaves the user without an accurate next step.
--
-- Returns two lists: blocking names, and advisory { name, reason } records.
function Updater.launcher_gate_state(manifest)
  local blocking, advisory = {}, {}
  if not Updater.launcher_topology_active() then return blocking, advisory end
  local listed = {}
  local section = Updater.launchers_section(manifest)
  for _, entry in ipairs(section or {}) do listed[entry.name] = true end
  for _, name in ipairs(Updater.LAUNCHER_FILES) do
    if not Updater.launcher_serviceable(name) then
      local state, detail = Updater.launcher_ownership(name)
      if state == Updater.OWNERSHIP_UNOWNED then
        if listed[name] then
          blocking[#blocking + 1] = name
        else
          advisory[#advisory + 1] =
            { name = name, reason = "unavailable", detail = detail }
        end
      elseif state == Updater.OWNERSHIP_OWNED then
        advisory[#advisory + 1] =
          { name = name, reason = "reapack", detail = detail }
      elseif state == Updater.OWNERSHIP_FOREIGN then
        advisory[#advisory + 1] =
          { name = name, reason = "foreign", detail = detail }
      else
        advisory[#advisory + 1] =
          { name = name, reason = "unknown", detail = detail }
      end
    end
  end
  return blocking, advisory
end

-- What the user is told about a launcher the app went ahead without.
--
-- Accurate about who can fix it and actionable about how, because the whole
-- point of not holding the gate here is that the user leaves informed rather
-- than blocked. Each reason gets its own paragraph because each one has a
-- different fix, and because a message that told a foreign-owner or
-- failed-lookup user to synchronize OUR package would be confidently wrong
-- (Codex round 25, blocker 1: the messaging has to be honest about what the
-- state actually is).
--
-- FOUR families, because four different things happened to the file.
-- "missing or damaged" is a launcher that is not doing its job right now.
-- "not updated" is one that is doing its job but carries the previous release's
-- bytes, because ownership changed between the queue and the swap. "not put
-- back" is the rollback's own case (Codex round 26): the swap DID land, then
-- ownership changed before the undo reached it, so the file at the package root
-- is now the new owner's rather than the copy this body had backed up. And "not
-- put back YET" is round 27's: the same rollback, but the ownership question
-- did not answer at all, so nothing was decided, nothing was thrown away, and
-- the next launch asks again. They read very differently to a user and the
-- difference is real, so they are never folded together.
--
-- The last family has exactly one member and can have no others. It is reached
-- only where the answer was UNKNOWN, because a confirmed answer in either
-- direction is acted on rather than deferred.
Updater.LAUNCHER_ADVISORY_ORDER = {
  "reapack", "foreign", "unknown", "unavailable",
  "skipped_reapack", "skipped_foreign", "skipped_unknown",
  "superseded_reapack", "superseded_foreign", "deferred_unknown",
}

-- The advisory reason for one launcher this body deliberately left alone, from
-- the ownership state that made it leave. One function, because four fences
-- reach this same decision and a fifth spelling of the same mapping is how two
-- of them end up saying different things about one state.
--
-- `family` is "skipped" going forward (the launcher was not updated),
-- "superseded" coming back (the launcher was not put back), or "deferred"
-- coming back with no answer at all (the launcher was not put back YET). The
-- state is whatever the fresh probe answered, and anything that is not owned or
-- foreign is unknown by construction: confirmed unowned never reaches here,
-- because confirmed unowned is the state that writes.
--
-- Not every family crosses with every state. "deferred" is asked only where the
-- state IS unknown, so `deferred_unknown` is its only product; the two spellings
-- it could name are unreachable and are deliberately absent from the advisory
-- order, so a future caller that routed a confirmed state here would lose its
-- paragraph loudly in the reason rows rather than quietly in the dialog.
function Updater.launcher_left_alone_reason(family, state)
  local tail = "unknown"
  if state == Updater.OWNERSHIP_OWNED then
    tail = "reapack"
  elseif state == Updater.OWNERSHIP_FOREIGN then
    tail = "foreign"
  end
  return tostring(family) .. "_" .. tail
end

function Updater.launcher_advisory_message(advisory)
  if type(advisory) ~= "table" or #advisory == 0 then return nil end
  local grouped, details = {}, {}
  for _, item in ipairs(advisory) do
    local reason = tostring(item.reason or "unavailable")
    grouped[reason] = grouped[reason] or {}
    grouped[reason][#grouped[reason] + 1] = item.name
    if item.detail and not details[reason] then
      details[reason] = tostring(item.detail)
    end
  end
  local parts = {}
  for _, reason in ipairs(Updater.LAUNCHER_ADVISORY_ORDER) do
    local names = grouped[reason]
    if names then
      local one = #names == 1
      local it = one and "it" or "them"
      local lead
      if reason:sub(1, 8) == "skipped_" then
        lead = one
          and "ReaAssist did not update one of the two actions that start it:"
          or  "ReaAssist did not update the two actions that start it:"
      elseif reason:sub(1, 11) == "superseded_" then
        lead = one
          and "ReaAssist did not put back one of the two actions that start it:"
          or  "ReaAssist did not put back the two actions that start it:"
      elseif reason:sub(1, 9) == "deferred_" then
        lead = one
          and "ReaAssist has not yet put back one of the two actions that "
              .. "start it:"
          or  "ReaAssist has not yet put back the two actions that start it:"
      else
        lead = one
          and "One of the two ReaAssist actions is missing or damaged:"
          or  "Both ReaAssist actions are missing or damaged:"
      end
      local head = lead .. "\n  " .. table.concat(names, "\n  ")
      local tail
      if reason == "reapack" then
        tail = "ReaPack installed " .. it .. ", so ReaAssist must not overwrite "
          .. it .. ". Open Extensions > ReaPack > Synchronize packages to put "
          .. it .. " back."
      elseif reason == "skipped_reapack" then
        tail = "ReaPack took ownership of " .. it .. " while this update was "
          .. "running, so ReaAssist must not overwrite " .. it
          .. ". Open Extensions > ReaPack > Synchronize packages to bring "
          .. it .. " up to date."
      elseif reason == "superseded_reapack" then
        -- Accurate, and worth being precise about. ReaPack synchronized over
        -- this file after ReaAssist had already changed it, so the copy at the
        -- package root is ReaPack's current one and whatever ReaAssist had put
        -- aside is an older launcher ReaPack has since replaced. Undoing the
        -- change would delete ReaPack's file, so ReaAssist did not, and nothing
        -- is lost that ReaPack cannot supply again.
        --
        -- What this may NOT say, since work package B2.5, is that ReaPack
        -- keeps the file up to date from here on. That was a standing promise
        -- about a future update path, and plan section 11.F ends it: after
        -- release N+1 ReaPack is discovery and first install only. The claim
        -- about the copy standing there right now is the true part and the
        -- only part the user needs, so that is all this says. Where to go if
        -- the file breaks is unchanged: ReaPack owns it, so ReaPack restores
        -- it, which is ownership rather than an update path.
        tail = "ReaPack now owns " .. it .. " and has its own copy in place, "
          .. "so ReaAssist left " .. it .. " exactly as " .. it .. " stands "
          .. "rather than undoing its own change to a file it must not write. "
          .. "Nothing is lost: your previous copy was superseded by ReaPack's "
          .. "current one. If " .. it
          .. " ever stops working, open Extensions > ReaPack > Synchronize "
          .. "packages."
      elseif reason == "superseded_foreign" then
        tail = "A different ReaPack package owns " .. it .. " now ("
          .. tostring(details[reason] or "a package that is not ours")
          .. ") and has its own copy in place, so ReaAssist left " .. it
          .. " exactly as " .. it .. " stands rather than undoing its own "
          .. "change to a file it must not write. Open Extensions > ReaPack to "
          .. "see which package that is, then synchronize or remove it and run "
          .. "a check again."
      elseif reason == "deferred_unknown" then
        -- Deliberately NOT the superseded copy. Nothing was decided here and
        -- nothing was given up: the previous copy is still backed up, the
        -- record of the change is still on disk, and the only thing that
        -- happened is that the ownership question did not answer. Telling this
        -- user their copy was superseded would be a claim about an owner
        -- nothing has identified.
        -- And the way out names the thing that is actually broken (Codex round
        -- 28, B2.3e should-fix). What did not answer is ReaPack's ownership
        -- lookup, so reinstalling ReaAssist repairs nothing and reopening it
        -- only asks the same broken question again: a lookup that never answers
        -- turns the fail-closed stance into a restart loop with no way out of
        -- it. ReaPack is where the fix is, ReaAssist is what has to be reopened
        -- afterwards to finish the job, and support is what is left when
        -- neither settles it.
        tail = "ReaAssist could not find out whether ReaPack owns " .. it
          .. " (" .. tostring(details[reason] or "the ownership check failed")
          .. "), so it left " .. it .. " exactly as " .. it .. " stands and "
          .. "kept its own copy safe rather than undoing a change to a file "
          .. "that may not be its own. Nothing has been lost. ReaAssist asks "
          .. "again the next time it starts and finishes putting " .. it
          .. " back then. If it keeps saying this, the ownership check itself "
          .. "is the problem: open Extensions > ReaPack > Browse packages and "
          .. "update ReaPack to the current version, or install ReaPack again "
          .. "from https://reapack.com, then reopen ReaAssist. If ReaAssist "
          .. "still cannot find out who owns " .. it .. " after that, ask for "
          .. "help at https://reaassist.app."
      elseif reason == "foreign" or reason == "skipped_foreign" then
        tail = "A different ReaPack package owns " .. it
          .. " (" .. tostring(details[reason] or "a package that is not ours")
          .. "), so ReaAssist must not overwrite " .. it
          .. ". Open Extensions > ReaPack to see which package that is, then "
          .. "synchronize or remove it and run this check again."
      elseif reason == "unknown" or reason == "skipped_unknown" then
        tail = "ReaAssist could not find out whether ReaPack owns " .. it
          .. " (" .. tostring(details[reason] or "the ownership check failed")
          .. "), so it left " .. it .. " alone rather than overwrite a file "
          .. "that may not be its own. Restart REAPER and run this check "
          .. "again; if that does not settle it, reinstall ReaAssist from "
          .. "https://reaassist.app."
      else
        tail = "This release does not carry a replacement for " .. it
          .. ". Reinstall ReaAssist from https://reaassist.app to restore "
          .. it .. "."
      end
      parts[#parts + 1] = head .. "\n\n" .. tail
    end
  end
  if #parts == 0 then return nil end
  return table.concat(parts, "\n\n")
end

-- The log half of the notice, on its own because the startup ending and the
-- rollback both record the same finding without a recovery surface to put it
-- on. Deliberately says only what is true of every caller: the file was left as
-- it was and the user was told. (An earlier wording said "the clear proceeded",
-- which was true of the gate and of nothing else once the rollback started
-- calling this.)
function Updater.launcher_notice_log(advisory)
  for _, item in ipairs(advisory or {}) do
    Log.line("UPDATE", string.format(
      "launcher serviceability: %s was left as it was by this body (%s: %s); "
      .. "the user was told.",
      tostring(item.name), tostring(item.reason), tostring(item.detail)))
  end
end

-- Record the advisory for the recovery surface and the log. One place, so the
-- visual and Screen Reader endings cannot say different things.
function Updater.launcher_notice_set(advisory)
  local message = Updater.launcher_advisory_message(advisory)
  if not message then return end
  if S then S.launcher_notice = message end
  Updater.launcher_notice_log(advisory)
end

-- What the user is told when the record stays because a launcher the app IS
-- allowed to fix is still not serviceable. Its own function because the startup
-- crash-recovery ending has no update session to set a failure on and says the
-- same thing through the dialog it does have (Codex round 25, blocker 2).
function Updater.launcher_blocked_message(names)
  return string.format(
    "ReaAssist checked the installed files, but %s that start%s ReaAssist "
    .. "%s still missing or damaged:\n  %s\n\n"
    .. "ReaAssist did not clear the interrupted update record, because that "
    .. "record is what keeps this check running. Close anything that has "
    .. "%s open, then run the check again.",
    #names == 1 and "one of the actions" or "the actions",
    #names == 1 and "s" or "",
    #names == 1 and "is" or "are",
    table.concat(names, "\n  "),
    #names == 1 and "that file" or "those files")
end

-- The clear did not happen, because a launcher the app IS allowed to fix is
-- still not serviceable. Same shape as quarantine_clear_failed: the gate stays
-- up, nothing reports success, no restart is scheduled, and the message names
-- the file and the way back.
function Updater.quarantine_launcher_blocked(names)
  update.restart_after = nil
  update.restart_fired = nil
  update.state = "failed"
  Updater._set_failure("quarantine_launcher",
    Updater.launcher_blocked_message(names))
  Log.line("UPDATE", string.format(
    "launcher serviceability: %d unowned launcher(s) still unserviceable "
    .. "after the pass (%s); the quarantine record was NOT cleared and the "
    .. "gate stays up.", #names, table.concat(names, ", ")))
end

-- Does this record describe a transaction whose destinations are all still
-- exactly as it found them? That is the only kind apply_start may write its own
-- journal over (Codex round 28, B2.3e blocker; round 29, B2.3f blocker).
--
-- PHASE first, because it costs nothing. "applying" is the only one a
-- transaction wears before it has done anything, and the other two both say the
-- opposite: "rolling_back" is a rollback somebody started and did not finish,
-- "committed" is one that ran to its end.
--
-- STATUS next. "pending" is what apply_start stamps and nothing else ever
-- writes, so an entry wearing "applied", "rolled_back" or "skipped" has been
-- swapped, undone or decided about.
--
-- Then the DESTINATION ITSELF, which is where round 29 found the hole. A status
-- is written after the mutation it describes, so a pending entry proves nothing
-- on its own, and the test this replaces asked only whether a .bak sat beside
-- it. A FRESH ADD NEVER CREATES ONE: there was no destination to move aside, so
-- its landing leaves no sidecar at all. Between the rename that put the staged
-- copy in place and the journal write that would have said so, a fresh add read
-- exactly like an entry nothing had touched, and the one record of a file that
-- DID land could be written over.
--
-- So the entry carries what the transaction found. apply_start writes the
-- journal before it touches anything, which makes `dest_existed` an observation
-- taken while it was still a fact about the install, and the two kinds of entry
-- then answer one question:
--
--   dest_existed = true   the file must still be there. Absent means the swap
--                         moved it aside, or something outside this transaction
--                         removed it.
--   dest_existed = false  the file must still be absent. Present means the
--                         staged copy landed on it, or a foreign file arrived
--                         at that name; either way this record is no longer the
--                         whole story of that destination.
--   no field at all       no observation, so no permission. A schema-1 journal,
--                         a record written on a host that could not answer, and
--                         anything a stranger wrote all land here, and absent
--                         evidence is not proof that nothing landed.
--
-- The backup question stays, and stays for both kinds. A .bak beside a still
-- pending entry is a mutation the status has not caught up with, and a crash
-- lands exactly there.
--
-- Deliberately not a hash comparison. A launcher whose bytes did not change
-- between releases hashes the same before and after its swap, which is the
-- reclassification hazard the recovery walk spells out at length; what the
-- destination looked like before the transaction started, recorded before it
-- started, is the signal that cannot be confused.
function Updater.journal_changed_nothing(j)
  if type(j) ~= "table" then return false end
  if j.phase ~= "applying" then return false end
  if type(j.files) ~= "table" then return false end
  -- No way to look at a destination is no proof about it.
  if not reaper.file_exists then return false end
  for _, jf in ipairs(j.files) do
    if type(jf) ~= "table" or jf.status ~= "pending" then return false end
    if type(jf.dest_existed) ~= "boolean" then return false end
    local dest = Updater.journal_entry_path(j, jf)
    local now_there = reaper.file_exists(dest) and true or false
    if now_there ~= jf.dest_existed then return false end
    if reaper.file_exists(dest .. ".bak") then return false end
  end
  return true
end

-- WHETHER PUTTING THE FILE BACK CAN STILL LEAD ANYWHERE (Codex round 31,
-- B2.3h should-fix). The apply_moved surface tells the user to restore what
-- moved and click Retry. Retry is force_reinstall, force_reinstall arrives at
-- apply_start, and the fence there starts a record over only while the whole
-- transaction has changed NOTHING. So the advice holds for exactly as long as
-- every entry is still pending, and is worthless the moment one is not: an
-- entry that moved AFTER an earlier one landed leaves a record no restoration
-- can make startable, and following the copy downloads the release again to
-- dead-end on the surface that has no button.
--
-- This asks the fence's question with the one term the user is about to change
-- taken out of it. Everything else the fence weighs is here: the record is
-- applying, every entry is still pending, every entry carries an observation,
-- and no .bak sits beside one. What is left out is ONE destination's comparison
-- against its observation, because that is the state the user's own hands are
-- being asked to put back; it stays the fence's to make, at the moment of the
-- click, over the disk as it is then.
--
-- ONE ENTRY, NOT ALL OF THEM (Codex round 32, B2.3i should-fix). The comparison
-- used to be left out for every entry, and the dialog only ever names one file.
-- The download window is wide enough for two destinations to change in it, and
-- when they did, the tick stopped on the first and the forecast said yes on
-- behalf of a record that also held a second mismatch nobody had been told
-- about. The user restored the file the copy named, clicked, spent a fresh
-- manifest fetch and a whole download, and arrived at apply_unresolved, because
-- journal_changed_nothing weighs every destination and that second one had not
-- moved back. A button was offered for a click that could not work.
--
-- So the caller passes the index it stopped on, and only that entry's
-- destination is excused. Every other one has to agree with its observation
-- already, in both directions, because a destination that VANISHED and one that
-- APPEARED are the same event and the copy says nothing about either of them.
-- An entry with no observation at all fails for every index, exempt or not:
-- that is the fence's permanent refusal and no hand can put it back. Passing no
-- index excuses nothing, which is the strict answer and the right default for
-- any caller that is not speaking for a named file.
--
-- Deliberately NOT folded into journal_changed_nothing. That one is the
-- authority and this is a forecast for a dialog, and a forecast that drifts
-- costs a button while a fence that drifts costs a file. Keeping them apart
-- leaves the authority's shape, and the teeth that bite it, untouched.
function Updater.journal_retry_viable(j, exempt_idx)
  if type(j) ~= "table" then return false end
  if j.phase ~= "applying" then return false end
  if type(j.files) ~= "table" then return false end
  -- No way to look is no proof, and it is also permanent: a host with no
  -- file_exists produced no observations at apply_start and the fence refuses
  -- every record on that ground alone, so no click will ever get past it.
  if not reaper.file_exists then return false end
  for i, jf in ipairs(j.files) do
    if type(jf) ~= "table" or jf.status ~= "pending" then return false end
    if type(jf.dest_existed) ~= "boolean" then return false end
    local dest = Updater.journal_entry_path(j, jf)
    if i ~= exempt_idx then
      local now_there = reaper.file_exists(dest) and true or false
      if now_there ~= jf.dest_existed then return false end
    end
    if reaper.file_exists(dest .. ".bak") then return false end
  end
  return true
end

-- Begin stage C. Every staged file has verified by now; from here on
-- live files get swapped one rename pair at a time, with the journal
-- updated after each landing so a crash at any point is recoverable.
function Updater.apply_start()
  update._batch = nil
  -- STILL THE ACQUISITION THE LOCK NAMES, before this writes its own record
  -- (Codex round 41, B2.3r). download_start took the lock and the download it
  -- covers can run for minutes, so this is the first moment after that window
  -- where a stolen lock matters, and the very next thing this function does is
  -- write a journal over whatever is at that path. Asked ahead of the
  -- foreign-journal guard on purpose: that guard reads the record, and a record
  -- another instance has not written yet still looks like ours.
  if not Updater.journal_writers_excluded() then
    Updater._set_failure("apply_takeover",
      "Another ReaAssist instance took over this update; no "
      .. "further files were changed.")
    Updater.release_apply_lock()
    update.state = "failed"
    return
  end
  -- Foreign-journal guard: a journal left by ANOTHER instance that is
  -- still live means that instance is mid-apply on this shared install.
  -- Overwriting its journal would destroy its recovery state, so fail
  -- this attempt instead. A stale journal from a dead instance would
  -- have been resolved by our own startup recovery; if one appeared
  -- since (that instance crashed while we ran), replacing it is the
  -- best available option and is logged.
  --
  -- INVALID is not ABSENT (Codex round 22, B2.2g blocker 2). This used to test
  -- the journal for truth and nothing else, so a record present on disk that
  -- could not be read, parsed, validated or adopted read exactly like no
  -- record at all, and the next thing this function does is write its own over
  -- the top -- destroying the only account of a transaction nobody has
  -- resolved, and doing it on an install where something has already gone
  -- wrong. So the two answers are separated at the one caller that mutated on
  -- them. Absent proceeds as it always did. Invalid stops here, having changed
  -- nothing: the evidence is left exactly where it is, byte for byte, for the
  -- startup resolver that is built to preserve it and gate on it.
  local existing, reason, bad_path, bad_why = Updater.journal_read()
  if not existing and reason == "invalid" then
    Updater._set_failure("apply_unresolved",
      "ReaAssist found an update record it cannot read at:\n"
      .. tostring(bad_path) .. "\n\n"
      .. "That record describes an update nobody has finished, so this one "
      .. "will not start and nothing was changed. Restart ReaAssist and it "
      .. "will offer to check every installed file and repair the install.")
    Log.line("UPDATE",
      "apply_start: refusing to start over an unresolved update record at "
      .. tostring(bad_path) .. " (" .. tostring(bad_why) .. "); it is "
      .. "preserved untouched and nothing was applied.")
    Updater.release_apply_lock()
    update.state = "failed"
    return
  end
  if existing and existing.instance ~= RA.instance_file_suffix()
      and RA.temp_instance_is_live(existing.instance) then
    -- Staged files are deliberately NOT deleted here. Since B2.3s they ARE
    -- this acquisition's alone (Updater.staging_path), so the old reason (they
    -- might be the live owner's downloads) no longer holds; what holds instead
    -- is that this branch is a back-off, and a back-off changes nothing. The
    -- startup sweep collects them under the lock's authority once no
    -- acquisition is standing.
    Updater._set_failure("apply_journal",
      "Another ReaAssist instance is applying an update on this "
      .. "install. Let it finish, then retry.")
    Updater.release_apply_lock()
    update.state = "failed"
    return
  end
  -- OURS IS NOT THE SAME AS RESOLVED (Codex round 28, B2.3e blocker). The
  -- guard above asks who wrote the record and stops for a live stranger; that
  -- was the whole of it, so a record written by THIS instance fell straight
  -- through to the write below and was erased.
  --
  -- The record that costs is the one the rollback deliberately keeps. A
  -- launcher whose ownership question did not answer leaves its entry applied
  -- with its .bak beside it and the journal on disk, precisely so the next
  -- launch can ask again; the failure that produced it puts a Retry button in
  -- front of the user, Retry is force_reinstall, and force_reinstall arrives
  -- here in the same process with the same instance id. One click and the only
  -- account of a backup nobody has put back is gone, the .bak beside it
  -- orphaned, and the launcher the user had is not coming back.
  --
  -- So ownership is not the question any more. The question is whether the
  -- record on disk describes a transaction that has changed something, and only
  -- a record that has changed NOTHING may be started over. That keeps the one
  -- flow the own-instance fall-through existed for: apply_start's own journal
  -- write can fail at its swap and leave a completed .tmp that journal_read
  -- adopts, and the retry that follows must be able to start over a record
  -- whose every entry is still pending and whose transaction never reached a
  -- live file. It keeps the same permission for a dead stranger's record for
  -- the same reason, and withdraws it from both where a mutation has happened.
  --
  -- Refusing is not a dead end and does not need to be: startup recovery
  -- resolves every one of these records, in whichever direction the record
  -- itself dictates, and it stays the one place a deferral resolves. The cost
  -- of the refusal is one restart. The cost of the write was the user's file.
  if existing and not Updater.journal_changed_nothing(existing) then
    Updater._set_failure("apply_unresolved",
      "ReaAssist has not finished recovering from an earlier update on this "
      .. "install, so this one will not start and nothing was changed.\n\n"
      .. "Close ReaAssist and open it again: recovery finishes when ReaAssist "
      .. "starts, and that is the only place it can finish. Nothing has been "
      .. "lost in the meantime.")
    Log.line("UPDATE", string.format(
      "apply_start: refusing to start over an unresolved update record "
      .. "(instance %s, phase %s); it is preserved untouched, along with "
      .. "every backup and staged copy belonging to it, and nothing was "
      .. "applied.", tostring(existing.instance), tostring(existing.phase)))
    Updater.release_apply_lock()
    update.state = "failed"
    return
  end
  if existing then
    Log.line("UPDATE",
      "apply_start: starting over a record that changed nothing (instance "
      .. tostring(existing.instance) .. ")")
  end
  local j = {
    -- Schema 2 with root = "app" says these names are App-relative, which
    -- is what separates this journal from one a pre-restructure body left
    -- at the same path with package-relative names (journal_root_dir).
    schema         = 2,
    root           = "app",
    instance       = RA.instance_file_suffix(),
    target_version = tostring(update.remote_version
      or (update.manifest and update.manifest.version) or "?"),
    phase          = "applying",
    files          = {},
    -- WHICH ACQUISITION'S STAGING THIS RECORD DESCRIBES (Codex round 42,
    -- B2.3s). The transaction can be finished by a launch that comes after the
    -- process that staged it, and the staged copies are named for the
    -- acquisition that downloaded them, so the record has to say which one or a
    -- later walk would hunt a name nobody wrote. Absent when this queue staged
    -- into the bare sibling name, which is what a body with no acquisition to
    -- name does.
    staging        = update._staging_tag,
  }
  -- Stamp the standing quarantine's identity when this apply IS the repair
  -- that gate authorized (B2.2d requirement 5). Without it a crash between
  -- here and the commit leaves a journal the gate will never walk, because
  -- the gate outranks every journal on purpose. With it, the next launch
  -- recognises this transaction as its own and finishes it, forward or back,
  -- before the gate decides anything.
  --
  -- Only under the gate, and only when there is a token to carry: an ordinary
  -- update on an ungated install has no episode to belong to, and a journal
  -- claiming one would be a shape nothing wrote.
  --
  -- The identity established for this episode from the standing record's own
  -- name, never a value read from somewhere beside it (Codex round 21, B2.2f
  -- fix 1, and round 22, B2.2g blocker 1). While the identity lived in a file
  -- of its own, a fresh write that did not land left the previous episode's
  -- value sitting there for this line to read, and stamping it would give this
  -- transaction the authorization of an episode that is over. There is no such
  -- value now. No identity means no stamp: the repair still runs, and a crash
  -- before it commits leaves a journal the gate refuses, so the repair is
  -- offered again from the start instead of resumed.
  if S and S.quarantine_gate then
    local token = Updater.quarantine_episode_token()
    if token then
      j.quarantine_token = token
    else
      Log.line("UPDATE",
        "apply_start: the standing quarantine has no proven identity this "
        .. "launch, so this repair's journal is unstamped; a crash before it "
        .. "commits re-offers the repair rather than resuming it.")
    end
  end
  for _, entry in ipairs(update.download_queue) do
    -- What this transaction found at that destination, taken here and only
    -- here, because here is the last moment it is a fact about the install
    -- rather than about the transaction: nothing below has run and no live file
    -- has been touched yet.
    --
    -- journal_changed_nothing is the only reader. What it needs is a pre-swap
    -- observation for EVERY entry, because the .bak it used to rely on is
    -- produced only by an entry that had a destination to move aside; a fresh
    -- add lands without leaving one, and looked untouched afterwards (Codex
    -- round 29, B2.3f blocker).
    --
    -- A host with no way to answer records nothing rather than guessing false.
    -- The field is absent then, which the fence reads as no proof and refuses
    -- over, and that is the right cost: the alternative is a record asserting
    -- something nobody looked at, which a later launch would believe.
    local dest_existed = nil
    if reaper.file_exists then
      dest_existed = reaper.file_exists(Updater.queue_dest(entry)) and true
        or false
    end
    j.files[#j.files+1] = {
      name   = entry.filename,
      sha256 = entry.sha256,
      status = "pending",
      dest_existed = dest_existed,
      -- Only ever "package", only ever for a launcher, and only because the
      -- queue entry already said so. Recovery resolves this entry against the
      -- package root on a later launch, which is the whole reason the field
      -- exists: without it the name would be read as App-relative and a crash
      -- mid-launcher-swap would hunt staging under App/ and delete a body file
      -- it never installed.
      root   = entry.root,
    }
  end
  if not Updater.journal_write(j) then
    -- No journal means no crash recovery; refuse to touch live files.
    -- Clear any artifacts of the failed write (journal_write keeps a
    -- completed .tmp on a swap failure so INTERRUPTED transactions stay
    -- recoverable, but no transaction has started here: nothing was
    -- applied and the staged files are deleted below, so an adopted
    -- journal next launch would describe a transaction that never ran).
    Updater.journal_delete()
    Updater._download_verify_fail("journal_write",
      "Could not write the update journal; no files were changed.")
    return
  end
  -- Ownership verify: even under the apply lock, the fallback
  -- (non-exclusive) lock mode leaves a small race, so re-read the
  -- journal after writing it. If the journal on disk is not ours, the
  -- other process won and its recovery state (and shared staging) must
  -- not be disturbed. Back off exactly like the live-owner case. A fence,
  -- so invalid and absent are both "not ours" and both back off (Codex round
  -- 22, B2.2g blocker 2).
  local winner = Updater.journal_read()
  if not winner or winner.instance ~= RA.instance_file_suffix() then
    Updater._set_failure("apply_journal",
      "Another ReaAssist instance is applying an update on this "
      .. "install. Let it finish, then retry.")
    Updater.release_apply_lock()
    update.state = "failed"
    return
  end
  update._journal = j
  update._apply = {
    idx             = 1,
    prepared        = false,
    bak_existed     = false,
    rename_failures = 0,
  }
  update.applied_files = {}
  update.download_idx  = 1
  update.state = "applying"
end

-- One frame of stage C. Applies as many files as renames allow; yields
-- (returns) whenever a staged->dest rename fails so AV scan locks get a
-- natural ~30 ms inter-frame delay, retrying up to 15 attempts per file
-- (same ceiling and rationale as the old rename_retry state: cold
-- Windows Defender scans hold a just-written file for 300-500 ms).
function Updater.apply_tick()
  local a = update._apply
  local j = update._journal
  if not a or not j then
    Updater._set_failure("apply",
      "apply_tick entered with no apply state.")
    Updater.release_apply_lock()
    update.state = "failed"
    return
  end
  while true do
    -- STILL THE ACQUISITION THE LOCK NAMES (Codex round 41, B2.3r). The lock is
    -- taken before the download starts and held across the whole of it, which
    -- can be minutes; a machine that sleeps in that window has this instance's
    -- live marker age out and its lock reclaimed, and the journal fence below
    -- cannot see it, because the record at the journal path is still ours until
    -- the other instance writes over it. So the lock itself is asked, once per
    -- entry, before the backup and the swap and before the finish that deletes
    -- every backup. The ending is the established one for exactly this event.
    if not Updater.journal_writers_excluded() then
      update._journal = nil
      update._apply = nil
      Updater._set_failure("apply_takeover",
        "Another ReaAssist instance took over this update; no "
        .. "further files were changed.")
      Updater.release_apply_lock()
      update.state = "failed"
      return
    end
    local entry = update.download_queue[a.idx]
    if not entry then
      Updater._apply_finish()
      return
    end
    local dest   = Updater.queue_dest(entry)
    local staged = entry.staged
    local bak    = dest .. ".bak"
    if not a.prepared then
      -- Ownership fence: re-verify the on-disk journal is still ours
      -- before EVERY file's destructive swap, not just once. A paused
      -- updater whose liveness lease expired can be reclaimed by a
      -- second instance; on resume, the other instance's on-disk state
      -- is authoritative and nothing here may touch the disk (no
      -- rollback, no staged cleanup, no journal deletion). This fence
      -- also subsumes the old first-frame verify: file 1's fence runs
      -- at the same instant, before any mutation. The fence-then-write
      -- pair (this read, then the per-file journal_write after the
      -- swap) is the revalidation boundary; a takeover landing between
      -- them is bounded by one file swap, which the winner's dest-hash
      -- reclassification tolerates (an extra applied file with a
      -- matching hash reads as landed). Cost: one journal read per
      -- swap, symmetric with the existing one write per swap. A fence, so
      -- invalid and absent are both "not ours" and both stop the apply
      -- (Codex round 22, B2.2g blocker 2).
      local current = Updater.journal_read()
      if not current or current.instance ~= RA.instance_file_suffix() then
        update._journal = nil
        update._apply = nil
        Updater._set_failure("apply_takeover",
          "Another ReaAssist instance took over this update; no "
          .. "further files were changed.")
        Updater.release_apply_lock()
        update.state = "failed"
        return
      end
      -- WHAT THIS ENTRY IS WAS SETTLED BEFORE ANY OF THIS RAN (Codex round 30,
      -- B2.3g blocker). The swap used to take its own look at the destination
      -- here and classify from that, which made the classification a fact about
      -- the disk at swap time rather than about the transaction. A file that
      -- was there when apply_start looked and gone by the time this ran was
      -- read as a fresh add: no backup taken, the staged copy landed on it, and
      -- the record still saying a file had been found there. Let the journal
      -- write that would have said "applied" fail, and the durable entry reads
      -- pending with dest_existed = true beside a destination that is present
      -- again with no .bak, which is the exact shape journal_changed_nothing
      -- calls untouched. One Retry then writes over the only account of a file
      -- this transaction DID replace.
      --
      -- So the recorded observation rules, and the only thing asked of the disk
      -- is whether it still agrees with it. It must, in both directions. A
      -- destination that has VANISHED under a swap entry and one that has
      -- APPEARED under a fresh add are the same event, something outside this
      -- transaction moved a file it is holding, and neither is a thing to
      -- classify around. An entry carrying NO observation is refused for the
      -- same reason the fence refuses it: there is nothing to ground the
      -- classification in, and a guess produces the fresh-add branch, which is
      -- the branch that takes no backup and whose rollback deletes the file.
      --
      -- Stopping costs almost nothing, because nothing of this entry has been
      -- touched. The journal stays as it was written, the staged copy stays
      -- staged, earlier entries keep their backups and their applied statuses,
      -- and the transaction ends the way every other apply failure ends, with
      -- the user told. The next launch's recovery walk owns the record from
      -- there; and if the world moves back before then, apply_start's fence
      -- reads a transaction that changed nothing and lets it start over.
      --
      -- Ahead of the launcher ownership fence below on purpose: a skip is a
      -- journal write plus the deletion of a staged copy, and neither belongs
      -- on an entry whose ground truth has moved out from under it.
      local jf = j.files[a.idx]
      local recorded = jf and jf.dest_existed
      local now_there = nil
      if reaper.file_exists then
        now_there = reaper.file_exists(dest) and true or false
      end
      if type(recorded) ~= "boolean" or now_there ~= recorded then
        -- WHICH WAY IT WENT, AND WHETHER A CLICK CAN STILL SERVE (Codex round
        -- 31, B2.3h should-fix). Both are settled HERE, while the record and
        -- the entry that stopped on it are still in hand, and both are stamped
        -- on the update state for the dialog to read. The dialog cannot work
        -- either of them out for itself: the in-memory journal is let go three
        -- lines below, and the durable one, which is what the fence will read
        -- at the moment of the click, is not a file to re-read once a frame to
        -- redraw a paragraph. The two say the same thing here in any case,
        -- because every status this transaction has written went to disk before
        -- the next entry was touched, and a write that failed ended it.
        --
        -- The direction decides what the user is told happened, because a file
        -- that WENT and a file that ARRIVED need opposite corrections and the
        -- rendered view used to give both of them the first one. The viability
        -- decides whether a Retry is offered at all: the fence starts a record
        -- over only while nothing in it has changed, so an entry that moved
        -- after an earlier one landed cannot be helped by any restoration, and
        -- a host that could produce no observation cannot be helped by
        -- anything. Neither is offered a button, and neither is told to press
        -- one.
        --
        -- The index goes with the question (Codex round 32, B2.3i). The copy
        -- below names ONE file, so one entry's destination is the only one the
        -- forecast may excuse, and it is this one. Every other destination in
        -- the record has to already agree with what apply_start found there,
        -- because nothing this dialog says will move it back.
        local direction = "unknown"
        if type(recorded) == "boolean" then
          direction = recorded and "gone" or "appeared"
        end
        update.moved_file      = entry.filename or dest
        update.moved_direction = direction
        update.moved_retry     = Updater.journal_retry_viable(j, a.idx)
        local said, way
        if direction == "gone" then
          said = "A file this update was going to replace is no longer where "
            .. "it was when the update started:"
        elseif direction == "appeared" then
          said = "A file this update was going to add is already there, and "
            .. "it was not there when the update started:"
        else
          said = "ReaAssist has no record of what was at this location when "
            .. "the update started, so it will not change it:"
        end
        -- MOVING IT COMES FIRST, WHICHEVER WAY OUT IS TAKEN (Codex round 33,
        -- B2.3j blocker). The appeared lines used to offer reopening as an
        -- alternative to moving the file, and the launch that offer sends the
        -- user to is the one that stops on the same disagreement. Nothing is
        -- lost by reopening (the roll-forward stops before it touches
        -- anything), but nothing is gained either, so the copy names the move
        -- in both ways out rather than leaving the user a lap to spend.
        if not update.moved_retry and direction == "appeared" then
          way = "Move that file somewhere else, then close ReaAssist and open "
            .. "it again: that is what finishes an update that stopped part "
            .. "way, and it cannot finish while that file is there."
        elseif not update.moved_retry then
          way = "Close ReaAssist and open it again: an update that stopped "
            .. "part way is finished when ReaAssist starts, and from here that "
            .. "is the only thing that can take it further."
        elseif direction == "appeared" then
          way = "If you put that file there, move it somewhere else and try "
            .. "again. Closing ReaAssist and opening it again works too, but "
            .. "only once that file has been moved: the update cannot finish "
            .. "while it is there."
        else
          way = "If the file was moved or deleted by mistake, put it back and "
            .. "try again. Otherwise close ReaAssist and open it again, which "
            .. "is what finishes an update that stopped part way."
        end
        Updater._set_failure("apply_moved", said .. "\n" .. dest .. "\n\n"
          .. "Nothing further was changed, and nothing was thrown away: every "
          .. "backup, every downloaded file and this update's own record were "
          .. "kept.\n\n" .. way)
        Log.line("UPDATE", string.format(
          "apply: %s is not what apply_start found there (recorded %s, now "
          .. "%s), so the swap stopped with nothing changed and the journal, "
          .. "every backup and all staging preserved; a retry over this record "
          .. "is %s.",
          dest, tostring(recorded), tostring(now_there),
          update.moved_retry
            and "offered, because nothing in it has changed yet"
            or "not offered, because apply_start will not start it over"))
        update._journal = nil
        update._apply = nil
        Updater.release_apply_lock()
        update.state = "failed"
        return
      end
      -- Ownership fence for the OTHER root: re-ask ReaPack immediately before
      -- this launcher's swap (Codex round 25, B2.3 blocker 1).
      --
      -- The queue was built before the download ran and this swap happens
      -- after it, and a ReaPack synchronization inside that window can hand a
      -- queued launcher an owner. download_start's refresh is the last check
      -- BEFORE the window; this is the check after it, and it is the one that
      -- guards the write. It reads no cache.
      --
      -- Before the backup, not merely before the rename: moving the live file
      -- to .bak is already a mutation of a file this body may no longer touch.
      --
      -- The answer is a SKIP, not a failure. The rest of the transaction is
      -- correct and has nothing to do with this file, and failing it would roll
      -- back a body update over a launcher that is now somebody else's to keep
      -- alive. The entry is journaled "skipped" before its staged copy goes, so
      -- a crash here leaves a record recovery reads as "leave this one alone"
      -- rather than as work to finish; a crash BEFORE that write leaves it
      -- pending, and recovery's roll-forward asks this same question again.
      if entry.root == "package" then
        local writable, ownership, detail =
          Updater.launcher_writable_now(entry.filename)
        if not writable then
          local reason =
            Updater.launcher_left_alone_reason("skipped", ownership)
          j.files[a.idx].status = "skipped"
          -- The reason rides in the journal, not only in memory. This apply may
          -- never reach the commit that reports it (a crash here is exactly the
          -- window x4 pins), and the launch that finishes the transaction has
          -- to be able to say WHY a launcher was left alone rather than only
          -- that it was (Codex round 26, blocker 2).
          j.files[a.idx].skip_reason = reason
          j.files[a.idx].skip_detail = detail and tostring(detail):sub(1, 200)
            or nil
          if not Updater.journal_write(j) then
            Updater._set_failure("journal_write",
              "Could not update the apply journal; the update was rolled back.")
            if Updater.rollback() then
              Updater._delete_all_staged()
            end
            Updater.release_apply_lock()
            update._apply = nil
            update.state = "failed"
            return
          end
          os.remove(staged)
          update._launcher_skipped = update._launcher_skipped or {}
          update._launcher_skipped[#update._launcher_skipped + 1] = {
            name = entry.filename, reason = reason, detail = detail,
          }
          Log.line("UPDATE", string.format(
            "apply: %s is no longer confirmed unowned (%s: %s), so its swap "
            .. "was skipped; the rest of the transaction continues and the "
            .. "user is told.", entry.filename, tostring(ownership),
            tostring(detail)))
          a.idx             = a.idx + 1
          a.prepared        = false
          a.bak_existed     = false
          a.rename_failures = 0
          update.download_idx = a.idx
          -- Yield the frame exactly as the rename retry does; the next tick
          -- picks up at the new index.
          return
        end
      end
      -- Back up the current file, or not, according to what apply_start found
      -- here. The distinction is between "dest does not exist (fresh-install
      -- add)" and "dest exists but rename failed (lock, permissions, AV scan,
      -- cloud sync, editor handle)", because os.rename returns nil for both,
      -- and misclassifying an existing-but-locked file as a fresh add is
      -- dangerous: rollback's fresh-install branch deletes dest, which would
      -- destroy the only intact copy when no .bak was created.
      --
      -- The answer comes off the record rather than off a probe taken here, and
      -- the fence above has already established that the disk still agrees with
      -- it (Codex round 30, B2.3g blocker).
      os.remove(bak)  -- stale leftover from an older interrupted swap
      if recorded then
        local ok_bak, bak_err = os.rename(dest, bak)
        if not ok_bak then
          Updater._set_failure("backup", string.format(
            "Could not back up existing file %s: %s",
            dest, tostring(bak_err)))
          -- A bailed (unmarked) rollback preserves staging as recovery
          -- state; only clean it when the rollback actually ran.
          if Updater.rollback() then
            Updater._delete_all_staged()
          end
          Updater.release_apply_lock()
          update._apply = nil
          update.state = "failed"
          return
        end
        a.bak_existed = true
      else
        a.bak_existed = false
      end
      a.prepared = true
    end
    local ok_mv = os.rename(staged, dest)
    if not ok_mv then
      a.rename_failures = a.rename_failures + 1
      if a.rename_failures >= 15 then
        -- Give up on this file. Restore its backup when one was
        -- created; a failed restore is the one rollback failure mode
        -- that needs manual attention, so it is appended to
        -- update.last_error below (same note format rollback uses).
        local restore_note
        if a.bak_existed then
          local ok_restore, restore_err = os.rename(bak, dest)
          if not ok_restore then
            Log.line("UPDATE", string.format(
              "rollback restore failed for %s: %s "
              .. "(.bak still on disk; manual recovery may be needed)",
              dest, tostring(restore_err)))
            restore_note = string.format(
              "\n\nNote: rollback could not restore 1 previous file "
              .. "(.bak file left on disk for manual recovery): %s",
              dest)
          end
        end
        Updater._set_failure("rename", string.format(
          "Could not rename downloaded file into place after %d "
          .. "attempts (%s -> %s). Antivirus or file lock?",
          a.rename_failures, tostring(staged), dest))
        if restore_note then
          update.last_error = (update.last_error or "") .. restore_note
        end
        -- A bailed (unmarked) rollback preserves staging as recovery
        -- state; only clean it when the rollback actually ran. The
        -- current file's staged copy is covered by _delete_all_staged,
        -- so no separate removal here.
        if Updater.rollback() then
          Updater._delete_all_staged()
        end
        Updater.release_apply_lock()
        update._apply = nil
        update.state = "failed"
        return
      end
      -- Stay in "applying"; next frame retries this same rename.
      return
    end
    -- Landed. Record for rollback, reflect into the journal, advance.
    -- name and root travel with the record because the ROLLBACK has to be able
    -- to ask the ownership question about this file too (Codex round 26,
    -- blocker 1B), and it can only ask about a launcher it can name. Reading
    -- them back off the journal would not do: the rollback runs with the
    -- journal absent in one of its paths, and that is precisely the path where
    -- guessing would delete somebody else's file.
    --
    -- The payload hash travels with it for the same reason and since round 34:
    -- the rollback has to be able to ask whether the file it is about to remove
    -- is still the one this rename put there, and on the path where the journal
    -- is absent there is nothing else left to ask.
    update.applied_files[#update.applied_files+1] = {
      path        = dest,
      bak_existed = a.bak_existed,
      name        = entry.filename,
      root        = entry.root,
      sha256      = entry.sha256,
    }
    j.files[a.idx].status      = "applied"
    j.files[a.idx].bak_existed = a.bak_existed
    if not Updater.journal_write(j) then
      -- A journal that can no longer be updated cannot guarantee
      -- recovery for the files still pending; unwind while the
      -- in-memory state is complete rather than pressing on.
      Updater._set_failure("journal_write",
        "Could not update the apply journal; the update was rolled back.")
      -- A bailed (unmarked) rollback preserves staging as recovery
      -- state; only clean it when the rollback actually ran.
      if Updater.rollback() then
        Updater._delete_all_staged()
      end
      Updater.release_apply_lock()
      update._apply = nil
      update.state = "failed"
      return
    end
    a.idx             = a.idx + 1
    a.prepared        = false
    a.bak_existed     = false
    a.rename_failures = 0
    update.download_idx = a.idx
  end
end

-- Every queued file has been renamed into place: run orphan cleanup,
-- mark the journal committed, delete the .baks, delete the journal,
-- then hand off to the done/auto-restart flow.
function Updater._apply_finish()
  local silent_manifest = update.silent_manifest_repair == true
  -- Per-version stale-file cleanup. The new manifest's removed_files
  -- list (auto-populated by gen_manifest.py from the diff between this
  -- release and the prior, plus carry-forward of older deletions for
  -- users skipping versions) names files we previously shipped and no
  -- longer do. Without this step a renamed file's old name would
  -- linger on disk forever -- the rest of the updater only writes new
  -- files and overwrites existing ones, never deletes. Three layers
  -- of safety make removing user-facing files here safe:
  --   1. Authoring layer: gen_manifest.py only ever populates this
  --      list from prior manifests we ourselves shipped. A user-
  --      dropped file in the install dir cannot end up there.
  --   2. is_safe_filename: rejects path-traversal, absolute paths,
  --      backslashes, hidden segments, and unknown extensions.
  --   3. should_remove_orphan: enforces the "owned path" zone and the
  --      PROTECTED_FROM_REMOVAL set (custom system prompt override,
  --      runtime debug log, FX cache).
  -- os.remove failures are logged but do not fail the update; the
  -- new files are already in place, lingering orphans are cosmetic.
  if not silent_manifest then
    local removed = update.manifest and update.manifest.removed_files
    if type(removed) == "table" then
      local current_files = {}
      for _, entry in ipairs(update.manifest.files or {}) do
        if type(entry) == "table" and type(entry.name) == "string" then
          current_files[entry.name] = true
        end
      end
      for _, name in ipairs(removed) do
        if Updater.should_remove_orphan(name, current_files) then
          local path = Updater.local_path_for(name)
          if reaper.file_exists and reaper.file_exists(path) then
            local ok = os.remove(path)
            Log.line("UPDATE", string.format(
              "removed orphan %s: %s",
              name, ok and "ok" or "failed"))
          end
        elseif type(name) == "string" then
          -- Loud about rejected entries so a malformed manifest doesn't
          -- silently get past the predicate. Only log the first ~20
          -- chars of the name to keep the log line short on
          -- pathological inputs.
          Log.line("UPDATE", string.format(
            "removed_files: refused %s (outside owned zone or "
            .. "protected)", tostring(name):sub(1, 80)))
        end
      end
    end
  end
  -- Commit point: once the journal says "committed", startup recovery
  -- treats the transaction as complete (finish cleanup, never roll
  -- back), so the .baks are deleted only AFTER this marker lands. A
  -- failed commit write is benign: the journal still shows "applying"
  -- with every file applied, which recovery resolves forward to this
  -- same cleanup.
  local j = update._journal
  if j then
    j.phase = "committed"
    Updater.journal_write(j)
  end
  for _, applied in ipairs(update.applied_files) do
    os.remove(applied.path .. ".bak")
  end
  Updater.journal_delete()
  -- The commit point is also what clears a standing journal quarantine. An
  -- earlier launch may have preserved a record it could not read and gated
  -- every launch since; what that gate is waiting for is somebody vouching
  -- for the install again, and a transaction that ran the whole pipeline and
  -- reached this line is exactly that. Both repair lanes land here
  -- (force_reinstall and the manual check's repair flow), which is why they
  -- clear it without knowing they do. The manifest-only silent repair is
  -- excluded: it applies one file and says nothing about the rest.
  -- Launcher serviceability, asked BEFORE the clear and only under a standing
  -- gate (round 20's release gate, implemented in B2.3). A committed apply
  -- vouches for what it applied; it says nothing about a launcher that was
  -- never queued, and a schema-1 handoff touches both of them. An unowned
  -- launcher this release could have supplied and did not keeps the record;
  -- a ReaPack-owned one does not, because the app is forbidden to write it.
  local launcher_blocking, launcher_advisory = {}, {}
  if not silent_manifest and S and S.quarantine_gate then
    launcher_blocking, launcher_advisory =
      Updater.launcher_gate_state(update.manifest)
  end
  -- A launcher this transaction declined to swap because ownership changed
  -- under it (Codex round 25, B2.3 blocker 1). Not a gate question: the file is
  -- present and doing its job, it simply carries the previous release's bytes
  -- and this body may not change that. It joins the advisory so the user gets
  -- told through the surface that already exists for launchers the app went
  -- ahead without, and so the auto-restart below stands down and leaves the
  -- message where it can be read. Asked on every apply, gate or no gate,
  -- because an ordinary update is where this happens.
  if not silent_manifest then
    for _, item in ipairs(update._launcher_skipped or {}) do
      launcher_advisory[#launcher_advisory + 1] = item
    end
  end
  update._launcher_skipped = nil
  local quarantine_stuck = nil
  if not silent_manifest and #launcher_blocking == 0 then
    quarantine_stuck = select(2, Updater.journal_quarantine_clear())
  end
  update._journal = nil
  update._apply   = nil
  Updater.release_apply_lock()
  update.state   = "done"
  update.applied = true
  if #launcher_blocking > 0 then
    Updater.quarantine_launcher_blocked(launcher_blocking)
    return
  end
  -- A clear that did not take is the one failure that must never be reported
  -- as success (B2.2d requirement 5). The files landed, so this is not a
  -- failed update; what failed is removing the record the next launch reads,
  -- and the next launch will be gated again. Say so here, ahead of the
  -- done view and ahead of the restart scheduling below, and leave the gate
  -- standing rather than pretending it came down.
  if not silent_manifest then
    local standing = quarantine_stuck or Updater.journal_quarantined()
    if standing then
      Updater.quarantine_clear_failed(standing)
      return
    end
    Updater.launcher_notice_set(launcher_advisory)
    if S and S.quarantine_gate then S.quarantine_gate = nil end
  end
  if silent_manifest then
    local manual = update._silent_manifest_manual == true
    update.state = "idle"
    update._last_ok_at = os.time()
    update.restart_after = nil
    update.restart_fired = nil
    update.show_dialog = false
    update.popup_opened = false
    update.force = false
    update.action_was_repair = nil
    update.repair_missing = nil
    update.repair_mismatched = nil
    update.silent_manifest_repair = false
    update._silent_manifest_manual = false
    update.download_queue = {}
    update.applied_files = {}
    RA.support_metadata_refresh = true
    if manual and UI and UI.show_float_toast then
      UI.show_float_toast(
        "ReaAssist is up to date (v" .. CFG.VERSION .. ")", "ok")
    end
    Log.line("UPDATE", "silent manifest transition repair verified and applied")
    return
  end
  -- Active stale-stock nudge for power-user prompt overrides. If this
  -- update modified the stock system prompt AND the user has a custom
  -- override file in place (which the loader prefers over the stock),
  -- set a persistent ExtState flag. The next-launch path reads it,
  -- clears it, and shows a one-time sticky toast inviting the user to
  -- diff the new stock prompt against their custom copy and merge any
  -- improvements worth keeping. Persistent (3rd arg true) so it
  -- survives the auto-restart that follows.
  do
    local stock_pp  = RA.RESOURCES_DIR .. "System_Prompt.md"
    local custom_pp = RA.RESOURCES_DIR .. "System_Prompt_Custom.md"
    local prompt_changed = false
    for _, applied in ipairs(update.applied_files) do
      if applied.path == stock_pp then prompt_changed = true; break end
    end
    if prompt_changed and reaper.file_exists(custom_pp) then
      reaper.SetExtState(CFG.EXT_NS, "prompt_review_pending", "1", true)
    end
  end
  -- Stage 3.4 auto-restart: schedule a short delay (so the user sees
  -- the "Applied" confirmation), then re-launch the script via the
  -- sidecar relauncher (Relaunch.lua). The relauncher re-
  -- registers ReaAssist via AddRemoveReaScript and fires it from its
  -- own script context, so auto-restart works regardless of how this
  -- instance was launched. File-existence check (cheap, no action-
  -- registry side effects) gates the restart scheduling so the done-
  -- view message stays honest: falls back to "Close and reopen" if
  -- the relauncher file is missing, which only happens on a broken
  -- install. try_auto_restart does the actual AddRemoveReaScript
  -- registration on-demand when it fires.
  --
  -- Not while a launcher advisory is standing. The relauncher fires the
  -- PACKAGE-root entrypoint (Resources/Relaunch.lua), which is the very file
  -- the advisory is about, so restarting into it is at best pointless and at
  -- worst hides the one message that tells the user what to do. The done view
  -- stays put and says it.
  if reaper.file_exists(RELAUNCHER_PATH) and #launcher_advisory == 0 then
    update.restart_after = time_precise() + 1.5
    update.restart_fired = false
  else
    update.restart_after = nil
  end
end

-- Resolve an interrupted apply at startup. Runs once, right after the
-- Updater module is defined (it needs local_path_for plus the pure-Lua
-- SHA block) and before the critical-file probe and remaining sidecar
-- dofiles, so a recovered install is what the rest of startup sees.
-- The stranded-.bak sweep near the top of the file skips itself
-- whenever a journal exists, so nothing this function needs has been
-- deleted by the time it runs.
--
-- Decision table:
--   * quarantined evidence already on disk -> stop before reading anything, on
--     this launch and every later one, until a verified repair clears it.
--     Nothing else does: the records live under Recovery/,
--     which Factory Reset's Data walk does not enter (B2.2d requirement 2).
--     Which stop depends on what is still at the journal path, because the
--     "invalid" report is also the offer of that repair and the repair has to
--     be able to start (Codex round 38, B2.3o:
--     Updater.gated_journal_disposition). Nothing there, or a record the
--     apply fence would permit -> "invalid". A record it would refuse, owned by
--     no live instance -> preserved beside the standing evidence, then
--     "invalid". A record another live instance is applying -> "skipped". A
--     record this body cannot read, and therefore cannot attribute or move ->
--     "unreadable", which stops the launch and offers nothing.
--     ASKED OF EACH OF THE TWO JOURNAL PATHS since B2.3p (Codex round 39), and
--     only a path this launch read for itself and found unused may move. The
--     primary and its .tmp are the two names journal_write swaps between, so a
--     launch that cannot account for one of them moves neither: a live owner
--     anywhere in the pair is "skipped" and an unreadable half is the
--     "unreadable" stop, in both cases with every byte where it lay. A half the
--     fence would permit is not in the way, so the record beside it still moves
--     and the offer is still true.
--     The reason is the same
--     one that stops the launch that quarantines: an unreadable record of a
--     transaction that touched this install means the install may be
--     half-swapped, and nothing has verified it since. Checking this FIRST
--     also means a journal that appears afterwards is left alone rather than
--     walked, which keeps the two records together for whoever reads them.
--   * no journal -> nothing to do
--   * a journal present but not one this body may walk (any field failing
--     Updater.journal_valid) -> mutate NOTHING, preserve the file as
--     evidence in its quarantine slot, and report "invalid" so the caller
--     stops the launch. Without trustworthy per-file statuses neither
--     direction is safe to automate, and continuing to load past a pending
--     update record nobody can read is the one option that is certainly
--     wrong: the install may be half-swapped.
--   * owner instance still live -> another REAPER process is mid-apply
--     on this shared install; leave everything alone this launch (the
--     startup call site exits the script for this case)
--   * phase "committed" -> the apply finished, only cleanup was
--     interrupted: delete leftover .baks and staging files, delete the
--     journal
--   * phase "rolling_back" -> a rollback was interrupted: complete the
--     rollback direction UNCONDITIONALLY (never roll a rolling_back
--     journal forward). When any restore fails (transient lock), or a
--     launcher's ownership question does not answer, the journal is KEPT
--     so the next launch retries the idempotent walk, and the result is
--     "incomplete" so the caller refuses to continue loading a possibly
--     mixed install. When a launcher IS confirmed to be someone else's and
--     that cannot be recorded, the walk stops before cleaning anything up
--     and returns "deferred" instead.
--   * phase "applying" -> roll FORWARD when every pending staged file
--     is present and hash-valid (finish the renames); otherwise flip
--     the phase to "rolling_back" first and complete the rollback. If
--     the phase marker cannot be written, nothing is mutated and the
--     launch is deferred. A pending entry whose record says its
--     destination was EMPTY, with a file sitting there now, stops the
--     roll-forward before it touches anything and returns "blocked":
--     that file is not this transaction's to move aside (Codex round 33).
--
-- Returns "none", "invalid", "repair", "skipped", "deferred", "incomplete",
-- "blocked", "unreadable", "finished", "forward", or "rollback". The startup
-- call site exits the launch on all of "skipped", "deferred", "incomplete",
-- "blocked", "unreadable" and "rollback"; "invalid" and "repair" end the
-- SESSION and hand what is left of the launch to the recovery surface's
-- verified repair; only "none", "finished" and "forward" continue into a
-- normal session.
--
-- EVERY COMPETING WRITER SHUT OUT FOR THE WHOLE OF IT (Codex round 40, B2.3q)
-- =============================================================================
-- The walk below reads records, decides from what it read whether they may be
-- moved, moves them, and writes journals of its own. Until B2.3q it did all of
-- that with nothing keeping another instance out, and the two are not
-- separable: a classification is a statement about a file at a moment, a rename
-- takes whatever is at the name at a later moment, and no arrangement of those
-- two calls makes them one. B2.3p narrowed the window to two adjacent
-- instructions and called the remainder unclosable. It is closable; the
-- primitive is just not a filesystem one. The updater has held an exclusive
-- apply lock since rounds 8-13, taken before any staging or journal mutation
-- and kept across the whole download/verify/apply pipeline, and this walk is
-- the ONLY other thing in the body that writes a journal. So it takes the same
-- lock, around the whole of itself, and every writer is excluded for the
-- complete classify-to-rename interval rather than for the last two lines of
-- it.
--
-- WHY THE WHOLE WALK RATHER THAN THE MOVERS. Three reasons, and the third is
-- the one that decides it. The invariant needs the classification that
-- justifies a move to be inside the exclusion, not just the move. The walk
-- itself WRITES journals (the rolling_back marker, a roll-forward's per-entry
-- status, a rollback's supersession), so an exclusion that covered only the
-- movers would leave this body's second writer outside the thing it is
-- excluded by, and an exclusion nobody's writers respect excludes nothing.
-- And there is exactly one entry to the walk, so one acquisition and one
-- release cover every road through it, including the ones that raise.
--
-- WHEN THE LOCK CANNOT BE HAD, which is the interesting refusal, and it comes
-- in two kinds. Two rounds of acquisition already reclaim a stale lock (a dead
-- or unreadable owner), so a lock still standing after that, with an OWNER at
-- the name, is a LIVE contender: another instance is mid-apply on this shared
-- install. That is a state the ratified matrix already has an answer for, and
-- the answer is to skip: touch nothing, promise nothing, and let the launch
-- after that instance finishes settle it. Same ending the live-owner branch
-- below reaches, same copy the user already gets.
--
-- A refusal with NOTHING at the name is the other kind: a lock this launch
-- could not CREATE. That is disk or permissions rather than company, and
-- telling that user another instance is applying would have them reopening
-- forever waiting for a process that does not exist. It ends as "deferred",
-- which already means recovery could not record its own state and asks for the
-- space or the rights. It is also the honest outcome on its merits: with no
-- lock there is nothing keeping a writer away from those records, so nothing
-- here may read them, move them or walk them.
--
-- With NOTHING at stake it ends as "none" instead, and that distinction is
-- deliberate rather than lenient. The lock is taken before the journal is
-- written, so it is held across the whole download, which can run for minutes
-- with no record on disk at all. Ending every launch during a neighbour's
-- download would stop a user opening a second REAPER window for a state that
-- has nothing to recover: no gate standing, nothing at either journal path,
-- and therefore no record this launch could move, walk or misjudge. Nothing is
-- mutated on that road, so nothing needs excluding; a record that arrives a
-- moment later belongs to the instance that is applying, and the launch after
-- this one reads it.
--
-- ONE MORE THING IS INHERITED RATHER THAN NEW. The lock's staleness rule is the
-- live-marker's fifteen seconds, so an instance whose marker goes stale mid-walk
-- can have its lock reclaimed under it. That bound is the same one every
-- live-owner question in this lane already rests on, it is the rounds 8-13
-- design, and B2.3q neither tightens nor relies on more than it.
function Updater.resolve_journal_at_startup()
  Updater._startup_missing_launcher_notice = nil
  if not Updater.acquire_apply_lock() then
    local standing = Updater.journal_quarantined()
    local present = Updater.journal_paths_live()
    if not (standing or #present > 0) then
      Log.line("UPDATE",
        "journal recovery: the exclusive apply lock could not be taken, and "
        .. "there is nothing at either journal path and no gate standing, so "
        .. "this launch has nothing to recover and continues.")
      return "none"
    end
    -- WHICH KIND OF REFUSAL IT WAS, because the two have different ways out
    -- and the same sentence is wrong for one of them. A refused acquisition
    -- with an OWNER at the name is a live contender: the acquisition's own two
    -- rounds already reclaimed a stale lock, so a lock still standing belongs
    -- to an instance whose live marker is fresh, and "another instance is
    -- applying, reopen in a moment" is both true and the thing to do. A
    -- refusal with NO owner at the name is a lock this launch could not
    -- CREATE, which is disk or permissions rather than company, and telling
    -- that user to wait for an instance that does not exist would leave them
    -- reopening forever. "deferred" is the ending that already means recovery
    -- could not record its own state and asks for the space or the rights.
    -- A THIRD KIND OF REFUSAL, AND IT IS THE ONE ONLY THE USER CAN END (Codex
    -- round 42, B2.3s). Since the reclaim rule became "never depose a living
    -- process", an acquisition can fail for a reason neither of the two below
    -- covers: a lock is standing, its recorded owner is not answering, and
    -- nothing here can prove whether that instance is alive or gone. Guessing
    -- alive strands this install until the user finds the file; guessing dead
    -- is the deposition this whole round removes. So it stops, names both the
    -- lock and the owner it recorded, and offers the clear only the person at
    -- the machine can authorize, which is the shape the quarantine gate has
    -- used for an undecidable state since B2.2c. The lock is left standing:
    -- evidence, not litter.
    if Updater._apply_lock_undecidable ~= nil then
      -- The ARTIFACT the acquisition found, not the base name it was built
      -- from (Codex round 43, B2.3t). The dialog below offers the user the
      -- removal, and on POSIX the thing standing is the claim DIRECTORY, so a
      -- record of the base path sent them looking for a file that was never
      -- created.
      Updater._startup_lock_path = Updater._apply_lock_undecidable_path
      Updater._startup_lock_kind = Updater._apply_lock_undecidable_kind
      Updater._startup_lock_owner = Updater._apply_lock_undecidable
      Log.line("UPDATE", string.format(
        (Updater._apply_lock_undecidable_kind == "blocked"
          and "journal recovery: nothing in %s can be seen from this launch, "
            .. "so whether another instance holds the exclusive apply lock "
            .. "cannot be decided here%s; %d record(s) at the journal path and "
            .. "the gate at %s are left exactly as they are and nothing is "
            .. "offered this launch."
          or "journal recovery: the exclusive apply lock at %s is held by %s "
            .. "and this launch cannot prove whether that instance is still "
            .. "running, so it was not reclaimed; %d record(s) at the journal "
            .. "path and the gate at %s are left exactly as they are and "
            .. "nothing is offered this launch."),
        tostring(Updater._apply_lock_undecidable_path or tmp.update_lock),
        (Updater._apply_lock_undecidable_kind == "blocked") and "" or
          tostring(Updater._apply_lock_undecidable ~= ""
            and Updater._apply_lock_undecidable
            or "an owner it could not read"),
        #present, tostring(standing or "(none)")))
      return "undecidable"
    end
    if Updater._lock_owner(tmp.update_lock) == nil then
      Log.line("UPDATE", string.format(
        "journal recovery: the exclusive apply lock could not be created at "
        .. "%s and nobody holds it, so nothing can keep a writer out of the "
        .. "%d record(s) at the journal path; nothing was read, moved or "
        .. "walked this launch.", tostring(tmp.update_lock), #present))
      return "deferred"
    end
    Log.line("UPDATE", string.format(
      "journal recovery: another instance holds the exclusive apply lock on "
      .. "this install, so it is mid-apply and every journal writer belongs "
      .. "to it; %d record(s) at the journal path and the gate at %s are "
      .. "left exactly as they are and nothing is offered this launch.",
      #present, tostring(standing or "(none)")))
    return "skipped"
  end
  -- Released on every road out, including the ones that raise: the walk is a
  -- long function with a dozen endings, and a lock left behind by one of them
  -- would stop this install updating until the process exits.
  local ok, outcome = pcall(Updater.resolve_journal_under_lock)
  Updater.release_apply_lock()
  if not ok then error(outcome, 0) end
  return outcome
end

-- The walk itself. Never called from anywhere but the acquisition above, and
-- everything in it (the gate's peek and adoption, the per-path classification,
-- both quarantine movers, the roll-forward, the rollback and every journal
-- write either of them makes) therefore runs with competing writers shut out.
--
-- FOR AS LONG AS THE LOCK IS STILL OURS, AND ASKED AT EVERY MUTATION (Codex
-- round 41, B2.3r). This walk runs before the main loop exists, so nothing else
-- is refreshing this instance's live marker while it works; a walk that outruns
-- the fifteen-second staleness bound, or a machine that sleeps in the middle of
-- one, used to have its lock reclaimed under it and carried on mutating beside
-- the instance that took it. `deposed` is the question, asked immediately
-- before every rename, removal and journal write on every road through here,
-- and the answer to yes is always the same: stop, mutate nothing further, and
-- end on "skipped", which is the ratified ending for another instance holding
-- the lock and which leaves every byte where the next launch can read it.
--
-- WHAT THE NEXT LAUNCH FINDS, at each point this can be discovered, and every
-- one of them is a shape the recovery vocabulary already carries:
--   mid-classification   nothing has moved, so the gate stands exactly as it
--                        stood and the records are at their own names; the next
--                        launch peeks, classifies and decides from scratch.
--   between the movers   the same, one preservation earlier or later: what
--                        reached the quarantine is evidence in the place
--                        evidence is kept, and what did not is still at the
--                        journal path for the next launch to set aside.
--   mid-roll-forward     entries that landed have "applied" on disk, because
--                        every status write happened while this walk still held
--                        the lock; an entry whose swap landed and whose status
--                        write was refused is exactly the rename-before-journal
--                        window this walk's own reclassification pre-pass
--                        closes, by hashing the destination.
--   mid-rollback         the rolling_back marker is on disk, restored entries
--                        have consumed their .bak and the rest still have
--                        theirs, which is precisely what makes complete_rollback
--                        idempotent; the next launch resumes it.
--   mid-cleanup          the record still says committed (or applying with
--                        everything applied), and the cleanup is a series of
--                        removals that do not care whether they already ran.
-- The instance that TOOK the lock meanwhile holds a journal path that may carry
-- this walk's partial work, and every state it can be in is one it already
-- knows: a readable record it walks by its phase, a record it cannot parse
-- which the validator refuses and the first-come lane preserves as evidence
-- behind the gate, or a primary and a .tmp sibling together, which is the
-- incomplete family both names of the quarantine already move as one episode.
function Updater.resolve_journal_under_lock()
  -- Are we still the instance that took this lock? Log once per discovery, then
  -- let the caller end. Nothing here retries: an authority that has been revoked
  -- stays revoked, because the classification this walk is holding is older than
  -- the theft.
  local said_deposed = false
  local function deposed()
    if Updater.journal_writers_excluded() then return false end
    if not said_deposed then
      said_deposed = true
      Log.line("UPDATE",
        "journal recovery: the exclusive apply lock this walk took is no "
        .. "longer this instance's, so another instance is now working on the "
        .. "same records; the walk stops here, changes nothing further and "
        .. "leaves everything exactly as it stands.")
    end
    return true
  end
  -- The standing quarantine gate, ahead of every other decision.
  local quarantined = Updater.journal_quarantined()
  local authorized = false
  local walk = nil
  if quarantined then
    -- One journal gets past it: the one the gate's own repair wrote, stamped
    -- with this quarantine's token (B2.2d requirement 5). Anything else --
    -- no journal, an unreadable one, or one carrying a token from a
    -- quarantine that has already been cleared -- leaves the gate exactly
    -- where it was, with the record and any later journal untouched.
    --
    -- Two things about this read, both from Codex round 20, blocker 2. It is a
    -- PEEK, so deciding whether to authorize a journal cannot move it: the
    -- adoption below happens after the token matched, never before. And the
    -- object it returns is the object that gets walked, passed to the walk
    -- rather than read again: a second read is a second file, and between the
    -- two of them a journal can be swapped for one carrying no token at all,
    -- which would then inherit this one's authorization.
    --
    -- And the identity judged against is the one the standing RECORD carries
    -- in its own name (Codex round 21, B2.2f fix 1, and round 22, B2.2g
    -- blocker 1), established here before anything is compared to it. It is
    -- recovered from the same listing that found the record, so a launch can
    -- only ever judge against the identity of the episode that is actually
    -- standing in front of it; there is no value on disk that could be read
    -- without its record, and so nothing left over from an episode that ended.
    -- A gate raised before the identity moved into the name carries none, and
    -- a launch that establishes none authorizes nothing, which leaves the gate
    -- exactly where it was and offers the repair again unstamped.
    --
    -- And the adoption that follows the match is PROVEN before anything walks
    -- (Codex round 21, B2.2f fix 2). An adoption that did not happen leaves
    -- the authorized journal at the .tmp path while a journal nobody vouched
    -- for sits at the one the walk's own cleanup deletes. So a failed adoption
    -- means the disk changed since the peek, and the answer is to peek again
    -- and re-run the authorization against what is actually there. Bounded at
    -- two passes: a second failure ends it with the gate standing, which is
    -- the same place a launch that authorizes nothing ends, and the repair is
    -- offered again on the next launch.
    local token = Updater.quarantine_episode_establish()
    local candidate = nil
    for _ = 1, 2 do
      local peeked, source = nil, nil
      if token then peeked, source = Updater.journal_peek() end
      authorized = peeked ~= nil and peeked.quarantine_token == token
      if not authorized then break end
      if deposed() then return "skipped" end
      if Updater.journal_adopt(source) then
        candidate = peeked
        break
      end
      authorized = false
    end
    if not authorized then
      -- NOTHING GETS PAST THE GATE, AND WHAT IS LEFT AT THE JOURNAL PATH
      -- DECIDES WHAT MAY BE PROMISED (Codex round 38, B2.3o blocker 2). This
      -- used to answer "invalid" over whatever was lying there, and "invalid"
      -- offers the full verified repair. A record the repair's own apply_start
      -- would refuse turns that offer into a loop with no exit in it. The
      -- reasoning behind each of these four answers is on
      -- Updater.gated_journal_disposition; what they have in common is that
      -- every one of them keeps every byte of evidence exactly where it can
      -- still be read.
      local disposition, plan, named_path, named_why =
        Updater.gated_journal_disposition()
      if disposition == "unreadable" then
        Updater._startup_unreadable_path = named_path
        Updater._startup_unreadable_record = quarantined
        Log.line("UPDATE", string.format(
          "journal recovery: a refused update record is preserved at %s, and a "
          .. "second record this body cannot read (%s) is at %s. There is "
          .. "nothing in it to say whose it is, so it and anything at the other "
          .. "journal path are left exactly where they lie, and the repair that "
          .. "would be refused over it is not offered.",
          tostring(quarantined), tostring(named_why), tostring(named_path)))
        return "unreadable"
      end
      if disposition == "live" then
        Log.line("UPDATE", string.format(
          "journal recovery: a refused update record is preserved at %s and "
          .. "another instance is mid-apply on this install (its record is at "
          .. "%s); that record is its recovery state and the other journal "
          .. "path is the other half of the swap it is in the middle of, so "
          .. "nothing here is moved and nothing is offered this launch.",
          tostring(quarantined), tostring(named_path)))
        return "skipped"
      end
      if disposition == "preserve" then
        if deposed() then return "skipped" end
        local moved = Updater.journal_quarantine_beside(plan)
        local still = Updater.journal_paths_in_the_way(plan)
        if #moved == 0 or #still > 0 then
          Log.line("UPDATE", string.format(
            "journal recovery: the record at the journal path would refuse the "
            .. "repair this gate offers, and %d of its path(s) could not be "
            .. "set aside (%s); %d that could stay preserved as evidence, "
            .. "nothing is offered this launch, and the next one tries the "
            .. "rest again.", #still, table.concat(still, ", "), #moved))
          return "deferred"
        end
        Updater._startup_setaside_record = moved[1]
        Log.line("UPDATE", string.format(
          "journal recovery: the record at the journal path belongs to no live "
          .. "instance and would refuse the repair this gate offers, so it was "
          .. "preserved as %s beside the evidence already standing, which was "
          .. "neither moved nor written over; the repair can start.",
          tostring(moved[1])))
      end
      Log.line("UPDATE",
        "journal recovery: a refused update record is still preserved at "
        .. tostring(quarantined) .. "; this install has not been verified "
        .. "since, so the launch stops here and nothing is swept or walked.")
      return "invalid"
    end
    walk = candidate
    Log.line("UPDATE",
      "journal recovery: the journal on disk carries this quarantine's "
      .. "repair token, so it is the repair this gate authorized; walking it "
      .. "to completion before the gate decides anything.")
  end
  local j, reason = walk, nil
  if not j then j, reason = Updater.journal_read() end
  if not j then
    -- "invalid" means a journal is present and this body must not walk it.
    -- Nothing is mutated, the file is preserved as evidence, and the caller
    -- stops the launch. It is NOT deleted: it is the only record of what the
    -- interrupted transaction was doing, on an install where something has
    -- already gone wrong.
    if reason == "invalid" then
      if deposed() then return "skipped" end
      Updater.journal_quarantine_all()
      return "invalid"
    end
    return "none"
  end
  if j.instance ~= RA.instance_file_suffix()
      and RA.temp_instance_is_live(j.instance) then
    Log.line("UPDATE", string.format(
      "journal recovery: owner %s is live (another instance mid-apply); "
      .. "skipping recovery and leaving the journal alone.",
      tostring(j.instance)))
    return "skipped"
  end

  -- EVERY LAUNCHER THIS TRANSACTION LEFT ALONE, AND WHY (Codex round 26,
  -- blocker 2). A skip is invisible to the serviceability gate by design: the
  -- launcher it protected is still sitting at the package root carrying the
  -- marker, so it IS serviceable and the gate says nothing about it. That is
  -- correct and it is also how this path lost the advisory. Ratified judgement 2
  -- made the message universal on an ordinary apply; recovery is not allowed to
  -- be the one ending where the user is never told.
  --
  -- Gathered from the journal as FOUND, not only from the decisions this walk
  -- makes, because most skips were decided by a session that then died: the
  -- apply writes the skip and crashes before its commit, and this launch is the
  -- first one in a position to say anything. That is why the reason is on the
  -- entry (skip_reason / skip_detail) rather than only in the memory of the
  -- process that made it.
  --
  -- Said by the walk that ENDS the transaction, never by one that stops early.
  -- A walk that defers has changed nothing about what the user still has to do,
  -- and the entries are still on disk for the launch that does finish.
  local left_alone = {}
  local function note_left_alone(reason, name, detail)
    left_alone[#left_alone + 1] =
      { name = name, reason = reason, detail = detail }
  end
  for _, jf in ipairs(j.files) do
    if jf.status == "skipped" and jf.root == "package" and jf.skip_reason then
      note_left_alone(jf.skip_reason, jf.name, jf.skip_detail)
    end
  end
  -- Hand them to the startup dialog, after whatever is already queued there
  -- rather than instead of it: a blocked launcher and a superseded one are two
  -- separate things the user has to know, and one must not swallow the other.
  local function say_left_alone()
    if #left_alone == 0 then return end
    Updater.launcher_notice_log(left_alone)
    local message = Updater.launcher_advisory_message(left_alone)
    if not message then return end
    local existing = Updater._startup_launcher_notice
    Updater._startup_launcher_notice = existing
      and (tostring(existing) .. "\n\n" .. message) or message
  end

  -- Every path this function touches comes from here, and it resolves the
  -- journal's names against the root the journal's own writer used, not
  -- against this body's app root (journal_root_dir). A recovery launch is
  -- exactly the moment a pre-restructure journal can still be lying around,
  -- and it is the one function that mutates files on its say-so.
  -- The two outcomes that mean the transaction reached its end going forward.
  -- When this walk was the gate's own authorized repair, that completion is
  -- what the gate was waiting for, so the record goes with it; a clear that
  -- will not happen leaves the gate up and reports "invalid" so the next
  -- launch offers the repair again (running it twice on a healthy install is
  -- safe: the full pass finds nothing to change).
  --
  -- THE THIRD ENDING (Codex round 25, B2.3 blocker 2). This is the one that
  -- used to clear directly. The other two endings establish that both actions
  -- that start ReaAssist are serviceable before they clear, and a repair that
  -- crashed at the right moment reached this one instead and cleared around an
  -- unserviceable launcher, losing the whole advisory with it. The same
  -- decision is made here, from the same function, with the same three
  -- answers, and it is made BEFORE the clear so a blocking answer costs the
  -- record nothing.
  --
  -- Two things are different about the context, and both are handled rather
  -- than assumed away. There is no fetched manifest yet, so the question of
  -- "does this release carry a replacement" is answered from the manifest the
  -- install itself carries (Updater.local_manifest_read), which is the same
  -- file every other launcher decision reads. And there is no recovery surface
  -- yet: this runs during startup resolution, before any of it exists. What
  -- DOES exist here is the dialog the invalid outcome already uses (reaper.MB,
  -- or OSARA on a Screen Reader launch), so both answers are handed to the
  -- startup block through Updater._startup_launcher_notice and it says them
  -- there. Blocking rides out on the "invalid" outcome, which is exactly the
  -- shape that keeps the record, stops the launch and offers the full repair;
  -- advisory rides out on the ordinary outcome, so the launch continues and
  -- the user is told what they still have to do. Nothing here schedules a
  -- restart in either case, which is the same standing-down the other two
  -- endings perform.
  local function completed(outcome)
    -- The gate comes down by RENAMING the anchor, which is a mutation like any
    -- other and one nothing else can undo. B2.3q left the clear outside its
    -- class because no journal moves in it; a deposed walk taking a gate down
    -- over another instance's work is the reason it is inside this one.
    if deposed() then return "skipped" end
    if not authorized then
      -- No gate to decide about, but a launcher this transaction left alone is
      -- still something the user has to be told, and an ordinary interrupted
      -- update is the commonest way to get one.
      say_left_alone()
      return outcome
    end
    local blocking, advisory =
      Updater.launcher_gate_state(Updater.local_manifest_read())
    if #blocking > 0 then
      Updater._startup_launcher_notice = Updater.launcher_blocked_message(blocking)
      say_left_alone()
      Log.line("UPDATE", string.format(
        "journal recovery: the authorized repair completed but %d unowned "
        .. "launcher(s) are still unserviceable (%s); the record was NOT "
        .. "cleared and the gate stays up.",
        #blocking, table.concat(blocking, ", ")))
      return "invalid"
    end
    local standing = select(2, Updater.journal_quarantine_clear())
      or Updater.journal_quarantined()
    if standing then
      Log.line("UPDATE",
        "journal recovery: the authorized repair completed but the record at "
        .. tostring(standing) .. " could not be removed; the gate stays up.")
      return "invalid"
    end
    -- Merged rather than appended on this path, so two findings about the same
    -- launcher are grouped into one paragraph by the message builder instead of
    -- read as two unrelated problems.
    for _, item in ipairs(left_alone) do advisory[#advisory + 1] = item end
    Updater._startup_launcher_notice =
      Updater.launcher_advisory_message(advisory)
    Updater.launcher_notice_log(advisory)
    Log.line("UPDATE",
      "journal recovery: the authorized repair completed (" .. outcome
      .. "); the preserved record is cleared and the gate is down.")
    return outcome
  end
  -- Takes the ENTRY, not the name. Since B2.3 an entry can carry root =
  -- "package", which is the only way a schema-2 journal can describe one of
  -- the two launchers rather than the App-relative file of the same name
  -- (journal_entry_path). Every path this walk mutates comes from here.
  local function path_for(jf) return Updater.journal_entry_path(j, jf) end
  local function package_launcher(jf)
    return jf.root == "package" or (j.schema == 1
      and (jf.name == "ReaAssist.lua"
        or jf.name == "ReaAssist_Screen_Reader_Mode.lua"))
  end
  local function exists(path)
    return reaper.file_exists and reaper.file_exists(path) or false
  end
  local function file_hash_ok(path, jf)
    local f = io.open(path, "rb")
    if not f then return false end
    local content = f:read("*a"); f:close()
    if not content then return false end
    return sha256_hash(content) == tostring(jf.sha256):lower()
  end
  -- Every staged path this walk touches comes from here, and it resolves
  -- against the ACQUISITION the record names as well as the root its writer
  -- used (Codex round 42, B2.3s). A record with no staging stamp was written by
  -- a body that staged into the bare sibling name, and that is what this
  -- answers for one.
  local function staged_for(jf) return Updater.journal_staged_path(j, jf) end
  local function staged_hash_ok(jf)
    return file_hash_ok(staged_for(jf), jf)
  end
  -- Older readers reject a schema-1 entry marked skipped. Removing an entry
  -- records the same loss of authority using vocabulary those readers accept.
  -- Write even an empty list before deleting sidecars. journal_delete alone
  -- does not verify that the record disappeared from disk.
  local function prune_legacy_launchers(pruned)
    local previous, remaining = j.files, {}
    for _, jf in ipairs(previous) do
      if not pruned[jf] then remaining[#remaining + 1] = jf end
    end
    if #remaining == #previous then return true end
    if deposed() then return false, "skipped" end
    j.files = remaining
    if not Updater.journal_write(j) then
      j.files = previous
      return false, deposed() and "skipped" or "deferred"
    end
    for _, jf in ipairs(previous) do
      local owner = pruned[jf]
      if owner then
        if deposed() then return false, "skipped" end
        if not owner.completed then
          note_left_alone(Updater.launcher_left_alone_reason(
            jf.status == "pending" and "skipped" or "superseded",
            owner.state), jf.name, owner.detail)
        end
        os.remove(path_for(jf) .. ".bak")
        os.remove(staged_for(jf))
      end
    end
    return true
  end
  local function missing_legacy_launcher(jf, state, detail)
    Updater._startup_missing_launcher_notice = Updater.launcher_advisory_message({
      { name = jf.name, reason = state == Updater.OWNERSHIP_OWNED
          and "reapack" or "foreign", detail = detail },
    })
    return "incomplete"
  end
  -- Use a separate work list because a late ownership change can remove an
  -- entry from the durable journal. Under schema 1, settle launcher entries
  -- before body entries so a deferred launcher does not hand recovery to an
  -- older App body. Preserve the existing order for schema 2.
  local function recovery_entries(reverse)
    local ordered = {}
    local function append(launchers, main)
      for n = 1, #j.files do
        local jf = j.files[reverse and (#j.files - n + 1) or n]
        if launchers == nil or (package_launcher(jf) == launchers
            and (main == nil or (jf.name == "ReaAssist.lua") == main)) then
          ordered[#ordered + 1] = jf
        end
      end
    end
    if j.schema == 1 then
      -- The old flat main entrypoint can itself load an older recovery reader.
      -- Resolve the Screen Reader wrapper before restoring that entrypoint.
      append(true, false); append(true, true); append(false)
    else
      append(nil)
    end
    return ordered
  end
  -- THE ONE PLACE THIS WALK ENDS ON "blocked" (Codex round 33, extended in
  -- rounds 34, 35 and 36). The outcome means one thing throughout: recovery
  -- could not act at a destination it had to act at, nothing of that entry was
  -- touched, and the user is the only one who can clear it. Every kind that
  -- reaches it shares the way out as well, and it is the same one: move the
  -- file, and the launch after that reaches an ending. WHICH ending differs,
  -- and that is what the kinds are for. The kind travels out beside the path
  -- and the startup dialog picks the sentences; one exit rather than three, so
  -- the outcome cannot drift between its callers.
  --
  -- "appeared" is round 33's: a destination the record says was empty, with
  -- something at it now, in front of a roll-forward that would have backed the
  -- stranger up and deleted the backup. "changed" is round 34's: a destination
  -- this transaction WROTE, holding something that is not what it wrote, in
  -- front of an UNDO that would have restored over it. "changed_cleanup" is
  -- that same finding in the forward direction, and round 36 made it a kind of
  -- its own because the two do not share a last sentence. The undo still holds
  -- the file it means to put back, so moving the stranger away lets the very
  -- next launch finish the rollback. The cleanup spent its copy at the swap:
  -- the .new became the installed file, so once the stranger is moved there is
  -- nothing on this computer left to land, and what finishes it is the verified
  -- repair the launch after that offers (repair_instead below).
  local function blocked_on(path, kind)
    Updater._startup_blocked_path = path
    Updater._startup_blocked_kind = kind
    return "blocked"
  end
  -- WHERE A CLEANUP THAT CANNOT FINISH ACTUALLY ENDS (Codex round 36, B2.3m).
  --
  -- Round 35 stopped the cleanup over a destination whose file is GONE, and it
  -- stopped it for the right reason: the .bak is the only copy of what was
  -- there, the record is the only account that anything was written, and
  -- deleting both is not what a missing installed file deserves. What that stop
  -- had no way to offer was an ending. The entry is applied, so its payload
  -- copy was consumed by the swap that landed it, and no walk over this record
  -- can put the file back from anything on disk. Telling the user to restore it
  -- and reopen only works while they still have it; a file antivirus took is
  -- one they usually do not.
  --
  -- The one thing that CAN put it back is the lane the arc already built for an
  -- install nothing has vouched for: preserve the record as evidence, raise the
  -- quarantine gate, and let this launch continue into the recovery surface,
  -- whose full pass checks every installed file against the current release and
  -- downloads and verifies a fresh copy of whatever is missing or does not
  -- match. It heals to the LATEST release, which is the standing decision of
  -- record for every repair, and it ends where every other repair ends: the
  -- commit point clears the preserved record and the gate comes down.
  --
  -- Quarantining is not an aside, it is what makes the offer reachable. A live
  -- record at the journal path would refuse the repair's own apply, and a
  -- record simply deleted would be the data loss round 35 closed. The slot
  -- keeps it durably, out of reach of Factory Reset and the Temp sweep, and it
  -- also keeps the .bak and .new files of every entry, because the stranded
  -- sidecar sweep stands down for exactly as long as a quarantined record does.
  -- Nothing of this transaction is thrown away; it stops being something a walk
  -- acts on and becomes something a verified repair supersedes.
  --
  -- What this gives up is disclosed rather than glossed: no later walk resumes
  -- this transaction, so a roll-forward that had entries still to land abandons
  -- them here. That is the trade taken deliberately. The repair's guarantee is
  -- the wider one, because it checks every entry in the manifest rather than
  -- the ones this record happens to name, and an entry left un-landed is a
  -- mismatch it repairs like any other. It is also the last moment any walk
  -- reads this record, so a launcher this transaction left alone is said HERE
  -- or never.
  --
  -- A GATE ALREADY STANDING TAKES THE OTHER ROAD, NOT A DIFFERENT ENDING
  -- (Codex round 37, B2.3n). This walk being the repair an earlier refusal
  -- authorized is the ordinary case, not an exception: the gate stands, its
  -- token is in this journal's own field, and the walk has just found the one
  -- thing no walk over this record can mend. B2.3m read the first-come rule as
  -- a reason to leave the journal live and say "invalid", which offers the same
  -- repair again. It offered a repair that could not start. The record was
  -- still at the journal path, apply_start weighs a live record with
  -- journal_changed_nothing, a committed one is the opposite of a record that
  -- changed nothing, and the attempt died at apply_unresolved with the user
  -- having done exactly what they were told.
  --
  -- First-come is about the standing record's NAME and bytes, and nothing here
  -- asks for either: journal_quarantine_beside puts this record into the same
  -- anchor under the second head, carrying the standing episode's identity, so
  -- the evidence closest to the fault is untouched, the gate is exactly as up
  -- as it was, and the repair starts against a journal path with nothing in it.
  -- The ending is therefore the SAME ending the ungated hand-off reaches, and
  -- the left-alone notice is said here too: this walk is the last one that ever
  -- reads this record, so a launcher it left alone is said now or never.
  --
  -- ONE WAY TO DECLINE IS LEFT, and it is the one round 37 ruled sound. A
  -- rename this filesystem will not do leaves the record live wherever the gate
  -- stands or not, the repair's apply would be refused over it, and "deferred"
  -- already means recovery could not record its own state and asks for the disk
  -- space or the permissions that would let the next launch get this far.
  -- Nothing may be claimed on that path, including by a gate that happens to be
  -- standing for an older reason.
  --
  -- HALF A PRESERVATION IS NOT A PRESERVATION (Codex round 38, B2.3o blocker
  -- 1). Both lanes move the primary and its .tmp sibling as two separate
  -- renames, so one can land while the other is refused, and this hand-off used
  -- to promise the repair whenever ANY record moved. The leftover then rebuilt
  -- the exact wall: apply_start READS a primary and ADOPTS a .tmp, they are
  -- different leftovers and neither is harmless, and a record that changed
  -- something is refused at apply_unresolved either way. So the claim is made
  -- on the disk rather than on a count, and it is all or nothing: every live
  -- journal path clear, or nothing is promised at all.
  --
  -- What already moved STAYS MOVED. A record that reached the quarantine is
  -- evidence in the place evidence is kept, and moving one back would be the
  -- one thing this lane never does. So the honest answer for a half-cleared
  -- pair is "deferred", which already means recovery could not record its own
  -- state and asks for the disk space or the permissions: the next launch finds
  -- the leftover still at its own path, sets it aside beside the half that went
  -- first, and reaches the repair for real.
  local function repair_instead(dest)
    if deposed() then return "skipped" end
    Updater._startup_repair_path = dest
    local moved, plan = {}, nil
    if Updater.journal_quarantined() then
      -- The same per-path attribution the gated branch uses (Codex round 39,
      -- B2.3p). This walk read and finished with the record at the PRIMARY
      -- path; whatever is at the .tmp beside it is a file nothing here has
      -- opened, and the mover used to carry it off regardless. So both names
      -- are classified, only what is proven readable and unused moves, and a
      -- sibling that is neither leaves this launch with nothing to promise.
      local disposition
      disposition, plan = Updater.gated_journal_disposition()
      if disposition == "preserve" then
        moved = Updater.journal_quarantine_beside(plan)
      end
    else
      moved = Updater.journal_quarantine_all()
    end
    local still = Updater.journal_paths_in_the_way(plan)
    if #moved > 0 and #still == 0 then
      -- The record THIS transaction left, which on the gated path is not the
      -- one the gate reports: that one belongs to the refusal that raised the
      -- gate, and the dialog is describing this one.
      Updater._startup_repair_record = moved[1]
      say_left_alone()
      Log.line("UPDATE", string.format(
        "journal recovery: nothing on disk can put %s back, so the record was "
        .. "preserved as %s and this launch continues into the verified repair "
        .. "instead of stopping; every backup and staged copy is kept with it.",
        tostring(dest), tostring(moved[1])))
      return "repair"
    end
    Log.line("UPDATE", string.format(
      "journal recovery: %s cannot be put back from anything on disk, and %d "
      .. "of this record's path(s) are still live (%s), so the verified repair "
      .. "is not offered this launch; %d path(s) that did move stay preserved "
      .. "as evidence and the next launch tries the rest again.",
      tostring(dest), #still, table.concat(still, ", "), #moved))
    return "deferred"
  end
  -- THE SAME QUESTION GOING FORWARD (Codex round 34, B2.3k blocker 1), where
  -- the only thing at stake is our own sidecars and the only thing that removes
  -- them is the cleanup at the end. A destination this transaction landed, with
  -- something else at it now, gets its .bak deleted and then its record deleted
  -- on top, so the one account of what the file used to be goes with the one
  -- account that anything was ever written there.
  --
  -- HASH FIRST HERE, OWNERSHIP ONLY ON A MISMATCH, and that order is the
  -- opposite of the one both rollbacks use because the question each of them
  -- can answer is different. In the undo direction ownership has to come first,
  -- since a launcher somebody else owns must not be written whatever it
  -- contains. Here nothing is written at all, so a hash that MATCHES settles it
  -- outright: the bytes are the ones this transaction put there, whoever the
  -- registry thinks owns the name. Only a mismatch needs the second question,
  -- and at the package root it is the one that tells a ReaPack synchronization
  -- apart from a stranger. Everywhere else there is no owner to ask about and a
  -- mismatch is a stranger on its own.
  --
  -- A VERIFIED DESTINATION IS THE ONLY ONE A CLEANUP MAY FINISH OVER (Codex
  -- round 35, B2.3l). "ours" is the whole of the permission here. Round 34 let
  -- an ABSENT destination through on the reasoning that a file that is not
  -- there is nothing to protect, and in the undo direction that is right: the
  -- rollback puts the .bak back INTO the empty name, so the user ends up
  -- holding their own file either way. Going forward there is no such landing.
  -- The cleanup deletes the .bak and then the record on top, so an installed
  -- file that DISAPPEARED would be finalized as a finished update with its one
  -- recovery copy thrown away, and the record that said anything was ever
  -- written there thrown away with it. A missing installed file is not a
  -- success. It stops, in both of the shapes it comes in and for a reason in
  -- each: with bak_existed true the .bak IS the user's previous launcher or
  -- sidecar and it is the only copy left, and on a fresh add there is no backup
  -- to lose but finalizing a record whose file is missing still writes down
  -- something untrue about the install. Since round 36 that stop hands the
  -- launch to the verified repair rather than ending it, because no walk over
  -- this record can put a consumed payload back (repair_instead).
  --
  -- Returns nil when nothing is standing in the way, or the outcome this walk
  -- must end on. `at_removal` says which of the two moments is asking, which
  -- changes nothing about the answer and only what the log can honestly claim.
  local function forward_dest_stop(jf, dest, at_removal)
    local verdict = Updater.applied_dest_verdict(dest, jf.sha256)
    if verdict == Updater.DEST_STRANGER and package_launcher(jf) then
      local _, state, detail = Updater.launcher_writable_now(jf.name)
      if state == Updater.OWNERSHIP_OWNED
          or state == Updater.OWNERSHIP_FOREIGN then
        -- ReaPack synchronized over the launcher this transaction landed.
        -- Not a stranger, and nothing here touches the file: the cleanup
        -- removes this body's own backup and staged copy, which is exactly
        -- what a superseded backup is for.
        verdict = Updater.DEST_OURS
        Log.line("UPDATE", string.format(
          "journal recovery: %s is no longer the copy this update landed, "
          .. "but it has an owner (%s: %s), so the roll-forward treats it "
          .. "as theirs rather than as a file nobody can account for.",
          jf.name, tostring(state), tostring(detail)))
      elseif state ~= Updater.OWNERSHIP_UNOWNED then
        -- No finding either way, so there is no telling a synchronization
        -- from a stranger. Nothing is cleaned up and the next launch asks
        -- again.
        verdict = Updater.DEST_UNVERIFIABLE
      end
    end
    if verdict == Updater.DEST_OURS then return nil end
    -- Deliberately NOT asked of an absent package-root destination. Who owns
    -- the name says nothing about a file that is not at it, and the answer
    -- would not change what happens: a launcher this transaction landed and
    -- that is gone now leaves the action ReaAssist starts from dead whether
    -- ReaPack has since claimed the name or not.
    if verdict == Updater.DEST_ABSENT then
      Log.line("UPDATE", string.format(
        "journal recovery: %s is not there at all, and this update's own "
        .. "record says it wrote a file at that name, so the cleanup stopped "
        .. "%s rather than finish an update over a file that is missing; the "
        .. "record, its backup and its staged copy were kept.", dest,
        at_removal and "at the moment it was about to remove that entry's "
          .. "backup" or "before anything of the transaction moved"))
      return repair_instead(dest)
    end
    if verdict == Updater.DEST_STRANGER then
      Log.line("UPDATE", string.format(
        "journal recovery: %s is not the file this update put there, so the "
        .. "cleanup stopped %s; that file was not touched, and the record, "
        .. "its backup and its staged copy were kept along with those of "
        .. "every entry behind it.", dest,
        at_removal and "at the moment it was about to remove that entry's "
          .. "backup" or "before anything of the transaction moved"))
      return blocked_on(dest, "changed_cleanup")
    end
    Log.line("UPDATE", string.format(
      "journal recovery: could not establish that %s is still the file "
      .. "this update put there, so nothing further was cleaned up and the "
      .. "record was kept for the next launch.", dest))
    return "incomplete"
  end
  -- Asked AHEAD of everything, for the reason round 33 ratified about the other
  -- pre-pass: nothing of the transaction moves, no rename, no backup, no
  -- deletion, not one journal write, so the record stays a record the next
  -- launch will start over from and the stop can honestly say nothing changed.
  -- That is what this pass is FOR, and it is why it survives round 35 rather
  -- than being replaced by the per-entry check below: it buys the honest
  -- nothing-was-changed copy in the common case, and the ownership-first
  -- classification round 35 ratified is anchored in it.
  local function forward_dests_ok()
    for _, jf in ipairs(j.files) do
      if jf.status == "applied" then
        local halted = forward_dest_stop(jf, path_for(jf), false)
        if halted then return halted end
      end
    end
    return nil
  end
  -- AND ASKED AGAIN, PER ENTRY, IMMEDIATELY BEFORE EACH REMOVAL (Codex round
  -- 35, B2.3l). The pre-pass answers for the moment it ran, and in the
  -- roll-forward that moment is before the pending-entry loop: every remaining
  -- swap happens after it, and the world keeps running while they do. A
  -- destination that passed the pre-pass and was replaced inside that window
  -- reached this cleanup as a stranger with its permission already granted,
  -- which is the same A-to-B-and-back the hash gate exists to close, one layer
  -- further out. So the permission is not carried: each entry's answer is taken
  -- fresh, at the instant its .bak is about to go, which is the last moment at
  -- which an answer can mean anything.
  --
  -- WHAT A STOP HERE CAN AND CANNOT PROMISE. Everything from the stopping entry
  -- onward is untouched: its backup, its staged copy, every later entry's, and
  -- the record, which is deliberately not deleted so the next launch walks the
  -- same ground and stops the same way (or finishes, once the user has cleared
  -- it). The sidecars already removed for the entries ahead of it are gone, and
  -- they are not coming back. Each of those was verified at its own moment of
  -- removal, which is the most any sequential walk can promise: the alternative
  -- is a walk that verifies everything and then removes everything, which just
  -- moves the same window somewhere else. The dialog is worded to that promise
  -- rather than to the stronger one the pre-pass can make.
  --
  -- Twice over the same file in the common case, and that is accepted: this
  -- runs on the rare crash-recovery launch, the hash is single-shot pure Lua,
  -- and the entries the mutation loop just landed were pending when the
  -- pre-pass ran, so they are hashed here for the first time.
  --
  -- Returns nil once the cleanup has finished and the record is gone, or the
  -- outcome this walk must end on.
  local function cleanup_sidecars()
    for _, jf in ipairs(j.files) do
      -- Before this entry's two removals, not once for the loop: the hash the
      -- stop below takes is the slowest thing on this road, and a pass over a
      -- large record is exactly the walk that can outlive its own liveness.
      if deposed() then return "skipped" end
      local dest = path_for(jf)
      -- Only what this transaction actually WROTE. A skipped entry's
      -- destination belongs to somebody else, its .bak (if the undo direction
      -- left one) is this body's own and no longer usable, and there is nothing
      -- about the file at that name for this question to be right or wrong
      -- about.
      if jf.status == "applied" then
        local halted = forward_dest_stop(jf, dest, true)
        if halted then return halted end
      end
      os.remove(dest .. ".bak")
      os.remove(staged_for(jf))
    end
    -- The record goes last, and only if it is still ours to remove. A refused
    -- deletion is not a finished cleanup, and reporting one would let the caller
    -- claim a completion over a record another instance is now holding.
    if not Updater.journal_delete() then return "skipped" end
    return nil
  end
  -- Ask every legacy launcher before applying or undoing entries. Committed
  -- recovery only cleans sidecars and retains its existing destination checks.
  -- An unavailable answer must leave the current recovery body in place.
  if j.schema == 1 and j.phase ~= "committed" then
    local pruned = {}
    for _, jf in ipairs(j.files) do
      if package_launcher(jf) then
        local writable, state, detail = Updater.launcher_writable_now(jf.name)
        if not writable then
          if state ~= Updater.OWNERSHIP_OWNED
              and state ~= Updater.OWNERSHIP_FOREIGN then
            return "incomplete"
          end
          if not exists(path_for(jf)) then
            return missing_legacy_launcher(jf, state, detail)
          end
          pruned[jf] = { state = state,
            detail = detail and tostring(detail):sub(1, 200) or nil }
        end
      end
    end
    local saved, outcome = prune_legacy_launchers(pruned)
    if not saved then return outcome end
  end
  local touched_context = false
  for _, jf in ipairs(j.files) do
    if jf.name == "Resources/Context.lua" then touched_context = true end
  end

  if j.phase == "committed" then
    -- Everything applied; only the post-commit cleanup was cut short. Which is
    -- the same cleanup, over the same applied destinations, as the one at the
    -- end of the roll-forward, so it asks the same questions in the same order.
    -- Codex named three sites and this is a fourth with the identical shape:
    -- leaving it out would mean a crash in the window between the commit and
    -- its cleanup is the one way to still lose the file.
    --
    -- Both passes, not just the second. Nothing of this transaction is left to
    -- move here, so the pre-pass can still make the promise it makes on the
    -- other path (nothing at all was changed) for every install where the
    -- trouble was already standing when the launch began, and the per-entry
    -- check is what covers a destination that goes while this very loop is
    -- walking.
    local halted = forward_dests_ok()
    if halted then return halted end
    halted = cleanup_sidecars()
    if halted then return halted end
    Log.line("UPDATE",
      "journal recovery: finished committed apply cleanup for v"
      .. tostring(j.target_version))
    return completed("finished")
  end

  -- Shared rollback completion for phase "rolling_back", whether the
  -- marker was written by the runtime rollback or by this function's
  -- own applying-phase fallback below. The phase forces the direction:
  -- complete the rollback unconditionally, never roll forward.
  -- Per-entry statuses flip BEFORE their mutation, so an entry's status
  -- alone cannot say whether its restore already happened; the .bak's
  -- presence can. Deliberately NOT hash-based: for a file whose content
  -- is identical across versions (exactly what the locked-file update
  -- path queues defensively), "restored" and "not restored" hash the
  -- same, and guessing wrong deletes the only copy. The .bak is
  -- consumed by the restoring rename, so its presence is the
  -- unambiguous not-yet-restored signal, which also makes this walk
  -- idempotent: a retry after a partial pass redoes only what is left.
  local function complete_rollback()
    local restore_failures = 0
    -- THE OWNERSHIP FENCE, IN THIS DIRECTION TOO (Codex round 26, blocker 1B).
    --
    -- This walk performs the same package-root writes the runtime rollback
    -- performs, on a LATER launch, which is if anything more exposed: a whole
    -- REAPER session may have synchronized ReaPack since the crash. Restoring a
    -- .bak over a launcher ReaPack now owns deletes ReaPack's current file and
    -- puts an older one in its place; deleting a fresh add that ReaPack has
    -- since adopted deletes it outright. Neither is this body's to do.
    --
    -- Asked ONLY where a mutation is actually about to happen, which is why it
    -- is a call inside each branch rather than a branch of its own. An entry
    -- with nothing left to undo (its .bak already consumed) is not probed and
    -- is not reported, because nothing was left alone: the rollback for that
    -- entry finished before the crash.
    --
    -- A launcher CONFIRMED to be someone else's is recorded skipped with its
    -- reason, its own now-unusable .bak is dropped, and the walk carries on. It
    -- is NOT a restore failure: nothing here will ever succeed on a retry, so
    -- counting it would keep the journal forever and gate every launch on a
    -- file this body is forbidden to touch.
    --
    -- THE TWO THINGS THAT MUST BOTH BE TRUE BEFORE THE BACKUP GOES (round 27),
    -- and they are the same two the runtime rollback observes.
    --
    -- A CONFIRMED answer. Unknown is the API failing, not another owner
    -- appearing, and abandoning the user's previous launcher on the strength of
    -- a call that did not answer is exactly the fail-open this fence exists to
    -- close. Unknown therefore DEFERS the entry whole: status untouched, .bak
    -- untouched, staging untouched, journal kept, and the walk ends
    -- "incomplete" so the launch stops and the next one asks again. The rest of
    -- the rollback still runs for every entry whose answer is confirmed.
    --
    -- A DURABLE record. On a false from journal_write nothing at all is cleaned
    -- up: the entry is put back the way it was found, the .bak stays, the
    -- staging stays, the journal stays as it is on disk, and the walk stops on
    -- "deferred" -- the same stop-before-cleanup rule the roll-forward below
    -- already follows, for the same reason. A skip that is dropped instead
    -- leaves an "applied" entry with no backup, and the launch after that hands
    -- a fresh-add launcher to a fence that may by then answer unowned.
    local deferrals = 0
    local deferred_now = nil
    local stop_now = false
    local blocked_now = nil
    -- AND THE FILE ITSELF, ONCE OWNERSHIP HAS SPOKEN (Codex round 34, B2.3k
    -- blocker 1). may_write asks who owns this name; this asks whether the
    -- bytes at it are still the ones the interrupted transaction wrote. Both
    -- have to answer before a restore deletes what is standing there, and the
    -- order is not interchangeable: a launcher ReaPack synchronized over is not
    -- a stranger, and may_write has already left it alone and dropped its
    -- backup by the time this is reached. So every destination that gets here
    -- is one nobody else claims, and a mismatch on one of those is a file this
    -- body has no account of.
    --
    -- Called only from the branches that WRITE. An entry with nothing left to
    -- undo is not read, exactly as it is not probed for ownership, and the two
    -- shapes that legitimately hold something other than the payload are
    -- excluded by the branch conditions rather than by a special case here: a
    -- restore that already happened has consumed its .bak, and a fresh add that
    -- was already deleted has no destination left to read.
    local function dest_is_ours(jf, dest)
      local verdict = Updater.applied_dest_verdict(dest, jf.sha256)
      if verdict == Updater.DEST_OURS or verdict == Updater.DEST_ABSENT then
        return true
      end
      if verdict == Updater.DEST_STRANGER then
        -- The walk stops on this one, before its own mutation and before its
        -- staging goes. Nothing is recorded, because nothing was decided.
        blocked_now = dest
        Log.line("UPDATE", string.format(
          "journal recovery: %s is not the file the interrupted update put "
          .. "there, so the rollback stopped without touching it; its backup, "
          .. "its staged copy and the record were all kept.", dest))
        return false
      end
      -- Unreadable is a lock, not a stranger, and a lock is the failure this
      -- walk already knows how to wait out: leave the entry, its backup and its
      -- status exactly as they are, keep the journal, ask again next launch.
      restore_failures = restore_failures + 1
      Log.line("UPDATE", string.format(
        "journal recovery: could not read %s to check that it is still the "
        .. "file the interrupted update put there (locked?), so the rollback "
        .. "left it, its backup and its entry exactly as they are.", dest))
      return false
    end
    local function may_write(jf, bak)
      if not package_launcher(jf) then return true end
      local writable, state, detail = Updater.launcher_writable_now(jf.name)
      if writable then return true end
      local said = detail and tostring(detail):sub(1, 200) or nil
      if state ~= Updater.OWNERSHIP_OWNED
          and state ~= Updater.OWNERSHIP_FOREIGN then
        deferrals = deferrals + 1
        deferred_now = jf
        note_left_alone(Updater.launcher_left_alone_reason("deferred", state),
          jf.name, said)
        Log.line("UPDATE", string.format(
          "journal recovery: could not find out who owns %s (%s: %s), so the "
          .. "rollback left it, its backup and its entry exactly as they are; "
          .. "the journal is kept and the next launch asks again.",
          jf.name, tostring(state), tostring(detail)))
        return false
      end
      if j.schema == 1 then
        if not exists(path_for(jf)) then
          missing_legacy_launcher(jf, state, said)
          deferrals = deferrals + 1
          deferred_now = jf
          return false
        end
        local saved, outcome = prune_legacy_launchers({ [jf] = { state = state,
          detail = said } })
        if not saved then stop_now = outcome end
        return false
      end
      local was, was_reason, was_detail = jf.status, jf.skip_reason,
        jf.skip_detail
      jf.status      = "skipped"
      jf.skip_reason = Updater.launcher_left_alone_reason("superseded", state)
      jf.skip_detail = said
      if not Updater.journal_write(j) then
        jf.status, jf.skip_reason, jf.skip_detail = was, was_reason, was_detail
        stop_now = true
        Log.line("UPDATE", string.format(
          "journal recovery: %s is no longer this body's to put back, but that "
          .. "could not be recorded; leaving the journal, its backup and all "
          .. "staging exactly as found (rollback deferred, and the next launch "
          .. "asks again).", jf.name))
        return false
      end
      note_left_alone(jf.skip_reason, jf.name, jf.skip_detail)
      -- Only once the supersession is on disk. Before that, this backup is
      -- still the only copy of the launcher the user had, and the entry that
      -- would send a later walk looking for it still says so.
      os.remove(bak)
      Log.line("UPDATE", string.format(
        "journal recovery: %s is no longer confirmed unowned (%s: %s), so the "
        .. "rollback left it as it stands and dropped its backup; the rest of "
        .. "the rollback continues.", jf.name, tostring(state),
        tostring(detail)))
      return false
    end
    for _, jf in ipairs(recovery_entries(true)) do
      -- Every restore, every backup drop and every fresh-add removal below is a
      -- mutation, so the question comes before the entry rather than before the
      -- loop. A rollback stopped between two entries is the shape this walk is
      -- built to resume: the marker is on disk, the .bak beside an entry says
      -- its restore has not happened, and the next launch reads both.
      if deposed() then return "skipped" end
      local dest   = path_for(jf)
      local staged = staged_for(jf)
      local bak    = dest .. ".bak"
      deferred_now = nil
      if jf.status == "skipped" then
        -- A destination this body may not write, whichever fence said so. The
        -- forward fences reach it before any backup was taken, so there is
        -- nothing to undo; the backward ones reach it after a swap landed and
        -- drop the backup as they go. Saying so explicitly matters, because the
        -- fresh-install branch further down deletes a dest whose entry has no
        -- backup, and the dest here is the file the skip exists to protect.
        --
        -- The .bak goes here and the staged copy goes at the bottom of this
        -- loop, like every other entry's. The backup is ours and only ours (the
        -- launcher itself is untouched), it can no longer be put anywhere, and
        -- leaving one behind would have the NEXT walk read "restore not yet
        -- performed" about a restore that must never happen. That is also what
        -- makes a rollback whose skip write was lost mid-crash converge: the
        -- fence runs again and reaches the same place.
        os.remove(bak)
      elseif jf.status == "pending" then
        -- Never touched by the apply; only the apply-side mid-swap
        -- edge (dest moved aside, rename-back failed) needs undoing.
        if not exists(dest) and exists(bak) and may_write(jf, bak) then
          if not os.rename(bak, dest) then
            restore_failures = restore_failures + 1
            Log.line("UPDATE", string.format(
              "journal recovery: could not restore mid-swap %s from "
              .. "its .bak (.bak left on disk; retried next launch)",
              dest))
          end
        end
      elseif exists(bak) then
        -- Restore not yet performed (bak unconsumed): finish it.
        if may_write(jf, bak) and dest_is_ours(jf, dest) then
          os.remove(dest)
          if not os.rename(bak, dest) then
            restore_failures = restore_failures + 1
            Log.line("UPDATE", string.format(
              "journal recovery: could not restore %s from its .bak "
              .. "(.bak left on disk; retried next launch)", dest))
          end
        end
      elseif exists(dest) and jf.bak_existed == false then
        -- Fresh-install add whose rollback (plain delete) had not
        -- happened yet. A failed delete on a still-present file is a
        -- lock, so it counts as a restore failure too.
        if may_write(jf, bak) and dest_is_ours(jf, dest) then
          if not os.remove(dest) and exists(dest) then
            restore_failures = restore_failures + 1
            Log.line("UPDATE", string.format(
              "journal recovery: could not remove fresh-install add %s "
              .. "(locked; retried next launch)", dest))
          end
        end
      end
      -- else: already restored (bak consumed, or fresh add already
      -- deleted); leave dest alone.
      --
      -- The stop leaves this iteration's staging alone too, which is the whole
      -- of "nothing is cleaned up": the .new is recovery state like the .bak
      -- and the journal, and a walk that could not record what it did has no
      -- business deleting any of the three.
      if stop_now then break end
      -- A stranger stops it the same way, and for a stronger reason: the file
      -- standing at that destination belongs to somebody, and every piece of
      -- evidence about what was there before it has to survive until they say
      -- what to do with it.
      if blocked_now then break end
      if j.schema == 1 and package_launcher(jf)
          and (deferred_now or restore_failures > 0) then break end
      if j.schema == 1 and package_launcher(jf) then
        -- A finished launcher undo must not remain an older reader's work.
        -- In particular, that reader would delete a fresh add again if
        -- ReaPack recreated it between this rollback and the next startup.
        local saved, outcome = prune_legacy_launchers({ [jf] = { completed = true } })
        if not saved then
          stop_now = outcome
          break
        end
      end
      -- A deferred entry keeps its staging as well. Nothing about that entry
      -- has been decided yet, so nothing belonging to it is thrown away.
      if not deferred_now then os.remove(staged) end
    end
    if blocked_now then
      Log.line("UPDATE", string.format(
        "journal recovery: the interrupted ROLLBACK for v%s stopped at %s, "
        .. "which is not the file it put there; nothing of that entry was "
        .. "moved, renamed or deleted and the record was kept exactly as it "
        .. "was found.", tostring(j.target_version), tostring(blocked_now)))
      return blocked_on(blocked_now, "changed")
    end
    if stop_now then
      if stop_now == "skipped" then return "skipped" end
      Log.line("UPDATE", string.format(
        "journal recovery: the interrupted ROLLBACK for v%s stopped because "
        .. "launcher recovery could not be recorded. Remaining recovery "
        .. "evidence was kept for the next launch.", tostring(j.target_version)))
      return "deferred"
    end
    -- Retention on failure: a transient lock (AV scan holding a .bak
    -- or dest) must not cost the user their rollback. Keeping the
    -- journal keeps the sweep gated and makes the next launch retry
    -- this same idempotent walk; it is only deleted once every restore
    -- has landed. (A vanished .bak is not counted as a failure: the
    -- walk has nothing to retry for it.) An incomplete pass returns a
    -- distinct result so the caller can refuse to continue loading a
    -- possibly mixed install.
    --
    -- A launcher DEFERRED for want of an ownership answer is retained the same
    -- way and for the same reason (round 27): the entry is still applied with
    -- its .bak beside it, which is precisely the shape the next walk reads as
    -- "restore not yet performed", so the retry finds it without anything
    -- having been recorded. It is counted separately from a restore failure
    -- because nothing failed: no file was touched and no attempt was made.
    if restore_failures > 0 or deferrals > 0 then
      Updater.journal_write(j)
      Log.line("UPDATE", string.format(
        "journal recovery: interrupted ROLLBACK for v%s left %d restore "
        .. "failure(s) and %d launcher(s) deferred for want of an ownership "
        .. "answer; journal kept for retry on next launch.",
        tostring(j.target_version), restore_failures, deferrals))
      -- Said here as well as on the clean ending, because this launch stops and
      -- the user reads a dialog now; the retry next launch re-reads the same
      -- skipped entries off the journal and says the same thing again.
      say_left_alone()
      return "incomplete"
    end
    -- A rollback is only completed once the record saying it was outstanding is
    -- gone. A refused deletion means the lock stopped being ours somewhere in
    -- the loop above, and the honest ending is the one that says another
    -- instance is working here, not the one that says this finished.
    if not Updater.journal_delete() then return "skipped" end
    Log.line("UPDATE", string.format(
      "journal recovery: completed interrupted ROLLBACK for v%s "
      .. "(%d files).", tostring(j.target_version), #j.files))
    if touched_context and RA.load_context then RA.load_context() end
    -- The last chance to say it: the journal has just been deleted, so no later
    -- launch can rediscover what this walk left alone.
    say_left_alone()
    return "rollback"
  end

  if j.phase == "rolling_back" then
    return complete_rollback()
  end

  -- Phase "applying". First, close the rename-before-journal window: a
  -- crash between os.rename(staged, dest) and the journal write that
  -- flips the entry to "applied" leaves a pending entry whose .new is
  -- gone but whose dest already holds the verified new content. Detect
  -- by hashing dest and reclassify in memory as applied, so neither
  -- direction mishandles it: roll-forward skips it (it already landed,
  -- and its .bak survives until the final cleanup), roll-back restores
  -- it exactly like any journal-applied entry. The staged-absent
  -- precondition matters: a still-staged pending file whose dest
  -- happens to match the new hash (unchanged content queued via the
  -- locked-file path) was never swapped and must stay pending.
  for _, jf in ipairs(j.files) do
    if jf.status == "pending"
        and not exists(staged_for(jf))
        and file_hash_ok(path_for(jf), jf) then
      jf.status = "applied"
      jf.bak_existed = exists(path_for(jf) .. ".bak")
      Log.line("UPDATE", string.format(
        "journal recovery: %s landed before its journal write; "
        .. "reclassified as applied.", jf.name))
    end
  end

  -- Can the interrupted transaction roll forward? Only pending files
  -- matter; applied files already hold verified content. Hashing runs
  -- single-shot pure-Lua here (worst case a couple of seconds, once,
  -- on the rare crash-recovery launch).
  local can_forward = true
  for _, jf in ipairs(j.files) do
    if jf.status == "pending" and not staged_hash_ok(jf) then
      can_forward = false
      break
    end
  end

  if can_forward then
    -- A DESTINATION THAT FILLED UP UNDER A FRESH ADD (Codex round 33, B2.3j
    -- blocker). This walk classified every entry from its own look at the disk,
    -- exactly as the live swap did before round 30, and the appeared direction
    -- is where that costs somebody a file. An entry whose record says the
    -- destination was EMPTY when the update started, with a file sitting there
    -- now, was read as an ordinary existing destination: the stranger was
    -- renamed to .bak, the staged payload landed on top of it, and the cleanup
    -- below deleted that .bak the moment the transaction finished. A file
    -- nothing in this record has ever seen, erased, by a user doing what the
    -- apply_moved surface told them to do.
    --
    -- So the rule the swap follows since round 30 applies here too: the
    -- recorded observation rules, and a destination that disagrees with it is
    -- not a thing to classify around. The stop happens BEFORE the loop below
    -- rather than inside it, so nothing of this transaction moves: no rename,
    -- no backup, no deletion, no journal write, not even for the entries queued
    -- ahead of the one that stopped it. The record, every sidecar and every
    -- staged copy stay exactly as they were found, which leaves the transaction
    -- open to whichever way out the user takes. Move the file away and reopen
    -- and this walk runs to the end; leave it and every launch stops here and
    -- says the same thing, having changed nothing.
    --
    -- The OTHER direction stays exactly as round 30 left it, and it is
    -- genuinely different. A destination recorded as present and absent now is
    -- either a swap this transaction had already begun, whose .bak is on disk
    -- and is adopted as the backup, or a file the world removed, which this
    -- completes as an add. Neither can erase a stranger, because there is no
    -- file at that name to erase, and the proof of what was there rides in the
    -- .bak, which the rollback direction can still put back.
    --
    -- Keyed on a recorded false, never on a missing observation. An entry
    -- carrying none cannot be judged here at all: the only host that writes one
    -- is a host with no reaper.file_exists, which is the same API this walk
    -- would have to ask.
    -- The destinations this transaction ALREADY WROTE, asked before the ones it
    -- has yet to write, and before the cleanup that would remove the evidence
    -- about either (Codex round 34, B2.3k blocker 1).
    local halted = forward_dests_ok()
    if halted then return halted end
    -- WHO OWNS IT COMES BEFORE WHETHER IT IS A STRANGER (Codex round 34, B2.3k
    -- blocker 2). The check above this line used to call every appeared file a
    -- stranger, and at the package root that is a question this body has spent
    -- four rounds learning it must ask ReaPack rather than assume. A launcher
    -- that was missing when the update started and is there now is the ordinary
    -- shape of a ReaPack synchronization between the crash and this launch: the
    -- file is valid, it is owned, ReaAssist's own rules forbid touching it, and
    -- telling the user to move it away is telling them to break the install
    -- this walk exists to protect.
    --
    -- So a package-root destination is asked the ownership question FIRST and
    -- the stranger question only if it has no owner, and the three answers land
    -- where the arc already put them. OWNED and FOREIGN are findings and they
    -- go on to the skip path the fence below already runs: the entry is
    -- recorded skipped with its reason, the launcher is left exactly as it
    -- stands, and the rest of the interrupted transaction finishes. UNKNOWN is
    -- the absence of a finding, and nothing may be decided on one: the walk
    -- stops with everything as it was and asks again next launch. Only a
    -- CONFIRMED unowned file at a destination the record says was empty is a
    -- file nobody can account for, and that is the one that blocks.
    --
    -- Everything that is not a launcher keeps round 33's answer unchanged,
    -- because there is no ownership question to ask about it: nothing but this
    -- body writes App-relative files, so anything at one of those destinations
    -- is a stranger by construction.
    --
    -- Two fresh probes rather than one for a launcher that gets past here, and
    -- that is deliberate. The fence below asks its own uncached question at the
    -- moment it decides about the write, which is a rule earlier rounds froze;
    -- this asks a different question at a different moment, which is whether
    -- there is anything to stop for at all. Reordering the questions is the
    -- whole of the change. Neither answer's meaning moves.
    for _, jf in ipairs(j.files) do
      if jf.status == "pending" and jf.dest_existed == false
          and exists(path_for(jf)) then
        local unowned, state, detail = true, nil, nil
        if jf.root == "package" then
          unowned, state, detail = Updater.launcher_writable_now(jf.name)
        end
        if unowned then
          Log.line("UPDATE", string.format(
            "journal recovery: %s was empty when this update started and "
            .. "something is there now, so the roll-forward stopped without "
            .. "touching anything; the record, every backup and all staging "
            .. "are exactly as they were found, and the next launch finishes "
            .. "the update once that file has been moved away.", path_for(jf)))
          -- The path travels to the startup dialog. Moving THAT file is the one
          -- thing that clears this, and this walk is the only thing that knows
          -- which file it is.
          return blocked_on(path_for(jf), "appeared")
        elseif state == Updater.OWNERSHIP_OWNED
            or state == Updater.OWNERSHIP_FOREIGN then
          Log.line("UPDATE", string.format(
            "journal recovery: %s was empty when this update started and is "
            .. "there now, but it has an owner (%s: %s), so it is a launcher "
            .. "to leave alone rather than a file to stop for; the entry goes "
            .. "to the skip the fence records.", jf.name, tostring(state),
            tostring(detail)))
        else
          Log.line("UPDATE", string.format(
            "journal recovery: %s was empty when this update started and is "
            .. "there now, and who owns it could not be found out (%s: %s), so "
            .. "nothing was decided and nothing was touched; the next launch "
            .. "asks again.", jf.name, tostring(state), tostring(detail)))
          return "incomplete"
        end
      end
    end
    for _, jf in ipairs(recovery_entries(false)) do
      -- Before this entry's backup and swap, and therefore between one landed
      -- entry and the next. An entry that already landed carries "applied" on
      -- disk, because its status write ran while the lock was still ours; the
      -- entries behind it are untouched and still pending; and the record, the
      -- backups and the staging are all where the launch after this one reads
      -- them (Codex round 41, B2.3r).
      if deposed() then return "skipped" end
      -- The same ownership fence the live apply puts in front of every
      -- package-root swap (Codex round 25, B2.3 blocker 1). This walk performs
      -- exactly that swap, and it runs on a LATER launch, which is if anything
      -- more exposed: a whole REAPER session may have synchronized ReaPack
      -- between the crash and this recovery. A launcher that is no longer
      -- confirmed unowned is recorded skipped and left alone, and the rest of
      -- the interrupted transaction still finishes.
      --
      -- This is also what closes the window inside the apply's own skip: a
      -- crash between the decision and the journal write leaves the entry
      -- pending, and the answer to a pending launcher entry here is to ask
      -- again rather than to write.
      --
      -- THE SKIP MUST BE DURABLE OR RECOVERY STOPS (Codex round 26, blocker 2).
      -- This write's result used to be ignored, and the loss it hid was total:
      -- the entry stays "pending" on disk, recovery then removes the staging
      -- and deletes the journal, and a crash in that window leaves a pending
      -- entry with no staged copy. The next launch hashes the untouched
      -- launcher, and if the release happened to ship the bytes already there
      -- (a launcher that did not change between versions is the ordinary case)
      -- the reclassification above reads it as APPLIED with no backup -- so a
      -- rollback triggered by any other entry deletes it as a fresh add. The
      -- file ReaPack owns, deleted, because a marker could not be written.
      --
      -- So the walk STOPS instead, and stops before it has cleaned anything up.
      -- The staging stays, the journal stays exactly as found for this entry,
      -- and "deferred" is the existing outcome that means precisely this: the
      -- recovery state could not be recorded, so the launch ends and the next
      -- one starts over. That next launch re-reads the same pending entry,
      -- re-asks the fence, and re-attempts the write; nothing here is lost by
      -- waiting and everything is lost by pressing on.
      local legacy_pruned = false
      if jf.status == "pending" and package_launcher(jf) then
        local writable, state, detail = Updater.launcher_writable_now(jf.name)
        if not writable then
          if j.schema == 1 then
            if state ~= Updater.OWNERSHIP_OWNED
                and state ~= Updater.OWNERSHIP_FOREIGN then
              return "incomplete"
            end
            if not exists(path_for(jf)) then
              return missing_legacy_launcher(jf, state, detail)
            end
            local saved, outcome = prune_legacy_launchers({ [jf] = { state = state,
              detail = detail and tostring(detail):sub(1, 200) or nil } })
            if not saved then return outcome end
            legacy_pruned = true
          else
          jf.status      = "skipped"
          jf.skip_reason = Updater.launcher_left_alone_reason("skipped", state)
          jf.skip_detail = detail and tostring(detail):sub(1, 200) or nil
          if not Updater.journal_write(j) then
            Log.line("UPDATE", string.format(
              "journal recovery: %s is no longer confirmed unowned, but the "
              .. "skip could not be recorded; leaving the journal and all "
              .. "staging exactly as found (recovery deferred, and the next "
              .. "launch asks again).", jf.name))
            return "deferred"
          end
          note_left_alone(jf.skip_reason, jf.name, jf.skip_detail)
          Log.line("UPDATE", string.format(
            "journal recovery: %s is no longer confirmed unowned (%s: %s), so "
            .. "its interrupted swap was skipped rather than completed.",
            jf.name, tostring(state), tostring(detail)))
          end
        end
      end
      if jf.status == "pending" and not legacy_pruned then
        local dest   = path_for(jf)
        local staged = staged_for(jf)
        local bak    = dest .. ".bak"
        -- The pre-pass above is the decision and this is the last line behind
        -- it. Two things can put a file at a destination the record says was
        -- empty after that decision was taken: an owned launcher whose owner
        -- vanished between the pre-pass's question and the fence's, and
        -- anything at all arriving while the entries ahead of this one were
        -- landing. Neither may be backed up and written over, and neither can
        -- be reported as a stop that changed nothing, because entries ahead of
        -- it have landed. So the transaction turns round instead: the rollback
        -- below puts every one of them back, leaves this destination alone (a
        -- pending entry is only ever restored INTO an empty name), and the
        -- launch ends on the ending that says the update was undone.
        if jf.dest_existed == false and exists(dest) then
          Log.line("UPDATE", string.format(
            "journal recovery: %s filled up after the roll-forward had "
            .. "started, so the interrupted apply is being rolled back instead "
            .. "of completed; that file is not touched either way.", dest))
          can_forward = false
          break
        end
        if exists(dest) then
          -- Normal swap: clear any stale .bak, back up the live file.
          os.remove(bak)
          local ok_bak = os.rename(dest, bak)
          if not ok_bak then can_forward = false break end
          jf.bak_existed = true
        else
          -- Mid-swap crash: dest already moved aside. An existing .bak
          -- IS the old live file; keep it as the backup.
          jf.bak_existed = exists(bak)
        end
        local ok_mv = os.rename(staged, dest)
        if not ok_mv then can_forward = false break end
        jf.status = "applied"
        Updater.journal_write(j)
      end
    end
  end

  if can_forward then
    -- The pre-pass above ran before the loop that just landed every pending
    -- entry, so its answers are as old as that loop is long. This asks again,
    -- one entry at a time, at each removal (Codex round 35, B2.3l).
    local halted = cleanup_sidecars()
    if halted then return halted end
    Log.line("UPDATE", string.format(
      "journal recovery: rolled interrupted apply FORWARD to v%s "
      .. "(%d files).", tostring(j.target_version), #j.files))
    if touched_context and RA.load_context then RA.load_context() end
    return completed("forward")
  end

  -- Roll back. Flip the phase marker FIRST: this walk mutates disk the
  -- same way the runtime rollback does, so it carries the same crash
  -- exposure (a crash after a restore but before any status write must
  -- never be rolled forward by the NEXT launch). With the marker on
  -- disk, any interruption re-enters the idempotent rolling_back
  -- completion above. If the marker cannot be written, mutate NOTHING:
  -- the journal and all recovery state stay exactly as found, and the
  -- caller exits the launch cleanly ("deferred").
  --
  -- Asked here as well, so a walk that lost the lock while the roll-forward was
  -- deciding does not turn the transaction round on a record that is no longer
  -- its own. "deferred" would be the wrong sentence for that, and this one is
  -- the marker write's own moment, before any restore.
  if deposed() then return "skipped" end
  j.phase = "rolling_back"
  if not Updater.journal_write(j) then
    Log.line("UPDATE",
      "journal recovery: could not write the rolling_back marker; "
      .. "leaving the journal and all recovery state untouched "
      .. "(recovery deferred).")
    return "deferred"
  end
  Log.line("UPDATE", string.format(
    "journal recovery: rolling interrupted apply for v%s BACK; the "
    .. "next session check offers the update again.",
    tostring(j.target_version)))
  return complete_rollback()
end
-- close transactional apply scope

-- THE THREE THINGS A "blocked" RECOVERY CAN HAVE FOUND, in one place because
-- they are one outcome (Codex round 33, extended in rounds 34, 35 and 36). The
-- meaning the three share is what makes them one: recovery could not act at a
-- destination it had to act at, it stopped there rather than guess, everything
-- from that point on was left exactly as it was found, and the user is the only
-- one who can clear it. The kind the walk stamped picks the sentences, and the
-- format string takes the path the walk stamped beside it.
--
-- WHAT EACH ONE MAY PROMISE IS NOT THE SAME, and that is the whole reason they
-- are not one paragraph. "appeared" comes from a pre-pass that runs before any
-- of the transaction moves, so it can say that nothing at all was changed.
-- "changed" comes from a rollback that may already have put earlier files back,
-- and "changed_cleanup" from a cleanup that may already have removed the
-- sidecars of the entries ahead of the one it stopped on, so both promise only
-- what every one of those walks keeps: that file untouched, and the record, the
-- backups and the downloads it had not finished with still there. Overclaiming
-- on either would be a sentence the user could disprove by looking at their own
-- install.
--
-- AND THE LAST SENTENCE IS WHERE THE TWO STRANGERS PART (Codex round 36,
-- B2.3m). Both say to move the file, because that is the only thing that clears
-- either. What differs is what happens after. The undo direction still holds
-- the file it means to put back, so the next launch restores the .bak into the
-- name and the rollback ends there. The cleanup direction spent its copy at the
-- swap that landed the file, so there is nothing left on this computer to
-- install again, and the launch after the move offers the verified repair
-- instead (startup_repair_copy). Saying "the recovery will finish" there was an
-- instruction into a dead end: move the file and the destination is empty, put
-- it back and the stranger is standing again, with no exit either way.
function Updater.startup_blocked_copy(kind)
  if kind == "changed_cleanup" then
    return "ReaAssist could not finish recovering from an interrupted "
      .. "update, because a file it did not put there is sitting where "
      .. "ReaAssist had already written one of its own:\n%s\n\n"
      .. "That file was not moved, renamed or deleted. ReaAssist stopped as "
      .. "soon as it found it, and kept its update record along with the "
      .. "backups and downloaded files it had not finished with.\n\n"
      .. "ReaAssist cannot put its own file back by itself: the copy it "
      .. "downloaded was used up when it installed that file, so there is "
      .. "nothing left on this computer to install again.\n\n"
      .. "Move that file somewhere else, then reopen ReaAssist: it will offer "
      .. "to check every installed file against the current release and "
      .. "download a fresh, verified copy of anything that is missing."
  end
  if kind == "changed" then
    return "ReaAssist could not finish recovering from an interrupted "
      .. "update, because a file it did not put there is sitting where "
      .. "ReaAssist had already written one of its own:\n%s\n\n"
      .. "That file was not moved, renamed or deleted. ReaAssist stopped as "
      .. "soon as it found it, and kept its update record along with the "
      .. "backups and downloaded files it had not finished with.\n\n"
      .. "Move that file somewhere else, then reopen ReaAssist and the "
      .. "recovery will finish."
  end
  return "ReaAssist could not finish an interrupted update, because a file "
    .. "it did not put there is sitting where the update was going to add "
    .. "one:\n%s\n\n"
    .. "Nothing was changed: no file was moved, renamed or deleted, and this "
    .. "update's own record, its backups and its downloaded files were all "
    .. "kept.\n\n"
    .. "Move that file somewhere else, then reopen ReaAssist and the update "
    .. "will finish."
end

-- THE ONE THING A WALK CANNOT DO, AND WHO DOES IT INSTEAD (Codex round 36,
-- B2.3m). Round 35 gave a missing installed file a stop of its own and the copy
-- asked for the file back. That is the right ask, and on its own it is not an
-- ending: the payload that would have replaced it was consumed by the swap that
-- landed it, so a user whose antivirus took the file has nothing to put back,
-- and no launch can put it back for them. This is what they get, and it is the
-- same offer the quarantine gate has made since B2.2d, reached the same way:
-- the record is preserved, the launch continues into the recovery surface, and
-- the full pass checks every installed file against the current release and
-- downloads and verifies a fresh copy of whatever is missing or does not match.
--
-- Two paths, in this order: the file that went, then the record that says it
-- was ever there. Both are named because they are the two things a user asking
-- for help will be asked about, and because the second is what a support answer
-- would want kept.
--
-- It promises what the walk it comes from can keep, exactly as the blocked
-- copies do: the backups and downloads it had not finished with, not "nothing
-- was changed", since a stop at the moment of a removal has entries behind it
-- whose sidecars are already gone.
function Updater.startup_repair_copy()
  return "ReaAssist could not finish recovering from an interrupted update, "
    .. "because a file the update had already installed is no longer "
    .. "there:\n%s\n\n"
    .. "ReaAssist stopped there rather than finish an update over a missing "
    .. "file, so it has not started a normal session. It kept the backups and "
    .. "downloaded files it had not finished with, and its update record is "
    .. "preserved here:\n%s\n\n"
    .. "ReaAssist will now offer to check every installed file against the "
    .. "current release and download a fresh, verified copy of anything that "
    .. "is missing or does not match. That check is what finishes this. If you "
    .. "know what took the file (antivirus quarantine and disk cleanup tools "
    .. "are the usual reasons one goes missing), putting it back before the "
    .. "check is fine: the check reads every installed file and replaces only "
    .. "what does not match. If you are reporting the problem, keep a copy of "
    .. "the preserved record for support first."
end

-- WHAT A RECORD NOBODY CAN ACCOUNT FOR IS TOLD (Codex round 38, B2.3o blocker
-- 2).
--
-- A gate is standing, and a second update record is at the journal path that
-- this body cannot read. It cannot be walked, because the gate outranks every
-- journal. It cannot be set aside, because a record that will not open carries
-- nothing to say whose it is, and moving one could take a live stranger's
-- recovery state with it. And the repair the gate normally offers would be
-- refused over it the moment the user accepted it, which is the loop this
-- outcome exists to stop being.
--
-- So it says the true thing rather than the useful-sounding one: what is in the
-- way, that nothing was touched, that the check is deliberately not on offer,
-- and the two ways out that are real. Reopening comes first, because a record
-- that will not open is usually one something else is holding for a moment and
-- that is the whole fix when it is. Support comes second, and it is the
-- standing answer for a wall that does not come down on its own (Codex round
-- 28). Neither of them is moving the file by hand, which would take a gate down
-- with nothing having verified the install.
--
-- Two paths, in the order a reader needs them: the evidence that raised the
-- gate, then the record standing in the way of clearing it.
function Updater.startup_unreadable_copy()
  return "ReaAssist has not started a normal session.\n\n"
    .. "An earlier update on this install was refused, and its record was "
    .. "kept here:\n%s\n\n"
    .. "There is now a second update record that ReaAssist cannot read, "
    .. "here:\n%s\n\n"
    .. "ReaAssist cannot tell which update wrote that second record, or "
    .. "whether another copy of ReaAssist is still using it, so it has left it "
    .. "exactly where it is. Nothing on this install was changed and nothing "
    .. "was deleted. The check that would normally clear this cannot run while "
    .. "that record is there, so ReaAssist is not offering it.\n\n"
    .. "Please reopen ReaAssist in a moment. If something else was holding "
    .. "that record open (antivirus scans often hold a file briefly), that is "
    .. "all this needs. If ReaAssist keeps stopping here, ask for help at "
    .. "https://reaassist.app, and keep both files above: together they are "
    .. "the whole record of what happened."
end

-- THE STOP THAT ONLY THE PERSON AT THE MACHINE CAN END (Codex round 42, B2.3s).
--
-- A lock is standing on this install, and ReaAssist cannot prove whether the
-- copy that took it is still running. Since this round it will not guess: a
-- copy that is only asleep is still working, and taking its lock is how two
-- ReaAssist processes end up writing the same files. A copy that has crashed
-- leaves a lock nobody will ever hand back, and only somebody who can see the
-- machine knows which of those two it is.
--
-- So the copy says what is true and asks for the one judgement it cannot make.
-- Reopening comes first, because the ordinary cause is a second REAPER window
-- that is genuinely busy and the whole fix is to wait for it. Deleting the lock
-- comes second, spelled out with the condition attached, because it is the
-- clear and it is the user's to authorize. Support comes last, as it does for
-- every wall that does not come down on its own.
--
-- Two lines of evidence, in the order a reader needs them: the lock, then the
-- instance it recorded.
--
-- AND THE NOUN IS THE ARTIFACT'S, NOT A GUESS (Codex round 43, B2.3t). The
-- claim protocol builds a flat FILE on Windows and on the wbx fast path, and a
-- claim DIRECTORY on POSIX. This copy is the one place the user is asked to
-- remove it by hand, so the last paragraph has to say the word for the thing
-- they will find in their file manager; a sentence naming a file, over a path
-- that is a folder, is an instruction that cannot be followed. `kind` comes
-- from the acquisition, which is the only thing that looked.
--
-- AND ONE OF THE THREE ANSWERS IS NOT A NOUN (Codex round 44, B2.3u). When the
-- lock's own directory cannot be searched, every name in it reads as present
-- and nothing here can say what is standing or whether anything is. Naming a
-- file then would be the same unusable instruction round 43 removed, one level
-- up, so this branch names the FOLDER and the permission instead, and asks for
-- the thing that would actually change the answer. The %s slots are the same
-- two the callers pass; the owner is not shown here because there is no claim
-- to have recorded one.
--
function Updater.startup_lock_undecidable_copy(kind)
  if kind == "blocked" then
    return "ReaAssist has not started a normal session.\n\n"
      .. "ReaAssist keeps the claim that says an update is in progress in this "
      .. "folder, and this launch cannot look inside it:\n%s\n\n"
      .. "Every name in that folder answers the same way whether something is "
      .. "there or not, so ReaAssist cannot tell whether another copy of "
      .. "ReaAssist is holding this install, and it will not guess.\n\n"
      .. "Nothing was read, moved, changed or removed this launch, and every "
      .. "update record is exactly where it was.\n\n"
      .. "Please give your account permission to open the folder named above, "
      .. "then reopen ReaAssist. If that does not settle it, ask for help at "
      .. "https://reaassist.app."
  end
  local noun = (kind == "folder") and "folder" or "file"
  return "ReaAssist has not started a normal session.\n\n"
    .. "Another copy of ReaAssist claimed this install for an update, and "
    .. "ReaAssist cannot tell whether that copy is still running. Its claim is "
    .. "here:\n%s\n\n"
    .. "It was recorded by:\n%s\n\n"
    .. "ReaAssist will not take that claim away from a copy that may still be "
    .. "working on this install, so nothing was read, moved, changed or "
    .. "removed this launch, and every update record is exactly where it "
    .. "was.\n\n"
    .. "Please close any other REAPER window that is running ReaAssist, then "
    .. "reopen ReaAssist. If ReaAssist keeps stopping here and you are sure no "
    .. "other copy of ReaAssist is running on this computer, delete the "
    .. noun .. " named above and reopen ReaAssist; that is the one decision "
    .. "only you can make. If that does not settle it, ask for help at "
    .. "https://reaassist.app."
end

-- Resolve any interrupted apply NOW, before anything further loads.
-- Must stay ahead of the critical-file probe and the CodeRuntime / UI
-- dofiles below; Resources/Context.lua loads earlier than this point,
-- so resolve_journal_at_startup reloads it when the journal touched it.
--
-- Eight outcomes stop the ordinary launch, and every one of them means the
-- same thing: continuing would run a body against an install we cannot
-- vouch for. Two of the eight stop the SESSION rather than the launch and hand
-- what is left of it to the recovery surface, because a verified repair is the
-- only thing that can honestly settle either.
--
-- "invalid" is the one that no longer just stops. It means a pending
-- update record is present that this body may not read, so nothing was
-- changed and the record was preserved, OR that a record preserved by an
-- earlier launch is still there, which is the same install in the same
-- unverified state. Until B2.2d that ended the launch with a dialog, and
-- the only ways out it could name were a repair the user could not reach
-- (ReaAssist would not open) and moving the file aside by hand, which
-- clears the gate without verifying anything (Codex round 19,
-- requirements 3 and 4). So the launch continues into a MINIMAL recovery
-- session instead: no normal session, no chat, no network beyond the
-- repair, just the recovery surface offering the full manifest
-- verification and repair, which is the one thing that can honestly clear
-- this. S.quarantine_gate carries that decision to the critical-file gate
-- further down, which is where bootstrap recovery is entered.
--
-- "repair" is the second of the two, and it is round 36's (B2.3m). Recovery
-- found a file this transaction had already installed missing from the place
-- its own record says it installed it. That already stopped the cleanup rather
-- than finalize an update over it (round 35), and what round 36 adds is the
-- ending: the payload copy was consumed by the swap that landed the file, so no
-- walk over this record can put it back, and the record is preserved into the
-- quarantine slot so the same gate can offer the same verified repair. Every
-- backup and staged copy is kept with it, because the stranded-sidecar sweep
-- stands down while a preserved record stands.
--
-- "unreadable" is round 38's (B2.3o), and it is the one that deliberately
-- offers nothing. A gate is standing and a second update record is at the
-- journal path that this body cannot read: it cannot be walked, because the
-- gate outranks every journal, and it cannot be set aside, because a record
-- that will not open carries nothing to say whose it is and moving one could
-- take a live stranger's recovery state with it. The repair the gate normally
-- offers would be refused over that record the moment it was accepted, so
-- offering it would only be a loop with the user's hand on the button. The copy
-- names both files, says nothing was touched, and gives the two ways out that
-- are real (Updater.startup_unreadable_copy).
--
-- The other six still stop here. "skipped" means another LIVE instance is
-- mid-apply on this shared install; "deferred" means recovery could not
-- record its own state (the rolling_back marker, a roll-forward skip, a
-- rollback's supersession, or a record that could not be preserved) and so left
-- everything exactly as it found it;
-- "incomplete" means recovery could not finish and something is still
-- outstanding -- a restore that failed on a locked file, a launcher whose
-- ownership question did not answer, or (since round 34) a destination this
-- transaction wrote that could not be read back to check it is still the file
-- it put there -- so the journal was kept for the next launch to retry;
-- "blocked" means recovery could not act at a destination it had to act at and
-- stopped there: a file this transaction did not put there is sitting at one it
-- was going to add to (round 33), at one an undo was about to restore over
-- (round 34), or at one a cleanup was about to finish over (round 36's kind of
-- its own), and in every case the walk left that destination alone, the user is
-- the only one who can clear it, and moving it is what lets the next launch
-- reach an ending; "rollback" means a
-- rollback COMPLETED, which is the one that used to fall through. It
-- cannot: this process compiled its body before recovery ran, so after a
-- rollback it is a new body running against files that were just put back
-- to their old versions, and the sidecars it is about to dofile are the
-- old ones. Exit cleanly instead (atexit releases the toolbar state and
-- this instance's lock).
do
  local resolved = Updater.resolve_journal_at_startup()
  if resolved == "invalid" then
    -- The record, or -- when the refusal could not move it aside at all -- the
    -- path it is still sitting at, which is where the user will find it. The
    -- fallback used to name the slot the record WOULD have gone to, which was
    -- a file that did not exist (Codex round 22, B2.2g blocker 1: the slot
    -- names are no longer a list of places, they are what was found).
    S.quarantine_gate = Updater.journal_quarantined() or Updater.journal_path()
    local notice =
      "Something is wrong with a pending ReaAssist update record, so "
      .. "ReaAssist has not started a normal session.\n\n"
      .. "Nothing on this install was changed, and the record was kept "
      .. "here:\n" .. tostring(S.quarantine_gate) .. "\n\n"
      .. "ReaAssist will now offer to check every installed file against "
      .. "the current release and repair anything that does not match. "
      .. "That check is what clears this. If you are reporting the "
      .. "problem, keep a copy of that file for support first."
    -- A SECOND RECORD THIS LAUNCH HAD TO SET ASIDE to make that offer true
    -- (Codex round 38, B2.3o blocker 2). The gate names the evidence written
    -- closest to the fault, which is the record above; when another one was
    -- lying at the journal path and would have refused the check, it is kept in
    -- the same folder under its own name. Naming it is what makes "keep a copy
    -- for support" cover the whole of what happened rather than half of it.
    if Updater._startup_setaside_record then
      notice = notice .. "\n\nA second update record was in the way of that "
        .. "check, so it was kept beside the first one, here:\n"
        .. tostring(Updater._startup_setaside_record)
      Updater._startup_setaside_record = nil
    end
    -- When the reason the gate is still up is a launcher rather than the
    -- record itself, say which and why, ahead of the generic copy (Codex
    -- round 25, B2.3 blocker 2). The authorized repair finished its file work
    -- and the record was deliberately kept, so "nothing was changed" is not
    -- the whole truth on its own.
    if Updater._startup_launcher_notice then
      notice = tostring(Updater._startup_launcher_notice) .. "\n\n" .. notice
      Updater._startup_launcher_notice = nil
    end
    Log.line("UPDATE",
      "journal recovery: entering quarantine recovery mode; the full "
      .. "verified repair is the only thing offered this launch.")
    -- Screen Reader launches get the same offer through the path they
    -- already use: announce it, then Bootstrap.screen_reader_loop runs the
    -- same repair without a prompt to click.
    if S.screen_reader_startup_intent and reaper.osara_outputMessage then
      pcall(reaper.osara_outputMessage, notice)
    else
      reaper.MB(notice, "ReaAssist", 0)
    end
  elseif resolved == "repair" then
    -- The same gate, raised for a different finding (Codex round 36, B2.3m).
    -- The record here was perfectly readable and this launch walked it; what it
    -- found is a file the update had installed and something has since taken
    -- away, which no walk over that record can put back, because the copy it
    -- would have used was consumed by the swap that landed the file. The walk
    -- has already preserved the record into the slot, so the way out is the one
    -- the gate has offered since B2.2d, reached through the same field: the
    -- launch continues into the minimal recovery session and its full pass
    -- checks every installed file against the current release and heals what is
    -- missing. Naming the file first and the preserved record second, because
    -- the first is what happened and the second is what a support answer wants
    -- kept.
    --
    -- The record NAMED is the one this walk preserved, which is not always the
    -- one the gate reports (Codex round 37, B2.3n). When a gate was already
    -- standing, journal_quarantined answers with the evidence of the refusal
    -- that raised it, and this dialog is describing a different transaction:
    -- the one whose file went, whose record was just set aside beside it. Both
    -- sit in the same folder and both are kept until the repair clears them;
    -- naming the one the sentences are about is what makes "keep a copy for
    -- support" point at the right file.
    S.quarantine_gate = Updater.journal_quarantined() or Updater.journal_path()
    local notice = string.format(Updater.startup_repair_copy(),
      tostring(Updater._startup_repair_path
        or "(the ReaAssist log names the file)"),
      tostring(Updater._startup_repair_record or S.quarantine_gate))
    -- A launcher this transaction left alone, said ahead of the outcome, and
    -- this is the last dialog that can say it: the walk that preserved the
    -- record is the last one that ever reads it.
    if Updater._startup_launcher_notice then
      notice = tostring(Updater._startup_launcher_notice) .. "\n\n" .. notice
      Updater._startup_launcher_notice = nil
    end
    Log.line("UPDATE",
      "journal recovery: a file this update installed is gone and nothing on "
      .. "disk can replace it, so the launch continues into the verified "
      .. "repair with the record preserved.")
    if S.screen_reader_startup_intent and reaper.osara_outputMessage then
      pcall(reaper.osara_outputMessage, notice)
    else
      reaper.MB(notice, "ReaAssist", 0)
    end
  elseif resolved == "skipped" or resolved == "deferred"
      or resolved == "incomplete" or resolved == "blocked"
      or resolved == "unreadable" or resolved == "undecidable"
      or resolved == "rollback" then
    local messages = {
      skipped =
        "Another ReaAssist instance is applying an update to this "
        .. "install right now.\n\n"
        .. "Please reopen ReaAssist in a moment, once that update "
        .. "finishes.",
      deferred =
        "ReaAssist could not record its update recovery state "
        .. "(disk full or permissions?).\n\n"
        .. "Please free up disk space or fix permissions for the "
        .. "ReaAssist Data folder, then reopen ReaAssist.",
      -- Two things reach this outcome now, so the copy names both rather than
      -- asserting the one it used to (Codex round 27). A file may be locked,
      -- or a check ReaAssist needed may not have answered; either way the
      -- recovery state is intact and the next launch finishes it.
      --
      -- The second of those two needs a way out, and reopening is not one
      -- (Codex round 28, B2.3e should-fix). A lock clears on its own and the
      -- next launch finishes; a ReaPack ownership lookup that never answers
      -- does not, so a user with one reopens into this same dialog forever
      -- unless the copy says where the fault is. It says so second, because
      -- reopening IS the fix for the commoner cause.
      incomplete =
        "ReaAssist is recovering from an interrupted update and could not "
        .. "finish this time. A file may still be locked (antivirus scans "
        .. "often hold them briefly), or the check ReaAssist makes with "
        .. "ReaPack may not have answered.\n\n"
        .. "Please reopen ReaAssist in a moment; recovery will finish "
        .. "automatically.\n\n"
        .. "If ReaAssist keeps stopping here, open Extensions > ReaPack > "
        .. "Browse packages and update ReaPack to the current version, or "
        .. "install ReaPack again from https://reapack.com, then reopen "
        .. "ReaAssist. If that does not settle it, ask for help at "
        .. "https://reaassist.app.",
      -- The one stop the user themselves clears, so it names the file and what
      -- to do about it (Codex round 33, B2.3j blocker; extended in rounds 34
      -- and 36). The path comes from the walk, which is the only thing that
      -- knows which entry stopped it; the fallback covers an outcome arriving
      -- without one and points at the log, which named the path on its way out.
      -- The three kinds, what each may honestly promise and where each one's
      -- move leads live together in Updater.startup_blocked_copy, beside the
      -- walk that stamps the kind.
      blocked = string.format(
        Updater.startup_blocked_copy(Updater._startup_blocked_kind),
        tostring(Updater._startup_blocked_path
          or "(the ReaAssist log names the file)")),
      -- The stop that offers nothing (Codex round 38, B2.3o blocker 2). Both
      -- paths come from the walk, which is the only thing that knows which
      -- record it could not read and which evidence was already standing; the
      -- fallbacks point at the log, which named both on its way out.
      unreadable = string.format(Updater.startup_unreadable_copy(),
        tostring(Updater._startup_unreadable_record
          or "(the ReaAssist log names the folder)"),
        tostring(Updater._startup_unreadable_path
          or "(the ReaAssist log names the file)")),
      -- The stop only the user can end (Codex round 42, B2.3s). All three come
      -- from the acquisition, which is the only thing that knows which lock it
      -- would not take, what kind of artifact was standing there and whose name
      -- was on it; the fallbacks point at the log, which named both on its way
      -- out.
      undecidable = string.format(
        Updater.startup_lock_undecidable_copy(Updater._startup_lock_kind),
        tostring(Updater._startup_lock_path
          or "(the ReaAssist log names the claim)"),
        tostring((Updater._startup_lock_owner ~= nil
            and Updater._startup_lock_owner ~= "")
          and Updater._startup_lock_owner
          or "a copy of ReaAssist whose name could not be read")),
      rollback =
        "ReaAssist undid an interrupted update and put the previous "
        .. "version back.\n\n"
        .. "Please reopen ReaAssist to run it.",
    }
    local message = messages[resolved]
    if resolved == "incomplete" and Updater._startup_missing_launcher_notice then
      message = Updater._startup_missing_launcher_notice
      Updater._startup_missing_launcher_notice = nil
    end
    -- A launcher the walk deliberately left alone, said ahead of the outcome
    -- (Codex round 26, blocker 2). "rollback" and "incomplete" are endings a
    -- recovery reaches with skips recorded, and this is the only dialog either
    -- of them ever shows: the launch stops on the line below, so a notice left
    -- in the field here would never be read by anything.
    if Updater._startup_launcher_notice then
      message = tostring(Updater._startup_launcher_notice) .. "\n\n" .. message
      Updater._startup_launcher_notice = nil
    end
    reaper.MB(message, "ReaAssist", 0)
    S.script_open = false
    return
  end
  -- The advisory half of the third ending (Codex round 25, B2.3 blocker 2).
  -- The authorized repair finished, the record is gone and this launch
  -- continues, but one of the two actions that start ReaAssist is not
  -- serviceable and this body is not allowed to put it right. Nothing later in
  -- this launch would ever show it: the recovery surface is not entered when
  -- the gate came down, and a normal session has no place for it. So it is said
  -- here, through the same dialog the outcomes above use, before the session
  -- starts. Reached on the outcomes that continue ("none", "finished",
  -- "forward"), and only the last two can have set it. The outcomes that stop
  -- read the same field in their own branch above, before the launch ends.
  if Updater._startup_launcher_notice then
    local notice = tostring(Updater._startup_launcher_notice)
    Updater._startup_launcher_notice = nil
    if S.screen_reader_startup_intent and reaper.osara_outputMessage then
      pcall(reaper.osara_outputMessage, notice)
    else
      reaper.MB(notice, "ReaAssist", 0)
    end
  end
end

-- Sweep any cleared-episode tombstone on a launch that got past the gate
-- (Codex round 24 rider). Its own do-block rather than the one above, because
-- that block's shape is pinned by the fail-closed regression and this has
-- nothing to do with the decision it makes. Reached only when the resolver
-- let the launch continue, so no gate is standing; the sweep re-checks that
-- for itself anyway, and does nothing on a launch that ended above.
do
  pcall(Updater.quarantine_tombstone_sweep)
end

Net = {}

OpenRouter.CATALOG_TTL_SECONDS = 24 * 60 * 60

function Net._openrouter_failure_text(value, fallback)
  if type(value) == "table" then
    return tostring(value.error_msg or value.error or value.state or fallback)
  end
  if value ~= nil and tostring(value) ~= "" then return tostring(value) end
  return tostring(fallback or RA.t(
    "settings.openrouter.operation.failed", nil,
    "OpenRouter operation failed"))
end

function Net._openrouter_message(key, values, fallback)
  return {
    key = tostring(key or ""),
    values = type(values) == "table" and values or nil,
    fallback = tostring(fallback or ""),
  }
end

function Net._set_openrouter_settings_status(operation, state, message,
                                              details)
  local message_key, message_values, message_fallback, resolved_message
  if type(message) == "table" and type(message.key) == "string"
      and message.key ~= "" then
    message_key = message.key
    message_values = message.values
    message_fallback = tostring(message.fallback or message.key)
    resolved_message = ""
  else
    resolved_message = tostring(message or "")
  end
  S.openrouter_settings_status_sequence =
    (tonumber(S.openrouter_settings_status_sequence) or 0) + 1
  S.openrouter_settings_status = {
    sequence = S.openrouter_settings_status_sequence,
    operation = tostring(operation or "unknown"),
    state = tostring(state or "unknown"),
    message = resolved_message,
    message_key = message_key,
    message_values = message_values,
    message_fallback = message_fallback,
    details = type(details) == "table" and details or nil,
  }
end

function Net.openrouter_settings_status()
  local source = S.openrouter_settings_status
  if type(source) ~= "table" then return nil end
  local message = source.message
  if type(source.message_key) == "string" and source.message_key ~= "" then
    message = RA.t(source.message_key, source.message_values,
      source.message_fallback)
  end
  return {
    sequence = source.sequence,
    operation = source.operation,
    state = source.state,
    message = message,
    message_key = source.message_key,
    message_values = source.message_values,
    details = source.details,
  }
end

function Net._close_openrouter_catalog_operation(operation, cancel)
  operation = operation or S.openrouter_catalog_operation
  if type(operation) ~= "table" then return end
  for _, kind in ipairs({"model", "endpoints", "presets", "preset"}) do
    local handle = operation.handles and operation.handles[kind] or nil
    if type(handle) == "table" and handle.closed ~= true then
      if cancel == true and handle.consumed ~= true
          and type(Engine.openrouter_catalog_cancel) == "function" then
        pcall(Engine.openrouter_catalog_cancel, handle)
      end
      if type(Engine.openrouter_catalog_close) == "function" then
        pcall(Engine.openrouter_catalog_close, handle)
      end
    end
  end
  if S.openrouter_catalog_operation == operation then
    S.openrouter_catalog_operation = nil
  end
end

function Net.openrouter_catalog_cancel(silent)
  local operation = S.openrouter_catalog_operation
  if type(operation) ~= "table" then return false, "no_catalog_operation" end
  Net._close_openrouter_catalog_operation(operation, true)
  if silent ~= true then
    Net._set_openrouter_settings_status("catalog", "cancelled",
      Net._openrouter_message("settings.openrouter.catalog.cancelled", nil,
        "OpenRouter catalog refresh cancelled."))
  end
  return true
end

function Net.openrouter_catalog_start(model_id)
  if type(S.openrouter_catalog_operation) == "table" then
    return false, RA.t("settings.openrouter.catalog.already_running", nil,
      "An OpenRouter catalog refresh is already running.")
  end
  local clean_model, model_error = OpenRouter.validate_model_id(model_id)
  if not clean_model then
    return false, RA.t("settings.openrouter.catalog.invalid_model", {
      reason = tostring(model_error),
    }, "Invalid OpenRouter model ID: " .. tostring(model_error))
  end
  local api_key = S.api_key_map and S.api_key_map.openrouter or nil
  if type(api_key) ~= "string" or api_key == "" then
    return false, RA.t("settings.openrouter.catalog.key_required", nil,
      "Enter an OpenRouter API key before refreshing the catalog.")
  end
  if type(Engine) ~= "table"
      or type(Engine.openrouter_catalog_start) ~= "function" then
    return false, RA.t("settings.openrouter.catalog.engine_unavailable", nil,
      "The OpenRouter catalog is unavailable.")
  end
  local ok_secret, secret_json = pcall(RA.JSON.encode, {api_key = api_key})
  if not ok_secret or type(secret_json) ~= "string" then
    return false, RA.t("settings.openrouter.catalog.credential_failed", nil,
      "Could not prepare the OpenRouter catalog credential.")
  end

  local operation = {
    operation_kind = "providers", model_id = clean_model,
    handles = {}, snapshots = {},
  }
  local ok_endpoints, endpoints_handle, endpoints_failure = pcall(
    Engine.openrouter_catalog_start, "endpoints", clean_model,
    secret_json)
  secret_json = nil
  if not ok_endpoints or type(endpoints_handle) ~= "table" then
    Net._close_openrouter_catalog_operation(operation, true)
    local reason = Net._openrouter_failure_text(
      ok_endpoints and endpoints_failure or endpoints_handle,
      RA.t("settings.openrouter.operation.reason.start_failed", nil,
        "start failed"))
    return false, RA.t(
      "settings.openrouter.catalog.provider_start_failed", {
        reason = reason,
      }, "OpenRouter provider lookup could not start: " .. reason)
  end
  operation.handles.endpoints = endpoints_handle
  S.openrouter_catalog_operation = operation
  Net._set_openrouter_settings_status("catalog", "running",
    Net._openrouter_message(
      "settings.openrouter.catalog.provider_running", nil,
      "Refreshing OpenRouter provider catalog..."))
  return true
end

function Net.openrouter_preset_catalog_start()
  if type(S.openrouter_catalog_operation) == "table" then
    return false, RA.t("settings.openrouter.catalog.already_running", nil,
      "An OpenRouter catalog refresh is already running.")
  end
  local api_key = S.api_key_map and S.api_key_map.openrouter or nil
  if type(api_key) ~= "string" or api_key == "" then
    return false, RA.t("settings.openrouter.preset.key_required", nil,
      "Enter an OpenRouter API key before refreshing presets.")
  end
  if type(Engine) ~= "table"
      or type(Engine.openrouter_catalog_start) ~= "function" then
    return false, RA.t("settings.openrouter.catalog.engine_unavailable", nil,
      "The OpenRouter catalog is unavailable.")
  end
  local ok_secret, secret_json = pcall(RA.JSON.encode, {api_key = api_key})
  if not ok_secret or type(secret_json) ~= "string" then
    return false, RA.t("settings.openrouter.catalog.credential_failed", nil,
      "Could not prepare the OpenRouter catalog credential.")
  end
  local operation = {
    operation_kind = "presets", handles = {}, snapshots = {},
  }
  local ok_start, handle, failure = pcall(
    Engine.openrouter_catalog_start, "presets", nil, secret_json)
  secret_json = nil
  if not ok_start or type(handle) ~= "table" then
    Net._close_openrouter_catalog_operation(operation, true)
    local reason = Net._openrouter_failure_text(ok_start and failure or handle,
      RA.t("settings.openrouter.operation.reason.start_failed", nil,
        "start failed"))
    return false, RA.t("settings.openrouter.preset.start_failed_reason", {
      reason = reason,
    }, "OpenRouter preset lookup could not start: " .. reason)
  end
  operation.handles.presets = handle
  S.openrouter_catalog_operation = operation
  Net._set_openrouter_settings_status("presets", "running",
    Net._openrouter_message("settings.openrouter.preset.refreshing", nil,
      "Refreshing OpenRouter presets..."))
  return true
end

function Net._openrouter_catalog_endpoint_for_store(source)
  local pricing = type(source.pricing) == "table" and source.pricing or {}
  local output = {
    tag = source.tag,
    provider_name = source.provider_name or source.name or source.tag,
    pricing = {
      input = pricing.prompt,
      output = pricing.completion,
      cache_read = pricing.input_cache_read,
      cache_write = pricing.input_cache_write,
    },
    context_length = source.context_length,
    max_output = source.max_completion_tokens,
    quantization = source.quantization,
    supported_parameters = source.supported_parameters,
    supports_implicit_caching = source.supports_implicit_caching,
    uptime = source.uptime_last_5m or source.uptime_last_30m
      or source.uptime_last_1d,
    latency = type(source.latency_last_30m) == "table"
      and source.latency_last_30m.p50 or nil,
    throughput = type(source.throughput_last_30m) == "table"
      and source.throughput_last_30m.p50 or nil,
  }
  return output
end

function Net._finish_openrouter_catalog_operation(operation)
  if operation.operation_kind == "presets" then
    local presets = operation.snapshots.presets
    if type(presets) ~= "table" or presets.kind ~= "presets" then
      return false, RA.t("settings.openrouter.preset.catalog_mismatch", nil,
        "OpenRouter preset catalog did not match the request.")
    end
    local fetched_at = os.time()
    local snapshot = {
      snapshot_revision = 1,
      fetched_at_utc = fetched_at,
      expires_at_utc = fetched_at + OpenRouter.CATALOG_TTL_SECONDS,
      total_count = presets.total_count,
      presets = Store._copy_json_value(presets.presets or {}),
    }
    local clean, validation_error =
      OpenRouter.validate_preset_catalog_snapshot(snapshot)
    if not clean then return false, tostring(validation_error) end
    local save_error = Store.replace_openrouter_preset_catalog_snapshot(clean)
    if save_error then return false, tostring(save_error) end
    return true, clean
  end
  local endpoints = operation.snapshots.endpoints
  if type(endpoints) ~= "table" or endpoints.kind ~= "endpoints"
      or endpoints.model_id ~= operation.model_id then
    return false, RA.t("settings.openrouter.catalog.snapshot_mismatch", nil,
      "OpenRouter catalog snapshots did not match the requested model.")
  end
  local fetched_at = os.time()
  local snapshot = {
    snapshot_revision = 1,
    model_id = operation.model_id,
    fetched_at_utc = fetched_at,
    expires_at_utc = fetched_at + OpenRouter.CATALOG_TTL_SECONDS,
    endpoints = {},
  }
  for index, endpoint in ipairs(endpoints.endpoints or {}) do
    snapshot.endpoints[index] =
      Net._openrouter_catalog_endpoint_for_store(endpoint)
  end
  local clean, validation_error = OpenRouter.validate_catalog_snapshot(
    snapshot, operation.model_id)
  if not clean then return false, tostring(validation_error) end
  local profile = OpenRouter.profile()
  if profile.model_id == operation.model_id and profile.read_only ~= true then
    local save_error = Store.replace_openrouter_catalog_snapshot(clean)
    if save_error then return false, tostring(save_error) end
  else
    OpenRouter._preview_catalog_model_id = operation.model_id
    OpenRouter._preview_catalog_snapshot = clean
  end
  return true, clean
end

function Net.poll_openrouter_catalog()
  local operation = S.openrouter_catalog_operation
  if type(operation) ~= "table" then return false end
  local requested_kinds = operation.operation_kind == "presets"
    and {"presets"} or {"endpoints"}
  for _, kind in ipairs(requested_kinds) do
    if operation.snapshots[kind] == nil then
      local handle = operation.handles[kind]
      local ok_status, status, status_failure = pcall(
        Engine.openrouter_catalog_status, handle)
      if not ok_status or type(status) ~= "table" then
        local reason = Net._openrouter_failure_text(
          ok_status and status_failure or status,
          RA.t("settings.openrouter.operation.reason.status_failed", nil,
            "status failed"))
        Net._close_openrouter_catalog_operation(operation, true)
        Net._set_openrouter_settings_status("catalog", "failed",
          Net._openrouter_message(
            "settings.openrouter.catalog.refresh_failed_reason", {
              reason = reason,
            }, "OpenRouter catalog refresh failed: " .. reason))
        return false
      end
      if status.state == "failed" or status.state == "cancelled"
          or status.state == "closed" or status.state == "consumed" then
        Net._close_openrouter_catalog_operation(operation, true)
        Net._set_openrouter_settings_status("catalog", "failed",
          Net._openrouter_message(
            "settings.openrouter.catalog.ended_state", {
              state = tostring(status.state),
            }, "OpenRouter catalog refresh ended in state "
              .. tostring(status.state) .. "."))
        return false
      end
      if status.state == "completed" then
        local ok_read, snapshot, read_failure = pcall(
          Engine.openrouter_catalog_read, handle)
        if not ok_read or type(snapshot) ~= "table" then
          local reason = Net._openrouter_failure_text(
            ok_read and read_failure or snapshot,
            RA.t("settings.openrouter.operation.reason.read_failed", nil,
              "read failed"))
          Net._close_openrouter_catalog_operation(operation, true)
          Net._set_openrouter_settings_status("catalog", "failed",
            Net._openrouter_message(
              "settings.openrouter.catalog.refresh_failed_reason", {
                reason = reason,
              }, "OpenRouter catalog refresh failed: " .. reason))
          return false
        end
        operation.snapshots[kind] = snapshot
        pcall(Engine.openrouter_catalog_close, handle)
      end
    end
  end
  local completed = operation.operation_kind == "presets"
    and operation.snapshots.presets or operation.snapshots.endpoints
  if completed then
    local ok_finish, saved, finish_reason = pcall(
      Net._finish_openrouter_catalog_operation, operation)
    Net._close_openrouter_catalog_operation(operation, false)
    if not ok_finish or saved ~= true then
      local reason = Net._openrouter_failure_text(
        ok_finish and finish_reason or saved,
        RA.t("settings.openrouter.operation.reason.snapshot_rejected", nil,
          "snapshot rejected"))
      Net._set_openrouter_settings_status("catalog", "failed",
        Net._openrouter_message("settings.openrouter.catalog.save_failed", {
          reason = reason,
        }, "OpenRouter catalog could not be saved: " .. reason))
      return false
    end
    if operation.operation_kind == "presets" then
      Net._set_openrouter_settings_status("presets", "completed",
        Net._openrouter_message("settings.openrouter.preset.completed", nil,
          "OpenRouter preset catalog refreshed."), {
          preset_count = #(finish_reason.presets or {}),
          total_count = finish_reason.total_count,
          truncated = finish_reason.total_count
            > #(finish_reason.presets or {}),
          fetched_at_utc = finish_reason.fetched_at_utc,
        })
    else
      Net._set_openrouter_settings_status("catalog", "completed",
        Net._openrouter_message("settings.openrouter.catalog.completed", nil,
          "OpenRouter provider catalog refreshed."), {
          model_id = operation.model_id,
          endpoint_count = #(finish_reason.endpoints or {}),
          fetched_at_utc = finish_reason.fetched_at_utc,
        })
    end
    return false
  end
  return true
end

function Net._close_openrouter_deliberate_test(operation, cancel)
  operation = operation or S.openrouter_deliberate_test_operation
  if type(operation) ~= "table" then return end
  local handle = operation.handle
  if type(handle) == "table" and handle.closed ~= true then
    if cancel == true and type(Engine.inference_cancel) == "function" then
      pcall(Engine.inference_cancel, handle)
    end
    if type(Engine.inference_close) == "function" then
      pcall(Engine.inference_close, handle)
    end
  end
  if S.openrouter_deliberate_test_operation == operation then
    S.openrouter_deliberate_test_operation = nil
  end
end

function Net.openrouter_deliberate_test_cancel(silent)
  local operation = S.openrouter_deliberate_test_operation
  if type(operation) ~= "table" then return false, "no_test_operation" end
  Net._close_openrouter_deliberate_test(operation, true)
  if silent ~= true then
    Net._set_openrouter_settings_status("test", "cancelled",
      Net._openrouter_message("settings.openrouter.test.cancelled", nil,
        "OpenRouter billed test cancelled. A request already sent may still be billed."))
  end
  return true
end

function Net._openrouter_chat_reasoning_fields(effort, display_mode)
  if type(effort) ~= "string" or effort == "" then return nil, nil end
  return effort, display_mode ~= "provider_visible"
end

function Net._openrouter_deliberate_test_input(protocol)
  local input = {
    messages = {{role = "user", content = "Reply with OK."}},
  }
  if protocol == "openrouter_responses" then
    input.max_output_tokens = 16
  elseif protocol == "openrouter_chat_completions" then
    input.max_completion_tokens = 16
    local effort, exclude = Net._openrouter_chat_reasoning_fields(nil, "off")
    if effort ~= nil then
      input.reasoning_effort = effort
      input.reasoning_exclude = exclude
    end
  else
    return nil
  end
  return input
end

function Net.openrouter_deliberate_test_start(profile)
  if type(S.openrouter_deliberate_test_operation) == "table" then
    return false, RA.t("settings.openrouter.test.already_running", nil,
      "An OpenRouter billed test is already running.")
  end
  profile = type(profile) == "table" and profile or OpenRouter.profile()
  local provider_options_json, options_error =
    OpenRouter.dispatch_options_json(profile)
  if not provider_options_json then return false, tostring(options_error) end
  local api_key = S.api_key_map and S.api_key_map.openrouter or nil
  if type(api_key) ~= "string" or api_key == "" then
    return false, RA.t("settings.openrouter.test.key_required", nil,
      "Enter an OpenRouter API key before running the billed test.")
  end
  local provider = PROVIDERS.get("openrouter")
  local model = provider and provider.models and provider.models[1] or nil
  local protocol = profile.api_format == "responses"
      and "openrouter_responses" or "openrouter_chat_completions"
  if type(model) ~= "table" or model.id ~= profile.model_id
      or type(Engine) ~= "table"
      or type(Engine.inference_start) ~= "function"
      or type(Engine.new_canonical_accumulator) ~= "function" then
    return false, RA.t("settings.openrouter.test.engine_unavailable", nil,
      "The OpenRouter connection is unavailable.")
  end
  local input = Net._openrouter_deliberate_test_input(protocol)
  if type(input) ~= "table" then
    return false, RA.t(
      "settings.openrouter.test.api_format_unavailable", nil,
      "The OpenRouter billed test API format is unavailable.")
  end
  local ok_input, input_json = pcall(RA.JSON.encode, input)
  if not ok_input or type(input_json) ~= "string" then
    return false, RA.t("settings.openrouter.test.input_failed", nil,
      "Could not prepare the OpenRouter billed test input.")
  end
  local seed = Net._new_native_seed("openrouter", model.id, protocol,
    input_json, nil, false, false, "off")
  local documents, _, _, map_error = Net._map_engine_inference_seed(
    seed, provider, model, protocol, api_key, "off", {},
    provider_options_json)
  if type(documents) ~= "table" then return false, tostring(map_error) end
  local ok_start, handle, start_failure = pcall(Engine.inference_start,
    documents.public_json, documents.secret_json, documents.input_json)
  if not ok_start or type(handle) ~= "table" then
    local reason = Net._openrouter_failure_text(
      ok_start and start_failure or handle,
      RA.t("settings.openrouter.operation.reason.start_failed", nil,
        "start failed"))
    return false, RA.t("settings.openrouter.test.start_failed_reason", {
      reason = reason,
    }, "OpenRouter billed test could not start: " .. reason)
  end
  local accumulator = Engine.new_canonical_accumulator(handle.request_id)
  if type(accumulator) ~= "table" then
    pcall(Engine.inference_close, handle)
    return false, RA.t("settings.openrouter.test.accumulator_failed", nil,
      "OpenRouter billed test accumulator could not start.")
  end
  S.openrouter_deliberate_test_operation = {
    handle = handle,
    accumulator = accumulator,
    model_id = model.id,
    protocol = protocol,
  }
  Net._set_openrouter_settings_status("test", "running",
    Net._openrouter_message("settings.openrouter.test.running", nil,
      "OpenRouter billed test is running..."))
  return true
end

function Net.poll_openrouter_deliberate_test()
  local operation = S.openrouter_deliberate_test_operation
  if type(operation) ~= "table" then return false end
  local ok_status, status, status_failure = pcall(
    Engine.inference_status, operation.handle)
  if not ok_status or type(status) ~= "table" or status.ok ~= true then
    local reason = Net._openrouter_failure_text(
      ok_status and status_failure or status,
      RA.t("settings.openrouter.operation.reason.status_failed", nil,
        "status failed"))
    Net._close_openrouter_deliberate_test(operation, true)
    Net._set_openrouter_settings_status("test", "failed",
      Net._openrouter_message("settings.openrouter.test.status_failed", {
        reason = reason,
      }, "OpenRouter billed test status failed: " .. reason))
    return false
  end
  local consumed = 0
  while consumed < 256 do
    local ok_read, event, read_failure = pcall(
      Engine.inference_read, operation.handle)
    if not ok_read or (event == nil and read_failure ~= nil) then
      local reason = Net._openrouter_failure_text(
        ok_read and read_failure or event,
        RA.t("settings.openrouter.operation.reason.read_failed", nil,
          "read failed"))
      Net._close_openrouter_deliberate_test(operation, true)
      Net._set_openrouter_settings_status("test", "failed",
        Net._openrouter_message("settings.openrouter.test.read_failed", {
          reason = reason,
        }, "OpenRouter billed test read failed: " .. reason))
      return false
    end
    if event == nil then break end
    local ok_consume, accepted, consume_reason = pcall(
      operation.accumulator.consume, operation.accumulator, event)
    if not ok_consume or accepted ~= true then
      local reason = tostring(ok_consume and consume_reason or accepted)
      Net._close_openrouter_deliberate_test(operation, true)
      Net._set_openrouter_settings_status("test", "failed",
        Net._openrouter_message("settings.openrouter.test.event_rejected", {
          reason = reason,
        }, "OpenRouter billed test event was rejected: " .. reason))
      return false
    end
    consumed = consumed + 1
  end
  local ok_fresh, fresh, fresh_failure = pcall(
    Engine.inference_status, operation.handle)
  if not ok_fresh or type(fresh) ~= "table" or fresh.ok ~= true then
    local reason = Net._openrouter_failure_text(
      ok_fresh and fresh_failure or fresh,
      RA.t("settings.openrouter.operation.reason.final_status_failed", nil,
        "final status failed"))
    Net._close_openrouter_deliberate_test(operation, true)
    Net._set_openrouter_settings_status("test", "failed",
      Net._openrouter_message("settings.openrouter.test.status_failed", {
        reason = reason,
      }, "OpenRouter billed test status failed: " .. reason))
    return false
  end
  if consumed == 256 or fresh.terminal ~= true
      or tonumber(fresh.events_pending) ~= 0 then
    return true
  end
  local ok_final, result, outcome, terminal_evidence = pcall(
    operation.accumulator.finalize, operation.accumulator, fresh)
  Net._close_openrouter_deliberate_test(operation, false)
  if not ok_final or type(result) ~= "table" then
    local evidence = type(terminal_evidence) == "table"
      and terminal_evidence or {}
    local detail = evidence.error_msg or evidence.error or outcome or result
    local reason = tostring(detail or RA.t(
      "settings.openrouter.operation.reason.unknown", nil, "unknown"))
    Net._set_openrouter_settings_status("test", "failed",
      Net._openrouter_message("settings.openrouter.test.failed_reason", {
        reason = reason,
      }, "OpenRouter billed test failed: " .. reason))
    return false
  end
  local usage = type(result.usage) == "table" and result.usage or {}
  local cost = type(usage.actual_cost) == "table"
      and usage.actual_cost.decimal or nil
  local routing = type(result.routing_provenance) == "table"
      and result.routing_provenance or {}
  local display_cost = MODELS.format_exact_cost_decimal(cost)
  local selected_provider = routing.selected_provider
  local message_key = display_cost and selected_provider
      and selected_provider ~= ""
      and "settings.openrouter.test.completed_cost_provider"
    or display_cost and "settings.openrouter.test.completed_cost"
    or selected_provider and selected_provider ~= ""
      and "settings.openrouter.test.completed_provider"
    or "settings.openrouter.test.completed"
  local fallback = "OpenRouter billed test completed."
  if display_cost then fallback = fallback .. " Actual cost: $" .. display_cost .. "." end
  if selected_provider and selected_provider ~= "" then
    fallback = fallback .. " Provider: " .. tostring(selected_provider) .. "."
  end
  Net._set_openrouter_settings_status("test", "completed",
    Net._openrouter_message(message_key, {
      cost = display_cost or "",
      provider = tostring(selected_provider or ""),
    }, fallback), {
    model_id = operation.model_id,
    protocol = operation.protocol,
    actual_cost_decimal = cost,
    selected_provider = selected_provider,
    selected_endpoint = routing.selected_endpoint,
    fallback_occurred = routing.fallback_occurred,
    input_tokens = usage.input_tokens,
    output_tokens = usage.output_tokens,
    cached_input_tokens = usage.cached_input_tokens,
    cache_write_input_tokens = usage.cache_write_input_tokens,
    reasoning_tokens = usage.reasoning_tokens,
  })
  return false
end

function Net.cancel_openrouter_settings_operations()
  Net.openrouter_catalog_cancel(true)
end

function Net.custom_instructions_prompt_block_for_request()
  local request_key = S and S.probe_turn or nil
  if request_key and S._custom_instr_prompt_key == request_key then
    return S._custom_instr_prompt_block
  end
  local blob = Store and Store.custom_instructions_prompt_block
    and Store.custom_instructions_prompt_block() or nil
  if request_key then
    S._custom_instr_prompt_key = request_key
    S._custom_instr_prompt_block = blob
  end
  return blob
end

-- =============================================================================
-- Custom-LLM connection test helpers
-- =============================================================================
-- Supports the Test Connection button on the custom_llm page. Fires a single
-- GET /v1/models request against the currently entered endpoint (without
-- requiring Save) and stores pass/fail in api_keys.custom_conn_test.result.
--
-- The test is model-agnostic -- /v1/models is a server directory listing, so
-- it only verifies the server is reachable + auth works. This is the most
-- information we can extract without running inference (which would invoke
-- reasoning on models like deepseek-r1 and block the test).
--
-- Implementation temporarily registers a minimal custom provider, fires
-- Net.fire_key_test (which dispatches custom providers to GET /v1/models),
-- then restores the originally-saved config on finish.
-- Placed after `local Net = {}` so the closures capture Net as an upvalue
-- instead of resolving it as a (nil) global.

-- Synthetic id used exclusively for the in-flight connection-test provider.
-- Double-underscore prefix makes it impossible to collide with any id that
-- Custom.gen_id() produces ("custom_" + 8 hex). Never persisted: the test
-- flow only touches in-memory PROVIDERS + S.api_key_map, never Key.save.
CUSTOM_CONN_TEST_ID = "__cllm_conn_test__"

-- Build a throwaway record from cfg_base, append it to PROVIDERS under the
-- conn-test sentinel id, and select it as the active provider. The model id
-- is a placeholder -- the GET /v1/models test doesn't reference it. Returns
-- the new provider index, or nil on failure. cfg_base carries the advanced
-- fields (connect_timeout, allow_insecure, extra_headers, model_prefix) so
-- the test exercises the same curl options the real request will use.
local function custom_conn_test_register(cfg_base)
  -- Default model id: a placeholder safe for the GET /v1/models path
  -- (which doesn't reference it). When the caller opts into the real-
  -- inference path, swap in the user's first model id from the form so
  -- the chat/completions POST hits the right model -- the placeholder
  -- would just earn an "unknown model" rejection from the server.
  local model_id_for_test = "conn-test"
  if cfg_base.use_inference_test and type(cfg_base.test_model_id) == "string"
     and cfg_base.test_model_id ~= "" then
    model_id_for_test = cfg_base.test_model_id
  end
  -- Provider-wide and per-model extra_body get plumbed through ONLY for
  -- the inference test path (GET /v1/models doesn't send a body, so the
  -- extras are irrelevant there). Net.merge_custom_extra_body reads
  -- p.extra_body and p.models[1].extra_body to assemble the merged
  -- vendor-toggle suffix that real chat would send.
  local record = {
    id                   = CUSTOM_CONN_TEST_ID,
    endpoint             = cfg_base.endpoint,
    timeout_secs         = cfg_base.timeout_secs,
    connect_timeout_secs = cfg_base.connect_timeout_secs,
    allow_insecure       = cfg_base.allow_insecure,
    model_prefix         = cfg_base.model_prefix,
    extra_headers        = cfg_base.extra_headers,
    label                = cfg_base.label,
    extra_body           = (cfg_base.use_inference_test
                              and cfg_base.extra_body) or "",
    models               = { {
      id             = model_id_for_test,
      price_in       = 0,
      price_out      = 0,
      context_window = CUSTOM_DEFAULT_CTX,
      extra_body     = (cfg_base.use_inference_test
                          and cfg_base.test_model_extra_body) or "",
      chat_token_limit_field = cfg_base.native_engine == true
        and cfg_base.record_format == "chat_completions"
        and cfg_base.test_model_chat_token_limit_field or nil,
    } },
  }
  if cfg_base.native_engine == true then
    record.profile_kind = cfg_base.profile_kind
    record.record_format = cfg_base.record_format
    record.private_network_origin = cfg_base.private_network_origin
    local endpoint_info = Custom.admit_native_endpoint(record.endpoint,
      record.record_format, record.profile_kind,
      record.private_network_origin)
    record.profile_id = Custom.native_profile_id(cfg_base.profile_kind,
      cfg_base.record_format, endpoint_info
        and endpoint_info.destination_class == "private_network")
    record.protocol = Custom.native_protocol(cfg_base.record_format)
    record.auth_mode = cfg_base.auth_mode
  end
  -- Defensive: if a prior test left the sentinel registered, drop it first.
  Custom.unregister_id(CUSTOM_CONN_TEST_ID)
  local cust_idx
  if cfg_base.native_engine == true then
    cust_idx = CustomNative.register_connection_test(record)
  else
    cust_idx = Custom.register_connection_test(record)
  end
  if cust_idx then
    -- Stamp the runtime-only flag on the registered provider entry so
    -- Net.fire_key_test / Net.handle_key_test can dispatch on it. Lives
    -- on the throwaway PROVIDERS slot only -- gets dropped with the
    -- sentinel in custom_conn_test_finish.
    if cfg_base.use_inference_test then
      PROVIDERS[cust_idx].use_inference_test = true
    end
    if cfg_base.native_engine == true then
      PROVIDERS[cust_idx].native_profile_test = true
    end
    prefs.provider_idx = cust_idx
    MODELS.refresh()
  end
  return cust_idx
end

-- Validate current form values on the custom_llm edit screen and fire a
-- single connection test. Called by the "Test Connection" button. Writes
-- per-field errors on failure. Returns true if the test was fired, false
-- otherwise. Reads from api_keys.custom_edit, which is populated when the
-- user navigates into the edit screen (new record or existing record).
function CTX.custom_llm_start_conn_test()
  local edit = api_keys.custom_edit
  if not edit then return false end
  edit.errors = {}
  local has_format_error = false
  local native_mode = edit.storage_kind == "native_engine"

  local endpoint_t  = (edit.endpoint        or ""):match("^%s*(.-)%s*$") or ""
  endpoint_t = native_mode
    and Custom.normalize_native_endpoint(endpoint_t, edit.record_format)
    or Custom.normalize_chat_endpoint(endpoint_t)
  if edit.endpoint ~= endpoint_t then edit.endpoint = endpoint_t end
  local timeout_t   = (edit.timeout         or ""):match("^%s*(.-)%s*$") or ""
  local ctimeout_t  = (edit.connect_timeout or ""):match("^%s*(.-)%s*$") or ""
  local label_t     = (edit.label           or ""):match("^%s*(.-)%s*$") or ""
  local key_t       = (edit.key             or ""):match("^%s*(.-)%s*$") or ""
  local prefix_t    = (edit.model_prefix    or ""):match("^%s*(.-)%s*$") or ""

  if label_t == "" then
    edit.errors.label = Custom.t("settings.custom.error.name_required", nil,
      "Name is required.")
    has_format_error = true
  end

  if not endpoint_t:match("^https?://") then
    edit.errors.endpoint = Custom.t("settings.custom.error.endpoint_scheme", nil,
      "Endpoint must start with http:// or https://.")
    has_format_error = true
  elseif endpoint_t:find("[\"'`%c]") then
    -- Reject characters that would break (or escape out of) the
    -- powershell + cmd quoting in Net.fire_curl.
    edit.errors.endpoint = Custom.t("settings.custom.error.endpoint_chars", nil,
      "Endpoint may not contain quotes, backticks, or control characters.")
    has_format_error = true
  elseif native_mode then
    local endpoint_info, endpoint_reason = Custom.admit_native_endpoint(
      endpoint_t, edit.record_format, edit.profile_kind,
      edit.private_network_origin)
    if not endpoint_info then
      edit.errors.endpoint = Custom.native_endpoint_error(endpoint_reason)
      has_format_error = true
    end
  elseif not native_mode
      and not Custom.endpoint_is_chat_completions(endpoint_t) then
    edit.errors.endpoint = Custom.t(
      "settings.custom.error.endpoint_chat_completions", nil,
      "Use the full chat-completions URL, for example http://localhost:1234/v1/chat/completions.")
    has_format_error = true
  end

  local timeout_n = tonumber(timeout_t == "" and tostring(CUSTOM_DEFAULT_TIMEOUT) or timeout_t)
  if not timeout_n or timeout_n < CUSTOM_MIN_TIMEOUT then
    edit.errors.timeout = Custom.t("settings.custom.error.timeout_min",
      { min = CUSTOM_MIN_TIMEOUT },
      str_format("Timeout must be a number >= %d seconds.",
        CUSTOM_MIN_TIMEOUT))
    has_format_error = true
  elseif timeout_n > CUSTOM_MAX_TIMEOUT then
    edit.errors.timeout = Custom.t("settings.custom.error.timeout_max",
      { max = CUSTOM_MAX_TIMEOUT },
      str_format("Timeout must be <= %d seconds (1 hour).",
        CUSTOM_MAX_TIMEOUT))
    has_format_error = true
  end

  local ctimeout_n = tonumber(ctimeout_t == "" and tostring(Custom.DEFAULT_CONNECT) or ctimeout_t)
  if not ctimeout_n or ctimeout_n < Custom.MIN_CONNECT or ctimeout_n > Custom.MAX_CONNECT then
    edit.errors.connect_timeout =
      Custom.t("settings.custom.error.connect_timeout_range",
        { min = Custom.MIN_CONNECT, max = Custom.MAX_CONNECT },
        str_format(
          "Connect timeout must be a number between %d and %d seconds.",
          Custom.MIN_CONNECT, Custom.MAX_CONNECT))
    has_format_error = true
  end
  if native_mode and timeout_n and ctimeout_n
      and (timeout_n ~= math_floor(timeout_n)
        or ctimeout_n ~= math_floor(ctimeout_n)
        or timeout_n < ctimeout_n) then
    edit.errors.timeout = Custom.t("settings.custom.error.native_timeouts", nil,
      "Timeouts must be whole seconds. The request timeout must be at least the connect timeout.")
    has_format_error = true
  end

  local headers_arr, headers_err = {}, nil
  if not native_mode then
    headers_arr, headers_err = Custom.parse_headers_text(
      edit.headers_text or "")
  end
  if headers_err then
    edit.errors.headers = headers_err
    has_format_error = true
  end

  if key_t ~= "" then
    local lk_valid, lk_reason = Key.validate_format(key_t,
      { is_custom = true, key_prefix = "", key_min_len = 0 })
    if not lk_valid then
      edit.errors.key = lk_reason
      has_format_error = true
    end
  end
  if native_mode and edit.auth_mode == "bearer" and key_t == "" then
    edit.errors.key = Custom.t("settings.custom.error.native_key_required", nil,
      "This provider requires an API key.")
    has_format_error = true
  end

  -- Opt-in real-inference test: only fires if the user ticked the
  -- checkbox AND filled in at least one model id. Without a model id we
  -- have nothing to send in the chat/completions body, so block the
  -- attempt with a clear per-field error rather than firing a malformed
  -- request and getting a confusing server-side error back.
  local use_inference = native_mode
    or edit.test_with_inference and true or false
  local first_model_id = ""
  if type(edit.models) == "table" and edit.models[1] then
    first_model_id = (edit.models[1].id or ""):match("^%s*(.-)%s*$") or ""
  end
  if use_inference and first_model_id == "" then
    -- Surface via the test-result panel since edit.errors.models has no
    -- inline renderer. This puts the message right where the user is
    -- looking after they click Test Connection.
    if api_keys.custom_conn_test then
      api_keys.custom_conn_test.result = {
        ok    = false,
        error = Custom.t("settings.custom.error.inference_model_required", nil,
          "Add at least one model id before running an inference test."),
      }
    end
    return false
  end
  if native_mode and not CustomNative.model_id_is_valid(first_model_id) then
    if api_keys.custom_conn_test then
      api_keys.custom_conn_test.result = {
        ok = false,
        error = Custom.t("settings.custom.error.native_model_id", nil,
          "Model IDs must use 1 to 256 printable ASCII characters without spaces."),
      }
    end
    return false
  end

  if has_format_error then return false end

  local cfg_base = {
    endpoint             = endpoint_t,
    timeout_secs         = timeout_n or CUSTOM_DEFAULT_TIMEOUT,
    connect_timeout_secs = ctimeout_n or Custom.DEFAULT_CONNECT,
    allow_insecure       = edit.allow_insecure and true or false,
    model_prefix         = prefix_t,
    extra_headers        = headers_arr,
    label                = label_t,
    use_inference_test   = use_inference,
    test_model_id        = first_model_id,
    -- Provider-wide and per-model extra_body. Only consumed by the
    -- inference test path; the GET /v1/models path sends no body so it
    -- ignores them. Pass the form values raw -- merge_custom_extra_body
    -- silently discards malformed JSON, so we don't need to re-run the
    -- save-time canonicalizer here.
    extra_body              = edit.extra_body or "",
    test_model_extra_body   = (edit.models and edit.models[1]
                                and edit.models[1].extra_body) or "",
    test_model_chat_token_limit_field = native_mode
      and edit.record_format == "chat_completions"
      and edit.models and edit.models[1]
      and edit.models[1].chat_token_limit_field or nil,
    native_engine           = native_mode,
    profile_kind            = edit.profile_kind,
    record_format           = edit.record_format,
    auth_mode               = edit.auth_mode,
    private_network_origin  = edit.private_network_origin,
  }
  CTX.custom_conn_test_start(cfg_base, key_t)
  return true
end

-- Start the connection test. cfg_base carries shared config (endpoint,
-- timeout, label); api_key is the auth key (or "" for none). The test
-- registers a throwaway provider under CUSTOM_CONN_TEST_ID and stashes
-- the active provider's index so finish() can restore it.
function CTX.custom_conn_test_start(cfg_base, api_key)
  local state = api_keys.custom_conn_test
  state.active            = true
  state.started           = reaper.time_precise()
  state.timeout           = CUSTOM_DEFAULT_TEST_TIMEOUT
  state.result            = nil   -- cleared; filled by advance()
  state.orig_provider_idx = prefs.provider_idx
  S.api_key_map[CUSTOM_CONN_TEST_ID] = (api_key ~= "" and api_key) or nil

  local cust_idx = custom_conn_test_register(cfg_base)
  local cust_prov = cust_idx and PROVIDERS[cust_idx] or nil
  if not cust_prov then
    CTX.custom_conn_test_advance(false,
      Custom.t("settings.custom.error.register_failed", nil,
        "Could not register custom provider."))
    return
  end
  S.api_key = S.api_key_map[CUSTOM_CONN_TEST_ID]
  api_keys.key_validating     = true
  api_keys.key_validating_idx = cust_idx
  -- Publish the test timeout for Net.fire_curl to pick up.
  S.key_test_custom_timeout = state.timeout
  api_keys.start_key_test("custom")
  Net.fire_key_test(cust_prov)
end

-- Record the test's pass/fail result and finish. Called by Net.handle_key_test
-- and by the various error paths in Net.fire_curl / Net.try_finish_curl.
function CTX.custom_conn_test_advance(ok, err_msg)
  local state = api_keys.custom_conn_test
  state.result = { ok = ok, error = err_msg }
  S.key_test_pending  = false
  S.key_test_provider = nil
  S.curl_pid          = nil
  CTX.custom_conn_test_finish()
end

-- Cancel an in-flight connection test. Kills any active curl request, marks
-- the result as cancelled, and restores the original custom config via finish().
function CTX.custom_conn_test_cancel()
  local state = api_keys.custom_conn_test
  if not state or not state.active then return end
  if Net.kill_curl then pcall(Net.kill_curl) end
  state.result        = {
    ok    = false,
    error = Custom.t("settings.custom.status.cancelled", nil,
      "Test cancelled."),
  }
  S.key_test_pending  = false
  S.key_test_provider = nil
  S.curl_pid          = nil
  CTX.custom_conn_test_finish()
end

-- Drop the throwaway conn-test provider, restore the previous active
-- provider, and clear transient state. Leaves state.result in place so
-- the UI can render the pass/fail message until the user clicks Test
-- Connection again or leaves the page. Persisted records are never
-- touched -- register_all was called at startup and stays in effect.
-- Idempotent: if the test was already finished (watchdog + advance racing,
-- or Cancel double-click), the second call is a no-op.
function CTX.custom_conn_test_finish()
  local state = api_keys.custom_conn_test
  if not state or not state.active then return end
  state.active                = false
  state.started               = nil
  -- Remove the throwaway provider and its in-memory key. The sentinel id is
  -- reserved, so wiping the key unconditionally is safe -- nothing else
  -- ever writes to S.api_key_map[CUSTOM_CONN_TEST_ID].
  Custom.unregister_id(CUSTOM_CONN_TEST_ID)
  S.api_key_map[CUSTOM_CONN_TEST_ID] = nil
  -- Restore active provider index (clamp if out of range).
  local orig_idx = state.orig_provider_idx or 1
  if orig_idx < 1 or orig_idx > #PROVIDERS then orig_idx = 1 end
  prefs.provider_idx = orig_idx
  MODELS.refresh()
  S.api_key = S.api_key_map[PROVIDERS.active().id]
  -- Clear transient flags.
  api_keys.key_validating     = false
  api_keys.key_validating_idx = nil
  S.status                    = "idle"
  S.key_test_custom_timeout   = nil
end

-- =============================================================================
-- Net.system_prompt_text
-- =============================================================================
-- General model guidance is separate from typed-action profiles. Typed-action
-- profiles change a structured contract; these notes are small hidden nudges
-- for a specific provider/model's everyday response habits.
Code.MODEL_GUIDANCE_BY_MODEL = Code.MODEL_GUIDANCE_BY_MODEL or {
  openai = {
    ["*"] = {
      key = "openai_explicit_sidechain_route",
      prompt = [[
- For explicit sidechain wording like "create a send from Voiceover to Music Bed", follow those named endpoints exactly: put the compressor on the destination/ducked track and create one direct source-to-destination send feeding sidechain channels. If the prompt also names a Sidechain Comp track, create/name that track only; do not route through it, send the destination into it, disable master send, or invent a separate sidechain/helper bus unless the user explicitly says that track is the bus.
- For named routing lists, create only the requested sends from the named sources to the named destination bus, return, or print track. Do not also route return/parallel/print/bus tracks to each other unless the user explicitly asks for those extra sends.
- When the user explicitly asks to set or change project tempo, call `reaper.SetCurrentBPM(0, N, true)` before timing calculations. A BPM mentioned as existing context does not require a tempo write. Exact-second marker requests need no tempo change.
- For MIDI items, `reaper.TakeIsMIDI` only accepts a take handle. Never call `reaper.TakeIsMIDI(item)` on a MediaItem variable; first use `local take = reaper.GetActiveTake(item)` and then check `reaper.TakeIsMIDI(take)`.
- For nested folders, an inner folder and an outer folder may need separate negative `I_FOLDERDEPTH` closes on different tracks. Do not remove the outer close when the inner folder is already closed.
- Track names like Pad Synth, Arp Synth, Lead Synth, Piano, Bass, or Keys are names only unless the user explicitly asks to load a virtual instrument, synth plugin, sampler, VSTi, or sound source. Do not add instrument plugins for those names.
- For JSFX memory, use explicit base variables and direct reads/writes such as `bufferL[i]` and `bufferR[i]`. Use readable DSP names; equivalent implementations may use abbreviations.
]],
      validators = {
        sidechain_ducking_requires_send = true,
      },
    },
    ["gpt-5.6-luna"] = {
      key = "luna_practical_track_routing",
      prompt = [[
- For simple track/routing setup, create only the requested or named tracks. Do not add helper, folder, parent, or container tracks unless the user explicitly asks for them.
- If the user asks to "select only" a track while doing another action, the selection change is required project state. Do not skip it as "touching less"; clear existing track selection and select only the target.
- `TrackFX_AddByName` returns exactly one integer FX index. Use `local fx = reaper.TrackFX_AddByName(...)`, then check `if fx < 0 then ... return end`; never use `local ok, fx = ...`.
- `CreateTrackSend(src, dst)` creates one send from that source to that destination. Do not call it twice for the same source/destination pair unless the user explicitly asks for duplicate sends.
- `GetSetMediaTrackInfo_String(track, "P_NAME", name, true)` always takes 4 arguments. For track names, never omit the final `true`.
- When you create a new track for an instrument, part, or MIDI idea, name that track for the part. For a drum MIDI idea, use a name containing "Drum".
- For ordinary action requests like create, add, make, put, set up, route, or select in REAPER, return a runnable fenced ```lua script. Do not answer with only a prose summary of what the script would do.
- For simple folder/template setup requests, treat plural category words like "guitars", "vocals", "keys", or "drums" as one category track named by that word unless the user gives a count or names separate parts. Do not ask how many tracks to create for those ordinary categories.
- For cue/routing setup requests that name source parts like vocal, guitar, or keys, ensure those named source tracks exist before creating sends. If the current session does not already contain a named source track, create it; do not silently skip a requested source because it is missing.
- For cue/headphones/monitor buses that should stay out of the master, set the bus track's `B_MAINSEND` to `0` with `SetMediaTrackInfo_Value`. Do not leave that bus feeding the master.
- Keep plug-in Lua direct. Use maintained mappings as guidance when they fit, or resolve requested controls by live parameter name and standard REAPER APIs. Configure only what the user requested.
- For JSFX delay, reverb, and grain/freezer effects, keep memory base names consistent across sections. If `@init` assigns `bufferL = 0`, use that same base in `@sample`. DSP identifiers may use abbreviations.
- For JSFX with several delay/comb/allpass buffers, allocate fixed unique base regions in `@init`. Do not initialize every buffer to `0` as placeholders, and do not compute buffer base offsets in `@slider`; slider changes can adjust tap lengths, not memory layout.
- For JSFX reverb code, names such as `allpass1L` can improve readability, but abbreviated identifiers are also valid.
]],
      validators = {
        exclusive_track_selection = true,
        created_track_inferred_name = true,
      },
    },
  },
  anthropic = {
    ["*"] = {
      key = "anthropic_practical_reascript_defaults",
      prompt = [[
- For ordinary safe ReaScript action/setup requests, return a runnable fenced ```lua script using practical defaults. Do not answer with only a prose setup question when the user names the tracks, sources, bus, return, MIDI idea, tempo, or setup goal.
- In an empty project, when the user names instrument/source parts for a setup, create those named tracks instead of asking whether they already exist.
- When the user asks for tracks going into a bus or return, create explicit sends with `reaper.CreateTrackSend(source_track, bus_or_return_track)` from every named non-destination source to the bus/return unless the user explicitly excludes a source. Folder depth alone is not bus routing.
- For cue/headphone/monitor buses that should be separate from or away from the main mix, set the cue bus track's own `B_MAINSEND` to `0` with `reaper.SetMediaTrackInfo_Value(cue_bus_track, "B_MAINSEND", 0)`.
- For named effect returns such as plate/reverb/delay returns, name the destination track with the requested effect word, for example "Plate Verb" for a plate reverb return, add the requested/resolved effect there, and route each named source to that return.
- For setup wording like "host, guest, music, and a bus", create the bus and route every named non-bus source track to it unless the user explicitly says a source should remain direct. Do not reinterpret that as a dialogue-only bus when Music is named; Music is a named source.
- For short MIDI ideas, beats, patterns, chords, or pads, create one appropriately named MIDI track and one MIDI item unless the user asks for separate tracks or separate items. Put multiple drums or chords into that one item; for a drum idea, name the track with "Drum" and include common GM kick/snare notes.
- For explicit sidechain wording like "create a send from Voiceover to Music Bed", follow those named endpoints exactly: put the compressor on the destination/ducked track and create one direct source-to-destination send feeding sidechain channels. If the prompt also names a Sidechain Comp track, create/name that track only; do not route through it, send the destination into it, disable master send, or invent a separate sidechain/helper bus unless the user explicitly says that track is the bus. For generic kick/bass ducking with no endpoints named, use Kick as source and Bass as destination.
- Keep plug-in scripts direct and small. For simple/basic/add-only chains, add the requested or resolved plug-ins in order and leave their defaults unchanged.
- Plain requests such as "add EQ and compression" are add-only when the user gives no settings, tonal goal, recipe, or starter/generic-treatment request. Insert the resolved plugins in the requested order at their defaults, check every AddByName result, and stop; do not invent settings, request fx_inspect, or use plugin helpers.
- Track/item custom colors written through I_CUSTOMCOLOR and reaper.ColorToNative are object colors, not application-theme edits. Do not request theme or prompt_bundle:theme unless actually calling reaper.SetThemeColor.
- For JSFX requests, return the requested ```jsfx block, not Lua/ReaScript. Preserve user-named DSP terms like allpass, buffer, grain, freeze, and width as readable identifiers or comments.
]],
      validators = {
        bus_routing_requires_sends = true,
        podcast_bus_routes_all_sources = true,
        sidechain_ducking_requires_send = true,
      },
    },
    ["claude-haiku-4-5"] = {
      key = "haiku_practical_track_templates",
      prompt = [[
- Prefer a runnable script for ordinary safe ReaScript action requests like create, add, make, set up, route, select, or organize. Do not answer with only a prose question or summary when a practical default exists.
- For simple folder/template setup requests, treat plural category words like "guitars", "vocals", "keys", or "drums" as one category track named by that word unless the user gives a count or names separate parts. Do not ask how many tracks to create for those ordinary categories.
- For folder setup, create only the requested folder/category tracks. Do not add extra lead/rhythm/helper tracks unless the user explicitly asks for them.
- Treat aliases like "comp" or "compression" as compressor requests. If `pref:` or `plugin_ref:` context is already pinned for the needed plugin type, use it and write the script; do not emit another `resolve:` request for that same type.
- For simple vocal chain requests, add the EQ and compressor in order and stop there unless the user asks for exact settings. Do not define `set_param_display`, use parameter helper functions, or defer parameter-setting code for a simple chain.
- For kick/bass ducking, the Kick-to-Bass send is mandatory. Create the send before any deferred compressor parameter setup, even if you also add/configure Pro-C or ReaComp.
- Keep plug-in code direct and small. Use standard REAPER parameter APIs and add a conversion helper only when the requested display value truly needs one.
]],
      validators = {
      },
    },
    ["claude-sonnet-5"] = {
      key = "sonnet5_explicit_bus_sends",
      prompt = [[
- When the user asks for tracks going into a bus or return, create explicit sends with `reaper.CreateTrackSend(source_track, bus_or_return_track)`. Folder depth alone is not bus routing and should not be used as a substitute unless the user explicitly asks for folders.
- Treat "basic EQ" by itself as add-only. Add the resolved EQ plugin to the requested/selected track(s), check each AddByName result, and stop there unless the user gives a tonal goal, explicit settings, or asks for starter/generic EQ settings. Do not use track-type starter EQ recipes, call `TrackFX_SetParam*`, or call/rewrite plugin helper functions for add-only/basic EQ tasks.
- For podcast setup wording like "host, guest, music, and a bus", Music is also a source. Route Host, Guest, and Music to the bus unless the user explicitly says Music should stay direct.
]],
      validators = {
        bus_routing_requires_sends = true,
      },
    },
    ["claude-opus-5"] = {
      key = "opus_practical_setup_defaults",
      prompt = [[
- For folder setup such as "put drums, bass, and guitar inside a band folder", create the folder/category track plus the named child tracks. Close the folder on the last child track, not on the following outside track.
]],
      validators = {
        bus_routing_requires_sends = true,
      },
    },
  },
  google = {
    ["*"] = {
      key = "google_explicit_sidechain_route",
      prompt = [[
- For explicit sidechain wording like "create a send from Voiceover to Music Bed", follow those named endpoints exactly: put the compressor on the destination/ducked track and create one direct source-to-destination send feeding sidechain channels. If the prompt also names a Sidechain Comp track, create/name that track only; do not route through it, send the destination into it, disable master send, or invent a separate sidechain/helper bus unless the user explicitly says that track is the bus.
- For cue/headphone/monitor setups that name tracks in a simple list, create those tracks in the user's order unless the user explicitly asks for a different order. Route named source tracks to the named cue bus and set the cue bus track's own `B_MAINSEND` to `0` when it should stay out of the master/main mix.
- When the user asks for tracks going into a bus or return, create explicit sends with `reaper.CreateTrackSend(source_track, bus_or_return_track)`. Folder depth alone is not bus routing.
- For podcast layouts with Dialog Bus, Music Bus, FX Bus, and Print Mix, create explicit sends from Host/Guest to Dialog Bus, Music Bed/Music to Music Bus, SFX to FX Bus, and then each bus to Print Mix.
- For JSFX requests, return the requested ```jsfx block, not Lua/ReaScript. Preserve user-named DSP terms like allpass, buffer, grain, freeze, and width as readable identifiers or comments.
]],
      validators = {
        bus_routing_requires_sends = true,
        sidechain_ducking_requires_send = true,
      },
    },
    ["gemini-3.5-flash-lite"] = {
      key = "flash_lite_practical_free_tier_actions",
      prompt = [[
- For ordinary action requests like create, add, make, put, set up, route, or select in REAPER, return a runnable fenced ```lua script. Do not answer with only a prose question, summary, or `<context_needed>` when a practical default exists.
- When an immediate action includes a `TARGET HINT` for selected/current tracks, first honor any tracks positively named or numbered in the current request and ignore `TARGET HINT` for those explicit targets. For a user-numbered target, check existence without requiring a snapshot-derived name unless the current request explicitly gives that name for that numbered target too. Otherwise, build the target list from every captured index/name pair first and validate each pair with `reaper.GetTrack` plus `reaper.GetTrackName`. If an index exists under a different name, stop before all edits and do not fall back to live selection. Only if every captured index no longer exists may you rebuild from `CountSelectedTracks`/`GetSelectedTrack`; never start from live selection.
- For short MIDI idea, beat, pattern, chord, or pad requests, create a new appropriately named MIDI track and item by default. Do not ask which track, instrument, or sample library to use unless the user explicitly says to use existing media or selected items.
- When the user asks for a drum beat or drum MIDI idea, create a track with a name containing "Drum" and add a small MIDI item using common GM pitches such as kick 36 and snare 38.
- When the user asks for intro, verse, chorus, bridge, or other song sections in time chunks, create timeline regions or markers. Do not create empty tracks or media items for sections unless the user explicitly asks for section tracks or items.
- For cue/routing setup requests that name source parts like vocal, guitar, or keys, ensure those named source tracks exist before creating sends. If the current session does not already contain a named source track, create it; do not silently skip a requested source because it is missing.
- For cue/headphone/monitor buses that should be separate from the main mix, set the cue bus track's own `B_MAINSEND` to `0` with `reaper.SetMediaTrackInfo_Value(cue_bus_track, "B_MAINSEND", 0)`. Disabling master send only on the source tracks is incomplete; the cue bus itself must not feed the master.
- When the user asks for tracks going into a bus or return, create explicit sends with `reaper.CreateTrackSend(source_track, bus_or_return_track)`. Folder depth alone is not bus routing.
- Keep plug-in Lua direct. Use maintained mappings as guidance when they fit, or resolve requested controls by live parameter name and standard REAPER APIs. Configure only what the user requested.
- For a request to modify an existing effect, when you use `TrackFX_GetByName` or `TakeFX_GetByName` to resolve that required effect, check `if fx < 0 then` and show a clear error plus `return` before any writes. Never use only `if fx >= 0 then ... end`, and do not put the missing-effect message in an `else` branch that continues to a success receipt. For add-and-configure requests, follow the ADD named plugin rule from `prompt_bundle:plugin` instead: add or upsert the requested effect and fail only if the required add also fails.
]],
      validators = {
        bus_routing_requires_sends = true,
      },
    },
  },
  deepseek = {
    ["deepseek-v4-flash"] = {
      key = "deepseek_compact_targeted",
      prompt = [[
- PINNED REFERENCES are complete inputs. Generate the requested runnable response now and never emit `<context_needed>` for a listed bucket. When SESSION CONTEXT is present, including `Tracks: none`, the `session` bucket is already complete and must never be requested again.
- For an open-ended plug-in chain, use every resolved preferred type listed in the final chain requirements unless the user excluded it. Return the complete runnable script in the first reply. Never return an empty Undo block, silently omit one of those resolved chain types, or claim project changes that are absent from the Lua.
- For ReaComp sidechain ducking, ensure the destination track has at least four channels, create one direct source-to-destination send, store its returned send index, and set that exact send's `I_DSTCHAN` to `2`. Enable the detector input using the maintained mapping when it fits or by resolving its live parameter name. Do not set threshold, ratio, attack, release, or other controls unless the user requested them.
]],
      validators = {
        bus_routing_requires_sends = true,
        region_requires_region_flag = true,
        sidechain_ducking_requires_send = true,
      },
    },
  },
}

function Code.model_guidance_profile(provider_id, model_id)
  local by_provider = Code.MODEL_GUIDANCE_BY_MODEL
    and Code.MODEL_GUIDANCE_BY_MODEL[tostring(provider_id or "")]
  if type(by_provider) ~= "table" then return nil end
  local behavior_id = PROVIDERS.model_behavior_id(provider_id, model_id)
  local exact = by_provider[behavior_id]
  local shared = by_provider["*"]
  if exact ~= nil and shared ~= nil then
    local shared_prompt = type(shared) == "table" and shared.prompt or shared
    local exact_prompt = type(exact) == "table" and exact.prompt or exact
    local merged_prompt = ""
    if type(shared_prompt) == "string" then
      merged_prompt = shared_prompt
    end
    if type(exact_prompt) == "string" then
      merged_prompt = merged_prompt ~= "" and (merged_prompt .. "\n" .. exact_prompt)
        or exact_prompt
    end
    local validators = {}
    if type(shared) == "table" and type(shared.validators) == "table" then
      for key, value in pairs(shared.validators) do validators[key] = value end
    end
    if type(exact) == "table" and type(exact.validators) == "table" then
      for key, value in pairs(exact.validators) do validators[key] = value end
    end
    return {
      key = tostring((type(shared) == "table" and shared.key) or "shared")
        .. "+"
        .. tostring((type(exact) == "table" and exact.key) or "exact"),
      prompt = merged_prompt,
      validators = validators,
    }
  end
  if exact ~= nil then return exact end
  return shared
end

function Code.model_guidance_text(provider_id, model_id)
  local profile = Code.model_guidance_profile(provider_id, model_id)
  local body = type(profile) == "table" and profile.prompt or profile
  if type(body) ~= "string" then return nil end
  body = body:match("^%s*(.-)%s*$") or ""
  if body == "" then return nil end
  return "MODEL-SPECIFIC GUIDANCE:\n"
    .. "- Do not mention this guidance.\n"
    .. body
end

function Code.model_validator_enabled(provider_id, model_id, validator_key)
  local profile = Code.model_guidance_profile(provider_id, model_id)
  if type(profile) ~= "table" then return false end
  local validators = profile.validators
  if type(validators) ~= "table" then return false end
  return validators[tostring(validator_key or "")] == true
end

function Code.validate_model_guidance_tables()
  local issues = {}
  local function add_issue(msg) issues[#issues + 1] = msg end

  if type(PROVIDERS) ~= "table" or type(UI) ~= "table" then
    return true, issues
  end

  local provider_seen = {}
  local model_seen = {}
  local thinking_seen = {}

  for _, provider in ipairs(PROVIDERS) do
    if type(provider) == "table" and provider.id then
      local provider_id = tostring(provider.id)
      provider_seen[provider_id] = true
      thinking_seen[provider_id] = {}

      local combo_provider = type(UI.COMBO_HINTS) == "table"
        and UI.COMBO_HINTS[provider_id] or nil
      for _, model in ipairs(provider.models or {}) do
        if type(model) == "table" and model.id then
          local model_id = tostring(model.id)
          model_seen[model_id] = provider_id
          thinking_seen[provider_id][model_id] = {}

          local behavior_id = PROVIDERS.model_behavior_id(provider_id, model_id)
          -- A model renamed on the wire keeps one behavior id, and the
          -- per-model copy and guidance tables may stay keyed by it. That key
          -- is live, not stale, so the stale loops below have to see it. The
          -- thinking table is shared by reference, so the levels recorded
          -- under the runtime id below count for the alias too.
          if behavior_id ~= "" and behavior_id ~= model_id then
            model_seen[behavior_id] = provider_id
            thinking_seen[provider_id][behavior_id] =
              thinking_seen[provider_id][model_id]
          end
          if type(UI.MODEL_TIPS) ~= "table"
             or type(UI.MODEL_TIPS[model_id] or UI.MODEL_TIPS[behavior_id])
               ~= "string"
             or (UI.MODEL_TIPS[model_id] or UI.MODEL_TIPS[behavior_id]) == "" then
            add_issue("MODEL_TIPS missing " .. provider_id .. "/" .. model_id)
          end

          local combo_model = type(combo_provider) == "table"
            and (combo_provider[model_id] or combo_provider[behavior_id]) or nil
          for level_idx, level in ipairs(provider.thinking_levels or {}) do
            local value = level and level.value
            if value and PROVIDERS.thinking_idx_allowed(
                provider, model, level_idx) then
              local value_s = tostring(value)
              thinking_seen[provider_id][model_id][value_s] = true
              if type(combo_model) ~= "table"
                 or type(combo_model[value_s]) ~= "string"
                 or combo_model[value_s] == "" then
                add_issue("COMBO_HINTS missing " .. provider_id .. "/"
                  .. model_id .. "/" .. value_s)
              end
            end
          end
        end
      end
    end
  end

  for model_id in pairs(UI.MODEL_TIPS or {}) do
    if not model_seen[tostring(model_id)] then
      add_issue("MODEL_TIPS stale " .. tostring(model_id))
    end
  end

  for provider_id, provider_tbl in pairs(UI.COMBO_HINTS or {}) do
    provider_id = tostring(provider_id)
    if not provider_seen[provider_id] then
      add_issue("COMBO_HINTS stale provider " .. provider_id)
    elseif type(provider_tbl) == "table" then
      for model_id, model_tbl in pairs(provider_tbl) do
        model_id = tostring(model_id)
        if model_seen[model_id] ~= provider_id then
          add_issue("COMBO_HINTS stale model " .. provider_id .. "/"
            .. model_id)
        elseif type(model_tbl) == "table" then
          for value in pairs(model_tbl) do
            value = tostring(value)
            if not (thinking_seen[provider_id]
                    and thinking_seen[provider_id][model_id]
                    and thinking_seen[provider_id][model_id][value]) then
              add_issue("COMBO_HINTS stale thinking " .. provider_id .. "/"
                .. model_id .. "/" .. value)
            end
          end
        end
      end
    end
  end

  for provider_id, provider_tbl in pairs(UI.COMBO_TONES or {}) do
    provider_id = tostring(provider_id)
    if not provider_seen[provider_id] then
      add_issue("COMBO_TONES stale provider " .. provider_id)
    elseif type(provider_tbl) == "table" then
      for model_id, tone_tbl in pairs(provider_tbl) do
        model_id = tostring(model_id)
        if model_seen[model_id] ~= provider_id then
          add_issue("COMBO_TONES stale model " .. provider_id .. "/"
            .. model_id)
        elseif type(tone_tbl) == "table" then
          for value in pairs(tone_tbl) do
            value = tostring(value)
            if not (UI.COMBO_HINTS
                    and UI.COMBO_HINTS[provider_id]
                    and UI.COMBO_HINTS[provider_id][model_id]
                    and UI.COMBO_HINTS[provider_id][model_id][value]) then
              add_issue("COMBO_TONES without COMBO_HINTS " .. provider_id
                .. "/" .. model_id .. "/" .. value)
            end
          end
        end
      end
    end
  end

  for provider_id, provider_tbl in pairs(Code.MODEL_GUIDANCE_BY_MODEL or {}) do
    provider_id = tostring(provider_id)
    if not provider_seen[provider_id] then
      add_issue("MODEL_GUIDANCE stale provider " .. provider_id)
    elseif type(provider_tbl) == "table" then
      for model_id in pairs(provider_tbl) do
        model_id = tostring(model_id)
        if model_id ~= "*" and model_seen[model_id] ~= provider_id then
          add_issue("MODEL_GUIDANCE stale model " .. provider_id .. "/"
            .. model_id)
        end
      end
    end
  end

  return #issues == 0, issues
end

function Code.compact_system_prompt_text()
  local version = (type(CFG) == "table" and CFG.VERSION) or ""
  local text = [[-- ReaAssist v]] .. version .. "\n" .. [[
You are a REAPER DAW assistant. This is the compact prompt: be practical, obey the context protocol exactly, and generate safe standalone REAPER Lua/JSFX.

CONTEXT PROTOCOL:
- Check the PINNED REFERENCES manifest before asking for context. If a key is listed, use the already-pinned data and do not request it again.
- When context is needed, the whole reply must be one tag only: <context_needed>bucket, bucket</context_needed>. No prose, no fence, no explanation.
- Required buckets: `docs` before any reaper.* code unless docs is pinned or the request is covered only by pinned `midi`; `session` for project state/track selection; `tracks` only when capped session rows omit needed tracks; `recent_reaper_changes` for current/latest REAPER behavior.
- Live ordinary-track FX names normally come from the session snapshot. Request `fx_chains` when the needed track was omitted by the snapshot cap or when the user asks about Monitor or monitoring FX. `fx_list:Name` searches the installed catalog for add-only unknown plugins; it is never a live track-chain read. Other plugin buckets: `resolve:Type` for generic FX types; `plugin_ref:Name` for curated plugins; `fx_inspect:Name` for add+configure unknown plugins; `fx_params:Name@TrackIndex` for current values on loaded plugins. Use full prefixes for multiple tokens.
- Prompt bundles provide focused guidance. Ordinary TrackFX and TakeFX Lua does not require a bundle as an authorization step. Request `plugin_helpers` only for a difficult display-value conversion that truly needs those templates. Drum edits, JSFX authoring, and theme changes still use their focused bundles.

OUTPUT CONTRACT:
- For action requests, prefer one complete runnable ```lua block after required context is pinned. For JSFX requests, output one ```jsfx block with `desc:` first.
- Do not claim code ran unless runtime output says so. Keep visible prose short and user-facing; never expose param indices, normalized values, helper internals, or cache annotations.
- Ask one concise question only for genuine ambiguity that context cannot resolve. Negative constraints such as no FX, no sends, no new tracks, or no delete are hard requirements.

SANDBOX / SAFETY:
- FORBIDDEN in code: os, io, ffi, debug, coroutine, package, require, dofile, loadfile, loadstring, load, _G, getfenv, setfenv, rawget, rawset.
- Use only reaper.*, gfx.* when a persistent UI is explicitly requested, and safe Lua builtins (math, string, table, pairs, ipairs, tonumber, tostring, type, pcall, xpcall, select, error, assert, next, unpack).
- Do not use SWS/js_ReaScriptAPI/extension APIs unless requested or docs says they exist and the script checks availability with a clear user error.

REAPER LUA PITFALLS:
- Void APIs return nil: InsertTrackAtIndex, SetEditCurPos, Main_OnCommand, Undo_BeginBlock, Undo_EndBlock, PreventUIRefresh, UpdateArrange, ThemeLayout_RefreshAll. Call them separately, then fetch handles.
- Track indices shown to users are 1-based; API indices are 0-based. Never invent track indices. Nil-check tracks/items/takes before use.
- Create tracks with InsertTrackAtIndex(index, true), then GetTrack(0, index), then name with GetSetMediaTrackInfo_String(track, "P_NAME", name, true).
- If the user asks for a created track to be selected, explicitly select it after creation with SetOnlyTrackSelected(track) or SetTrackSelected(track, true), as appropriate.
- Wrap project changes in one Undo_BeginBlock/Undo_EndBlock. Balance PreventUIRefresh on every normal exit and always call UpdateArrange after changes. Do not use pcall or xpcall to suppress errors; a failed protected call makes the run fail.
- D_VOL is linear amplitude. Do not use DB2SLIDER/SLIDER2DB for track/item/take/send volume.
- CreateTrackSend returns one integer send index; 0 is valid and -1 is failure. Master send is B_MAINSEND, not RemoveTrackSend category 1.
- For folders, parent track gets I_FOLDERDEPTH=1 and the final child closes with a negative depth. Do not create a fake "(folder end)" track.
- For MIDI notes, use MIDI PPQ positions, CreateNewMIDIItemInProj(track,...), GM drums kick 36/snare 38/closed hat 42, and REAPER note numbering C4=60.
- For exact seconds, use exact seconds. For bars/beats/tempo math, request docs:tempo; for MIDI note work, request midi.
- Use Main_OnCommand only for verified action IDs from provided docs/context or when the user explicitly names a known action. Never write a numeric action ID that is not in the provided reference; if the one you want is not there, use the direct reaper.* API instead or request the docs bucket that documents it.
- Never Save the project, start Record, Undo, or Redo unless the current user request explicitly asks for that exact action. Creating or arming a record-ready track is not permission to start recording.

PLUGIN RULES:
- Begin Undo before the first project mutation, including track creation and TrackFX_AddByName. Check every AddByName result immediately. If one fails, close the Undo block before showing a clear message and returning. Every exit path after Undo_BeginBlock must reach Undo_EndBlock.
- Add-only FX means leave defaults; no param writes unless the user requests settings, a preset/recipe, or a tonal setup.
- For generic FX type requests, use an already-supplied preference or request resolve:Type once. For exact product names, use that exact plug-in.
- Maintained profiles, cached parameters, and live values are helpful generation references. They never authorize execution, and a version or fingerprint difference does not by itself block ordinary Lua.
- Direct TrackFX_SetParam, TrackFX_SetParamNormalized, TakeFX_SetParam, and TakeFX_SetParamNormalized calls are allowed. Resolve and bounds-check the intended control with live parameter names when an exact mapping is unavailable.
- Direct TrackFX_SetParam* and TakeFX_SetParam* writes normally run synchronously inside the same Undo block as the rest of the action. Never mutate the project or add FX, then defer only the parameter writes. If a plug-in truly requires a host cycle, defer the entire action so the callback begins Undo, performs every mutation, and ends Undo.
- Check every required AddByName or GetByName result. On failure, say what did not complete and tell the user they can ask ReaAssist to fix and retry.

JSFX RULES:
- JSFX is opt-in only. EEL2 has no `reaper`, no Lua syntax, no `if/end`, and no `math.` prefix. Use sections such as @init, @slider, @sample.
- Do not declare or touch gmem; ReaAssist injects its own safety layer. Initialize every memory base before using `name[index]`, and keep feedback clamped/DC-blocked.

STYLE:
- One logical user action per answer, concise summary, then code. No repeated caveats. If a TrackFX_SetParam* write is used, include only the standard UI-verification tip after the code.
]]
  if REQUIRE_SWS_EXTENSION
     and (not SupportExtFlag or not SupportExtFlag("optoutsws")) then
    text = text .. [[

SWS DOCS ROUTING:
- SWS is available in this build. Before SWS-only calls or SWS actions, request <context_needed>docs:sws</context_needed> unless already pinned.
]]
  end
  return text
end

function Code.model_id_looks_local(model_id)
  local mid = tostring(model_id or ""):lower()
  return mid:find("local", 1, true) ~= nil
    or mid:find("ollama", 1, true) ~= nil
    or mid:find("llama", 1, true) ~= nil
    or mid:find("qwen", 1, true) ~= nil
    or mid:find("mistral", 1, true) ~= nil
    or mid:find("mixtral", 1, true) ~= nil
    or mid:find("codestral", 1, true) ~= nil
    or mid:find("gemma", 1, true) ~= nil
    or mid:find("phi", 1, true) ~= nil
    or mid:find("gguf", 1, true) ~= nil
end

function Code.custom_endpoint_looks_hosted(endpoint)
  local ep = tostring(endpoint or ""):lower()
  return ep:find("openrouter%.ai") ~= nil
    or ep:find("api%.openai%.com") ~= nil
    or ep:find("anthropic%.com") ~= nil
    or ep:find("generativelanguage%.googleapis%.com") ~= nil
    or ep:find("api%.together%.xyz") ~= nil
    or ep:find("api%.fireworks%.ai") ~= nil
    or ep:find("api%.groq%.com") ~= nil
    or ep:find("api%.deepseek%.com") ~= nil
    or ep:find("openai%.azure%.com") ~= nil
end

function Code.custom_endpoint_looks_local(endpoint)
  local ep = tostring(endpoint or ""):lower()
  if ep:find("localhost", 1, true)
     or ep:find("127.", 1, true)
     or ep:find("0.0.0.0", 1, true)
     or ep:find("[::1]", 1, true) then
    return true
  end
  if ep:find("://10%.") then return true end
  if ep:find("://192%.168%.") then return true end
  if ep:find("://172%.1[6-9]%.")
     or ep:find("://172%.2%d%.")
     or ep:find("://172%.3[01]%.") then
    return true
  end
  return false
end

function Code.use_compact_system_prompt(provider, model_id)
  if SYSTEM_PROMPT_IS_CUSTOM then return false end
  if type(provider) == "table" and provider.id == "deepseek"
      and PROVIDERS.model_behavior_id(provider.id, model_id)
        == "deepseek-v4-flash" then
    return true
  end
  if type(provider) == "table" and provider.is_custom then
    if Code.custom_endpoint_looks_hosted(provider.endpoint) then
      return false
    end
    return Code.custom_endpoint_looks_local(provider.endpoint)
      or Code.model_id_looks_local(model_id)
  end
  return Code.model_id_looks_local(model_id)
end

-- Return the SYSTEM_PROMPT string plus request-stable system-level additions,
-- optionally with a per-TEST-SESSION stamp appended as a hidden comment when
-- prefs.test_force_cold_cache is on.
--
-- The stamp is minted ONCE when the toggle transitions off -> on (held in
-- S.cold_cache_stamp) and reused on every subsequent send until the toggle
-- flips off or is re-minted. That way the FIRST send after toggling on
-- misses cache across all three providers (fresh prefix the server has
-- never seen), but subsequent sends within the same test run hit cache
-- normally -- so you can still observe caching behavior turn-over-turn
-- while starting from a guaranteed cold state.
--
-- Starting a fresh cold test: toggle off, then toggle on again -- that
-- mints a new stamp.
do
  local ok, issues = Code.validate_model_guidance_tables()
  if not ok and Log and Log.line then
    Log.line("MODEL-GUIDANCE", table.concat(issues, "; "))
  end
end

function Net.informational_starter_key(user_text, attachments)
  if type(attachments) == "table" and #attachments > 0 then return nil end
  if type(user_text) ~= "string" or user_text == "" then return nil end
  for _, key in ipairs({
      "editing",
      "track_project",
      "mixing_effects",
      "lua_scripting",
      "jsfx",
      "qa",
      "no_audio",
    }) do
    local prompt = RA and RA.t
      and RA.t("home.card." .. key .. ".prompt", nil, "") or ""
    if prompt ~= "" and user_text == prompt then return key end
  end
  return nil
end

function Net.system_prompt_text()
  local active_provider = PROVIDERS and PROVIDERS.active and PROVIDERS.active()
    or nil
  local active_model_id = MODELS and MODELS.active_id
    and MODELS.active_id() or nil
  local text = Code.use_compact_system_prompt(active_provider, active_model_id)
    and Code.compact_system_prompt_text()
    or SYSTEM_PROMPT
  local custom_blob = Net.custom_instructions_prompt_block_for_request()
  if custom_blob then
    text = text .. "\n\n" .. custom_blob
  end
  if S.pending_starter_card_key then
    text = text .. "\n\nSTARTER CARD PRESENTATION:\n"
      .. "- This exact built-in starter asks only for a brief capability "
      .. "overview. Answer with concise prose or short bullets.\n"
      .. "- Do not generate code, code fences, structured-edit JSON, "
      .. "action plans, or runnable instructions.\n"
      .. "- Do not emit or request `<context_needed>`. Do not claim to know "
      .. "the current project, tracks, items, markers, effects, settings, "
      .. "selection, or transport state.\n"
      .. "- Describe stable ReaAssist capabilities only. Follow the "
      .. "configured visible reply language."
  end
  local lang = (I18N and I18N.prompt_language_name and I18N.prompt_language_name())
    or (CFG.prompt_language_name_for_idx
      and CFG.prompt_language_name_for_idx(prefs.reply_language_idx or 1))
    or (CFG.REPLY_LANGUAGE_CODES and CFG.REPLY_LANGUAGE_CODES[prefs.reply_language_idx or 1])
  if lang and lang ~= "English" then
    text = text .. "\n\nVISIBLE REPLY LANGUAGE:\n"
      .. "- When visible natural-language prose is allowed, write it in "
      .. lang .. ".\n"
      .. "- Generated script comments, script title comments, "
      .. "Undo_EndBlock labels, ShowMessageBox text, console/debug text, "
      .. "and other user-visible string literals are visible prose: write "
      .. "those in " .. lang .. " too. Keep the `ReaAssist:` prefix in "
      .. "undo labels unchanged, but localize the action description after "
      .. "the prefix.\n"
      .. "- Structured-edit JSON is not Lua code. Keep JSON syntax, schema "
      .. "keys, op names, REAPER API identifiers, FX/plugin names, and "
      .. "existing user/project names unchanged, but write generated "
      .. "user-visible string values such as track.create.name, "
      .. "track.ensure.name, track.set.name, and generic object labels in "
      .. lang .. ".\n"
      .. "- Do not translate code syntax, code fence labels, REAPER API "
      .. "names, variable/function identifiers, plugin names/identifiers, "
      .. "JSON schema/syntax, XML-like tags such as <context_needed>, paths, filenames "
      .. "supplied by the user, model/provider names, "
      .. "diagnostic labels, or quoted project/user text. For generated "
      .. "script title comments and generated undo descriptions, use "
      .. lang .. " so ReaAssist can derive a localized suggested filename.\n"
      .. "- If a contract requires raw code, JSON, or a bare "
      .. "<context_needed> tag only, obey that contract exactly."
  end
  local model_guidance = Code.model_guidance_text(
    active_provider and active_provider.id or nil,
    active_model_id)
  if model_guidance then
    text = text .. "\n\n" .. model_guidance
  end
  if prefs.test_force_cold_cache and S.cold_cache_stamp then
    return text
      .. "\n\n<!-- test_force_cold_cache: "
      .. S.cold_cache_stamp
      .. " -->"
  end
  return text
end

-- =============================================================================
-- Net.bundled_static_refs
-- =============================================================================
-- Concatenates the long-lived static references (api_ref, midi_ref, theme_ref)
-- into one blob so each provider can emit them as ONE pinned exchange instead
-- of three. Saves the per-ref "Understood." ack overhead and reduces the
-- number of message turns the providers' caches have to align on (matters
-- most for Gemini's cachedContents structure). Returns nil when no refs
-- are present. Order is stable: api_ref first (largest, most stable), then
-- midi_ref, then theme_ref, then a small manifest line so static-only turns
-- do not need a separate manifest-only sticky message.
function Net.bundled_static_refs()
  local parts = {}
  local keys = {}
  if S.api_ref_message   then parts[#parts+1] = S.api_ref_message;   keys[#keys+1] = "docs"  end
  if S.midi_ref_message  then parts[#parts+1] = S.midi_ref_message;  keys[#keys+1] = "midi"  end
  if S.theme_ref_message then parts[#parts+1] = S.theme_ref_message; keys[#keys+1] = "theme" end
  if #parts == 0 then return nil end
  parts[#parts+1] =
    "PINNED REFERENCES (already provided above; do NOT re-request via "
    .. "<context_needed>): " .. tbl_concat(keys, ", ")
  return tbl_concat(parts, "\n\n")
end

function Net.answer_only_context_enabled()
  -- Intentional cache trade-off: answer-only follow-ups drop static refs,
  -- sticky context, and snapshot for one turn. Alternating answer-only and
  -- code-generation phrasing can rebuild a cache rung, but the answer-only
  -- request becomes much smaller and avoids carrying code/plugin context into
  -- pure "why did you choose that?" follow-ups.
  return S.pending_answer_only_followup == true
end

function Net.request_context_suppressed()
  if Net.answer_only_context_enabled() then return true end
  return S.pending_answer_only_followup == "attachment_review"
    and S.request_context_recovered ~= true
end

function Net.fx_sticky_suppressed_for_request()
  return type(Code) == "table"
    and type(Code.prompt_forbids_fx_addition) == "function"
    and Code.prompt_forbids_fx_addition(S.pending_orig_prompt or "")
end

function Net.bundled_static_refs_for_request()
  if Net.request_context_suppressed() then return nil end
  return Net.bundled_static_refs()
end

-- =============================================================================
-- Net.sticky_text
-- =============================================================================
-- Net.sticky_set / Net.sticky_unset: wrappers that maintain both
-- S.sticky_context (the key -> content map) AND S.sticky_context_order (the
-- insertion-order key list). Use these instead of assigning to
-- S.sticky_context[k] directly -- the order list drives sticky_parts() emit
-- order, which is critical for prefix-cache stability.
--
-- Why insertion order matters: providers (Anthropic, OpenAI, Gemini) cache on
-- exact byte-prefix match. The earlier alphabetical sort shuffled new refs
-- into the middle of the sticky blob (e.g. adding Pro-C 3 pushed it before
-- Pro-Q 4), invalidating the entire cached prefix on every plugin addition.
-- Observed cost: ~15-20K tokens of cache_write on every ref-addition turn,
-- ~50% of total chat cost in a plugin-heavy session. Insertion order keeps
-- appends truly appended -- the prefix through existing refs stays
-- byte-identical and remains cached. See Net.sticky_parts() for the
-- two-block split that also preserves Anthropic block-level caching.
-- Dedup helper: for a fresh plugin_ref:/pref: write, check whether an
-- existing bundled key (same prefix, slash-joined names) already covers
-- this name. If yes, the standalone write is redundant -- skip it and let
-- the caller's "injected" log entry still fire at the bucket-dispatch site.
-- Returns true when the write should be skipped.
local function _sticky_would_duplicate(key)
  local prefix, name = key:match("^([%a_]+:)(.+)$")
  if not prefix or not name then return false end
  if prefix ~= "plugin_ref:" and prefix ~= "pref:" then return false end
  if name:find("/", 1, true) then return false end  -- the new key IS a bundle
  for existing_key in pairs(S.sticky_context or {}) do
    if existing_key ~= key then
      local ex_prefix, ex_names = existing_key:match("^([%a_]+:)(.+)$")
      if ex_prefix == prefix and ex_names and ex_names:find("/", 1, true) then
        for chunk in ex_names:gmatch("[^/]+") do
          if chunk == name then return true end
        end
      end
    end
  end
  return false
end

-- Symmetrical dedup: when a FRESH bundle is added, any standalone entries
-- with the same prefix that name a member of the bundle are now redundant
-- and should be removed. Returns the list of keys that were cleared (caller
-- uses this for logging if it cares).
local function _sticky_evict_standalones_for_bundle(bundle_key)
  local prefix, names = bundle_key:match("^([%a_]+:)(.+)$")
  if not prefix or not names then return {} end
  if prefix ~= "plugin_ref:" and prefix ~= "pref:" then return {} end
  if not names:find("/", 1, true) then return {} end
  local covered = {}
  for chunk in names:gmatch("[^/]+") do covered[chunk] = true end
  local to_evict = {}
  for existing_key in pairs(S.sticky_context or {}) do
    if existing_key ~= bundle_key then
      local ex_prefix, ex_name = existing_key:match("^([%a_]+:)(.+)$")
      if ex_prefix == prefix and ex_name
         and not ex_name:find("/", 1, true)
         and covered[ex_name] then
        to_evict[#to_evict+1] = existing_key
      end
    end
  end
  for _, k in ipairs(to_evict) do Net.sticky_unset(k) end
  return to_evict
end

function Net.sticky_set(key, content, source)
  if not S.sticky_context_order then S.sticky_context_order = {} end
  local is_fresh = S.sticky_context[key] == nil
  -- First-time add of a singleton that's already covered by an existing
  -- bundle: skip. Every turn before this was paying to send the same
  -- plugin_ref/pref content twice (once inside the bundle, once standalone),
  -- which bloated the sticky blob and invalidated prefix caching further
  -- downstream every time a new standalone landed.
  if is_fresh and _sticky_would_duplicate(key) then
    Log.line("STICKY", "skip redundant " .. key
      .. " (already covered by existing bundle)")
    return
  end
  if is_fresh then
    S.sticky_context_order[#S.sticky_context_order+1] = key
    -- First-time add of a bundle: evict any singletons it now subsumes.
    -- One-time cache-miss cost on the immediate next turn (the blob's
    -- suffix bytes shift), then permanent savings from not resending the
    -- singleton content on every subsequent turn.
    local evicted = _sticky_evict_standalones_for_bundle(key)
    if #evicted > 0 then
      Log.line("STICKY", "evicted " .. tbl_concat(evicted, ", ")
        .. " (subsumed by new bundle " .. key .. ")")
    end
    -- Record the source on first add only. Later same-key calls (idempotent
    -- re-pins) keep the original source -- a "copin" mid-session call
    -- shouldn't downgrade an already-"preempt" entry.
    S.sticky_pin_source = S.sticky_pin_source or {}
    S.sticky_pin_source[key] = source or "copin"
  end
  S.sticky_context[key] = content
end

function Net.sticky_unset(key)
  S.sticky_context[key] = nil
  if S.sticky_pin_source then S.sticky_pin_source[key] = nil end
  if not S.sticky_context_order then return end
  for i, k in ipairs(S.sticky_context_order) do
    if k == key then
      table.remove(S.sticky_context_order, i)
      return
    end
  end
end

-- Remove the complete pref: family containing one type. A preferred bucket can
-- bundle several slash-separated types, so removing only pref:<type> leaves a
-- stale compound pin behind. Return the family in its original stable order so
-- popup resume can refill valid siblings without changing cache ordering.
function Net.preferred_plugin_type_key(type_key)
  if CTX and type(CTX.preferred_plugin_type_key) == "function" then
    return CTX.preferred_plugin_type_key(type_key)
  end
  return tostring(type_key or ""):lower():match("^%s*(.-)%s*$") or ""
end

function Net._reset_preferred_turn_state()
  for _, key in ipairs(S.turn_only_stock_sticky_keys or {}) do
    Net.sticky_unset(key)
  end
  S.turn_only_stock_sticky_keys = {}
  S.turn_only_stock_approved_refs = nil
  S.pref_plugins_sent = {}
  S.pref_plugins_unresolved = {}
  S.resolve_resume_guard_type = nil
  S.approved_stock_fallback_refs = nil
end

function Net.sticky_pref_family_invalidate(type_key)
  local wanted = Net.preferred_plugin_type_key(type_key)
  if wanted == "" then return {} end
  -- pref_map lists every saved role in one entry, so any preference change
  -- invalidates the whole map. The next chain prompt rebuilds it from the
  -- current preferred_types.
  if S.sticky_context and S.sticky_context["pref_map"] then
    Net.sticky_unset("pref_map")
    if S.sticky_context_age then S.sticky_context_age["pref_map"] = nil end
  end
  local keys, family, family_seen, key_seen = {}, {}, {}, {}
  local function capture(key)
    if key_seen[key] then return end
    local names = tostring(key or ""):match("^pref:(.+)$")
    if not names then return end
    local members, contains = {}, false
    for name in names:gmatch("[^/]+") do
      name = Net.preferred_plugin_type_key(name)
      if name ~= "" then
        members[#members+1] = name
        if name == wanted then contains = true end
      end
    end
    if not contains then return end
    key_seen[key] = true
    keys[#keys+1] = key
    for _, name in ipairs(members) do
      if not family_seen[name] then
        family_seen[name] = true
        family[#family+1] = name
      end
    end
  end
  for _, key in ipairs(S.sticky_context_order or {}) do capture(key) end
  local remaining = {}
  for key in pairs(S.sticky_context or {}) do
    if not key_seen[key] then remaining[#remaining+1] = key end
  end
  table.sort(remaining)
  for _, key in ipairs(remaining) do capture(key) end
  for _, key in ipairs(keys) do
    Net.sticky_unset(key)
    if S.sticky_context_age then S.sticky_context_age[key] = nil end
  end
  S.pref_plugins_sent = S.pref_plugins_sent or {}
  S.pref_plugins_unresolved = S.pref_plugins_unresolved or {}
  for _, name in ipairs(family) do
    S.pref_plugins_sent[name] = nil
    S.pref_plugins_unresolved[name] = nil
  end
  return family
end

function Net.sticky_key_mentioned_in_prompt(key, lower_prompt)
  local ident = key and key:match("^[^:]+:(.+)$")
  if not ident or lower_prompt == "" then return false end
  local ident_lower = ident:lower()
  if lower_prompt:find(ident_lower, 1, true) then return true end
  for part in ident:gmatch("[^/]+") do
    part = part:match("^%s*(.-)%s*$")
    if part ~= "" and lower_prompt:find(part:lower(), 1, true) then
      return true
    end
  end
  return false
end

-- Pin prompt_bundle:plugin into sticky if it's not already there. Called from
-- every site that pins a plugin_ref / pref_plugin / preferred_plugins entry,
-- so that any plugin ADD/CONFIGURE task arrives at the model already holding
-- the plugin workflow rules (find_param / set_param_display etc) -- saves
-- the first-plugin-turn round-trip where the model would otherwise emit
-- <context_needed>prompt_bundle:plugin</context_needed> and wait a full
-- turn before writing the script. variant is internal (add_only or full) and
-- upgrades the same sticky key in place; it never downgrades full to compact.
-- The optional out_list gets pb_key only when the payload was added/replaced,
-- so the caller can surface the actual change in context logs.
function Net.plugin_bundle_variant_for_prompt(text)
  if type(Code) == "table"
     and type(Code.prompt_can_use_plugin_add_only_bundle) == "function" then
    local ok, can_compact = pcall(Code.prompt_can_use_plugin_add_only_bundle,
      text or "")
    if ok and can_compact == true then return "add_only" end
  end
  return "full"
end

-- A compact plugin pin satisfies an add-only preempt, but it must not satisfy
-- an explicit model request for prompt_bundle:plugin. Keep this decision in one
-- place so the pre-dedup pass, explicit-token parser, and continuation-token
-- parser cannot disagree about whether the same public key still needs full.
function Net.prompt_bundle_needs_full_upgrade(name)
  return tostring(name or ""):lower() == "plugin"
    and S.plugin_bundle_variant == "add_only"
end

function Net.copin_plugin_bundle(out_list, variant, source)
  local pb_key = "prompt_bundle:plugin"
  variant = variant == "add_only" and "add_only" or "full"
  local existing = S.sticky_context[pb_key]
  local current = S.plugin_bundle_variant
  if existing and current ~= "add_only" and current ~= "full" then
    -- A same-key pin created by older or untracked code must be treated as
    -- full. Never infer that it is safe to preserve a compact payload.
    current = "full"
    S.plugin_bundle_variant = current
  end
  if existing and (current == "full" or current == variant) then
    if S.prompt_bundle_sent then S.prompt_bundle_sent["plugin"] = true end
    return true
  end
  local pb_content, pb_err = CTX.prompt_bundle("plugin", variant)
  if not pb_content and variant == "add_only" then
    variant = "full"
    pb_content, pb_err = CTX.prompt_bundle("plugin", "full")
  end
  if not pb_content then return false, pb_err end
  Net.sticky_set(pb_key, pb_content, source)
  S.plugin_bundle_variant = variant
  if S.prompt_bundle_sent then S.prompt_bundle_sent["plugin"] = true end
  if out_list and existing ~= pb_content then out_list[#out_list+1] = pb_key end
  return true
end

-- A compact plugin bundle can persist across turns under the same sticky key.
-- Upgrade it before a later parameter-writing follow-up is assembled; waiting
-- for the model to request prompt_bundle:plugin costs an avoidable round-trip.
function Net.maybe_upgrade_plugin_bundle_for_prompt(text)
  local bare_plugin_followup =
    type(Code.prompt_has_plugin_param_bare_integer_intent) == "function"
      and Code.prompt_has_plugin_param_bare_integer_intent(text or "")
  local has_plugin_bundle =
    S.plugin_bundle_variant == "add_only"
      or S.plugin_bundle_variant == "full"
  -- A musical-configuration first turn now pins the full plugin bundle.
  -- Bare-integer follow-ups still need helpers/docs even though there is no
  -- compact bundle left to upgrade. Keep that co-pin independent from the
  -- variant transition so the two signals work in one conversation.
  if bare_plugin_followup and has_plugin_bundle then
    Net.copin_docs_core(nil)
    Net.copin_plugin_helpers(nil, "intent_upgrade")
  end
  if S.plugin_bundle_variant ~= "add_only" then
    if bare_plugin_followup == true and has_plugin_bundle then
      return true, nil, "context_pinned"
    end
    return false
  end
  local write_intent =
    type(Code.prompt_has_param_write_intent) == "function"
      and Code.prompt_has_param_write_intent(text or "")
  local needs_full = write_intent
    or type(Code.prompt_requests_named_param_value) == "function"
      and Code.prompt_requests_named_param_value(text or "")
    or bare_plugin_followup
  if not needs_full then return false end
  local ok, err = Net.copin_plugin_bundle(nil, "full", "intent_upgrade")
  if not ok then return false, err end
  if write_intent and not bare_plugin_followup then
    Net.copin_docs_core(nil)
    Net.copin_plugin_helpers(nil, "intent_upgrade")
  end
  return true, nil, "upgraded"
end

-- Pin prompt_bundle:theme next to the theme color reference. The theme bucket
-- lists the color keys; this bundle carries the backup/restore safety rule
-- required before any SetThemeColor code.
function Net.copin_theme_bundle(out_list)
  local pb_key = "prompt_bundle:theme"
  if S.sticky_context[pb_key] then
    if S.prompt_bundle_sent then S.prompt_bundle_sent["theme"] = true end
    return
  end
  local pb_content, _ = CTX.prompt_bundle("theme")
  if not pb_content then return end
  Net.sticky_set(pb_key, pb_content)
  if S.prompt_bundle_sent then S.prompt_bundle_sent["theme"] = true end
  if out_list then out_list[#out_list+1] = pb_key end
end

-- Helper templates remain available when a Model explicitly asks for them,
-- but ordinary plug-in work no longer pre-pins a large mandatory helper body.
function Net.copin_plugin_helpers()
  return false
end

-- Recovery retries must never claim the canonical helper reference is pinned
-- unless the request renderer will actually include it. Keep this check
-- shared by both helper validators so loader failure and intentional sticky
-- suppression both produce truthful, self-contained guidance.
function Net.ensure_plugin_helpers_for_retry()
  local ph_key = "prompt_bundle:plugin_helpers"
  if Net.request_context_suppressed()
     or Net.fx_sticky_suppressed_for_request() then
    return false
  end
  if not S.sticky_context[ph_key] then
    Net.copin_plugin_helpers(nil)
  end
  return type(S.sticky_context[ph_key]) == "string"
    and S.sticky_context[ph_key] ~= ""
end

function Net.plugin_helpers_retry_guidance(integrity_retry)
  if Net.ensure_plugin_helpers_for_retry() then
    if integrity_retry then
      return "Helper guidance is pinned above. Replace each affected call "
        .. "with direct REAPER API calls, or write a complete safe local "
        .. "definition before main(). Do not claim a canonical body exists. "
    end
    return "Helper guidance is pinned above. For find_param/"
      .. "set_param_display/set_param_enum/set_param_enum_paced, use direct "
      .. "REAPER API calls or write a complete safe local definition before "
      .. "its first call. "
  end
  if integrity_retry then
    return "The canonical helper reference is not available in this "
      .. "retry. Do not claim that it is available. Remove the affected "
      .. "helper and use direct safe REAPER API calls, or write a complete "
      .. "safe local definition before main(). "
  end
  return "The canonical plugin-helper reference is not available in this "
    .. "retry. Do not claim that it is available. For find_param/"
    .. "set_param_display/set_param_enum/set_param_enum_paced, remove the "
    .. "call and use direct safe REAPER API calls, or write a complete safe "
    .. "local definition before its first call. "
end

-- Pre-pin an on-demand prompt bundle into sticky_context. Called from the
-- preempt path when the user prompt matches a narrow bundle-specific intent
-- (JSFX pitch recipes, drum-edit workflow rules, etc.).
-- No-op when the bundle is already pinned this session, when the bundle
-- file is missing, or when the bundle name isn't registered in
-- PROMPT_BUNDLE_NAMES.
function Net.copin_jsfx_family(family, out_list)
  if not family or family == "" then return end
  local pb_key = "prompt_bundle:" .. family
  if S.sticky_context[pb_key] then
    if S.prompt_bundle_sent then S.prompt_bundle_sent[family] = true end
    return
  end
  local pb_content, _ = CTX.prompt_bundle(family)
  if not pb_content then return end
  Net.sticky_set(pb_key, pb_content)
  if S.prompt_bundle_sent then S.prompt_bundle_sent[family] = true end
  if out_list then out_list[#out_list+1] = pb_key end
end

-- Pre-pin docs (core API ref) into S.api_ref_message. Called alongside
-- copin_plugin_bundle from every preempt / resolve site that signals plugin
-- work. Without this, the chain-phrase / resolve preempts pre-pin a rich
-- plugin context (plugin_ref + pref + bundle) but NO docs -- the model then
-- bypasses the API-REF-REQUIREMENT rule, writes reaper.* code anyway, and
-- the docs-gate inside Net.try_finish_curl silently force-fetches +
-- retries. Net: 2 round-trips instead of 1, +30K cache_write on the retry,
-- and the user-visible cost/time display only shows the FIRST request,
-- understating the true cost. Co-pinning docs alongside the plugin context
-- adds ~5K cache_write on the first turn but eliminates the retry's ~30K
-- and the wasted assistant turn. Net: smaller AND faster on every plugin
-- session that goes through preempt / resolve.
--
-- No-ops when:
--   - api_ref_message is already set (user has "Always include API ref" on,
--     or docs was force-fetched / requested earlier this session)
--   - docs file fails to load (logged via CTX.docs error path; docs-gate
--     still acts as the safety net on response)
--
-- Sets S.docs_already_sent so a same-turn <context_needed>docs</context_needed>
-- (e.g. from a model that's belt-and-suspenders) hits the dispatcher's
-- dedup branch instead of re-fetching. Also sets S.docs_fetched_session
-- so the docs-gate sees docs as available and doesn't trigger.
function Net.copin_docs_core(out_list)
  if S.api_ref_message then return end
  local content, _err = CTX.docs()
  if not content then return end
  S.api_ref_message      = content
  S.docs_already_sent    = true
  S.docs_fetched_session = true
  if out_list then out_list[#out_list+1] = "docs" end
end

-- Returns two text blobs, stable + growing, emitted in sticky_context_order.
--   stable : prompt_bundle:* payloads and request-scoped Custom Instructions.
--            These effectively never change once pinned during a request.
--            Placed in a dedicated Anthropic cache block so this rung stays
--            hot across ref-addition turns.
--   growing: everything else (plugin_ref, pref, preferred_plugins,
--            fx_params, fx_inspect, docs_extended). Grows as new plugins
--            are referenced; its cache rung invalidates when a new ref is
--            appended, but that only costs the new ref's tokens -- the
--            stable rung stays cached. A leading manifest line lists ALL
--            pinned keys (stable + growing) so weak models can string-scan
--            before emitting a redundant <context_needed>.
--
-- Both may be nil when their respective bucket set is empty. When only one
-- side has content, the other returns nil. sticky_text() concatenates both
-- for providers without multi-breakpoint caching.
function Net.public_context_key(key)
  key = tostring(key or "")
  local fx_payload = key:match("^fx:(.+)$")
  if fx_payload then return "fx_params:" .. fx_payload end
  return key
end

function Net.sticky_parts()
  -- Static refs (docs / midi / theme) live in their own message slots, not in
  -- S.sticky_context, but they're equally "pinned above" from the model's POV.
  -- Include them in the manifest so the model's quick-scan sees them and
  -- doesn't emit a redundant <context_needed>docs</context_needed> (observed
  -- failure mode on weaker models).
  local static_keys = {}
  if S.api_ref_message   then static_keys[#static_keys+1] = "docs"  end
  if S.midi_ref_message  then static_keys[#static_keys+1] = "midi"  end
  if S.theme_ref_message then static_keys[#static_keys+1] = "theme" end
  local suppress_fx_sticky = Net.fx_sticky_suppressed_for_request()
  local function skip_sticky_key(k)
    -- Intentional cache trade-off: prompts that explicitly forbid adding FX
    -- drop plugin/Fx sticky refs for this one turn. That can invalidate a
    -- mid-prefix cache rung when the user alternates FX/no-FX wording, but
    -- the suppressed turn is much smaller and the prior 5-minute rungs
    -- usually survive for the next normal turn. Keep this local to the
    -- skip predicate; do not "fix" it by always retaining plugin context.
    if not suppress_fx_sticky then return false end
    return k == "prompt_bundle:plugin"
      or k == "prompt_bundle:plugin_helpers"
      or k:find("^plugin_ref:") ~= nil
      or k:find("^pref:") ~= nil
      or k == "pref_map"
      or k:find("^preferred_plugins:") ~= nil
      or k:find("^fx:") ~= nil
      or k == "fx_list"
      or k:find("^fx_list:") ~= nil
      or k:find("^fx_inspect:") ~= nil
      or k == "fx_chains"
  end

  local stable_keys, growing_keys = {}, {}
  if S.sticky_context_order then
    for _, k in ipairs(S.sticky_context_order) do
      if S.sticky_context[k] and not skip_sticky_key(k) then
        -- Most prompt_bundle:* entries are stable (pinned once at the start
        -- of a plugin/jsfx/theme task and don't change). prompt_bundle:
        -- plugin_helpers is the exception: it can be pinned via three
        -- different paths and only one of them is safe to route to stable:
        --
        --   "preempt"        -- co-pinned in CTX.preempt_buckets_for_prompt
        --                       alongside prompt_bundle:plugin. The stable
        --                       rung is already being initialized this turn,
        --                       so adding helpers to it costs no extra
        --                       cache miss. Route to STABLE.
        --   "copin"          -- co-pinned mid-flow by a dispatcher write-
        --                       intent path (fx_params / fx_inspect /
        --                       preferred_plugins) or the helper-validator
        --                       retry. The stable rung was cached on an
        --                       earlier turn; adding helpers there would
        --                       invalidate it on a turn we didn't plan to.
        --                       Route to GROWING.
        --   "context_needed" -- pulled in response to a model
        --                       <context_needed>prompt_bundle:plugin_helpers
        --                       tag. Same reasoning as "copin". Route to
        --                       GROWING.
        --
        -- Default to "copin" (growing) for any helpers entry without a
        -- recorded source -- the safe choice that matches pre-source-tag
        -- behavior. Other prompt_bundle:* keys always go to stable; those
        -- bundles are session-defining and don't suffer the late-add
        -- problem helpers does.
        local is_helpers = (k == "prompt_bundle:plugin_helpers")
        local helpers_source = is_helpers and S.sticky_pin_source
          and S.sticky_pin_source[k] or nil
        if k:find("^prompt_bundle:") and not is_helpers then
          stable_keys[#stable_keys+1] = k
        elseif is_helpers and helpers_source == "preempt" then
          stable_keys[#stable_keys+1] = k
        else
          growing_keys[#growing_keys+1] = k
        end
      end
    end
  end

  -- Nothing pinned anywhere: no sticky output.
  if #static_keys == 0 and #stable_keys == 0 and #growing_keys == 0 then
    return nil, nil
  end
  -- Static-only pinned refs already carry their manifest inside
  -- Net.bundled_static_refs(). Avoid emitting a separate manifest-only sticky
  -- message plus acknowledgement when no actual sticky keys are present.
  if #stable_keys == 0 and #growing_keys == 0 then
    return nil, nil
  end

  local stable_text
  if #stable_keys > 0 then
    local parts = {}
    for _, k in ipairs(stable_keys) do parts[#parts+1] = S.sticky_context[k] end
    stable_text = tbl_concat(parts, "\n\n")
  end

  -- Always emit the sticky manifest when any sticky bucket exists. Static-only
  -- turns carry their manifest inside Net.bundled_static_refs() instead. The
  -- manifest lists every pinned key so the model can short-circuit re-requests.
  -- Order: static refs first (stable slot), then stable sticky
  -- (prompt_bundle:*), then growing sticky (plugin_ref/pref/fx_*).
  --
  -- LAYOUT WITHIN growing_text (cache-stability-driven):
  --   1. Byte-stable preamble (fixed text -- never changes).
  --   2. Plugin content in insertion order (sticky_context_order). This
  --      block's prefix bytes are stable across additions because content
  --      only ever appends to the end.
  --   3. Manifest at the END.
  -- Why manifest-at-end: the manifest line gains a key every time a plugin
  -- is added. Putting it at the TOP made byte 0 of growing_text differ on
  -- every addition, invalidating the entire growing cache rung. With the
  -- manifest at the end, the plugin-content prefix stays byte-identical
  -- across additions, so Anthropic's cache hits up through the previous
  -- turn's content -- only the new plugin's content + new manifest +
  -- last_asst need fresh cache_write. ~10-15K cache_write savings per
  -- ref-addition turn.
  local all_keys = {}
  for _, k in ipairs(static_keys) do
    all_keys[#all_keys+1] = Net.public_context_key(k)
  end
  -- Keep the manifest shape stable on normal snapshot-enabled turns. The
  -- snapshot itself rides the latest user message, not sticky_context, but
  -- changing this manifest line every time a retry/follow-up rebuild toggles
  -- S.pending_snapshot would invalidate the sticky cache rung.
  if prefs.include_snapshot ~= false then all_keys[#all_keys+1] = "session" end
  for _, k in ipairs(stable_keys) do
    all_keys[#all_keys+1] = Net.public_context_key(k)
  end
  for _, k in ipairs(growing_keys) do
    all_keys[#all_keys+1] = Net.public_context_key(k)
  end
  local growing_parts = {}
  if #growing_keys > 0 then
    -- Byte-stable preamble (no key list -- fixed text). Cues the model that
    -- a manifest exists at the bottom of this section without changing the
    -- byte content turn-to-turn.
    growing_parts[#growing_parts+1] =
      "PINNED REFERENCES section follows. Full manifest at the END of this section."
    -- Plugin content in insertion order. Append-only is critical for cache
    -- stability -- see Net.sticky_set / sticky_context_order.
    for _, k in ipairs(growing_keys) do
      growing_parts[#growing_parts+1] = S.sticky_context[k]
    end
  end
  growing_parts[#growing_parts+1] =
    "PINNED REFERENCES (already provided above; do NOT re-request via "
    .. "<context_needed>): " .. tbl_concat(all_keys, ", ")
  local growing_text = tbl_concat(growing_parts, "\n\n")

  return stable_text, growing_text
end

function Net.sticky_parts_for_request()
  if Net.request_context_suppressed() then return nil, nil end
  return Net.sticky_parts()
end

-- Single-blob accessor for providers without Anthropic-style multi-breakpoint
-- caching (OpenAI / Gemini paths use this; Anthropic uses sticky_parts()
-- directly to keep the stable rung in its own cache breakpoint). Concatenates
-- stable + growing preserving insertion order. Returns nil when both sides
-- are empty.
function Net.sticky_text()
  local s, g = Net.sticky_parts_for_request()
  if not s and not g then return nil end
  if s and g then return s .. "\n\n" .. g end
  return s or g
end

-- =============================================================================
-- Net.sticky_evict
-- =============================================================================
-- Keeps S.sticky_context bounded over long sessions. Without this, every
-- plugin_ref / pref_plugins / fx_params bucket ever pinned in the session
-- stays in sticky forever, growing the prefix linearly and re-sending
-- 50-100K of irrelevant data on every turn for cinematic / 30+ turn sessions.
--
-- Strategy: each key has a "last touched" turn (sticky_context_age[k]).
--   - Unknown keys (just added) are treated as touched on the current turn.
--   - Keys whose payload identifier (the part after the colon) appears in
--     the current user prompt are refreshed to the current turn.
--   - Keys older than STICKY_MAX_AGE turns are evicted.
-- Conservative -- a re-mentioned plugin survives indefinitely; only truly
-- abandoned context gets pruned.
local STICKY_MAX_AGE = 10  -- turns

function Net.sticky_evict(user_text)
  if not S.sticky_context then return end
  S.turn_counter = (S.turn_counter or 0) + 1
  local now = S.turn_counter
  local age = S.sticky_context_age
  if not age then S.sticky_context_age = {}; age = S.sticky_context_age end
  local lower = (user_text or ""):lower()
  -- Initialize new keys, refresh keys whose identifier hits in the prompt.
  for k in pairs(S.sticky_context) do
    if not age[k] then age[k] = now end
    if Net.sticky_key_mentioned_in_prompt(k, lower) then
      age[k] = now
    end
  end
  -- Drop stale keys + clean up orphaned age entries.
  -- Exemption: docs:* / docs_extended and prompt_bundle:* are stable
  -- session-wide reference material, not per-task context that should churn.
  -- The doc payloads are cheaper to keep than to re-fetch on a follow-up
  -- keyword mention. Prompt bundles are treated as system-prompt content
  -- (`prompt_bundle_sent` is session-scoped), so evicting them would make the
  -- manifest/sent flags claim a bundle is pinned when it no longer is.
  -- Trade-off: a misfired pre-pin stays alive forever (bounded ~850-1800
  -- tokens × cache rolls; if this becomes a problem, a softer "evict at
  -- 25 turns of no-keyword-mention" rule could be added).
  local evicted
  for k, t in pairs(age) do
    if not S.sticky_context[k] then
      age[k] = nil
    elseif k == "docs_extended" or k:find("^docs:")
        or k:find("^prompt_bundle:") then
      -- exempt; see comment above.
    elseif k == "recent_reaper_changes"
        and (now - t) > 2 then
      Net.sticky_unset(k)
      age[k] = nil
      evicted = (evicted or {})
      evicted[#evicted+1] = k
    elseif (now - t) > STICKY_MAX_AGE then
      Net.sticky_unset(k)   -- also removes k from sticky_context_order
      age[k] = nil
      evicted = (evicted or {})
      evicted[#evicted+1] = k
    end
  end
  if evicted then
    Log.line("STICKY", "evicted stale sticky context: "
      .. tbl_concat(evicted, ", "))
  end
end

function Net.sticky_prune_after_plugin_success(user_text, code_text)
  if not (CTX and CTX.prompt_indicates_chain_context
      and CTX.prompt_indicates_chain_context(user_text)) then
    return
  end
  if not S.sticky_context then return end

  local code = tostring(code_text or "")
  local helper_used =
       code:find("%f[%w]find_param%s*%(") ~= nil
    or code:find("%f[%w]set_param_display%s*%(") ~= nil
    or code:find("%f[%w]set_param_enum%s*%(") ~= nil
    or code:find("%f[%w]set_param_enum_paced%s*%(") ~= nil
  local evict = {}
  for k in pairs(S.sticky_context) do
    if k == "fx_chains"
       or k == "pref_map"
       or k:find("^plugin_ref:")
       or k:find("^pref:")
       or (k == "prompt_bundle:plugin_helpers" and not helper_used) then
      evict[#evict+1] = k
    end
  end
  table.sort(evict)
  for _, k in ipairs(evict) do
    if k == "fx_chains" then
      S.fx_chains_already_sent = false
    elseif k == "prompt_bundle:plugin_helpers" then
      if S.prompt_bundle_sent then S.prompt_bundle_sent["plugin_helpers"] = nil end
    else
      local refs = k:match("^plugin_ref:(.+)$")
      if refs and S.plugin_ref_sent then
        for name in refs:gmatch("[^/]+") do S.plugin_ref_sent[name] = nil end
      end
      local prefs = k:match("^pref:(.+)$")
      if prefs and S.pref_plugins_sent then
        for name in prefs:gmatch("[^/]+") do S.pref_plugins_sent[name] = nil end
      end
    end
    Net.sticky_unset(k)
    if S.sticky_context_age then S.sticky_context_age[k] = nil end
  end
  if #evict > 0 then
    Log.line("STICKY", "pruned after successful chain action: "
      .. tbl_concat(evict, ", "))
  end
end

-- =============================================================================
-- Net.build_body (provider dispatch)
-- =============================================================================
-- Constructs the complete API request JSON body. Dispatches to a provider-specific
-- builder based on the active provider. Each builder handles system prompt
-- packaging, message formatting, attachment encoding, and any provider-specific
-- features (e.g. Anthropic prompt caching).
function Net._new_native_seed(provider_id, model_id, protocol, input_json,
                              msg_attachments, allow_image, allow_document,
                              reasoning_display_mode, conversation,
                              explicit_cache)
  if type(provider_id) ~= "string" or provider_id == ""
      or type(model_id) ~= "string" or model_id == ""
      or type(protocol) ~= "string" or protocol == ""
      or type(input_json) ~= "string" or input_json == "" then
    return nil
  end
  local required_inputs = {"text"}
  local found_image = false
  local found_document = false
  for _, attachment in ipairs(msg_attachments or {}) do
    if attachment.kind == "image" and allow_image == true then
      found_image = true
    elseif attachment.kind == "pdf" and allow_document == true then
      found_document = true
    end
  end
  if found_document then required_inputs[#required_inputs + 1] = "document" end
  if found_image then required_inputs[#required_inputs + 1] = "image" end
  local native_input_json = input_json
  local input_media_handles
  local input_media_error
  if found_image and not S.screen_reader_mode
      and type(Attach) == "table"
      and type(Attach.native_input_plan) == "function" then
    native_input_json, input_media_handles, input_media_error =
      Attach.native_input_plan(input_json, msg_attachments)
  end
  local values = {
    revision = 1,
    provider = provider_id,
    model = model_id,
    protocol = protocol,
    input_json = native_input_json or input_json,
    input_media_handles = input_media_handles,
    input_media_error = input_media_error,
    input_media_requires_engine = type(input_media_handles) == "table"
      and #input_media_handles > 0 or nil,
    required_input_modalities = Net._freeze_string_list(required_inputs),
    required_output_modalities = Net._freeze_string_list({"text"}),
    reasoning_display_mode = reasoning_display_mode,
    conversation_context_revision = conversation
      and conversation.context_revision or nil,
    conversation_history_revision = conversation
      and conversation.history_revision or nil,
    conversation_initial = conversation and conversation.initial == true or nil,
    explicit_cache_handle = explicit_cache and explicit_cache.handle or nil,
    explicit_cache_binding = explicit_cache and explicit_cache.binding or nil,
  }
  return setmetatable({}, {
    __index = values,
    __newindex = function()
      error("native inference seed is immutable", 2)
    end,
    __pairs = function() return next, values, nil end,
    __metatable = false,
  })
end

function Net._google_interactions_thinking_level(value)
  local normalized = tostring(value or ""):lower()
  if normalized == "minimal" or normalized == "low"
      or normalized == "medium" or normalized == "high" then
    return normalized
  end
  return nil
end

function Net._google_interactions_hash(tag, values)
  local framed = {tostring(tag or "")}
  for _, value in ipairs(values or {}) do
    value = tostring(value or "")
    framed[#framed + 1] = tostring(#value) .. ":" .. value
  end
  local payload = tbl_concat(framed, "|")
  local digest
  if type(Engine) == "table" and type(Engine.sha256_string) == "function" then
    local ok_native, native_digest = pcall(Engine.sha256_string, payload)
    if ok_native then digest = native_digest end
  end
  if type(digest) ~= "string" and type(RA.sha256_hex) == "function" then
    digest = RA.sha256_hex(payload)
  end
  digest = tostring(digest or ""):lower()
  return #digest == 64 and digest:match("^[0-9a-f]+$") and digest or nil
end

function Net._google_interactions_history_revision(messages, count)
  local values = {}
  count = math_max(0, math_min(math_floor(tonumber(count) or 0),
    type(messages) == "table" and #messages or 0))
  for index = 1, count do
    local message = messages[index]
    if type(message) ~= "table"
        or (message.role ~= "user" and message.role ~= "assistant")
        or type(message.content) ~= "string" then
      return nil
    end
    values[#values + 1] = message.role
    values[#values + 1] = message.content
  end
  return Net._google_interactions_hash("reaassist-google-history-v1", values)
end

function Net._google_interactions_cached_history_revision(
    conversation, messages, count)
  if type(conversation) ~= "table" or type(messages) ~= "table" then return nil end
  count = math_floor(tonumber(count) or -1)
  local cache = conversation.lua_history_cache
  if count < 0 or type(cache) ~= "table" or cache.table ~= messages
      or cache.count ~= count or cache.revision ~= conversation.history_revision
      or type(cache.messages) ~= "table" then
    return nil
  end
  for index = 1, count do
    local message = messages[index]
    local cached = cache.messages[index]
    if type(message) ~= "table" or type(cached) ~= "table"
        or cached.ref ~= message or cached.role ~= message.role
        or cached.content ~= message.content then
      return nil
    end
  end
  return cache.revision
end

function Net._google_interactions_remember_history(
    conversation, messages, count, revision)
  if type(conversation) ~= "table" or type(messages) ~= "table"
      or type(revision) ~= "string" or #revision ~= 64 then
    return false
  end
  count = math_floor(tonumber(count) or -1)
  if count < 0 or count > #messages then return false end
  local entries = {}
  for index = 1, count do
    local message = messages[index]
    if type(message) ~= "table"
        or (message.role ~= "user" and message.role ~= "assistant")
        or type(message.content) ~= "string" then
      return false
    end
    entries[index] = {
      ref = message,
      role = message.role,
      content = message.content,
    }
  end
  conversation.lua_history_cache = {
    table = messages,
    count = count,
    revision = revision,
    messages = entries,
  }
  return true
end

function Net._google_interactions_context_revision(system_text, static_blob)
  system_text = tostring(system_text or "")
  static_blob = tostring(static_blob or "")
  local cached = S.google_interactions_context_cache
  if type(cached) == "table" and cached.system_text == system_text
      and cached.static_blob == static_blob then
    return cached.revision
  end
  local revision = Net._google_interactions_hash(
    "reaassist-google-context-v1", {system_text, static_blob})
  if revision then
    S.google_interactions_context_cache = {
      system_text = system_text,
      static_blob = static_blob,
      revision = revision,
    }
  end
  return revision
end

function Net._close_google_interactions_conversation()
  local pending = S.google_interactions_pending
  S.google_interactions_pending = nil
  if type(pending) == "table" and type(pending.request_handle) == "table"
      and type(Engine) == "table"
      and type(Engine.inference_close) == "function" then
    pcall(Engine.inference_close, pending.request_handle)
  end
  local conversation = S.google_interactions_conversation
  S.google_interactions_conversation = nil
  if type(conversation) == "table" and type(Engine) == "table"
      and type(Engine.inference_conversation_close) == "function" then
    pcall(Engine.inference_conversation_close, conversation)
  end
end

function Net._discard_google_interactions_pending()
  local pending = S.google_interactions_pending
  S.google_interactions_pending = nil
  if type(pending) == "table" and type(pending.request_handle) == "table"
      and type(Engine) == "table"
      and type(Engine.inference_close) == "function" then
    pcall(Engine.inference_close, pending.request_handle)
  end
end

function Net._commit_google_interactions_pending(messages)
  local pending = S.google_interactions_pending
  if type(pending) ~= "table" then return true end
  local next_revision = Net._google_interactions_history_revision(
    messages, type(messages) == "table" and #messages or 0)
  local ok = next_revision ~= nil and type(Engine) == "table"
    and type(Engine.inference_conversation_commit) == "function"
    and select(1, pcall(function()
      local committed = Engine.inference_conversation_commit(
        pending.conversation, pending.request_handle, next_revision)
      if committed ~= true then error("conversation commit refused") end
    end))
  if type(Engine) == "table" and type(Engine.inference_close) == "function"
      and type(pending.request_handle) == "table" then
    pcall(Engine.inference_close, pending.request_handle)
  end
  S.google_interactions_pending = nil
  if ok then
    Net._google_interactions_remember_history(pending.conversation, messages,
      type(messages) == "table" and #messages or 0, next_revision)
  end
  if not ok then
    Net._close_google_interactions_conversation()
    Log.line("ENGINE", "Google Interactions continuity commit failed; "
      .. "GenerateContent will resume with Lua history")
  end
  return ok
end

function Net._responses_text_format_field(response_format)
  if response_format == "" then return "" end
  if type(response_format) ~= "string" or response_format:sub(1, 1) ~= "," then
    return nil
  end
  local ok_decode, wrapper = pcall(JSON.decode,
    "{" .. response_format:sub(2) .. "}")
  local format = ok_decode and type(wrapper) == "table"
    and wrapper.response_format or nil
  if type(format) ~= "table" then return nil end
  local converted
  if format.type == "text" then
    for name in pairs(format) do
      if name ~= "type" then return nil end
    end
    converted = {type = "text"}
  elseif format.type == "json_schema" and type(format.json_schema) == "table" then
    for name in pairs(format) do
      if name ~= "type" and name ~= "json_schema" then return nil end
    end
    converted = {type = "json_schema"}
    for name, value in pairs(format.json_schema) do
      if name ~= "name" and name ~= "schema"
          and name ~= "description" and name ~= "strict" then
        return nil
      end
      converted[name] = value
    end
  else
    return nil
  end
  local ok_encode, encoded = pcall(JSON.encode, converted)
  if not ok_encode or type(encoded) ~= "string" then return nil end
  return ',"text_format":' .. encoded
end

function Net.build_body(msgs, snapshot, msg_attachments)
  -- Probe timing: time spent assembling the request body.
  -- Wraps the dispatcher rather than each provider variant so all
  -- callers (send_to_api initial build + retries / context-needed
  -- re-fires that call build_body inline) accumulate into the same
  -- turn's body_build phase total.
  Probe.mark_phase_start(S.probe_turn, "body_build")
  local p = PROVIDERS.active()
  local task_row, task_original, task_meta =
    Net.task_context_inject_for_build(msgs)
  local ok, result, native_seed = xpcall(function()
    if p.id == "anthropic" then
      return Net.build_body_anthropic(msgs, snapshot, msg_attachments)
    elseif p.id == "openai" or p.id == "deepseek"
        or p.id == "openrouter" or p.is_custom then
      -- Custom providers always speak the OpenAI Chat Completions schema (the
      -- de-facto standard for OSS servers like Ollama, LM Studio, vLLM).
      -- DeepSeek shares this branch -- it is OpenAI-compatible at the wire
      -- level, with thinking expressed via extra_body (see the
      -- deepseek_extra_body branch in build_body_openai itself).
      return Net.build_body_openai(msgs, snapshot, msg_attachments)
    elseif p.id == "google" then
      return Net.build_body_google(msgs, snapshot, msg_attachments)
    end
  end, function(err)
    if debug and debug.traceback then return debug.traceback(err, 2) end
    return tostring(err)
  end)
  if task_row then task_row.content = task_original end
  Probe.mark_phase_end(S.probe_turn, "body_build")
  if not ok then error(result, 0) end
  if task_meta and S.pending_display_idx
     and S.display_messages[S.pending_display_idx] then
    local dmsg = S.display_messages[S.pending_display_idx]
    dmsg.task_context_bytes = task_meta.bytes
    dmsg.task_context_source_requests = task_meta.source_requests
    dmsg.task_context_included_requests = task_meta.included_requests
    dmsg.task_context_shortened_requests = task_meta.shortened_requests
    dmsg.task_context_elided_requests = task_meta.elided_requests
  end
  -- Local Bench builds expose a request-context recorder. Keep this hook inert
  -- in shipped ReaAssist, but let the Bench attribute exact included source
  -- bytes to individual sticky buckets before Log.request attaches the body to
  -- a cell. Matching against the assembled JSON avoids reporting stale sticky
  -- entries that the request-specific skip policy omitted.
  if result and BenchMode and BenchMode.record_request_context then
    local buckets = {}
    local function record_if_included(name, content)
      if type(content) ~= "string" or content == "" then return end
      if result:find(JSON.escape(content), 1, true) then
        buckets[name] = #content
      end
    end
    local sys = Net.system_prompt_text()
    if sys then
      local custom = Net.custom_instructions_prompt_block_for_request()
      local base_bytes = #sys - (custom and #custom or 0)
      if base_bytes > 0 then buckets.system_prompt = base_bytes end
      record_if_included("custom_instructions", custom)
    end
    if task_original then
      -- The temporary task-context insertion can split the original row, so
      -- contiguous body matching cannot account for it after restoration.
      buckets.user_request = #task_original
    elseif msgs and msgs[#msgs] then
      record_if_included("user_request", msgs[#msgs].content)
    end
    if not Net.request_context_suppressed() then
      record_if_included("docs", S.api_ref_message)
      record_if_included("midi", S.midi_ref_message)
      record_if_included("theme", S.theme_ref_message)
      for key, content in pairs(S.sticky_context or {}) do
        record_if_included(key, content)
      end
    end
    record_if_included("snapshot", snapshot)
    local attachment_bytes = 0
    for _, att in ipairs(msg_attachments or {}) do
      attachment_bytes = attachment_bytes
        + #(att.b64 or att.data or "")
    end
    if attachment_bytes > 0 then buckets.attachments = attachment_bytes end
    if task_meta and task_meta.bytes > 0 then
      buckets.task_context = task_meta.bytes
    end
    BenchMode.record_request_context({
      provider = p.id,
      body_bytes = #result,
      buckets = buckets,
    })
  end
  return result, native_seed
end

-- =============================================================================
-- Net.build_body_anthropic
-- =============================================================================
-- Anthropic Messages API format. System prompt as top-level "system" field with
-- cache_control. Pinned API ref as first user message (stable cache position).
-- Snapshot injected as a separate content block in the last user message.
--
-- Cache breakpoints (max 4 allowed by Anthropic, we use up to 4):
--   1. System prompt                                 (always)
--   2. End of static_blob + sticky_stable rung       (when either present;
--      static_blob piggybacks on sticky_stable's mark when both are present)
--   3. sticky_growing rung                           (when present)
--   4. Last assistant message                        (moving breakpoint,
--      prefix grows one user/assistant pair per turn)
--
-- TTL strategy: every rung uses the 5-minute default (CACHE_5M). Two
-- constraints made anything fancier net-negative:
--
--   1. Anthropic forbids a 1h cache_control block from appearing AFTER any
--      5m block in the same request: "a ttl='1h' cache_control block must
--      not come after a ttl='5m' cache_control block" (invalid_request_error).
--      Since our breakpoints are positionally fixed (system first,
--      last_asst last), any per-rung mix of 5m+1h that puts 1h on
--      last_asst gets rejected.
--   2. Anthropic also treats the ttl field as part of the cache key, so
--      flipping a rung from 5m to 1h between turns busts that rung's
--      cached prefix. Earlier code stamped one TTL per request and
--      flipped 5m -> 1h on turn 2 to "warm" 1h coverage; the observed
--      effect was cache_read=0 on T2 (full prefix re-write) regardless
--      of whether the gap exceeded 5 min.
--
-- Plan A (this code): drop the 1h escalation entirely. Always 5m, on every
-- rung, every turn. Net effect: cache stays warm across normal read/run/
-- refine cadences (which are typically <5 min anyway), and the rare
-- >5-min idle gap costs one prefix re-write -- strictly cheaper than
-- the original "flip everyone to 1h on T2" approach which paid that cost
-- 100% of the time on multi-turn sessions.
local CACHE_5M = ',"cache_control":{"type":"ephemeral"}'

-- Cheap content fingerprint for cache-plan diagnostics. Not cryptographic --
-- just a stable 32-bit FNV-1a in hex so the debug log can show "did this
-- rung's bytes drift between turns" at a glance. Skipped when debug logging
-- is off (callers gate on prefs.debug_logging via Log.line).
local function _cache_plan_hash(s)
  local h = 2166136261
  for i = 1, #s do
    h = (h ~ s:byte(i)) * 16777619
    h = h & 0xFFFFFFFF
  end
  return string.format("%08x", h)
end

function Net.build_body_anthropic(msgs, snapshot, msg_attachments)
  -- Each rung emits CACHE_5M; the helpers below also record bytes/hash into
  -- cache_plan for the per-request CACHE-PLAN debug line. See the function
  -- header for the constraints that motivated the always-5m strategy.
  local cache_plan = {}
  local function rung_cache_mark(rung_name, content)
    cache_plan[#cache_plan+1] = {
      name = rung_name, ttl = "5m", bytes = content and #content or 0,
      hash = (content and prefs.debug_logging) and _cache_plan_hash(content) or "-",
    }
    return CACHE_5M
  end

  -- Diagnostic-only registration for content that lands ahead of an
  -- existing cache breakpoint without a marker of its own (e.g.,
  -- static_blob when sticky_stable absorbs it onto the same rung).
  -- Without this, the cache plan only hashes the rung-bearing block,
  -- so drift in the absorbed content (a new static ref appearing,
  -- reorder of api_ref / midi_ref / theme_ref) is invisible to the
  -- log even though it busts the rung's prefix in reality.
  local function rung_piggyback(rung_name, content)
    cache_plan[#cache_plan+1] = {
      name = rung_name .. "(piggyback)",
      ttl  = "-",
      bytes = content and #content or 0,
      hash = (content and prefs.debug_logging) and _cache_plan_hash(content) or "-",
    }
  end

  local system_text = Net.system_prompt_text()
  local system_json = str_format(
    '[{"type":"text","text":"%s"%s}]',
    JSON.escape(system_text), rung_cache_mark("system", system_text))

  local msg_parts = {}

  -- Bundle the long-lived static refs (api_ref + midi_ref + theme_ref) into
  -- ONE pinned user message with a single trailing ack, instead of three
  -- separate user/ack pairs. Saves ~16-24 tokens per turn in ack overhead
  -- and reduces alignment churn for downstream caches when refs come in.
  -- Anthropic 4-breakpoint allocation:
  --   slot 1: system + custom instructions             (always)
  --   slot 2: end of static_blob + sticky_stable       (when sticky_stable
  --                                                     present; static_blob
  --                                                     piggybacks on this rung)
  --           OR static_blob                           (when sticky_stable
  --                                                     absent but static_blob
  --                                                     present)
  --           OR sticky_stable                         (when static_blob absent)
  --   slot 3: sticky_growing                           (when present)
  --   slot 4: last_asst                                (moving, when history
  --                                                     has >= 1 complete turn)
  -- Why static_blob loses its dedicated cache mark when sticky_stable is
  -- present: a single-rung cache covering "system + static_blob + sticky_stable"
  -- is functionally identical to two separate rungs (any change to static_blob
  -- invalidates sticky_stable's prefix anyway), but it FREES a breakpoint slot
  -- so sticky_growing can have its own rung. The win: when sticky_growing
  -- changes (every fx_inspect / plugin_ref / pref addition), sticky_stable
  -- (~14K plugin bundle) keeps reading from cache instead of being rewritten
  -- alongside the growing block. Observed cost before this change: ~10-15K
  -- cache_write per ref-addition turn.
  local sticky_stable, sticky_growing = Net.sticky_parts_for_request()
  local static_blob = Net.bundled_static_refs_for_request()
  if static_blob then
    -- Drop static_blob's own cache_mark when sticky_stable will absorb it
    -- into the next rung. Keep it when sticky_stable is absent (otherwise
    -- static_blob would only cache via sticky_growing's rung, which gets
    -- invalidated frequently).
    local static_cache_mark
    if sticky_stable then
      -- Absorbed onto sticky_stable's rung. Register a piggyback entry
      -- in the cache plan so static-ref drift (a new midi_ref / theme_ref
      -- arriving, or api_ref reordering) shows up in the log even though
      -- this block carries no cache_control marker of its own.
      rung_piggyback("static", static_blob)
      static_cache_mark = ""
    else
      static_cache_mark = rung_cache_mark("static", static_blob)
    end
    msg_parts[#msg_parts+1] = str_format(
      '{"role":"user","content":[{"type":"text","text":"%s"%s}]}',
      JSON.escape(static_blob), static_cache_mark)
    msg_parts[#msg_parts+1] = '{"role":"assistant","content":[{"type":"text","text":"Understood."}]}'
  end
  -- Pinned sticky with up to TWO cache_control breakpoints:
  --   - sticky_stable  : prompt_bundle:* payloads (big, effectively frozen
  --                      for the rest of the session). Own cache rung so it
  --                      stays hot even when the growing block invalidates.
  --   - sticky_growing : plugin_ref / pref / fx_params / fx_inspect, plus
  --                      a manifest line listing all pinned keys. Its cache
  --                      rung re-writes on each ref addition but the stable
  --                      rung's ~15K tokens no longer get re-written with it.
  -- The 2-block split now fires whenever both halves are populated -- the
  -- breakpoint budget is free because static_blob piggybacks on sticky_stable.
  local has_sticky = sticky_stable or sticky_growing
  if has_sticky then
    local can_split = sticky_stable and sticky_growing
    if can_split then
      -- Two content blocks in ONE user message, each with its own
      -- cache_control. Anthropic caches each block as its own prefix rung:
      -- adding a new plugin_ref changes the growing block but NOT the
      -- stable block, so the stable rung keeps reading on subsequent
      -- turns. Saves ~15K tokens of cache_write per ref-addition turn.
      msg_parts[#msg_parts+1] = str_format(
        '{"role":"user","content":[{"type":"text","text":"%s"%s},{"type":"text","text":"%s"%s}]}',
        JSON.escape(sticky_stable), rung_cache_mark("sticky_stable", sticky_stable),
        JSON.escape(sticky_growing), rung_cache_mark("sticky_growing", sticky_growing))
    else
      -- Single-block fallback: only one of stable/growing is populated.
      -- Concatenate in stable-first order so byte-prefix caching still wins
      -- on OpenAI-style implicit cache if we're ever reused there.
      local blob = sticky_stable and sticky_growing
        and (sticky_stable .. "\n\n" .. sticky_growing)
        or  (sticky_stable or sticky_growing)
      -- Rung name reflects which half is present so per-rung TTL state
      -- doesn't conflate "sticky_stable alone" with "sticky_stable + growing
      -- collapsed into one rung". In practice only one of these branches
      -- exercises within a given session.
      local rung = sticky_stable and "sticky_stable" or "sticky_growing"
      msg_parts[#msg_parts+1] = str_format(
        '{"role":"user","content":[{"type":"text","text":"%s"%s}]}',
        JSON.escape(blob), rung_cache_mark(rung, blob))
    end
    msg_parts[#msg_parts+1] = '{"role":"assistant","content":[{"type":"text","text":"Understood."}]}'
  end

  local last_asst_idx = nil
  for idx = #msgs, 1, -1 do
    local m = msgs[idx]
    if m and m.role == "assistant" then
      last_asst_idx = idx
      break
    end
  end

  for idx, m in ipairs(msgs) do
    local is_last_user = (m.role == "user" and idx == #msgs)

    if is_last_user then
      -- Build content blocks for the last user message: text + snapshot + attachments.
      local blocks = {}
      blocks[#blocks+1] = str_format('{"type":"text","text":"%s"}',
        JSON.escape(m.content))

      if snapshot then
        blocks[#blocks+1] = str_format('{"type":"text","text":"%s"}',
          JSON.escape(snapshot))
      end

      -- Append attachment content blocks (images, PDFs, text files).
      if msg_attachments then
        for _, att in ipairs(msg_attachments) do
          if att.kind == "image" then
            local media_index = Attach.native_media_index(msg_attachments, att)
            if media_index ~= nil then
              blocks[#blocks+1] = str_format(
                '{"type":"input_media","index":%d}', media_index)
            else
              blocks[#blocks+1] = str_format(
                '{"type":"image","source":{"type":"base64","media_type":"%s","data":"%s"}}',
                JSON.escape(att.media_type), att.b64)
            end
          elseif att.kind == "pdf" then
            blocks[#blocks+1] = str_format(
              '{"type":"document","source":{"type":"base64","media_type":"application/pdf","data":"%s"}}',
              att.b64)
          elseif att.kind == "text" then
            blocks[#blocks+1] = str_format(
              '{"type":"text","text":"[Attached file: %s]\\n%s"}',
              JSON.escape(att.name), JSON.escape(att.data))
          end
        end
      end

      msg_parts[#msg_parts+1] = str_format(
        '{"role":"user","content":[%s]}', tbl_concat(blocks, ","))
    else
      -- Non-final messages: single block. Mark the last assistant message as a
      -- moving cache breakpoint so the conversation prefix is cached for
      -- cheaper follow-up turns.
      local is_last_asst = (m.role == "assistant" and idx == last_asst_idx)
      local cache = is_last_asst and rung_cache_mark("last_asst", m.content) or ""
      msg_parts[#msg_parts+1] = str_format(
        '{"role":"%s","content":[{"type":"text","text":"%s"%s}]}',
        m.role, JSON.escape(m.content), cache)
    end
  end

  -- Per-rung cache plan (debug only): rung=bytes/ttl/hash, comma-separated.
  -- Lets the user diff request-to-request: if a rung's hash changes, its
  -- prefix bytes drifted (manifest reorder, ref insertion); if its ttl
  -- string changes, the freeze logic regressed. Either way, expect a miss.
  if prefs.debug_logging and #cache_plan > 0 then
    local parts = {}
    for _, p in ipairs(cache_plan) do
      parts[#parts+1] = str_format("%s=%dB/%s/%s", p.name, p.bytes, p.ttl, p.hash)
    end
    Log.line("CACHE-PLAN", tbl_concat(parts, ", "))
  end

  -- Anthropic Messages API REQUIRES max_tokens (omitting returns 400). Send
  -- the active model's published output ceiling so the model can write up to
  -- the maximum it supports. This is intentionally larger than any thinking
  -- budget above; thinking budget limits reasoning tokens, while max_tokens
  -- limits total response output. Non-streaming requests with very large
  -- ceilings rely on ReaAssist's watchdog/Extend UX to handle slow completions.
  -- Falls back to 64K if the model entry is missing max_output (older entries;
  -- defensive, all current entries have it).
  local active_m = MODELS[prefs.model_idx] or MODELS[1]
  local max_out  = (active_m and active_m.max_output) or 64000

  -- Extended thinking. Anthropic's API treats `thinking` as opt-in for
  -- every Claude model: when the field is absent, the model runs in
  -- non-thinking mode regardless of which 4.x variant is active. The
  -- "None" dropdown entry maps to an explicit disabled-thinking request.
  -- When a non-None level is picked, the wire shape depends on the active model's
  -- thinking_style: Haiku 4.5 takes manual budget_tokens; Sonnet 5 and
  -- Opus 5 use adaptive + an effort knob and reject manual budgets.
  -- S.thinking_override_idx (when
  -- set) wins over prefs.thinking_idx so the length-retry path can force
  -- "None" for one round-trip.
  local p_active = PROVIDERS.active()
  local effective_thinking_idx = S.thinking_override_idx or prefs.thinking_idx
  local thinking_field = ""
  local summary_display = prefs.show_reasoning_summaries == true
    and not S.screen_reader_mode
    and ',"display":"summarized"' or ""
  if effective_thinking_idx and effective_thinking_idx > 0
     and p_active.thinking_levels then
    local tl = p_active.thinking_levels[effective_thinking_idx]
    local style = active_m and active_m.thinking_style
    if tl then
      if tl.value == "none" then
        thinking_field = ',"thinking":{"type":"disabled"}'
      elseif style == "claude_adaptive" and tl.effort then
        thinking_field = str_format(
          ',"thinking":{"type":"adaptive"%s},"output_config":{"effort":"%s"}',
          summary_display, tl.effort)
      elseif tl.budget_tokens then
        -- claude_manual (Haiku 4.5) -- and a defensive fallback if a
        -- model entry omits thinking_style entirely.
        thinking_field = str_format(
          ',"thinking":{"type":"enabled","budget_tokens":%d%s}',
          tl.budget_tokens, summary_display)
      end
    end
  end

  local messages_json = tbl_concat(msg_parts, ",")
  local model_id = MODELS.active_id()
  local body = str_format(
    '{"model":"%s","max_tokens":%d%s,"system":%s,"messages":[%s]}',
    model_id, max_out, thinking_field, system_json, messages_json)
  local input_json = str_format(
    '{"max_tokens":%d%s,"system":%s,"messages":[%s]}',
    max_out, thinking_field, system_json, messages_json)
  local protocol = type(Net._protocol_for_provider) == "function"
    and Net._protocol_for_provider(p_active, active_m) or nil
  local seed = type(Net._new_native_seed) == "function" and protocol
    and Net._new_native_seed("anthropic", model_id, protocol, input_json,
      msg_attachments, true, true, Net.reasoning_display_mode()) or nil
  return body, seed
end

-- =============================================================================
-- Net.merge_custom_extra_body
-- =============================================================================
-- Merge provider-wide extra_body (p.extra_body) with per-model extra_body
-- (active_m.extra_body) and return the result as a comma-prefixed JSON
-- body suffix ("," + inner-JSON without surrounding braces) ready to splice
-- into the outer chat/completions body. Returns "" when both are empty or
-- decode fails -- callers can append it unconditionally.
--
-- Per-model keys win over provider-wide keys (in-order decode/merge/re-
-- encode pass). Runs through JSON.decode / JSON.encode so we don't brace-
-- splice raw user input.
--
-- Shared by Net.build_body_openai (real chat) and Net.fire_key_test's
-- opt-in inference probe so the test exercises the same vendor-specific
-- toggles as the real chat path. active_m may be nil; result is the same
-- as if its extra_body were empty.
function Net.merge_custom_extra_body(p, active_m)
  if not p or not p.is_custom then return "" end
  local prov_body  = p.extra_body or ""
  local model_body = (active_m and active_m.extra_body) or ""
  if prov_body == "" and model_body == "" then return "" end
  local merged = {}
  if prov_body ~= "" then
    local pobj = JSON.decode(prov_body)
    if type(pobj) == "table" then
      for k, v in pairs(pobj) do merged[k] = v end
    end
  end
  if model_body ~= "" then
    local mobj = JSON.decode(model_body)
    if type(mobj) == "table" then
      for k, v in pairs(mobj) do merged[k] = v end
    end
  end
  local encoded = JSON.encode(merged)
  if not encoded or encoded == "{}"
     or encoded:sub(1, 1) ~= "{" or encoded:sub(-1) ~= "}" then
    return ""
  end
  local inner = encoded:sub(2, -2)
  if inner == "" then return "" end
  return "," .. inner
end

-- =============================================================================
-- Net.build_body_openai
-- =============================================================================
-- OpenAI Chat Completions API format. System prompt as a "system" role message.
-- All messages are simple {role, content} objects. Attachments: images as
-- image_url content parts, text files inline, PDFs as text note (unsupported).
function Net.openai_prompt_cache_key()
  if type(S.openai_prompt_cache_key) == "string"
     and S.openai_prompt_cache_key ~= "" then
    return S.openai_prompt_cache_key
  end
  local key
  if Store and Store.openai_prompt_cache_key then
    local ok, result = pcall(Store.openai_prompt_cache_key)
    if ok and type(result) == "string" and result ~= "" then
      key = result
    elseif not ok then
      Log.line("CACHE", "openai prompt_cache_key restore failed: "
        .. tostring(result))
    end
  end
  key = key or S.INSTANCE_ID or "ra_prompt_cache"
  S.openai_prompt_cache_key = key
  return key
end

function Net.openai_safety_identifier()
  if type(S.openai_safety_identifier) == "string"
     and #S.openai_safety_identifier == 64
     and S.openai_safety_identifier:match("^[0-9a-f]+$") then
    return S.openai_safety_identifier
  end
  if not RA or type(RA.sha256_hex) ~= "function" then
    Log.line("SAFETY", "OpenAI safety identifier omitted: SHA-256 unavailable")
    return nil
  end
  local cache_key = Net.openai_prompt_cache_key()
  if type(cache_key) ~= "string" or cache_key == "" then return nil end
  local ok, identifier = pcall(RA.sha256_hex,
    "reaassist:openai:safety:v1:" .. cache_key)
  if not ok or type(identifier) ~= "string" then
    Log.line("SAFETY", "OpenAI safety identifier omitted: hash failed")
    return nil
  end
  identifier = identifier:lower()
  if #identifier ~= 64 or not identifier:match("^[0-9a-f]+$") then
    Log.line("SAFETY", "OpenAI safety identifier omitted: invalid hash")
    return nil
  end
  S.openai_safety_identifier = identifier
  return identifier
end

function Net.build_body_openai(msgs, snapshot, msg_attachments)
  local msg_parts = {}
  local deepseek_msg_parts = {}
  local p = PROVIDERS.active()
  local model_id = MODELS.active_id()
  if p.is_custom and p.model_prefix and p.model_prefix ~= "" then
    model_id = p.model_prefix .. model_id
  end
  local is_openai_56 = p.id == "openai"
    and type(model_id) == "string"
    and model_id:match("^gpt%-5%.6") ~= nil

  -- GPT-5.6 explicit caching: mark the stable core system prompt and disable
  -- the implicit latest-message breakpoint. This avoids paying a 1.25x write
  -- premium on the changing user prompt, snapshot, and attachments. Older
  -- models reject the new fields, so they retain automatic implicit caching.
  if is_openai_56 then
    local message = str_format(
      '{"role":"system","content":[{"type":"text","text":"%s","prompt_cache_breakpoint":{"mode":"explicit"}}]}',
      JSON.escape(Net.system_prompt_text()))
    msg_parts[#msg_parts+1] = message
  else
    local message = str_format(
      '{"role":"system","content":"%s"}', JSON.escape(Net.system_prompt_text()))
    msg_parts[#msg_parts+1] = message
    if p.id == "deepseek" then deepseek_msg_parts[#deepseek_msg_parts+1] = message end
  end

  -- Bundle the long-lived static refs (api_ref + midi_ref + theme_ref) into
  -- ONE pinned system message instead of three. OpenAI's implicit prefix
  -- caching aligns on byte-level prefix; fewer message boundaries mean a
  -- cleaner, more stable prefix. See Net.bundled_static_refs().
  local static_blob = Net.bundled_static_refs_for_request()
  if static_blob then
    if is_openai_56 then
      -- The bundled API/MIDI/theme references are the second reusable prefix.
      -- Prompt-specific sticky plugin/context material remains after this
      -- breakpoint so one-off context does not create avoidable cache writes.
      msg_parts[#msg_parts+1] = str_format(
        '{"role":"system","content":[{"type":"text","text":"%s","prompt_cache_breakpoint":{"mode":"explicit"}}]}',
        JSON.escape(static_blob))
    else
      local message = str_format(
        '{"role":"system","content":"%s"}', JSON.escape(static_blob))
      msg_parts[#msg_parts+1] = message
      if p.id == "deepseek" then deepseek_msg_parts[#deepseek_msg_parts+1] = message end
    end
  end

  -- Prepend pinned sticky context (plugin_ref / pref_plugins / fx_params /
  -- fx_inspect) as a system message so OpenAI's implicit prefix caching can
  -- discover the stable common prefix across turns. See Net.sticky_text().
  local sticky_blob = Net.sticky_text()
  if sticky_blob then
    local message = str_format(
      '{"role":"system","content":"%s"}', JSON.escape(sticky_blob))
    msg_parts[#msg_parts+1] = message
    if p.id == "deepseek" then deepseek_msg_parts[#deepseek_msg_parts+1] = message end
  end

  for idx, m in ipairs(msgs) do
    local is_last_user = (m.role == "user" and idx == #msgs)

    if is_last_user then
      -- Last user message: may include snapshot and attachments as content array.
      local has_extras = snapshot or msg_attachments
      if has_extras then
        local blocks = {}
        local deepseek_text_parts = {m.content}
        blocks[#blocks+1] = str_format('{"type":"text","text":"%s"}',
          JSON.escape(m.content))
        if snapshot then
          blocks[#blocks+1] = str_format('{"type":"text","text":"%s"}',
            JSON.escape(snapshot))
          deepseek_text_parts[#deepseek_text_parts+1] = snapshot
        end
        local _active_provider = PROVIDERS.active()
        local _active_model = MODELS[prefs.model_idx]
        local _deepseek_image_input = false
        local _openrouter_image_input = false
        if _active_provider and _active_provider.id == "deepseek"
            and _active_model and type(_active_model.input_modalities) == "table" then
          for _, _modality in ipairs(_active_model.input_modalities) do
            if _modality == "image" then _deepseek_image_input = true end
          end
        elseif _active_provider and _active_provider.id == "openrouter"
            and _active_model and type(_active_model.input_modalities) == "table" then
          for _, _modality in ipairs(_active_model.input_modalities) do
            if _modality == "image" then _openrouter_image_input = true end
          end
        end
        if msg_attachments then
          for _, att in ipairs(msg_attachments) do
            if att.kind == "image" then
              if _active_provider and _active_provider.id == "deepseek"
                  and not _deepseek_image_input then
                -- This selected DeepSeek model is text-only, so an image_url
                -- block would be unrepresentable. Surface the attachment by
                -- name as a text note so the model can acknowledge it and the
                -- user understands why it was not visually inspected. This
                -- matches the PDF handling below.
                blocks[#blocks+1] = str_format(
                  '{"type":"text","text":"[Attached image: %s] (DeepSeek does not support image input; this attachment was not sent.)"}',
                  JSON.escape(att.name))
                deepseek_text_parts[#deepseek_text_parts+1] =
                  "[Attached image: " .. tostring(att.name or "")
                  .. "] (DeepSeek does not support image input; this attachment was not sent.)"
              elseif _active_provider and _active_provider.id == "openrouter"
                  and not _openrouter_image_input then
                blocks[#blocks+1] = str_format(
                  '{"type":"text","text":"[Attached image: %s] (This OpenRouter model has no verified image-input capability; this attachment was not sent.)"}',
                  JSON.escape(att.name))
              else
                local media_index = Attach.native_media_index(
                  msg_attachments, att)
                if media_index ~= nil then
                  blocks[#blocks+1] = str_format(
                    '{"type":"input_media","index":%d}', media_index)
                else
                  blocks[#blocks+1] = str_format(
                    '{"type":"image_url","image_url":{"url":"data:%s;base64,%s"}}',
                    JSON.escape(att.media_type), att.b64)
                end
              end
            elseif att.kind == "text" then
              blocks[#blocks+1] = str_format(
                '{"type":"text","text":"[Attached file: %s]\\n%s"}',
                JSON.escape(att.name), JSON.escape(att.data))
              deepseek_text_parts[#deepseek_text_parts+1] =
                "[Attached file: " .. tostring(att.name or "") .. "]\n"
                .. tostring(att.data or "")
            elseif att.kind == "pdf" then
              blocks[#blocks+1] = str_format(
                '{"type":"text","text":"[Attached PDF: %s] (PDF content attached as document)"}',
                JSON.escape(att.name))
              deepseek_text_parts[#deepseek_text_parts+1] =
                "[Attached PDF: " .. tostring(att.name or "")
                .. "] (PDF content attached as document)"
            end
          end
        end
        local message = str_format(
          '{"role":"user","content":[%s]}', tbl_concat(blocks, ","))
        msg_parts[#msg_parts+1] = message
        if p.id == "deepseek" then
          if _deepseek_image_input then
            deepseek_msg_parts[#deepseek_msg_parts+1] = message
          else
            deepseek_msg_parts[#deepseek_msg_parts+1] = str_format(
              '{"role":"user","content":"%s"}',
              JSON.escape(tbl_concat(deepseek_text_parts, "\n\n")))
          end
        end
      else
        local message = str_format(
          '{"role":"user","content":"%s"}', JSON.escape(m.content))
        msg_parts[#msg_parts+1] = message
        if p.id == "deepseek" then deepseek_msg_parts[#deepseek_msg_parts+1] = message end
      end
    else
      local message = str_format(
        '{"role":"%s","content":"%s"}', m.role, JSON.escape(m.content))
      msg_parts[#msg_parts+1] = message
      if p.id == "deepseek" then deepseek_msg_parts[#deepseek_msg_parts+1] = message end
    end
  end

  local safety_identifier_field = ""
  if p.id == "openai" then
    local safety_identifier = Net.openai_safety_identifier()
    if safety_identifier then
      safety_identifier_field = str_format(
        ',"safety_identifier":"%s"', JSON.escape(safety_identifier))
    end
  end
  -- reasoning_effort: top-level string on the Chat Completions API.
  -- Hosted OpenAI accepts "none" | "low" | "medium" | "high" (and newer
  -- models also accept xhigh/max). Send "none" explicitly: GPT-5.6 defaults
  -- to Medium when the field is omitted, so omission is not an off switch.
  -- Custom-compatible providers keep the older omission behavior because
  -- many reject OpenAI-specific reasoning values.
  -- S.thinking_override_idx (when set) wins over prefs.thinking_idx -- the
  -- length auto-retry path uses this to force "none" for one round-trip
  -- when reasoning consumed the entire output budget on the first attempt.
  --
  -- DeepSeek (thinking_style == "deepseek_extra_body") expresses thinking
  -- via a top-level "thinking" object with type="disabled"|"enabled" instead
  -- of OpenAI's reasoning_effort scale. The "extra_body" name in DeepSeek's
  -- own docs is an OpenAI-SDK pass-through convention; on the wire the
  -- field sits at the top level next to where reasoning_effort would go.
  -- The field is MANDATORY for every DeepSeek request: omitting it falls
  -- through to DeepSeek's server-side default (currently enabled) which
  -- would silently ignore both the user's Non-Thinking selection and the
  -- length-retry fallback. Always emit an explicit "enabled"/"disabled";
  -- if the resolved idx is somehow out-of-range or carries an unexpected
  -- value, default to "disabled" (safer -- no surprise reasoning cost).
  local effective_thinking_idx = S.thinking_override_idx or prefs.thinking_idx
  local reasoning = ""
  local reasoning_effort_value
  local deepseek_thinking_value
  if p.thinking_style == "deepseek_extra_body" then
    local tl = p.thinking_levels and p.thinking_levels[effective_thinking_idx]
    local val = (tl and tl.value) or "disabled"
    if val ~= "enabled" and val ~= "disabled" then val = "disabled" end
    deepseek_thinking_value = val
    reasoning = str_format(',"thinking":{"type":"%s"}', val)
  elseif effective_thinking_idx > 0
     and p.thinking_levels
     and p.thinking_levels[effective_thinking_idx] then
    local val = p.thinking_levels[effective_thinking_idx].value
    if val and (val ~= "none" or is_openai_56) then
      reasoning_effort_value = val
      reasoning = str_format(',"reasoning_effort":"%s"', val)
    end
  end
  -- prompt_cache_key: stable per install identifier. Hosted OpenAI cache
  -- routing uses this together with the exact prefix, raising hit rates on
  -- long sessions and across REAPER restarts. GPT-5.6 requires it for improved
  -- implicit or explicit matching. Keep the automatic field out of Custom
  -- request bodies, where an OpenAI-compatible endpoint may reject it. A user
  -- can still add a vendor-supported field explicitly through extra_body.
  -- Custom-provider model prefix: OpenRouter/LiteLLM/Ollama routing gateways
  -- often require a prefix ("openrouter/anthropic/...", "ollama/...") on the
  -- model id. Stored per-provider so users don't have to type it into every
  -- model row. Empty string = no-op, matching hosted OpenAI's behaviour.
  local cache_options_field = is_openai_56
    and ',"prompt_cache_options":{"mode":"explicit","ttl":"30m"}' or ""
  local prompt_cache_key_field = ""
  if p.id == "openai" then
    prompt_cache_key_field = str_format(
      ',"prompt_cache_key":"%s"',
      JSON.escape(Net.openai_prompt_cache_key()))
  end
  local response_format = ""
  if p.id == "openai"
     and S.pending_typed_action_expected == true
     and S.pending_typed_action_response_format == true
     and type(Code.typed_actions_openai_response_format_field) == "function" then
    response_format =
      Code.typed_actions_openai_response_format_field(
        S.pending_orig_prompt or "") or ""
  end
  -- Custom-provider extra_body: merge provider-wide + per-model JSON objects
  -- into the outer request body. Net.merge_custom_extra_body is the shared
  -- helper -- used here for real chat AND from Net.fire_key_test's opt-in
  -- inference test path so the test exercises the same vendor toggles
  -- (Kimi thinking flag, Qwen enable_thinking, OpenRouter reasoning, etc.)
  -- that real chat sends.
  local extra_suffix = ""
  if p.is_custom then
    extra_suffix = Net.merge_custom_extra_body(p, MODELS[prefs.model_idx])
  end
  -- max_completion_tokens: optional on the OpenAI Chat Completions API. For
  -- normal cloud OpenAI chat, omit it so the server applies its own per-model
  -- ceiling -- avoids the GPT-5-thinking failure mode where a fixed cap got
  -- consumed by reasoning tokens and produced empty visible output. Typed-action
  -- response-format requests are different: the only valid answer is compact
  -- JSON, so cap them to prevent runaway structured-output completions. Keep
  -- enough room for GPT-5 mini Low thinking, which can spend several thousand
  -- hidden reasoning tokens before emitting the compact JSON object. Small
  -- typed-action profiles can opt into a lower cap; if they hit it, the
  -- validator fails closed and escalates instead of waiting on an 8K-token loop.
  -- For custom providers (Ollama / LM Studio / vLLM / OpenRouter etc.), keep
  -- the cap derived from the per-model context_window field on the API Keys
  -- page, since local servers commonly run with tight context windows that need
  -- a real bound on output.
  local max_tokens_field = ""
  if p.id == "openai" and response_format ~= "" then
    local typed_action_cap = 8192
    local active_model = MODELS[prefs.model_idx]
    local model_cap = active_model
      and tonumber(active_model.typed_action_max_completion)
    if model_cap and model_cap > 0 then
      typed_action_cap = math_floor(model_cap)
    end
    local tl = p.thinking_levels and p.thinking_levels[effective_thinking_idx]
    if S.typed_action_escalation_used == true
       and tl and tl.value == "none" then
      typed_action_cap = math_min(typed_action_cap, 2048)
    end
    max_tokens_field =
      str_format(',"max_completion_tokens":%d', typed_action_cap)
  elseif p.id == "openrouter" then
    local openrouter_active = MODELS[prefs.model_idx] or active_model
    local openrouter_cap = tonumber(openrouter_active
      and openrouter_active.max_output) or OpenRouter.OUTPUT_CAP_DEFAULT
    openrouter_cap = math_max(1, math_min(
      OpenRouter.OUTPUT_CAP_DEFAULT, math_floor(openrouter_cap)))
    max_tokens_field =
      str_format(',"max_completion_tokens":%d', openrouter_cap)
  elseif p.is_custom then
    local custom_active = MODELS[prefs.model_idx]
    local ctx_window    = (custom_active and tonumber(custom_active.context_window))
                          or CUSTOM_DEFAULT_CTX
    -- Reserve at most 10% of the local context for output, with a hard
    -- ceiling at 16K so a misconfigured huge context_window doesn't lead
    -- to absurd output budgets that don't match what local hardware can
    -- actually generate in a reasonable time.
    local custom_cap = math_min(16384, math_floor(ctx_window * 0.1))
    if custom_cap < 256 then custom_cap = 256 end
    max_tokens_field = str_format(',"max_completion_tokens":%d', custom_cap)
  end
  -- DeepSeek: skip prompt_cache_key (OpenAI-only routing hint; DeepSeek caches
  -- automatically on prefix and ignores the field, but emitting it makes the
  -- request log misleading) and skip max_completion_tokens (handled like
  -- cloud OpenAI -- let the server apply its own per-model ceiling).
  local messages_json = tbl_concat(msg_parts, ",")
  local body
  if p.id == "deepseek" then
    body = str_format(
      '{"model":"%s","messages":[%s]%s%s}',
      model_id, messages_json, reasoning, extra_suffix)
  else
    body = str_format(
      '{"model":"%s"%s%s%s%s,"messages":[%s]%s%s%s}',
      model_id, max_tokens_field, prompt_cache_key_field, cache_options_field,
      safety_identifier_field, messages_json, reasoning,
      response_format, extra_suffix)
  end
  if (p.is_custom and p.is_native_custom ~= true)
      or type(Net._protocol_for_provider) ~= "function"
      or type(Net._new_native_seed) ~= "function" then
    return body
  end

  local active_model = MODELS[prefs.model_idx] or MODELS[1]
  local protocol = Net._protocol_for_provider(p, active_model)
  local reasoning_display_mode = Net.reasoning_display_mode()
  local input_json
  local allow_image = p.id == "openai" or p.id == "openrouter"
    or (p.id == "deepseek"
      and Net._model_supports_input(active_model, "image"))
    or (p.is_native_custom == true
      and Net._model_supports_input(active_model, "image"))
  if p.id == "deepseek" then
    local canonical_messages = tbl_concat(deepseek_msg_parts, ",")
    if protocol == "deepseek_responses" then
      local effort = deepseek_thinking_value == "enabled" and "high" or "none"
      input_json = str_format(
        '{"messages":[%s],"reasoning_effort":"%s"}',
        canonical_messages, effort)
    elseif protocol == "deepseek_chat_completions" then
      input_json = str_format(
        '{"messages":[%s],"thinking":{"type":"%s"}}',
        canonical_messages, deepseek_thinking_value or "disabled")
    end
  elseif protocol == "openai_responses" then
    local max_output_field = max_tokens_field:gsub(
      "max_completion_tokens", "max_output_tokens", 1)
    local summary_field = reasoning_display_mode ~= "off"
      and ',"reasoning_summary":"auto"' or ""
    local text_format_field = Net._responses_text_format_field(response_format)
    if text_format_field ~= nil then
      input_json = str_format(
        '{"messages":[%s]%s%s%s%s%s%s%s}', messages_json, reasoning,
        summary_field, max_output_field, safety_identifier_field,
        prompt_cache_key_field, cache_options_field, text_format_field)
    end
  elseif protocol == "openai_chat_completions" and response_format == "" then
    input_json = str_format(
      '{"messages":[%s]%s%s%s%s%s}', messages_json, reasoning,
      max_tokens_field, safety_identifier_field, prompt_cache_key_field,
      cache_options_field)
  elseif protocol == "openrouter_responses" then
    local max_output_field = max_tokens_field:gsub(
      "max_completion_tokens", "max_output_tokens", 1)
    local summary_field = reasoning_display_mode ~= "off"
      and ',"reasoning_summary":"auto"' or ""
    input_json = str_format(
      '{"messages":[%s]%s%s%s}', messages_json, reasoning,
      summary_field, max_output_field)
  elseif protocol == "openrouter_chat_completions" then
    local openrouter_effort, openrouter_exclude =
      Net._openrouter_chat_reasoning_fields(
        reasoning_effort_value, reasoning_display_mode)
    local openrouter_reasoning_fields = ""
    if openrouter_effort ~= nil then
      openrouter_reasoning_fields = str_format(
        ',"reasoning_effort":"%s","reasoning_exclude":%s',
        JSON.escape(openrouter_effort),
        openrouter_exclude and "true" or "false")
    end
    input_json = str_format(
      '{"messages":[%s]%s%s}', messages_json, max_tokens_field,
      openrouter_reasoning_fields)
  end
  local seed_provider = p.is_native_custom == true
    and p.native_provider_id or p.id
  local seed = input_json and Net._new_native_seed(seed_provider, model_id,
    protocol,
    input_json, msg_attachments, allow_image, false, reasoning_display_mode)
    or nil
  return body, seed
end

-- =============================================================================
-- Net.build_body_google
-- =============================================================================
-- Gemini generateContent API format. System prompt as systemInstruction.
-- Messages as contents[]. Role mapping: "assistant" -> "model".
-- Attachments: images and PDFs as inlineData parts, text files inline.
--
-- If a Gemini explicit context cache is active and valid for the current
-- model, the cached content (system_instruction including Custom Instructions
-- + api_ref priming) is referenced via cachedContent and omitted from the live
-- request body.
function Net.build_body_google(msgs, snapshot, msg_attachments)
  local msg_parts = {}
  local canonical_msg_parts = {}
  local request_context_suppressed = Net.request_context_suppressed()
  local engine_cache_handle = (not request_context_suppressed)
    and Net.gemini_explicit_cache_enabled()
    and Net.gemini_cache_engine_is_usable()
    and S.gemini_cache_engine_handle or nil
  -- The first cache release has no combined cache-plus-input-media export.
  -- Preserve the attachment instead of silently changing its representation.
  if engine_cache_handle then
    for _, attachment in ipairs(msg_attachments or {}) do
      if attachment.kind == "image" or attachment.kind == "pdf" then
        engine_cache_handle = nil
        break
      end
    end
  end
  local native_cache_selected = type(engine_cache_handle) == "table"
  local curl_cache_selected = (not request_context_suppressed)
    and Net.gemini_explicit_cache_enabled()
    and not native_cache_selected
    and type(S.gemini_cache_name) == "string"
    and S.gemini_cache_name ~= ""
    and Net.gemini_cache_is_usable()
  local use_cache = native_cache_selected or curl_cache_selected
  S.gemini_cache_last_used = use_cache == true
  S.gemini_cache_last_state =
    Net.gemini_cache_debug_state("body_build", use_cache)
  if request_context_suppressed
     and type(S.gemini_cache_last_state) == "table" then
    S.gemini_cache_last_state.status = "disabled"
    S.gemini_cache_last_state.reason = "request_context_suppressed"
    S.gemini_cache_last_state.used = false
  end

  -- Bundle the long-lived static refs (api_ref + midi_ref + theme_ref) into
  -- ONE pinned user+model exchange instead of three. Fewer turns inside
  -- contents[] is cleaner for Gemini's implicit prefix caching to align on.
  -- When the explicit context cache is active, it already covers
  -- system_instruction (including Custom Instructions when enabled) + api_ref,
  -- so we omit api_ref from the bundle in that case to avoid double-sending it.
  local curl_static_parts = {}
  local native_static_parts = {}
  local static_keys = {}
  local static_blob
  if not request_context_suppressed and S.api_ref_message then
    if not curl_cache_selected then
      curl_static_parts[#curl_static_parts+1] = S.api_ref_message
    end
    if not native_cache_selected then
      native_static_parts[#native_static_parts+1] = S.api_ref_message
    end
  end
  if not request_context_suppressed and S.api_ref_message then
    static_keys[#static_keys+1] = "docs"
  end
  if not request_context_suppressed and S.midi_ref_message then
    curl_static_parts[#curl_static_parts+1] = S.midi_ref_message
    native_static_parts[#native_static_parts+1] = S.midi_ref_message
    static_keys[#static_keys+1] = "midi"
  end
  if not request_context_suppressed and S.theme_ref_message then
    curl_static_parts[#curl_static_parts+1] = S.theme_ref_message
    native_static_parts[#native_static_parts+1] = S.theme_ref_message
    static_keys[#static_keys+1] = "theme"
  end
  -- Gemini used to omit the static-reference manifest because this builder
  -- manually assembled the reference blob instead of using
  -- Net.bundled_static_refs(). That made correctly pinned docs invisible to
  -- the model and caused redundant <context_needed> requests. Keep the
  -- manifest live even when docs themselves reside in an explicit Gemini
  -- cache; cached content is not otherwise self-advertising to the model.
  if not request_context_suppressed and #static_keys > 0 then
    local manifest =
      "PINNED REFERENCES (already provided above; do NOT re-request via "
      .. "<context_needed>): " .. tbl_concat(static_keys, ", ")
    curl_static_parts[#curl_static_parts+1] = manifest
    native_static_parts[#native_static_parts+1] = manifest
  end
  if #curl_static_parts > 0 then
    local curl_static_blob = tbl_concat(curl_static_parts, "\n\n")
    msg_parts[#msg_parts+1] = str_format(
      '{"role":"user","parts":[{"text":"%s"}]}',
      JSON.escape(curl_static_blob))
    msg_parts[#msg_parts+1] = '{"role":"model","parts":[{"text":"Understood."}]}'
  end
  if #native_static_parts > 0 then
    static_blob = tbl_concat(native_static_parts, "\n\n")
    canonical_msg_parts[#canonical_msg_parts+1] = str_format(
      '{"role":"user","parts":[{"type":"text","text":"%s"}]}',
      JSON.escape(static_blob))
    canonical_msg_parts[#canonical_msg_parts+1] =
      '{"role":"model","parts":[{"type":"text","text":"Understood."}]}'
  end

  -- Prepend pinned sticky context (plugin_ref / pref_plugins / fx_params /
  -- fx_inspect) as a user+model exchange. Sits in a stable prefix position
  -- so Gemini's implicit caching (and explicit cache if it covers here) can
  -- match it across turns. See Net.sticky_text(). Deliberately NOT included
  -- in the Gemini explicit cache (that stays scoped to api_ref only), so
  -- sticky growth doesn't force cache recreation.
  local sticky_blob = not request_context_suppressed and Net.sticky_text()
  if sticky_blob then
    msg_parts[#msg_parts+1] = str_format(
      '{"role":"user","parts":[{"text":"%s"}]}', JSON.escape(sticky_blob))
    msg_parts[#msg_parts+1] = '{"role":"model","parts":[{"text":"Understood."}]}'
    canonical_msg_parts[#canonical_msg_parts+1] = str_format(
      '{"role":"user","parts":[{"type":"text","text":"%s"}]}',
      JSON.escape(sticky_blob))
    canonical_msg_parts[#canonical_msg_parts+1] =
      '{"role":"model","parts":[{"type":"text","text":"Understood."}]}'
  end

  for idx, m in ipairs(msgs) do
    local is_last_user = (m.role == "user" and idx == #msgs)
    -- Gemini uses "model" instead of "assistant".
    local role = (m.role == "assistant") and "model" or m.role

    if is_last_user then
      local parts = {}
      local canonical_parts = {}
      parts[#parts+1] = str_format('{"text":"%s"}', JSON.escape(m.content))
      canonical_parts[#canonical_parts+1] = str_format(
        '{"type":"text","text":"%s"}', JSON.escape(m.content))
      if snapshot and not request_context_suppressed then
        parts[#parts+1] = str_format('{"text":"%s"}', JSON.escape(snapshot))
        canonical_parts[#canonical_parts+1] = str_format(
          '{"type":"text","text":"%s"}', JSON.escape(snapshot))
      end
      if msg_attachments then
        for _, att in ipairs(msg_attachments) do
          if att.kind == "image" then
            local media_index = Attach.native_media_index(msg_attachments, att)
            if media_index ~= nil then
              local placeholder = str_format(
                '{"type":"input_media","index":%d}', media_index)
              parts[#parts+1] = placeholder
              canonical_parts[#canonical_parts+1] = placeholder
            else
              parts[#parts+1] = str_format(
                '{"inlineData":{"mimeType":"%s","data":"%s"}}',
                JSON.escape(att.media_type), att.b64)
              canonical_parts[#canonical_parts+1] = str_format(
                '{"type":"inline_data","mime_type":"%s","data":"%s"}',
                JSON.escape(att.media_type), att.b64)
            end
          elseif att.kind == "pdf" then
            parts[#parts+1] = str_format(
              '{"inlineData":{"mimeType":"application/pdf","data":"%s"}}',
              att.b64)
            canonical_parts[#canonical_parts+1] = str_format(
              '{"type":"inline_data","mime_type":"application/pdf","data":"%s"}',
              att.b64)
          elseif att.kind == "text" then
            parts[#parts+1] = str_format(
              '{"text":"[Attached file: %s]\\n%s"}',
              JSON.escape(att.name), JSON.escape(att.data))
            canonical_parts[#canonical_parts+1] = str_format(
              '{"type":"text","text":"[Attached file: %s]\\n%s"}',
              JSON.escape(att.name), JSON.escape(att.data))
          end
        end
      end
      msg_parts[#msg_parts+1] = str_format(
        '{"role":"user","parts":[%s]}', tbl_concat(parts, ","))
      canonical_msg_parts[#canonical_msg_parts+1] = str_format(
        '{"role":"user","parts":[%s]}', tbl_concat(canonical_parts, ","))
    else
      msg_parts[#msg_parts+1] = str_format(
        '{"role":"%s","parts":[{"text":"%s"}]}', role, JSON.escape(m.content))
      canonical_msg_parts[#canonical_msg_parts+1] = str_format(
        '{"role":"%s","parts":[{"type":"text","text":"%s"}]}',
        role, JSON.escape(m.content))
    end
  end

  local thinking = ""
  local native_thinking_level
  local native_include_thoughts
  -- S.thinking_override_idx (when set) wins over prefs.thinking_idx -- the
  -- length auto-retry path uses this to force "none" for one round-trip
  -- when reasoning consumed the entire output budget on the first attempt.
  local effective_thinking_idx = S.thinking_override_idx or prefs.thinking_idx
  if effective_thinking_idx > 0 then
    local p = PROVIDERS.active()
    local m = MODELS[prefs.model_idx] or MODELS[1]
    if p.thinking_levels then
      -- Normalize overrides and stale saved choices to the model's supported
      -- range before constructing the request.
      local tidx = PROVIDERS.normalize_thinking_idx(
        p, m, effective_thinking_idx)
      local tl = p.thinking_levels[tidx]
      if tl then
        local include_thoughts = prefs.show_reasoning_summaries == true
          and not S.screen_reader_mode and "true" or "false"
        native_thinking_level = tl.value
        native_include_thoughts = include_thoughts
        thinking = str_format(
          ',"thinkingConfig":{"thinkingLevel":"%s","includeThoughts":%s}',
          tl.value, include_thoughts)
      end
    end
  end
  -- maxOutputTokens: optional in Gemini's generationConfig. Omit it so the
  -- server applies its own per-model ceiling (~64K on Gemini 3.x). Same
  -- rationale as the OpenAI path: a fixed cap can be entirely consumed by
  -- thinking tokens, leaving zero visible output. Letting the server cap
  -- naturally avoids that failure mode.
  if curl_cache_selected then
    -- system_instruction lives inside the cache; omit it from the live body.
    return str_format(
      '{"contents":[%s],"cachedContent":"%s","generationConfig":{%s}}',
      tbl_concat(msg_parts, ","), S.gemini_cache_name,
      thinking:gsub("^,", ""))
  end
  local messages_json = tbl_concat(msg_parts, ",")
  local body = str_format(
    '{"contents":[%s],"systemInstruction":{"parts":[{"text":"%s"}]},"generationConfig":{%s}}',
    messages_json, JSON.escape(Net.system_prompt_text()),
    thinking:gsub("^,", ""))
  if type(Net._protocol_for_provider) ~= "function"
      or type(Net._new_native_seed) ~= "function" then
    return body
  end
  local active_model = MODELS[prefs.model_idx] or MODELS[1]
  local protocol = Net._protocol_for_provider(PROVIDERS.active(), active_model)
  local canonical_thinking = ""
  if native_thinking_level and native_include_thoughts then
    canonical_thinking = str_format(
      ',"thinking_config":{"thinking_level":"%s","include_thoughts":%s}',
      JSON.escape(native_thinking_level), native_include_thoughts)
  end
  local system_instruction = Net.system_prompt_text()
  local generate_content_input_json
  if native_cache_selected then
    generate_content_input_json = str_format(
      '{"contents":[%s]%s}',
      tbl_concat(canonical_msg_parts, ","), canonical_thinking)
  else
    generate_content_input_json = str_format(
      '{"contents":[%s],"system_instruction":"%s"%s}',
      tbl_concat(canonical_msg_parts, ","),
      JSON.escape(system_instruction), canonical_thinking)
  end
  local reasoning_mode = Net.reasoning_display_mode()
  local interaction_attachments_ok = true
  for _, attachment in ipairs(msg_attachments or {}) do
    if attachment.kind == "image" or attachment.kind == "pdf" then
      interaction_attachments_ok = false
      break
    end
  end
  local current = msgs[#msgs]
  local conversation = S.google_interactions_conversation
  local may_open = conversation == nil and #msgs == 1
  local interactions_engine_available = false
  if type(Engine) == "table"
      and type(Engine.protocol_available) == "function" then
    local ok_available, available = pcall(
      Engine.protocol_available, "google_interactions")
    interactions_engine_available = ok_available and available == true
  end
  local interactions_preeligible = active_model.interactions_v1 == true
    and interactions_engine_available
    and not use_cache and not request_context_suppressed
    and S.history_trim_start == nil
    and interaction_attachments_ok
    and type(current) == "table" and current.role == "user"
    and type(current.content) == "string"
    and (may_open or (type(conversation) == "table"
      and conversation.closed ~= true
      and conversation.model == active_model.id))
  local base_history_revision
  local context_revision
  local conversation_matches = false
  if interactions_preeligible then
    base_history_revision = Net._google_interactions_cached_history_revision(
      conversation, msgs, #msgs - 1)
      or Net._google_interactions_history_revision(msgs, #msgs - 1)
    context_revision = Net._google_interactions_context_revision(
      system_instruction, static_blob)
    conversation_matches = type(conversation) == "table"
      and conversation.context_revision == context_revision
      and conversation.history_revision == base_history_revision
  end
  local interactions_eligible = interactions_preeligible
    and base_history_revision ~= nil and context_revision ~= nil
    and (conversation_matches or may_open)
  local seed
  if interactions_eligible then
    local interaction_parts = {}
    if may_open and static_blob then
      interaction_parts[#interaction_parts + 1] = str_format(
        '{"type":"text","text":"%s"}', JSON.escape(static_blob))
    end
    if sticky_blob then
      interaction_parts[#interaction_parts + 1] = str_format(
        '{"type":"text","text":"%s"}', JSON.escape(sticky_blob))
    end
    interaction_parts[#interaction_parts + 1] = str_format(
      '{"type":"text","text":"%s"}', JSON.escape(current.content))
    if snapshot then
      interaction_parts[#interaction_parts + 1] = str_format(
        '{"type":"text","text":"%s"}', JSON.escape(snapshot))
    end
    for _, attachment in ipairs(msg_attachments or {}) do
      if attachment.kind == "text" then
        interaction_parts[#interaction_parts + 1] = str_format(
          '{"type":"text","text":"[Attached file: %s]\\n%s"}',
          JSON.escape(attachment.name), JSON.escape(attachment.data))
      end
    end
    local generation_fields = {}
    local interaction_thinking_level =
      Net._google_interactions_thinking_level(native_thinking_level)
    if interaction_thinking_level then
      generation_fields[#generation_fields + 1] = str_format(
        '"thinking_level":"%s"', JSON.escape(interaction_thinking_level))
    end
    if reasoning_mode ~= "off" then
      generation_fields[#generation_fields + 1] = '"thinking_summaries":"auto"'
    end
    local generation_json = #generation_fields > 0
      and ',"generation_config":{' .. tbl_concat(generation_fields, ",") .. '}'
      or ""
    local interaction_input_json = str_format(
      '{"input":[{"type":"user_input","content":[%s]}],'
        .. '"system_instruction":"%s"%s}',
      tbl_concat(interaction_parts, ","),
      JSON.escape(system_instruction), generation_json)
    protocol = "google_interactions"
    seed = Net._new_native_seed("google", active_model.id, protocol,
      interaction_input_json, msg_attachments, false, false, reasoning_mode, {
        context_revision = context_revision,
        history_revision = base_history_revision,
        initial = may_open,
      })
  else
    if type(conversation) == "table" then
      Net._close_google_interactions_conversation()
    end
    seed = Net._new_native_seed("google", active_model.id, protocol,
      generate_content_input_json, msg_attachments, true, true, reasoning_mode,
      nil, native_cache_selected and {
        handle = engine_cache_handle,
        binding = {
          provider = engine_cache_handle.binding.provider,
          protocol = engine_cache_handle.binding.protocol,
          api_version = engine_cache_handle.binding.api_version,
          model = engine_cache_handle.binding.model,
          adapter_contract_revision =
            engine_cache_handle.binding.adapter_contract_revision,
          source_revision = engine_cache_handle.binding.source_revision,
          context_revision = engine_cache_handle.binding.context_revision,
        },
      } or nil)
  end
  return body, seed
end

-- =============================================================================
-- Net.trimmed_history
-- =============================================================================
-- Returns the last CFG.MAX_HISTORY_TURNS entries from S.history for the API call.
-- The full S.history table is preserved for display; only the slice is sent.
-- If the first entry in the slice is an assistant message (possible if an
-- odd number of entries were removed mid-conversation), it is dropped so
-- the API always receives a conversation starting with a user turn.
function Net.trimmed_history()
  local hist
  if #S.history <= CFG.MAX_HISTORY_TURNS then
    S.history_trim_start = nil
    hist = S.history
  else
    hist = {}
    local start = tonumber(S.history_trim_start)
    if not start or start < 1 or start > #S.history
       or (#S.history - start + 1) > CFG.MAX_HISTORY_TURNS then
      local hysteresis = math_floor(
        tonumber(CFG.HISTORY_TRIM_HYSTERESIS) or 0)
      if hysteresis < 0 then hysteresis = 0 end
      if hysteresis >= CFG.MAX_HISTORY_TURNS then hysteresis = 0 end
      local keep = CFG.MAX_HISTORY_TURNS - hysteresis
      if keep < 1 then keep = CFG.MAX_HISTORY_TURNS end
      start = #S.history - keep + 1
      if start < 1 then start = 1 end
      if S.history[start]
         and S.history[start].role == "assistant"
         and start < #S.history then
        start = start + 1
      end
      S.history_trim_start = start
    end
    for i = start, #S.history do
      hist[#hist+1] = S.history[i]
    end
    if #hist > 0 and hist[1].role == "assistant" then
      tbl_remove(hist, 1)
    end
    if #hist == 0 then
      -- Slice was a single assistant entry that we just dropped. Return
      -- just the most recent message rather than falling back to the
      -- FULL untrimmed S.history (latent overshoot of the trim budget;
      -- only triggerable at very low MAX_HISTORY_TURNS, but the previous
      -- behaviour silently sent every prior turn, defeating the trim).
      hist = { S.history[#S.history] }
    end
  end
  return hist
end

-- =============================================================================
-- Net.fire_curl
-- =============================================================================
-- Writes the JSON body to a temp file and launches curl asynchronously.
-- Provider-aware: builds the endpoint URL, auth headers, and extra headers
-- dynamically from the active PROVIDERS entry.
--
-- Auth strategies:
--   header      (Claude, OpenAI, Gemini): key sent via -H @file so it never
--               appears on the command line. The auth file is cleaned up after
--               curl. Each provider specifies its own auth_header name.
--
-- Both platforms use an async pattern: curl runs in the background, writes
-- its response to tmp.out, stderr to tmp.err, and echoes its exit code to tmp.exit.
-- Net.try_finish_curl() polls both files each frame to detect completion.
--
-- Windows: the curl command is inlined directly into a PowerShell -Command
--   string launched via Start-Process -WindowStyle Hidden.
-- macOS/Linux: trailing "&" backgrounds the shell pipeline.
-- opts (optional table) lets the caller request a non-standard request shape:
--   opts.method            -- "GET" to send an empty GET instead of POST
--   opts.endpoint_override -- full URL to use instead of the provider's endpoint
-- Both are used by the custom-LLM connection test, which hits GET /v1/models
-- so no inference runs on the server. When method=="GET" we skip the body
-- write, the content-type header, and the -d flag; nil/POST behaves as before.
-- Restore the trailing user-history entry from S.pending_orig_prompt,
-- shedding any sticky-bucket / internal-retry-note content that was baked
-- in mid-turn. Mirrors the success-path cleanup in Net._drop_pending_history_rows;
-- centralised so the per-turn-call-cap abort path can reuse the same
-- semantics without leaving an internal note as the user's last turn.
function Net._restore_pending_user_history()
  if not S.pending_orig_prompt or not S.history or #S.history == 0 then return end
  local restored = "USER REQUEST:\n" .. S.pending_orig_prompt
  local tail = S.history[#S.history]
  if tail and tail.role == "user" then
    tail.content = restored
    return
  end
  local prev = S.history[#S.history - 1]
  if tail and tail.role == "assistant"
     and prev and prev.role == "user" then
    prev.content = restored
  end
end

-- A validator-cap streak is consecutive only while every completed turn ends
-- at that same cap. Any success, cancellation, unrelated guardrail, or ordinary
-- error breaks the streak before the next user turn begins.
function Net._finish_probe_turn(probe_turn, reason)
  if reason ~= "validator_retry_cap" then
    S.validator_retry_cap_streak = 0
  end
  if probe_turn then Probe.end_turn(probe_turn, reason) end
  if S.probe_turn == probe_turn then S.probe_turn = nil end
end

-- Retry prompts sometimes fire on terse follow-ups ("1", "yes", "use built
-- in", "snap them"), where S.pending_orig_prompt alone is not enough context.
-- Expand those into a compact task-context block so hidden validator retries
-- don't make the model reconstruct the user's real intent from luck.
function Net._retry_trim_text(text)
  return tostring(text or "")
    :gsub("\r\n", "\n")
    :gsub("^%s+", "")
    :gsub("%s+$", "")
end

function Net._retry_extract_user_request(content)
  local text = tostring(content or "")
  if text:find("INTERNAL NOTE TO THE MODEL", 1, true) then return "" end
  local marker, last = "USER REQUEST:", nil
  local pos = 1
  while true do
    local s, e = text:find(marker, pos, true)
    if not s then break end
    last = e + 1
    pos = e + 1
  end
  if last then text = text:sub(last) end
  return Net._retry_trim_text(text)
end

function Net._retry_prompt_needs_context(text)
  local t = Net._retry_trim_text(text)
  local lo = t:lower()
  if lo == "" then return false end
  if #lo <= 24 then return true end
  if lo:match("^%d+[%.)]?$") then return true end
  if lo:find("%f[%w]option%f[%W]") then return true end
  if lo:find("%f[%w]same%f[%W]") then return true end
  if lo:find("%f[%w]previous%f[%W]") then return true end
  if lo:find("%f[%w]last%f[%W]") then return true end
  if lo:find("%f[%w]that%f[%W]") then return true end
  if lo:find("%f[%w]this%f[%W]") then return true end
  if lo:find("%f[%w]them%f[%W]") then return true end
  if lo:find("%f[%w]those%f[%W]") then return true end
  if lo:find("built in", 1, true) or lo:find("built%-in") then return true end
  return false
end

function Net._retry_request_is_substantive(text, current)
  local t = Net._retry_trim_text(text)
  if t == "" or t == current then return false end
  if #t <= 12 then return false end
  if t:match("^[%d%p%s]+$") then return false end
  return true
end

function Net.retry_user_request_context()
  local current = Net._retry_trim_text(S.pending_orig_prompt or "")
  if not Net._retry_prompt_needs_context(current) then return current end
  local prior_rev = {}
  for i = #S.history, 1, -1 do
    local row = S.history[i]
    if row and row.role == "user" then
      local req = Net._retry_extract_user_request(row.content)
      if Net._retry_request_is_substantive(req, current) then
        prior_rev[#prior_rev + 1] = req
        if #prior_rev >= 2 then break end
      end
    end
  end
  if #prior_rev == 0 then return current end
  local prior = {}
  for i = #prior_rev, 1, -1 do
    local req = prior_rev[i]
    if #req > 700 then req = req:sub(1, 697) .. "..." end
    prior[#prior + 1] = req
  end
  return "Prior task context:\n" .. tbl_concat(prior, "\n\n")
    .. "\n\nLatest user reply / option selection:\n" .. current
end

-- Preserve substantive requirements that fell outside the sliding history
-- window. The block is attached only while a provider body is serialized and
-- is removed immediately afterward by Net.build_body. This keeps S.history
-- byte-exact for display, caching, retries, and later turns.
function Net._task_context_normalize(text)
  local normalized = sanitize_utf8(tostring(text or ""))
    :gsub("\r\n", "\n")
    :gsub("\r", "\n")
    :gsub("%s+", " ")
    :gsub("^%s+", "")
    :gsub("%s+$", "")
  return normalized
end

function Net._task_context_utf8_prefix(text, max_bytes)
  text = sanitize_utf8(tostring(text or ""))
  max_bytes = math_max(0, math_floor(tonumber(max_bytes) or 0))
  if #text <= max_bytes then return text end
  local cut = max_bytes
  while cut > 0 do
    local next_byte = str_byte(text, cut + 1)
    if not next_byte or next_byte < 128 or next_byte > 191 then break end
    cut = cut - 1
  end
  return text:sub(1, cut)
end

function Net._task_context_utf8_suffix(text, max_bytes)
  text = sanitize_utf8(tostring(text or ""))
  max_bytes = math_max(0, math_floor(tonumber(max_bytes) or 0))
  if #text <= max_bytes then return text end
  local first = #text - max_bytes + 1
  while first <= #text do
    local first_byte = str_byte(text, first)
    if not first_byte or first_byte < 128 or first_byte > 191 then break end
    first = first + 1
  end
  return text:sub(first)
end

function Net._task_context_middle_clip(text, max_bytes)
  text = Net._task_context_normalize(text)
  max_bytes = math_max(0, math_floor(tonumber(max_bytes) or 0))
  if #text <= max_bytes then return text, false end
  local marker = " [...] "
  if max_bytes <= #marker + 2 then
    return Net._task_context_utf8_prefix(text, max_bytes), true
  end
  local usable = max_bytes - #marker
  local left = math_floor(usable / 2)
  local right = usable - left
  return Net._task_context_utf8_prefix(text, left)
    .. marker .. Net._task_context_utf8_suffix(text, right), true
end

function Net._task_context_empty_meta()
  return {
    bytes = 0,
    source_requests = 0,
    included_requests = 0,
    shortened_requests = 0,
    elided_requests = 0,
  }
end

function Net._task_context_skip_current_turn()
  if Net.request_context_suppressed() or S.pending_starter_card_key then
    return true
  end
  return type(Code) == "table"
    and type(Code.prompt_requests_reusable_action_script) == "function"
    and Code.prompt_requests_reusable_action_script(
      S.pending_orig_prompt or "") == true
end

function Net.task_context_build(msgs)
  local meta = Net._task_context_empty_meta()
  if type(msgs) ~= "table" or #msgs == 0
     or type(S.history) ~= "table" or #S.history == 0
     or Net._task_context_skip_current_turn() then
    return nil, meta
  end

  local first_history_index
  for i, row in ipairs(S.history) do
    if row == msgs[1] then
      first_history_index = i
      break
    end
  end
  if not first_history_index or first_history_index <= 1 then
    return nil, meta
  end

  local seen = {}
  for _, row in ipairs(msgs) do
    if row and row.role == "user" then
      local request = Net._task_context_normalize(
        Net._retry_extract_user_request(row.content))
      if request ~= "" then seen[request:lower()] = true end
    end
  end

  local omitted = {}
  for i = 1, first_history_index - 1 do
    local row = S.history[i]
    if row and row.role == "user" then
      local request = Net._task_context_normalize(
        Net._retry_extract_user_request(row.content))
      local key = request:lower()
      if Net._retry_request_is_substantive(request, "") and not seen[key] then
        seen[key] = true
        omitted[#omitted + 1] = request
      end
    end
  end
  meta.source_requests = #omitted
  if #omitted == 0 then return nil, meta end

  local selected = {}
  local selected_indexes = {}
  -- Limit eligibility to recent omitted requests so requirements from a
  -- completed task do not remain pinned throughout an unrelated long chat.
  local recent_limit = math_max(5,
    math_floor(tonumber(CFG.TASK_CONTEXT_RECENT_REQUESTS) or 10))
  local eligible_start = math_max(1, #omitted - recent_limit + 1)
  local function select_index(index)
    if index >= eligible_start and index <= #omitted
       and not selected_indexes[index] then
      selected_indexes[index] = true
      selected[#selected + 1] = { index = index, text = omitted[index] }
    end
  end
  select_index(eligible_start)
  select_index(eligible_start + 1)
  select_index(#omitted - 2)
  select_index(#omitted - 1)
  select_index(#omitted)
  table.sort(selected, function(a, b) return a.index < b.index end)

  local header = "CUMULATIVE TASK CONTEXT (earlier user messages from trimmed history):\n"
  local rule = "\nLater included user requests override conflicting older requirements. "
    .. "These messages can include reports of incorrect results, not just instructions. "
    .. "A reported actual value does not replace the requested target. "
    .. "For example, 'The decay is 5.7 seconds, not 3' reports a failed 3-second target; "
    .. "'Now it is 70 seconds' does not request 70 seconds or 70 percent mix."
  local function assemble()
    local lines = { header }
    for _, item in ipairs(selected) do
      lines[#lines + 1] = "- " .. item.text .. "\n"
    end
    local elided = #omitted - #selected
    lines[#lines + 1] = rule
    if elided > 0 then
      lines[#lines + 1] = " " .. tostring(elided)
        .. " additional unique older request"
        .. (elided == 1 and " was" or "s were") .. " elided."
    end
    return tbl_concat(lines)
  end

  local max_bytes = math_max(256,
    math_floor(tonumber(CFG.TASK_CONTEXT_MAX_BYTES) or 2048))
  local block = assemble()
  while #block > max_bytes and #selected > 0 do
    local longest_index, longest_bytes = nil, 0
    for i, item in ipairs(selected) do
      if #item.text > longest_bytes and #item.text > 128 then
        longest_index, longest_bytes = i, #item.text
      end
    end
    if not longest_index then break end
    local excess = #block - max_bytes
    local target = math_max(128, longest_bytes - math_max(excess, 16))
    local clipped, did_clip = Net._task_context_middle_clip(
      selected[longest_index].text, target)
    selected[longest_index].text = clipped
    if did_clip then selected[longest_index].shortened = true end
    block = assemble()
  end
  while #block > max_bytes and #selected > 1 do
    table.remove(selected, math_floor((#selected + 1) / 2))
    block = assemble()
  end
  if #block > max_bytes then
    block = Net._task_context_utf8_prefix(block, max_bytes)
  end

  meta.bytes = #block
  meta.included_requests = #selected
  meta.elided_requests = #omitted - #selected
  for _, item in ipairs(selected) do
    if item.shortened then
      meta.shortened_requests = meta.shortened_requests + 1
    end
  end
  return block, meta
end

function Net.task_context_inject_for_build(msgs)
  local block, meta = Net.task_context_build(msgs)
  if not block then return nil, nil, meta end
  local moving_row
  for i = #msgs, 1, -1 do
    if msgs[i] and msgs[i].role == "user" then
      moving_row = msgs[i]
      break
    end
  end
  if not moving_row or type(moving_row.content) ~= "string" then
    return nil, nil, Net._task_context_empty_meta()
  end
  local marker = "USER REQUEST:"
  local search_at, marker_start = 1, nil
  while true do
    local found = moving_row.content:find(marker, search_at, true)
    if not found then break end
    marker_start = found
    search_at = found + #marker
  end
  if not marker_start then return nil, nil, Net._task_context_empty_meta() end
  local original = moving_row.content
  moving_row.content = original:sub(1, marker_start - 1)
    .. block .. "\n\n" .. original:sub(marker_start)
  return moving_row, original, meta
end

function Net.midi_input_findings_are_arm_only(kinds)
  local only_invalid_arm = type(kinds) == "table" and #kinds > 0
  for _, kind in ipairs(kinds or {}) do
    if kind ~= "invalid_record_arm_property" then
      only_invalid_arm = false
      break
    end
  end
  return only_invalid_arm
end

function Net.midi_input_retry_uses_arm_only_guidance(user_text, kinds)
  if not Net.midi_input_findings_are_arm_only(kinds) then return false end
  local requests_device_filter =
    type(Code.prompt_requests_midi_input_device_filter) == "function"
      and Code.prompt_requests_midi_input_device_filter(user_text or "")
  return not requests_device_filter
end

function Net.midi_input_retry_guidance(user_text, kinds)
  if Net.midi_input_retry_uses_arm_only_guidance(user_text, kinds) then
    return "Your previous Lua used `B_RECARM`, which is not a valid "
      .. "REAPER track property. Use `I_RECARM` for track record arming "
      .. "for either audio or MIDI, while preserving the recording input "
      .. "and mode the user actually requested. Do not infer or add MIDI "
      .. "input-routing behavior unless the user asked for it."
  end
  return "The user asked for a MIDI record-input/arming setup. "
    .. "Your previous Lua used an unsupported/incomplete shape: "
    .. tbl_concat(kinds or {}, ", ") .. ". REAPER track I_RECINPUT can "
    .. "select one physical MIDI input or all physical MIDI inputs. "
    .. "It cannot represent all MIDI devices except X as one track "
    .. "input. Do NOT use P_MIDI_MAP, a comma-separated device map, "
    .. "or 4096+256. For one named physical device, enumerate "
    .. "reaper.GetMIDIInputName and match the device NAME "
    .. "case-insensitively with substring tolerance, then set "
    .. "I_RECINPUT = 4096 + (device_index * 32) + channel, where "
    .. "channel is an integer 0..16, and channel 0 means all "
    .. "channels. Arm a track with I_RECARM, never B_RECARM. Set "
    .. "I_RECINPUT and I_RECMON first, then I_RECARM last. For an "
    .. "all-except request, either create helper "
    .. "input tracks for the allowed device names and route their "
    .. "MIDI to the target track, or explain that the direct "
    .. "single-track all-except setting is not scriptable and offer "
    .. "that helper-track workaround. If you create helper tracks, "
    .. "skip devices by NAME match every run, not by hard-coded "
    .. "index, because REAPER device indexes can change after "
    .. "hot-plug or restart."
end

function Net.midi_input_block_copy(kinds, semantic_only)
  local arm_only = Net.midi_input_findings_are_arm_only(kinds)
  local block_kind = arm_only and "record_arm_property_validator"
    or "midi_input_validator"
  local error_kind = semantic_only and "semantic_incomplete"
    or "validator_blocked"
  local meta = {
    failure_kind = error_kind,
    source = arm_only and "record_arm_property_validator"
      or "midi_input_device_filter_validator",
    validation_block_kind = block_kind,
    run_status = semantic_only and "semantic_incomplete"
      or (arm_only and "blocked_record_arm_property_validator"
        or "blocked_midi_input_validator"),
    validation_status = "blocked",
    error_kind = error_kind,
    log_source = arm_only and "RECORD-ARM-VALIDATOR"
      or "MIDI-INPUT-VALIDATOR",
    log_label = arm_only and "record-arm property issue"
      or "MIDI input filtering issue",
  }
  if arm_only then
    return "validator.record_arm_property_blocked",
      "The script still uses `B_RECARM` after an automatic correction "
        .. "attempt. `B_RECARM` is not a valid REAPER track property, so "
        .. "auto-run is blocked. Use `I_RECARM` for track record arming "
        .. "while preserving the requested audio or MIDI input and mode.",
      meta
  end
  return "validator.midi_input_filter_blocked",
    "The script does not safely implement the requested MIDI input-device "
      .. "filter. REAPER cannot encode 'all MIDI devices except one named "
      .. "device' as a single track I_RECINPUT value, and the generated Lua "
      .. "still uses an unsupported map or only lists devices. Auto-run is "
      .. "blocked; use a name-matched helper-track workaround or set a "
      .. "single named input directly.",
    meta
end

function Net.midi_record_mode_retry_guidance(findings)
  local modes = {}
  for _, finding in ipairs(findings or {}) do
    modes[#modes + 1] = tostring(finding.mode or "?")
      .. " (" .. tostring(finding.mode_label or "output mode") .. ")"
  end
  return "Your previous Lua assigns an output-recording I_RECMODE value "
    .. "inside a MIDI recording workflow: " .. tbl_concat(modes, ", ")
    .. ". Use the user's requested record behavior. The exact I_RECMODE "
    .. "values are 0=input, 1=stereo output, 2=none, 3=stereo output "
    .. "with latency compensation, 4=MIDI output, 5=mono output, 6=mono "
    .. "output with latency compensation, 7=MIDI overdub, and 8=MIDI "
    .. "replace. Preserve the requested input, monitoring, arming, and "
    .. "track targeting. Respond as if this is your FIRST reply. Do not "
    .. "mention a retry or this internal note."
end

function Net.midi_record_mode_review_copy(findings)
  local modes = {}
  for _, finding in ipairs(findings or {}) do
    modes[#modes + 1] = tostring(finding.mode or "?")
      .. " (" .. tostring(finding.mode_label or "output mode") .. ")"
  end
  local fallback = "The script still assigns an output-recording I_RECMODE "
    .. "value to a MIDI recording workflow after an automatic correction "
    .. "attempt: " .. tbl_concat(modes, ", ") .. ". Automatic execution "
    .. "is paused because that mode can record track output instead of the "
    .. "requested MIDI behavior. Review the code before using Run. MIDI "
    .. "overdub is 7 and MIDI replace is 8."
  return "validator.midi_record_mode_review", fallback, {
    failure_kind = "semantic_review",
    source = "midi_record_mode_validator",
    validation_block_kind = "midi_record_mode_review",
    run_status = "manual_run",
    validation_status = "manual_required",
    error_kind = "semantic_unsafe",
    log_source = "MIDI-RECORD-MODE-VALIDATOR",
  }
end

-- Referential numbered option selections (for example "option 3" or a
-- short non-English equivalent) do not contain enough standalone grounding
-- to prove that an FX in the candidate is unrelated. If unrequested_plugin is
-- the only retryable relevance finding, preserve the candidate for manual
-- review instead of silently asking the model to remove the FX. This is a
-- conservative execution policy only: it never authorizes or auto-runs the
-- plugin, and other relevance findings keep their existing retry behavior.
-- Language-neutral evidence that an assistant turn presented a numbered
-- option list: two or more lines that begin with an enumerator (optional
-- '#', digits, then '.', ')', or ':'). ReaAssist does not impose a custom
-- options format, so the model renders ordered choices as ordinary markdown
-- ("1. ...", "2) ...", "3: ..."), which this matches without depending on any
-- language. Two lines is the minimum that reads as a list rather than a
-- stray numbered sentence.
function Net._text_has_numbered_option_list(text)
  if type(text) ~= "string" or text == "" then return false end
  local matches = 0
  for line in text:gmatch("[^\r\n]+") do
    if line:match("^%s*#?%d+[%.%)%:]") then
      matches = matches + 1
      if matches >= 2 then return true end
    end
  end
  return false
end

function Net._is_short_numbered_selection(text, prior_assistant_text)
  local t = Net._retry_trim_text(text)
  if t == "" or t:find("\n", 1, true) then return false end
  local token_count, number_count, number_pos = 0, 0, nil
  for token in t:gmatch("%S+") do
    token_count = token_count + 1
    if token_count > 5 then return false end
    local cleaned = token
      :gsub("^[#%(%)%[%]{}]+", "")
      :gsub("[%(%)%[%]{}%.,:;!?]+$", "")
    if cleaned:match("^%d+$") then
      number_count = number_count + 1
      if number_count > 1 then return false end
      number_pos = token_count
    end
  end
  if number_count ~= 1 then return false end
  -- Base rule (no context): a genuine numbered-option pick ends at the
  -- number, whether bare ("3"), wrapped ("#3", "option 3"), or in another
  -- language ("давай завдання 3"). Anchoring on the number's position rather
  -- than an English keyword keeps this language-neutral, and it fails safe:
  -- "mute track 3" still classifies (ends at the number), which only routes
  -- to manual review and never widens auto-run.
  if number_pos == token_count then return true end
  -- Politeness suffixes leave the number non-final ("option 3 please",
  -- "3, please"). Number-final alone would misread those as imperatives and
  -- re-enable the silent unrequested-plugin repair, which strips FX not named
  -- in the current turn and can undo the user's actual option pick -- the
  -- exact regression commit 11f4079 guards against. So accept a non-final
  -- single integer ONLY when the previous assistant turn actually presented a
  -- numbered option list. Tradeoff: with that context present, a short
  -- imperative like "lower it by 3 db" also classifies and falls into manual
  -- review (fail-safe, acceptable); without context, the number-final rule
  -- governs and that imperative retries normally.
  return Net._text_has_numbered_option_list(prior_assistant_text)
end

function Net._action_relevance_retry_policy(findings, user_text,
    prior_assistant_text)
  local retryable_count, only_unrequested_plugin = 0, true
  for _, finding in ipairs(findings or {}) do
    if type(finding) == "table" and finding.review_only ~= true then
      retryable_count = retryable_count + 1
      if finding.kind ~= "unrequested_plugin" then
        only_unrequested_plugin = false
      end
    end
  end
  if retryable_count == 0 then return false, nil end
  if only_unrequested_plugin
     and Net._is_short_numbered_selection(user_text, prior_assistant_text) then
    return false, "referential_unrequested_plugin"
  end
  return true, nil
end

function Net._action_relevance_block_message(findings, snapshot)
  for _, finding in ipairs(findings or {}) do
    if type(finding) == "table"
        and finding.kind == "missing_requested_fx_param_write" then
      local fallback = "Auto-run was blocked because the plug-in was added "
        .. "without applying another requested value. Review the generated "
        .. "action and resend the request. Do not run the blocked script "
        .. "manually."
      return (RA and RA.t and RA.t(
        "auto_run.blocked.missing_fx_parameter_write", nil, fallback))
        or fallback
    end
  end
  for _, finding in ipairs(findings or {}) do
    if type(finding) == "table"
        and finding.kind == "unrequested_record_input" then
      local fallback = "Auto-run was blocked because the generated action "
        .. "changes a track record input that the request did not ask to "
        .. "change. Preserve the current record input or ask for the exact "
        .. "input channel. Do not run the blocked script manually."
      return (RA and RA.t and RA.t(
        "auto_run.blocked.unrequested_record_input", nil, fallback))
        or fallback
    end
  end
  for _, finding in ipairs(findings or {}) do
    if type(finding) == "table"
        and finding.kind == "unresolved_record_input_property" then
      local fallback = "Auto-run was blocked because the generated action "
        .. "computes a track property at runtime and that property may "
        .. "resolve to the record input. Review the generated action and "
        .. "preserve the current record input. Do not run the blocked script "
        .. "manually."
      return (RA and RA.t and RA.t(
        "auto_run.blocked.unresolved_record_input_property", nil, fallback))
        or fallback
    end
  end
  local no_time_selection = tostring(snapshot or ""):find(
    "Time selection: none", 1, true) ~= nil
  if no_time_selection then
    for _, finding in ipairs(findings or {}) do
      if type(finding) == "table"
          and (finding.kind == "time_selection_glue_changes_range"
            or finding.kind == "time_selection_glue_action") then
        local fallback = "No project changes were run because no time "
          .. "selection is active. Make a time selection over at least two "
          .. "items on the requested track, then send the request again. "
          .. "Do not run the blocked script manually."
        return (RA and RA.t and RA.t(
          "auto_run.blocked.time_selection_glue_no_range", nil, fallback))
          or fallback
      end
    end
  end
  local fallback = "Auto-run was blocked because the generated action did "
    .. "not clearly match the request and captured session. Review the "
    .. "target tracks, plugins, and REAPER actions before running it manually."
  return (RA and RA.t and RA.t(
    "auto_run.blocked.relevance", nil, fallback)) or fallback
end

function Net._force_manual_run_status(history_entry, code, code_type)
  if type(history_entry) ~= "table" then return false end
  history_entry.run_status = "manual_run"
  history_entry.code_bytes = type(code) == "string" and #code or nil
  history_entry.code_type = code_type
  return true
end

function Net._force_manual_display_status(display_message, typed_action_present)
  if type(display_message) ~= "table"
      or display_message.auto_run_block_reason ~= "auto_run_disabled" then
    return false
  end
  if display_message.code_block_present ~= true
      and typed_action_present ~= true then
    return false
  end
  display_message.run_status = "manual_run"
  display_message.validation_status = "manual_required"
  if typed_action_present == true
      and display_message.code_block_present ~= true then
    display_message.code_type = "typed_actions"
  end
  return true
end

function Net._display_status_accepts_last_run_result(display_message)
  if type(display_message) ~= "table" then return false end
  return display_message.run_status == "ran_ok"
    or display_message.run_status == "errored"
    or display_message.run_status == "pending"
end
-- End referential option-selection retry policy.

-- Most recent assistant reply text as shown to the user. Used only to detect
-- whether a numbered-option list preceded a short referential selection. Kept
-- outside the sliced retry-policy block above on purpose: it reaches session
-- state, while the policy and its detector stay pure and sandbox-testable.
-- Reads S.display_messages rather than S.history because the current turn's
-- assistant reply is appended to display_messages only after the auto-run
-- gate runs, so the newest assistant display entry here is the PRIOR turn
-- (the one that may have presented the options); S.history already holds the
-- current reply by gate time and would return the wrong turn.
function Net._recent_assistant_display_text()
  local msgs = S and S.display_messages
  if type(msgs) ~= "table" then return nil end
  for i = #msgs, 1, -1 do
    local m = msgs[i]
    if type(m) == "table"
       and (m.role == "assistant" or m.role == "model") then
      local c = m.content
      if type(c) == "string" and c ~= "" then return c end
    end
  end
  return nil
end

-- Tier-aware copy for the per-turn-call-cap abort. Small / local models
-- loop the most, so the message nudges users toward the next tier up;
-- flagship models on the cap usually mean a genuinely confused turn,
-- so the suggestion is to start fresh and report it if it repeats.
function Net._call_cap_message()
  local p   = PROVIDERS.active() or {}
  local m   = MODELS[prefs.model_idx] or MODELS[1] or {}
  local mid = (m.id or m.name or ""):lower()
  local pid = p.id or ""
  -- Match a marker only at a word boundary so substrings inside larger
  -- names don't trigger -- e.g. "gemini-3.1-pro-preview" must NOT hit
  -- "mini", and "anthropic-flash-prototype" must hit "flash" cleanly.
  -- %f[%a] = position where prev char is non-letter and next is letter
  -- (start of a word); %f[%A] is the inverse (end of a word).
  local function tag(kw)
    return mid:find("%f[%a]" .. kw .. "%f[%A]") ~= nil
  end
  local hint
  if pid == "anthropic" and tag("haiku") then
    hint = RA.t("net.cap.call.hint_haiku", nil,
      "Try Sonnet 5 or Opus 5 for this request.")
  elseif pid == "google" and (tag("flash") or tag("nano")) then
    hint = RA.t("net.cap.call.hint_gemini", nil,
      "Try Gemini 3.1 Pro for this request.")
  elseif pid == "openai" and tag("mini") then
    hint = RA.t("net.cap.call.hint_openai", nil,
      "Try a non-mini OpenAI model for this request.")
  elseif p.is_custom
      or tag("haiku") or tag("flash") or tag("mini")
      or tag("nano")  or tag("gemma") or tag("llama")
      or tag("phi") then
    hint = RA.t("net.cap.call.hint_small", nil,
      "This often happens with smaller or local models -- try a "
        .. "higher-tier model.")
  else
    local help = RA.t("help.nav.feedback", nil, "Feedback & Report a Bug")
    hint = RA.t("net.cap.call.hint_flagship", { help = help },
      ("Unusual on a flagship model. Try starting a new chat or rephrasing. "
        .. "If it repeats, please use Help -> %s."):format(help))
  end
  return RA.t("net.cap.call",
    { calls = CFG.MAX_CALLS_PER_TURN, hint = hint },
    ("Stopped after %d API calls in one turn to avoid runaway cost. %s")
      :format(CFG.MAX_CALLS_PER_TURN, hint))
end

function Net._validator_retry_cap_message()
  return RA.t("net.cap.validator_retry",
    nil,
    "No project changes were made. ReaAssist could not safely complete this "
      .. "request after its automatic correction attempts.")
end

-- ONE BUDGET RULE, READ FROM BOTH SIDES OF THE DISPATCH. Net.fire_curl reads
-- this AFTER Probe.add_validator_retry has counted the retry, so the event it
-- is about to send is already in the turn's totals. A caller that reads the
-- budget BEFORE it dispatches (the preference repair of plan section 7.2,
-- which has to know the answer before it touches any turn state) passes
-- `proposed_kind`, and the state is projected forward by exactly the one event
-- that caller would cause: the aggregate plus one, that kind's count plus one,
-- the distinct-kind count plus one when the kind has not fired this turn, and
-- the proposed event as the last event. The projection is applied inside the
-- rule, so a pre-dispatch read and the transport's read cannot answer
-- differently about the same retry.
function Net._validator_retry_budget_state(proposed_kind)
  local proposed = nil
  if type(proposed_kind) == "string" and proposed_kind ~= "" then
    proposed = proposed_kind
  end
  local aggregate = tonumber(S.validator_retries_this_turn) or 0
  local normal_cap = CFG.MAX_VALIDATOR_RETRIES_PER_TURN or 3
  local kind_cap = CFG.MAX_VALIDATOR_RETRY_KINDS_PER_TURN or 4
  local counts = type(S.validator_retry_counts_by_kind) == "table"
    and S.validator_retry_counts_by_kind or {}
  local distinct = 0
  for _, count in pairs(counts) do
    if (tonumber(count) or 0) > 0 then distinct = distinct + 1 end
  end
  local last_kind, last_kind_count
  if proposed then
    local proposed_count = tonumber(counts[proposed]) or 0
    aggregate = aggregate + 1
    if proposed_count == 0 then distinct = distinct + 1 end
    last_kind = proposed
    last_kind_count = proposed_count + 1
  else
    local events = S.validator_retry_events_this_turn or {}
    local last_event = events[#events]
    last_kind = tostring(last_event and last_event.kind or "unspecified")
    last_kind_count = tonumber(counts[last_kind]) or 0
  end
  local allowed = aggregate <= normal_cap
    or (last_kind_count == 1 and distinct <= kind_cap)
  return {
    allowed = allowed,
    aggregate = aggregate,
    normal_cap = normal_cap,
    distinct_kind_count = distinct,
    distinct_kind_cap = kind_cap,
    last_kind = last_kind,
    last_kind_count = last_kind_count,
    projected_kind = proposed,
    mode = aggregate <= normal_cap and "normal"
      or (allowed and "distinct_kind_extension" or "exhausted"),
  }
end

function Net._validator_retry_cap_display_message()
  local message = Net._validator_retry_cap_message()
  local help = RA.t("help.nav.feedback", nil, "Feedback & Report a Bug")
  return message .. "\n\n" .. RA.t(
    "net.cap.validator_retry_next_resend",
    { help = help },
    "Send the same request again. If it fails again, switch models. If the "
      .. "problem repeats, use Help -> " .. help
      .. ". The rejected draft was kept out of this chat.")
end

function Net._context_fetch_cap_message()
  local cap = CFG.MAX_CONTEXT_FETCHES_PER_TURN or 3
  local help = RA.t("help.nav.feedback", nil, "Feedback & Report a Bug")
  return RA.t("net.cap.context_fetch",
    { cap = cap, help = help },
    ("No project changes were run. The model kept asking for additional project details after %d context fetches, so ReaAssist stopped to avoid runaway cost. Start a new chat or try another model. If it happens again, please use Help -> %s.")
      :format(cap, help))
end

function Net._validator_retry_candidate_type(text)
  text = tostring(text or "")
  if text:find("```reaassist-actions", 1, true) then return "typed_actions" end
  if text:find("```lua", 1, true)
     or text:find("```reascript", 1, true) then return "lua" end
  if text:find("```jsfx", 1, true)
     or text:find("```eel", 1, true) then return "jsfx" end
  if S.pending_typed_action_expected == true then return "typed_actions" end
  return text ~= "" and "response_text" or "empty_response"
end

-- Bounded per-retry event copy shared by the successful-turn validation
-- trace and both capped-turn error_debug payloads. The cap copiers used to
-- hand-copy events without the findings array, so capped bug reports (the
-- ones that actually get submitted) lost the per-rule finding detail. Routing
-- all three sites through here keeps findings on the cap paths too, with the
-- same 8-event / 8-finding caps and candidate subtable fields everywhere.
--   opts.kind_default: fallback kind ("unspecified" or "context_needed").
--   opts.retry_class:  stamped on every copy when set (context copier).
--   opts.repair_boolean: true stores repair_request_fired as boolean
--     true/false (the trace repair_fired rollup depends on it); otherwise the
--     historical cap shape of `true or nil` is preserved.
function Net._copy_retry_event(event, fallback_index, opts)
  opts = opts or {}
  local retry_reason = type(Diag) == "table"
    and type(Diag.normalize_retry_reason) == "function"
    and Diag.normalize_retry_reason(event.retry_reason or event.kind
      or event.ctx_label or opts.retry_class) or "unknown"
  if retry_reason == "unknown" and type(Diag) == "table"
     and type(Diag.normalize_retry_reason) == "function" then
    retry_reason = Diag.normalize_retry_reason(opts.retry_class or "validator")
  end
  local copy = {
    index = tonumber(event.index) or fallback_index,
    kind = retry_reason,
    retry_reason = retry_reason,
    context_class = event.ctx_label and type(Diag) == "table"
      and type(Diag.normalize_context_class) == "function"
      and Diag.normalize_context_class(event.ctx_label) or nil,
    api_calls_before_retry = tonumber(event.api_calls_before_retry) or 0,
    model_calls_before_retry = tonumber(event.model_calls_before_retry) or 0,
  }
  copy.retry_class = opts.retry_class == "context" and "context_fetch"
    or "validator"
  if opts.repair_boolean then
    copy.repair_request_fired = event.repair_request_fired == true
  else
    copy.repair_request_fired = event.repair_request_fired == true or nil
  end
  if type(event.findings) == "table" then
    copy.findings = {}
    for finding_index, finding in ipairs(event.findings) do
      if finding_index > 8 then break end
      if type(finding) == "table" then
        copy.findings[#copy.findings + 1] = {
          kind = "validator_finding",
          detail = tostring(finding.detail or ""),
          line = tonumber(finding.line),
          review_only = finding.review_only == true,
        }
      end
    end
    if #copy.findings == 0 then copy.findings = nil end
  end
  if event.reuse_hint_only ~= nil then
    copy.reuse_hint_only = event.reuse_hint_only == true
  end
  if type(event.candidate) == "table" then
    copy.candidate = {
      code_type = tostring(event.candidate.code_type or "response_text"),
      byte_count = tonumber(event.candidate.byte_count) or 0,
      content_hash = event.candidate.content_hash,
      content_hash_scope = event.candidate.content_hash_scope,
    }
    if event.candidate.excerpt ~= nil then
      copy.candidate.excerpt = tostring(event.candidate.excerpt or "")
      copy.candidate.excerpt_bytes =
        tonumber(event.candidate.excerpt_bytes) or 0
      copy.candidate.excerpt_truncated =
        event.candidate.excerpt_truncated == true or nil
    end
  end
  return copy
end

function Net._validation_trace_for_turn(final_candidate_text)
  local source_events = S.validator_retry_events_this_turn
  if type(source_events) ~= "table" or #source_events == 0 then return nil end
  local events = {}
  local repair_fired = false
  for i, event in ipairs(source_events) do
    if i > 8 then break end
    if type(event) == "table" then
      local copy = Net._copy_retry_event(event, i, { repair_boolean = true })
      repair_fired = repair_fired or copy.repair_request_fired
      events[#events + 1] = copy
    end
  end
  if #events == 0 then return nil end

  local final_scrubbed = tostring(final_candidate_text or "")
  if Net and type(Net._debug_scrub) == "function" then
    final_scrubbed = tostring(Net._debug_scrub(final_scrubbed) or "")
  elseif Log and type(Log.scrub_url_secrets) == "function" then
    final_scrubbed = tostring(Log.scrub_url_secrets(final_scrubbed) or "")
  end
  local final_hash = Diag and type(Diag.content_hash) == "function"
    and Diag.content_hash(final_scrubbed) or nil
  local last_candidate = events[#events].candidate
  local prior_hash = last_candidate and last_candidate.content_hash or nil
  local comparison = (final_hash and prior_hash)
    and (final_hash == prior_hash and "identical" or "changed")
    or "unavailable"
  local candidate_changed
  if comparison == "changed" then
    candidate_changed = true
  elseif comparison == "identical" then
    candidate_changed = false
  end

  local trace = {
    retry_count = #events,
    repair_request_fired = repair_fired,
    candidate_comparison = comparison,
    candidate_changed = candidate_changed,
    final_candidate_hash = final_hash,
    final_candidate_hash_scope = final_hash and "redacted" or nil,
    events = events,
  }
  local pending = S.pending_display_idx
    and S.display_messages[S.pending_display_idx] or nil
  if pending and type(pending.model_call_usage) == "table" then
    trace.call_usage = {}
    for i, usage in ipairs(pending.model_call_usage) do
      if i > 8 then break end
      if type(usage) == "table" then
        trace.call_usage[#trace.call_usage + 1] = {
          call_index = tonumber(usage.call_index) or i,
          stage = tostring(usage.stage or "response"),
          provider_id = usage.provider_id and tostring(usage.provider_id) or nil,
          input_tokens = tonumber(usage.input_tokens) or 0,
          output_tokens = tonumber(usage.output_tokens) or 0,
          cache_read_tokens = tonumber(usage.cache_read_tokens) or 0,
          cache_create_tokens = tonumber(usage.cache_create_tokens) or 0,
          uncached_input_tokens = tonumber(usage.uncached_input_tokens) or 0,
          context_class = type(Diag) == "table"
            and type(Diag.normalize_context_class) == "function"
            and Diag.normalize_context_class(usage.context_label) or "unknown",
        }
      end
    end
    if #trace.call_usage == 0 then trace.call_usage = nil end
  end
  return trace
end

function Net._call_cap_error_extra()
  local p   = PROVIDERS.active() or {}
  local m   = MODELS[prefs.model_idx] or MODELS[1] or {}
  local provider_id = p.is_custom and "custom" or (p.id or nil)
  local model_id = p.is_custom and "custom" or (m and (m.id or m.name) or nil)
  return {
    error_kind = "runaway_call_cap",
    error_debug = {
      failure_kind = "runaway_call_cap",
      source = "runaway_call_guardrail",
      matched_condition = "api_call_turn_cap",
      provider_id = provider_id,
      model_id = model_id,
      api_calls_this_turn = S.api_calls_this_turn or 0,
      max_api_calls_per_turn = CFG.MAX_CALLS_PER_TURN,
      session_status_before = S.status or nil,
      retry_count = S.retry_count,
      retry_max = S.retry_max,
      pending_display_idx = S.pending_display_idx,
      pending_turn_state = S.pending_orig_prompt and "orig_prompt" or nil,
    },
  }
end

function Net._validator_retry_cap_error_extra()
  local p   = PROVIDERS.active() or {}
  local m   = MODELS[prefs.model_idx] or MODELS[1] or {}
  local provider_id = p.is_custom and "custom" or (p.id or nil)
  local model_id = p.is_custom and "custom" or (m and (m.id or m.name) or nil)
  local events = {}
  for i, event in ipairs(S.validator_retry_events_this_turn or {}) do
    if i > 8 then break end
    events[#events + 1] = Net._copy_retry_event(event, i)
  end
  local last_event = events[#events]
  local budget = Net._validator_retry_budget_state()
  return {
    error_kind = "runaway_validator_retry_cap",
    error_debug = {
      failure_kind = "runaway_validator_retry_cap",
      source = "runaway_validator_retry_guardrail",
      matched_condition = "validator_retry_turn_cap",
      provider_id = provider_id,
      model_id = model_id,
      validator_retries_this_turn = S.validator_retries_this_turn or 0,
      max_validator_retries_per_turn = CFG.MAX_VALIDATOR_RETRIES_PER_TURN or 3,
      validator_retry_budget_mode = budget.mode,
      validator_retry_distinct_kind_count = budget.distinct_kind_count,
      max_validator_retry_kinds_per_turn = budget.distinct_kind_cap,
      last_validator_kind_retry_count = budget.last_kind_count,
      api_calls_this_turn = S.api_calls_this_turn or 0,
      max_api_calls_per_turn = CFG.MAX_CALLS_PER_TURN,
      session_status_before = S.status or nil,
      transport_retry_count = S.retry_count,
      transport_retry_max = S.retry_max,
      consecutive_validator_cap_count =
        (S.validator_retry_cap_streak or 0) > 0
          and S.validator_retry_cap_streak or 1,
      last_validator_kind = last_event and last_event.kind or nil,
      validator_retry_events = events,
      pending_display_idx = S.pending_display_idx,
      pending_turn_state = S.pending_orig_prompt and "orig_prompt" or nil,
    },
  }
end

function Net._context_fetch_cap_error_extra()
  local p   = PROVIDERS.active() or {}
  local m   = MODELS[prefs.model_idx] or MODELS[1] or {}
  local provider_id = p.is_custom and "custom" or (p.id or nil)
  local model_id = p.is_custom and "custom" or (m and (m.id or m.name) or nil)
  local events = {}
  for i, event in ipairs(S.context_fetch_events_this_turn or {}) do
    if i > 8 then break end
    events[#events + 1] = Net._copy_retry_event(event, i, {
      kind_default = "context_needed",
      retry_class = "context",
    })
  end
  local last_event = events[#events]
  return {
    error_kind = "runaway_context_fetch_cap",
    error_debug = {
      failure_kind = "runaway_context_fetch_cap",
      source = "runaway_context_fetch_guardrail",
      matched_condition = "context_fetch_turn_cap",
      provider_id = provider_id,
      model_id = model_id,
      context_fetches_this_turn = S.context_fetches_this_turn or 0,
      max_context_fetches_per_turn = CFG.MAX_CONTEXT_FETCHES_PER_TURN or 3,
      validator_retries_this_turn = S.validator_retries_this_turn or 0,
      api_calls_this_turn = S.api_calls_this_turn or 0,
      max_api_calls_per_turn = CFG.MAX_CALLS_PER_TURN,
      session_status_before = S.status or nil,
      transport_retry_count = S.retry_count,
      transport_retry_max = S.retry_max,
      last_context_kind = last_event and last_event.kind or nil,
      context_fetch_events = events,
      pending_display_idx = S.pending_display_idx,
      pending_turn_state = S.pending_orig_prompt and "orig_prompt" or nil,
    },
  }
end

function Net._ensure_request_start_time()
  -- Hidden same-turn retries fire curl directly instead of re-entering
  -- Net.send_to_api(), so they must preserve the original wall-clock anchor
  -- for the visible "Elapsed" timer. If an older path already lost it, fall
  -- back to the current request clock rather than showing a frozen 0:00.
  if not S.request_start_time then
    S.request_start_time = S.send_time or time_precise()
  end
end

function Net._clear_terminal_funding(provider_id)
  local latches = S.provider_terminal_funding_by_provider
  if type(latches) ~= "table" then latches = {} end
  local legacy = S.provider_terminal_funding
  if type(legacy) == "table" and legacy.provider_id then
    latches[legacy.provider_id] = latches[legacy.provider_id] or legacy
  end
  S.provider_terminal_funding_by_provider = latches
  S.provider_terminal_funding = nil
  if provider_id then
    if latches[provider_id] == nil then return false end
    latches[provider_id] = nil
    return true
  end
  local had_latch = next(latches) ~= nil
  S.provider_terminal_funding_by_provider = {}
  return had_latch
end

function Net._set_terminal_funding(p, error_kind)
  if type(p) ~= "table" or not p.id then return false end
  S.provider_terminal_funding_by_provider =
    S.provider_terminal_funding_by_provider or {}
  S.provider_terminal_funding_by_provider[p.id] = {
    provider_id = p.id,
    error_kind = error_kind,
  }
  S.provider_terminal_funding = nil
  return true
end

function Net._active_terminal_funding(p)
  if type(p) ~= "table" or not p.id then return nil end
  local latches = S.provider_terminal_funding_by_provider
  if type(latches) ~= "table" then
    latches = {}
    local legacy = S.provider_terminal_funding
    if type(legacy) == "table" and legacy.provider_id then
      latches[legacy.provider_id] = legacy
    end
    S.provider_terminal_funding_by_provider = latches
    S.provider_terminal_funding = nil
  end
  return latches[p.id]
end

function Net.try_local_terminal_funding_answer(user_text, attachments,
