function Net.try_local_save_actions_help(user_text, attachments, probe_turn)
  if attachments then return false end
  if not Code.prompt_requests_save_actions_help
      or not Code.prompt_requests_save_actions_help(
        user_text, S.latest_code_candidate) then
    return false
  end
  local save_label = S.screen_reader_mode
    and RA.t("a11y.sr.save_code", nil, "Save Code")
    or RA.t("common.save", nil, "Save")
  local add_label = S.screen_reader_mode
    and RA.t("a11y.sr.add_actions", nil, "Add to Actions")
    or RA.t("modal.actions.title", nil, "Add to Actions")
  local response_key = "response.local_save_actions_help"
  local fallback = "Use " .. save_label
    .. " beneath the generated code and choose a filename. If the full file "
    .. "browser opens, you can also choose a location; otherwise the basic "
    .. "prompt saves the script in REAPER's Scripts folder. When prompted, "
    .. "choose " .. add_label .. ". Then open REAPER's Actions list, find "
    .. "the saved script, select it, and use Add... under Shortcuts for "
    .. "selected action to press the key you want."
  if S.screen_reader_mode then
    response_key = "response.local_save_actions_help_sr"
    fallback = "Use " .. save_label .. ". ReaAssist saves the Lua script in "
      .. "REAPER's Scripts/ReaAssist folder and adds it to the Actions list "
      .. "automatically. Then open REAPER's Actions list, find the saved "
      .. "script, select it, and use Add... under Shortcuts for selected "
      .. "action to press the key you want."
  end
  local answer = RA.t(response_key, {
    save = save_label,
    add = add_label,
  }, fallback)
  return Net._emit_local_answer(user_text, answer, probe_turn, {
    ctx_label = "local_save_actions_help",
  })
end

function Net._prune_display_messages(max_count)
  local list = S and S.display_messages
  if type(list) ~= "table" then return 0 end
  local max = tonumber(max_count) or CFG.MAX_DISPLAY_MSGS
  local n = #list
  if n <= max then return 0 end
  local pruned_count = n - max
  for i = 1, max do
    list[i] = list[i + pruned_count]
  end
  for i = max + 1, n do
    list[i] = nil
  end
  return pruned_count
end

function Net._rebase_display_message_index(idx, pruned_count)
  local n = tonumber(idx)
  local pruned = tonumber(pruned_count) or 0
  if not n then return nil end
  n = n - pruned
  if n < 1 then return nil end
  return n
end

function Net._clear_pending_typed_action_lua_generation(expected)
  local generation = S and S.pending_typed_action_lua_generation or nil
  if expected ~= nil and generation ~= expected then return false end
  if type(generation) == "table" then
    local source = generation.source_message
    if type(source) == "table" then
      source.typed_action_lua_generation_pending = nil
    end
  end
  if S then S.pending_typed_action_lua_generation = nil end
  return generation ~= nil
end

function Net._pending_typed_action_lua_generation_for_request()
  local generation = S and S.pending_typed_action_lua_generation or nil
  if type(generation) ~= "table"
      or generation.request_display_idx == nil
      or generation.request_display_idx ~= S.pending_display_idx then
    return nil
  end
  return generation
end

function Net._typed_action_lua_generation_fully_settled()
  return (S.status == "idle" or S.status == "error")
    and S.curl_pid == nil
    and S.retry_scheduled ~= true
    and S.turn_budget_confirmation == nil
    and S.gemini_tier_pending ~= true
end

function Net._mark_typed_action_lua_generation_complete(generation, ready)
  if type(generation) ~= "table" then return false end
  local source = generation.source_message
  if type(source) ~= "table" then return false end
  source.typed_action_lua_generation_pending = nil
  if ready == true then source.typed_action_lua_requested = true end
  return true
end

function Net._rebase_display_message_refs(pruned_count)
  pruned_count = tonumber(pruned_count) or 0
  if pruned_count <= 0 or type(S) ~= "table" then return end
  S.pending_display_idx = Net._rebase_display_message_index(
    S.pending_display_idx, pruned_count)
  S.engine_display_idx = Net._rebase_display_message_index(
    S.engine_display_idx, pruned_count)
  if not S.engine_display_idx then S.engine_stream_visible = false end
  S.backup_warn_idx = Net._rebase_display_message_index(
    S.backup_warn_idx, pruned_count)
  S.backup_warn_typed_idx = Net._rebase_display_message_index(
    S.backup_warn_typed_idx, pruned_count)
  S.risky_warn_idx = Net._rebase_display_message_index(
    S.risky_warn_idx, pruned_count)
  S.jsfx_save_warn_idx = Net._rebase_display_message_index(
    S.jsfx_save_warn_idx, pruned_count)
  S.scroll_to_msg = Net._rebase_display_message_index(
    S.scroll_to_msg, pruned_count)
  if not S.scroll_to_msg then S.scroll_to_msg_frames = nil end
  if type(S.lua_defer_run) == "table" then
    S.lua_defer_run.message_idx = Net._rebase_display_message_index(
      S.lua_defer_run.message_idx, pruned_count)
  end
  if type(S.pending_typed_action_lua_generation) == "table" then
    local generation = S.pending_typed_action_lua_generation
    generation.source_message_idx = Net._rebase_display_message_index(
      generation.source_message_idx, pruned_count)
    generation.request_display_idx = Net._rebase_display_message_index(
      generation.request_display_idx, pruned_count)
  end
  if type(S.backup_flash) == "table" then
    local shifted = {}
    for idx, flash in pairs(S.backup_flash) do
      local rebased = Net._rebase_display_message_index(idx, pruned_count)
      if rebased then shifted[rebased] = flash end
    end
    S.backup_flash = shifted
  end
end

function Net._emit_local_answer(user_text, answer, probe_turn, opts)
  opts = opts or {}
  S.history[#S.history + 1] = {
    role = "user",
    content = "USER REQUEST:\n" .. tostring(user_text or ""),
  }
  S.history[#S.history + 1] = {
    role = "assistant",
    content = answer,
  }

  S.display_messages[#S.display_messages + 1] = {
    role = "user",
    content = tostring(user_text or ""),
    ctx_label = opts.ctx_label or "local_answer",
    model_label = "ReaAssist Local",
    provider_id = "local",
    from_card = S.from_card or nil,
  }
  local local_answer_msg = {
    role = "assistant",
    content = answer,
    provider_id = "local",
    model_label = "ReaAssist Local",
    local_answer = true,
    local_answer_available = true,
    provider_call_avoided = true,
    code_block_present = false,
    assistant_response_status = "complete",
    -- Diagnostic-only run_status: local read answer finished without provider/code execution.
    run_status = "local_answer",
    validation_status = "not_applicable",
    local_retry_available = true,
    llm_retry_prompt = tostring(user_text or ""),
    link_url = opts.link_url,
    link_label = opts.link_label,
  }
  if opts.selected_count_guard then
    local_answer_msg.selected_count_guard = opts.selected_count_guard
    local_answer_msg.validation_status = "blocked"
    local_answer_msg.validation_block_kind = "selected_count_mismatch"
  end
  S.display_messages[#S.display_messages + 1] = local_answer_msg
  S.from_card = false
  if #S.display_messages > CFG.MAX_DISPLAY_MSGS then
    if Diag.uploader_enabled and Diag.capture_current_chat then
      Diag.capture_current_chat()
    end
    local pruned_count = Net._prune_display_messages(CFG.MAX_DISPLAY_MSGS)
    if pruned_count > 0 then
      Net._rebase_display_message_refs(pruned_count)
      S.wrap_cache = {}
    end
  end

  S.status = "idle"
  S.request_start_time = nil
  S.send_time = nil
  S.pending_code = nil
  S.pending_display_idx = nil
  S.pending_no_guess_seed = nil
  S.pending_orig_prompt = nil
  S.pending_typed_action_expected = false
  S.pending_typed_action_response_format = false
  S.pending_typed_action_profile = nil
  S.pending_answer_only_followup = nil
  S.pending_starter_card_key = nil
  S.pending_project = nil
  S.pending_snapshot = nil
  S.pending_attachments = nil
  S._fx_cache_events = nil
  S.scroll_to_bottom = true
  Net._finish_probe_turn(probe_turn, "success")
  return true
end

