      Log.line("DRUM-QUANTIZE-VALIDATOR",
        "whole-item D_POSITION write for drum quantize/edit persisted after "
        .. "retry; auto-run blocked")
      Log.add_error((RA and RA.t and RA.t(
        "validator.drum_whole_item_quantize_blocked", nil,
        "The model tried to quantize/edit drums by moving whole "
          .. "media items even after a retry. That can do nothing or move the "
          .. "wrong musical material. Auto-run is blocked; use a shared "
          .. "guide-track stretch-marker timing map instead."))
        or "The model tried to quantize/edit drums by moving whole media items even after a retry. That can do nothing or move the wrong musical material. Auto-run is blocked; use a shared guide-track stretch-marker timing map instead.")
    end
  end

  -- DRUM-MARKER-SYNC VALIDATOR: A drum stretch-marker script that does not
  -- normalize the marker set in the edit range can leave guide tracks with
  -- extra Dynamic Split markers and non-guide tracks with a different map,
  -- causing phase and stretch-ratio mismatches.
  local drum_marker_sync_gate_hit = false
  if lua_code and not docs_gate_hit and not validator_gate_hit then
    local drum_marker_sync_user_text = Net.retry_user_request_context()
    local drum_marker_sync_bad =
      Code.find_unsynced_drum_stretch_marker_scripts(
        lua_code, drum_marker_sync_user_text)
    if drum_marker_sync_bad and #drum_marker_sync_bad > 0 then
      if (S.drum_marker_sync_validator_retries or 0) < 1 then
        S.drum_marker_sync_validator_retries =
          (S.drum_marker_sync_validator_retries or 0) + 1
        local lines = {}
        for _, e in ipairs(drum_marker_sync_bad) do
          lines[#lines + 1] = "  - line " .. tostring(e.line)
        end
        Log.line("DRUM-MARKER-SYNC-VALIDATOR",
          "drum stretch-marker script lacked range normalization ("
          .. #drum_marker_sync_bad .. " finding(s)); retrying with hint "
          .. "(user-invisible)")
        local history_content = "(INTERNAL NOTE TO THE MODEL -- DO NOT MENTION "
          .. "ANY OF THIS IN YOUR VISIBLE REPLY: Your previous reply added or "
          .. "moved drum stretch markers without first normalizing the marker "
          .. "set across every affected drum item. This can leave guide tracks "
          .. "with extra Dynamic Split markers while non-guide tracks get a "
          .. "different marker map, creating phase drift and extreme stretch "
          .. "ratios.\n\n"
          .. "Affected SetTakeStretchMarker line(s):\n"
          .. tbl_concat(lines, "\n") .. "\n\n"
          .. "Regenerate so the final marker set is identical on every "
          .. "affected drum item, including guide tracks. Guide tracks are "
          .. "analysis sources only. After deriving the guide source-time -> "
          .. "target-time map, delete/replace stretch markers in the edit "
          .. "range on every affected item, then insert the same sorted, "
          .. "de-duplicated map plus unchanged boundary anchors. Compute each "
          .. "marker as pos = target_project_time - item_position and srcpos "
          .. "= source_project_time - item_position; do not preserve arbitrary "
          .. "existing guide-track srcpos. Merge/skip hits whose snapped target "
          .. "times collide or cross. If the user did not authorize replacing "
          .. "markers in the range, ask one question instead of emitting code. "
          .. "Respond as if this is your FIRST reply -- do NOT apologize, do "
          .. "NOT mention a retry.)\n\n"
          .. "USER REQUEST:\n" .. drum_marker_sync_user_text
        Net.fire_validator_retry({
          kind = "drum_marker_sync",
          history_content = history_content,
          ctx_label = "drum_marker_sync_retry",
          retry_failed_key = "retry.reason.for_unsynchronized_drum_stretch_markers",
          retry_failed_label = "for unsynchronized drum stretch markers",
          failure_message = "Auto-retry for unsynchronized drum stretch markers did not go through. Please resend the last message.",
        })
        return
      end
      drum_marker_sync_gate_hit = true
      validator_gate_hit = true
      Log.line("DRUM-MARKER-SYNC-VALIDATOR",
        "drum stretch-marker script without range normalization persisted "
        .. "after retry; auto-run blocked")
      Log.add_error((RA and RA.t and RA.t(
        "validator.drum_marker_sync_blocked", nil,
        "The model tried to write drum stretch markers without "
          .. "normalizing the same marker map across every affected drum item. "
          .. "Auto-run is blocked; the final stretch markers must be identical "
          .. "on guide and non-guide tracks."))
        or "The model tried to write drum stretch markers without normalizing the same marker map across every affected drum item. Auto-run is blocked; the final stretch markers must be identical on guide and non-guide tracks.")
    end
  end

  -- ARITY VALIDATOR: After the API validator passes, scan high-confidence
  -- fixed-arity calls (TrackFX_SetParamNormalized, etc.) for wrong arg
  -- counts. Catches a class the API validator can't: the NAME is real, but
  -- the call was emitted with the wrong number of arguments -- often a
  -- model dropping the param-index and passing a value where pidx belongs,
  -- which crashes inside reaper.defer with "bad argument #N (number has no
  -- integer representation)". Same recovery shape as the other validators.
  local arity_gate_hit = false
  if lua_code and not docs_gate_hit and not validator_gate_hit then
    local arity_bad = Code.find_reaper_arity_mismatches(lua_code) or {}
    local marker2_isrgn_bad = type(Code.find_addprojectmarker2_isrgn_misuse) == "function"
      and Code.find_addprojectmarker2_isrgn_misuse(lua_code) or nil
    if marker2_isrgn_bad then
      for _, e in ipairs(marker2_isrgn_bad) do
        arity_bad[#arity_bad + 1] = e
      end
    end
    if arity_bad and #arity_bad > 0 then
      if (S.arity_validator_retries or 0) < 1 then
        S.arity_validator_retries = (S.arity_validator_retries or 0) + 1
        local lines = {}
        for _, e in ipairs(arity_bad) do
          lines[#lines+1] = "  - reaper." .. e.name
            .. " requires " .. e.expected .. "; call site has "
            .. e.got .. "."
        end
        Log.line("ARITY-VALIDATOR",
          "fixed-arity reaper.* calls with wrong arg count ("
          .. #arity_bad .. "): "
          .. (function()
              local names = {}
              for _, e in ipairs(arity_bad) do
                names[#names+1] = e.name .. "(got " .. e.got
                  .. "/expected " .. e.expected .. ")"
              end
              return tbl_concat(names, ", ")
            end)()
          .. "; retrying with hint (user-invisible)")
        local history_content = "(INTERNAL NOTE TO THE MODEL -- DO NOT MENTION "
          .. "ANY OF THIS IN YOUR VISIBLE REPLY: Your previous reply called "
          .. "REAPER API function(s) with the WRONG number of arguments. "
          .. "These would crash at runtime:\n"
          .. tbl_concat(lines, "\n") .. "\n\n"
          .. "Common cause: dropping a required argument from a fixed "
          .. "signature call. Examples: `reaper.SetCurrentBPM(project, "
          .. "bpm, wantUndo)` has 3 args; "
          .. "`reaper.GetSetMediaTrackInfo_String(track, parmname, "
          .. "value, setNewValue)` has 4 args; "
          .. "`reaper.AddProjectMarker2(project, isrgn, pos, rgnend, "
          .. "name, wantidx, color)` has 7 args; pass `0` for the default "
          .. "marker color, and pass `false` as the second arg for a point "
          .. "marker (`true` only for regions); or use `AddProjectMarker` "
          .. "with 6 args; "
          .. "`reaper.TrackFX_SetParamNormalized(track, fx_index, "
          .. "param_index, value)` has 4 args. "
          .. "`reaper.TrackFX_GetFormattedParamValue(track, fx_index, "
          .. "param_index, \"\")` and the TakeFX equivalent have 4 args. "
          .. "For a three-argument formatted readback, append the empty string "
          .. "as argument 4; preserve the existing parameter index at argument 3. "
          .. "There is no candidate value argument in this readback API. Check the API reference "
          .. "for the correct signature and regenerate the code. If docs, "
          .. "midi, session, or prompt bundles are already pinned above, "
          .. "use them now; do NOT request context again. Respond as if "
          .. "this is your FIRST reply -- do NOT apologize, do NOT mention "
          .. "a retry.)\n\n"
          .. "Previous Lua to fix:\n```lua\n"
          .. lua_code
          .. "\n```\n\n"
          .. "USER REQUEST:\n" .. (S.pending_orig_prompt or "")
        Net.fire_validator_retry({
          kind = "arity",
          history_content = history_content,
          ctx_label = "arity_retry",
          retry_failed_key = "retry.reason.for_reaper_arity_mismatch",
          retry_failed_label = "for reaper.* arity mismatch",
          failure_message = "Auto-retry for reaper.* arity mismatch did not go through. Please resend the last message.",
        })
        return
      end
      arity_gate_hit = true
      Log.line("ARITY-VALIDATOR",
        "fixed-arity reaper.* calls with wrong arg count persist after "
        .. "retry; auto-run blocked")
      local user_lines = {}
      for _, e in ipairs(arity_bad) do
        user_lines[#user_lines+1] = "reaper." .. e.name .. " (got "
          .. e.got .. ", expected " .. e.expected .. ")"
      end
      Log.add_error((RA and RA.t and RA.t(
        "validator.reaper_arity_blocked",
        { calls = tbl_concat(user_lines, "; ") },
        "The model emitted REAPER API call(s) with the wrong "
          .. "number of arguments, even after a retry: "
          .. tbl_concat(user_lines, "; ")
          .. ". Auto-run is blocked; review and edit the code before clicking "
          .. "Run manually."))
        or ("The model emitted REAPER API call(s) with the wrong number of arguments, even after a retry: "
          .. tbl_concat(user_lines, "; ")
          .. ". Auto-run is blocked; review and edit the code before clicking Run manually."))
    end
  end

  -- ENVELOPE VISIBILITY CHUNK VALIDATOR: preserve every field after the first
  -- VIS flag. A whole-line rewrite can rely on undocumented host normalization
  -- and can fail without evidence when SetEnvelopeStateChunk is unchecked.
  if lua_code and not docs_gate_hit and not validator_gate_hit
      and not arity_gate_hit then
    local vis_bad = Code.find_destructive_envelope_vis_rewrites
      and Code.find_destructive_envelope_vis_rewrites(lua_code) or nil
    if vis_bad and #vis_bad > 0 then
      if (S.envelope_vis_validator_retries or 0) < 1 then
        S.envelope_vis_validator_retries =
          (S.envelope_vis_validator_retries or 0) + 1
        Log.line("ENVELOPE-VIS-VALIDATOR",
          "destructive envelope VIS record rewrite; retrying with preserved fields and readback")
        local history_content = "(INTERNAL NOTE TO THE MODEL -- DO NOT "
          .. "MENTION ANY OF THIS IN YOUR VISIBLE REPLY: Your previous Lua "
          .. "rewrote an entire envelope state-chunk VIS record as a "
          .. "one-field line. Regenerate the full script. Change only the "
          .. "first VIS flag and preserve every remaining field byte for "
          .. "byte. Require SetEnvelopeStateChunk to return true, reread the "
          .. "envelope chunk, verify that the first VIS flag now equals the "
          .. "requested state, then call TrackList_AdjustWindows(false) and "
          .. "UpdateArrange(). If any write or readback check fails, report "
          .. "the failure and stop. Respond as if this is your FIRST reply "
          .. "and do not mention a retry.)\n\nPrevious Lua to fix:\n```lua\n"
          .. lua_code .. "\n```\n\nUSER REQUEST:\n"
          .. (S.pending_orig_prompt or "")
        Net.fire_validator_retry({
          kind = "envelope_visibility",
          findings = vis_bad,
          history_content = history_content,
          ctx_label = "envelope_visibility_retry",
          failure_message = "Automatic repair after an unsafe envelope "
            .. "visibility rewrite did not go through. Please resend the last message.",
        })
        return
      end
      validator_gate_hit = true
      Log.line("ENVELOPE-VIS-VALIDATOR",
        "destructive envelope VIS record rewrite persisted after retry; auto-run blocked")
      local request_elapsed_s = S.request_start_time
        and math.max(0, time_precise() - S.request_start_time) or nil
      local validation_trace = Net._validation_trace_for_turn(
        S.validator_retry_candidate_text)
      Log.add_error("The script still rewrites a complete envelope VIS record "
        .. "without preserving its remaining fields or verifying the write. "
        .. "ReaAssist did not run it. Preserve the existing VIS fields, change "
        .. "only the first flag, and verify SetEnvelopeStateChunk plus readback "
        .. "before running manually.", nil, nil, nil, {
          error_kind = "validator_blocked",
          run_status = "blocked_validator",
          validation_status = "blocked",
          validation_block_kind = "envelope_visibility",
          failed_request_latency_ms = request_elapsed_s
            and math.floor(request_elapsed_s * 1000 + 0.5) or nil,
          validation_trace = validation_trace,
          error_debug = {
            failure_kind = "validator_blocked",
            source = "envelope_visibility_validator",
            validation_block_kind = "envelope_visibility",
            request_elapsed_s = request_elapsed_s,
            retry_count = S.envelope_vis_validator_retries or 0,
          },
        })
    end
  end

  -- LITERAL NAME WORD REMOVAL VALIDATOR: a request to remove one plain word
  -- must not delete the same letters inside a larger name. Require token
  -- boundaries, delimiter cleanup, and an empty-result guard.
  if lua_code and not docs_gate_hit and not validator_gate_hit
      and not arity_gate_hit then
    local name_word_bad = Code.find_unsafe_literal_name_word_removal
      and Code.find_unsafe_literal_name_word_removal(
        lua_code, S.pending_orig_prompt) or nil
    if name_word_bad and #name_word_bad > 0 then
      if (S.literal_name_word_validator_retries or 0) < 1 then
        S.literal_name_word_validator_retries =
          (S.literal_name_word_validator_retries or 0) + 1
        Log.line("LITERAL-NAME-WORD-RETRY",
          "unrestricted literal deletion in name cleanup; retrying with token-boundary pattern")
        local history_content = "(INTERNAL NOTE TO THE MODEL -- DO NOT "
          .. "MENTION ANY OF THIS IN YOUR VISIBLE REPLY: The user asked to "
          .. "remove one plain alphabetic word from names. Your previous "
          .. "Lua used unrestricted substring deletion, which can corrupt "
          .. "a larger embedded word. Regenerate the full script using Lua "
          .. "frontier boundaries around the requested literal. Clean any "
          .. "adjacent spaces, underscores, and hyphens left behind, trim "
          .. "the final name, and keep the original name if the cleaned "
          .. "result would be empty. Preserve all unrelated name text and "
          .. "targets. Respond as if this is your FIRST reply and do not "
          .. "mention a retry.)\n\nPrevious Lua to fix:\n```lua\n"
          .. lua_code
          .. "\n```\n\nUSER REQUEST:\n" .. (S.pending_orig_prompt or "")
        Net.fire_validator_retry({
          kind = "literal_name_word_removal",
          findings = name_word_bad,
          history_content = history_content,
          ctx_label = "literal_name_word_retry",
          retry_failed_key =
            "retry.reason.after_unsafe_literal_name_word_removal",
          retry_failed_label = "after unsafe literal name cleanup",
          failure_message = "Automatic repair after unsafe literal name "
            .. "cleanup did not go through. Please resend the last message.",
        })
        return
      end
      validator_gate_hit = true
      Log.line("LITERAL-NAME-WORD-VALIDATOR",
        "unsafe literal name cleanup persisted after retry; auto-run blocked")
      Log.add_error((RA and RA.t and RA.t(
        "validator.literal_name_word_removal_blocked", nil,
        "The script still removes a requested word as an unrestricted "
          .. "substring, leaves spaces, underscores, or hyphens unhandled, "
          .. "or omits empty-name protection. ReaAssist did not run it. Add "
          .. "token boundaries, cleanup for spaces, underscores, and "
          .. "hyphens, plus an empty-result guard before running manually."))
        or "The script still removes a requested word as an unrestricted substring, leaves spaces, underscores, or hyphens unhandled, or omits empty-name protection. ReaAssist did not run it. Add token boundaries, cleanup for spaces, underscores, and hyphens, plus an empty-result guard before running manually.")
    end
  end

  -- MEDIA-ITEM LABEL VALIDATOR: visible arrange item labels live on takes,
  -- not MediaItems. A script that writes MediaItem P_NAME can appear to
  -- "label" chord-chart items in prose while leaving the arrange view blank.
  -- Retry once with the concrete AddTakeToMediaItem / take-name sequence.
  local media_item_label_gate_hit = false
  if lua_code and not docs_gate_hit and not validator_gate_hit
     and not arity_gate_hit then
    local label_bad = Code.find_media_item_p_name_misuse(lua_code)
    if label_bad and #label_bad > 0 then
      if (S.media_item_label_validator_retries or 0) < 1 then
        S.media_item_label_validator_retries =
          (S.media_item_label_validator_retries or 0) + 1
        S.media_item_label_retry_used = true
        Log.line("MEDIA-ITEM-LABEL-VALIDATOR",
          "MediaItem P_NAME used for visible item label; retrying with hint")
        local history_content = "(INTERNAL NOTE TO THE MODEL -- DO NOT "
          .. "MENTION ANY OF THIS IN YOUR VISIBLE REPLY: Your previous reply "
          .. "called reaper.GetSetMediaItemInfo_String(item, \"P_NAME\", ...). "
          .. "MediaItem string params do not include P_NAME; they accept "
          .. "P_NOTES, P_EXT:..., and GUID. Visible arrange item labels live "
          .. "on the active take. If you create a plain item with "
          .. "reaper.AddMediaItemToTrack(item_track), call "
          .. "reaper.AddTakeToMediaItem(item), then name that returned take "
          .. "with reaper.GetSetMediaItemTakeInfo_String(take, \"P_NAME\", "
          .. "label, true). If you create a MIDI item with "
          .. "reaper.CreateNewMIDIItemInProj(track, start, finish, false), "
          .. "get its active take and name the take. Preserve the user's "
          .. "requested item labels, timing, colors, track names, and ordering. "
          .. "Respond as if this is your FIRST reply -- do NOT apologize, do "
          .. "NOT mention a retry.)\n\n"
          .. "Previous Lua to fix:\n```lua\n"
          .. lua_code
          .. "\n```\n\nUSER REQUEST:\n" .. (S.pending_orig_prompt or "")
        Net.fire_validator_retry({
          kind = "media_item_label",
          history_content = history_content,
          ctx_label = "media_item_label_retry",
          retry_failed_key = "retry.reason.for_media_item_label_misuse",
          retry_failed_label = "for MediaItem item-label misuse",
          failure_message = "Auto-retry for MediaItem item-label misuse did not go through. Please resend the last message.",
        })
        return
      end
      media_item_label_gate_hit = true
      validator_gate_hit = true
      Log.line("MEDIA-ITEM-LABEL-VALIDATOR",
        "MediaItem P_NAME persisted after retry; auto-run blocked")
      Log.add_error((RA and RA.t and RA.t(
        "validator.media_item_label_blocked", nil,
        "The script tries to label MediaItems with P_NAME. "
          .. "Auto-run is blocked because MediaItem string params accept only "
          .. "P_NOTES/P_EXT/GUID; visible arrange labels live on the take. "
          .. "Use AddTakeToMediaItem or CreateNewMIDIItemInProj, then call "
          .. "GetSetMediaItemTakeInfo_String(take, \"P_NAME\", label, true)."))
        or "The script tries to label MediaItems with P_NAME. Auto-run is blocked because MediaItem string params accept only P_NOTES/P_EXT/GUID; visible arrange labels live on the take. Use AddTakeToMediaItem or CreateNewMIDIItemInProj, then call GetSetMediaItemTakeInfo_String(take, \"P_NAME\", label, true).")
    end
  end

  -- SEND-INDEX VALIDATOR: CreateTrackSend returns the new send index.
  -- If the model ignores that return value and later uses hard-coded
  -- send indices while setting send properties, it can silently set the
  -- wrong send when multiple sends exist on the same source track. Same
  -- recovery shape as the other validators: one hidden retry, then block
  -- auto-run if the pattern persists.
  local sendidx_gate_hit = false
  if lua_code and not docs_gate_hit and not validator_gate_hit
     and not arity_gate_hit and not media_item_label_gate_hit then
    local sendidx_bad = Code.find_untracked_createtracksend_results(lua_code)
    if sendidx_bad and #sendidx_bad > 0 then
      if (S.sendidx_validator_retries or 0) < 1 then
        S.sendidx_validator_retries =
          (S.sendidx_validator_retries or 0) + 1
        local lines = {}
        for _, e in ipairs(sendidx_bad) do
          if e.kind == "multi_assign" then
            lines[#lines+1] = "  - line " .. tostring(e.create_line)
              .. " assigns CreateTrackSend with multiple return variables (`"
              .. tostring(e.sendidx) .. "`), but it returns one integer"
          elseif e.kind == "duplicate" then
            lines[#lines+1] = "  - lines " .. tostring(e.create_line)
              .. " and " .. tostring(e.set_line)
              .. " both create a send from `" .. tostring(e.source)
              .. "` to `" .. tostring(e.dest) .. "`"
          elseif e.kind == "zero_check" then
            lines[#lines+1] = "  - line " .. tostring(e.set_line)
              .. " treats returned send index `" .. tostring(e.sendidx)
              .. "` as failed when it is 0, but the first valid send index is 0"
          else
            lines[#lines+1] = "  - source `" .. tostring(e.source)
              .. "` uses literal send index " .. tostring(e.sendidx)
              .. " after an ignored CreateTrackSend result"
          end
        end
        Log.line("SENDIDX-VALIDATOR",
          "unsafe CreateTrackSend result handling ("
          .. #sendidx_bad .. "); retrying with hint (user-invisible)")
        local history_content = "(INTERNAL NOTE TO THE MODEL -- DO NOT MENTION "
          .. "ANY OF THIS IN YOUR VISIBLE REPLY: Your previous reply called "
          .. "reaper.CreateTrackSend(...) with unsafe return-value handling. "
          .. "CreateTrackSend returns exactly ONE value: the new send index. "
          .. "It does NOT return `ok, sendidx`, so `local _, sidx = "
          .. "reaper.CreateTrackSend(...)` makes sidx nil. It is also unsafe "
          .. "to ignore the return value and later use hard-coded send indices. "
          .. "Do not call CreateTrackSend twice for the same source and "
          .. "destination unless the user explicitly asked for duplicate sends. "
          .. "A returned send index of 0 is valid for the first send; only -1 "
          .. "means failure. "
          .. "You MUST store the one returned integer and use it when setting "
          .. "send attributes.\n\n"
          .. "Affected send property call(s):\n"
          .. tbl_concat(lines, "\n") .. "\n\n"
          .. "Use this pattern:\n"
          .. "  local sidx = reaper.CreateTrackSend(src, dst)\n"
          .. "  if sidx >= 0 then\n"
          .. "    reaper.SetTrackSendInfo_Value(src, 0, sidx, \"D_VOL\", amp)\n"
          .. "  end\n\n"
          .. "Regenerate the code with every configured send using its own "
          .. "returned send index variable. Respond as if this is your FIRST "
          .. "reply -- do NOT apologize, do NOT mention a retry.)\n\n"
          .. "USER REQUEST:\n" .. (S.pending_orig_prompt or "")
        Net.fire_validator_retry({
          kind = "sendidx",
          history_content = history_content,
          ctx_label = "sendidx_retry",
          retry_failed_key = "retry.reason.for_ignored_createtracksend_result",
          retry_failed_label = "for ignored CreateTrackSend result",
          failure_message = "Auto-retry for ignored CreateTrackSend result did not go through. Please resend the last message.",
        })
        return
      end
      sendidx_gate_hit = true
      Log.line("SENDIDX-VALIDATOR",
        "unsafe CreateTrackSend result handling persists after retry; auto-run blocked")
      local user_lines = {}
      for _, e in ipairs(sendidx_bad) do
        if e.kind == "multi_assign" then
          user_lines[#user_lines+1] =
            "line " .. tostring(e.create_line)
            .. " uses multiple assignment for CreateTrackSend"
        elseif e.kind == "zero_check" then
          user_lines[#user_lines+1] =
            "line " .. tostring(e.set_line)
            .. " rejects valid send index 0"
        else
          user_lines[#user_lines+1] = tostring(e.source)
            .. " send index " .. tostring(e.sendidx)
        end
      end
      Log.add_error((RA and RA.t and RA.t(
        "validator.send_index_blocked",
        { details = tbl_concat(user_lines, "; ") },
        "The model created sends with unsafe CreateTrackSend "
          .. "return-value handling, even after a retry: "
          .. tbl_concat(user_lines, "; ")
          .. ". Auto-run is blocked; review and edit the code before clicking "
          .. "Run manually."))
        or ("The model created sends with unsafe CreateTrackSend return-value handling, even after a retry: "
          .. tbl_concat(user_lines, "; ")
          .. ". Auto-run is blocked; review and edit the code before clicking Run manually."))
    end
  end

  -- TIMECODE-WORKFLOW VALIDATOR: native timecode generator actions are
  -- selection-sensitive, and hardware output sends use category 1. Catch the
  -- common partial-success shape where the item lands on one track while the
  -- script routes an empty helper track, or where category 0 leaves the
  -- hardware send on its default output pair.
  local timecode_workflow_gate_hit = false
  if lua_code and not docs_gate_hit and not validator_gate_hit
     and not arity_gate_hit and not media_item_label_gate_hit
     and not sendidx_gate_hit then
    local workflow_bad = Code.find_timecode_generator_workflow_misuse(
      lua_code, S.pending_orig_prompt or "")
    if workflow_bad and #workflow_bad > 0 then
      if (S.timecode_workflow_validator_retries or 0) < 1 then
        S.timecode_workflow_validator_retries =
          (S.timecode_workflow_validator_retries or 0) + 1
        local lines = {}
        for _, e in ipairs(workflow_bad) do
          if e.kind == "hardware_category" then
            lines[#lines + 1] = "  - line " .. tostring(e.set_line)
              .. " sets hardware send `" .. tostring(e.sendidx)
              .. "` with category 0; hardware outputs require category 1"
          elseif e.kind == "route_before_action" then
            lines[#lines + 1] = "  - line " .. tostring(e.line)
              .. " routes a track before the native timecode action runs"
          elseif e.kind == "precreated_track_before_timecode_action" then
            lines[#lines + 1] = "  - line " .. tostring(e.line)
              .. " creates a helper target track before the native timecode "
              .. "action; the native action can create/use a separate item "
              .. "track, leaving a blank extra track behind"
          elseif e.kind == "missing_generated_item_track_detection" then
            lines[#lines + 1] = "  - line " .. tostring(e.line)
              .. " routes the pre-created track without first detecting which "
              .. "track actually received the native timecode generator item"
          elseif e.kind == "precreated_track_without_item_move" then
            lines[#lines + 1] = "  - line " .. tostring(e.line)
              .. " detects the generated item track but leaves the item on "
              .. "that track instead of moving it onto the pre-created target "
              .. "track before routing"
          elseif e.kind == "missing_exclusive_selection" then
            lines[#lines + 1] = "  - line " .. tostring(e.line)
              .. " runs the native timecode action without first selecting "
              .. "only the intended target track"
          elseif e.kind == "overconstrained_action_lookup" then
            lines[#lines + 1] = "  - line " .. tostring(e.line)
              .. " requires timecode plus generator plus SMPTE/LTC/MTC in "
              .. "one action-name match; that can miss REAPER's native "
              .. "timecode generator action"
          else
            lines[#lines + 1] = "  - line "
              .. tostring(e.line or e.set_line or "?")
              .. ": unsafe native timecode generator workflow"
          end
        end
        Log.line("TIMECODE-WORKFLOW-VALIDATOR",
          "unsafe native timecode workflow (" .. #workflow_bad
          .. "); retrying with track/send hint (user-invisible)")
        local history_content = "(INTERNAL NOTE TO THE MODEL -- DO NOT "
          .. "MENTION ANY OF THIS IN YOUR VISIBLE REPLY: The user asked for "
          .. "a native SMPTE/LTC/MTC timecode generator routed only to "
          .. "hardware outputs 3 and 4. Your previous reply used an unsafe "
          .. "native workflow:\n"
          .. tbl_concat(lines, "\n") .. "\n\n"
          .. "Regenerate the FULL Lua script with these exact requirements:\n"
          .. "1. Do NOT use TrackFX_AddByName/TakeFX_AddByName; this is not "
          .. "an FX plugin.\n"
          .. "2. Do NOT create a helper/target track before running the "
          .. "native timecode-generator action. For this standalone insert "
          .. "request, let the native action create or choose the generator "
          .. "item track, then rename and route that actual track. A "
          .. "pre-created helper track can be left blank.\n"
          .. "3. Find the native action with broad fallback pairs: first "
          .. "try an action whose text contains `timecode` and `generator`; "
          .. "if not found, try `smpte` and `generator`; then try "
          .. "`ltc`/`mtc` and `generator`. Do NOT require `timecode`, "
          .. "`generator`, and `smpte`/`ltc`/`mtc` all in the same match, "
          .. "because REAPER action names vary by install/localization.\n"
          .. "4. Run the verified native timecode generator action, then "
          .. "detect which track actually received the generated timecode "
          .. "item. Prefer `local item = reaper.GetSelectedMediaItem(0, 0)` "
          .. "immediately after Main_OnCommand, then "
          .. "`generator_track = item and reaper.GetMediaItemTrack(item)`. "
          .. "A before/after item-count fallback is allowed only if it "
          .. "ultimately resolves a specific MediaItem with GetMediaItemTrack. "
          .. "Do NOT use source filenames to identify the item, and do NOT "
          .. "fall back to the pre-created target track unless that exact "
          .. "track demonstrably received the new item. If you cannot detect "
          .. "the item track, show an error and return before routing.\n"
          .. "5. Route the detected `generator_track` and optionally rename "
          .. "that track. Do not create, route, or leave behind a blank helper "
          .. "target track.\n"
          .. "6. For the hardware output send, use:\n"
          .. "   local sidx = reaper.CreateTrackSend(generator_track, nil)\n"
          .. "   if sidx < 0 then ... return end\n"
          .. "   reaper.SetTrackSendInfo_Value(generator_track, 1, sidx, "
          .. "\"I_SRCCHAN\", 0)\n"
          .. "   reaper.SetTrackSendInfo_Value(generator_track, 1, sidx, "
          .. "\"I_DSTCHAN\", 2)\n"
          .. "Category 1 is required because nil destination creates a "
          .. "hardware output. Category 0 is only for normal track-to-track "
          .. "sends and will leave the hardware send at its default 1/2 "
          .. "destination.\n"
          .. "7. Disable `B_MAINSEND` on the generator track so it does not "
          .. "also feed the master/main outputs.\n\n"
          .. "Respond as if this is your FIRST reply -- do NOT apologize, do "
          .. "NOT mention a retry.)\n\n"
          .. "USER REQUEST:\n" .. (S.pending_orig_prompt or "")
        Net.fire_validator_retry({
          kind = "timecode_workflow",
          history_content = history_content,
          ctx_label = "timecode_workflow_retry",
          retry_failed_key = "retry.reason.for_timecode_generator_workflow_repair",
          retry_failed_label = "for native timecode generator workflow repair",
          failure_message = "Auto-retry for native timecode generator workflow repair did not go through. Please resend the last message.",
        })
        return
      end
      timecode_workflow_gate_hit = true
      Log.line("TIMECODE-WORKFLOW-VALIDATOR",
        "unsafe native timecode workflow persists after retry; auto-run blocked")
      local user_lines = {}
      for _, e in ipairs(workflow_bad) do
        if e.kind == "hardware_category" then
          user_lines[#user_lines + 1] =
            "line " .. tostring(e.set_line)
            .. " uses send category 0 for a hardware output"
        elseif e.kind == "route_before_action" then
          user_lines[#user_lines + 1] =
            "line " .. tostring(e.line)
            .. " routes before the native action creates/inserts the item"
        elseif e.kind == "precreated_track_before_timecode_action" then
          user_lines[#user_lines + 1] =
            "line " .. tostring(e.line)
            .. " creates a helper target track before the native timecode action"
        elseif e.kind == "missing_generated_item_track_detection" then
          user_lines[#user_lines + 1] =
            "line " .. tostring(e.line)
            .. " routes the pre-created track without detecting the generated item track"
        elseif e.kind == "precreated_track_without_item_move" then
          user_lines[#user_lines + 1] =
            "line " .. tostring(e.line)
            .. " detects the item track but does not move the generated item onto the pre-created target track before routing"
        elseif e.kind == "missing_exclusive_selection" then
          user_lines[#user_lines + 1] =
            "line " .. tostring(e.line)
            .. " runs the native action without exclusive target-track selection"
        elseif e.kind == "overconstrained_action_lookup" then
          user_lines[#user_lines + 1] =
            "line " .. tostring(e.line)
            .. " requires too many words in one timecode-generator action lookup"
        end
      end
      Log.add_error((RA and RA.t and RA.t(
        "validator.timecode_generator_workflow_blocked",
        { details = tbl_concat(user_lines, "; ") },
        "The model still did not safely find, insert, or bind the native timecode generator item to the routed hardware-output track, even after a retry: "
          .. tbl_concat(user_lines, "; ")
          .. ". Auto-run is blocked; review the generated action lookup, track selection, and hardware output send category before running manually."))
        or ("The model still did not safely find, insert, or bind the native timecode generator item to the routed hardware-output track, even after a retry: "
          .. tbl_concat(user_lines, "; ")
          .. ". Auto-run is blocked; review the generated action lookup, track selection, and hardware output send category before running manually."))
    end
  end

  -- TIMECODE-FX VALIDATOR: SMPTE/LTC/MTC generation is a native REAPER
  -- action/item workflow, not an FX plugin. If the model tries to load a
  -- timecode-looking TrackFX/TakeFX for a generator prompt, retry with native
  -- action lookup and explicit output routing guidance before auto-run.
  local timecodefx_gate_hit = false
  if lua_code and not docs_gate_hit and not validator_gate_hit
     and not arity_gate_hit and not sendidx_gate_hit
     and not timecode_workflow_gate_hit then
    local timecodefx_bad = Code.find_timecode_generator_fx_misuse(
      lua_code, S.pending_orig_prompt or "")
    if timecodefx_bad and #timecodefx_bad > 0 then
      if (S.timecodefx_validator_retries or 0) < 1 then
        S.timecodefx_validator_retries =
          (S.timecodefx_validator_retries or 0) + 1
        local lines = {}
        for _, e in ipairs(timecodefx_bad) do
          lines[#lines + 1] = "  - line " .. tostring(e.line)
            .. ": " .. tostring(e.fn) .. " tried to load `"
            .. tostring(e.plugin) .. "` as an FX plugin"
        end
        Log.line("TIMECODEFX-VALIDATOR",
          "timecode generator loaded as FX (" .. #timecodefx_bad
          .. "); retrying with native workflow hint (user-invisible)")
        local history_content = "(INTERNAL NOTE TO THE MODEL -- DO NOT "
          .. "MENTION ANY OF THIS IN YOUR VISIBLE REPLY: The user asked to "
          .. "insert/create/generate SMPTE/LTC/MTC timecode, but your "
          .. "previous reply tried to load timecode as an FX plugin:\n"
          .. tbl_concat(lines, "\n") .. "\n\n"
          .. "SMPTE/LTC/MTC timecode GENERATION is not a TrackFX_AddByName "
          .. "or TakeFX_AddByName task. Do NOT call TrackFX_AddByName or "
          .. "TakeFX_AddByName for SMPTE/LTC/MTC/timecode generator names, "
          .. "including JS: ltc-generator or SMPTE LTC Reader/Generator.\n\n"
          .. "Use REAPER's native action-list workflow instead: enumerate "
          .. "Main-section actions with kbd_enumerateActions/"
          .. "kbd_getTextFromCmd, find an action whose display text contains "
          .. "timecode or SMPTE/LTC/MTC plus generator, and run that verified "
          .. "command with Main_OnCommand. Do not hard-code an unverified "
          .. "numeric action ID.\n\n"
          .. "If the user asks for output only on channels/outputs 3 and 4, "
          .. "explicitly route the generator track to hardware outputs 3/4: "
          .. "create a hardware send with CreateTrackSend(track, nil), "
          .. "check send index >= 0, then set send attributes with category "
          .. "1 because nil destination creates a hardware output: "
          .. "SetTrackSendInfo_Value(track, 1, sidx, \"I_SRCCHAN\", 0) and "
          .. "SetTrackSendInfo_Value(track, 1, sidx, \"I_DSTCHAN\", 2). "
          .. "Disable B_MAINSEND when the request excludes the master/main "
          .. "outputs. Do not rely on I_NCHAN=4 alone; that only changes the "
          .. "track channel count.\n\n"
          .. "Regenerate the FULL script using the native action/item "
          .. "workflow and preserving the requested routing. Respond as if "
          .. "this is your FIRST reply -- do NOT apologize, do NOT mention "
          .. "a retry.)\n\n"
          .. "USER REQUEST:\n" .. (S.pending_orig_prompt or "")
        Net.fire_validator_retry({
          kind = "timecodefx",
          history_content = history_content,
          ctx_label = "timecodefx_retry",
          retry_failed_key = "retry.reason.for_timecode_generator_fx_repair",
          retry_failed_label = "for native timecode generator repair",
          failure_message = "Auto-retry for native timecode generator repair did not go through. Please resend the last message.",
        })
        return
      end
      timecodefx_gate_hit = true
      Log.line("TIMECODEFX-VALIDATOR",
        "timecode generator still loaded as FX after retry; auto-run blocked")
      local user_lines = {}
      for _, e in ipairs(timecodefx_bad) do
        user_lines[#user_lines + 1] = tostring(e.plugin)
          .. " via " .. tostring(e.fn)
      end
      Log.add_error((RA and RA.t and RA.t(
        "validator.timecode_generator_fx_blocked",
        { plugins = tbl_concat(user_lines, "; ") },
        "The model tried to insert/generate SMPTE/LTC/MTC timecode as an FX plugin, even after a retry: "
          .. tbl_concat(user_lines, "; ")
          .. ". Auto-run is blocked; use REAPER's native timecode generator action/item workflow and route outputs explicitly."))
        or ("The model tried to insert/generate SMPTE/LTC/MTC timecode as an FX plugin, even after a retry: "
          .. tbl_concat(user_lines, "; ")
          .. ". Auto-run is blocked; use REAPER's native timecode generator action/item workflow and route outputs explicitly."))
    end
  end


  -- FX-RECFX VALIDATOR: TrackFX_AddByName's third argument is recFX
  -- (input/record FX), not "is instrument". Lower-tier models sometimes pass
  -- true for ReaSynth/VSTi helpers, causing the FX to land outside the normal
  -- track FX chain while the script reports success.
  local fxrecfx_gate_hit = false
  if lua_code and not docs_gate_hit and not validator_gate_hit
     and not arity_gate_hit and not sendidx_gate_hit
     and not timecode_workflow_gate_hit and not timecodefx_gate_hit then
    local recfx_bad = Code.find_trackfx_addbyname_recfx_misuse
      and Code.find_trackfx_addbyname_recfx_misuse(lua_code,
        S.pending_orig_prompt)
    if recfx_bad and #recfx_bad > 0 then
      if (S.fxrecfx_validator_retries or 0) < 1 then
        S.fxrecfx_validator_retries =
          (S.fxrecfx_validator_retries or 0) + 1
        local lines = {}
        for _, e in ipairs(recfx_bad) do
          lines[#lines+1] = "  - " .. tostring(e.kind or "recfx_true")
            .. " near line " .. tostring(e.line)
            .. (e.detail and (" (" .. tostring(e.detail) .. ")") or "")
        end
        Log.line("FX-RECFX-VALIDATOR",
          "TrackFX_AddByName recFX=true pattern(s) (" .. #recfx_bad
          .. "); retrying with hint (user-invisible)")
        local history_content = "(INTERNAL NOTE TO THE MODEL -- DO NOT MENTION "
          .. "ANY OF THIS IN YOUR VISIBLE REPLY: Your previous reply passed "
          .. "`true` as the third argument to reaper.TrackFX_AddByName for "
          .. "normal track FX/instrument insertion. That third argument is "
          .. "`recFX` (input/record FX), NOT \"is instrument\". Passing true "
          .. "places the plugin in the record/input FX chain, so the normal "
          .. "track FX chain will be missing the requested ReaSynth/plugin.\n\n"
          .. "Affected call(s):\n"
          .. tbl_concat(lines, "\n") .. "\n\n"
          .. "Regenerate the code so normal track FX and instruments use:\n"
          .. "  local fx = reaper.TrackFX_AddByName(track, \"<name>\", false, -1)\n"
          .. "  if fx < 0 then return end\n\n"
          .. "Do not use helper parameters named isVSTi/isInstrument as the "
          .. "recFX argument. The instrument/plugin name belongs in the second "
          .. "argument; the third argument should stay false unless the user "
          .. "explicitly asks for input FX or record FX. Respond as if this is "
          .. "your FIRST reply -- do NOT apologize, do NOT mention a retry.)\n\n"
          .. "USER REQUEST:\n" .. (S.pending_orig_prompt or "")
        Net.fire_validator_retry({
          kind = "trackfx_recfx",
          history_content = history_content,
          ctx_label = "fxrecfx_retry",
          retry_failed_key = "retry.reason.for_trackfx_recfx_argument",
          retry_failed_label = "for TrackFX_AddByName recFX argument",
          failure_message = "Auto-retry for TrackFX_AddByName recFX argument did not go through. Please resend the last message.",
        })
        return
      end
      fxrecfx_gate_hit = true
      validator_gate_hit = true
      Log.line("FX-RECFX-VALIDATOR",
        "TrackFX_AddByName recFX=true pattern(s) persist after retry; auto-run blocked")
      local user_lines = {}
      for _, e in ipairs(recfx_bad) do
        user_lines[#user_lines+1] = tostring(e.kind or "recFX=true")
          .. " (line ~" .. tostring(e.line) .. ")"
      end
      Log.add_error((RA and RA.t and RA.t(
        "validator.fx_trackfx_recfx_blocked",
        { calls = tbl_concat(user_lines, ", ") },
        "The model passed true as the TrackFX_AddByName recFX argument "
          .. "for normal track FX, even after a retry: "
          .. tbl_concat(user_lines, ", ")
          .. ". Auto-run is blocked because the plugin would be added as "
          .. "input/record FX instead of normal track FX."))
        or ("The model passed true as the TrackFX_AddByName recFX argument for normal track FX, even after a retry: "
          .. tbl_concat(user_lines, ", ")
          .. ". Auto-run is blocked because the plugin would be added as input/record FX instead of normal track FX."))
    end
  end

  -- FX-CHECK VALIDATOR: After the API/arity validators pass, scan
  -- generated code for `local NAME = reaper.(Track|Take)FX_AddByName(...)`
  -- where NAME is never tested in a failure-direction comparison
  -- (NAME < 0 / NAME == -1 / NAME <= -1 / NAME < -1). Catches two
  -- silent-success patterns the model has shown:
  --   1. local fx = TrackFX_AddByName(...); -- no check, downstream
  --      use assumes fx is valid; failure produces silent skip + script
  --      reports OK.
  --   2. local fx = TrackFX_AddByName(...); if fx >= 0 then ... end
  --      with no else and no error -- the success-direction-only check
  --      means a failed AddByName silently skips configuration. The
  --      script appears to succeed but the chain is broken.
  -- Same recovery shape as the other validators: hidden retry with a
  -- focused hint, single retry per turn, auto-run blocked + visible
  -- error if the retry still fails. GetByName is covered by the narrower
  -- dependent-use validator below because returning -1 is a legitimate
  -- "not present" signal in upsert patterns.
  local fxcheck_gate_hit = false
  if lua_code and not docs_gate_hit and not validator_gate_hit
     and not arity_gate_hit and not sendidx_gate_hit
     and not timecode_workflow_gate_hit and not timecodefx_gate_hit then
    local unchecked = Code.find_unchecked_addbyname_results(lua_code)
    if unchecked and #unchecked > 0 then
      if (S.fxcheck_validator_retries or 0) < 1 then
        S.fxcheck_validator_retries = (S.fxcheck_validator_retries or 0) + 1
        local lines = {}
        for _, e in ipairs(unchecked) do
          if e.multi_assign then
            lines[#lines+1] = "  - multiple assignment `"
              .. tostring(e.lhs or e.name)
              .. "` from TrackFX_AddByName / TakeFX_AddByName near line "
              .. e.line
          elseif e.unassigned then
            lines[#lines+1] = "  - unassigned TrackFX_AddByName / "
              .. "TakeFX_AddByName result near line " .. e.line
          else
            lines[#lines+1] = "  - " .. e.name
              .. " (assigned from TrackFX_AddByName / TakeFX_AddByName near "
              .. "line " .. e.line .. ")"
          end
        end
        Log.line("FX-CHECK-VALIDATOR",
          "unchecked AddByName result(s) (" .. #unchecked .. "): "
          .. (function()
              local names = {}
              for _, e in ipairs(unchecked) do names[#names+1] = e.name end
              return tbl_concat(names, ", ")
            end)()
          .. "; retrying with hint (user-invisible)")
        local history_content = Net._fxcheck_retry_history(lua_code, lines)
        Net.fire_validator_retry({
          kind = "fxcheck",
          history_content = history_content,
          ctx_label = "fxcheck_retry",
          retry_failed_key = "retry.reason.for_unchecked_addbyname_result",
          retry_failed_label = "for unchecked AddByName result",
          failure_message = "Auto-retry for unchecked AddByName result did not go through. Please resend the last message.",
        })
        return
      end
      fxcheck_gate_hit = true
      Log.line("FX-CHECK-VALIDATOR",
        "unchecked AddByName result(s) persist after retry; auto-run blocked")
      local user_lines = {}
      for _, e in ipairs(unchecked) do
        user_lines[#user_lines+1] = e.name .. " (line ~" .. e.line .. ")"
      end
      Log.add_error((RA and RA.t and RA.t(
        "validator.fx_addbyname_unchecked_blocked",
        { vars = tbl_concat(user_lines, ", ") },
        "The model wrote TrackFX_AddByName / TakeFX_AddByName "
          .. "without checking the result, even after a retry: "
          .. tbl_concat(user_lines, ", ")
          .. ". If the plugin fails to load the script will silently report "
          .. "success. Auto-run is blocked; review and edit the code before "
          .. "clicking Run manually."))
        or ("The model wrote TrackFX_AddByName / TakeFX_AddByName without checking the result, even after a retry: "
          .. tbl_concat(user_lines, ", ")
          .. ". If the plugin fails to load the script will silently report success. Auto-run is blocked; review and edit the code before clicking Run manually."))
    end
  end

  -- FX-IDENT VALIDATOR: identity and preference in one pass, one validator
  -- kind (`fxident`). Two outcomes fault. An identifier the static pass can
  -- resolve that is missing from the installed list would reach
  -- TrackFX_AddByName and return -1 (`ReaTransient` and `ReaSat` both did on
  -- 2026-09-10). A resolved identifier that bypasses the user's saved
  -- preference for an established role writes a stock plug-in over a product
  -- the user chose. Anything the static pass cannot establish is unknown: it
  -- runs as before and the existing runtime notice still covers it.
  local fxident_gate_hit = false
  -- The structured fault detail the completed response carries. Log.add_error
  -- writes its own transcript entry, but the assistant response for the turn
  -- is appended after it, and that later entry is the one the Screen Reader
  -- reads as the latest response. Both interfaces read this field off the
  -- completed response so the spoken and the visual answer name the plug-ins.
  local fxident_block_detail = nil
  if lua_code and not docs_gate_hit and not validator_gate_hit
     and not arity_gate_hit and not sendidx_gate_hit
     and not timecode_workflow_gate_hit and not timecodefx_gate_hit
     and not fxcheck_gate_hit
     and type(Code.find_fx_identifier_faults) == "function" then
    local installed_entries, enumeration_available = nil, false
    if type(CTX) == "table" and type(CTX.populate_installed_fx) == "function" then
      local ok, list = pcall(CTX.populate_installed_fx)
      enumeration_available = ok and list ~= nil
      installed_entries = CTX._installed_fx_entries
    end
    local reeq_state = "unknown"
    if type(Code.is_reeq_installed) == "function" then
      local ok, present = pcall(Code.is_reeq_installed)
      if ok then reeq_state = present and "present" or "absent" end
    end
    -- The effective preferences, not the raw saved ones: a role whose
    -- identifier the current enumeration filter hides is left out of the
    -- pinned pref_map, so enforcing it here would fault a stock fallback for a
    -- preference the model was never shown. One view feeds the map, the
    -- validation and the retry hint.
    local pref_types = {}
    local hidden_prefs = {}
    if FXCache and type(FXCache.get_preferred_types) == "function" then
      local ok, saved = pcall(FXCache.get_preferred_types)
      if ok and type(saved) == "table" then
        if type(CTX) == "table"
            and type(CTX.effective_preferred_types) == "function" then
          local view_ok, effective, hidden =
            pcall(CTX.effective_preferred_types, saved)
          if view_ok and type(effective) == "table" then
            pref_types = effective
            hidden_prefs = type(hidden) == "table" and hidden or {}
          end
        end
        if next(pref_types) == nil and next(hidden_prefs) == nil then
          for tkey, ident in pairs(saved) do
            if type(ident) == "string" and ident ~= "" then
              pref_types[tostring(tkey):lower()] = ident
            end
          end
        end
      end
    end
    for tkey in pairs(hidden_prefs) do
      Log.line("FX-IDENT-VALIDATOR",
        "saved preference for the " .. tostring(tkey)
        .. " role is hidden by the current enumeration filter; not enforced")
    end
    -- The plug-in source rule of plan section 7.4: a word-bounded "stock",
    -- "cockos" or "third-party" anywhere in the prompt exempts every role for
    -- this turn. No clause reading of any kind.
    local stock_only = type(Code.prompt_names_fx_source) == "function"
      and Code.prompt_names_fx_source(S.pending_orig_prompt) == true
    if stock_only then
      Log.line("FX-IDENT-VALIDATOR",
        "the prompt names a plug-in source, so no role takes a preference "
        .. "repair this turn")
    end
    -- A static pass that raised would block a turn that has nothing wrong with
    -- it, so a failure here is treated as "nothing established": the code runs
    -- as before and the existing runtime notice still covers a failed insert.
    local scan_ok, faults, fx_notes = pcall(Code.find_fx_identifier_faults,
      lua_code, {
        installed_entries = installed_entries,
        enumeration_available = enumeration_available,
        preferred_types = pref_types,
        user_text = S.pending_orig_prompt or "",
        reeq_state = reeq_state,
        stock_only = stock_only,
        stock_role_for_identifier = FXCache
          and FXCache.preferred_identifier_type or nil,
        hidden_identifier = type(CTX) == "table"
          and CTX.identifier_hidden_by_fx_filter or nil,
      })
    if not scan_ok then
      Log.line("FX-IDENT-VALIDATOR",
        "scan failed; every identifier stays unknown: " .. tostring(faults))
      faults, fx_notes = nil, nil
    end
    for _, entry in ipairs(fx_notes or {}) do
      Log.line("FX-IDENT-VALIDATOR", entry)
    end
    if not faults or #faults == 0 then
      Log.line("FX-IDENT-VALIDATOR",
        "scanned AddByName identifiers, no identity or preference fault"
        .. " (catalog=" .. (enumeration_available and "available" or "unavailable")
        .. ", rows=" .. tostring(installed_entries and #installed_entries or 0)
        .. ", stock_only=" .. tostring(stock_only) .. ")")
    end
    if faults and #faults > 0 then
      -- One hidden repair fires on any finding. What may follow it is one
      -- thing only: a visible block for an identifier that is missing at high
      -- confidence, which is an identifier REAPER cannot load. A preference
      -- finding never blocks, whatever the repair comes back with; the script
      -- runs and the substitution notice states what ran.
      local all_missing, all_missing_seen = {}, {}
      local missing_names, missing_seen = {}, {}
      local low_missing_names = {}
      local preference_lines, preference_seen = {}, {}
      local preferred_idents = {}
      for _, fault in ipairs(faults) do
        if fault.kind == "missing" then
          local name = tostring(fault.identifier or "")
          if name ~= "" and not all_missing_seen[name] then
            all_missing_seen[name] = true
            all_missing[#all_missing + 1] = name
          end
          if name ~= "" and not missing_seen[name] then
            missing_seen[name] = true
            if fault.confidence == "high" then
              missing_names[#missing_names + 1] = name
            else
              low_missing_names[#low_missing_names + 1] = name
            end
          end
        else
          local line = tostring(fault.identifier or "") .. " for the "
            .. tostring(fault.role or "?") .. " role instead of "
            .. tostring(fault.preference or "?")
          if not preference_seen[line] then
            preference_seen[line] = true
            preference_lines[#preference_lines + 1] = line
          end
        end
      end
      local pref_keys = {}
      for tkey in pairs(pref_types) do pref_keys[#pref_keys + 1] = tkey end
      table.sort(pref_keys)
      for _, tkey in ipairs(pref_keys) do
        preferred_idents[#preferred_idents + 1] = tkey .. " = " .. pref_types[tkey]
      end
      -- PREFERENCE FINDINGS NEVER STOP A RUN (plan section 7.2, invariants
      -- I1 and I2). When the only findings are preference findings the repair
      -- improves a script that is already safe to run, so a budget that is
      -- already spent and a dispatch that never left the machine both continue
      -- through the remaining validation and the execution path with the
      -- original candidate, exactly once, instead of ending the turn. The caps
      -- are read HERE because the abort they take inside Net.fire_curl clears
      -- the pending turn state the run needs. An identity finding keeps its
      -- existing behaviour, and a cancellation still stops execution.
      -- The one name for this repair, read by the budget projection below and
      -- by the dispatch further down, so the event the gate weighs and the
      -- event it fires cannot become two different kinds.
      local repair_kind = "fxident"
      local preference_only = #all_missing == 0 and #preference_lines > 0
      local repair_already_made = (S.fxident_validator_retries or 0) >= 1
      local repair_admitted = true
      if preference_only then
        local spent_reason = nil
        -- THE PROPOSED RETRY IS PART OF WHAT IS BEING WEIGHED. The budget is
        -- read here with the `fxident` event this gate would cause projected
        -- into it, because the transport reads the same rule after that event
        -- has been counted. Reading the current state instead would let four
        -- completed repairs of four distinct kinds answer "allowed", and the
        -- fifth kind would then be refused inside Net.fire_curl, whose abort
        -- ends the turn and takes the candidate with it.
        if type(Net) == "table"
            and type(Net._validator_retry_budget_state) == "function" then
          local budget_ok, budget = pcall(Net._validator_retry_budget_state,
            repair_kind)
          if budget_ok and type(budget) == "table"
              and budget.allowed == false then
            spent_reason = tostring(budget.mode or "exhausted")
          end
        end
        local call_cap = tonumber(CFG and CFG.MAX_CALLS_PER_TURN)
        if spent_reason == nil and call_cap
            and (S.api_calls_this_turn or 0) >= call_cap then
          spent_reason = "call cap"
        end
        if spent_reason then
          repair_admitted = false
          Log.line("FX-IDENT-VALIDATOR",
            "the turn's retry budget is spent (" .. spent_reason
            .. "), so no preference repair is dispatched and the original "
            .. "script continues to the run")
        end
      end
      if repair_admitted and (S.fxident_validator_retries or 0) < 1 then
        S.fxident_validator_retries = (S.fxident_validator_retries or 0) + 1
        Log.line("FX-IDENT-VALIDATOR",
          "missing identifier(s): " .. (#all_missing > 0
            and tbl_concat(all_missing, ", ") or "none")
          .. "; unused preference(s): " .. (#preference_lines > 0
            and tbl_concat(preference_lines, "; ") or "none")
          .. "; one hidden repair (user-invisible)")
        local hint_parts = {}
        if #all_missing > 0 then
          local missing_lines = {}
          for _, name in ipairs(all_missing) do
            local stem = name:gsub("^%s*[%a][%w]*%s*:%s*", "")
              :gsub("%s*%b()%s*$", "")
            local suggestion = nil
            if type(CTX) == "table" and type(CTX.installed_fx) == "function"
                and stem ~= "" then
              -- X-02: this note regenerates the FULL script as a first
              -- reply, so its no-match sentence must not tell the model to
              -- ask the user for a name or to drop the step. "repair_note"
              -- is what selects that reading.
              local ok, matches = pcall(CTX.installed_fx, { stem },
                "repair_note")
              if ok and type(matches) == "string" then
                suggestion = matches
              end
            end
            missing_lines[#missing_lines + 1] = "  - `" .. name
              .. "` is not installed on this system."
              .. (suggestion and ("\n" .. suggestion) or "")
          end
          hint_parts[#hint_parts + 1] =
            "These plug-in identifiers are not in this system's installed "
            .. "list, so TrackFX_AddByName / TakeFX_AddByName would return "
            .. "-1:\n" .. tbl_concat(missing_lines, "\n")
        end
        if #preference_lines > 0 then
          hint_parts[#hint_parts + 1] =
            "These generic roles were written with a plug-in the user did "
            .. "not ask for, over a saved preference:\n  - "
            .. tbl_concat(preference_lines, "\n  - ")
        end
        if #preferred_idents > 0 then
          hint_parts[#hint_parts + 1] =
            "The user's saved preferences are:\n  "
            .. tbl_concat(preferred_idents, "\n  ")
        end
        -- The repair instruction is confined to PLUG-IN CHOICE. It changes
        -- which product a role gets and nothing else, and the user's own
        -- request stands below it, verbatim and unaltered, as the statement of
        -- what the script has to do.
        local history_content = "(INTERNAL NOTE TO THE MODEL -- DO NOT MENTION "
          .. "ANY OF THIS IN YOUR VISIBLE REPLY: "
          .. tbl_concat(hint_parts, "\n\n") .. "\n\n"
          .. "Regenerate the FULL script. Change the PLUG-IN CHOICE only: "
          .. "every operation, target, parameter and step the user asked for "
          .. "stays exactly as it is. Keep a product the user named. For a "
          .. "generic role with a saved preference, use that preference. Use "
          .. "an identifier from the pinned references, from the installed "
          .. "list above, or exactly what the user named. Request "
          .. "<context_needed>resolve:<type></context_needed> only for a "
          .. "generic role with no saved preference listed above. Never write "
          .. "a plug-in name from memory. Respond as if this is your "
          .. "FIRST reply -- do NOT apologize, do NOT mention a retry.)\n\n"
          .. (S.pending_output_note or "")
          .. "The user's request follows, unchanged. It is the whole of what "
          .. "the script has to do.\n\nUSER REQUEST:\n"
          .. (S.pending_orig_prompt or "")
        local dispatch_ok, dispatch_reason = Net.fire_validator_retry({
          kind = repair_kind,
          history_content = history_content,
          ctx_label = "fxident_retry",
          retry_failed_key = "retry.reason.for_plugin_identifier",
          retry_failed_label = "for plug-in identity and preference",
          failure_message = "Auto-retry for plug-in identity and preference did not go through. Please resend the last message.",
          continue_on_failed_dispatch = preference_only,
        })
        -- A dispatch that never left the machine keeps the original candidate,
        -- which Net.fire_validator_retry puts back, so a preference-only
        -- repair continues from here. Two failures do not continue:
        -- call_cap_exceeded means the dispatcher already ended the turn, and
        -- kill_pending means a cancel is being carried out, and a cancelled
        -- turn runs nothing.
        local dispatch_ended_turn = dispatch_reason == "call_cap_exceeded"
          or dispatch_reason == "kill_pending"
        if not (preference_only and dispatch_ok == false
            and not dispatch_ended_turn) then
          return
        end
        Log.line("FX-IDENT-VALIDATOR",
          "the preference repair did not dispatch; the original script "
          .. "continues to the run")
      end
      if #low_missing_names > 0 then
        Log.line("FX-IDENT-VALIDATOR",
          "missing-low-confidence after the repair, "
          .. (#missing_names == 0 and "running: " or "named beside the block: ")
          .. tbl_concat(low_missing_names, ", ")
          .. " (an enumerated name or ident contains the stem, so REAPER's "
          .. "own matching may accept it)")
      end
      if #preference_lines > 0 then
        Log.line("FX-IDENT-VALIDATOR",
          (repair_already_made
            and "the repair left the saved preference unused, running: "
            or "no repair was made, running: ")
          .. tbl_concat(preference_lines, "; ")
          .. " (preferences never block; the completion notice states what "
          .. "ran)")
      end
      if #missing_names == 0 then
        Log.line("FX-IDENT-VALIDATOR",
          "no high-confidence missing identifier after the repair; auto-run "
          .. "not blocked")
      else
        fxident_gate_hit = true
        validator_gate_hit = true
        -- ROUND TWENTY, V-06: the block names EVERY identifier the scan could
        -- not match against the installed catalog, not only the ones it blocks
        -- on. A low-confidence name stem-matches an installed row, so it may
        -- still load and never blocks; naming it here is what stops a model
        -- from repairing one fault, coming back, and being blocked a second
        -- time on a fault this scan already knew about. One renderer builds
        -- the sentences for the error entry and for the transcript, so the two
        -- cannot drift apart.
        fxident_block_detail = {
          missing = missing_names,
          unmatched = low_missing_names,
        }
        Log.line("FX-IDENT-VALIDATOR",
          "missing identifier(s) persist after the repair; auto-run blocked: "
          .. tbl_concat(missing_names, ", ")
          .. (#low_missing_names > 0
            and ("; also unmatched: " .. tbl_concat(low_missing_names, ", "))
            or ""))
        local block_message = type(Code.fx_identifier_block_message)
            == "function"
          and Code.fx_identifier_block_message(fxident_block_detail,
            RA and RA.t)
          or nil
        Log.add_error(block_message
          or ("The generated script uses plug-ins that are not installed on this system, even after a retry: "
            .. tbl_concat(missing_names, ", ")
            .. ". Auto-run is blocked because those plug-ins cannot load. Install them, or ask for the chain again with plug-ins you have."))
      end
    end
  end

  -- HELPER-DEFINITION VALIDATOR: Scan for
  -- helper function calls (find_param, set_param_display, set_param_enum,
  -- set_param_enum_paced) that lack a matching `local function NAME(`
  -- definition in the same script. The model has seen these helpers in
  -- training data and CAN write the calls from memory without including
  -- the source -- producing a runtime `attempt to call a nil value` crash
  -- on the deferred tick. The plugin_helpers prompt bundle is the source
  -- of truth; this validator catches the case where the call ships without
  -- the definition. Same recovery shape as the other validators: model-
  -- only nudge with the helper bundle pinned. Permit one additional helper
  -- repair when a different validator's rewrite reintroduces the omission;
  -- the aggregate per-turn retry cap remains the hard ceiling.
  -- auto-run block + visible error if it persists.
  local helper_gate_hit = false
  if lua_code
     and not docs_gate_hit and not validator_gate_hit
     and not arity_gate_hit and not sendidx_gate_hit
     and not timecode_workflow_gate_hit and not timecodefx_gate_hit
     and not fxcheck_gate_hit then
    local missing = Code.find_helper_calls_without_definition(lua_code)
    if missing and #missing > 0 then
      if (S.helper_validator_retries or 0) < 2 then
        S.helper_validator_retries = (S.helper_validator_retries or 0) + 1
        Log.line("HELPER-VALIDATOR",
          "helper/global calls without definitions (" .. #missing .. "): "
          .. tbl_concat(missing, ", ")
          .. "; retrying (user-invisible)")
        -- Build load- and renderer-aware guidance for canonical plugin
        -- helpers. Ad-hoc names still get the general "define before first
        -- use or inline the operation" nudge above.
        local history_content = "(INTERNAL NOTE TO THE MODEL -- DO NOT MENTION "
          .. "ANY OF THIS IN YOUR VISIBLE REPLY: Your previous reply called "
          .. "bare helper/global function(s) without a usable in-script definition. The "
          .. "definition was either missing OR placed LEXICALLY AFTER the "
          .. "first call site -- in Lua, a `local function NAME(...)` "
          .. "declared after the line that calls it is not yet a visible "
          .. "local at that line, so the call compiles to a global lookup "
          .. "and crashes at runtime with `attempt to call a nil value`. "
          .. "This can happen in normal top-level code or inside deferred "
          .. "callbacks.\n\n"
          .. "Affected helper(s):\n  - "
          .. tbl_concat(missing, "\n  - ")
          .. "\n\nRegenerate the FULL script NOW. For each affected helper, "
          .. "either paste a complete `local function NAME(...) ... end` "
          .. "definition at the TOP of the script before any call site, or "
          .. "remove the helper call and use direct REAPER API calls inline. "
          .. "For send-volume helpers, call "
          .. "`reaper.SetTrackSendInfo_Value(track, 0, send_index, "
          .. "\"D_VOL\", 10 ^ (db / 20))` directly or define the helper "
          .. "before it is called. "
          .. Net.plugin_helpers_retry_guidance(false)
          .. "Do NOT emit "
          .. "<context_needed>prompt_bundle:plugin_helpers</context_needed> "
          .. "or any other <context_needed> tag. Put the entire replacement "
          .. "script inside one complete ```lua code fence. Do not place any "
          .. "Lua before or after that fence. Respond as if this is your "
          .. "FIRST reply to the user's request -- do NOT apologize, do NOT "
          .. "say 'let me try again', do NOT mention a retry.)\n\n"
          .. "USER REQUEST:\n" .. (S.pending_orig_prompt or "")
        Net.fire_validator_retry({
          kind = "helper",
          history_content = history_content,
          ctx_label = "helper_retry",
          retry_failed_key = "retry.reason.for_missing_helper_definitions",
          retry_failed_label = "for missing helper definitions",
          failure_message = "Auto-retry for missing helper definitions did not go through. Please resend the last message.",
        })
        return
      end
      -- Retry already used and the model STILL emitted helper calls without
      -- definitions. Block auto-run + surface diagnostic.
      helper_gate_hit = true
      Log.line("HELPER-VALIDATOR",
        "helper/global calls still missing definitions after retry: "
        .. tbl_concat(missing, ", ") .. "; auto-run blocked")
      Log.add_error((RA and RA.t and RA.t(
        "validator.missing_helper_definitions_blocked",
        { helpers = tbl_concat(missing, ", ") },
        "The model called helper/global function(s) without including "
          .. "their definitions, even after a retry: "
          .. tbl_concat(missing, ", ")
          .. ". These are not REAPER built-ins, so the "
          .. "script will crash at runtime with 'attempt to call a nil value' "
          .. "when these are reached. Auto-run is blocked; define each "
          .. "helper before its first call or replace it with direct REAPER "
          .. "API calls before running manually."))
        or ("The model called helper function(s) without including their definitions, even after a retry: "
          .. tbl_concat(missing, ", ")
          .. ". These are not REAPER built-ins, so the script will crash at runtime with 'attempt to call a nil value' when these are reached. Auto-run is blocked; define each helper before its first call or replace it with direct REAPER API calls before running manually."))
    end
  end


  -- JSFX VALIDATOR: After the Lua-focused validators, statically analyze
  -- generated JSFX before it gets auto-saved + auto-loaded. Catches EEL2
  -- syntax that won't compile (`{}`, `else`, `for(...)`, `math.X`, `reaper.X`)
  -- plus safety violations from Prompts.md (unclamped feedback >0.85, hard
  -- clipping without explicit user request, indexed memory with no base
  -- assignment). Same recovery shape as the other validators: model-only
  -- nudge, scrub the bad turn from history, single retry per turn, surface
  -- a visible error if the retry still fails.
  --
  -- Calibrated against C:\REAPER\Effects (264 standalone stock + community
  -- JSFX); each rule's false-positive rate sits at or below ~3.5%. See
  -- Code.validate_jsfx and Dev/Tests/corpus_audit.lua for details.
  local jsfx_gate_hit = false
  -- Single source of truth for any validator block this turn. Defined after
  -- all validator flags so the run and reporting paths use the same list.
  local function _any_gate_hit()
    return docs_gate_hit
        or action_relevance_gate_hit
        or validator_gate_hit
        or marker_pair_gate_hit
        or action_gate_hit
        or toolbar_gate_hit
        or tempo_marker_gate_hit
        or project_tempo_gate_hit
        or loop_time_map_gate_hit
        or ruler_timebase_gate_hit
        or transient_gate_hit
        or audio_sync_gate_hit
        or audio_accessor_nil_gate_hit
        or drum_quantize_gate_hit
        or drum_marker_sync_gate_hit
        or arity_gate_hit
        or media_item_label_gate_hit
        or sendidx_gate_hit
        or timecode_workflow_gate_hit
        or timecodefx_gate_hit
        or fxrecfx_gate_hit
        or fxcheck_gate_hit
        or fxident_gate_hit
        or helper_gate_hit
        or unqualified_reaper_api_gate_hit
        or midi_record_mode_gate_hit
        or midi_input_gate_hit
        or jsfx_format_gate_hit
        or jsfx_wrong_artifact_gate_hit
        or jsfx_gate_hit
  end
  local function _auto_run_block_reason()
    if docs_gate_hit then return "docs_gate" end
    if action_relevance_gate_hit then return "action_relevance_review" end
    if marker_pair_gate_hit then return "marker_pair_validator" end
    if midi_record_mode_gate_hit then return "midi_record_mode_review" end
    if midi_input_gate_hit then
      return midi_input_block_kind or "midi_input_validator"
    end
    if tempo_marker_gate_hit then return "tempo_marker_validator" end
    if project_tempo_gate_hit then return "project_tempo_validator" end
    if loop_time_map_gate_hit then return "loop_time_map_validator" end
    if ruler_timebase_gate_hit then return "ruler_timebase_validator" end
    if audio_accessor_nil_gate_hit then return "audio_accessor_samples_nil_validator" end
    if unqualified_reaper_api_gate_hit then
      return "unqualified_reaper_api_validator"
    end
    -- The two FX plug-in gates keep their own diagnostic kind. The identity
    -- gate raises the shared validator flag to stop the downstream
    -- validators, so it has to answer before the generic rollup or both
    -- interfaces would render "validation flagged this script" and drop the
    -- plug-in names.
    if fxcheck_gate_hit then return "fx_check_validator" end
    if fxident_gate_hit then return "fx_ident_validator" end
    if validator_gate_hit then return "validator_gate" end
    if action_gate_hit then return "action_context_validator" end
    if toolbar_gate_hit then return "toolbar_validator" end
    if transient_gate_hit then return "transient_validator" end
    if audio_sync_gate_hit then return "audio_sync_validator" end
    if drum_quantize_gate_hit then return "drum_quantize_validator" end
    if drum_marker_sync_gate_hit then return "drum_marker_sync_validator" end
    if arity_gate_hit then return "arity_validator" end
    if media_item_label_gate_hit then return "media_item_label_validator" end
    if sendidx_gate_hit then return "send_index_validator" end
    if timecode_workflow_gate_hit then return "timecode_workflow_validator" end
    if timecodefx_gate_hit then return "timecode_fx_validator" end
    if fxrecfx_gate_hit then return "trackfx_recfx_validator" end
    if helper_gate_hit then return "helper_validator" end
    if jsfx_format_gate_hit then return "jsfx_format_validator" end
    if jsfx_wrong_artifact_gate_hit then return "jsfx_wrong_artifact_validator" end
    if jsfx_gate_hit then return "jsfx_validator" end
    -- Defensive fallback for future gate flags added to _any_gate_hit().
    if _any_gate_hit() then return "validator_gate" end
    if not prefs.auto_run then return "auto_run_disabled" end
    return nil
  end
  if jsfx_code then
    local prior_gate_hit_before_jsfx = _any_gate_hit()
    local findings = Code.validate_jsfx(jsfx_code, S.pending_orig_prompt or "")
    -- Pass log: prove the validator actively ran on this response, regardless
    -- of provider, so an unexpected silent-pass is distinguishable from a
    -- skipped-run in the debug log. Mirrors the API-VALIDATOR pass log.
    if not (findings and Code.jsfx_findings_have_gate(findings)) then
      local warn_count = 0
      if findings then
        for _, f in ipairs(findings) do
          if f.severity == "warn" then warn_count = warn_count + 1 end
        end
      end
      Log.line("JSFX-VALIDATOR",
        "scanned JSFX (" .. tostring(#jsfx_code) .. " bytes), no fatal findings"
        .. (warn_count > 0
             and (" (" .. warn_count .. " advisory)") or ""))
    end
    if findings and Code.jsfx_findings_have_gate(findings) then
      -- Distinct fatal codes for the log + user-visible error (used in both
      -- the retry path and the post-retry gate-blocked path).
      local code_summary = {}
      do
        local seen = {}
        for _, f in ipairs(findings) do
          local finding_code = tostring(f.code or "jsfx")
          if f.severity == "fatal" and not seen[finding_code] then
            seen[finding_code] = true
            code_summary[#code_summary+1] = finding_code
          end
        end
      end
      if not prior_gate_hit_before_jsfx
         and (S.jsfx_validator_retries or 0) < 1 then
        S.jsfx_validator_retries = (S.jsfx_validator_retries or 0) + 1
        -- Build per-finding lines for the retry hint. Only fatal findings
        -- count toward the gate; warns are advisory and listed for context.
        local fatal_lines, warn_lines = {}, {}
        for _, f in ipairs(findings) do
          local entry = "  - [" .. tostring(f.code or "jsfx")
            .. "] line " .. tostring(f.line)
            .. ": " .. tostring(f.message or "")
          if f.severity == "fatal" then
            fatal_lines[#fatal_lines+1] = entry
          else
            warn_lines[#warn_lines+1] = entry
          end
        end
        Log.line("JSFX-VALIDATOR",
          "JSFX failed validation (" .. #fatal_lines .. " fatal, "
          .. #warn_lines .. " warn): "
          .. tbl_concat(code_summary, ", ")
          .. "; retrying with hint (user-invisible)")
        local history_content = "(INTERNAL NOTE TO THE MODEL -- DO NOT MENTION "
          .. "ANY OF THIS IN YOUR VISIBLE REPLY: Your previous JSFX failed "
          .. "ReaAssist's static JSFX validator. The following issues MUST be "
          .. "fixed:\n"
          .. tbl_concat(fatal_lines, "\n")
          .. (#warn_lines > 0
              and ("\n\nAdvisory (not blocking, but worth addressing):\n"
                   .. tbl_concat(warn_lines, "\n"))
              or "")
          .. "\n\nRegenerate the JSFX from scratch. Keep the same user-facing "
          .. "intent, but fix every fatal issue. EEL2 reminders: no `if`/`else`/"
          .. "`{}` blocks (use ternary `cond ? (...) : (...)` and grouping `(...)`); "
          .. "no `for(...)` (use `loop(N, ...)` or `while(cond) (...)`); "
          .. "section names are singular (`@sample`, not `@samples`; `@slider`, "
          .. "not `@sliders`); bare math "
          .. "functions only (no `math.` prefix); no `reaper` identifier or "
          .. "ReaScript API calls -- use JSFX host variables such as `tempo` "
          .. "and `srate` for tempo/time math. For any "
          .. "feedback path, hard-clamp the feedback coefficient to <= 0.85, add a "
          .. "DC blocker, and use soft saturation (tanh, x/(1+|x|)) instead of "
          .. "hard clipping unless the user explicitly asked for clipping/"
          .. "limiting/distortion. Initialize every persistent variable + buffer "
          .. "base in `@init`. For simple LFO waveforms, do not build lookup "
          .. "tables; use bare sin/cos/arithmetic directly. If you use any "
          .. "`name[index]` memory/table access, assign `name = <numeric base>` "
          .. "in `@init` before use. Do not write generic `buf[base + i]` "
          .. "accesses; read and write from the initialized base variable "
          .. "directly, such as `bufferL[i]`, `bufferR[i]`, `allpassL1[i]`, "
          .. "or `combR2[i]`. Keep the exact same base variable name in "
          .. "`@init`, `@slider`, and `@sample`; if you initialize `bufferL`, "
          .. "do not later read `bufferL_base` or `bufL`. If the user named "
          .. "a DSP concept such as allpass, buffer, grain, freeze, or width, "
          .. "verify that concept is implemented; names may be abbreviated. "
          .. "Allocate every delay/comb/allpass buffer base in "
          .. "`@init` with unique non-overlapping offsets; do not initialize "
          .. "multiple buffers to `0` as placeholders or recompute bases in "
          .. "`@slider`. Respond as if this is your FIRST reply to the "
          .. "user's request -- do NOT apologize, do NOT say 'let me try again', "
          .. "do NOT mention a retry.)\n\n"
          .. "USER REQUEST:\n" .. (S.pending_orig_prompt or "")
        Net.fire_validator_retry({
          kind = "jsfx",
          history_content = history_content,
          ctx_label = "jsfx_retry",
          retry_failed_key = "retry.reason.for_invalid_jsfx",
          retry_failed_label = "for invalid JSFX",
          failure_message = "Auto-retry for invalid JSFX did not go through. Please resend the last message.",
        })
        return
      end
      -- Retry already used, or another validator already forced a visible
      -- correction this turn. In both cases, still block manual JSFX save/add
      -- from silently accepting unsafe generated effect code.
      jsfx_gate_hit = true
      local retry_used = (S.jsfx_validator_retries or 0) >= 1
      local retry_phrase = retry_used and ", even after a retry" or ""
      Log.line("JSFX-VALIDATOR",
        "JSFX fails validation" .. retry_phrase .. ": "
        .. tbl_concat(code_summary, ", ")
        .. "; auto-save and auto-run blocked")
      local message_key = retry_used
        and "validator.jsfx_safety_blocked"
        or "validator.jsfx_safety_blocked_no_retry"
      Log.add_error((RA and RA.t and RA.t(
        message_key,
        { codes = tbl_concat(code_summary, ", ") },
        "The model emitted JSFX that fails ReaAssist's safety/"
          .. "syntax validator" .. retry_phrase .. ": "
          .. tbl_concat(code_summary, ", ")
          .. ". Auto-save and auto-run are blocked; review the code carefully "
          .. "and fix the listed issues before saving manually."))
        or ("The model emitted JSFX that fails ReaAssist's safety/syntax validator"
          .. retry_phrase .. ": "
          .. tbl_concat(code_summary, ", ")
          .. ". Auto-save and auto-run are blocked; review the code carefully and fix the listed issues before saving manually."))
    end
  end

  -- =============================================================================
  -- CEILING INJECTION (chat-display-time)
  -- =============================================================================
  -- After the JSFX validator passes, inject the output-ceiling safety layer.
  -- Runs BEFORE the chat bubble is built and BEFORE auto-save, so the visible
  -- code box, the copy button, the manual Save / Add to Track buttons, and
  -- auto-save all see the SAME injected source.
  --
  -- Without this, copying from the chat would produce un-injected JSFX that
  -- skips the safety layer when the user pastes it elsewhere or hand-saves.
  --
  -- Skipped only if the JSFX validator itself blocked the JSFX, if there's no
  -- jsfx_code, or if the injector itself bails on a content check. Unrelated
  -- validator gates still allow the visible JSFX to be ceiling-injected because
  -- manual Save / Add to Track works from the displayed source.
  -- Cache the inject info so the auto-save block below (which actually
  -- knows the saved file path) can record the slot metadata.
  local ceiling_inject_info = nil
  if jsfx_code and not jsfx_gate_hit then
    local injected, info_or_reason = Code.inject_output_ceiling(jsfx_code)
    if injected then
      ceiling_inject_info = info_or_reason
      Log.line("CEILING-INJECT",
        ("injected: slot=%d slider=%d merged_options=%s created_init=%s created_slider=%s created_block=%s")
          :format(info_or_reason.slot_base, info_or_reason.slider_num,
                  tostring(info_or_reason.merged_options),
                  tostring(info_or_reason.created_init),
                  tostring(info_or_reason.created_slider),
                  tostring(info_or_reason.created_block)))
      -- Replace the JSFX fence content in the assistant message text so
      -- (a) the chat code box renders the injected version, (b) the copy
      -- button copies the injected version, and (c) any future re-extract
      -- (e.g. manual edit, history replay) sees the injected source.
      -- gsub with a function avoids %-substitution on injected.
      local replacement = function() return "```jsfx\n" .. injected .. "\n```" end
      local new_text, n = text:gsub("```jsfx[ \t\r]*\n.-%s*```", replacement, 1)
      if n == 0 then
        -- ```eel fallback (less common label).
        new_text, n = text:gsub("```eel[ \t\r]*\n.-%s*```",
          function() return "```eel\n" .. injected .. "\n```" end, 1)
      end
      if n > 0 then
        text = new_text
        if S.history[#S.history] and S.history[#S.history].role == "assistant" then
          S.history[#S.history].content = text
        end
      end
      -- Update locals used downstream by auto-save and the chat bubble.
      jsfx_code = injected
      if code_type == "jsfx" then code = injected end
      -- Also update the explanation text we built earlier, which had fences
      -- stripped from the ORIGINAL `text`. Re-strip from the updated `text`
      -- so the explanation matches what's actually rendered.
      explanation = text
        :gsub("```[^\n]*\n.-\n%s*```", "")
        :gsub("\n\n\n+", "\n\n")
        :match("^%s*(.-)%s*$") or ""
    else
      Log.line("CEILING-INJECT", "skipped: " .. tostring(info_or_reason))
    end
  end

  -- Auto-run handling.
  local jsfx_auto_status = nil
  local jsfx_saved_path_for_msg = nil   -- saved path to carry on the message
  local jsfx_saved_fx_name_for_msg = nil -- FX ref name to carry on the message
  local auto_ran_ok = false             -- V5: flag for the AUTO-RAN pill below code
  local auto_run_block_reason = _turn_no_guess.protected and
    (_turn_no_guess.policy and "no_guess_mapping_validator" or "no_guess_execution_contract_invalid") or nil
  local diag_blocked_code = nil
  local diag_blocked_code_type = nil
  S.last_run_result = nil               -- avoid carrying manual-run evidence into this turn
  S.last_run_project = nil              -- bind this turn only after execution begins
  if not _turn_no_guess.protected then
    S.lua_defer_run = nil               -- stale deferred callbacks must not rewrite this turn
  end
  -- TYPED-ACTION FX GUARD (round thirty, acceptance finding Z-01). The
  -- typed-action contract has six operations and not one of them inserts a
  -- plug-in, so a reply that is a typed-action plan and nothing else cannot
  -- have served a request that asked for one. gpt-5.6-luna answered "Make a
  -- track called Drive Bus and put Klanghelm MJUC on it" with a lone
  -- track.create, ran it, and reported success with the plug-in named
  -- nowhere: not in the actions, not in prose, not in any error. The FX
  -- identity validator never saw it, because that validator scans
  -- TrackFX_AddByName and TakeFX_AddByName in generated Lua and this lane
  -- emits neither.
  --
  -- THIS GUARD NEVER BLOCKS AND NEVER ENDS THE TURN. It asks once, hidden,
  -- for one Lua script that covers the whole request. A spent budget, a
  -- dispatch that never left the machine, and a second answer that is still
  -- typed actions all reach the same place: the actions run, because they are
  -- correct for what they do cover, and a visible notice names the plug-in
  -- they could not insert. The retry flag is set BEFORE the ask, so a refusal
  -- is recorded as the one attempt made rather than read as an unused retry
  -- by a later pass of the same turn.
  local typed_action_unserved_fx = nil
  if typed_action_ready and not code then
    local unserved_names = Net._requested_plugin_names(
      S.pending_orig_prompt or "",
      Code.typed_actions_artifact_text(text, typed_action_response_format))
    if type(unserved_names) == "table"
        and (tonumber(unserved_names.count) or #unserved_names) > 0 then
      typed_action_unserved_fx = unserved_names
      -- ROUND THIRTY-THREE: THE TWO CLASSES PART HERE. A certain record names
      -- its plug-ins in the hint, in the notice and in the log. A guessed one
      -- names nothing anywhere: it fires the same single hidden ask, worded so
      -- that it asserts nothing about which word is a plug-in and instructs no
      -- insertion the request did not ask for.
      local unserved_certain = unserved_names.certainty ~= "guessed"
      Log.line("TYPED-ACTION-FX", unserved_certain
        and ("the request asks for " .. tbl_concat(unserved_names, ", ")
          .. " and no typed-action operation can insert a plug-in")
        or ("the request may name a plug-in ("
          .. tostring(tonumber(unserved_names.count) or 0)
          .. " capitalised candidate(s), none of them named here) and no "
          .. "typed-action operation can insert one"))
      if not S.typed_action_fx_retry_used then
        S.typed_action_fx_retry_used = true
        -- The installed-catalog search the FX identity validator's repair note
        -- runs, through the same helper and the same "repair_note" reading, so
        -- a plug-in that IS installed comes back with its exact identifier and
        -- one that is not carries CTX.fx_no_match_sentence("repair_note")
        -- verbatim rather than a second copy of that wording.
        local history_content
        if unserved_certain then
          local search_lines = {}
          for _, name in ipairs(unserved_names) do
            local stem = name:gsub("^%s*[%a][%w]*%s*:%s*", "")
              :gsub("%s*%b()%s*$", "")
            local search_block = nil
            if type(CTX) == "table" and type(CTX.installed_fx) == "function"
                and stem ~= "" then
              local search_ok, matches = pcall(CTX.installed_fx, { stem },
                "repair_note")
              if search_ok and type(matches) == "string" then
                search_block = matches
              end
            end
            search_lines[#search_lines + 1] = "  - `" .. name .. "`"
              .. (search_block and ("\n" .. search_block) or "")
          end
          history_content = "(INTERNAL NOTE TO THE MODEL -- DO NOT "
            .. "MENTION ANY OF THIS IN YOUR VISIBLE REPLY: The user asked for "
            .. "a plug-in:\n" .. tbl_concat(search_lines, "\n") .. "\n\n"
            .. "A typed-action plan CANNOT insert a plug-in. Its operations "
            .. "create, resolve and set tracks, build folders and make sends, "
            .. "and nothing else. Answer this request with ONE complete "
            .. "runnable REAPER Lua script inside one ```lua fence that does "
            .. "the WHOLE request, and insert the named plug-in with "
            .. "reaper.TrackFX_AddByName using the exact identifier as it is "
            .. "installed on this system. Request "
            .. "<context_needed>fx_list:<name></context_needed> if you do not "
            .. "know that exact identifier. Never replace a product the user "
            .. "named with a different product. If a saved preference is listed "
            .. "for a generic role, use that preference, whatever any search "
            .. "returns. Do NOT emit typed-action JSON or a "
            .. "`reaassist-actions` fence. Respond as if this is your FIRST "
            .. "reply -- do NOT apologize, do NOT mention a retry.)\n\n"
            .. (S.pending_output_note or "")
            .. "The user's request follows, unchanged. It is the whole of what "
            .. "the script has to do.\n\nUSER REQUEST:\n"
            .. (S.pending_orig_prompt or "")
        else
          -- THE GUESSED HINT ASSERTS NOTHING AND LISTS NOTHING. It states the
          -- one fact this lane is certain of, asks for the whole request as
          -- Lua, and makes the insertion conditional on the request itself, so
          -- a capitalised track name cannot become an instruction to insert a
          -- plug-in. No candidate is quoted and no catalog search runs,
          -- because there is no name to search for.
          history_content = "(INTERNAL NOTE TO THE MODEL -- DO NOT "
            .. "MENTION ANY OF THIS IN YOUR VISIBLE REPLY: A typed-action "
            .. "plan CANNOT insert a plug-in. Its operations create, resolve "
            .. "and set tracks, build folders and make sends, and nothing "
            .. "else. Answer this request with ONE complete runnable REAPER "
            .. "Lua script inside one ```lua fence that does the WHOLE "
            .. "request. If the request asks for a plug-in, insert that "
            .. "plug-in with reaper.TrackFX_AddByName using the exact "
            .. "identifier as it is installed on this system, and request "
            .. "<context_needed>fx_list:<name></context_needed> if you do not "
            .. "know that exact identifier. If the request asks for no "
            .. "plug-in, add none: write the script for what it does ask for "
            .. "and nothing else. Never replace a product the user named with "
            .. "a different product. If a saved preference is listed for a "
            .. "generic role, use that preference, whatever any search "
            .. "returns. Do NOT emit typed-action JSON or a "
            .. "`reaassist-actions` fence. Respond as if this is your FIRST "
            .. "reply -- do NOT apologize, do NOT mention a retry.)\n\n"
            .. (S.pending_output_note or "")
            .. "The user's request follows, unchanged. It is the whole of what "
            .. "the script has to do.\n\nUSER REQUEST:\n"
            .. (S.pending_orig_prompt or "")
        end
        -- THE TYPED-ACTION CONTRACT COMES OFF THE TURN FOR THIS ONE ASK
        -- (round thirty-two, Codex). The hint tells the model not to emit
        -- typed actions, and the expectation this flag carries would then
        -- read the compliant Lua reply as a missing action block and ask for
        -- typed JSON again at the format validator above; on OpenAI it would
        -- also keep the typed-action response_format on the wire, which no
        -- Lua reply can satisfy. It goes back exactly as it was when the
        -- dispatch never left the machine, because the original typed-action
        -- candidate is then what continues.
        local restore_typed_expectation = S.pending_typed_action_expected
        local restore_typed_response_format =
          S.pending_typed_action_response_format
        local restore_typed_profile = S.pending_typed_action_profile
        S.pending_typed_action_expected = false
        S.pending_typed_action_response_format = false
        S.pending_typed_action_profile = nil
        if Net.fire_optional_validator_retry({
          kind = "typed_action_fx",
          log_tag = "TYPED-ACTION-FX",
          log_message = unserved_certain
            and ("a typed-action plan cannot insert "
              .. tbl_concat(unserved_names, ", ")
              .. "; asking once for Lua (user-invisible)")
            or ("a typed-action plan cannot insert a plug-in; asking once "
              .. "for Lua (user-invisible)"),
          history_content = history_content,
          ctx_label = "typed_action_fx_retry",
          retry_failed_key = "retry.reason.for_typed_action_plugin_request",
          retry_failed_label =
            "for the plug-in a structured edit cannot insert",
          failure_message = "Auto-retry for the plug-in a structured edit cannot insert did not go through. Please resend the last message.",
        }) == "stop" then return end
        S.pending_typed_action_expected = restore_typed_expectation
        S.pending_typed_action_response_format = restore_typed_response_format
        S.pending_typed_action_profile = restore_typed_profile
        Log.line("TYPED-ACTION-FX",
          "the ask did not dispatch; the typed-action expectation is restored "
          .. "and the actions run as before")
      end
    end
  end
  local typed_defer = { probe_turn = S.probe_turn }
  typed_defer.runtime_code = Code.typed_actions_artifact_text(text,
    typed_action_response_format)
  typed_defer.runtime_hash = type(Code.plugin_profile_code_key) == "function"
    and Code.plugin_profile_code_key(typed_defer.runtime_code) or nil
  local lua_defer_pending = false
  -- The typed-action FX guard's one record, written onto whichever completed
  -- response the turn ends with and measured exactly once. The immediate and
  -- the deferred execution paths both reach it, and the flag is what keeps a
  -- turn that passes through both from logging the line twice.
  local function record_typed_action_unserved_fx(dmsg)
    if not typed_action_unserved_fx or type(dmsg) ~= "table" then return end
    dmsg.fx_requested_unserved = typed_action_unserved_fx
    if type(dmsg.run_result) == "table" then
      dmsg.run_result.fx_requested_unserved = typed_action_unserved_fx
    end
    if typed_defer.unserved_logged then return end
    typed_defer.unserved_logged = true
    if type(Code.log_run_measurements) == "function" then
      Code.log_run_measurements(dmsg.run_result or {
        run_status = dmsg.run_status,
        code_type = "typed_actions",
        fx_requested_unserved = typed_action_unserved_fx,
      })
    end
  end
  typed_defer.finish = function()
    if not (typed_defer.pending and typed_defer.done) then
      return
    end
    typed_defer.pending = false
    typed_action_metrics.deferred_pending = nil
    typed_action_metrics.executed = typed_defer.ok == true
    local completed_result = typed_defer.result
      and (typed_defer.result.result or typed_defer.result) or nil
    if completed_result and completed_result.action_results then
      typed_action_metrics.action_results = completed_result.action_results
    end
    local dmsg = S.display_messages[typed_defer.message_idx]
    if typed_defer.ok then
      auto_ran_ok = true
      typed_action_metrics.error = nil
      if not explanation or explanation == ""
         or explanation == "Structured edit is applying..."
         or explanation == "Structured edit is running." then
        explanation = ""
      end
      if type(Log) == "table" and type(Log.line) == "function" then
        local counts_text = Code.typed_actions_op_counts_text(
          typed_action_metrics.op_counts)
        if counts_text ~= "" then
          Log.line("TYPED-ACTIONS", "executed " .. counts_text)
        end
      end
      if S.history[_asst_hist_idx] then
        S.history[_asst_hist_idx].run_status = "ran_ok"
        S.history[_asst_hist_idx].code_bytes = 0
        S.history[_asst_hist_idx].code_type  = "typed_actions"
      end
      if not typed_defer.pruned then
        Net.sticky_prune_after_plugin_success(_turn_user_intent,
          lua_code or code)
        typed_defer.pruned = true
      end
    else
      auto_ran_ok = false
      typed_action_metrics.error =
        (typed_defer.result and typed_defer.result.code) or "execution_failed"
      explanation = Code.typed_actions_user_failure_message(typed_defer.result)
      if S.history[_asst_hist_idx] then
        S.history[_asst_hist_idx].run_status = "errored"
        S.history[_asst_hist_idx].code_bytes = 0
        S.history[_asst_hist_idx].code_type  = "typed_actions"
      end
    end
    if dmsg then
      dmsg._typed_action_run_project = completed_result
        and completed_result._execution_project or nil
      dmsg.content = explanation
      dmsg.auto_ran = auto_ran_ok
      dmsg.typed_actions = typed_action_metrics
      dmsg.run_status = typed_defer.ok and "ran_ok" or "errored"
      dmsg.validation_status = typed_defer.ok and "passed" or "failed"
      dmsg.validation_block_kind = (not typed_defer.ok)
        and typed_action_metrics.error or nil
      local typed_plan_text = Code.typed_actions_artifact_text(text,
        typed_action_response_format)
      if type(typed_plan_text) == "string" and typed_plan_text ~= ""
         and type(Code.typed_actions_display_text) == "function" then
        dmsg.typed_action_summary = Code.typed_actions_display_text(
          typed_plan_text, typed_action_metrics.action_results)
      end
      dmsg.run_result = Code.build_run_result("typed_actions", typed_plan_text,
        dmsg.run_status, dmsg.validation_status, {
          auto_ran = auto_ran_ok,
          fx_requested_unserved = typed_action_unserved_fx,
          validation_block_kind = dmsg.validation_block_kind,
          error_kind = (not typed_defer.ok) and "runtime_error" or nil,
          runtime_error = (not typed_defer.ok)
            and tostring(typed_action_metrics.error or "execution_failed") or nil,
          error_debug = (not typed_defer.ok) and {
            failure_kind = "runtime_error",
            source = "typed_action_executor",
            typed_action_error = tostring(typed_action_metrics.error
              or "execution_failed"),
            deferred = typed_defer.pending == true,
          } or nil,
        })
      if dmsg.run_result.error_kind and not dmsg.error_kind then
        dmsg.error_kind = dmsg.run_result.error_kind
      end
      if dmsg.run_result.error_debug and not dmsg.error_debug then
        dmsg.error_debug = dmsg.run_result.error_debug
      end
      if dmsg.run_result.runtime_error then
        dmsg.runtime_error = dmsg.run_result.runtime_error
      end
      record_typed_action_unserved_fx(dmsg)
    end
    if type(Code.plugin_test_runtime_event) == "function" then
      Code.plugin_test_runtime_event(typed_defer.ok
          and "run_completed" or "run_error", {
        code_sha256 = typed_defer.runtime_hash,
        code_type = "typed_actions",
        run_result = dmsg and dmsg.run_result or Code.build_run_result(
          "typed_actions", typed_defer.runtime_code,
          typed_defer.ok and "ran_ok" or "errored",
          typed_defer.ok and "passed" or "failed", {
            auto_ran = typed_defer.ok == true,
            error_kind = (not typed_defer.ok) and "runtime_error" or nil,
          }),
      })
    end
    Probe.mark_phase_end(typed_defer.probe_turn, "execution")
    Probe.add_typed_action(typed_defer.probe_turn, typed_action_metrics)
    if typed_defer.probe_turn then
      Net._finish_probe_turn(typed_defer.probe_turn, "ok")
    end
    S.scroll_to_bottom = true
  end
  if prefs.auto_run and not _any_gate_hit()
      and typed_action_lua_generation == nil then
    if typed_action_ready then
      local skip_typed = false
      if not Code.project_is_active(S.pending_project) then
        auto_run_block_reason = "project_changed"
        typed_action_metrics.error = "project_changed"
        explanation = "Structured edit validated, but auto-run was paused "
          .. "because the active project changed. Return to the intended "
          .. "project tab, or use Run Edit to apply it deliberately to the "
          .. "current project."
        skip_typed = true
        if S.history[_asst_hist_idx] then
          S.history[_asst_hist_idx].run_status = "manual_run"
        end
      elseif prefs.auto_backup then
        local _, berr = Code.safety_backup()
        if berr == "unsaved" then
          auto_run_block_reason = "backup_required"
          typed_action_metrics.error = "backup_required"
          explanation = (RA and RA.t and RA.t(
            "typed_actions.status.backup_required", nil,
            "Structured edit validated, but auto-run is blocked until the project is saved for safety backup."))
            or "Structured edit validated, but auto-run is blocked until the project is saved for safety backup."
          skip_typed = true
          if S.history[_asst_hist_idx] then
            S.history[_asst_hist_idx].run_status = "manual_run"
          end
        elseif not Code.safety_backup_can_proceed(berr) then
          auto_run_block_reason = "backup_failed"
          typed_action_metrics.error = "backup_failed"
          explanation = (RA and RA.t and RA.t(
            "typed_actions.status.backup_failed", nil,
            "Structured edit validated, but auto-run is blocked because ReaAssist could not create a safety backup."))
            or "Structured edit validated, but auto-run is blocked because ReaAssist could not create a safety backup."
          Log.add_error(explanation)
          skip_typed = true
          if S.history[_asst_hist_idx] then
            S.history[_asst_hist_idx].run_status = "manual_run"
          end
        end
      end
      if not skip_typed then
        Probe.mark_phase_start(S.probe_turn, "execution")
        if type(Code.plugin_test_runtime_event) == "function" then
          Code.plugin_test_runtime_event("run_started", {
            code_sha256 = typed_defer.runtime_hash,
            code_type = "typed_actions",
          })
        end
        local exec_ok, exec_result = Code.execute_typed_actions_from_text(text, {
          allow_raw_json = typed_action_response_format,
          user_text = S.pending_orig_prompt or "",
          profile = typed_action_profile,
          expected_project = S.pending_project,
          on_done = function(done_ok, done_result)
            typed_defer.done = true
            typed_defer.ok = done_ok == true
            typed_defer.result = done_result
            typed_defer.finish()
          end,
        })
        local exec_pending = exec_ok and exec_result
          and exec_result.deferred == true
          and exec_result.completed ~= true
        typed_defer.execution_project = exec_result
          and exec_result._execution_project or nil
        if exec_pending then
          typed_defer.pending = true
        else
          Probe.mark_phase_end(S.probe_turn, "execution")
        end
        typed_action_metrics.deferred =
          exec_result and exec_result.deferred == true or nil
        typed_action_metrics.deferred_pending = exec_pending or nil
        typed_action_metrics.executed = exec_ok == true and not exec_pending
        if exec_result and exec_result.action_results then
          typed_action_metrics.action_results = exec_result.action_results
        end
        if exec_ok then
          if exec_pending then
            explanation = ""
            if type(Code.plugin_test_runtime_event) == "function" then
              Code.plugin_test_runtime_event("run_pending", {
                code_sha256 = typed_defer.runtime_hash,
                code_type = "typed_actions",
                run_result = Code.build_run_result("typed_actions",
                  typed_defer.runtime_code, "pending", "pending", {
                    deferred = true,
                    deferred_pending = true,
                  }),
              })
            end
            if S.history[_asst_hist_idx] then
              S.history[_asst_hist_idx].run_status = "pending"
              S.history[_asst_hist_idx].code_bytes = 0
              S.history[_asst_hist_idx].code_type  = "typed_actions"
            end
          else
            auto_ran_ok = true
            if type(Log) == "table" and type(Log.line) == "function" then
              local counts_text = Code.typed_actions_op_counts_text(
                typed_action_metrics.op_counts)
              if counts_text ~= "" then
                Log.line("TYPED-ACTIONS", "executed " .. counts_text)
              end
            end
            explanation = (explanation and explanation ~= "") and explanation or ""
            if S.history[_asst_hist_idx] then
              S.history[_asst_hist_idx].run_status = "ran_ok"
              S.history[_asst_hist_idx].code_bytes = 0
              S.history[_asst_hist_idx].code_type  = "typed_actions"
            end
            if type(Code.plugin_test_runtime_event) == "function" then
              Code.plugin_test_runtime_event("run_completed", {
                code_sha256 = typed_defer.runtime_hash,
                code_type = "typed_actions",
                run_result = Code.build_run_result("typed_actions",
                  typed_defer.runtime_code, "ran_ok", "passed", {
                    auto_ran = true,
                  }),
              })
            end
          end
        else
          local code_or_nil = exec_result and exec_result.code or nil
          typed_action_metrics.error = code_or_nil or "execution_failed"
          explanation = Code.typed_actions_user_failure_message(exec_result)
          local typed_err_debug = {
            failure_kind = "runtime_error",
            source = "typed_action_executor",
            typed_action_error = tostring(typed_action_metrics.error),
            deferred = false,
          }
          local message = tostring(explanation or code_or_nil or "unknown error")
          local fallback = "Structured edit failed: " .. message
          Log.add_error((RA and RA.t and RA.t("typed_actions.error.failed",
            { message = message }, fallback)) or fallback,
            nil, nil, nil,
            { error_kind = "runtime_error", error_debug = typed_err_debug })
          if S.history[_asst_hist_idx] then
            S.history[_asst_hist_idx].run_status = "errored"
            S.history[_asst_hist_idx].code_bytes = 0
            S.history[_asst_hist_idx].code_type  = "typed_actions"
          end
          if type(Code.plugin_test_runtime_event) == "function" then
            Code.plugin_test_runtime_event("run_error", {
              code_sha256 = typed_defer.runtime_hash,
              code_type = "typed_actions",
              run_result = Code.build_run_result("typed_actions",
                typed_defer.runtime_code, "errored", "failed", {
                  error_kind = "runtime_error",
                  runtime_error = tostring(typed_action_metrics.error),
                }),
            })
          end
        end
      end
    end

    -- JSFX: auto-save to Effects/ReaAssist/ folder ONLY when a Lua companion
    -- block is also present (meaning the user asked for it on a track).
    -- If the user just asked for an example, there is no Lua block and the
    -- JSFX is displayed but not saved.
    local jsfx_to_save = not _turn_no_guess.protected and (jsfx_code or (code_type == "jsfx" and code))
    if jsfx_to_save and lua_code then
      local saved_path, fx_name = Code.auto_save_jsfx(jsfx_to_save)
      if saved_path then
        jsfx_saved_path_for_msg = saved_path
        jsfx_saved_fx_name_for_msg = fx_name
        -- Record the ceiling slot allocation for the host poll loop now
        -- that we have a real on-disk file path to associate with it.
        -- (Pre-injection bails left ceiling_inject_info nil, so this
        -- no-ops on bail.)
        if ceiling_inject_info then
          Code.ceiling_record_slot(ceiling_inject_info, saved_path,
            ceiling_inject_info.desc)
        end
        -- Patch the Lua companion to use the actual saved filename (may have a
        -- numeric suffix if a file with the original name already existed).
        if lua_code and fx_name and Code.rewrite_lua_companion_jsfx_refs then
          lua_code = Code.rewrite_lua_companion_jsfx_refs(
            lua_code, jsfx_to_save, fx_name)
        end
        if lua_code then
          jsfx_auto_status = (RA and RA.t and RA.t("jsfx.done", nil,
            "Done.")) or "Done."
        else
          jsfx_auto_status = (RA and RA.t and RA.t("jsfx.saved_to",
            { path = saved_path }, "JSFX saved to " .. saved_path))
            or ("JSFX saved to " .. saved_path)
        end
      end
    end
    -- Lua: auto-run (handles both standalone Lua and JSFX companion scripts).
    local run_lua = not _turn_no_guess.protected and (lua_code or (code_type == "lua" and code))
    if run_lua then
      S.pending_code = run_lua
      local skip_run = false
      local run_lua_artifact = lua_artifact_info
      if not run_lua_artifact or run_lua ~= lua_code then
        run_lua_artifact = Code.classify_lua_artifact(run_lua,
          { context_text = text })
      end
      if Code.prompt_requests_reusable_action_script(
          S.pending_orig_prompt or "") then
        skip_run = true
        auto_run_block_reason = "reusable_action_manual_only"
        S.pending_code = nil
        Log.line("AUTO-RUN",
          "skipped reusable Action List script; save/install handoff required")
        if S.history[_asst_hist_idx] then
          S.history[_asst_hist_idx].run_status = "manual_run"
          S.history[_asst_hist_idx].code_bytes = #run_lua
          S.history[_asst_hist_idx].code_type = "lua"
        end
      elseif not run_lua_artifact.runnable then
        local block_msg = Code.lua_artifact_block_message(run_lua_artifact)
        Log.line("AUTO-RUN", "blocked non-runnable Lua artifact: "
          .. tostring(run_lua_artifact.kind) .. " / "
          .. tostring(run_lua_artifact.reason))
        if explanation and explanation ~= "" then
          explanation = explanation .. "\n\n" .. block_msg
        else
          explanation = block_msg
        end
        skip_run = true
        auto_run_block_reason = "non_runnable_lua_artifact"
        S.pending_code = nil
        diag_blocked_code = run_lua
        diag_blocked_code_type = "lua"
        if S.history[_asst_hist_idx] then
          S.history[_asst_hist_idx].run_status = "blocked_fragment"
          S.history[_asst_hist_idx].code_bytes = #run_lua
          S.history[_asst_hist_idx].code_type  = "lua"
        end
      elseif run_lua_artifact.manual_run_only then
        local block_msg = Code.lua_artifact_block_message(run_lua_artifact)
        Log.line("AUTO-RUN", "blocked action-context Lua artifact: "
          .. tostring(run_lua_artifact.kind) .. " / "
          .. tostring(run_lua_artifact.manual_run_reason))
        if explanation and explanation ~= "" then
          explanation = explanation .. "\n\n" .. block_msg
        else
          explanation = block_msg
        end
        skip_run = true
        auto_run_block_reason = "manual_run_only_lua_artifact"
        S.pending_code = nil
        diag_blocked_code = run_lua
        diag_blocked_code_type = "lua"
        if S.history[_asst_hist_idx] then
          S.history[_asst_hist_idx].run_status = "blocked_action_context"
          S.history[_asst_hist_idx].code_bytes = #run_lua
          S.history[_asst_hist_idx].code_type  = "lua"
        end
      end
      -- Risky-code gate: if the scanner flags anything, require explicit
      -- confirmation before auto-executing. The modal index points to the
      -- message that will be appended just below this block.
      local sandbox_forbidden =
        (not skip_run and type(Code.scan_forbidden_sandbox_globals) == "function")
        and Code.scan_forbidden_sandbox_globals(run_lua) or nil
      if sandbox_forbidden then
        local block_debug = {
          failure_kind = "validator_blocked",
          source = "sandbox_forbidden_global_validator",
          validation_block_kind = "sandbox_forbidden_global",
          forbidden_globals = sandbox_forbidden,
          generated_code_bytes = type(run_lua) == "string" and #run_lua or 0,
        }
        validator_gate_hit = true
        auto_run_block_reason = "sandbox_forbidden_global"
        skip_run = true
        diag_blocked_code = run_lua
        diag_blocked_code_type = "lua"
        Log.line("SANDBOX-GLOBAL-VALIDATOR",
          "sandbox-forbidden globals; auto-run blocked: "
          .. tostring(sandbox_forbidden))
        Log.add_error((RA and RA.t and RA.t(
          "validator.sandbox_api_blocked",
          { apis = tostring(sandbox_forbidden) },
          "I blocked this script because it references Lua APIs "
            .. "that are unavailable in ReaAssist's execution sandbox: "
            .. tostring(sandbox_forbidden)
            .. ". Ask ReaAssist to regenerate it without those APIs."))
          or ("I blocked this script because it references Lua APIs that are unavailable in ReaAssist's execution sandbox: "
            .. tostring(sandbox_forbidden)
            .. ". Ask ReaAssist to regenerate it without those APIs."),
          nil, nil, nil,
          { error_kind = "validator_blocked", error_debug = block_debug })
        S.last_run_error = "blocked sandbox-forbidden globals: "
          .. tostring(sandbox_forbidden)
        S.last_run_result = Code.build_run_result("lua", run_lua,
          "blocked_sandbox_api", "blocked", {
            validation_block_kind = "sandbox_forbidden_global",
            error_kind = "validator_blocked",
            error_debug = block_debug,
            runtime_error = S.last_run_error,
          })
        if S.history[_asst_hist_idx] then
          S.history[_asst_hist_idx].run_status = "blocked_sandbox_api"
          S.history[_asst_hist_idx].validation_status = "blocked"
          S.history[_asst_hist_idx].error_kind = "validator_blocked"
          S.history[_asst_hist_idx].error_debug = block_debug
          S.history[_asst_hist_idx].code_bytes = #run_lua
          S.history[_asst_hist_idx].code_type  = "lua"
        end
      end
      if not skip_run and not Code.project_is_active(S.pending_project) then
        auto_run_block_reason = "project_changed"
        skip_run = true
        Log.line("AUTO-RUN",
          "active project changed after Send; generated Lua was not run")
        if S.history[_asst_hist_idx] then
          S.history[_asst_hist_idx].run_status = "manual_run"
        end
      end
      _turn_no_guess.contract = Code.make_no_guess_execution_contract(_turn_no_guess.policy, run_lua)
      _turn_no_guess.parameter_targets, _turn_no_guess.parameter_context =
        Code.plugin_parameter_targets(_turn_user_intent, S.history)
      _turn_no_guess.run_context = Code.generated_lua_run_context({code_type="lua", code_block=run_lua,
        parameter_targets=_turn_no_guess.parameter_targets,
        parameter_context=_turn_no_guess.parameter_context,
        source_request=_turn_user_intent, no_guess_activation_request=_turn_no_guess.activation_request,
        no_guess_current_reply=_turn_no_guess.current_reply, no_guess_policy_state=_turn_no_guess.state,
        no_guess_inherited_constraints=_turn_no_guess.inherited_constraints,
        no_guess_execution_contract=_turn_no_guess.contract}, #S.display_messages+1, run_lua)
      if not skip_run then
        local allowed, reason = Code.preflight_generated_lua_execution(run_lua, _turn_no_guess.run_context)
        if not allowed then skip_run, auto_run_block_reason = true, reason end
      end
      local auto_risk = (not skip_run) and Code.scan_risky(run_lua) or nil
      if auto_risk then
        auto_run_block_reason = "risky_code_confirmation"
        S.risky_warn_code   = run_lua
        S.risky_warn_idx    = #S.display_messages + 1
        S.risky_warn_detail = auto_risk
        S.open_risky_warn   = true
        skip_run = true
        if S.history[_asst_hist_idx] then
          S.history[_asst_hist_idx].run_status = "manual_run"
        end
      elseif not skip_run and prefs.auto_backup then
        local _, berr = Code.safety_backup()
        if berr == "unsaved" then
          auto_run_block_reason = "backup_required"
          S.backup_warn_code = run_lua
          S.backup_warn_idx  = #S.display_messages + 1
          S.open_backup_warn = true
          skip_run = true
          if S.history[_asst_hist_idx] then
            S.history[_asst_hist_idx].run_status = "manual_run"
          end
        elseif not Code.safety_backup_can_proceed(berr) then
          auto_run_block_reason = "backup_failed"
          skip_run = true
          if S.history[_asst_hist_idx] then
            S.history[_asst_hist_idx].run_status = "manual_run"
          end
          Log.add_error((RA and RA.t and RA.t(
            "code.backup_failed_run", { error = tostring(berr) },
            "Safety backup failed (" .. tostring(berr)
              .. "). The generated code was NOT run. Check the project "
              .. "folder, disk space, and permissions, then try again. To "
              .. "proceed without a backup, turn off Auto-backup in Settings "
              .. "and run the code again."))
            or ("Safety backup failed (" .. tostring(berr)
              .. "). The generated code was NOT run."))
        end
      end
      if not skip_run then
        -- Probe timing: time the actual code execution.
        -- Skipped when skip_run is true (risky-code gate or backup
        -- requirement); execution measurement is for auto-run only.
        Probe.mark_phase_start(S.probe_turn, "execution")
        local run_ok, run_state = Code.run(run_lua, S.pending_project,
          S.pending_conversation_delete, _turn_no_guess.run_context)
        lua_defer_pending = run_state == "pending"
        if not lua_defer_pending then
          Probe.mark_phase_end(S.probe_turn, "execution")
        end
        S.pending_code = nil
        -- AUTO-RAN pill (V5) reflects the actual run outcome -- a
        -- compile/runtime failure should NOT show as auto-ran. Mirror the
        -- same outcome onto the per-turn run record for diagnostics.
        auto_ran_ok = (run_ok == true and not lua_defer_pending)
        if S.history[_asst_hist_idx] then
          S.history[_asst_hist_idx].run_status = lua_defer_pending and "pending"
            or (run_ok and "ran_ok" or "errored")
          S.history[_asst_hist_idx].code_bytes = #run_lua
          S.history[_asst_hist_idx].code_type  = code_type
        end
      end
    end
  end
  if typed_action_lua_generation and code then
    auto_run_block_reason = "typed_action_lua_generation_only"
    if S.history[_asst_hist_idx] then
      S.history[_asst_hist_idx].run_status = "manual_run"
      S.history[_asst_hist_idx].code_bytes = #code
      S.history[_asst_hist_idx].code_type = code_type
    end
  end
  if typed_action_ready
     and not typed_action_metrics.executed
     and not typed_defer.pending
     and (not explanation or explanation == "") then
    typed_action_metrics.error = typed_action_metrics.error or "auto_run_disabled"
    auto_run_block_reason = auto_run_block_reason or "auto_run_disabled"
    explanation = (RA and RA.t and RA.t(
      "typed_actions.status.auto_run_off", nil,
      "Structured edit validated, but it was not run because Auto-run is off."))
      or "Structured edit validated, but it was not run because Auto-run is off."
    if S.history[_asst_hist_idx] then
      S.history[_asst_hist_idx].run_status = "manual_run"
      S.history[_asst_hist_idx].code_bytes = 0
      S.history[_asst_hist_idx].code_type = "typed_actions"
    end
  end
  if code and not auto_ran_ok then
    local inferred_block_reason = _auto_run_block_reason()
    if inferred_block_reason ~= nil then
      auto_run_block_reason = auto_run_block_reason or inferred_block_reason
    end
    if auto_run_block_reason == "action_relevance_review"
       and S.history[_asst_hist_idx] then
      Net._force_manual_run_status(
        S.history[_asst_hist_idx], code, code_type)
    end
    if type(Code.plugin_test_runtime_event) == "function" then
      Code.plugin_test_runtime_event("validation_completed", {
        code_sha256 = type(Code.plugin_profile_code_key) == "function"
          and Code.plugin_profile_code_key(code) or nil,
        code_type = code_type,
        gate_hit = _any_gate_hit() == true,
        auto_run_enabled = prefs.auto_run == true,
        auto_run_block_reason = auto_run_block_reason,
      })
    end
    if auto_run_block_reason == "auto_run_disabled"
       and type(code) == "string" and code ~= ""
       and S.history[_asst_hist_idx] then
      Net._force_manual_run_status(
        S.history[_asst_hist_idx], code, code_type)
    end
  end
  if code and not _turn_no_guess.protected and not S.pending_code
     and (code_type ~= "lua"
       or not lua_artifact_info
       or (lua_artifact_info.runnable
         and not lua_artifact_info.manual_run_only)) then
    S.pending_code = code
  end

  -- Truncation: model hit MAX_TOKENS but still emitted visible text. Stamp
  -- the message so the chat bubble renders a "cut off" banner + the same
  -- recovery buttons as the empty-response case. provider_id is always set
  -- below, so the thinking-level button scopes to the right provider.
  local was_truncated = (empty_reason == "length")
  if was_truncated and S.history[_asst_hist_idx] then
    S.history[_asst_hist_idx].truncated   = true
    S.history[_asst_hist_idx].run_status  = "truncated"
  end
  if not code and not (typed_action_metrics and typed_action_metrics.present) then
    local filtered_explanation, filtered_count =
      Code.filter_broad_fx_param_readout(_turn_user_intent, explanation)
    if filtered_count and filtered_count > 0 then
      explanation = filtered_explanation
      text = filtered_explanation
      if S.history[_asst_hist_idx] then
        S.history[_asst_hist_idx].content = filtered_explanation
      end
      Log.line("PARAM-READOUT",
        "filtered " .. tostring(filtered_count)
        .. " default utility parameter line(s) from broad readout")
    end
  end
  Net._set_pending_request_status("succeeded", nil, {
    clear_display_text = true,
  })
  if _turn_no_guess.protected then
    _turn_no_guess.contract = Code.make_no_guess_execution_contract(
      _turn_no_guess.policy, _turn_no_guess.blocked_lua)
    local _, reason = Code.preflight_generated_lua_execution(_turn_no_guess.blocked_lua,
      {origin="generated_response", source_request=_turn_user_intent,
        activation_request=_turn_no_guess.activation_request, current_reply=_turn_no_guess.current_reply,
        policy_state=_turn_no_guess.state, inherited_constraints=_turn_no_guess.inherited_constraints,
        multiple_scripts=_turn_no_guess.multiple_scripts,
        contract=_turn_no_guess.contract})
    auto_run_block_reason = reason or "no_guess_execution_contract_invalid"
    if S.history[_asst_hist_idx] then
      S.history[_asst_hist_idx].run_status = "blocked"
      S.history[_asst_hist_idx].validation_status = "blocked"
    end
    S.pending_code = nil
  end
  if not _turn_no_guess.parameter_context then
    _turn_no_guess.parameter_targets, _turn_no_guess.parameter_context =
      Code.plugin_parameter_targets(_turn_user_intent, S.history)
  end
  S.display_messages[#S.display_messages+1] = {
    role       = "assistant",
    content    = explanation,
    provider_reasoning = provider_reasoning,
    provider_reasoning_open = provider_reasoning and true or nil,
    provider_reasoning_truncated = provider_reasoning_truncated or nil,
    provider_reasoning_summary = provider_reasoning_summary,
    provider_reasoning_summary_open = provider_reasoning_summary and true or nil,
    provider_reasoning_summary_truncated =
      provider_reasoning_summary_truncated or nil,
    code_block = code,
    code_type  = code_type,
    source_request = _turn_user_intent,
    parameter_targets = _turn_no_guess.parameter_targets,
    parameter_context = _turn_no_guess.parameter_context,
    no_guess_activation_request = _turn_no_guess.activation_request,
    no_guess_current_reply = _turn_no_guess.current_reply,
    no_guess_policy_state = _turn_no_guess.state,
    no_guess_inherited_constraints = _turn_no_guess.inherited_constraints,
    no_guess_execution_contract = _turn_no_guess.contract,
    ctx_label  = (function()
      local dmsg = S.pending_display_idx
        and S.display_messages[S.pending_display_idx] or nil
      return dmsg and dmsg.ctx_label or nil
    end)(),
    request_status = (function()
      local dmsg = S.pending_display_idx
        and S.display_messages[S.pending_display_idx] or nil
      return dmsg and type(dmsg.request_status) == "table"
        and type(Diag) == "table"
        and type(Diag.sanitize_request_status) == "function"
        and Diag.sanitize_request_status(dmsg.request_status) or nil
    end)(),
    transport_events = (function()
      local dmsg = S.pending_display_idx
        and S.display_messages[S.pending_display_idx] or nil
      return dmsg and dmsg.transport_events or nil
    end)(),
    provider_id     = (function()
      local _p = PROVIDERS[S.pending_provider_idx] or PROVIDERS.active()
      return _p and _p.id or nil
    end)(),
    -- model_id captured alongside provider_id so per-message recovery
    -- actions (Lower Thinking on a length-cap reply, etc.) can write
    -- their changes against the model that actually produced this
    -- response, not against whatever model the user happens to be on
    -- when they click the recovery button.
    model_id        = (function()
      local _p = PROVIDERS[S.pending_provider_idx] or PROVIDERS.active()
      local _models = _p and _p.models or MODELS
      local _m = _models[S.pending_model_idx or prefs.model_idx]
        or _models[1]
      return _m and _m.id or nil
    end)(),
    thinking_label  = (function()
      local _p = PROVIDERS[S.pending_provider_idx] or PROVIDERS.active()
      local _thinking_idx = S.pending_thinking_idx or prefs.thinking_idx
      if _p and _p.thinking_levels and _thinking_idx
         and _thinking_idx > 0 then
        local _tl = _p.thinking_levels[_thinking_idx]
        return _tl and (_tl.value or _tl.id or _tl.label) or nil
      end
      return nil
    end)(),
    model_label     = (function()
      local _p = PROVIDERS[S.pending_provider_idx] or PROVIDERS.active()
      local _models = _p and _p.models or MODELS
      -- Same fallback as the user-bubble model_label build: a brief
      -- post-provider-switch race or a 0-model custom provider would
      -- make MODELS[prefs.model_idx] nil, and indexing .label on it
      -- would crash the response handler.
      local _m = _models[S.pending_model_idx or prefs.model_idx]
        or _models[1]
      return ((_p and _p.label or "?") .. " "
        .. (_m and _m.label or "?"))
    end)(),
    lua_companion   = (_turn_no_guess.blocked_jsfx and _turn_no_guess.blocked_lua)
      or (jsfx_code and lua_code) or nil,  -- store companion for manual run
    lua_artifact    = code_type == "lua" and lua_artifact_info or nil,
    lua_companion_artifact = jsfx_code and lua_code and lua_artifact_info or nil,
    jsfx_auto_saved = jsfx_auto_status,               -- status text from auto-save
    jsfx_saved_path = jsfx_saved_path_for_msg,        -- path if already saved (avoids re-save)
    jsfx_saved_fx_name = jsfx_saved_fx_name_for_msg,  -- FX ref name if already saved
    ceiling_injected = ceiling_inject_info ~= nil or nil,
    ceiling_inject_info = ceiling_inject_info,
    jsfx_user_text = jsfx_code and _turn_user_intent or nil,
    code_block_present = ((code ~= nil and code ~= "")
      or (typed_action_metrics and typed_action_metrics.present == true))
      and true or false,
    assistant_response_status = was_truncated and "truncated"
      or ((((explanation or "") == "")
        and not code
        and not (typed_action_metrics and typed_action_metrics.present == true))
        and "empty" or "complete"),
    run_status      = S.history[_asst_hist_idx]
      and S.history[_asst_hist_idx].run_status or nil,
    manual_review_reason = auto_run_block_reason == "midi_record_mode_review"
      and S.history[_asst_hist_idx]
      and S.history[_asst_hist_idx].manual_review_reason
      or action_relevance_review_message,
    validation_status = (function()
      local _rs = S.history[_asst_hist_idx]
        and S.history[_asst_hist_idx].run_status or nil
      local _ta = typed_action_metrics
      local _ta_err = _ta and tostring(_ta.error or "") or ""
      if docs_gate_hit then return "blocked" end
      if auto_run_block_reason == "action_relevance_review"
         or auto_run_block_reason == "midi_record_mode_review" then
        return "manual_required"
      end
      if auto_run_block_reason
         and auto_run_block_reason ~= "auto_run_disabled"
         and auto_run_block_reason ~= "reusable_action_manual_only"
         and auto_run_block_reason ~= "typed_action_lua_generation_only" then
        return "blocked"
      end
      if _rs == "semantic_incomplete"
         or _rs == "blocked_midi_input_validator"
         or _rs == "blocked_record_arm_property_validator" then
        return "blocked"
      end
      if _rs == "manual_run" then return "manual_required" end
      if _rs == "pending" then return "pending" end
      if _rs == "blocked_fragment" or _rs == "blocked_action_context" then
        return "blocked"
      end
      if _ta and _ta.present then
        if _ta_err == "auto_run_disabled" or _ta_err == "backup_required"
           or _ta_err == "backup_failed" then
          return "manual_required"
        end
        if _ta.valid == true then return "passed" end
        if _ta_err ~= "" then return "failed" end
        return "not_applicable"
      end
      if _rs == "ran_ok" then return "passed" end
      if _rs == "errored" then return "failed" end
      if code then return "not_applicable" end
      return nil
    end)(),
    validation_block_kind = (function()
      local _rs = S.history[_asst_hist_idx]
        and S.history[_asst_hist_idx].run_status or nil
      local _ta = typed_action_metrics
      local _ta_err = _ta and tostring(_ta.error or "") or ""
      if docs_gate_hit then return "docs_gate" end
      if auto_run_block_reason
         and auto_run_block_reason ~= "auto_run_disabled"
         and auto_run_block_reason ~= "reusable_action_manual_only"
         and auto_run_block_reason ~= "typed_action_lua_generation_only" then
        return auto_run_block_reason
      end
      if midi_input_gate_hit then
        return midi_input_block_kind or "midi_input_validator"
      end
      if _rs == "blocked_fragment" or _rs == "blocked_action_context" then
        return lua_artifact_info
          and (lua_artifact_info.manual_run_reason or lua_artifact_info.reason)
          or "non_runnable_lua"
      end
      if _ta_err ~= "" then return _ta_err end
      return nil
    end)(),
    auto_run_block_reason = auto_run_block_reason,
    -- The plug-in names behind an fx_ident_validator block, so the completed
    -- response carries them into the visual transcript and the Screen
    -- Reader's latest response, not only into the separate error entry.
    fx_ident_block = fxident_block_detail,
    auto_ran        = auto_ran_ok,                    -- V5: show AUTO-RAN pill below code
    truncated       = was_truncated or nil,
    typed_action_token_cap = (was_truncated and typed_action_response_format
      and S.typed_action_escalation_used == true) or nil,
    recovery        = was_truncated and "token_limit" or nil,
    recovery_kind   = was_truncated and "token_limit" or nil,
    -- True when the response tripped the docs-gate (reaper.* emitted with no
    -- api_ref in session). Chat bubble renderers can key off this to show a
    -- warning banner; auto-run was already suppressed above.
    docs_gate_hit   = docs_gate_hit or nil,
    typed_actions   = typed_action_metrics,
    _typed_action_run_project = typed_defer.execution_project,
    validation_trace = Net._validation_trace_for_turn(
      S.validator_retry_candidate_text),
    conversation_delete = S.pending_conversation_delete,
  }
  do
    local dmsg = S.display_messages[#S.display_messages]
    if dmsg then
      if S.backup_warn_idx == #S.display_messages and S.backup_warn_code then
        S.backup_warn_message = dmsg
      end
      if S.risky_warn_idx == #S.display_messages and S.risky_warn_code then
        S.risky_warn_message = dmsg
      end
      if dmsg.code_block then
        dmsg.generated_code = Code.generated_code_descriptor(
          dmsg.code_block, dmsg.code_type)
      elseif typed_action_metrics and typed_action_metrics.present == true then
        local typed_plan_text = Code.typed_actions_artifact_text(text,
          typed_action_response_format)
        dmsg.generated_code = Code.generated_code_descriptor(typed_plan_text,
          "typed_actions", { content_field = "typed_action_plan" })
        if dmsg.generated_code then dmsg.generated_code.content = typed_plan_text end
        if type(typed_plan_text) == "string" and typed_plan_text ~= ""
           and type(Code.typed_actions_display_text) == "function" then
          dmsg.typed_action_summary = Code.typed_actions_display_text(
            typed_plan_text, typed_action_metrics.action_results)
        end
      end
      Net._force_manual_display_status(dmsg,
        typed_action_metrics and typed_action_metrics.present == true)

      local rr = type(S.last_run_result) == "table" and S.last_run_result or nil
      if rr and Net._display_status_accepts_last_run_result(dmsg) then
        dmsg.run_result = {}
        for k, v in pairs(rr) do dmsg.run_result[k] = v end
        if dmsg.code_type == "lua" then
          dmsg._lua_run_project = S.last_run_project
        end
        dmsg.run_result.auto_ran = auto_ran_ok == true
        dmsg.run_result.code_type = dmsg.code_type or dmsg.run_result.code_type
        dmsg.run_result.validation_status =
          dmsg.validation_status or dmsg.run_result.validation_status
        -- ROUND THIRTY-TWO, AA-02: A SCRIPT THAT RAN AND INSERTED NOTHING.
        -- Code.run wrote the record onto the run result, where the accepted
        -- insert count is final; a synchronous auto-run never reaches
        -- Code.apply_run_result_to_message, so the message takes its copy
        -- here, which is what both interfaces render.
        if type(dmsg.run_result.fx_requested_unserved) == "table" then
          dmsg.fx_requested_unserved = dmsg.run_result.fx_requested_unserved
          dmsg.fx_requested_unserved_kind =
            dmsg.run_result.fx_requested_unserved_kind
        end
        if type(Code.log_run_measurements) == "function" then
          Code.log_run_measurements(dmsg.run_result)
        end
        dmsg.observable_change_status = dmsg.run_result.observable_change_status
        dmsg.change_evidence = dmsg.run_result.change_evidence
        dmsg.parameter_change_status = dmsg.run_result.parameter_change_status
        dmsg.parameter_change_evidence = dmsg.run_result.parameter_change_evidence
        dmsg.midi_note_change_evidence = dmsg.run_result.midi_note_change_evidence
        dmsg.midi_note_change_status = dmsg.run_result.midi_note_change_status
        dmsg.host_value_change_status =
          dmsg.run_result.host_value_change_status
        dmsg.host_value_change_evidence =
          dmsg.run_result.host_value_change_evidence
        if dmsg.run_result.error_kind and not dmsg.error_kind then
          dmsg.error_kind = dmsg.run_result.error_kind
        end
        if dmsg.run_result.error_debug and not dmsg.error_debug then
          dmsg.error_debug = dmsg.run_result.error_debug
        end
        if dmsg.run_result.runtime_error then
          dmsg.runtime_error = dmsg.run_result.runtime_error
        end
      elseif not typed_defer.pending
          and (dmsg.code_block_present ~= nil or dmsg.run_status
          or dmsg.validation_status) then
        local rr_code_type = dmsg.code_type
          or ((typed_action_metrics and typed_action_metrics.present == true)
            and "typed_actions" or nil)
        local rr_code = dmsg.code_block
        if diag_blocked_code then
          rr_code_type = diag_blocked_code_type or rr_code_type
          rr_code = diag_blocked_code
        elseif not rr_code and typed_action_metrics
           and typed_action_metrics.present == true then
          rr_code = Code.typed_actions_artifact_text(text,
            typed_action_response_format)
        end
        local rr_error_kind = nil
        local rr_runtime_error = nil
        local rr_error_debug = nil
        local typed_err = typed_action_metrics
          and tostring(typed_action_metrics.error or "") or ""
        if dmsg.run_status == "blocked_fragment"
           or dmsg.run_status == "blocked_action_context" then
          rr_error_kind = "validator_blocked"
          rr_runtime_error = "blocked lua artifact: "
            .. tostring(dmsg.validation_block_kind or dmsg.run_status)
          rr_error_debug = {
            failure_kind = "validator_blocked",
            source = "response_display",
            validation_block_kind = tostring(dmsg.validation_block_kind
              or dmsg.run_status),
            run_status = tostring(dmsg.run_status or ""),
          }
        elseif dmsg.run_status == "errored" then
          rr_error_kind = "runtime_error"
          rr_runtime_error = typed_err ~= "" and typed_err or "execution_failed"
          rr_error_debug = {
            failure_kind = "runtime_error",
            source = dmsg.code_type == "typed_actions"
              and "typed_action_executor" or "auto_run",
            runtime_error = rr_runtime_error,
            run_status = tostring(dmsg.run_status or ""),
          }
        end
        dmsg.run_result = Code.build_run_result(rr_code_type, rr_code,
          dmsg.run_status, dmsg.validation_status, {
            auto_ran = dmsg.auto_ran,
            auto_run_block_reason = dmsg.auto_run_block_reason,
            validation_block_kind = dmsg.validation_block_kind,
            error_kind = rr_error_kind,
            error_debug = rr_error_debug,
            runtime_error = rr_runtime_error,
          })
        if rr_error_kind and not dmsg.error_kind then
          dmsg.error_kind = rr_error_kind
        end
        if rr_error_debug and not dmsg.error_debug then
          dmsg.error_debug = rr_error_debug
        end
        if rr_runtime_error and not dmsg.runtime_error then
          dmsg.runtime_error = rr_runtime_error
        end
      end
      if type(dmsg.validation_trace) == "table"
         and type(dmsg.run_result) == "table" then
        dmsg.run_result.validation_trace = dmsg.validation_trace
      end
      -- The deferred path writes its own copy from typed_defer.finish, which
      -- runs after this block and rebuilds dmsg.run_result; the flag inside
      -- the recorder is what keeps the measurement line at one.
      if not typed_defer.pending then
        record_typed_action_unserved_fx(dmsg)
      end
      if effect_init_advisories and #effect_init_advisories > 0 then
        dmsg.validation_trace = dmsg.validation_trace or {}
        dmsg.validation_trace.advisories = effect_init_advisories
        if type(dmsg.run_result) == "table" then
          dmsg.run_result.validation_trace = dmsg.validation_trace
        end
      end
      if typed_action_lua_generation then
        local generation_ready = dmsg.code_type == "lua"
          and type(dmsg.code_block) == "string"
          and dmsg.code_block ~= ""
          and dmsg.truncated ~= true
          and type(lua_artifact_info) == "table"
          and lua_artifact_info.runnable == true
          and dmsg.validation_status == "manual_required"
        Net._mark_typed_action_lua_generation_complete(
          typed_action_lua_generation, generation_ready)
      end
    end
  end
  typed_defer.message_idx = #S.display_messages
  if lua_defer_pending and type(S.lua_defer_run) == "table" then
    if type(S.lua_defer_run.bind) == "function" then
      S.lua_defer_run.bind(#S.display_messages, _asst_hist_idx, true,
        S.probe_turn)
    else
      S.lua_defer_run.message_idx = #S.display_messages
      S.lua_defer_run.history_idx = _asst_hist_idx
      S.lua_defer_run.auto_ran = true
      S.lua_defer_run.probe_turn = S.probe_turn
    end
  end
  typed_defer.finish()
  if code_type == "lua" and code then
    Code.record_latest_code_candidate(code, "assistant", {
      artifact = lua_artifact_info,
      context_text = text,
    })
  end
  if auto_ran_ok and not typed_defer.pruned then
    Net.sticky_prune_after_plugin_success(_turn_user_intent, lua_code or code)
    typed_defer.pruned = true
  end
  if not typed_defer.pending then
    Probe.add_typed_action(S.probe_turn, typed_action_metrics)
  end
  Net._restore_typed_action_escalation_model()

  -- Prune oldest display messages beyond the soft cap to prevent unbounded
  -- memory growth. History is bounded by CFG.MAX_HISTORY_TURNS for the API;
  -- this caps the UI-only list. When we prune, also dump the wrap cache --
  -- it's keyed on raw segment text and would otherwise accumulate entries for
  -- every message ever rendered across a long session. The next frame rewrap
  -- is one-shot and imperceptible.
  if #S.display_messages > CFG.MAX_DISPLAY_MSGS then
    if Diag.uploader_enabled and Diag.capture_current_chat then
      Diag.capture_current_chat()
    end
    local pruned_count = Net._prune_display_messages(CFG.MAX_DISPLAY_MSGS)
    Net._rebase_display_message_refs(pruned_count)
    if typed_defer.message_idx and pruned_count > 0 then
      typed_defer.message_idx = typed_defer.message_idx - pruned_count
      if typed_defer.message_idx < 1 then typed_defer.message_idx = nil end
    end
    S.wrap_cache = {}  -- invalidate per-bubble text-wrap cache
  end

  Net._commit_google_interactions_pending(S.history)
  Code.safe_write(tmp.out, "")
  -- Response processing is complete. For deferred typed-action param writes,
  -- the execution result is finalized by typed_defer.finish() on the defer
  -- tick, but the request/resume state below is no longer needed. Leaves
  -- S.pending_code alone since that carries generated Lua the user may still
  -- want to Run manually.
  S.pending_orig_prompt = nil
  S.pending_typed_action_expected = false
  S.pending_typed_action_response_format = false
  S.pending_typed_action_profile = nil
  S.pending_answer_only_followup = nil
  S.pending_starter_card_key = nil
  S.pending_snapshot    = nil
  S.pending_project     = nil
  S.pending_attachments = nil
  Net._resolve_local_escalation("succeeded")
  S.pending_display_idx = nil
  S.pending_no_guess_seed = nil
  -- Final clear: this is the only spot in process_response that nils
  -- request_start_time. Earlier cleanup paths (empty-text error, normal
  -- cleanup at ~22087) deliberately leave it set so the docs-gate auto-
  -- retry can keep the in-flight "Thinking..." timer ticking across the
  -- silent retry curl. Once we reach here the turn is fully complete and
  -- the next send_to_api will overwrite anyway.
  S.request_start_time = nil
  S.status           = "idle"
  S.scroll_to_bottom = true
  -- Probe lifecycle: canonical "turn completed successfully" site
  -- for non-deferred turns. Deferred typed-action param writes close the same
  -- probe from typed_defer.finish() after the REAPER defer tick reports the
  -- actual result. Probe is currently a no-op compatibility surface.
  if S.probe_turn and not typed_defer.pending and not lua_defer_pending then
    Net._finish_probe_turn(S.probe_turn, "ok")
  end
end

Render = {}

-- =============================================================================
-- Shared factory-reset support
-- =============================================================================

function RA.delete_extstate_section(ns)
  if not ns or ns == "" then return 0 end
  local ini_path = reaper.GetResourcePath() .. "/reaper-extstate.ini"
  local f = io.open(ini_path, "r")
  if not f then return 0 end
  local keys = {}
  local in_section = false
  local line_no = 0
  for line in f:lines() do
    line_no = line_no + 1
    if line_no == 1 then line = line:gsub("^\xEF\xBB\xBF", "") end
    line = line:match("^%s*(.-)%s*$") or ""
    if line ~= "" and not line:match("^[;#]") then
      local sec = line:match("^%[(.-)%]$")
      if sec then
        in_section = (sec == ns)
      elseif in_section then
        local key = line:match("^([^=]+)")
        if key then
          key = key:match("^%s*(.-)%s*$") or ""
          key = key:gsub("\r$", "")
          if key ~= "" then keys[#keys + 1] = key end
        end
      end
    end
  end
  f:close()
  for _, k in ipairs(keys) do
    reaper.DeleteExtState(ns, k, true)
  end
  return #keys
end

function RA.delete_extstate_key_all(ns, key)
  if not ns or ns == "" or not key or key == "" then return end
  reaper.DeleteExtState(ns, key, false)
  reaper.DeleteExtState(ns, key, true)
end

function RA.clear_theme_backup_extstate()
  local ns = "ReaAssist"
  local manifest = reaper.GetExtState(ns, "ThemeBackup__KEYS")
  if manifest ~= "" then
    for key in manifest:gmatch("[^,]+") do
      key = key:match("^%s*(.-)%s*$") or ""
      if key ~= "" then
        RA.delete_extstate_key_all(ns, "ThemeBackup_" .. key)
      end
    end
  end
  RA.delete_extstate_key_all(ns, "ThemeBackup__KEYS")
  RA.delete_extstate_section(ns)
end

function RA.ensure_factory_reset_temp_dir(factory_reset_data_dir_cleared)
  if not (factory_reset_data_dir_cleared
      and RA.TEMP_DIR
      and RA.TEMP_DIR ~= ""
      and type(reaper.RecursiveCreateDirectory) == "function") then
    return
  end
  local temp_dir = tostring(RA.TEMP_DIR):gsub("[/\\]+$", "")
  if temp_dir ~= "" then pcall(reaper.RecursiveCreateDirectory, temp_dir, 0) end
end

function RA.factory_reset_execute(opts)
  opts = opts or {}
  local keep_screen_reader = opts.keep_screen_reader == true
  pcall(Theme.restore_backups)
  pcall(RA.clear_theme_backup_extstate)
  pcall(Custom.unregister_all)
  pcall(Net.gemini_cache_invalidate)

  RA.delete_extstate_section(CFG.EXT_NS)
  reaper.DeleteExtState(CFG.EXT_NS, "running",       false)
  reaper.DeleteExtState(CFG.EXT_NS, "request_close", false)
  reaper.DeleteExtState(CFG.EXT_NS, "dev_signal",    false)
  reaper.SetExtState(CFG.EXT_NS, "factory_reset_clean_boot", "1", false)
  if keep_screen_reader then
    reaper.SetExtState(CFG.EXT_NS, "prefer_screen_reader", "1", true)
  end

  S._suppress_geometry_save  = true
  S._suppress_os_theme_cache = true

  prefs.auto_run              = false
  prefs.auto_backup           = true
  prefs.show_details          = false
  prefs.custom_instructions_enabled = false
  prefs.debug_logging         = true
  prefs.include_api_ref       = false
  prefs.include_snapshot      = true
  prefs.update_check          = true
  prefs.stream_responses      = true
  prefs.show_reasoning_summaries = false
  prefs.reasoning_display_mode = "off"
  prefs.typed_actions_opt_in  = true
  prefs.diag_auto_tier        = "basic"
  prefs.test_force_cold_cache = false
  prefs.cloud_request_timeout = CFG.CLOUD_TIMEOUT_DEFAULT
  prefs.turn_cost_limit_usd   = CFG.TURN_COST_LIMIT_DEFAULT
  prefs.turn_token_limit      = CFG.TURN_TOKEN_LIMIT_DEFAULT
  prefs.provider_idx          = 1
  prefs.model_idx             = 2
  prefs.thinking_idx          = 0
  prefs.ui_scale_idx          = 3
  prefs.ui_scale_by_dpi       = {}
  prefs.theme                 = "auto"
  prefs.chat_font_idx         = 2
  prefs.reply_language_idx    = 1
  prefs.language_code         = "en"
  apply_palette(PALETTES[resolve_theme("auto")])
  S._reset_window_size = true
  Net.clear_conversation()
  S.api_key  = nil
  S.api_key_map = {}
  S.gemini_paid_tier = nil
  api_keys.key_bufs = {}
  api_keys.key_errors = {}
  api_keys.key_warnings = {}
  api_keys.key_error = nil
  api_keys.key_error_provider = nil
  api_keys.key_error_detail = nil
  api_keys.key_error_hint = nil
  api_keys.key_error_url = nil
  api_keys.key_error_url_label = nil
  api_keys.key_test_recovery = nil
  api_keys.key_focused = false
  api_keys.key_validating = false
  api_keys.key_validating_idx = nil
  api_keys.show_key_error_popup = false
  api_keys.show_test_results = false
  api_keys.test_results = {}
  api_keys.custom_edit = nil

  local factory_reset_data_dir_cleared = false
  do
    local function remove_family(path)
      if not path or path == "" then return end
      os.remove(path)
      os.remove(path .. ".tmp")
      os.remove(path .. ".bak")
      local dir, base = tostring(path):match("^(.*[\\/])([^\\/]*)$")
      if dir and base and type(reaper.EnumerateFiles) == "function" then
        local names = {}
        local index = 0
        while index < 4096 do
          local name = reaper.EnumerateFiles(dir, index)
          if not name then break end
          if name:sub(1, #base + 5) == base .. ".tmp."
              or name:sub(1, #base + 5) == base .. ".bak." then
            names[#names+1] = name
          end
          index = index + 1
        end
        for _, name in ipairs(names) do os.remove(dir .. name) end
      end
    end
    -- Data/ is the package root's, so that is what the containment check is
    -- measured against. Measuring against the app root would refuse every
    -- real Data path and Factory Reset would quietly clear nothing.
    local function safe_data_dir(dir)
      if not dir or dir == "" then return false end
      if not RA.PACKAGE_DIR or RA.PACKAGE_DIR == "" then return false end
      if dir:sub(1, #RA.PACKAGE_DIR) ~= RA.PACKAGE_DIR then return false end
      return dir:match("[/\\]Data[/\\]$") ~= nil
    end
    local function shell_path_safe(path)
      return type(path) == "string" and path ~= "" and not path:find('"', 1, true)
    end
    local function ps_escape(path) return tostring(path or ""):gsub("'", "''") end
    local function sq(path) return "'" .. tostring(path or ""):gsub("'", "'\\''") .. "'" end
    local function norm_dir(path)
      return tostring(path or ""):gsub("[/\\]+$", ""):lower()
    end
    local function remove_dir(path)
      if not path or path == "" then return end
      path = path:gsub("[/\\]+$", "")
      if path == "" then return end
      if os.remove(path) == true then return end
      if not shell_path_safe(path) then return end
      if RA.IS_WINDOWS then
        if type(reaper.ExecProcess) == "function" then
          local cmd = "powershell -NoProfile -WindowStyle Hidden"
            .. " -Command \"Remove-Item -LiteralPath '"
            .. ps_escape(path)
            .. "' -Recurse -Force -ErrorAction SilentlyContinue\""
          pcall(reaper.ExecProcess, cmd, 5000)
        end
      else
        os.execute("rmdir " .. sq(path) .. " >/dev/null 2>&1")
      end
    end
    local function clear_tree_contents(dir)
      if not dir or dir == "" then return end
      local sep = (dir:sub(-1) == "/" or dir:sub(-1) == "\\") and "" or RA.SEP
      local files = {}
      local idx = 0
      while true do
        local fn = reaper.EnumerateFiles(dir, idx)
        if not fn then break end
        files[#files + 1] = fn
        idx = idx + 1
      end
      for _, fn in ipairs(files) do
        -- Factory Reset preserves the internal-telemetry marker at the Data
        -- root. A reset development or test install must not silently rejoin
        -- the user statistics it is meant to be excluded from.
        if not (norm_dir(dir) == norm_dir(RA.DATA_DIR)
            and tostring(fn):lower() == "internal_telemetry.flag") then
          os.remove(dir .. sep .. fn)
        end
      end

      if type(reaper.EnumerateSubdirectories) ~= "function" then return end
      local dirs = {}
      idx = 0
      while true do
        local sub = reaper.EnumerateSubdirectories(dir, idx)
        if not sub then break end
        dirs[#dirs + 1] = sub
        idx = idx + 1
      end
      for _, sub in ipairs(dirs) do
        local child = dir .. sep .. sub
        -- Recurse FIRST, always, including into Data/Temp: only the Temp
        -- directory itself is kept (the store helpers expect it to exist),
        -- never its contents.
        --
        -- This walk is rooted at Data/ and never leaves it, which is what
        -- keeps it out of the quarantine's way. Until B2.2d the two slots
        -- were files in Data/Temp, so this loop deleted them and a Factory
        -- Reset counted as clearing the gate without verifying anything
        -- (Codex round 19). The records live under Recovery/ now, beside the
        -- launcher's own durable state, and nothing here reaches it.
        clear_tree_contents(child)
        if norm_dir(child) ~= norm_dir(RA.TEMP_DIR) then
          remove_dir(child)
        end
      end
    end
    if safe_data_dir(RA.DATA_DIR) then
      clear_tree_contents(RA.DATA_DIR)
      factory_reset_data_dir_cleared = true
    else
      remove_family(RA.CONFIG_PATH)
      remove_family(RA.PROVIDERS_PATH)
      remove_family(RA.STATE_PATH)
      remove_family(RA.CUSTOM_INSTRUCTIONS_PATH)
      remove_family(RA.DATA_DIR .. "FX_Cache.json")
      remove_family(RA.DATA_DIR .. "Debug.log")
      remove_family(RA.FX_CACHE_PATH)
      remove_family(Log and Log.path)
    end
    remove_family(RA._LEGACY_FX_CACHE_PATH)
    remove_family(RA._LEGACY_DEBUG_LOG_PATH)
    if Store then
      Store._config_doc = nil
      Store._config_snapshot_persisted = false
      Store._state_doc = nil
      Store._read_failed_paths = {}
      Store._write_locked_paths = {}
      Store._providers_load_state = nil
    end
  end
  if S and S.screen_reader_mode and ScreenReaderLegacy
      and ScreenReaderLegacy.factory_reset then
    ScreenReaderLegacy.factory_reset(
      Store, PROVIDERS, prefs, S, reaper, CFG)
    prefs.provider_idx = ScreenReaderLegacy.provider_idx(PROVIDERS)
    MODELS.refresh()
    ScreenReaderLegacy.finalize_startup(PROVIDERS, MODELS, prefs, S)
  end
  FXCache.invalidate()
  api_keys.screen     = "tos"
  api_keys.is_reentry = false
  S.refocus_prompt = true
  if I18N and I18N.set_language_code then
    I18N.set_language_code("en")
  end

  if S and S.screen_reader_mode then
    RA.ensure_factory_reset_temp_dir(factory_reset_data_dir_cleared)
    if keep_screen_reader then
      reaper.SetExtState(CFG.EXT_NS, "prefer_screen_reader", "1", true)
    end
    return true
  end
  if not (Updater and Updater.fire_relauncher_now
      and Updater.fire_relauncher_now()) then
    RA.ensure_factory_reset_temp_dir(factory_reset_data_dir_cleared)
    if UI and UI.show_float_toast then
      UI.show_float_toast(
        UI.t("settings.factory_reset.complete", nil,
          "Reset complete. Close and reopen ReaAssist to finish."), "ok", true)
    end
  end
  if keep_screen_reader then
    reaper.SetExtState(CFG.EXT_NS, "prefer_screen_reader", "1", true)
  end
  return true
end

-- =============================================================================
-- Uninstaller (plan section 5, work package B2.4)
-- =============================================================================
-- ReaPack stops carrying the application body after the transition, so
-- uninstalling through ReaPack alone would take the two entry points and leave
-- everything the in-app updater installed sitting on disk. This is the real
-- uninstaller, and the whole of it is shaped by one rule from section 5:
-- OWNERSHIP DECIDES.
--
--   * A launcher ReaPack owns is never deleted here. ReaPack reinstalls a
--     registered file it finds missing (measured in Dev/ReaPackSmoke), so
--     deleting one buys a moment of tidiness and a permanent argument between
--     two installers. Those installs are told to remove the package in
--     ReaPack, which is the only thing that can retire a registry entry.
--   * A launcher nobody owns is this body's to remove, and only when the
--     answer is a CONFIRMED unowned. Foreign and unknown are the absence of a
--     finding, exactly as they are in the updater's write path, and neither
--     authorizes a delete.
--   * User data is a SEPARATE offer that defaults to off. Nothing about
--     removing a program implies permission to remove what the user made
--     with it.
--
-- AND IT FAILS CLOSED, EVERYWHERE. This is the one operation in the app that
-- deletes the product itself, on a machine that may be running other copies of
-- it, so every question it cannot answer is a stop with a named cause and a
-- way forward rather than a step taken on a guess. It never erases an
-- unresolved update record, never removes a lock artifact it cannot prove is
-- nobody's, and never reports a file removed without probing for it
-- afterwards.
--
-- THE ORDER IS PART OF THE SAFETY, and it is:
--
--   1. Recovery/, which holds the parked copy of the body. It goes FIRST
--      because a launcher that finds the body missing restores it from there.
--      Removing the body while a parked copy still stands would let the next
--      launch undo the uninstall from local files, silently. An interruption
--      here leaves a complete working install with no parked copy, which is
--      the state a fresh install is in before its first update, so the user
--      simply runs Uninstall again.
--   2. The unowned launchers. After this no new launcher can start on this
--      install, which closes the window in which one could bootstrap the body
--      back while step 3 is taking it apart. An interruption here leaves an
--      install with no entry points and inert files, all of them named in the
--      report.
--   3. App/, the body. An interruption here leaves a partial body with no
--      parked copy: a ReaPack install still has its launchers and will
--      network-bootstrap a fresh body on the next run, which is the state
--      section 5 already describes for that lane, and a website install has
--      no entry point left to run at all.
--   4. Data/, and only when the user asked for it.
--
-- WHAT IT NEVER TOUCHES: REAPER's own Effects/ReaAssist folder (open projects
-- may reference those effects), the Scripts/ReaAssist folder holding scripts
-- ReaAssist saved for the user, anything under a directory it did not install
-- into, and any folder that still has something in it when the walk finishes.

-- Is this install one this uninstaller may take apart at the directory level?
--
-- The body's own root is removed as a TREE, so the containment question has to
-- be answered before any of it runs, and it has to be answered about the two
-- roots rather than about a name. A pre-restructure install has one directory
-- for both (RA.package_dir_for resolves flat when no marker-verified launcher
-- sits above the body), and there a tree removal rooted at the app root would
-- take Data/, Recovery/ and the launchers with it. That install is refused
-- outright: it has no launcher topology, so it is not the thing section 5
-- describes, and the documented standalone route covers it.
--
-- Returns true, or false plus the word for what was wrong.
function Updater.uninstall_layout()
  local pkg = tostring(RA.PACKAGE_DIR or "")
  local app = tostring(RA.APP_DIR or "")
  if pkg == "" or app == "" then return false, "root" end
  if app == pkg then return false, "flat" end
  if app:sub(1, #pkg) ~= pkg then return false, "outside" end
  local tail = app:sub(#pkg + 1):gsub("[/\\]+$", "")
  if tail ~= "App" then return false, "name" end
  return true
end

-- Every user-facing sentence this uninstaller says, through the same catalog
-- the rest of the product speaks through.
--
-- English is authored here as the fallback, exactly the way UI.t, ScreenReader.t
-- and AppController.t author theirs, so a language pack that has never seen
-- these keys degrades to this English word for word rather than to a key name.
-- The language-pack pipeline owns every other language; nothing here is
-- hand-translated.
function Updater.uninstall_t(key, values, fallback)
  return RA.t("uninstall." .. tostring(key), values, fallback)
end

-- WHERE THE UNINSTALL MARKER LIVES, AND WHY IT LIVES THERE.
--
-- The gate can refuse while another instance is running, but it cannot refuse
-- a launcher that starts in another REAPER window a moment AFTER it has read
-- everything it can read. That launcher finds the body still present, takes no
-- lock, and starts a live session on files this run is about to delete. The
-- lock protocol cannot close that: an ordinary launch deliberately takes no
-- lock, which is what makes it fast, and this side does not get to change the
-- launcher's protocol from here.
--
-- So the launcher is told instead, by a file it reads before it does anything
-- else. The marker sits at the PACKAGE ROOT, and that is the only place it can
-- sit: the run removes Recovery/ first, then the launchers, then App/, then
-- optionally Data/, and the package root itself is never removed by any of
-- them. It has to outlive all four, and it has to still be there for a
-- ReaPack-owned launcher, which this uninstaller never deletes and which
-- therefore keeps running after everything else is gone.
--
-- It is cleared by a DELIBERATE reinstall: the launcher that finds it asks the
-- user whether to install ReaAssist again, and only a yes removes it. Nothing
-- clears it automatically, because a bootstrap that cleared it would be the
-- silent reinstall the marker exists to prevent.
--
-- AND IT HAS TWO PHASES, WHICH IS THE WHOLE OF ROUND 49'S FIRST FINDING.
--
-- ACTIVE means a removal is running right now, or one was running and never
-- reached its end. While it stands, a launcher must not load the body and must
-- not offer to put ReaAssist back: the files it would load are the files this
-- run is deleting, and an offer somebody could accept would let one click in
-- another REAPER window clear the exclusion in the middle of the run. DONE
-- means the run finished and nothing anywhere is being written or removed any
-- more, and only then is the deliberate-reinstall question safe to ask,
-- because only then is there nothing left to race.
--
-- THE PHASE IS THE FIRST LINE, AND EVERYTHING ELSE IS ACTIVE. A file that will
-- not open, a first line that is not exactly the done line, an empty file left
-- by a write that was cut in half: each of them answers ACTIVE, because ACTIVE
-- is the answer that refuses. The done line is matched whole, its terminator
-- included, so a write that stopped part way through spelling it cannot be
-- read as one that finished.
--
-- IT IS NOT WRITTEN THROUGH THE ATOMIC WRITER, and that is a decision rather
-- than an omission. An atomic swap here means removing the name and renaming a
-- staged file onto it, and the instant when nothing is at the name is the one
-- instant a launcher must never see: it would read "no removal here" and load
-- the body. A rewrite in place is never absent, and never reads as done unless
-- the done line is whole, so every instant of it fails closed.
--
-- A RUN THAT DIES BETWEEN THE TWO PHASES leaves an ACTIVE marker on an install
-- that may still be whole, and no launcher will start it. That is the
-- fail-closed direction, and the way out is written in three places: in this
-- file's own words, in the launcher's refusal, and in the confirmation copy
-- before the user commits. Deleting the file by hand is the recovery. Teaching
-- the launcher to decide for itself, by reading the life files this body keeps,
-- would put a second reader for this body's format inside the frozen launcher,
-- which is the same thing this uninstaller refuses to do to the launcher's own
-- lock.
Updater.UNINSTALL_MARKER_DONE_LINE = "ReaAssist-uninstall: done"
Updater.UNINSTALL_MARKER_ACTIVE_LINE = "ReaAssist-uninstall: in progress"

function Updater.uninstall_marker_path()
  return tostring(RA.PACKAGE_DIR or "") .. "ReaAssist_uninstalled.txt"
end

-- nil when no marker stands, "done" for a removal that finished, and "active"
-- for every other answer including one that could not be read at all.
function Updater.uninstall_marker_phase()
  local path = Updater.uninstall_marker_path()
  if not RA.path_present(path) then return nil end
  local text
  local ok = pcall(function()
    local f = io.open(path, "rb")
    if not f then return end
    text = f:read("*a")
    f:close()
  end)
  if not ok or type(text) ~= "string" then return "active" end
  local done = Updater.UNINSTALL_MARKER_DONE_LINE .. "\n"
  if text:sub(1, #done) == done then return "done" end
  return "active"
end

-- Write the marker in one of its two phases and PROVE it reads back as that
-- phase, because a write nobody checked is a promise rather than a fact.
function Updater.uninstall_marker_write(phase)
  local path = Updater.uninstall_marker_path()
  if tostring(RA.PACKAGE_DIR or "") == "" then return false end
  local want = (phase == "done") and "done" or "active"
  local text
  if want == "done" then
    text = Updater.UNINSTALL_MARKER_DONE_LINE .. "\n\n"
      .. Updater.uninstall_t("marker.file_done", nil,
        "ReaAssist was uninstalled from this REAPER installation.\n\n"
        .. "This file is what tells the ReaAssist actions not to start the "
        .. "program or install it again on their own. Running a ReaAssist "
        .. "action while this file is here asks you whether to install "
        .. "ReaAssist again, and installing again removes this file.\n\n"
        .. "Deleting this file by hand has the same effect.\n")
  else
    -- AND IT TELLS THE TRUTH ABOUT AN INTERRUPTED RUN, which is round 50's
    -- second finding. It used to say only "delete this file and the actions
    -- will work again", and a run that died mid-walk leaves folders standing
    -- under names of ReaAssist's own: an install put back on those terms would
    -- have hidden them for ever. The way back is named here, in the file the
    -- user is being told to delete, because this is the one place they are
    -- certain to read before they act.
    text = Updater.UNINSTALL_MARKER_ACTIVE_LINE .. "\n\n"
      .. Updater.uninstall_t("marker.file_active",
        { path = Updater.uninstall_claim_journal_path() },
        "ReaAssist is being removed from this REAPER installation, or a "
        .. "removal was started and did not finish.\n\n"
        .. "While this file says that, the ReaAssist actions will not start "
        .. "the program and will not install it again, because the files "
        .. "they would start are the files being removed.\n\n"
        .. "If no removal is running, the last one was interrupted. Delete "
        .. "this file by hand and run a ReaAssist action again.\n\n"
        .. "A removal moves each folder aside under a name of its own before "
        .. "it empties it, so an interrupted one can leave folders standing "
        .. "under those names. ReaAssist writes down every one of them "
        .. "here:\n" .. Updater.uninstall_claim_journal_path() .. "\n\n"
        .. "The next time ReaAssist starts it puts back every folder on that "
        .. "list whose own name is free again, and names the ones it cannot. "
        .. "Leave that list where it is until then.\n")
  end
  local ok = pcall(function()
    local f = io.open(path, "wb")
    if not f then return end
    f:write(text)
    f:close()
  end)
  if not ok then return false end
  return Updater.uninstall_marker_phase() == want
end

function Updater.uninstall_marker_clear()
  local path = Updater.uninstall_marker_path()
  os.remove(path)
  return not RA.path_present(path)
end

-- =============================================================================
-- The claim journal
-- =============================================================================
-- ROUND 50'S SECOND FINDING, STATED PLAINLY: a run that dies with a folder
-- moved aside leaves that folder standing under a name only the dead run knew.
-- Nothing looked for those names, restoration happened only on the path the run
-- itself takes when it settles, and the marker's own words told the user to
-- delete the marker and carry on. An install put back on those terms hides the
-- application folder, the recovery folder, or the user's own data from every
-- later launch, and hides them under a name that looks like litter.
--
-- So every claim is WRITTEN DOWN BEFORE IT IS TAKEN, and somebody reachable
-- reads that list afterwards.
--
-- WHERE IT LIVES. Beside the marker, at the package root, and for the same
-- reason the marker lives there: the run removes Recovery/, then the launchers,
-- then App/, then optionally Data/, and the package root is the one directory
-- none of them touches. A journal inside a claimed tree would be a record of a
-- folder kept inside that folder.
--
-- WHAT IT SAYS. One line per event, appended, never rewritten:
--
--   claim<tab><the folder's own name><tab><the name this run gave it>
--   done<tab><the name this run gave it>
--
-- A claim with no matching done is OPEN. Reading is a fold over the whole file,
-- so a duplicate done is harmless and a torn last line resolves nothing rather
-- than resolving the wrong thing.
--
-- THE ORDERING IS THE WHOLE POINT. The line is on disk, and PROVEN to be on
-- disk by reading it back, before the rename that it describes happens. A crash
-- between the write and the rename leaves a record of a claim that never
-- happened, and the folder is still standing at its own name where the user can
-- see it. THE AUTHORITY TO RETIRE A RECORD BELONGS ONLY TO THE ATTEMPT THAT
-- MINTED IT, so a later reader keeps such a record and surfaces it rather than
-- taking it off. A crash the other way around, a rename with no record, is what
-- this ordering makes impossible.
--
-- AND AN UNRESOLVED RECORD IS NEVER ERASED. It is resolved by the attempt that
-- minted it, and only when that attempt can PROVE what happened to the folder;
-- every other reader surfaces it to the user and keeps it, whether or not the
-- questions it can ask are answered. That is the rule the update journal in
-- this same body has carried since round 22, taken one notch further. The file
-- itself is taken away only when nothing in it is open.
function Updater.uninstall_claim_journal_path()
  return tostring(RA.PACKAGE_DIR or "") .. "ReaAssist_uninstall_claims.txt"
end

-- The bytes on disk, or nil for a list that is there and cannot be read. It is
-- its own function because the framing rules below are about the bytes
-- themselves: which lines the file really terminated, and what an unterminated
-- tail at the end of it means.
function Updater.uninstall_claim_journal_bytes()
  local path = Updater.uninstall_claim_journal_path()
  if not RA.path_present(path) then return "" end
  local text
  local ok = pcall(function()
    local f = io.open(path, "rb")
    if not f then return end
    text = f:read("*a")
    f:close()
  end)
  if not ok or type(text) ~= "string" then return nil end
  return text
end

-- Every claim nobody has resolved yet, oldest first, plus the raw text the
-- answer was folded out of, plus what the fold could not make sense of. nil
-- means the file is there and could not be read, which is a state that is
-- surfaced and never acted on.
--
-- A LINE COUNTS ONLY IF THE FILE ITSELF TERMINATED IT, which is round 51's
-- second blocker. This side used to fold over `text .. "\n"`, manufacturing the
-- terminator the last line was missing: a crash in the middle of the one line
-- that resolves a record then read as a finished one and could retire the only
-- record of a stranded folder. An unterminated tail now resolves nothing,
-- retires nothing, and is surfaced.
--
-- AND A COMPLETE LINE THE FOLD CANNOT READ IS COUNTED RATHER THAN DROPPED.
-- While one is in the file the list is never taken away, because the
-- alternative is this side deciding that a file somebody else has rewritten
-- holds nothing worth keeping.
--
-- Each record carries whether it is this package's own to act on. That answer
-- is the containment rule below, and it is taken here so that every reader gets
-- the same one.
--
-- AND A CLAIM LINE MAY NAME THE RECORD IT REPLACES, which is round 52's second
-- blocker. When a parent goes back to its own name, every name below it changes
-- underneath the records that spell them, so the replacements are written
-- BEFORE the rename, and the original is taken off after it ONLY WHEN THIS
-- ATTEMPT MINTED IT. Between those two acts both records are on the list, and a
-- pair an attempt inherited keeps both lines for good, so the third field is
-- what lets a later reader tell that they are two descriptions of one folder
-- rather than two folders.
--
-- AND IT IS READ IN THE ORDER THE LINES WERE WRITTEN, which is round 54's
-- third blocker. Validating a successor against the FINAL contents of the file
-- accepted a line whose named predecessor was written AFTER it, or had already
-- been retired before it, neither of which this package can produce: a
-- replacement is appended while the record it replaces is still open. Both are
-- decided while the line is being folded, against the prefix of the file above
-- it, so a successor can only be honoured by a past this file really had.
--
-- AND A CLAIM LINE CARRIES THE VALUE ITS SEED WAS MINTED WITH, which is round
-- 56's second blocker. A later session has no run in memory to speak for a
-- record an earlier one wrote, so B2.4h let it read the seed's value for the
-- SHAPE this package's minting produces; anything that could list a directory
-- could then mint a file that answered. The value travels ON THE RECORD now, so
-- the question a later session asks is the same one the run that wrote it would
-- have asked. It is a fourth field, and the third is spelled empty when the
-- record replaces nothing, so the two are never read for each other.
--
-- AND IT IS EXACTLY AS STRONG AS THE LIST AND NO STRONGER, said here rather
-- than discovered later. Seed-value disclosure lets a reader forge the binding
-- value. Separately, an actor with write access to the journal can append
-- `done`, rewrite it, or remove it, with no probe of any kind. Those are two
-- capabilities and neither is assumed from the other, so a value on the list
-- costs nothing against anybody who already holds the one they need. What it
-- buys is everything short of that: a shape is mintable by anything that can
-- list a folder, and a value is not.
--
-- AND A LINE WITH NO VALUE ON IT IS STILL A RECORD, read and acted on exactly
-- as before, and simply never retired by a later session's reading. There is no
-- evidence on it for that session to ask about, so the folder is named and the
-- record is kept.
--
-- AND THAT FIELD IS READ AS A LINEAGE RATHER THAN AS A NAME, which is round
-- 53's second blocker. Checking only that it is a contained minted path let a
-- corrupted line name an UNRELATED record as the one it replaces, and the
-- successor's own restoration then retired that unrelated record: a line
-- nothing on this side wrote reaching in and closing the only description of
-- somebody else's folder. The field is honoured only when the record it names
-- is really on this list AND is really this record's predecessor, which is a
-- question with one right answer because there is exactly one way this package
-- makes a successor. A line whose third field is anything else is not this
-- package's to act on: it is surfaced with both of its names, moved nowhere and
-- left exactly as it is, which is what every other line this side could not
-- have written already gets.
function Updater.uninstall_claim_journal_read()
  local text = Updater.uninstall_claim_journal_bytes()
  if type(text) ~= "string" then return nil end
  local info = { torn = false, unknown = 0 }
  local open_by_private, older_by_private, order = {}, {}, {}
  local seed_by_private = {}
  -- Every private name this file ever carried a claim for, open or retired,
  -- because a predecessor MAY ALREADY BE RETIRED by the time the fold reaches a
  -- line that names it and the lineage question is still about the line that
  -- claimed it. A pair left behind by an interrupted attempt has both lines
  -- open instead, and this map holds them the same way. It is
  -- filled AS THE LINES ARE FOLDED, so what it holds at any line is what the
  -- file said above that line and nothing the file says below it.
  local public_by_private, foreign_by_private = {}, {}
  local at = 1
  while at <= #text do
    local nl = text:find("\n", at, true)
    if not nl then
      info.torn = true
      break
    end
    local line = text:sub(at, nl - 1)
    at = nl + 1
    local verb, rest = line:match("^(%a+)\t(.*)$")
    local known = false
    if verb == "claim" then
      -- EXACTLY TWO FIELDS, NEITHER CARRYING A CHARACTER THIS SIDE REFUSES TO
      -- WRITE. A record is only ever written from paths holding no tab and no
      -- carriage return, so a line holding one was not written by a claim this
      -- body took.
      --
      -- AND A THIRD FIELD, WHEN THERE IS ONE, is the private name of the record
      -- this one replaces. An empty one is not a field at all.
      --
      -- AND A FOURTH, WHEN THERE IS ONE, is the value the claim's own seed was
      -- minted with. A line that carries it spells the third field even when
      -- there is no predecessor, so a three-field line is always a lineage and
      -- never a value.
      local fields, whole = {}, rest:find("\r", 1, true) == nil
      if whole then
        for field in (rest .. "\t"):gmatch("([^\t]*)\t") do
          fields[#fields + 1] = field
        end
      end
      local public, private, older = fields[1], fields[2], fields[3]
      local seed = nil
      if #fields == 4 then
        seed = fields[4]
        if older == "" then older = nil end
      end
      if whole and (#fields == 2 or (#fields == 3 and older ~= "")
            or (#fields == 4 and seed ~= ""))
          and public ~= "" and private ~= "" then
        known = true
        -- AND THE LINEAGE IS DECIDED HERE, AT THE LINE, IN THE ORDER THE LINES
        -- WERE WRITTEN, which is round 54's third blocker. B2.4f built the
        -- whole map first and then asked whether the named predecessor was
        -- anywhere in it, so a successor written BEFORE its alleged
        -- predecessor, or written after that predecessor had already been
        -- retired, was accepted retroactively. Existing in the same file is not
        -- evidence: this package appends a replacement WHILE the record it
        -- replaces is still open, so the only line that can honestly name a
        -- predecessor is one whose predecessor was already on the list and
        -- still open at the moment the line was appended. That is a question
        -- about the prefix of the file above this line and nothing else, and it
        -- is asked of exactly that.
        local honoured = nil
        if older ~= nil then
          local before = public_by_private[older]
          if before ~= nil and open_by_private[older] ~= false
              and Updater.uninstall_claim_owned(public, private)
              and Updater.uninstall_claim_owned_name(older)
              and Updater.uninstall_claim_lineage(before, older, public,
                private) then
            honoured = older
          else
            -- A third field this side could not have written makes the whole
            -- line one it could not have written. It is surfaced with both of
            -- its names, moved nowhere and left exactly as it is.
            foreign_by_private[private] = true
          end
        end
        if open_by_private[private] == nil then order[#order + 1] = private end
        open_by_private[private] = public
        older_by_private[private] = honoured
        public_by_private[private] = public
        seed_by_private[private] = (seed ~= nil and seed ~= "") and seed or nil
      end
    elseif verb == "done" then
      if rest ~= "" and rest:find("[\t\r]") == nil then
        known = true
        if open_by_private[rest] ~= nil then open_by_private[rest] = false end
      end
    end
    if not known then info.unknown = info.unknown + 1 end
  end
  local out = {}
  for _, private in ipairs(order) do
    local public = open_by_private[private]
    if public then
      -- The lineage was answered at the line. What is left here is whether the
      -- record's own two names are this package's to act on, and whether the
      -- predecessor an honoured line named is still open by the end of the
      -- file. Retired by then is not corrupt: it is the ordinary end of the
      -- pair, and there is simply nothing left for the successor to close.
      local older = older_by_private[private]
      local owned = Updater.uninstall_claim_owned(public, private)
        and not foreign_by_private[private]
      local older_open = older ~= nil and open_by_private[older] ~= false
      out[#out + 1] = { public = public, private = private, older = older,
        older_open = older_open, owned = owned,
        seed = seed_by_private[private] }
    end
  end
  return out, text, info
end

-- THE SEAL THAT CLOSES A TORN LINE WITHOUT COMPLETING IT. Appending onto a line
-- the file never terminated would join this run's own record to the end of
-- somebody's half-written one, and closing that line with a bare newline would
-- be worse: a `done` line torn one character from its end would become a
-- finished one the instant this side terminated it. The seal is a carriage
-- return, which is the one character no field of a record may carry, so
-- whatever the torn line was it can no longer be read as a record at all.
Updater.UNINSTALL_CLAIM_SEAL = "\r\n"

-- Append one line and PROVE it is on disk AS A LINE OF ITS OWN, because a write
-- nobody read back is a promise rather than a record, and everything after this
-- depends on the record being there.
function Updater.uninstall_claim_journal_append(line)
  if tostring(RA.PACKAGE_DIR or "") == "" then return false end
  if type(line) ~= "string" or line == "" then return false end
  if line:find("[\n\r]") then return false end
  local before = Updater.uninstall_claim_journal_bytes()
  if type(before) ~= "string" then return false end
  local seal = ""
  if before ~= "" and before:sub(-1) ~= "\n" then
    seal = Updater.UNINSTALL_CLAIM_SEAL
  end
  local path = Updater.uninstall_claim_journal_path()
  local ok = pcall(function()
    local f = io.open(path, "ab")
    if not f then return end
    f:write(seal, line, "\n")
    f:flush()
    f:close()
  end)
  if not ok then return false end
  local after = Updater.uninstall_claim_journal_bytes()
  if type(after) ~= "string" then return false end
  -- The file only ever grows at its end, so what this write added is whatever
  -- stands past the bytes that were there before it, and the line has to stand
  -- WHOLE inside that. A line found anywhere else is somebody else's, and a
  -- line found as part of a longer one is not a record.
  if after:sub(1, #before) ~= before then return false end
  for candidate in after:sub(#before + 1):gmatch("([^\n]*)\n") do
    if candidate == line then return true end
  end
  return false
end

-- A path with a tab or a newline in it cannot be written down here without
-- making the record ambiguous, and an ambiguous record is worse than none. Both
-- callers treat a refusal as a claim that must not be taken, so such a folder
-- is walked under the pin or left whole rather than moved aside.
function Updater.uninstall_claim_recordable(path)
  return type(path) == "string" and path ~= ""
    and path:find("[\t\n\r]") == nil
end

-- WHICH NAMES A RECORD IS ALLOWED TO SPEAK ABOUT, which is round 51's third
-- blocker. The list is an ordinary text file at the package root. Nothing stops
-- a corrupted write, a disk fault or somebody's editor from putting other paths
-- in it, and the consumer's answers to a record are a rename and a
-- non-recursive rmdir, so a line naming a folder that was never ReaAssist's
-- would aim both of those at it. A record is acted on ONLY when it names this
-- package's own work; anything else is surfaced with both of its names, never
-- acted on and never erased.
--
-- The comparison is on a normalized key rather than on the text: separators
-- both ways, trailing separators, and case on Windows, which is how the rest of
-- this body spells the same question. A path carrying a `.` or `..` step is
-- refused outright rather than resolved, because resolving it here would be
-- this side deciding what a name means when only the filesystem can answer, and
-- `App\..\..\Somewhere` is exactly the shape that would escape a prefix test.
function Updater.uninstall_claim_path_key(path)
  if type(path) ~= "string" or path == "" then return nil end
  if path:find("[\t\n\r]") then return nil end
  local key = path:gsub("[/\\]+", "/"):gsub("/+$", "")
  if key == "" then return nil end
  for step in key:gmatch("[^/]+") do
    if step == "." or step == ".." then return nil end
  end
  if RA.IS_WINDOWS then key = key:lower() end
  return key
end

-- Inside that root, or that root itself. The separator is what keeps a sibling
-- out: `...\ReaAssistEvil` shares every character of `...\ReaAssist` and is a
-- different folder.
--
-- AND A ROOT THAT IS ITSELF UNDER A CLAIM COUNTS AS THE ROOT. The walk renames
-- each directory to a minted name BEFORE it descends, so every name below a
-- claimed folder is spelled with that name in it and a child's claim is
-- recorded under it: `<package>\~ra...\Resources` is `App\Resources` while the
-- run is inside it. The root's own last step is the one a claim can have
-- replaced, so that step may be either the root's name or a minted one, and
-- everything above it has to match exactly. That keeps the widest name this
-- rule will accept inside the package directory.
function Updater.uninstall_claim_within(root, key)
  if type(root) ~= "string" or root == "" then return false end
  if type(key) ~= "string" or key == "" then return false end
  if key == root or key:sub(1, #root + 1) == root .. "/" then return true end
  local parent = root:match("^(.*)/[^/]+$")
  if not parent or parent == "" then return false end
  if key:sub(1, #parent + 1) ~= parent .. "/" then return false end
  return Updater.uninstall_claim_shaped(
    key:sub(#parent + 2):match("^[^/]+") or "")
end

-- The three trees an uninstall removes, which are the only trees a claim is
-- ever taken in. They are read from this install's own paths, so a record from
-- another package's list cannot name a folder inside this one.
function Updater.uninstall_claim_roots()
  local roots = {}
  for _, dir in ipairs({ RA.APP_DIR, RA.DATA_DIR, RA.RECOVERY_DIR }) do
    local key = Updater.uninstall_claim_path_key(tostring(dir or ""))
    if key then roots[#roots + 1] = key end
  end
  return roots
end

-- The shape a claim name is minted in: `~ra`, this run's tag, and the counter
-- under it. Asked of a leaf, because that is all a claim ever adds to a parent.
--
-- TWO SHAPES SINCE B2.7c, and both are ours. The mint gained entropy in round
-- 83: the tag is longer and a fresh random component follows the counter, so an
-- actor who has seen one private name cannot compute the next. A name left on
-- disk by an interrupted run of an EARLIER release still carries the old shape,
-- and this question is asked of leftovers as much as of live names, so refusing
-- the historical one would make those unrecognizable to the very lane that
-- exists to account for them. Both are accepted and neither is loosened into a
-- wildcard: the tag is hex, the counter is digits, and the new tail is hex.
-- EXACTLY THE TWO SHAPES THIS PACKAGE HAS EVER MINTED, each asked whole
-- (Codex round 84). Asking the tag's length and the tail's format as separate
-- questions accepted three shapes no release ever produced: a historical tag
-- with a tail, a current tag without one, and a current tail of any length.
-- Those answers reach the ownership decision, so each spelling is written out
-- in one pattern and nothing between them is ours.
--
--   historical: ~ra + six hex + "-" + counter
--   current:    ~ra + ten hex + "-" + counter + "-" + eight hex
function Updater.uninstall_claim_shaped(leaf)
  if type(leaf) ~= "string" then return false end
  if leaf:match("^~ra%x%x%x%x%x%x%-%d+$") then return true end
  return leaf:match(
    "^~ra%x%x%x%x%x%x%x%x%x%x%-%d+%-%x%x%x%x%x%x%x%x$") ~= nil
end

-- Is this ONE name a name this package's own minting could have produced,
-- inside one of its own removal roots? Asked of the third field of a claim
-- line, which names a record rather than a pair: the same containment rule as
-- below, minus the question about a public name it does not carry.
function Updater.uninstall_claim_owned_name(private)
  local key = Updater.uninstall_claim_path_key(tostring(private or ""))
  if not key then return false end
  local inside = false
  for _, root in ipairs(Updater.uninstall_claim_roots()) do
    if Updater.uninstall_claim_within(root, key) then
      inside = true
      break
    end
  end
  if not inside then return false end
  return Updater.uninstall_claim_shaped(key:match("[^/]+$") or "")
end

-- Is this record about a folder inside one of this package's own removal roots,
-- moved aside under a name this package's own minting could have produced, in
-- the parent it would have been minted in?
function Updater.uninstall_claim_owned(public, private)
  local pub_key = Updater.uninstall_claim_path_key(tostring(public or ""))
  local priv_key = Updater.uninstall_claim_path_key(tostring(private or ""))
  if not pub_key or not priv_key then return false end
  local inside = false
  for _, root in ipairs(Updater.uninstall_claim_roots()) do
    if Updater.uninstall_claim_within(root, pub_key) then
      inside = true
      break
    end
  end
  if not inside then return false end
  local pub_parent = pub_key:match("^(.*)/[^/]+$")
  local priv_parent = priv_key:match("^(.*)/[^/]+$")
  if not pub_parent or not priv_parent then return false end
  if pub_parent ~= priv_parent then return false end
  -- Asked of the normalized key rather than of the text, so a name spelled
  -- with a trailing separator is the same name it would be without one.
  return Updater.uninstall_claim_shaped(priv_key:match("[^/]+$") or "")
end

-- ONE PARENT PUT-BACK, READ OFF TWO NAMES. Given two normalized keys, answer
-- the pair of prefixes that turn the first into the second when EXACTLY ONE
-- whole step of the path is spelled differently and that step is not the last
-- one. Anything else answers nothing at all, which is the answer a name that is
-- not the other name's successor deserves.
--
-- The last step is excluded because a successor is made by RE-ROOTING a record
-- under a parent that moved, so the step that changes is always an ancestor of
-- both names. Two records differing in their own last step are two folders.
function Updater.uninstall_claim_restep(before, after)
  if type(before) ~= "string" or type(after) ~= "string" then return nil end
  local at, from_end, to_end, steps = nil, nil, nil, 0
  local a, b = 1, 1
  while true do
    local a_next = before:find("/", a, true)
    local b_next = after:find("/", b, true)
    if (a_next == nil) ~= (b_next == nil) then return nil end
    local a_end = (a_next or (#before + 1)) - 1
    local b_end = (b_next or (#after + 1)) - 1
    steps = steps + 1
    if before:sub(a, a_end) ~= after:sub(b, b_end) then
      if at then return nil end
      at, from_end, to_end = steps, a_end, b_end
    end
    if not a_next then break end
    a, b = a_next + 1, b_next + 1
  end
  if not at or at == steps then return nil end
  return before:sub(1, from_end), after:sub(1, to_end), at
end

-- IS THE SECOND RECORD THE FIRST ONE RE-ROOTED BY A PARENT GOING BACK TO ITS
-- OWN NAME? That is the only way this package makes a successor, and the rule
-- is read straight off the one function that makes them:
-- uninstall_claim_repath_plan takes a parent moving from `from` to `to` and
-- rewrites every record spelled through `from` by replacing that prefix in BOTH
-- of its names, changing nothing else. So a real pair satisfies all of:
--   * the two private names differ in exactly one step, and it is not the last;
--   * the two public names differ in exactly that same step, spelled the same
--     way on each side, so the prefixes taken off both fields are one pair;
--   * that pair is itself a claim this package could have taken, which is the
--     containment rule the records themselves are held to: the parent's public
--     name inside one of this install's own removal roots, its private name a
--     name this package's minting could have produced, and both in one parent.
-- A third field naming anything else is not a predecessor, so it is not acted
-- on.
function Updater.uninstall_claim_lineage(before_public, before_private,
    after_public, after_private)
  local bpub = Updater.uninstall_claim_path_key(tostring(before_public or ""))
  local bpriv = Updater.uninstall_claim_path_key(tostring(before_private or ""))
  local apub = Updater.uninstall_claim_path_key(tostring(after_public or ""))
  local apriv = Updater.uninstall_claim_path_key(tostring(after_private or ""))
  if not bpub or not bpriv or not apub or not apriv then return false end
  local from, to, at = Updater.uninstall_claim_restep(bpriv, apriv)
  if not from then return false end
  local pub_from, pub_to, pub_at = Updater.uninstall_claim_restep(bpub, apub)
  if pub_from ~= from or pub_to ~= to or pub_at ~= at then return false end
  return Updater.uninstall_claim_owned(to, from)
end

-- `older`, when it is given, is the private name of the record this one
-- replaces, and it is written into the line rather than inferred afterwards
-- because only the writer knows it.
--
-- `seed` is the value the claim's own seed carries, and it is written for the
-- same reason: only the run that minted it knows it, and a later session that
-- has to decide whether the folder came back needs the question rather than a
-- likeness of it. A value carrying a tab, a carriage return or a newline is not
-- one this side minted, so the record is refused rather than written with a
-- field the reader would fold apart.
function Updater.uninstall_claim_record(public, private, older, seed)
  if not Updater.uninstall_claim_recordable(public)
      or not Updater.uninstall_claim_recordable(private) then
    return false
  end
  -- AND A RECORD THIS SIDE WOULD REFUSE TO READ IS NOT ONE IT WRITES. The
  -- consumer acts only on records naming this package's own work, so a claim
  -- whose names would not pass that test is never taken at all rather than
  -- written down and then ignored by everything that reads the list.
  if not Updater.uninstall_claim_owned(public, private) then return false end
  local tail = ""
  if older ~= nil then
    if not Updater.uninstall_claim_recordable(older) then return false end
    if not Updater.uninstall_claim_owned_name(older) then return false end
    tail = "\t" .. older
  end
  if seed ~= nil then
    seed = tostring(seed)
    if seed == "" or seed:find("[\t\r\n]") then return false end
    tail = "\t" .. tostring(older or "") .. "\t" .. seed
  end
  return Updater.uninstall_claim_journal_append(
    "claim\t" .. public .. "\t" .. private .. tail)
end

-- WHOSE RECORD IS IT TO RETIRE, which is round 58's blocker and the one rule
-- this round adds. THE AUTHORITY TO RETIRE A RECORD BELONGS ONLY TO THE RUN
-- THAT CREATED IT.
--
-- Round 57 closed the arm where a later session read a value off the list and
-- retired on it. What it did not close is the same retirement reached one step
-- around: recovery calls the put-back, the put-back plants a FRESH value into
-- whatever directory is standing at the recorded private name, renames it, and
-- marks the record; the accounting pass then closes that record on a value THE
-- RECOVERING SESSION ITSELF MINTED, against an object nothing ever verified.
-- An actor carries the folder away, leaves an ordinary directory at the private
-- name, and the session stamps and proves its own substitute before erasing the
-- only description of the original. A NONCE IS EVIDENCE ONLY WHEN THE RUN THAT
-- ASKS ABOUT IT MINTED IT AT CLAIM TIME, before anything could substitute the
-- object; one minted later, by anybody, against whatever is standing at a name
-- read off a list, proves only that the session stamped something.
--
-- SO PROVENANCE IS CARRIED IN MEMORY AND NOWHERE ELSE, because a mark on the
-- list would be a mark an actor could write. There are two strengths of it and
-- they are not the same authority:
--   * MINTED. This run planted the seed and minted its value BEFORE the rename
--     the record describes. That is the only thing a nonce can be evidence for,
--     and it is also the only thing that makes this run's own parent rename
--     evidence about the folders the records below it name.
--   * WRITTEN. This run wrote the line itself, in this run, as a replacement
--     for a record it inherited. It may take that line back off when its own
--     act has disproved it, because the record it replaced is still open and
--     still describes the folder, and it may never be settled on a value.
-- A record with neither is one this run found on disk, and no act of this run's
-- takes it away.
function Updater.uninstall_claim_authority(private, minted)
  private = tostring(private or "")
  if private == "" then return false end
  local held = Updater._uninstall_claim_authority
  if type(held) ~= "table" then
    held = {}
    Updater._uninstall_claim_authority = held
  end
  if minted == true then
    held[private] = "minted"
  elseif held[private] == nil then
    held[private] = "written"
  end
  return true
end

-- `minted` asks for the stronger of the two. Everything that decides an
-- outcome from a VALUE asks for it; the one caller that asks for the weaker is
-- the rollback of a line this run wrote moments earlier and then disproved.
function Updater.uninstall_claim_authorized(private, minted)
  local held = Updater._uninstall_claim_authority
  if type(held) ~= "table" then return false end
  local at = held[tostring(private or "")]
  if at == "minted" then return true end
  return minted ~= true and at == "written"
end

-- AND AN AUTHORITY IS EVIDENCE ONLY FOR THE ATTEMPT THAT MINTED IT, which is
-- round 59's blocker and the last notch of the same rule. B2.4k scoped
-- provenance to the PROCESS, and an uninstall attempt is not a process: a stop
-- ends the attempt by clearing the running marker and leaves the barrier
-- willing to run another one in the same window, so a table that outlived the
-- stop handed the retry a minted answer for a private name it had never
-- claimed. Between the two attempts the name is nobody's: the stop gave the
-- lock back and put the folder down, so an actor can stand an ordinary
-- directory at it, and the retry's recovery would then stamp and retire the
-- record of the substitute. That is round 58's defect exactly, reached through
-- a stopped attempt instead of a later session.
--
-- SO BOTH TABLES DIE TOGETHER AND THEY DIE EMPTY. The pending marks are the
-- same trust in a second shape: the accounting pass asks the mark and never
-- asks the authority again, so a mark that survived the stop would settle a
-- record in the retry with no authority of any kind standing behind it. There
-- is nothing to keep in either of them once the attempt is over. A record this
-- attempt put back and could not account for is still on the list, and the
-- next reader of that list is a session with no run behind it, which is the
-- one thing this whole lane is built to be conservative about.
--
-- WHY A CLEAR RATHER THAN A SERIAL ON EACH ROW. A row stamped with the
-- attempt it belongs to would leave the stale rows in memory and make the rule
-- depend on every reader remembering to compare the stamp, which is one more
-- guard at each of the places B2.4k had to gate one by one. Emptying the
-- tables cannot be partially right: after it, every question about every name
-- answers exactly as it does in a window that has never run an uninstall.
function Updater.uninstall_claim_attempt_forget()
  Updater._uninstall_claim_authority = nil
  Updater._uninstall_claim_pending = nil
  return true
end

function Updater.uninstall_claim_resolve(private)
  if not Updater.uninstall_claim_recordable(private) then return false end
  return Updater.uninstall_claim_journal_append("done\t" .. private)
end

-- A RECORD IS CLOSED ONLY ON PROOF THAT NOTHING IS STANDING UNDER THE NAME ONLY
-- THIS RUN HAS SPELLED. It is one rule rather than a decision taken again at
-- each of the places that reach it, and round 51 is why: the two paths that
-- closed a record while a folder they could not prove was still standing under
-- its private name were the two that abandoned a stranger's folder there.
function Updater.uninstall_claim_settle(private)
  if RA.path_present(private) then return false end
  return Updater.uninstall_claim_resolve(private)
end

-- WHAT THIS RUN PUT BACK, HELD IN MEMORY UNTIL THE LIST IS READ AGAIN.
--
-- A PUT-BACK NO LONGER CLOSES ITS OWN RECORD, which is round 54's first
-- blocker taken to its end. B2.4f wrote the rule as a proof about the folder at
-- the public name, and no chain of these primitives can be that: the rename is
-- refused while anything inside the folder is held open (P41), so the folder is
-- unpinned in the instant the rename lands, the handle can only be taken back
-- through a name, and a junction planted at that name in that instant carries
-- every later question to the folder wherever the actor has put it. The
-- measured chain narrows that to one instant and makes the redirect SEEN
-- (uninstall_claim_bound), and it is still not a proof, so it settles nothing.
--
-- SO THE RECORD IS RETIRED BY AN ACCOUNTING RULE ABOUT THE LIST INSTEAD, read
-- once, later, by the accounting pass of the attempt that minted the record.
-- That is not a proof either and is not offered as one: a record describes a
-- folder displaced to a private name, and when that name is free and the folder
-- at its own name answers for the file this run planted inside it and the value
-- this run minted before the rename, there is nothing displaced left to
-- describe. THE AUTHORITY TO APPLY IT BELONGS ONLY TO THE ATTEMPT THAT MINTED
-- THE RECORD, which is where rounds 58 and 59 put it. A later reader inherits
-- the record, keeps it and surfaces it, and never retires it. What changes here
-- is only WHO may apply the rule and WHEN: never the act that moved the folder,
-- and never in the same breath.
-- AND THE MARK CARRIES THE EVIDENCE RATHER THAN A WORD, which is round 55's
-- first blocker. B2.4g's mark said only "standing" and the accounting pass then
-- had nothing of the folder to ask about, so it asked the name instead. What
-- travels now is the file this run put inside the folder and the value it
-- wrote into it, which is the one thing on this machine an actor cannot mint:
-- it exists in this run's memory and nowhere else. `finish` says whether the
-- record's own put-back is the one that may finish an already-emptied folder,
-- and only the consumer's put-back sets it.
--
-- The public name is NOT carried here. It is read off the record itself when
-- the list is read, so a parent put-back that re-spells every name below it
-- re-spells this one too, and the mark cannot go stale against it.
function Updater.uninstall_claim_pending(private, leaf, nonce, finish)
  if not Updater.uninstall_claim_recordable(private) then return false end
  -- AND A VALUE IS EVIDENCE ONLY FOR THE RUN THAT MINTED IT AT CLAIM TIME,
  -- which is round 58's blocker and the gate the accounting pass stands behind.
  -- Everything this table carries is read later by uninstall_claim_account and
  -- turned into a closed record, so a mark taken for a record this run did not
  -- create is the indirect retirement itself: the value would be one this
  -- session minted, moments ago, against whatever was standing at a name it
  -- read off a list. Refusing here is what makes a recovering session incapable
  -- of accounting for anything it inherited, however the put-back went.
  if not Updater.uninstall_claim_authorized(private, true) then return false end
  Updater._uninstall_claim_pending = Updater._uninstall_claim_pending or {}
  Updater._uninstall_claim_pending[private] = {
    leaf = tostring(leaf or ""),
    nonce = tostring(nonce or ""),
    finish = finish == true,
  }
  return true
end

-- THE ACCOUNTING PASS. It reads the list, and for each record THIS ATTEMPT
-- MINTED AND PUT BACK it asks the two questions the rule is made of. A record
-- this attempt inherited leaves no mark for it to read (uninstall_claim_pending
-- refuses one), so this pass never asks about such a record and never closes
-- one.
--
--   * the private name is free. The record says a folder is standing there and
--     nothing is.
--   * the folder's own name is BOUND TO THE FILE THIS RUN PUT INSIDE THE
--     FOLDER, which is round 55's first blocker and the whole of this round.
--     B2.4g asked the measured removal at that name and read any REFUSAL as the
--     record being accounted for. A refusal is what any non-empty directory
--     gives, so a folder carried away and replaced with a stranger's directory
--     retired the record, and so did a permission failure and a shell this side
--     could not reach. What is asked instead is uninstall_claim_bound, which
--     starts inside the folder with a handle on this run's own file and ends
--     with the one act on Windows that a junction cannot survive. A junction
--     standing where the folder belongs is TAKEN by that question and reported
--     rather than followed; anything this side cannot bind keeps the record.
--
-- AND THE FILE COMES OUT ONLY AFTER THE RECORD IT PROVED IS CLOSED. A crash
-- between the two leaves one file of ReaAssist's own inside a folder that is
-- back where it belongs, which is litter; the other order leaves a record no
-- later reader could ever prove, which is a folder described forever. One that
-- will not come out is handed back so the run that asked can name it.
--
-- ANYTHING ELSE KEEPS THE RECORD, and the list then outlives the run and the
-- report says so. That is the price of not closing a record on a name, and it
-- is a price rather than a defect: the list is the only description this
-- machine has of a folder ReaAssist moved.
--
-- Returns how many records were closed, the files of this run's own that would
-- not come back out, and the already-emptied folders this pass finished.
function Updater.uninstall_claim_account()
  local pending = Updater._uninstall_claim_pending
  local strays, finished = {}, {}
  if type(pending) ~= "table" then return 0, strays, finished end
  local records = Updater.uninstall_claim_journal_read()
  if type(records) ~= "table" then return 0, strays, finished end
  local closed = 0
  for _, record in ipairs(records) do
    local private = tostring(record.private)
    local mark = pending[private]
    if record.owned and type(mark) == "table"
        and not RA.path_present(private) then
      local public = tostring(record.public)
      local bound = Updater.uninstall_claim_bound(public, mark.leaf, mark.nonce)
      if bound and Updater.uninstall_claim_settle(private) then
        pending[private] = nil
        closed = closed + 1
        -- AND THE RECORD THIS ONE REPLACED GOES WITH IT, never before it. The
        -- successor's own account is what accounts for the pair, so a
        -- predecessor retired on a successor that was never accounted for
        -- would be the only description of the folder erased on nothing.
        if record.older and record.older_open then
          Updater.uninstall_claim_settle(record.older)
        end
        local seed = public .. RA.SEP .. tostring(mark.leaf)
        if not Updater.uninstall_remove_file(seed) then
          strays[#strays + 1] = seed
        elseif mark.finish then
          -- AND A FOLDER AN INTERRUPTED RUN HAD ALREADY EMPTIED IS FINISHED
          -- HERE, once its own file is out of it and never before. It is the
          -- last act of that run rather than a new one, it happens at the
          -- folder's own name on the folder the question above had just bound,
          -- and a non-recursive rmdir refuses anything holding anything, so a
          -- folder with the user's work in it stays exactly where it was put
          -- back. It settles nothing: the record it belongs to is already
          -- closed, on the binding rather than on this removal.
          local _, kind = Updater.uninstall_remove_empty_dir_kind(public)
          if kind == "removed" then finished[#finished + 1] = public end
        end
      end
    end
  end
  return closed, strays, finished
end

-- What to do with a folder standing under a private name that this side cannot
-- prove is the one it renamed there.
--
-- IT IS NOT LEFT THERE. A private name is minted litter: the user has never
-- seen it, nothing points at it, and a folder abandoned under one is a folder
-- nobody will look for. So it goes to the name the report can name, which is
-- the name the rename took it from, and only ever into a name nothing is
-- standing at, because a rename onto a taken name fails on Windows and can
-- merge on POSIX and neither is an answer. When that cannot happen the record
-- stays OPEN and the next session tries again, which is the promise the
-- consumer already makes for every other folder on the list.
--
-- AND THE RENAME NEVER FOLLOWS A LINK, which is round 52's first blocker. This
-- put-back used to rename an UNPROVEN name. An actor needed no secret of this
-- run's to abuse it: replace the folder at the private name with a junction and
-- the rename carries that junction's EXTERNAL target onto one of ReaAssist's
-- own names, which is an unrelated folder relocated INTO this install. Keeping
-- the record open does not undo a move that has already happened, so the answer
-- has to be prevention where prevention is possible.
--
-- THE SAME PRIMITIVE THAT MADE THE CLAIM DECIDABLE MAKES THIS ONE DECIDABLE,
-- and both halves were measured on this machine rather than reasoned about. A
-- non-recursive rmdir TAKES A JUNCTION whatever its target holds, and REFUSES a
-- real directory that holds anything at all. So one file of this run's own goes
-- in first, and the question is asked immediately afterwards:
--   * the removal SUCCEEDS: nothing but a link could have gone with a file of
--     this run's inside it. The link is gone, everything it pointed at is
--     untouched, NOTHING WAS RENAMED, and the folder this record describes is
--     not here. The record stays OPEN and the outcome is named.
--   * the removal is REFUSED: a real directory held this run's file at that
--     instant, and that is the only state the rename is allowed to act on.
--
-- AND A RENAME THAT LANDED IS THE ONLY ACT HERE THAT CAN EVER COUNT TOWARDS
-- CLOSING A RECORD, which is round 53's first blocker. Nothing in this function
-- closes one, as the paragraph below says; what a rename buys is a mark for the
-- attempt's own accounting pass, and only when that attempt minted the record.
-- B2.4e took the file back out and asked the same question
-- a SECOND time, so that a directory holding nothing but it, which is what an
-- interrupted run leaves when it emptied a folder and died before removing it,
-- was taken away rather than put back as an empty shell. That second answer
-- could never be a proof and the state matrix is why. A removal that succeeds
-- says the name went; it does not say the name was still the directory the
-- first refusal saw. Between the file coming out and the question being asked
-- the directory can be MOVED AWAY, and the ask then answers true because the
-- name is absent; or it can be REPLACED WITH A LINK, and the ask then answers
-- true because it took the link. The first refusal proved only that the folder
-- held AT LEAST this run's file, never that it held nothing else, so both of
-- those cells settled the record of a folder that still had the user's work in
-- it and had gone somewhere this side cannot name.
--
-- SO THE EMPTY SHELL IS FINISHED AT THE FOLDER'S OWN NAME INSTEAD, after a
-- rename this run performed. The rename is self-checking in a way the removal
-- is not: a rename that followed a link leaves the link standing at the old
-- name (P19), and a rename that landed leaves the old name free (P18).
--
-- AND THE READ THROUGH THE FOLDER'S OWN NAME IS NOT A PROOF, which is round
-- 54's first blocker and the sharpest thing this lane has had to write down. A
-- PROOF ABOUT AN OBJECT IS ONLY A PROOF IF NO STEP OF IT CAN BE REDIRECTED BY A
-- NAME. B2.4f read this run's own file back through the folder's own name and
-- called a match proof of what was standing there; a junction put at that name
-- after the rename carries the read straight through to the folder wherever an
-- actor has moved it, so the private name is free, the rename did happen, and
-- the value matches, with no knowledge of this run's value at all (P38).
--
-- WHAT IS ASKED INSTEAD IS uninstall_claim_bound, and what it answers is one
-- instant rather than a fact about the folder: the file is opened THROUGH the
-- folder's own name and HELD, a mark only that descriptor can have written is
-- asked for by name, the measured removal is asked at that name while the
-- handle is open, and on Windows the name is asked to rename onto itself, which
-- only a directory a handle is open inside refuses. That makes the redirect
-- SEEN. It does not make it impossible, and no ordering of these primitives
-- does: the rename is refused while anything inside the folder is held open
-- (P41), so the folder is unpinned in the instant the rename lands and the
-- handle can only be taken back through a name.
--
-- SO NOTHING HERE CLOSES A RECORD AT ALL. The put-back marks what it did and
-- the accounting pass reads the list later; see uninstall_claim_pending.
--
-- THE WINDOW THAT IS LEFT, NAMED RATHER THAN CLAIMED AWAY. Between the refusal
-- and the rename a swap is still possible, and it cannot be closed with these
-- primitives: an open handle inside the directory would hold the name still,
-- but the same handle makes the rename itself fail, so it has to be let go
-- before the rename can happen. What that window costs is bounded on all three
-- sides. NOTHING IN IT DELETES ANYTHING THAT HOLDS ANYTHING, because the only
-- removals here are a non-recursive rmdir and this run's own file. THE MOVE IS
-- NEVER SILENT, because a rename that followed a link leaves the link standing
-- at the old name, so a private name that survives its own rename is proof the
-- rename took something else, and that is reported with all three of its
-- places. AND THE RECORD IS KEPT, because nothing this side could not prove is
-- ever closed behind.
--
-- Returns the name the folder is standing under now, and a note saying which of
-- those answers this was.
function Updater.uninstall_claim_restore(private, public)
  local note = { outcome = "gone", private = private, public = public }
  if not RA.path_present(private) then return public, note end
  note.outcome = "taken"
  if RA.path_present(public) then return private, note end
  -- THE RECORDS OF ANYTHING INSIDE IT GO FIRST, because this rename is a parent
  -- move and every name below it is about to change. A replacement this side
  -- cannot write down stops the put-back rather than making the old names stale
  -- with nothing standing in for them.
  local moves, ready = Updater.uninstall_claim_repath_plan(private, public)
  if not ready then
    Updater.uninstall_claim_repath_commit(moves, false)
    note.outcome = "records"
    return private, note
  end
  local probe = Updater.uninstall_claim_name(private)
  local mark = Updater.uninstall_claim_nonce()
  local leaf = probe and (tostring(probe):match("[^/\\]+$") or "") or ""
  local planted = probe ~= nil and pcall(function()
    local f = io.open(probe, "wb")
    if not f then return end
    f:write(mark)
    f:close()
  end)
  if not planted or not Updater.uninstall_claim_proof(probe, mark) then
    if probe then os.remove(probe) end
    Updater.uninstall_claim_repath_commit(moves, false)
    note.outcome = "undecided"
    return private, note
  end
  if Updater.uninstall_remove_empty_dir(private) then
    -- A LINK STOOD AT THE NAME, and this run's own file went through it into
    -- whatever it pointed at before the question could be asked. Once the link
    -- is gone there is no path from here to that file, so it is named.
    Updater.uninstall_claim_repath_commit(moves, false)
    note.outcome = "link"
    note.probe = leaf
    return private, note
  end
  -- THE RENAME, WITH THIS RUN'S OWN FILE STILL INSIDE THE FOLDER, deliberately:
  -- the file is what makes the folder at the other end of the rename provable,
  -- and taking it out first would put a window between the last proof and the
  -- rename for nothing.
  local moved = os.rename(private, public)
  local standing = RA.path_present(private)
  if moved and standing then
    -- THE RENAME FOLLOWED A LINK SWAPPED INTO THAT WINDOW. What is at the
    -- folder's own name now came from outside this install and this run's own
    -- rename is what moved it there, the link is still standing at the private
    -- name, and where the folder this record described went is not something
    -- this side can answer. All of it is said, the file this run wrote went
    -- with that folder wherever it is, and the record is kept.
    Updater.uninstall_claim_repath_commit(moves, false)
    note.outcome = "breach"
    note.probe = leaf
    return public, note
  end
  -- THE QUESTION THE FOLDER'S OWN NAME IS ASKED, and B2.4f's bare read is gone
  -- from it. The file this run wrote travelled inside the folder, so it is
  -- opened THROUGH the folder's own name and HELD, and every question after
  -- that is asked with the handle open: a junction is taken and says so, a real
  -- directory holding this side's own open file refuses, a name that has gone
  -- says that, and a name that is a real directory this side's handle is NOT
  -- inside is caught by the rename probe. See uninstall_claim_bound for what
  -- that answers and what it still cannot answer.
  local held, held_kind
  if moved and not standing then
    held, held_kind = Updater.uninstall_claim_bound(public, leaf, mark)
  end
  if held then
    -- THE STRONGEST ANSWER THESE PRIMITIVES GIVE, AND IT CLOSES NOTHING. This
    -- run asked for the rename, the private name is free afterwards, and at the
    -- instant it asked, the folder's own name was bound to the file this run
    -- had put inside the folder. The record is left OPEN and marked, and the
    -- accounting pass reads the list later.
    --
    -- AND THIS RUN'S OWN FILE STAYS WHERE IT IS, which is round 55's first
    -- blocker taken to its end: it is the evidence the accounting pass asks its
    -- question of, so taking it out here would leave that pass with nothing of
    -- the folder to ask about and nothing but the name to read. The pass takes
    -- it out once the record it proved is closed, and finishes an already
    -- emptied folder after it.
    --
    -- AND FOR A RECORD THIS RUN DID NOT CREATE, THE MARK IS REFUSED AND THE
    -- FILE COMES BACK OUT, which is round 58's blocker. The value planted above
    -- was minted by THIS session against whatever was standing at a name it
    -- read off the list, so it can prove that this side stamped something and
    -- never which object it stamped. Its only purpose was the settlement that
    -- is now forbidden, so leaving it inside the folder would be litter no pass
    -- will ever ask about or take out again: the question a later session asks
    -- is asked of the record's OWN seed, under the leaf the private name
    -- carries, which is untouched by any of this. The folder still went back,
    -- and the record still stays open on its own terms.
    if not Updater.uninstall_claim_pending(private, leaf, mark, true) then
      local left = public .. RA.SEP .. leaf
      if not Updater.uninstall_remove_file(left) then note.stray = left end
    end
    Updater.uninstall_claim_repath_commit(moves, true)
    note.outcome = "restored"
    return public, note
  end
  if standing then
    -- THE RENAME DID NOT HAPPEN AND THE FOLDER IS STILL UNDER THE NAME THIS RUN
    -- GAVE IT. Nothing was moved, the record stays open, and the next session
    -- tries again. This run's own file comes back out of the folder.
    os.remove(probe)
    if RA.path_present(probe) then note.stray = probe end
    Updater.uninstall_claim_repath_commit(moves, false)
    note.outcome = "refused"
    return private, note
  end
  Updater.uninstall_claim_repath_commit(moves, false)
  if held_kind == "removed" then
    -- A LINK WAS STANDING AT THE FOLDER'S OWN NAME AND THE QUESTION TOOK IT,
    -- which is round 54's first blocker caught rather than followed. The rename
    -- landed and the private name is free, so this run really did move the
    -- folder to its own name; something then moved it on and put a link where
    -- it had been, and every bare read of that name would have gone straight
    -- through to the folder wherever it now is. The link is gone, everything it
    -- pointed at is untouched, the file this run wrote is inside that folder,
    -- and where the folder is is not a question this side can answer. Nothing
    -- is closed and all of it is said.
    note.outcome = "redirected"
    note.probe = leaf
    return public, note
  end
  if moved then
    -- THE RENAME LANDED ON SOMETHING THIS SIDE CANNOT PROVE IS THE FOLDER. The
    -- private name is free, so nothing is standing behind, but what is at the
    -- folder's own name does not carry the file this run wrote into the folder
    -- it asked about. Two hands reach this: a link swapped in and taken away
    -- again after the rename had followed it, and the whole directory replaced
    -- with another real one. Neither is a restoration, so nothing is closed and
    -- the report says what the rename really did rather than naming a mechanism
    -- this side cannot see.
    note.outcome = "unproven"
    return public, note
  end
  -- THE PRIVATE NAME WENT WHILE THIS SIDE WAS ASKING ABOUT IT, and no rename of
  -- this run's put anything anywhere. Something may be standing at the folder's
  -- own name and this side cannot prove it is the folder: B2.4e read that state
  -- as a restoration somebody else had completed and CLOSED the record on it,
  -- which is round 53's other race. A rename that did not happen proves
  -- nothing, so the record is kept, both names are reported, and the next
  -- session or the user decides.
  note.outcome = "vanished"
  return public, note
end

-- THE LIST FOLLOWS THE FOLDERS. A claim inside a claimed folder is recorded
-- with the name it really has while the walk is inside it, which is spelled
-- with the parent's private name; when the parent goes back to its own name,
-- every one of those names changes underneath the record. Without this the
-- record would name two places that no longer exist, the consumer would prove
-- nothing is standing at either and resolve it, and a folder still standing
-- under a minted name inside the restored parent would have lost the only
-- description of where it is. That is the same class of defect as round 51's
-- second and third findings: a record that has stopped describing what is
-- really on disk.
--
-- THE NEW RECORDS ARE WRITTEN AND PROVEN BEFORE THE RENAME, NOT AFTER IT, which
-- is round 52's second blocker. B2.4d wrote them after, so a crash in between
-- left every child record naming a path through a parent name that no longer
-- existed, and the consumer then proved nothing stood at either name and
-- RESOLVED the record, erasing the only description of where the nested folder
-- had gone. The whole point of the list is that it survives exactly that crash.
--
-- SO THE PROTOCOL IS THREE ACTS AND THE ORDER IS THE PROTOCOL.
--   1. Write and PROVE the replacement records, each naming the record it
--      replaces, while the old names are still true.
--   2. Rename the parent.
--   3. Take off whichever of the two descriptions the disk has made false, and
--      only on proof that nothing is standing under its name, and only when
--      this attempt minted the record being taken off. A pair inherited from
--      an earlier run keeps both of its lines whatever the rename did.
-- A crash after 1 leaves both records, and the one whose private name is
-- standing is the live one. A crash after 2 leaves both the other way round.
-- Either way the folder is described by at least one open record at every
-- instant, and the consumer's own rule below reads the pair.
--
-- AND A REPLACEMENT THAT CANNOT BE WRITTEN STOPS THE RENAME. Handing back
-- success on a failed write, as B2.4d did, is the same loss with none of the
-- crash: the caller renames, the old names go stale, and nothing on the machine
-- says where the folder went.
function Updater.uninstall_claim_repath_plan(from, to)
  local moves = {}
  from = tostring(from or "")
  to = tostring(to or "")
  if from == "" or to == "" or from == to then return moves, true end
  local records = Updater.uninstall_claim_journal_read()
  if type(records) ~= "table" then return moves, false end
  local head = from .. RA.SEP
  for _, record in ipairs(records) do
    local public, private = tostring(record.public), tostring(record.private)
    if record.owned and public:sub(1, #head) == head
        and private:sub(1, #head) == head then
      local moved_private = to .. private:sub(#from + 1)
      local moved_public = to .. public:sub(#from + 1)
      -- AND A RECORD THIS SIDE WOULD REFUSE TO READ IS NOT ONE IT WRITES. The
      -- reader honours a third field only when it names this record's real
      -- predecessor, so the same question is asked here, of the pair this line
      -- is about to spell. It holds by construction on every path that reaches
      -- this line; asking is what keeps that true if the construction ever
      -- changes, because a replacement the reader would not honour is a
      -- replacement that cannot retire what it replaces.
      if not Updater.uninstall_claim_lineage(public, private, moved_public,
          moved_private) then
        return moves, false
      end
      -- AND THE EVIDENCE TRAVELS WITH THE DESCRIPTION. The seed is a file
      -- inside the folder and a value on the line beside it, and a parent going
      -- back to its own name changes neither: the leaf keeps its spelling
      -- because only the prefix moves. A replacement written without it would
      -- be a record no later session could ever ask a question of.
      if not Updater.uninstall_claim_record(moved_public, moved_private,
          private, record.seed) then
        return moves, false
      end
      -- AND THE AUTHORITY TRAVELS WITH THE DESCRIPTION AND IS NEVER MINTED BY
      -- IT (round 58). This run wrote the replacement line, so it may take that
      -- line back off when its own rename turns out not to have happened; what
      -- it may NOT do is inherit the right to be settled on a value, because
      -- re-spelling a description this run found on disk verifies nothing about
      -- the folder it names. A replacement for a record this run claimed itself
      -- carries the claim-time minting forward, because it is the same folder,
      -- the same seed and the same run.
      Updater.uninstall_claim_authority(moved_private,
        Updater.uninstall_claim_authorized(private, true))
      moves[#moves + 1] = { old = private, new = moved_private }
    end
  end
  return moves, true
end

-- `landed` says whether the rename really happened, and it is read from the
-- disk by the caller rather than from the rename's own answer. A rename that
-- landed makes the old description false, and that one is taken off ONLY WHEN
-- THIS ATTEMPT MINTED IT, so a pair inherited from an earlier run keeps both of
-- its lines. A rename that did not happen makes the replacement THIS RUN wrote
-- moments ago false, and that line is taken back off. Either way it goes
-- through the one rule that closes any record: nothing at all may be standing
-- under the name it names. So a parent name that survived its own rename leaves
-- both records open, which is exactly what that state deserves.
function Updater.uninstall_claim_repath_commit(moves, landed)
  local pending = Updater._uninstall_claim_pending
  for _, move in ipairs(moves or {}) do
    if landed then
      -- AND A DESCRIPTION THIS RUN DID NOT CREATE SURVIVES ITS OWN RENAME, which
      -- is the second half of round 58's blocker. This rename is evidence about
      -- the folders below it only when the folder it moved is one this run
      -- claimed: a parent put back from a name read off a list may be an actor's
      -- substitute, and the nested folders the records below it name are then
      -- still inside the original, wherever it was carried. Retiring those
      -- records here would erase the only description of where they are on the
      -- strength of a rename that never touched them. Both lines are kept
      -- instead, and the pair is surfaced rather than resolved.
      if Updater.uninstall_claim_authorized(move.old, true) then
        Updater.uninstall_claim_settle(move.old)
      end
      -- AND WHAT THIS RUN HAS STILL TO ACCOUNT FOR MOVES WITH THE RECORD. A
      -- put-back marks the private name it put back, and a parent going back to
      -- its own name changes that name in every record below it; a mark left
      -- pointing at the old spelling would be a folder this run put back and
      -- then never accounted for, which keeps the list on disk for nothing.
      if type(pending) == "table" and pending[move.old] ~= nil then
        pending[move.new] = pending[move.old]
        pending[move.old] = nil
      end
    else
      Updater.uninstall_claim_settle(move.new)
    end
  end
end

-- Take the list away, and only when there is nothing in it this side has not
-- accounted for: no claim still open, no tail the file never terminated, and no
-- complete line the fold could not read.
function Updater.uninstall_claim_journal_retire()
  local records, _, info = Updater.uninstall_claim_journal_read()
  if type(records) ~= "table" or #records > 0 then return false end
  if type(info) ~= "table" then return false end
  if info.torn or (info.unknown or 0) > 0 then return false end
  local path = Updater.uninstall_claim_journal_path()
  if not RA.path_present(path) then return true end
  os.remove(path)
  return not RA.path_present(path)
end

-- THE CONSUMER. Put back every folder an interrupted removal left under a name
-- of its own, and name the ones that cannot be put back.
--
-- WHERE IT RUNS, AND WHY IT RUNS THERE. On the first tick of every session, and
-- again inside the uninstaller's own run with the apply lock held. It does NOT
-- run in the launcher, and that is a decision rather than an omission: the
-- launcher refuses an active marker outright and teaching it otherwise means
-- putting a reader for this body's life files inside the frozen launcher, which
-- is the same thing this lane refuses to do to the launcher's own lock. What
-- the launcher does instead is refuse, and the marker's own words send the user
-- through the one door that reaches this code: delete the marker, run an
-- action, and the body that starts puts the folders back.
--
-- THE ANSWERS, AND EACH ONE IS PROVED RATHER THAN ASSUMED. NOT ONE OF THEM
-- TAKES A LINE OFF THE LIST. This pass reads records an earlier attempt minted,
-- the authority to retire one never leaves that attempt, so what every answer
-- here decides is where the folder is and what the user is told rather than
-- whether the record survives.
--   * the private name is there and the folder's own name is FREE: the put-back
--     the walk itself uses, which asks the junction question immediately before
--     its rename and asks it again afterwards. The folder goes back on proof
--     and only on proof, and its record stays on the list behind it.
--   * the private name is there and something else has taken the folder's own
--     name: this side cannot decide which of the two the user wants, so it
--     moves neither, names both, and KEEPS the record.
--   * the private name is not there: NOT AN ANSWER ON ITS OWN (round 52). Two
--     questions are asked about it: whether the folder at its own name answers
--     for this record's own evidence, which is what a put-back that already
--     happened looks like, and whether the record that replaces it or the one
--     it replaces answers for its own, which is a parent move caught partway.
--     They choose WHICH SENTENCE the user is told about a folder this side
--     cannot locate. The record is kept, surfaced and said out loud in every
--     one of them.
--
-- AND A RECORD THAT IS NOT THIS PACKAGE'S TO ACT ON IS A FOURTH ANSWER. Round
-- 51: the list is an ordinary file and nothing stopped a corrupted or edited
-- one from naming folders that were never ReaAssist's, which the rename and the
-- rmdir above would then have been aimed at. Such a record is surfaced with
-- both of its names, moved nowhere, and left on the list exactly as it is.
function Updater.uninstall_claim_recover(opts)
  opts = opts or {}
  if opts.once then
    if Updater._uninstall_claim_recovered then return nil end
    Updater._uninstall_claim_recovered = true
  end
  -- Never against a removal that is running in this window: those claims are
  -- the live walk's own and the walk settles them itself.
  if Updater.uninstall_active and Updater.uninstall_active() then return nil end
  -- And never against a relative name. Without a package root there is no
  -- package root to look in, and probing one would be probing whatever
  -- directory this process happens to be sitting in.
  if tostring(RA.PACKAGE_DIR or "") == "" then return nil end
  local path = Updater.uninstall_claim_journal_path()
  if not RA.path_present(path) then return nil end
  local records, _, info = Updater.uninstall_claim_journal_read()
  if type(records) ~= "table" then
    -- Surfaced and left exactly where it is. A list that cannot be read is the
    -- one thing this side must not delete, because it is the only description
    -- of what an interrupted run moved.
    Log.line("UPDATE", "uninstall claims: the list at " .. tostring(path)
      .. " could not be read; nothing was moved.")
    return { restored = {}, left = {}, foreign = {}, journal = path,
      unreadable = true }
  end
  -- A LINE THE FOLD COULD NOT READ IS A REASON TO KEEP THE LIST, not a reason
  -- to act. It is counted and said out loud once per session, and the list stays
  -- on disk while one is there, because a torn tail is the shape a crash in the
  -- middle of writing a record leaves and only the file itself can be read for
  -- what it really says.
  local unread = (type(info) == "table")
    and ((info.unknown or 0) + (info.torn and 1 or 0)) or 0
  if #records == 0 and unread == 0 then
    Updater.uninstall_claim_journal_retire()
    return nil
  end
  local out = { restored = {}, left = {}, foreign = {}, lost = {},
    journal = path }
  if unread > 0 then
    out.unread_lines = unread
    Log.line("UPDATE", string.format(
      "uninstall claims: %d line(s) of %s could not be read; they were left "
      .. "exactly as they are and nothing was resolved from them",
      unread, tostring(path)))
  end
  for _, record in ipairs(records) do
    if not record.owned then
      -- NOT THIS PACKAGE'S TO MOVE. Both names are surfaced, neither is
      -- touched, and the line stays exactly where it is.
      out.foreign[#out.foreign + 1] = { path = tostring(record.private),
        public = tostring(record.public) }
    end
  end
  -- EVERY RECORD WHOSE PRIVATE NAME IS REALLY STANDING, AND THE PUT-BACK IS THE
  -- ONE THE WALK ITSELF USES. It asks the junction question immediately before
  -- its rename, so a link that arrived at a private name is taken as a link
  -- rather than followed.
  --
  -- AND THE LIST IS READ AGAIN BETWEEN ROUNDS, because putting a parent back
  -- writes the records of everything still standing inside it, and those are
  -- names this pass can act on now. A name is only ever worked once, so the
  -- rounds terminate.
  local handled, list = {}, records
  for round = 1, 1 + Updater.UNINSTALL_MAX_DEPTH do
    if round > 1 then list = Updater.uninstall_claim_journal_read() end
    if type(list) ~= "table" then break end
    local worked = false
    for _, record in ipairs(list) do
      local public, private = tostring(record.public), tostring(record.private)
      if record.owned and not handled[private]
          and RA.path_present(private) then
        handled[private] = true
        worked = true
        local where, note = Updater.uninstall_claim_restore(private, public)
        local outcome = (type(note) == "table" and note.outcome) or "refused"
        -- AND THE DESCRIPTION THIS ONE REPLACED IS WORKED WITH IT WHEN THE
        -- FOLDER REALLY WENT BACK, which is round 58's doing. Nothing retires
        -- either line any more, so the one the rename has just made false is
        -- still on the list when the rule below reads it, and that rule would
        -- call a folder this very pass had put back one ReaAssist cannot find.
        -- Both lines describe one folder, the pass moved it and said so, and
        -- the spelling it moved away from is not a second folder to report. It
        -- is silenced rather than retired: the line stays, the list stays with
        -- it, and nothing on disk is decided by this. ONLY A RENAME THAT
        -- HAPPENED reaches it, because every other answer leaves the folder
        -- where it was and the other line still describing it in its own right,
        -- which is the state the partner sentence is for.
        if outcome == "restored" and record.older ~= nil then
          handled[tostring(record.older)] = true
        end
        -- THE RECORD THIS ONE REPLACED IS NEVER RETIRED AHEAD OF THE RECORD
        -- THAT REPLACED IT, because retiring a predecessor on a successor that
        -- is itself only pending would close the only description of the folder
        -- on nothing at all. That ordering lives in the accounting pass, and
        -- that pass closes a pair only for the attempt that minted it, so a
        -- pass working records it inherited retires neither line.
        if outcome == "restored" then
          out.restored[#out.restored + 1] = public
        elseif outcome == "link" then
          -- The name held a link, so the folder this record describes is not
          -- there and this side cannot say where it is. The record is kept.
          out.lost[#out.lost + 1] = { path = private, public = public,
            reason = "link", probe = note.probe }
        elseif outcome == "redirected" then
          -- The rename landed and a link was standing at the folder's own name
          -- when this side asked; the question took the link and the folder is
          -- somewhere this side cannot name. The record is kept.
          out.lost[#out.lost + 1] = { path = private, public = public,
            reason = "redirected", probe = note.probe }
        elseif outcome == "vanished" or outcome == "unproven" then
          -- The private name went while this side was asking about it, either
          -- with no rename of this run's landing at all or with one landing on
          -- something it cannot prove is the folder. Neither closes anything,
          -- and the two are said apart because only one of them moved
          -- something.
          out.lost[#out.lost + 1] = { path = private, public = public,
            reason = outcome }
        elseif outcome == "breach" then
          out.left[#out.left + 1] = { path = tostring(where),
            public = public, reason = "not ReaAssist's" }
          out.lost[#out.lost + 1] = { path = private, public = public,
            reason = "breach", probe = note.probe }
        elseif outcome == "taken" then
          out.left[#out.left + 1] = { path = private, public = public,
            reason = "taken" }
        elseif outcome ~= "removed" then
          out.left[#out.left + 1] = { path = private, public = public,
            reason = "refused" }
        end
        if type(note) == "table" and note.stray then
          -- One file of this run's that would not come back out. It is
          -- ReaAssist's own and is named rather than counted with the folders.
          -- Asked of the note the same way the outcome above is, because a
          -- put-back that answered with nothing at all is a put-back this side
          -- knows nothing about rather than one it can read fields off.
          out.left[#out.left + 1] = { path = tostring(note.stray),
            public = public, reason = "ReaAssist's own" }
        end
      end
    end
    if not worked then break end
  end
  -- AND A RECORD IS NEVER RETIRED HERE AT ALL, ON ABSENCE OR ON ANYTHING ELSE.
  -- An absent private name used to be read as nothing to do, which is what
  -- erased the record of a nested folder whose parent had gone back to its own
  -- name (round 52). Two questions are asked of it now: whether the folder at
  -- its own name answers for this record's own evidence, which is what a
  -- put-back that already happened looks like; and whether the record this one
  -- replaces, or the one that replaces it, answers for its own, which is a
  -- parent move caught partway. Both of them choose which sentence the user is
  -- told. Anything else is a folder ReaAssist moved and can no longer find, and
  -- that is said rather than swallowed.
  --
  -- AND THE ACCOUNTING PASS RUNS BEFORE THE RULE BELOW READS THE LIST. It is
  -- the one place a record is ever closed, no put-back closes its own any more
  -- (round 54's first blocker), and a record it had closed must not then be
  -- read by that rule as a folder this side had lost. It closes ONLY WHAT THIS
  -- ATTEMPT MINTED, so a pass working a list an earlier run left behind closes
  -- nothing at all and every record it has just put back stays open; what keeps
  -- those out of the rule below is the worked set, which is said again beside
  -- that rule. One read of the whole list after every round of putting back has
  -- finished, which is the reading this consumer is: a later session looking at
  -- what an earlier run left.
  local _, strays, done_shells = Updater.uninstall_claim_account()
  for _, path in ipairs(strays) do
    -- One file of this run's that would not come back out. It is ReaAssist's
    -- own and is named rather than counted with the folders.
    out.left[#out.left + 1] = { path = path, reason = "ReaAssist's own" }
  end
  if #done_shells > 0 then
    -- AND A FOLDER THE ACCOUNTING FINISHED IS NOT REPORTED AS ONE THAT IS BACK.
    -- It was an interrupted run's already-emptied folder, it was put back and
    -- then removed, and saying it is standing at its own name would be a
    -- sentence the user could go and disprove.
    local still = {}
    for _, path in ipairs(out.restored) do
      local finished = false
      for _, gone in ipairs(done_shells) do
        if gone == path then finished = true break end
      end
      if not finished then still[#still + 1] = path end
    end
    out.restored = still
  end
  local after = Updater.uninstall_claim_journal_read()
  if type(after) == "table" then
    local live, successor_of, described_by = {}, {}, {}
    for _, record in ipairs(after) do
      described_by[tostring(record.private)] = record
      if RA.path_present(record.private) then live[record.private] = true end
      if record.older then successor_of[record.older] = record.private end
    end
    for _, record in ipairs(after) do
      local public, private = tostring(record.public), tostring(record.private)
      -- BOTH DIRECTIONS, because a folder can have been repathed more than
      -- once: the record this one replaced, and the record that replaced it,
      -- are each a description of the same folder, so either one standing on
      -- disk is the partner this record is asked about. Nothing either of them
      -- answers takes this line off the list.
      --
      -- AND THE PARTNER IS A NAME UNTIL SOMETHING BINDS IT, which is round 56's
      -- second blocker. B2.4h retired this record on the mere PRESENCE of the
      -- other one's private name, so a directory an actor made at a name the
      -- list carries erased a description with no question asked of anything.
      -- What is asked instead is the same binding, of the partner's own folder
      -- and the partner's own evidence: the folder standing at the partner's
      -- private name has to be the folder the partner's record describes.
      local partner = nil
      if record.older ~= nil and live[record.older] == true then
        partner = record.older
      elseif successor_of[private] ~= nil
          and live[successor_of[private]] == true then
        partner = successor_of[private]
      end
      -- A record the pass above already worked is not asked again. Its private
      -- name can be absent BECAUSE of what that pass did, and the answer to it
      -- has already been given and already been said.
      --
      -- AND A RECORD IS NEVER RETIRED BECAUSE SOMETHING IS STANDING AT THE
      -- FOLDER'S OWN NAME, which is round 55's first blocker. B2.4g retired an
      -- unhandled record whenever ANYTHING at all was present there, so a
      -- folder carried away and replaced with a stranger's directory erased the
      -- only description of where ReaAssist had put it. What is asked is the
      -- same binding question the accounting pass asks, of the file a claim
      -- leaves inside the folder it moves: the seed goes in BEFORE the record
      -- is written and before the rename, so a run interrupted anywhere after
      -- that leaves it at the folder's own name, under the same minted leaf the
      -- record's private name carries.
      --
      -- AND THE VALUE IT ASKS FOR IS THE ONE ON THE RECORD, which is round 56's
      -- second blocker and the whole of this arm. B2.4h read the seed for the
      -- SHAPE this package's minting produces, and a shape is mintable by
      -- anything that can list a folder: the leaf is the record's own private
      -- name and the pattern is public, so an actor who had carried the folder
      -- away could write the file that answered. The claim writes its value ON
      -- THE LINE now, so this session asks the question the run that wrote it
      -- would have asked. What that costs is said in the plan and it is not a
      -- new residual: seed-value disclosure lets a reader forge the binding
      -- value. Separately, an actor with write access to the journal can append
      -- `done`, rewrite it, or remove it. Those are two capabilities and neither
      -- is assumed from the other.
      --
      -- AND A RECORD CARRYING NO VALUE IS NEVER RETIRED HERE. There is nothing
      -- on it for this session to ask about, so the folder is named, the record
      -- is kept, and the list stays.
      --
      -- AND NO LATER SESSION RETIRES ANY RECORD AT ALL NOW, which is round 57's
      -- blocker and the whole of this arm. The value the question is asked
      -- against is written IN THE LIST, so an actor who can read the list can
      -- put a file carrying it inside a directory of their own at the folder's
      -- own name, and every question below then answers for that directory
      -- because this side opens and pins it itself. The answer is real about
      -- the object it was asked of and says nothing about which object that is,
      -- which is not the invariant this lane is defending. So the question is
      -- still asked and what it answers still decides WHICH SENTENCE the user
      -- is told, and nothing it answers takes a line off the list.
      --
      -- WHAT KEEPS ITS STRENGTH IS THE RUN THAT HOLDS THE NONCE IN MEMORY. The
      -- accounting pass retires on a value this run minted and never wrote
      -- down, which no reader of the list can have, and that pass is untouched:
      -- see uninstall_claim_account. This one is the other reader, the one with
      -- no run behind it, and it has nothing but the list.
      --
      -- THE COST, SAID PLAINLY RATHER THAN HIDDEN. A record an interrupted run
      -- left behind is never taken off by a later session, so the list stays on
      -- disk and the message is said every session until the user takes the
      -- list away, and the one file of ReaAssist's own inside the folder stays
      -- there too: it is the evidence, and taking it out would leave every
      -- session after this one with less to say than this one had. Michael may
      -- accept the plaintext value instead and get the automatic cleanup back;
      -- that is a decision on the sheet rather than one taken here.
      if record.owned and not live[private] and not handled[private] then
        local leaf = private:match("[^/\\]+$") or ""
        local bound, why = false, nil
        if leaf ~= "" and record.seed then
          bound, why = Updater.uninstall_claim_bound(public, leaf, record.seed)
          bound = bound == true
        end
        -- AND THE PARTNER IS NOT ASKED ABOUT ONCE THIS PASS HAS TAKEN SOMETHING
        -- AT THIS RECORD'S OWN NAME. The question above removes a junction
        -- standing where the folder belongs rather than following it, and the
        -- sentence the partner produces says ReaAssist deleted nothing here,
        -- which would be false the moment it had. That cell belongs to the
        -- message that says the uncertainty and names the removal as one of the
        -- things that may have happened.
        local by_partner = false
        if not bound and why ~= "removed" and partner ~= nil then
          local mate = described_by[partner]
          local mate_leaf = tostring(partner):match("[^/\\]+$") or ""
          if type(mate) == "table" and mate.seed and mate_leaf ~= "" then
            by_partner = Updater.uninstall_claim_bound(partner, mate_leaf,
              mate.seed) == true
          end
        end
        if bound then
          -- EVERY QUESTION ANSWERED AND THE RECORD IS KEPT ANYWAY. This is the
          -- state B2.4i retired and round 57 refused: what answered is a value
          -- the list itself carries, so the folder that answered is the folder
          -- this side opened and pinned rather than provably the folder the
          -- record describes. The file stays inside it, nothing is renamed and
          -- nothing is removed, and the user is told what is known.
          out.lost[#out.lost + 1] = { path = private, public = public,
            reason = "matched", probe = leaf }
        elseif by_partner then
          -- THE OTHER LINE ON THE LIST DESCRIBES THE SAME FOLDER AND ITS OWN
          -- FOLDER ANSWERED. B2.4i retired the stale one on that; the evidence
          -- is the partner's value off the same list, so it is worth exactly
          -- what the one above is worth and both lines are kept. Nothing is
          -- taken out of the partner's folder either: that file is the
          -- partner record's evidence rather than this one's.
          out.lost[#out.lost + 1] = { path = private, public = public,
            reason = "superseded", partner = tostring(partner) }
        else
          -- AND THE NAME THAT REFUSED THIS SIDE FOR A REASON OF ITS OWN IS SAID
          -- APART FROM THE ONE THIS SIDE SIMPLY COULD NOT MATCH, because they
          -- are different things to be told and only one of them is something
          -- the user can go and fix.
          --
          -- AND A QUESTION THAT TOOK A LINK NEVER LANDS IN A CELL THAT DENIES
          -- IT, which is round 59's should-fix carried to the arm the partner
          -- test already refused it on. The two sentences these reasons produce
          -- say what the check itself did, and neither of them removed
          -- anything; a binding question that met a junction standing at the
          -- folder's own name TOOK it, and only a name something else has been
          -- put at in the instant since can carry that answer this far. It goes
          -- where the removal is already named as one of the things that may
          -- have happened.
          local reason = "unlocatable"
          if why == "foreign" then
            reason = "unbindable"
          elseif why ~= "removed" and RA.path_present(public) then
            reason = "unaccounted"
          end
          out.lost[#out.lost + 1] = { path = private, public = public,
            reason = reason }
        end
      end
    end
  end
  -- SAID AS "COULD NOT ACCOUNT FOR" RATHER THAN "COULD NOT FIND" (round 57).
  -- That list has carried names this side found and could not bind since B2.4g,
  -- and since B2.4j it carries the folder whose own name answered every
  -- question there is, so "could not find" is the one thing it does not mean.
  Log.line("UPDATE", string.format(
    "uninstall claims: put back %d, could not put back %d, could not account "
    .. "for %d, left alone %d",
    #out.restored, #out.left, #out.lost, #out.foreign))
  Updater.uninstall_claim_journal_retire()
  if opts.announce then Updater.uninstall_claim_announce(out) end
  return out
end

-- What the user is told, and it is told at the first tick rather than kept for
-- a report nobody will open. A folder that went back needs no decision, so it
-- is a toast; a folder that could not be put back is holding the user's own
-- files under a name they have never seen, and that is a message they have to
-- be able to act on.
function Updater.uninstall_claim_announce(summary)
  if type(summary) ~= "table" then return end
  if #(summary.restored or {}) > 0 and UI and UI.show_float_toast then
    -- SAID WITHOUT CLAIMING WHOSE THE FOLDER WAS. What this side can prove is
    -- that the folder standing under a name a ReaAssist run minted is back at
    -- the name that run renamed it from. Whether it is ReaAssist's own is a
    -- question the run that moved it answers, in its own report.
    UI.show_float_toast(Updater.uninstall_t("recovered.toast", nil,
      "ReaAssist put back what an interrupted removal had moved aside."),
      "ok", true)
  end
  if type(reaper.MB) ~= "function" then return end
  -- LINES THIS PACKAGE COULD NOT HAVE WRITTEN GET THEIR OWN MESSAGE, because
  -- every sentence in the one below is about a folder ReaAssist moved and none
  -- of them is true of a line ReaAssist did not write. Two shapes reach it: a
  -- line naming folders that were never ReaAssist's, and a line claiming to
  -- replace a record that is not the one it replaces. Neither is acted on, and
  -- the sentence says only what is true of both.
  if #(summary.foreign or {}) > 0 then
    local strangers = {}
    for _, item in ipairs(summary.foreign) do
      strangers[#strangers + 1] = "  " .. tostring(item.public)
      strangers[#strangers + 1] = "  " .. tostring(item.path)
    end
    local stranger_list = table.concat(strangers, "\n")
    pcall(reaper.MB, Updater.uninstall_t("recovered.foreign",
      { paths = stranger_list, journal = tostring(summary.journal or "") },
      "ReaAssist keeps a list of the folders one of its own removals has "
      .. "moved aside, and that list now carries lines ReaAssist could not "
      .. "have written. Nothing on them was moved and nothing was deleted, and "
      .. "the lines were left exactly as they are.\n\nThe names on them are:\n"
      .. stranger_list .. "\n\nThe list is here:\n  "
      .. tostring(summary.journal or "")), "ReaAssist", 0)
  end
  -- AND A FOLDER THIS SIDE MOVED AND CANNOT FIND GETS ITS OWN MESSAGE, because
  -- every sentence in the one below is about a folder that is standing
  -- somewhere and none of them is true of one that is not. It is the state
  -- round 52 refused to let the list forget: the record is kept, and saying so
  -- is the only thing left that can help.
  --
  -- AND THE ONE CELL WHERE A MOVE REALLY HAPPENED IS SAID SEPARATELY, which is
  -- round 53's third finding. When the put-back's own rename followed a link,
  -- that rename moved the link's target onto the folder's own name before this
  -- side could see it, so "nothing was moved" is the one thing this message
  -- must not say about that cell. It is a different event with a different list
  -- and a different sentence.
  if #(summary.lost or {}) > 0 then
    local missing, carried, unproven = {}, {}, {}
    local redirected, unaccounted, unbindable = {}, {}, {}
    local matched, superseded = {}, {}
    for _, item in ipairs(summary.lost) do
      if tostring(item.reason) == "breach" then
        carried[#carried + 1] = "  " .. tostring(item.public)
        carried[#carried + 1] = "  " .. tostring(item.path)
      elseif tostring(item.reason) == "unproven" then
        unproven[#unproven + 1] = "  " .. tostring(item.public)
      elseif tostring(item.reason) == "redirected" then
        redirected[#redirected + 1] = "  " .. tostring(item.public)
      elseif tostring(item.reason) == "unaccounted" then
        unaccounted[#unaccounted + 1] = "  " .. tostring(item.public)
      elseif tostring(item.reason) == "unbindable" then
        unbindable[#unbindable + 1] = "  " .. tostring(item.public)
      elseif tostring(item.reason) == "matched" then
        matched[#matched + 1] = "  " .. tostring(item.public)
          .. "  (" .. tostring(item.probe) .. ")"
      elseif tostring(item.reason) == "superseded" then
        superseded[#superseded + 1] = "  " .. tostring(item.public)
        superseded[#superseded + 1] = "  " .. tostring(item.partner)
      else
        missing[#missing + 1] = "  " .. tostring(item.public)
      end
    end
    -- AND THE NAME THAT ANSWERED EVERY QUESTION AND KEPT ITS RECORD ANYWAY,
    -- which is round 57's blocker. The value this side asks the folder about is
    -- written in the list, so an answer is worth what the list is worth and no
    -- later session closes a record on one. What is known is said, what is not
    -- known is said, and the way out is the one every message here gives.
    --
    -- AND THE FOUR MESSAGES BELOW SAY WHAT THEIR OWN CHECK DID AND NOTHING
    -- ABOUT THE SESSION, which is round 59's should-fix. All four used to end
    -- the same way: ReaAssist moved nothing and deleted nothing here. THE PASS
    -- WRITING THEM MAY HAVE MOVED THE VERY FOLDER THE SENTENCE IS ABOUT. It
    -- puts an inherited parent back to its own name a few lines above this one
    -- and re-spells every record below it, so a child record reported here as
    -- matched, superseded, unbindable or unaccounted names a folder this same
    -- pass renamed moments earlier, along with everything inside it. A bare
    -- denial naming no act is the wrong shape for that, however true it is of
    -- the check: what each message can say is what its own last question found
    -- standing, what that question touched and what it did not. The messages
    -- whose denial already names its act keep it, because a denial with an act
    -- in front of it is bounded by the act.
    if #matched > 0 then
      local matched_list = table.concat(matched, "\n")
      pcall(reaper.MB, Updater.uninstall_t("recovered.matched",
        { paths = matched_list, journal = tostring(summary.journal or "") },
        "A ReaAssist removal was interrupted. ReaAssist moves each folder "
        .. "aside under a name of its own before it empties it, and nothing is "
        .. "standing under the name it gave these:\n" .. matched_list
        .. "\n\nSomething is standing at each folder's own name and it holds a "
        .. "file carrying the value ReaAssist wrote down for the folder it "
        .. "moved aside, which is what a folder that had been put back would "
        .. "look like. ReaAssist will not take the line off its list for that: "
        .. "the value it checks that file against is written in the list "
        .. "itself, so anything that can read the list can put a file carrying "
        .. "it inside a folder of its own. That check renamed nothing and "
        .. "removed nothing: what it did was open the file it asks about inside "
        .. "the folder, add to that file and read it back, and ask the folder's "
        .. "own name questions that leave the name as they find it. It touched "
        .. "nothing else in the folder. Any name in brackets is the file "
        .. "ReaAssist asks about "
        .. "inside that folder. ReaAssist keeps the list here and says this "
        .. "again every time it starts, until you take the list away:\n  "
        .. tostring(summary.journal or "")), "ReaAssist", 0)
    end
    -- AND THE LINE ANOTHER LINE ON THE SAME LIST DESCRIBES THE SAME FOLDER AS.
    -- A parent going back to its own name rewrites every record below it, so a
    -- run that died in the middle of that leaves two descriptions of one
    -- folder. Which of them is finished is a question this side can only answer
    -- from the list, so it answers neither and says so.
    if #superseded > 0 then
      local superseded_list = table.concat(superseded, "\n")
      pcall(reaper.MB, Updater.uninstall_t("recovered.superseded",
        { paths = superseded_list, journal = tostring(summary.journal or "") },
        "A ReaAssist removal was interrupted. ReaAssist moves each folder "
        .. "aside under a name of its own before it empties it, and nothing is "
        .. "standing under the name it gave these. Another line on the same "
        .. "list describes each of them under a second name of ReaAssist's "
        .. "own, and a folder is standing there. Each folder's own name comes "
        .. "first below and the name a folder is standing under comes "
        .. "second:\n" .. superseded_list
        .. "\n\nReaAssist keeps both lines rather than deciding which one is "
        .. "finished, because what it can check either of them against is "
        .. "written in the list itself. Neither check renamed anything or "
        .. "removed anything: each one looked inside for the file ReaAssist "
        .. "asks about there and, where what it found carried the value "
        .. "ReaAssist wrote down, added to that file and read it back, and each "
        .. "asked the name it was standing at questions that leave the name as "
        .. "they find it. They touched nothing else in either folder. "
        .. "ReaAssist keeps the list here and says this again "
        .. "every time it starts, until you take the list away:\n  "
        .. tostring(summary.journal or "")), "ReaAssist", 0)
    end
    -- AND THE NAME THAT REFUSED THE QUESTION FOR A REASON OF ITS OWN. Round 56:
    -- a refusal is not a pin, so a name this side cannot even ask about is not
    -- the same state as one it asked and could not match, and the difference is
    -- worth telling because this one usually has something behind it the user
    -- can do something about.
    if #unbindable > 0 then
      local unbindable_list = table.concat(unbindable, "\n")
      pcall(reaper.MB, Updater.uninstall_t("recovered.unbindable",
        { paths = unbindable_list, journal = tostring(summary.journal or "") },
        "A ReaAssist removal was interrupted. ReaAssist moves each folder "
        .. "aside under a name of its own before it empties it, and nothing is "
        .. "standing under the name it gave these:\n" .. unbindable_list
        .. "\n\nSomething is standing at each folder's own name and it refused "
        .. "ReaAssist's question for a reason of its own, which is usually a "
        .. "permission or another program holding it open, so ReaAssist cannot "
        .. "tell you whether it is the folder it had moved aside. The question "
        .. "renamed nothing and removed nothing: the most it can do at a name "
        .. "that refuses it is open the file ReaAssist asks about inside the "
        .. "folder and add to that file, and it touched nothing else. "
        .. "Look in each one before you "
        .. "do anything with it. ReaAssist keeps the list here and says this "
        .. "again every time it starts, until you take the list away:\n  "
        .. tostring(summary.journal or "")), "ReaAssist", 0)
    end
    -- AND THE CELL WHERE SOMETHING IS STANDING AT THE FOLDER'S OWN NAME AND
    -- THIS SIDE CANNOT BIND IT TO THE FOLDER, which is round 55's first
    -- blocker. Every sentence above is about a folder that is missing and none
    -- of them is true here: the name is occupied, and the one thing this
    -- message must not do is tell the user which folder is occupying it.
    if #unaccounted > 0 then
      local unaccounted_list = table.concat(unaccounted, "\n")
      pcall(reaper.MB, Updater.uninstall_t("recovered.unaccounted",
        { paths = unaccounted_list, journal = tostring(summary.journal or "") },
        "A ReaAssist removal was interrupted. ReaAssist moves each folder "
        .. "aside under a name of its own before it empties it, and nothing is "
        .. "standing under the name it gave these:\n" .. unaccounted_list
        .. "\n\nSomething is standing at each folder's own name, and ReaAssist "
        .. "cannot tell you whether it is the folder it had moved aside. "
        .. "The check renamed nothing and removed nothing: it looked inside for "
        .. "the file ReaAssist asks about there and, where what it found "
        .. "carried the value ReaAssist wrote down, added to that file and read "
        .. "it back, and it asked the folder's own name questions that leave "
        .. "the name as they find it. It touched nothing else in the folder. "
        .. "Look in each one "
        .. "before you do anything with it. ReaAssist keeps the list here and "
        .. "says this again every time it starts, until you take the list "
        .. "away:\n  " .. tostring(summary.journal or "")), "ReaAssist", 0)
    end
    -- AND THIS ONE PROMISED WHAT THE LIST CANNOT SUPPORT, which is round 57's
    -- should-fix. Three different things reach it: a folder somebody else
    -- carried away, a link ReaAssist itself removed from one of the two names,
    -- and a folder ReaAssist emptied, could not bind and then took the empty
    -- name of. The list says which folder, never which of those, so the
    -- sentence says the uncertainty rather than an attribution, and it is
    -- bounded by the one thing that IS always true here: every removal this
    -- lane makes is a non-recursive one, so nothing that was inside a folder
    -- goes with it.
    --
    -- AND IT PROMISES NOTHING ABOUT WHAT IS STILL IN THE FOLDER, which is round
    -- 58's should-fix. B2.4j finished the sentence with "whatever was in them
    -- that was not ReaAssist's own is where it was", and that is a promise the
    -- list cannot support anywhere and is plainly false under Data: that tree is
    -- walked with NO ownership shape, because the offer the user accepted is
    -- everything in the folder, so the walk empties the folder file by file and
    -- the contents are gone long before its emptied name is taken or the run is
    -- interrupted. What is bounded is the act that took the NAME, and only that.
    -- What the walk removed before it belongs to the run that removed it, and
    -- this list carries a claim and never a removal, so the sentence says that
    -- instead.
    if #missing > 0 then
      local missing_list = table.concat(missing, "\n")
      pcall(reaper.MB, Updater.uninstall_t("recovered.lost",
        { paths = missing_list, journal = tostring(summary.journal or "") },
        "A ReaAssist removal was interrupted. ReaAssist moves each folder aside "
        .. "under a name of its own before it empties it, and it cannot find "
        .. "these where it put them:\n" .. missing_list
        .. "\n\nWhat became of them after that is not something ReaAssist can "
        .. "tell from here. Something else may have moved or replaced them, and "
        .. "one of ReaAssist's own acts may have taken the name: a removal that "
        .. "has emptied a folder finishes by taking the empty folder, and a "
        .. "link found standing at either of the two names ReaAssist knows for "
        .. "one of these folders is removed rather than followed. Neither of "
        .. "those can take anything that is inside a folder. What a removal had "
        .. "already taken out of one of these folders before it was interrupted "
        .. "is not on this list, which carries what ReaAssist moved and never "
        .. "what it removed, so what is inside one of them now is not something "
        .. "ReaAssist can tell you from here. ReaAssist keeps "
        .. "the list here and says this again every time it starts, until you "
        .. "take the list away:\n  "
        .. tostring(summary.journal or "")), "ReaAssist", 0)
    end
    if #carried > 0 then
      local carried_list = table.concat(carried, "\n")
      pcall(reaper.MB, Updater.uninstall_t("recovered.breach",
        { paths = carried_list, journal = tostring(summary.journal or "") },
        "A ReaAssist removal was interrupted, and when ReaAssist went to put a "
        .. "folder back, the name it had moved that folder to had been replaced "
        .. "with a link to somewhere else. Windows follows a link when it "
        .. "renames one, so ReaAssist's own rename moved what that link pointed "
        .. "at. A folder that is not ReaAssist's is standing at the first name "
        .. "below, and the link is still standing at the second, where "
        .. "ReaAssist has left it alone:\n" .. carried_list
        .. "\n\nReaAssist deleted nothing. The folder ReaAssist had moved aside "
        .. "is at neither name and ReaAssist cannot tell you where it is, and "
        .. "one file of ReaAssist's own went with it. Look at what is at each "
        .. "name before you move or delete anything: the folder that was "
        .. "carried in came from wherever that link points, which is where it "
        .. "was until the rename. ReaAssist keeps the list here and says this "
        .. "again every time it starts, until you take the list away:\n  "
        .. tostring(summary.journal or "")), "ReaAssist", 0)
    end
    if #unproven > 0 then
      local unproven_list = table.concat(unproven, "\n")
      pcall(reaper.MB, Updater.uninstall_t("recovered.unproven",
        { paths = unproven_list, journal = tostring(summary.journal or "") },
        "A ReaAssist removal was interrupted. ReaAssist moves each folder "
        .. "aside under a name of its own before it empties it, and when it "
        .. "went to put these back its own rename landed on something "
        .. "ReaAssist cannot prove is the folder:\n" .. unproven_list
        .. "\n\nWhat is standing at each of those names arrived there through "
        .. "that rename, and ReaAssist can tell you neither that it is the "
        .. "folder it had moved aside nor where that folder is now. ReaAssist "
        .. "deleted nothing. Look at each one before you move or delete "
        .. "anything. ReaAssist keeps the list here and says this again every "
        .. "time it starts, until you take the list away:\n  "
        .. tostring(summary.journal or "")), "ReaAssist", 0)
    end
    -- AND THE CELL WHERE THE PUT-BACK LANDED AND THE NAME BECAME A LINK, which
    -- is a different event again: this side really did put the folder back and
    -- something moved it on afterwards.
    if #redirected > 0 then
      local redirected_list = table.concat(redirected, "\n")
      pcall(reaper.MB, Updater.uninstall_t("recovered.redirected",
        { paths = redirected_list, journal = tostring(summary.journal or "") },
        "A ReaAssist removal was interrupted. ReaAssist moves each folder "
        .. "aside under a name of its own before it empties it, and its own "
        .. "rename did put each of these back:\n" .. redirected_list
        .. "\n\nBy the time ReaAssist looked at those names again, each one was "
        .. "a link to somewhere else rather than the folder, so something other "
        .. "than ReaAssist moved the folder on in between. ReaAssist removed "
        .. "the link, left everything it pointed at alone, and deleted nothing "
        .. "else. Where each folder is now is not something ReaAssist can tell "
        .. "you, and one file of ReaAssist's own is inside it wherever it is. "
        .. "ReaAssist keeps the list here and says this again every time it "
        .. "starts, until you take the list away:\n  "
        .. tostring(summary.journal or "")), "ReaAssist", 0)
    end
  end
  if #(summary.left or {}) == 0 then return end
  local names = {}
  for _, item in ipairs(summary.left) do
    names[#names + 1] = "  " .. tostring(item.path)
  end
  local list = table.concat(names, "\n")
  pcall(reaper.MB, Updater.uninstall_t("recovered.left",
    { paths = list, journal = tostring(summary.journal or "") },
    "A ReaAssist removal was interrupted. ReaAssist moves each folder aside "
    .. "under a name of its own before it empties it, and it could not put "
    .. "these back, because something else is at the name each of them "
    -- AND IT NO LONGER TELLS THE USER TO DELETE THEM. Since B2.4d a folder on
    -- this list can be one a run could not prove was ReaAssist's, put where the
    -- user can see it rather than abandoned under a minted name, and "delete
    -- them" is the wrong instruction for that one. Looking first is the right
    -- instruction for both.
    .. "belongs at:\n" .. list .. "\n\nWhat is in them is still there. Look in "
    .. "each one before you do anything with it, and move anything you want to "
    .. "keep somewhere else. ReaAssist keeps the list here and tries again "
    .. "every time it starts:\n  "
    .. tostring(summary.journal or "")), "ReaAssist", 0)
end

-- Is a launcher standing at Recovery/launcher.lock right now?
--
-- That lock is the LAUNCHER's, not this body's, and the two protocols do not
-- share a name or a reader. A launcher takes it only when it has work to do
-- (an ordinary launch that finds the body present takes no lock at all), so
-- one being there means a bootstrap or a recovery is running, or crashed.
-- Either way this body cannot prove the folder is nobody's, and the rule this
-- lane has carried since round 42 is that an unprovable claim is left standing
-- and surfaced. The way out is in the copy: close the other REAPER window, or
-- delete the named file if you are certain nothing is running.
function Updater.uninstall_launcher_lock_path()
  local path = tostring(RA.RECOVERY_DIR or "") .. "launcher.lock"
  if RA.path_present(path) then return path end
  return nil
end

-- Every other ReaAssist instance on this install that is not provably gone.
--
-- The apply lock excludes another instance from the UPDATE pipeline, and that
-- is not the question here: an instance that is merely running is reading the
-- files this is about to delete and writing into the Data folder this may be
-- about to clear. So the life files are read directly and each one is asked
-- the same liveness question the lock asks, with the same answer set. Alive
-- and unknown both count as company, because only a proven death is proof of
-- anything, and the dead leave files that are safe to remove.
--
-- AND THE LISTING IS FORCED FRESH BEFORE IT IS READ. reaper.EnumerateFiles
-- caches a directory the first time it is walked and hands that same listing
-- back on every later index 0; only index -1 invalidates the cache and makes
-- the next walk read the directory again. This scan is asked twice, once for
-- the confirmation screen and once as the authoritative gate under the apply
-- lock, and the whole point of the second ask is that it can see an instance
-- that started since the first. Without the reset it would answer with the
-- first walk's listing, which is the one answer this gate must never give.
function Updater.uninstall_foreign_instances()
  local out = {}
  if type(reaper.EnumerateFiles) ~= "function" then return out end
  local mine = RA.instance_file_suffix()
  pcall(reaper.EnumerateFiles, RA.TEMP_DIR, -1)
  local idx = 0
  while true do
    local fn = reaper.EnumerateFiles(RA.TEMP_DIR, idx)
    if not fn then break end
    local suffix = fn:match("^reaassist_life_(inst_[%w%-_]+)%.lock$")
    if suffix and suffix ~= mine then
      local verdict = "unknown"
      if type(RA.instance_liveness) == "function" then
        verdict = RA.instance_liveness(suffix) or "unknown"
      end
      if verdict ~= "dead" then
        out[#out + 1] = { instance = suffix, verdict = verdict }
      end
    end
    idx = idx + 1
  end
  return out
end

-- Everything standing between this install and an uninstall, in the order a
-- person would want to hear it.
--
-- Asked TWICE and only the second answer is authority: once for the
-- confirmation screen, so the user reads the refusal before they commit to
-- anything, and once inside the apply lock immediately before the first
-- removal. The first is advice about a moment that has passed by the time it
-- is read; the second is taken with the lock held, and while that lock is held
-- no other body writes a journal, quarantines a record, or applies anything.
function Updater.uninstall_blockers()
  local out = {}
  local layout_ok, layout_why = Updater.uninstall_layout()
  if not layout_ok then
    out[#out + 1] = {
      code = "layout",
      detail = layout_why,
      -- Deliberately says what is TRUE OF ALL FOUR answers rather than naming
      -- the one this install gave. Only "flat" is reachable from the real path
      -- derivation, and copy that explains a cause it has not established
      -- would be wrong in every other case; the word itself travels in
      -- `detail` for the log and for a support reply.
      message = Updater.uninstall_t("blocked.layout",
        { path = tostring(RA.PACKAGE_DIR or "") },
        "ReaAssist cannot tell its application folder apart from the "
        .. "folder that holds it, so removing one could remove the other. "
        .. "Nothing was changed.\n\nClose REAPER and delete this folder by "
        .. "hand to remove ReaAssist:\n" .. tostring(RA.PACKAGE_DIR or "")),
    }
    return out
  end
  if Updater.is_busy() then
    out[#out + 1] = {
      code = "busy",
      message = Updater.uninstall_t("blocked.busy", nil,
        "ReaAssist is in the middle of an update. Let it finish or "
        .. "cancel it, then start the uninstall again."),
    }
  end
  local others = Updater.uninstall_foreign_instances()
  if #others > 0 then
    local names = {}
    for _, rec in ipairs(others) do
      names[#names + 1] = tostring(rec.instance) .. " (" .. tostring(rec.verdict) .. ")"
    end
    out[#out + 1] = {
      code = "instance",
      detail = table.concat(names, ", "),
      message = Updater.uninstall_t("blocked.instance",
        { names = table.concat(names, "\n") },
        "Another copy of ReaAssist is open on this install, or one "
        .. "was open and ReaAssist cannot prove it has closed. Removing the "
        .. "program while it is running there would break that session, so "
        .. "nothing was changed.\n\nClose ReaAssist in every other REAPER "
        .. "window, then start the uninstall again.\n\nReaAssist read this "
        .. "from:\n" .. table.concat(names, "\n")),
    }
  end
  local lock_path = Updater.uninstall_launcher_lock_path()
  if lock_path then
    out[#out + 1] = {
      code = "launcher_lock",
      path = lock_path,
      message = Updater.uninstall_t("blocked.launcher_lock",
        { path = lock_path },
        "A ReaAssist launcher is repairing or restoring this install, "
        .. "or one was and did not finish. That claim belongs to the "
        .. "launcher, not to this window, so ReaAssist will not remove it and "
        .. "nothing was changed.\n\nThe claim is here:\n" .. lock_path
        .. "\n\nClose any other REAPER window that is starting ReaAssist and "
        .. "try again. If you are sure none is, delete the file named above "
        .. "and try again."),
    }
  end
  local quarantine = Updater.journal_quarantined()
  if quarantine then
    out[#out + 1] = {
      code = "quarantine",
      path = quarantine,
      message = Updater.uninstall_t("blocked.quarantine",
        { path = tostring(quarantine) },
        "ReaAssist is holding the record of an update it could not "
        .. "finish, and that record is the only description of which files "
        .. "were changed. Removing ReaAssist now would delete it unread, so "
        .. "nothing was changed.\n\nThe record is here:\n" .. tostring(quarantine)
        .. "\n\nRestart ReaAssist and take the repair it offers. Once the "
        .. "install has been verified the record is cleared and the uninstall "
        .. "can run."),
    }
  end
  -- journal_peek answers with the journal plus the path it came from, or with
  -- nil plus the word for why. A valid record is a transaction nobody has
  -- resolved; an unreadable one is a transaction nobody CAN resolve from here.
  -- Both are stops, and neither is ever erased by this lane.
  local journal, jword, jpath = Updater.journal_peek()
  if journal then
    out[#out + 1] = {
      code = "journal",
      path = jword,
      message = Updater.uninstall_t("blocked.journal",
        { path = tostring(jword) },
        "An update is part applied on this install and has not been "
        .. "resolved yet. Its record names the files that were replaced and "
        .. "the copies of the originals, and removing ReaAssist now would "
        .. "delete both, so nothing was changed.\n\nThe record is here:\n"
        .. tostring(jword) .. "\n\nRestart ReaAssist. It finishes or undoes "
        .. "that update at startup, and the uninstall can run afterwards."),
    }
  elseif jword == "invalid" then
    out[#out + 1] = {
      code = "journal_invalid",
      path = jpath,
      message = Updater.uninstall_t("blocked.journal_invalid",
        { path = tostring(jpath) },
        "ReaAssist found the record of an interrupted update that it "
        .. "cannot read, so it cannot tell which files that update touched. "
        .. "Nothing was changed.\n\nThe record is here:\n" .. tostring(jpath)
        .. "\n\nRestart ReaAssist. It sets that record aside as evidence and "
        .. "offers to verify and repair the install; the uninstall can run "
        .. "once that is done."),
    }
  end
  return out
end

-- The refusal the apply lock itself produced, in the same three shapes
-- download_start uses and for the same reasons. It is built here rather than
-- read from the surface because the acquisition is the only thing that looked
-- at the name, and a surface asking again later would be answering about a
-- different instant.
function Updater.uninstall_lock_blocker()
  if Updater._apply_lock_undecidable == nil then
    return {
      code = "apply_lock",
      message = Updater.uninstall_t("blocked.apply_lock", nil,
        "Another copy of ReaAssist is applying an update on this "
        .. "install. Let it finish, then start the uninstall again. Nothing "
        .. "was changed."),
    }
  end
  if Updater._apply_lock_undecidable_kind == "blocked" then
    return {
      code = "apply_lock_blocked",
      path = Updater._apply_lock_undecidable_path,
      message = Updater.uninstall_t("blocked.apply_lock_blocked",
        { path = tostring(Updater._apply_lock_undecidable_path
          or Updater.uninstall_t("named_in_log", nil,
            "(the ReaAssist log names it)")) },
        "ReaAssist cannot look inside the folder where it keeps the "
        .. "claim that says an update is in progress, so it cannot tell "
        .. "whether another copy of ReaAssist is applying one on this "
        .. "install. Nothing was changed.\n\nThe folder is here:\n"
        .. tostring(Updater._apply_lock_undecidable_path
          or Updater.uninstall_t("named_in_log", nil,
            "(the ReaAssist log names it)"))
        .. "\n\nGive your account permission to open it, then try again."),
    }
  end
  return {
    code = "apply_lock_undecidable",
    path = Updater._apply_lock_undecidable_path,
    message = Updater.uninstall_t("blocked.apply_lock_undecidable", {
      path = tostring(Updater._apply_lock_undecidable_path
        or Updater.uninstall_t("named_in_log", nil,
          "(the ReaAssist log names it)")),
      owner = tostring(Updater._apply_lock_undecidable ~= ""
        and Updater._apply_lock_undecidable
        or Updater.uninstall_t("unnamed_owner", nil,
          "a copy of ReaAssist whose name could not be read")),
      kind = (Updater._apply_lock_undecidable_kind == "folder"
        and Updater.uninstall_t("kind.folder", nil, "folder")
        or Updater.uninstall_t("kind.file", nil, "file")),
    },
      "ReaAssist cannot tell whether another copy of ReaAssist is "
      .. "still applying an update on this install, so it has not removed "
      .. "anything.\n\nThe claim is here:\n"
      .. tostring(Updater._apply_lock_undecidable_path
        or Updater.uninstall_t("named_in_log", nil,
          "(the ReaAssist log names it)"))
      .. "\n\nIt was recorded by:\n"
      .. tostring(Updater._apply_lock_undecidable ~= ""
        and Updater._apply_lock_undecidable
        or Updater.uninstall_t("unnamed_owner", nil,
          "a copy of ReaAssist whose name could not be read"))
      .. "\n\nClose any other REAPER window that is running ReaAssist and try "
      .. "again. If you are sure no other copy of ReaAssist is running on "
      .. "this computer, delete the "
      .. (Updater._apply_lock_undecidable_kind == "folder"
        and Updater.uninstall_t("kind.folder", nil, "folder")
        or Updater.uninstall_t("kind.file", nil, "file"))
      .. " named above and try again."),
  }
end

-- Is an uninstall running in THIS instance, and is one finished?
--
-- The cross-instance direction is the apply lock's job and needs nothing new:
-- an uninstall holds that lock for its whole run, so another instance's
-- download_start fails to acquire and refuses exactly as it would against
-- another download. The same-instance direction is what these answer, because
-- acquire_apply_lock ADOPTS a lock already carrying this instance's name, so
-- an update started from this window during an uninstall would sail through
-- the lock and start writing into a tree that is being removed.
function Updater.uninstall_active()
  return Updater._uninstall_running == true
end

function Updater.uninstall_barrier()
  return Updater._uninstall_running == true or Updater._uninstalled == true
end

-- Remove one file and PROVE it went. os.remove's own answer is not the whole
-- proof: what matters for the caller's own next step is whether the name is
-- still there afterwards, asked with the same fail-closed probe every other
-- removal in this lane is asked with.
--
-- AND THE SECOND ANSWER SAYS WHICH OF THE TWO IT WAS, because "the name is not
-- there" and "this call took it" are different facts and only the second one is
-- a removal this run performed. Round 54's second blocker was that distinction
-- missing from the directory removal below; the same distinction is missing
-- here for the same reason, and a run that counts a file somebody else took as
-- one of its own removals is claiming something it did not do. os.remove
-- answering true is the only thing that says this call is what took the name.
function Updater.uninstall_remove_file(path)
  if type(path) ~= "string" or path == "" then return false, "unnamed" end
  if os.remove(path) == true then return true, "removed" end
  if not RA.path_present(path) then return true, "gone" end
  return false, "refused"
end

-- Remove a directory this run has just proven empty, and prove that went too.
--
-- NON-RECURSIVE ON BOTH PLATFORMS, deliberately, and this is the one place
-- where the difference matters. os.remove is rmdir on POSIX and refuses a
-- directory with anything in it. On Windows os.remove cannot remove a
-- directory at all, so that platform shells out, and it shells out to `rmdir`
-- WITHOUT /s, which refuses in exactly the same way. A file landing in the
-- directory between the listing that proved it empty and the removal therefore
-- survives, and the directory is reported as left behind. A recursive delete
-- here would take that file instead, which is check-then-act on a shared name,
-- and that is the defect class this whole lane exists to kill.
--
-- AND BECAUSE IT IS NON-RECURSIVE, IT IS ALSO THE LINK PROBE. Both spellings
-- take a link itself and never what it points at: POSIX os.remove unlinks a
-- symbolic link, and `rmdir` without /s deletes a junction and leaves its
-- target whole, which this project measured rather than assumed.
-- uninstall_remove_tree calls this before it enters ANY directory and before
-- it renames one, for exactly that reason, so read a change here as a change
-- to containment rather than to a tidy-up helper.
--
-- IT IS ALSO THE ONE DESTRUCTIVE-LOOKING CALL THAT MAY BE AIMED AT A NAME THIS
-- RUN HAS NOT TAKEN, because it cannot destroy the contents of anything. The
-- worst it can do through a name that was swapped in the instant before it is
-- remove a link or an empty directory, and neither of those is somebody's
-- work.
-- AND THE ANSWER IS SPLIT, because "the name is not there" and "this run took
-- it away" are different facts and only the second one is evidence of anything.
-- Round 53's first blocker was a record settled on the first while the caller
-- believed it had the second: the folder the record described had been moved
-- away by somebody else, the ask answered true because there was nothing left
-- to refuse it, and the only description of where the folder belonged was
-- erased. Every caller that acts on a RECORD asks for the kind; the callers
-- that only want the name gone keep the plain answer below.
--
--   gone     there was nothing at the name for THIS CALL to take, so this run
--            removed nothing and nothing at all is settled from it
--   removed  this call's own removal act succeeded against something that was
--            standing there
--   refused  it is still standing, which a non-recursive rmdir answers for any
--            directory holding anything at all
--   unnamed  no name was given, so nothing was asked
--
-- AND THE ANSWER IS READ OFF THIS CALL'S OWN ACT RATHER THAN OFF THE NAME
-- AFTERWARDS, which is round 54's second blocker. B2.4f asked whether the name
-- was there, performed the removal, and then read a name that had gone as one
-- this call had taken. Between those two acts the directory can be MOVED AWAY
-- by somebody else, and the answer then said "removed" for a folder this run
-- never touched, which is exactly the evidence the walk closes a record on. The
-- check is gone: every answer below comes from the removal itself.
--
-- AND NO BRANCH OF IT DELETES A FILE, which is round 55's second blocker. A
-- REGULAR FILE swapped in at a directory's name was taken by os.remove on
-- either platform (P54: true, and the bytes are gone), so an actor who put a
-- file where a folder had been had it deleted and the caller read "removed".
-- Two things answer that, and both were measured rather than reasoned about.
--   * THE KIND IS ASKED FIRST, through an open that changes nothing. A name
--     that opens as a readable file is answered "file", kept and surfaced, and
--     never removed. The probe-to-act window is still there and is not claimed
--     away: on POSIX os.remove IS the only spelling this side has and it
--     unlinks a file (P54), so a file that arrives inside that window is taken.
--   * ON WINDOWS NOTHING BUT THE SHELL IS ASKED AT ALL, so the window costs
--     nothing there. os.remove can never take a directory on Windows (P54b,
--     P54c, P54d: EACCES for an empty one, a full one and a junction alike), so
--     the only thing it could ever have removed on that platform was a file,
--     and it is gone from this path. `rmdir` REFUSES a file with an exit code
--     of its own and leaves the bytes untouched (P53e: 267).
--
-- THE ANSWERS THIS CALL'S OWN ACT GIVES, measured on this machine. os.remove IS
-- rmdir on POSIX, so a true answer is this call having taken a directory that
-- was really there and its errno tells an empty name apart from a full one. On
-- Windows the shell's own exit code separates every state (P42, P53: 0 for a
-- directory it took and for a junction it took, 145 for one it refused, 2 for a
-- name that was not there, 267 for a file it would not touch).
function Updater.uninstall_remove_empty_dir_kind(path)
  local dir = tostring(path or ""):gsub("[/\\]+$", "")
  if dir == "" then return false, "unnamed" end
  if Updater.uninstall_name_is_file(dir) then return false, "file" end
  if not RA.IS_WINDOWS then
    local ok, _, code = os.remove(dir)
    if ok == true then return true, "removed" end
    -- 2 is ENOENT on every platform this ships to, and it is the one answer
    -- that means this call had nothing to take.
    if tonumber(code) == 2 then return false, "gone" end
    return false, "refused"
  end
  if dir:find('"', 1, true) then return false, "refused" end
  if type(reaper.ExecProcess) ~= "function" then return false, "refused" end
  local ran, said = pcall(reaper.ExecProcess,
    'cmd.exe /c rmdir "' .. dir .. '"', 5000)
  local exit = ran and tonumber(tostring(said or ""):match("^%s*(%-?%d+)"))
  if exit == 0 then return true, "removed" end
  if exit == 2 then return false, "gone" end
  if exit == 267 then return false, "file" end
  -- An answer this side cannot read at all is read as a refusal, because "still
  -- standing" is the answer that keeps a record open and names a folder.
  return false, "refused"
end

-- DOES THIS NAME OPEN AS A READABLE FILE? Asked with an open that takes
-- nothing and writes nothing, in front of every removal aimed at a directory.
--
-- The platforms answer differently and both halves are written down here. On
-- Windows a directory and a junction both REFUSE the open (P52a, P52d: EACCES),
-- so an open that succeeds is a file and nothing else. On POSIX a directory
-- opens and the first read of it fails, so a read that hands back a byte is a
-- file. That leaves one name the two questions cannot tell apart, an EMPTY file
-- against a directory (P52c: the open succeeds and the read is empty for both
-- shapes), and a trailing separator is what answers it: a directory accepts one
-- and a regular file answers ENOTDIR. That last step was MEASURED on the
-- MacBook (2026-08-16): this function run verbatim answered the full
-- nine-shape matrix exactly as this comment reads it, the trailing-separator
-- step included, an empty file answering ENOTDIR while a directory opens.
-- This machine is Windows and never reaches it: P52a shows the directory
-- refusing the open one question earlier.
function Updater.uninstall_name_is_file(path)
  if type(path) ~= "string" or path == "" then return false end
  local handle, first
  pcall(function() handle = io.open(path, "rb") end)
  if not handle then return false end
  pcall(function() first = handle:read(1) end)
  pcall(function() handle:close() end)
  if type(first) == "string" and first ~= "" then return true end
  local as_dir
  pcall(function() as_dir = io.open(path .. "/", "rb") end)
  if as_dir then
    pcall(function() as_dir:close() end)
    return false
  end
  return true
end

function Updater.uninstall_remove_empty_dir(path)
  local gone = Updater.uninstall_remove_empty_dir_kind(path)
  return gone
end

-- ===========================================================================
-- Legacy cleanup after the migration
-- ===========================================================================
-- Plan section 3b, migration rule 3: the handoff manifest omits legacy
-- removals for EVERYONE, because the pre-N orphan pass has no ownership branch
-- and therefore cannot preserve a ReaPack install's dormant tree while
-- cleaning a website install's. This lane is that omission's replacement, and
-- it lives in the new body because the new body is the only thing that can ask
-- the ownership question at all.
--
-- WHAT MAY BE REMOVED IS DECIDED PER FILE, NOT PER INSTALL. The package brief
-- phrased this at launcher level (website install removes, ReaPack install
-- leaves), which gives the right answer for the two plain cases and the wrong
-- one inside a single ReaPack install. A name this package RETIRED in an
-- earlier version is no longer registered with ReaPack, so ReaPack will never
-- put it back and it is ours to take; a name the N package still carries is
-- registered, and taking it invites exactly the same-version reinstall that
-- section 3a MEASURED and that Variant B exists to avoid. Nothing but the file
-- itself can tell those two apart, so every candidate is asked about by path.
-- Ruled and accepted for this package; it supersedes the launcher-level
-- phrasing rather than contradicting it, because both plain cases still land
-- exactly where the brief put them.
--
-- CONFIRMED UNOWNED IS THE ONLY ANSWER THAT REMOVES ANYTHING (section 2,
-- B2.3b). Owned leaves the dormant tree alone, foreign was never ours, and
-- unknown is the absence of a finding rather than permission to act on one.
--
-- THE LANE ONLY DELETES, so the recovery question is what a crash leaves
-- rather than what it half-wrote. Every path this run removed answers "absent"
-- on the next run and is skipped; every path it had not reached answers what
-- it would have answered anyway. A partial cleanup is therefore
-- indistinguishable from one that has not started, and can never read as
-- damage. The two ordering rules that keep it that way are files before
-- directories, and no directory removed that this run did not itself empty.

-- The frozen candidate list, package-root-relative, with its provenance.
--
-- G1, the body files release 1.4.9 shipped and the manifest listed. In a
-- ReaPack install these are registered at N and the probe answers owned, so
-- they stay; in a website install nothing owns them and they go.
Updater.LEGACY_CLEANUP_FILES = {
  "CHANGELOG.md",
  "LICENSE.txt",
  "README.md",
  "Resources/API_Ref.md",
  "Resources/CodeRuntime.lua",
  "Resources/Context.lua",
  "Resources/Diag.lua",
  "Resources/I18N.lua",
  "Resources/Plugin_Pack.md",
  "Resources/Prompts.md",
  "Resources/Reaper_Recent_Changes.md",
  "Resources/Relaunch.lua",
  "Resources/System_Prompt.md",
  "Resources/UI.lua",
  "Resources/ReEQ/LICENSE.txt",
  "Resources/ReEQ/ReEQ.jsfx",
  "Resources/ReEQ/Dependencies/firhalfband.jsfx-inc",
  "Resources/ReEQ/Dependencies/spectrum.jsfx-inc",
  "Resources/ReEQ/Dependencies/svf_filter.jsfx-inc",
  "Resources/fonts/Inter_18pt-Bold.ttf",
  "Resources/fonts/Inter_18pt-Light.ttf",
  "Resources/fonts/Inter_18pt-Regular.ttf",
  "Resources/fonts/Inter_18pt-SemiBold.ttf",
  "Resources/fonts/JetBrainsMono-Medium.ttf",
  "Resources/fonts/JetBrainsMono-Regular.ttf",
  "Resources/fonts/lucide.ttf",
  -- G2, names this package retired in earlier generations and the 1.4.9
  -- manifest still carries in removed_files. ReaPack stopped registering each
  -- of them when it stopped shipping them, so no install has an owner for one
  -- and the probe says so; they are listed here rather than assumed, and the
  -- probe still runs in front of every one.
  "ReaAssist - Screen Reader Mode.lua",
  "ReaAssist_ScreenReaderMode.lua",
  "Resources/Help.md",
  "Resources/MIDI_Ref.md",
  "Resources/Plugin_Ref.md",
  "Resources/ScreenReaderMode.lua",
  "Resources/Theme_Ref.md",
  "Resources/fonts/JetBrainsMono-SemiBold.ttf",
  -- G3, the two runtime artifacts THIS PROGRAM wrote into the legacy zone back
  -- when the package was flat. They carry one precondition the others do not,
  -- below: they are only candidates once this launch has finished migrating
  -- them into Data/, because a failed migration leaves the running body
  -- writing the legacy path.
  "Resources/FX_Cache.json",
  "Resources/Debug.log",
}

-- Directories, deepest first, and each one removed only if this run emptied it.
-- Resources/Local is deliberately absent: it is where a user's own scripts
-- live, so it is not this lane's to tidy even when empty.
Updater.LEGACY_CLEANUP_DIRS = {
  "Resources/ReEQ/Dependencies",
  "Resources/ReEQ",
  "Resources/fonts",
  "Resources",
}

-- NEVER A CANDIDATE, written down so the reason survives and a harness row can
-- hold the list to it. These are not "protected" in the sense of being asked
-- about and refused; they are not asked about at all.
--
--   Resources/System_Prompt_Custom.md  the documented power-user override.
--   Resources/Local/                   the user's own scripts.
-- Surveyed rather than assumed: nothing in the body and nothing in the
-- launcher migrates either one out of the legacy zone, so they stay exactly
-- where their owner put them and this lane never names them. Because the
-- directory removal below is non-recursive, an install carrying either one
-- simply keeps its legacy Resources/ folder, which is the correct outcome and
-- needs no special case.
--
--   manifest.json    the pre-N manifest at the package root, which is also
--                    where pre-N clients poll the handoff manifest. Its
--                    removal policy is work package C's open item (section 3b)
--                    and is deliberately carried there rather than guessed at
--                    here.
--   ReaAssist.lua, ReaAssist_Screen_Reader_Mode.lua
--                    the two permanent action identities. Not legacy at all.
--   The N-only legacy-zone body main file (section 10a's working
--                    interpretation) is not listed either: it is registered at
--                    N, so the probe would leave it, and N+1 is what removes
--                    it. Naming it here would freeze a filename work package C
--                    has not chosen yet.
Updater.LEGACY_CLEANUP_NEVER = {
  ["Resources/System_Prompt_Custom.md"] = "user override",
  ["Resources/Local"]                   = "user scripts",
  ["manifest.json"]                     = "carried to work package C",
  ["ReaAssist.lua"]                     = "permanent action identity",
  ["ReaAssist_Screen_Reader_Mode.lua"]  = "permanent action identity",
}

-- The legacy paths this launch is still WRITING, read off the migration's own
-- answer rather than re-derived.
--
-- RA._migrate_runtime_file returns the path the program will actually use, so
-- a rename that failed leaves RA.FX_CACHE_PATH or RA.DEBUG_LOG_PATH pointing
-- back into the legacy folder and this session appends to it. Asking the
-- migration what it decided is the only way these two can never disagree;
-- re-deriving "did the migration work" here would be a second opinion, and a
-- second opinion is what the round-68 lesson in the settings guard was about.
function Updater.legacy_cleanup_live_paths()
  local live = {}
  for _, p in ipairs({ RA.FX_CACHE_PATH, RA.DEBUG_LOG_PATH }) do
    if type(p) == "string" and p ~= "" then live[p] = true end
  end
  return live
end

-- IS THIS NAME A LINK? A junction, a symbolic link, any reparse point.
--
-- Round 71 is why this exists. Every candidate below the package root shares
-- its ancestors, so a junction dropped at `Resources` redirects the whole list
-- out of the install, and the old code looked only at the FINAL entry's kind:
-- os.remove would then have followed the redirected parent and taken somebody
-- else's file. Ancestors are asked about before anything is removed.
--
-- EXIT 1 IS NOT EVIDENCE, and round 72 is why this reads the error identity
-- rather than the exit code. Measured on this machine, read-only, rather than
-- inherited from the review:
--
--   junction          exit 0, "Reparse Tag Value : 0xa0000003 ... Mount Point"
--   real directory    exit 1, "Error 4390: The file or directory is not a
--                              reparse point."
--   name not there    exit 1, "Error 2: The system cannot find the file
--                              specified."
--   access denied     exit 1, "Error 5: Access is denied."
--
-- So exit 1 covers three different facts and the old classifier called all
-- three "not a link". The dangerous one is Error 5: an ancestor this account
-- cannot open would have been read as safe and the pass would have walked
-- through it. Only 4390 means not-a-link. A name that is not there is its own
-- answer and is honest about being one. Access denied, and anything this side
-- does not recognise, is CANNOT-TELL and refuses.
--
-- THE ARGUMENT IS SANITIZED FOR TWO CHARACTERS, not one. A quotation mark ends
-- the argument early; a percent sign is expanded by cmd.exe against the
-- environment BEFORE fsutil sees it, so `%TEMP%` in a path would have this ask
-- about a different name than the one being removed. ReaAssist ships no name
-- carrying either, so refusing both costs nothing real and closes the gap
-- between the path asked about and the path acted on.
--
-- macOS IS MEASURED (release-prep round 204). Through REAPER's ExecProcess,
-- `/bin/sh -c <quoted test>` returned exit 0 for every measured name: an
-- ordinary directory, a regular file, a real symbolic link, a missing name,
-- and a child behind a mode-000 directory. Direct BSD stat kept the five
-- answers distinct: exit 0 plus Directory, Regular File, or Symbolic Link;
-- exit 1 plus No such file or directory; and exit 1 plus Permission denied.
-- The Mac branch therefore uses that measured command and safe-lists only the
-- three successful types. Linux uses direct `/bin/test -L` without the broken
-- shell wrapper. Its exit 1 still conflates not-a-link, not-there, and
-- unreadable, which remains the recorded Linux debt.
--
-- Returns true (link), false (not a link), "missing", or nil (cannot tell).
-- GENERALIZED IN B2.7a, DELIBERATELY AND IN NAME. This was
-- `legacy_cleanup_link_kind` and it was never legacy-specific: it takes an
-- absolute path and answers with the measured shapes, and the parked-copy lane
-- needs exactly the same answer about a different tree. Renamed rather than
-- copied, the way the launcher ownership probe was split rather than
-- duplicated, because two link probes would be two chances to get the error
-- identities wrong. It still lives here, beside the lane that first needed it,
-- and both callers go through `Updater.chain_refusal` below.
function Updater.path_link_kind(path)
  if type(path) ~= "string" or path == "" then return nil end
  if type(reaper.ExecProcess) ~= "function" then return nil end
  local cmd
  if RA.IS_WINDOWS then
    if path:find('"', 1, true) or path:find("%", 1, true) then return nil end
    cmd = 'cmd.exe /c fsutil reparsepoint query "' .. path .. '"'
  elseif RA.IS_MACOS then
    cmd = "/usr/bin/stat -f %HT " .. Shell.sh_quote(path)
  else
    cmd = "/bin/test -L " .. Shell.sh_quote(path)
  end
  local ran, said = pcall(reaper.ExecProcess, cmd, 5000)
  if not ran then return nil end
  local out = tostring(said or "")
  local exit = tonumber(out:match("^%s*(%-?%d+)"))
  if RA.IS_MACOS then
    if exit == 0 then
      local kind = out:match("^[^\r\n]*[\r\n]+([^\r\n]+)")
      if kind == "Symbolic Link" then return true end
      if kind == "Directory" or kind == "Regular File" then return false end
      return nil
    end
    if exit == 1 and out:find("No such file or directory", 1, true) then
      return "missing"
    end
    return nil
  end
  if exit == 0 then return true end
  if not RA.IS_WINDOWS then
    if exit == 1 then return false end
    return nil
  end
  if exit ~= 1 then return nil end
  if out:find("4390", 1, true) then return false end
  if out:find("Error 2:", 1, true) then return "missing" end
  return nil
end

-- The directory chain a candidate hangs from, inside the package root,
-- outermost first. The package root itself is not in it: this body is running
-- from inside it, so it is the ground everything else is measured against
-- rather than something this pass can hold an opinion about.
function Updater.legacy_cleanup_ancestors(rel)
  local out, seen = {}, ""
  for part in tostring(rel or ""):gmatch("([^/]+)/") do
    seen = (seen == "") and part or (seen .. "/" .. part)
    out[#out + 1] = seen
  end
  return out
end

-- ONE DIRECTORY, ONE ANSWER, and it is the whole of what either walk knows.
--
-- Extracted in B2.7a so the parked-copy lane asks this question through the
-- same code rather than beside it. Everything measured lives here: presence is
-- asked first, the link probe's four answers are classified by safe-list, and a
-- file standing where a folder belongs is its own refusal. The two callers
-- differ only in how they enumerate directories, one walking relative names
-- under the package root and one walking absolute ones, and each keeps its own
-- labels for its own copy.
--
-- Returns nil when the directory is fine to act under, or the reason it is not.
function Updater.chain_refusal(path)
  if not RA.path_present(path) then return nil end
  local link = Updater.path_link_kind(path)
  -- Compared against true and not merely tested for truth: "missing" is a
  -- string and therefore truthy, and reading it as a link would refuse a
  -- pass over an ancestor that simply is not there.
  if link == nil then return "unreadable" end
  if link == true then return "link" end
  -- "missing" carries on: nothing is under a name that is not there, so the
  -- caller's own presence check finds nothing and the pass costs nothing. It is
  -- answered honestly rather than folded into false.
  if link == false and Updater.uninstall_name_is_file(path) then
    return "file where a folder belongs"
  end
  return nil
end

-- Is every ancestor of this candidate a real directory this body can read?
-- Returns true, or false plus the ancestor that answered and why.
function Updater.legacy_cleanup_chain_ok(rel)
  for _, dir in ipairs(Updater.legacy_cleanup_ancestors(rel)) do
    local why = Updater.chain_refusal(Updater.name_under(RA.PACKAGE_DIR, dir))
    if why then return false, dir, why end
  end
  return true
end

-- The facts the apply lock CANNOT pin, re-asked immediately before every
-- destructive act.
--
-- The lock stops another ReaAssist body from applying, journalling or
-- uninstalling while this pass runs, so nothing it covers is asked twice. It
-- does not stop a new instance from opening, and it does not stop a launcher
-- from taking a repair claim, and either one means somebody may now be reading
-- the very files this pass is about to take. Returns a reason or nil.
function Updater.legacy_cleanup_volatile()
  local others = Updater.uninstall_foreign_instances()
  if #others > 0 then
    local names = {}
    for _, rec in ipairs(others) do names[#names + 1] = tostring(rec.instance) end
    return "another instance appeared: " .. table.concat(names, ", ")
  end
  if Updater.uninstall_launcher_lock_path() then
    return "a launcher claim landed"
  end
  return nil
end

-- May this install be cleaned at all? Asked once, before anything is touched.
--
-- The layout question is the one that matters most and it is asked first, by
-- the uninstaller's own blocker list rather than by a second rule of this
-- lane's: RA.package_dir_for resolves FLAT whenever no marker-verified
-- launcher stands above the body, and in a flat install the legacy zone and
-- the running body are the same directory, so every name in the list above
-- would be aimed at the program that is executing it. uninstall_blockers
-- already refuses that install for the same reason, so it is reused whole
-- instead of restated, and the rest of what it refuses is exactly what this
-- lane must refuse too: an update in flight whose rollback may still need
-- these files, another live instance that may be running the old body out of
-- this very folder, a launcher holding a repair claim, and a quarantined or
-- invalid journal.
--
-- Then the precondition the package brief asked for by name, and it is a
-- proof rather than a comment: the body manifest has to be readable at
-- App/manifest.json. A body running from App/ under a marker-verified
-- launcher with its own manifest in place is a finished migration that
-- relaunched, and nothing else produces that shape.
--
-- Returns true, or false plus the reason for the log.
-- THE LOCK IS NOT ASKED ABOUT HERE, IT IS TAKEN BY THE CALLER, and round 71 is
-- why that sentence is in this comment. This function used to end with
-- `if Updater.uninstall_lock_blocker() then ... end`, which reads like a lock
-- predicate and is not one: it is the refusal FORMATTER the uninstaller calls
-- AFTER acquire_apply_lock has already failed, and its first branch fires when
-- `_apply_lock_undecidable` is nil, which is the ordinary state of a healthy
-- install. So it returned a blocker every time and the lane never ran once.
-- The real question is the one the uninstaller and download_start both ask,
-- the apply-lock acquisition itself, and the pass asks it and holds it. The
-- name is deliberately not spelled in full here: the launcher harness counts
-- the roads into the locked region by counting that exact string, and a
-- mention in a comment is not a road.
function Updater.legacy_cleanup_ready()
  if RA.PACKAGE_DIR == RA.APP_DIR then return false, "flat layout" end
  local blockers = Updater.uninstall_blockers()
  if #blockers > 0 then
    local codes = {}
    for _, b in ipairs(blockers) do codes[#codes + 1] = tostring(b.code) end
    return false, "blocked: " .. table.concat(codes, ", ")
  end
  local manifest = io.open(RA.APP_DIR .. "manifest.json", "rb")
  if not manifest then return false, "no body manifest to prove the relaunch" end
  manifest:close()
  return true
end

-- One candidate, asked and answered.
--
-- The probe is UNCACHED and stands immediately in front of the removal, which
-- is the rule B2.3b set for every destructive moment: a synchronization can
-- land between a queue being built and a file being taken, and the answer that
-- matters is the one nobody has had time to invalidate.
--
-- Returns the outcome word for the log.
-- One candidate, asked and answered.
--
-- EVERY MUTABLE SAFETY FACT IS RE-ASKED IMMEDIATELY IN FRONT OF THE ACT, and
-- round 71 rejected the once-per-pass gate that used to stand in for this. The
-- apply lock is held for the whole pass by the caller, so what the lock pins is
-- not asked twice; what it cannot pin is asked here, per act, in the order that
-- costs least first. Per fact:
--
--   ownership        the lock cannot pin it. A ReaPack synchronization is
--                    another program entirely. RE-ASKED, uncached.
--   path kind        the lock cannot pin it. Anything on the machine can put a
--                    file where a folder was. RE-ASKED.
--   live write target
--                    this process's own answer, and the lock does pin the
--                    other bodies; re-read anyway because it is free.
--   ancestors        the lock cannot pin them. Every present candidate walks
--                    its own chain immediately before the remaining gates.
--   another instance, launcher claim
--                    the lock does NOT pin either: it stops another body
--                    APPLYING, not a new one opening or a launcher taking a
--                    repair claim. RE-ASKED, but only once a candidate has
--                    got as far as being removable, so a settled install pays
--                    nothing for them.
--   an update, journal, quarantine, uninstall by another body
--                    HELD BY THE LOCK. Asked once in the static gate and not
--                    again.
--
-- Returns the outcome word for the log, and "abort: ..." when the pass itself
-- must stop rather than this candidate be skipped.
function Updater.legacy_cleanup_one(rel, progress)
  if Updater.LEGACY_CLEANUP_NEVER[rel] then return "never" end
  local path = Updater.name_under(RA.PACKAGE_DIR, rel)
  if not RA.path_present(path) then return "absent" end
  -- Only a present candidate can reach a destructive act. Ask its ancestor
  -- chain here so absent legacy names do not launch one fsutil process per
  -- directory group during every startup. This also rechecks the chain for
  -- every present file instead of caching one answer across a group.
  local chain_ok, offender, chain_why =
    Updater.legacy_cleanup_chain_ok(rel)
  if not chain_ok then
    return "abort: ancestor " .. tostring(offender) .. " is "
      .. tostring(chain_why)
  end
  -- ORDER MATTERS AND ROUND 72 REORDERED IT. The old order read ownership
  -- first and then asked the volatile facts, which is check-then-act with the
  -- expensive check first: the answer that decided the act was the oldest
  -- thing in the sequence. Volatile first, then ownership, then kind, then the
  -- act, so each answer is younger than the one it overrules.
  local volatile = Updater.legacy_cleanup_volatile()
  if volatile then return "abort: " .. volatile end
  -- ASKED PER ACT, from the migration's own answer, and no longer from a
  -- snapshot taken once at the top of the pass. The snapshot was a pass-level
  -- cache wearing a per-act claim.
  local live = Updater.legacy_cleanup_live_paths()
  if live[path] then return "in use" end
  local state, detail = Updater.reapack_owner_of(path)
  if state ~= Updater.OWNERSHIP_UNOWNED then
    return tostring(state) .. " (" .. tostring(detail) .. ")"
  end
  -- A name that opens as a directory is never handed to the file remover: the
  -- directory pass is the only thing allowed at a directory's name, and it is
  -- non-recursive on both platforms and takes a link rather than what a link
  -- points at.
  if not Updater.uninstall_name_is_file(path) then return "not a file" end
  local ok, why = Updater.uninstall_remove_file(path)
  if ok and why == "removed" and progress then
    -- TRUE PROVENANCE, and round 71 is why it is recorded here rather than
    -- inferred later. A directory may only go if THIS RUN emptied it, so the
    -- act that took something out of a directory is the only thing entitled to
    -- say so, and it says so at the moment it succeeds.
    progress[rel:match("^(.*)/[^/]+$") or ""] = true
  end
  return ok and tostring(why) or ("refused (" .. tostring(why) .. ")")
end

-- The pass. Silent, best effort, and it never reports a failure to the user:
-- everything it declines to do is a file staying exactly where it already was,
-- which is the state this install has been in since it migrated.
-- The pass. Silent, best effort, and it never reports a failure to the user:
-- everything it declines to do is a file staying exactly where it already was,
-- which is the state this install has been in since it migrated.
--
-- THE APPLY LOCK IS HELD FOR THE WHOLE PASS, taken the way the uninstaller and
-- download_start take it, and released on every exit including the ones that
-- raise. That is what makes "no other body is applying, journalling or
-- uninstalling" a fact for the duration rather than a reading from one instant,
-- which is what round 71 rejected.
--
-- THE ANCESTOR WALK, AND THE WINDOW IT DOES NOT CLOSE. Every present candidate
-- below the package root walks its own ancestors before ownership and removal.
-- Absent candidates do not need an external link probe because they cannot
-- reach an act. A link arriving between present candidates is therefore caught.
-- The window between each walk and its act remains and is stated directly:
--   * what bounds it: the lock is held, the pass is bounded at 36 files and 4
--     directories with no recursion and no enumeration, and every present file
--     receives its own chain walk.
--   * what the ceiling is: the specific names in the frozen list, resolved
--     through a hostile ancestor, deleted. It is not a tree walk and it cannot
--     become one, because nothing here descends.
--   * what B2.4 measured, and why directories are not exposed at all: rmdir
--     without /s takes a junction and leaves its target whole, and POSIX
--     os.remove unlinks a symbolic link rather than following it. A link
--     swapped in at a DIRECTORY candidate therefore costs the link and nothing
--     behind it.
--   * what would be needed to close it: an open-once-then-act handle the Lua
--     side does not have, or the claim-and-rename apparatus B2.4 built for the
--     uninstaller. Neither is in this package and neither is claimed here.
function Updater.legacy_cleanup_run()
  -- THE LOCK COMES FIRST AND THE BLOCKER READ HAPPENS INSIDE IT, which is the
  -- uninstaller's own ordering and what round 72 required. The blocker list's
  -- own header says its authoritative read is the one taken with the lock
  -- held, and the old code read it BEFORE acquiring: another holder could
  -- create or quarantine a journal, release its lock, and this pass would take
  -- the now-free lock and act on a reading of persistent state that was
  -- already stale. Only the layout is asked outside, as a cheap early-out,
  -- because a package root cannot become an app root while the process runs.
  if RA.PACKAGE_DIR == RA.APP_DIR then
    Log.line("UPDATE", "legacy cleanup: skipped; flat layout")
    return false, "flat layout"
  end
  if not Updater.acquire_apply_lock() then
    Log.line("UPDATE", "legacy cleanup: skipped; the apply lock is held")
    return false, "apply lock held"
  end
  -- NOTHING BUT THE ACQUISITION STANDS BETWEEN THE LOCK AND THE PROTECTED
  -- CALL, and round 73 is why that is a rule rather than a preference. The
  -- authoritative gate used to run here, outside the pcall, and it probes the
  -- blocker list, the journal, the instance table and the manifest. A raise
  -- from any of them left this function by the error path with the lock still
  -- held, and the raise tooth could not see it because the tooth injected
  -- inside the protected call. The gate is inside it now, so there is one exit
  -- path and it always releases.
  local ok_run, result_or_err, removed, left, gated = pcall(function()
    local ready, why = Updater.legacy_cleanup_ready()
    if not ready then
      Log.line("UPDATE", "legacy cleanup: skipped; " .. tostring(why))
      -- The fourth value separates a GATE REFUSAL from a pass that ran and
      -- stopped. Both leave the install untouched, but only one of them ran.
      return why, 0, 0, true
    end
    -- `progress` is what this run has actually emptied. A directory may only go
    -- if it is in here, so a folder that was already empty when the pass
    -- started is left exactly where it is: this run did not empty it, and
    -- removing somebody else's empty folder is not this lane's business.
    local progress = {}
    local counted_removed, counted_left = 0, 0
    local aborted = nil
    for _, rel in ipairs(Updater.LEGACY_CLEANUP_FILES) do
      local outcome = Updater.legacy_cleanup_one(rel, progress)
      if outcome:sub(1, 7) == "abort: " then
        aborted = outcome:sub(8)
        break
      elseif outcome == "removed" then
        counted_removed = counted_removed + 1
        Log.line("UPDATE", "legacy cleanup: " .. rel .. ": " .. outcome)
      elseif outcome ~= "absent" and outcome ~= "gone" then
        counted_left = counted_left + 1
        -- A dormant ReaPack tree answers "owned" for every file it holds, every
        -- session, and a line each would be two dozen lines of nothing
        -- happening. The count carries it and the first one carries the reason.
        if counted_left == 1 then
          Log.line("UPDATE", "legacy cleanup: " .. rel .. ": " .. outcome)
        end
      end
    end
    -- Directories last and deepest first. TWO conditions, not one: this run
    -- emptied it, AND it answers empty at the act.
    --
    -- Emptiness is still the whole ownership story here and an ownership probe
    -- is still not asked, because ReaPack registers FILES and answers that
    -- nothing owns any directory, so the probe would have been decoration in
    -- front of the rule doing the work. That rule is the stronger one: a
    -- dormant ReaPack tree still holds every file this pass just declined, so
    -- its folder cannot go. What round 71 added is the other half, provenance:
    -- an empty folder this run did not empty is somebody else's.
    if not aborted then
      for _, rel in ipairs(Updater.LEGACY_CLEANUP_DIRS) do
        if not Updater.LEGACY_CLEANUP_NEVER[rel] and progress[rel] then
          local chain_ok, offender, chain_why = Updater.legacy_cleanup_chain_ok(rel)
          if not chain_ok then
            aborted = "ancestor " .. tostring(offender) .. " is "
              .. tostring(chain_why)
            break
          end
          local volatile = Updater.legacy_cleanup_volatile()
          if volatile then aborted = volatile break end
          local path = Updater.name_under(RA.PACKAGE_DIR, rel)
          if RA.path_present(path) then
            -- THE ANCESTOR ANSWER IS RE-ASKED IMMEDIATELY IN FRONT OF THE ACT,
            -- and round 74 measured why. The walk above is separated from this
            -- removal by the volatile probe and the presence check, and a
            -- parent that becomes a junction inside that gap sends rmdir into
            -- the junction's TARGET: the protection that takes a link at the
            -- final component does not apply, because here the link is not the
            -- final component. This narrows the gap, and round 75 is why what
            -- remains is spelled out rather than flattered: the answer below is
            -- the last ancestor answer this pass takes, and the act it guards
            -- is NOT the next statement. The removal helper normalizes the
            -- name, opens it to decide its kind, runs its own guards and only
            -- then calls the shell, so the window runs from this answer through
            -- all of that work to the shell call. It does not close, Lua has no
            -- open-then-act handle, and the sheet states what the remainder
            -- costs rather than claiming it away. It is additive: no refusal
            -- the walk above produced is lost.
            local near_ok, near_off, near_why =
              Updater.legacy_cleanup_chain_ok(rel)
            if not near_ok then
              aborted = "ancestor " .. tostring(near_off) .. " is "
                .. tostring(near_why)
              break
            end
            local gone, kind = Updater.uninstall_remove_empty_dir_kind(path)
            if gone then
              counted_removed = counted_removed + 1
              progress[rel:match("^(.*)/[^/]+$") or ""] = true
            else
              counted_left = counted_left + 1
            end
            Log.line("UPDATE", "legacy cleanup: " .. rel .. "/: " .. tostring(kind))
          end
        end
      end
    end
    if aborted then
      Log.line("UPDATE", "legacy cleanup: stopped; " .. tostring(aborted))
    end
    return aborted, counted_removed, counted_left, false
  end)
  Updater.release_apply_lock()
  if not ok_run then
    Log.line("UPDATE", "legacy cleanup: raised; " .. tostring(result_or_err))
    return false, "raised"
  end
  if gated then return false, result_or_err end
  Log.line("UPDATE", string.format(
    "legacy cleanup: finished; %d removed, %d left standing",
    removed or 0, left or 0))
  return true, result_or_err, removed, left
end

-- =============================================================================
-- The parked copy (plan section 3, decision 10a.2)
-- =============================================================================
-- Section 3 gives release N+1 a promise: a syncing user loses the dormant
-- legacy files and "the launcher restores from the parked copy instantly if
-- anything is missing". This lane is what puts that copy on disk. Everything
-- below is a local copy of files this install already has, from App/ into
-- Recovery/Body/, with no network anywhere near it.
--
-- THE CONTRACT IS NOT INVENTED HERE, IT IS MET. The launcher's restore lane
-- (Dev/Launcher/launcher_core.lua, try_parked) already reads a fixed shape:
-- manifest.json at Recovery/Body/, parseable, covering every critical file,
-- with every file it names present under that root and hashing to the recorded
-- checksum. So the manifest this lane publishes is the body's OWN manifest,
-- byte for byte, and the files are the files that manifest names. Nothing is
-- re-derived, re-serialised or re-ordered, because anything re-derived is a
-- second opinion about what this release is, and the launcher trusts the copy
-- that travels with the bytes.
--
-- WHEN IT RUNS, AND WHY NOT INSIDE THE APPLY. The plan says the runtime parks
-- after applying; this lane satisfies that sentence at the next settled session
-- start rather than inside the apply transaction, for three reasons. A backup
-- that cannot be written must never fail an update, and a park inside the
-- transaction would make a full disk an apply question or a rollback question.
-- The park costs a whole tree read, written and read back, which is not work to
-- put inside the moment the user is being told an update finished. And the
-- next-session trigger covers every way a body arrives at a version, including
-- the launcher's own network bootstrap and its parked restore, which an
-- apply-time hook covers none of; the N+1 promise is owed to users who never
-- take an in-app update at all. What that reading costs is a bounded staleness
-- window: an install that applies Y and is never restarted keeps a parked copy
-- of X until the next session parks it. What stands in that window is a
-- complete, coherent X, and a launcher that restores it restores one whole
-- release with its own manifest, never a mixture.
--
-- WHY IT VERIFIES BY READBACK AND NOT BY HASH. The plan calls the parked copy
-- hash-verified, and it is: the launcher hashes every parked file at the moment
-- it uses it and one mismatch discards the whole copy. That is the check that
-- decides whether a restore happens, and it is the only one that can speak for
-- bytes as they are when they are read rather than as they were months ago.
-- What this lane owes is that the copy is faithful to the tree it was taken
-- from, which a readback answers exactly. A silently corrupted App file is
-- therefore parked faithfully and refused by the launcher, which costs an
-- offline restore and falls to the network lane; it never produces a restore
-- nobody verified.
--
-- THE ORDERING IS THE SAFETY, and it is three rules.
--   1. THE PRE-FLIGHT COMES FIRST. A body missing one of the files its manifest
--      names is not parked at all, and whatever is already parked is left
--      standing: that copy is the recovery asset for exactly this damage, and
--      destroying it to back up a damaged install would be the one move that
--      turns a repairable state into an unrepairable one.
--   2. THE MANIFEST IS CLEARED BEFORE THE FIRST BYTE IS COPIED. While it
--      stands it vouches for the files beside it, and copying over those files
--      underneath it would make it a lie for the length of the copy.
--   3. THE MANIFEST IS PUBLISHED LAST, and only after every file has been
--      written and read back. So an interruption anywhere in the middle leaves
--      files with no manifest, which the launcher discards at its first step,
--      and the next session copies again. A partial parked copy is never
--      restorable, because there is nothing there to restore it from.
--
-- WHAT IT NEVER DOES. It does not walk, list or descend anything: every
-- destination is a manifest name, validated by the same predicate the download
-- pipeline validates with, joined under Recovery/Body/. It removes exactly one
-- name it owns, the parked manifest, and overwrites destinations it is about to
-- write. A file under Recovery/Body/ that this release no longer ships is left
-- where it is rather than swept, because a sweep is a walk and this lane does
-- not have one; the launcher copies only names its manifest lists, so a
-- leftover is inert, and the uninstaller removes the whole tree.

-- The launcher spells this name itself and cannot be told another one, so it is
-- fixed here rather than taken from configuration. `park_names` refuses a
-- manifest that claims it for an entry, which is the launcher's own rule.
Updater.PARKED_MANIFEST_NAME = "manifest.json"
Updater.PARKED_BODY_DIRNAME = "Body"

function Updater.parked_root()
  return tostring(RA.RECOVERY_DIR or "")
    .. Updater.PARKED_BODY_DIRNAME .. RA.SEP
end

function Updater.parked_manifest_path()
  return Updater.parked_root() .. Updater.PARKED_MANIFEST_NAME
end

-- Whole-file read, nil on anything that is not a complete answer. A read that
-- raises is a read that failed, which is the only reading of it this lane has.
function Updater.park_read(path)
  if type(path) ~= "string" or path == "" then return nil end
  local f = io.open(path, "rb")
  if not f then return nil end
  local ok, data = pcall(f.read, f, "*a")
  pcall(f.close, f)
  if not ok or type(data) ~= "string" then return nil end
  return data
end

-- Whole-file write with the close counted. A close is where a full disk is
-- reported, so a write that only checked the write call would report success
-- for a file that never landed.
function Updater.park_write(path, data)
  local f, err = io.open(path, "wb")
  if not f then return false, tostring(err or "open failed") end
  local ok_w, w_ok, w_err = pcall(f.write, f, data)
  local ok_c, c_ok, c_err = pcall(f.close, f)
  if not ok_w or not w_ok or not ok_c or not c_ok then
    return false, tostring((not ok_w and w_ok) or w_err
      or (not ok_c and c_ok) or c_err or "write failed")
  end
  return true
end

-- The names a parked copy is made of, read out of the body's own manifest.
--
-- Every rule the launcher's parser applies is applied here, in front of the
-- copy rather than after it: entries must carry a name and a checksum, names
-- must pass the download pipeline's own filename predicate, no name may repeat,
-- no entry may claim the manifest's own name (the launcher pre-claims it, so a
-- manifest that lists it is refused wholesale), and the list may not be empty.
-- A manifest this lane would publish and the launcher would then refuse is a
-- parked copy that exists and cannot be used, which is worse than no copy at
-- all: it looks like the promise being kept.
function Updater.park_names(raw)
  if type(raw) ~= "string" or raw == "" then return nil, "unreadable" end
  local ok, data = pcall(JSON.decode, raw)
  if not ok or type(data) ~= "table" or type(data.files) ~= "table" then
    return nil, "unreadable"
  end
  if type(data.version) ~= "string" or data.version == "" then
    return nil, "no version"
  end
  local names, seen = {}, {}
  for _, entry in ipairs(data.files) do
    if type(entry) ~= "table" or type(entry.name) ~= "string"
        or type(entry.sha256) ~= "string" then
      return nil, "an entry is not a file"
    end
    if entry.name == Updater.PARKED_MANIFEST_NAME then
      return nil, "an entry claims the manifest's own name"
    end
    if not Updater.is_safe_filename(entry.name) then
      return nil, "unsafe name"
    end
    if seen[entry.name] then return nil, "a name is listed twice" end
    seen[entry.name] = true
    names[#names + 1] = entry.name
  end
  if #names == 0 then return nil, "no files" end
  return names
end

-- Is what is parked the release this body is running?
--
-- Decided by the manifest BYTES, in both directions. A parked copy of a newer
-- release is as stale as a parked copy of an older one: what the launcher
-- restores has to be the thing that is running here, and "newer" is not a
-- reason to keep a copy of something this install is not. The listed files are
-- asked for by existence only, which costs one probe each and catches a copy
-- somebody has been into; their bytes are the launcher's question, asked with a
-- hash at the moment it uses them.
function Updater.park_current(raw, names)
  if Updater.park_read(Updater.parked_manifest_path()) ~= raw then return false end
  local root = Updater.parked_root()
  for _, name in ipairs(names) do
    if not RA.path_present(Updater.name_under(root, name)) then return false end
  end
  return true
end

-- Every directory this pass could act under, outermost first, absolute, with
-- no name repeated. The Recovery root and the parked root come first because
-- they are the two this lane creates and writes into whatever the manifest
-- says, and after them come the ancestors each manifest name hangs from.
--
-- Names only, no listing: the directories are derived from the manifest the
-- same way the destinations are, so this walk can never be pointed at a folder
-- the destinations do not reach.
function Updater.park_dirs(names)
  local dirs, seen = {}, {}
  local function add(path)
    path = tostring(path or ""):gsub("[/\\]+$", "")
    if path == "" or seen[path] then return end
    seen[path] = true
    dirs[#dirs + 1] = path
  end
  add(RA.RECOVERY_DIR)
  local root = Updater.parked_root()
  add(root)
  for _, name in ipairs(names) do
    local walked = ""
    for part in tostring(name):gmatch("([^/]+)/") do
      walked = (walked == "") and part or (walked .. "/" .. part)
      add(Updater.name_under(root, walked))
    end
  end
  return dirs
end

-- THE CONTAINMENT QUESTION, ASKED OF THE DISK RATHER THAN OF THE STRING.
--
-- Round 81's blocker: a prefix test proves a name is spelled inside the package
-- and says nothing about where that name LEADS. A junction or a symbolic link
-- at Recovery, at Recovery/Body, or at any directory under it satisfies every
-- string test there is, and the removal and the writes that follow land
-- wherever it points. So the question is asked of the filesystem, through the
-- same probe and the same classification the legacy-cleanup lane uses, and
-- every uncertain answer refuses.
--
-- Returns true, or false plus the directory that answered and why.
function Updater.park_chain_ok(dirs)
  for _, path in ipairs(dirs) do
    local why = Updater.chain_refusal(path)
    if why then return false, path, why end
  end
  return true
end

-- PUT ONE FILE IN PLACE WITHOUT EVER OPENING THE NAME SOMEBODY COULD PREDICT.
--
-- Round 82's blocker: removing a destination and then opening that same name
-- for writing leaves a window, and a file symlink planted inside it is
-- FOLLOWED, so an arbitrary file anywhere on the machine could be truncated.
-- The window is unclosable with Lua's primitives, so the fix is to stop
-- putting an openable name in it: the bytes are written to a PRIVATE name
-- nobody can precompute and that name is then RENAMED onto the destination.
--
-- WHY THAT IS SAFE, AND IT IS MEASURED RATHER THAN ASSUMED. Measured on this
-- machine with the shipped Lua 5.4: os.rename onto a name that already exists
-- fails with EEXIST, whatever is standing there. A regular file, a directory
-- and a directory junction all refuse it, and the junction's target was
-- untouched. So on Windows a link planted in the window makes the rename FAIL,
-- which is a refusal this lane already knows how to handle, and never a write
-- through the link. File symlinks could not be created on this machine to
-- measure directly (Windows asks for administrator rights and Developer Mode
-- is off), so that case rests on the measured rule that ANY existing name
-- refuses, plus the junction, which is a reparse point at a name exactly as a
-- symlink is. On POSIX the answer is the other safe one and was MEASURED on
-- the MacBook (2026-08-16) at both the rename(2) and Lua os.rename layers:
-- rename() replaces the destination DIRECTORY ENTRY, so a symlink standing at
-- the name is replaced rather than followed, for file, directory and dangling
-- targets alike, and what it pointed at is untouched in every case. Refusal on
-- one platform, link-replacement on the other, and a write through the link on
-- neither.
--
-- The private name comes from B2.4's own minter rather than a second one: it
-- is short by design, it is proven free before this pass touches anything, and
-- its per-name component comes from the operating system's entropy source where
-- there is one.
--
-- WHAT IS LEFT, corrected in round 90 to say what the acceptance sheet says.
-- The name is UNPREDICTABLE, not invisible: it does not exist on disk until the
-- write creates it, and from that moment an actor reading the folder can see
-- it. So the windows are the two after creation, between the write and the
-- readback and between the readback and the rename, and they are measured, not
-- reasoned about. Occupying the name BEFORE it exists takes knowledge of this
-- process's memory, which no sheet here defends against and none pretends to.
-- The sheet carries all of it, including the one adversary no check in this
-- runtime can answer: a hard link at the name, to a byte-identical file, which
-- passes every question asked below and is the same class B2.4 accepted as its
-- own P45 item.
--
-- Returns nil, or the reason this file did not get into place.
function Updater.park_place(dest, data, staging)
  if type(staging) ~= "string" or staging == "" then
    return "had no private name prepared for it"
  end
  -- FOLDER WHERE A FILE BELONGS, ASKED BEFORE THE REMOVAL (Codex round 83).
  -- The two platforms do not agree about what removing a directory means: on
  -- POSIX os.remove IS rmdir and takes an EMPTY one, which B2.4 measured, while
  -- Windows refuses a directory outright. A lane that removed first would
  -- therefore delete somebody's folder on one platform and refuse on the other,
  -- for the same disk. A folder standing where a file belongs is an anomalous
  -- state whatever put it there, a stopped uninstall or somebody deliberate, so
  -- it is refused on both platforms instead, and the refusal costs one
  -- abandoned pass with the parked copy exactly as it was. This is the mirror
  -- of the question chain_refusal asks about the folders on the way down.
  if RA.path_present(dest) and not Updater.uninstall_name_is_file(dest) then
    return "has a folder standing at its name"
  end
  -- The destination goes FIRST, because a rename onto an existing name refuses
  -- on Windows and that is the ordinary case: the previous parked file is
  -- standing there. What is removed is a name, and a link at that name is
  -- taken rather than followed.
  os.remove(dest)
  -- THE NAME WAS PROVEN FREE IN THE PRE-FLIGHT AND IS ASKED ABOUT ONCE MORE
  -- HERE, and this is a question rather than a search: nothing is minted, no
  -- entropy is read, and no other candidate is tried.
  --
  -- WHO CAN HAVE TAKEN IT, corrected in round 90 to match the acceptance
  -- sheet: nothing has been written at this name yet, so nothing on disk names
  -- it, and an actor reading the folder cannot have found it. Occupying it
  -- therefore takes knowledge of this process's own memory, which is outside
  -- the threat model the sheet carries and is bounded there rather than
  -- defended here.
  --
  -- Skipping the file is not available whoever did it: the manifest lists every
  -- file, so a copy missing one is a copy no launcher may adopt. The pass
  -- abandons instead, leaving files with no manifest, which is the state an
  -- interruption already leaves. The next session repairs it if it gets the
  -- chance, which is the expected case rather than a guaranteed one; until some
  -- pass publishes again there is no offline restore and the launcher's network
  -- lane covers it.
  if RA.path_present(staging) then
    return "had its private name taken before it could be used"
  end
  local wrote, werr = Updater.park_write(staging, data)
  if not wrote then
    os.remove(staging)
    return "could not be written: " .. tostring(werr)
  end
  -- Read back at the name this pass created, before it becomes the destination.
  --
  -- ONCE THAT FILE EXISTS THE NAME IS NO LONGER PRIVATE, corrected in round 90:
  -- an actor reading the folder sees it appear, which is exactly when a listing
  -- actor learns it. This readback is what meets a swap made in the moment
  -- after the write, and it compares BYTES, so it answers for content and not
  -- for what kind of thing is standing there. The question below asks that.
  if Updater.park_read(staging) ~= data then
    os.remove(staging)
    return "did not read back as it was written"
  end
  -- AND WHAT KIND OF THING IS STANDING THERE, asked immediately before the
  -- rename (Codex round 89).
  --
  -- The readback compares BYTES, so a symbolic link whose target happens to
  -- hold exactly these bytes passes it, and the rename would then move the LINK
  -- into the parked copy. That copy would still restore and still hash, because
  -- the launcher reads through the link when it fills its candidate, so nothing
  -- downstream would ever notice. What would be lost is the property the parked
  -- copy exists for: independent durability. A parked entry that is a link
  -- depends on somebody else's file staying where it is and staying unchanged.
  --
  -- So the kind is asked before the rename, through the same probes the
  -- ancestor walk uses, at a name only an actor who has already found it can
  -- reach. What those questions establish is what was standing at the name WHEN
  -- EACH WAS ASKED, which is not the same as what the rename will move; the two
  -- blocks below say which questions they are, what the intervals between them
  -- cost, and where the recovery lives.
  --
  -- The staging name is NOT removed on this road. What stands there is no
  -- longer what this pass wrote, and removing a name on an answer this pass
  -- could not read would be acting on something it cannot account for.
  --
  -- TWO QUESTIONS, NOT ONE (Codex round 90). The link probe answers "not a
  -- link" for every ordinary entry INCLUDING A DIRECTORY, so it alone does not
  -- say a plain file is standing there, and a directory substituted here would
  -- otherwise be renamed onto the destination. The file-or-folder probe is
  -- asked as well, and only not-a-link AND is-a-file answers yes. Everything
  -- else refuses, including the answer that cannot tell.
  --
  -- THEY ARE SEQUENTIAL, AND THAT IS NOT A DETAIL (Codex round 91). The link
  -- probe launches an external process and the file probe opens the name after
  -- it returns, so there is a real interval between them and another between
  -- the second answer and the rename. What these questions establish is
  -- therefore what was standing there WHEN EACH WAS ASKED, not what the rename
  -- will move. Both intervals are measured in Dev/Tests/test_parked_copy.lua
  -- and carried on the acceptance sheet: a symlink arriving after the first
  -- answer is opened through by the second and reaches the rename as a link, and
  -- a directory arriving after the second answer reaches the rename as a
  -- directory. Adding a third question would only add a third interval; what
  -- answers for the bytes at the moment they are used is the launcher's own
  -- hash, which is where the sheet puts the recovery.
  local kind = Updater.path_link_kind(staging)
  if kind ~= false or not Updater.uninstall_name_is_file(staging) then
    return "was not a plain file when it was about to be moved into place"
  end
  if not os.rename(staging, dest) then
    os.remove(staging)
    return "could not be moved into place"
  end
  return nil
end

-- The authoritative gate. Read under the lock, by park_run, inside the same
-- protected call as the work, and every answer is a refusal rather than a
-- guess. The third return says whether the refusal is settled for this session
-- or worth asking again a little later.
function Updater.park_ready()
  if RA.PACKAGE_DIR == RA.APP_DIR then return false, "flat layout", true end
  -- The root this lane writes into is DERIVED, and everything else here trusts
  -- it. A body whose Recovery root is empty or is not under the package root
  -- would have this lane writing somewhere nobody named, so the containment is
  -- proven rather than assumed, once, in front of every write.
  local root = tostring(RA.RECOVERY_DIR or "")
  local pkg = tostring(RA.PACKAGE_DIR or "")
  if root == "" or pkg == "" or root:sub(1, #pkg) ~= pkg or #root <= #pkg then
    return false, "the recovery folder is not under the package root", true
  end
  -- An uninstall in THIS instance, or one that has already finished here.
  -- Parking behind an uninstall would put back the one thing whose absence the
  -- uninstaller stops the whole run to guarantee.
  if Updater.uninstall_barrier() then
    return false, "an uninstall has run in this session", true
  end
  -- And an uninstall in another REAPER window, which cannot be seen any other
  -- way. Its marker goes down before its gate finishes, and either phase of it
  -- means this install is being taken away.
  if Updater.uninstall_marker_phase() then
    return false, "an uninstall marker is standing", true
  end
  if Updater.is_busy() or update.state ~= "idle" then
    return false, "the updater is busy"
  end
  -- A launcher claim is the one writer of App/ the apply lock does not exclude:
  -- the launcher takes a lock of its own, in Recovery/, and restores into the
  -- tree this lane copies FROM.
  if Updater.uninstall_launcher_lock_path() then
    return false, "a launcher claim is standing"
  end
  if Updater.journal_quarantined() then
    return false, "a quarantine record is standing", true
  end
  if #Updater.journal_paths_live() > 0 then
    return false, "an update record is at a journal path"
  end
  return true
end

-- Bring the parked copy up to the running body. Returns nil plus the number of
-- files copied, or the reason it stopped. Every stop leaves the parked manifest
-- absent or untouched, never standing over files it does not describe.
function Updater.park_refresh()
  local source_manifest =
    Updater.local_path_for(tostring(CFG.UPDATE_MANIFEST or ""))
  local raw = Updater.park_read(source_manifest)
  if not raw then return "the body manifest could not be read" end
  local names, why = Updater.park_names(raw)
  if not names then
    return "the body manifest cannot be parked: " .. tostring(why)
  end
  if Updater.park_current(raw, names) then return nil, 0 end
  -- Rule 1. Asked of every name before anything is cleared or written, and
  -- asked by READING rather than by looking.
  --
  -- Round 81's should-fix, taken as a fix: presence is not readability, and the
  -- step after this one removes the manifest that vouches for a parked copy
  -- that may be the only offline recovery this install has. A file that is
  -- there and cannot be opened would have been discovered halfway through the
  -- copy, with that manifest already gone, so one unreadable source would have
  -- cost a working parked copy. UNREADABLE IS DAMAGED, and a damaged body takes
  -- the same road as a missing one: leave what is parked exactly where it is.
  --
  -- AND THE BYTES ARE KEPT (round 82's should-fix). Reading here and reading
  -- again in the copy would leave a gap between the two reads, and a source
  -- that turned unreadable inside it would be discovered with the parked
  -- manifest already gone, which is the very loss this pre-flight exists to
  -- prevent. So every file is read exactly ONCE, before anything is cleared,
  -- and the copy below writes what is in hand. Nothing is read out of the body
  -- after the invalidate at all.
  --
  -- The cost is memory rather than time, it is paid only by a pass that was
  -- going to copy the whole tree anyway, and it is the release's own size:
  -- roughly 8.4 MB held for the length of the pass at the current release,
  -- released with the table when the pass ends.
  local bytes = {}
  for _, name in ipairs(names) do
    local source = Updater.local_path_for(name)
    if not RA.path_present(source) then
      return "the body is missing " .. name
        .. ", so the parked copy was left as it was"
    end
    local data = Updater.park_read(source)
    if not data then
      return "the body's " .. name .. " could not be read, so the parked copy "
        .. "was left as it was"
    end
    bytes[name] = data
  end
  -- EVERY STAGING NAME, MINTED AND PROVEN FREE, BEFORE ANYTHING IS CLEARED
  -- (Codex round 87).
  --
  -- Round 86 moved the entropy here and carried words. That was not enough: a
  -- name costs one word only when the first candidate is free, and each name
  -- may probe up to sixty-four candidates, so a run of collisions could empty
  -- the carried words AFTER the invalidate and land the pass in the loss the
  -- pre-flight exists to prevent. Raising the allowance moves that failure
  -- rather than removing it.
  --
  -- So the names are RESOLVED here, not just the material for them: each one is
  -- minted and probed free in the folder it will be used in, re-minting on
  -- collision, with the entropy source available and a refusal costing nothing
  -- because nothing has been touched yet. What the pass carries afterwards is a
  -- list of names it has already proven. After the invalidate it mints nothing,
  -- reads no entropy, and searches for no name.
  --
  -- The order is the use order: one per file the manifest lists, then one for
  -- the manifest itself.
  local root = Updater.parked_root()
  local manifest_dest = Updater.parked_manifest_path()
  local staged = {}
  for i = 1, #names + 1 do
    local dest = (i <= #names) and Updater.name_under(root, names[i])
      or manifest_dest
    local parent = tostring(dest):match("^(.*)[/\\][^/\\]+$")
    if not parent then
      return "the parked copy has no folder for " .. tostring(dest)
    end
    local name, mint_why = Updater.uninstall_claim_name(parent)
    if not name then
      return "no private name could be prepared on this system ("
        .. tostring(mint_why) .. "), so the parked copy was left as it was"
    end
    staged[i] = name
  end
  -- Rule 2a. The first of the two on-disk containment walks, before the first
  -- mutation. A refusal here costs nothing, because nothing has been taken yet
  -- and the parked copy is still whole.
  local dirs = Updater.park_dirs(names)
  local chain_ok, offender, chain_why = Updater.park_chain_ok(dirs)
  if not chain_ok then
    return "the folder " .. tostring(offender) .. " is "
      .. tostring(chain_why) .. ", so nothing was copied"
  end
  if type(reaper.RecursiveCreateDirectory) == "function" then
    pcall(reaper.RecursiveCreateDirectory, (root:gsub("[/\\]+$", "")), 0)
  end
  -- Rule 2b. Nothing is copied until the old manifest is proven gone, and the
  -- same kind question park_place asks is asked here first, for the same
  -- reason: this removal would take an EMPTY directory on POSIX and refuse on
  -- Windows, and a folder standing at the manifest's name is not this lane's
  -- to delete on either.
  if RA.path_present(manifest_dest)
      and not Updater.uninstall_name_is_file(manifest_dest) then
    return "a folder is standing at the parked manifest's name, so nothing "
      .. "was copied"
  end
  os.remove(manifest_dest)
  if RA.path_present(manifest_dest) then
    return "the parked manifest could not be cleared, so nothing was copied"
  end
  local copied = 0
  for i, name in ipairs(names) do
    local dest = Updater.name_under(root, name)
    local parent = dest:match("^(.*)[/\\][^/\\]+$")
    if parent and type(reaper.RecursiveCreateDirectory) == "function" then
      pcall(reaper.RecursiveCreateDirectory, parent, 0)
    end
    local failed = Updater.park_place(dest, bytes[name], staged[i])
    if failed then return "the copy of " .. name .. " " .. failed end
    copied = copied + 1
  end
  -- TWO MUTABLE FACTS, RE-ASKED IN FRONT OF THE PUBLISH RATHER THAN ONCE AT THE
  -- GATE. The apply lock keeps this body's update pipeline out for the whole
  -- pass, and it is the only exclusion there is: the launcher takes a lock of
  -- its OWN, in Recovery/, and a launcher rolling a pending journal forward
  -- writes into the very tree this pass is reading. The gate asked whether a
  -- claim was standing, and a claim taken a moment after that answer is a
  -- writer this pass never saw. So both are asked again here, at the last
  -- instant this pass can still decide not to publish.
  --
  -- The manifest question is the one that reads the TREE rather than a claim
  -- about it. The claim question is the one that can see a writer whose changes
  -- have not reached the manifest yet, because the launcher lands the manifest
  -- last exactly as this lane does. Neither subsumes the other, and publishing
  -- a manifest for a tree that moved underneath it is the one failure this lane
  -- could not detect afterwards.
  --
  -- WHAT IS LEFT, stated rather than claimed away: a claim taken and given back
  -- entirely inside this pass answers no to both questions. What that produces
  -- is a parked copy mixing two releases under one manifest, which the
  -- launcher's own hashing refuses at the moment of use, so the cost is an
  -- offline restore rather than a restore of something nobody verified.
  if Updater.park_read(source_manifest) ~= raw then
    return "the body changed while it was being copied, so nothing was published"
  end
  if Updater.uninstall_launcher_lock_path() then
    return "a launcher claimed this install while the copy was running, "
      .. "so nothing was published"
  end
  -- And the containment walk again, immediately in front of the publish, which
  -- is the second moment this pass mutates anything.
  --
  -- WHAT THE TWO WALKS CLOSE AND WHAT THEY DO NOT, stated rather than claimed
  -- away, the way the legacy lane states its own. Each walk is an answer about
  -- the disk at the moment it is taken, and the act it guards is not the next
  -- instruction: between the first walk and the last file written lie the
  -- directory creation, the manifest removal and the whole copy, and between
  -- this walk and the rename lie the staging write and its readback. Lua has no
  -- open-then-act handle, so the window does not close.
  --
  -- ITS CEILING is what somebody who wins that race can make this pass do: the
  -- removal of one file named manifest.json inside whatever a swapped-in link
  -- points at, the creation there of the directories the manifest names and of
  -- the files it names, and one rename into the same place. It cannot delete
  -- anything else, because the only names this lane removes are the manifest,
  -- its staging sibling and destinations it is about to write; it cannot
  -- descend, because it never lists a directory; and it cannot be steered by
  -- the tree it copies, because every name comes from a manifest each name was
  -- validated against before any of this ran.
  local publish_ok, publish_offender, publish_why = Updater.park_chain_ok(dirs)
  if not publish_ok then
    return "the folder " .. tostring(publish_offender) .. " is "
      .. tostring(publish_why) .. ", so nothing was published"
  end
  -- Rule 3. The manifest goes in last and by the same road, which is the road
  -- round 82 required: it used to be staged at `manifest.json.tmp`, a name
  -- anybody could write down in advance, and that name was opened for writing.
  -- Now it is staged at a private one and renamed, exactly like every file it
  -- describes.
  --
  -- Nothing reads the published name afterwards. The bytes were verified where
  -- only this pass could name them and the rename is the evidence they became
  -- the destination; a re-read of the published name would prove less and would
  -- put a predictable name back in this lane's hands.
  local failed = Updater.park_place(manifest_dest, raw, staged[#names + 1])
  if failed then return "the parked manifest " .. failed end
  return nil, copied
end

-- One pass, one acquisition, one release.
--
-- THE CROSS-PROCESS LOCK COMES FIRST, after two same-process actors are refused
-- before acquisition. `acquire_apply_lock` deliberately adopts a lock that
-- already names this instance. That is useful for a recovery continuation, but
-- it means a parked-copy turn must not call it while this process's updater or
-- uninstaller owns the lock: the parked-copy refusal would release the adopted
-- acquisition and revoke the live actor's authority. Lua callbacks do not
-- preempt one another, and neither refusal below yields, so those same-process
-- facts cannot change before the acquisition. The full gate is still repeated
-- inside the protected call, where cross-process and persistent state belong.
-- Nothing else stands between the acquisition and the pcall, so there is one
-- exit path and it always releases.
--
-- Returns whether the pass RAN, the reason it did not or the reason it stopped,
-- and whether the answer is settled for this session.
function Updater.park_run()
  if RA.PACKAGE_DIR == RA.APP_DIR then
    Log.line("UPDATE", "parked copy: skipped; flat layout")
    return false, "flat layout", true
  end
  if Updater.uninstall_barrier() then
    Log.line("UPDATE", "parked copy: skipped; an uninstall has run in this session")
    return false, "an uninstall has run in this session", true
  end
  if Updater.is_busy() or update.state ~= "idle" then
    Log.line("UPDATE", "parked copy: skipped; the updater is busy")
    return false, "the updater is busy", false
  end
  if not Updater.acquire_apply_lock() then
    Log.line("UPDATE", "parked copy: skipped; the apply lock is held")
    return false, "apply lock held", false
  end
  local ok_run, why, copied, settled, gated = pcall(function()
    local ready, gate_why, gate_settled = Updater.park_ready()
    if not ready then
      Log.line("UPDATE", "parked copy: skipped; " .. tostring(gate_why))
      return gate_why, nil, gate_settled == true, true
    end
    local stopped, count = Updater.park_refresh()
    return stopped, count, true, false
  end)
  Updater.release_apply_lock()
  if not ok_run then
    Log.line("UPDATE", "parked copy: raised; " .. tostring(why))
    return false, "raised", true
  end
  if gated then return false, why, settled end
  if why then
    Log.line("UPDATE", "parked copy: stopped; " .. tostring(why))
    return true, why, true
  end
  if (copied or 0) == 0 then
    Log.line("UPDATE", "parked copy: already current")
  else
    Log.line("UPDATE", string.format(
      "parked copy: refreshed; %d files copied", copied))
  end
  return true, nil, true
end

-- How often the pass is offered, and how many times.
--
-- A ONE-SHOT WOULD NOT SURVIVE THE STARTUP UPDATE CHECK. The automatic check
-- fires as the session opens and can hold the updater busy for tens of seconds,
-- and a pass that took its single turn inside that window would be refused and
-- never asked again, on every session, for every user who has update checks on.
-- So a transient refusal is asked again, a settled one is not, and the number
-- of turns is bounded so a permanently busy install cannot turn this into a
-- per-frame probe.
Updater.PARK_FIRST_DELAY = 5.0
Updater.PARK_RETRY_DELAY = 30.0
Updater.PARK_MAX_TRIES = 4

-- The one entry point both session loops call. The visual loop and the Screen
-- Reader loop are separate frames on separate files, and a park wired into only
-- one of them would leave the users least able to repair an install by hand
-- with no offline restore at all.
function Updater.park_dispatch()
  if update._park_settled then return end
  local now = time_precise()
  if not update._park_next then
    update._park_next = now + Updater.PARK_FIRST_DELAY
    return
  end
  if now < update._park_next then return end
  update._park_next = now + Updater.PARK_RETRY_DELAY
  update._park_tries = (update._park_tries or 0) + 1
  -- Counted BEFORE the call, so a raise cannot spend a turn without paying for
  -- it and a bounded retry cannot become a loop.
  if update._park_tries >= Updater.PARK_MAX_TRIES then
    update._park_settled = true
  end
  local ok, ran, _, settled = pcall(Updater.park_run)
  if not ok then
    Log.line("UPDATE", "parked copy: raised; " .. tostring(ran))
    update._park_settled = true
    return
  end
  if ran or settled then update._park_settled = true end
end

-- The directories ReaAssist itself installs under App/, relative to it,
-- lowercased and spelled with forward slashes.
--
-- This is the walker's descent list for the application tree, and it is read
-- out of the body's own manifest rather than written down here, so a release
-- that adds a folder is covered by shipping its manifest. `Resources` is the
-- floor for a manifest that cannot be read at all, which is a real state: the
-- launcher's own FALLBACK_CRITICAL exists for exactly that install.
--
-- Anything not in this set is left where it is, with everything in it, and
-- named in the report. THE REASON FOR IT IS OWNERSHIP RATHER THAN
-- CONTAINMENT, and round 49 is why that distinction is spelled out here: the
-- claim and the pin contain the walk whether or not a name is in this set, so
-- the shape adds no safety against a link any more. What it still answers is a
-- different question, WHOSE files these are, and the answer to that one should
-- not be "everything anybody ever put under App/". It is kept for that, and
-- for that alone.
--
-- Returns the shape plus whether the manifest really answered. A manifest that
-- could not be read leaves the shape at its floor, which means a deeper folder
-- this release does install is left behind and named; the confirmation copy
-- says so before the user commits, because the alternative is walking into
-- folders on no evidence at all.
function Updater.uninstall_app_shape()
  local shape = { ["resources"] = true }
  local manifest = Updater.local_manifest_read()
  local files = type(manifest) == "table" and manifest.files or nil
  if type(files) ~= "table" then return shape, false end
  for _, entry in ipairs(files) do
    local name = type(entry) == "table" and tostring(entry.name or "") or ""
    name = name:gsub("\\", "/")
    local parts = {}
    for part in name:gmatch("([^/]+)") do parts[#parts + 1] = part end
    -- The last element is the file, so every element before it is a folder
    -- this release installs into.
    local prefix = nil
    for i = 1, #parts - 1 do
      prefix = prefix and (prefix .. "/" .. parts[i]:lower()) or parts[i]:lower()
      shape[prefix] = true
    end
  end
  return shape, true
end

-- MAKING A NAME THIS RUN'S OWN BEFORE ANYTHING DESTRUCTIVE HAPPENS TO IT.
--
-- Round 49's second finding, stated plainly: proving something about a PATH
-- and then acting on that same path afterwards is check-then-act however good
-- the proof was. The walker used to probe a directory, then enumerate it, then
-- delete through it, and each of those was a separate look at a name somebody
-- else could change in between.
--
-- The answer is this arc's own idiom, which is to take the name out of
-- everybody else's reach FIRST and then work. There are two ways to do that
-- here, and the second exists because the platform will not always give the
-- first.
--
-- THE CLAIM. Rename the directory to a name only this run has spelled, inside
-- the same parent. Everything after that acts on a name nothing else has ever
-- seen: the link-or-real probe, the listing, the per-file removal, the descent
-- into each child, and the final removal of the directory itself.
--
-- AND A PRIVATE NAME IS NOT AN EXCLUSIVE ONE, WHICH IS ROUND 50'S FIRST
-- FINDING. A minted name appears in an ordinary directory listing the moment it
-- exists, so anybody watching the parent can read it, rename the folder out
-- from under it and leave a link at the name this run is about to enumerate and
-- empty. Secrecy is not a mechanism. What follows is.
--
-- THE PIN ON THE CLAIM, WHICH IS THE MECHANISM. Windows refuses to rename or
-- remove a directory while any file anywhere inside it is open, for every
-- process at once, and this arc already measured that and already relies on it
-- (the life file under Data/ is why a claim of that folder is refused at all).
-- So the claim is pinned by a file INSIDE it, held open from the instant the
-- rename lands until the last thing that reads or empties the folder is done.
-- While that handle is open the claimed folder cannot be renamed away by
-- anybody and its name cannot be swapped for a link.
--
-- THE SEED, WHICH IS WHAT MAKES THE PIN PROVABLE. Lua's io can open a file, and
-- it cannot open a directory, so the pin needs a file inside the folder before
-- the folder can be pinned, and reading the folder to find one would be another
-- look at a name nobody owns yet. So this run writes its own: one file, at a
-- name minted from the same counter as the claim, carrying a value that existed
-- nowhere until it was written. It is planted BEFORE the rename, through the
-- folder's own name, and opened AFTER the rename, through the private one.
--
-- Then the pin and the identity are one act rather than two. The open both
-- pins whatever is at the private name and hands back the only evidence that
-- says whether that thing is what this run moved there: the seed's own value,
-- read out of the pinned file. A folder swapped in between the rename and the
-- open does not carry it, so the claim is refused and nothing is walked. A
-- folder that does carry it is the one that was renamed, and from that instant
-- the platform is holding it still.
--
-- WHAT IS LEFT, NAMED RATHER THAN CLAIMED CLOSED. Two things.
--   * The instant between the rename and the open. The seed answers it, in the
--     sense that anything else standing there fails the proof and stops the
--     walk; what it cannot answer is an actor that READ this run's seed out of
--     the folder before the rename and staged a folder carrying the same value.
--     That is a different adversary from the one this lane defends against.
--   * POSIX. An open handle pins nothing there, so the claim is private and
--     proven rather than exclusive. The rest of the POSIX story is milder for
--     the same reasons it always was: rename(2) never follows a symbolic link,
--     so the claim itself cannot carry a stranger's folder off, and rule one
--     takes a link at the public name before the claim is attempted.
--
-- AND THE PLATFORM DETAIL THAT DECIDES ITS SHAPE, WHICH WAS MEASURED RATHER
-- THAN ASSUMED. On POSIX, rename(2) acts on a symbolic link itself. ON WINDOWS
-- IT DOES NOT. MoveFile FOLLOWS a junction, so renaming a junction renames THE
-- FOLDER IT POINTS AT, out of its own parent, and leaves the junction standing
-- where it was. A claim that met a junction would therefore drag a stranger's
-- folder into this install under a private name and then empty it, which is
-- worse than following the link. Two things answer that. Rule one is asked
-- FIRST, and a non-recursive rmdir takes a junction itself, so an ordinary
-- link never reaches the rename. And the claim is CHECKED: a rename that
-- followed a link leaves the old name standing, because the junction is still
-- there, so a public name that survives its own rename is proof that the
-- rename took something else. That is a BREACH, and it stops the whole run
-- with nothing further removed rather than deleting anything.
--
-- THE PIN. On Windows the claim is refused outright while any file anywhere
-- inside the directory is open, and this run always holds one: the life file
-- that proves this instance is alive lives under Data/ and is deliberately
-- never closed. So a claim that is refused is answered by taking a handle on
-- one of the directory's OWN files and holding it for the length of the walk.
-- That is the same trick the launcher's lock uses, and Windows enforces it for
-- everybody: while a handle is open inside it, the directory cannot be renamed
-- or removed by this process or by any other, so its name cannot be swapped
-- for a link. Rule one is then asked once more, because a junction that had
-- arrived would still be a junction and its own removal is not blocked by a
-- handle in its target; a name that goes there was a link, and nothing inside
-- it was ever touched.
--
-- THE PIN IS WINDOWS ONLY. An open handle pins nothing on POSIX, where a
-- directory full of open files renames and unlinks freely, and where the claim
-- consequently never fails for that reason in the first place.
--
-- A DIRECTORY THAT IS NEITHER CLAIMED NOR PINNED IS NOT WALKED. It is left
-- where it is with everything in it, and named in the report. That is why a
-- folder whose every file is locked open by something else now survives whole
-- rather than losing the files around the locked one.
--
-- RULE ONE ITSELF IS STILL ASKED ON THE PUBLIC NAME, and that is not an
-- exception to any of this. A non-recursive rmdir cannot destroy the contents
-- of anything: it takes a link itself, or an empty directory, and refuses
-- everything else. It is the one act that is safe to aim at a name this run
-- has not taken.

-- One tag per run, and a counter under it, so no two claims can collide and a
-- name left behind by a run that died is never mistaken for one of this run's.
-- EIGHT HEX CHARACTERS FOR THE PER-NAME TAIL, from the best source each
-- platform actually offers, MEASURED rather than hoped for (Codex round 84).
--
-- On POSIX `/dev/urandom` is the operating system's own source and is read
-- directly, four bytes per name. That half was MEASURED on the MacBook
-- (2026-08-16): the device answered 1000 of 1000 full four-byte reads at both
-- the fread(3) and Lua io layers, and the acceptance sheet carries the
-- MEASURED marker.
--
-- On Windows there is no file-shaped source: `/dev/urandom` and `/dev/random`
-- do not open, measured with the shipped Lua this round. Two things were
-- considered to stand in for it and only one survived measurement. `os.clock`
-- did not: it is ONE MILLISECOND granular here, eleven distinct values across
-- two hundred thousand calls, and eight consecutive mints produced the
-- identical microsecond word, so mixing it would add nothing while implying it
-- had. The address of a fresh table did: two taken in one process differed
-- widely. That is ALLOCATOR STATE, not entropy, it is not claimed to defeat
-- anything, and what it buys is that recovering the random generator's state
-- alone does not hand an attacker the name.
--
-- Either way the answer is exactly eight hex characters, because the validator
-- above knows one current shape and not a family of them.
--
-- AND ON POSIX IT FAILS CLOSED (Codex round 85, ruled by the orchestrator). The
-- fallback used to run there too, so a device that would not open, or read
-- short, or raise, quietly turned the platform's real source into the
-- deterministic one while the acceptance sheet said otherwise. A sheet that is
-- true only when a device works is not true. So on POSIX this returns NOTHING
-- rather than something weaker, the pass abandons with the parked copy exactly
-- as it was, and the install degrades to the network lane until the device is
-- fixed. That is the same refusal-over-guessing this whole lane is built on.
function Updater.claim_random_word()
  if RA.IS_WINDOWS then
    local addr = tostring({}):match("(%x%x%x%x)$") or "0000"
    return string.format("%04x", math.random(0, 65535)) .. addr
  end
  local f = io.open("/dev/urandom", "rb")
  if not f then
    return nil, "the system entropy source could not be opened"
  end
  local ok, data = pcall(f.read, f, 4)
  pcall(f.close, f)
  if not ok or type(data) ~= "string" or #data ~= 4 then
    return nil, "the system entropy source returned nothing usable"
  end
  return (data:gsub(".", function(c)
    return string.format("%02x", c:byte())
  end))
end

-- STRENGTHENED IN B2.7c, and honestly: this is a UNIQUENESS token that is now
-- harder to guess, not a secret. Three random bytes instead of one, beside the
-- heap address, which costs four characters and buys a first guess nobody can
-- take. What it does not buy is invisibility: any name built from it is in the
-- directory while it is in use, so an actor who can list that directory learns
-- the token. The per-name component in uninstall_claim_name is what stops the
-- NEXT name from following from the last one.
function Updater.uninstall_claim_token()
  if not Updater._uninstall_claim_token then
    local addr = tostring({}):match("(%x%x%x%x)$") or "0000"
    Updater._uninstall_claim_token = string.format("%02x%02x%02x%s",
      math.random(0, 255), math.random(0, 255), math.random(0, 255),
      tostring(addr))
    Updater._uninstall_claim_seq = 0
  end
  return Updater._uninstall_claim_token
end

-- A free name beside `dir`, kept SHORT on purpose: every claim replaces a name
-- in the paths below it, and a long one would push a deep tree past what the
-- platform will accept.
--
-- The name is probed rather than assumed free. os.rename onto a name that is
-- already taken fails on Windows, and on POSIX it can succeed onto an empty
-- directory, which would be a silent merge.
-- `supplied`, when given, is a LIST OF PRE-MINTED WORDS this caller read before
-- it touched anything, and it is taken from rather than read from (Codex round
-- 86). The parked copy needs that: its whole discipline is that nothing is read
-- after the invalidate, and an entropy source that answered once in a pre-flight
-- can still fail later, which would stop a pass with the parked manifest
-- already gone. The uninstaller passes nothing and reads its own word per
-- attempt, which is right for a lane that runs once and mutates immediately.
-- One function, one shape, one freeness probe; only where the material comes
-- from differs.
function Updater.uninstall_claim_name(parent, supplied)
  Updater.uninstall_claim_token()
  -- THE COUNTER IS NO LONGER THE WHOLE TAIL (B2.7c, Codex round 83). A
  -- monotonic sequence makes every later name follow from any earlier one, so
  -- an actor who sees ONE of these names in the directory can write down the
  -- next and lie in wait at it. The sequence stays, because it keeps the
  -- retries below distinct, and a fresh random component is appended to it, so
  -- knowing one name says nothing about the next. It is still not a secret: a
  -- name in use is visible to anyone who can list the folder, and that
  -- remainder is stated in the plan rather than dressed up.
  for _ = 1, 64 do
    Updater._uninstall_claim_seq = (Updater._uninstall_claim_seq or 0) + 1
    -- No word, no name. The reason travels with the refusal so the caller can
    -- say which of the two happened: a system with no usable entropy source, or
    -- a folder where sixty-four private names were all taken.
    local word, why
    if supplied then
      word = table.remove(supplied, 1)
      if not word then
        return nil, "the private name material minted for this pass ran out"
      end
    else
      word, why = Updater.claim_random_word()
      if not word then return nil, why end
    end
    local name = parent .. RA.SEP .. "~ra" .. Updater._uninstall_claim_token
      .. "-" .. tostring(Updater._uninstall_claim_seq) .. "-" .. word
    if not RA.path_present(name) then return name end
  end
  return nil, "no private name was free beside that folder"
end

-- The value the seed carries. It exists nowhere until it is written into the
-- folder this run is about to claim, which is the whole of what it proves: the
-- folder standing at the private name afterwards is the folder that value was
-- written into. It is a freshness token and nothing stronger; it is not a
-- secret and this lane does not treat it as one.
function Updater.uninstall_claim_nonce()
  local bits = {}
  for _ = 1, 4 do
    bits[#bits + 1] = string.format("%04x", math.random(0, 65535))
  end
  return "ReaAssist claim " .. Updater.uninstall_claim_token() .. " "
    .. table.concat(bits) .. " " .. tostring(os.clock())
end

-- DID A REAL DIRECTORY HOLDING THIS RUN'S OWN OPEN FILE STAND AT THIS NAME?
--
-- This is the question a put-back is allowed to ask, and round 54's first
-- blocker is why it replaced the one B2.4f asked. That one read the file back
-- THROUGH the public name and called a match proof that the folder was there.
-- A name is not an object: after the rename lands, an actor can move the folder
-- somewhere of their own and put a junction at the folder's own name pointing
-- at it, and then the private name is free, the rename did happen, and the read
-- FOLLOWS the junction to the folder and matches. All three checks passed with
-- no knowledge of this run's value at all (P38).
--
-- SO THE READ IS TAKEN THROUGH A HANDLE AND THE HANDLE IS HELD WHILE THE NAME
-- IS ASKED ABOUT. A handle binds to the object, wherever that object later
-- sits, and holding it freezes the directory the file is in: that directory
-- cannot be renamed and cannot be removed while this side is holding one of its
-- files open (P41, P43). The measured removal is then asked AT THE NAME with
-- the handle still held, and it answers the two states apart:
--   * a JUNCTION at the name is TAKEN, exit 0, with everything it points at
--     whole and this side's handle still reading (P30). So "removed" here is
--     positive proof that the name was NOT the directory the handle is inside,
--     because that directory cannot be removed while the handle is open.
--   * a REAL directory holding this run's own open file REFUSES, exit 145, and
--     nothing is touched (P43, P31). That is the only answer this side acts on.
-- A name that has gone answers "gone" and is proof of nothing.
--
-- WHAT IT IS STILL NOT, SAID PLAINLY. It is an answer about one instant, not a
-- proof about the folder, and this side cannot make it into one: the rename is
-- refused while any handle inside the folder is open (P41), so the folder is
-- unpinned at the instant the rename lands and the handle can only be taken
-- back THROUGH a name. That one step is redirectable and no ordering of these
-- primitives removes it, which is why nothing here closes a record. What it
-- does is make the redirect SEEN rather than followed, so the run says what
-- really happened instead of reporting a restoration it cannot stand behind.
--
-- AND THE REFUSAL ALONE WAS NEVER EVIDENCE ABOUT THE FOLDER, which is round
-- 55's first blocker and the reason this function has two more questions in it
-- than B2.4g's did. A non-recursive removal refuses ANY directory holding
-- anything at all, so a folder carried away and replaced with a stranger's
-- non-empty directory answered exactly what an honest put-back answers; a
-- permission failure and a shell this side cannot reach answer it too. What
-- this asks now is the question the refusal was standing in for: IS THE NAME
-- THE DIRECTORY THIS SIDE'S OWN HANDLE IS INSIDE?
--
--   * THE VALUE IS READ THROUGH THE HANDLE, so it is a fact about the object
--     that handle opened rather than about anything a name reaches.
--   * A MARK IS APPENDED THROUGH THAT SAME HANDLE and then asked for BY NAME.
--     Only this descriptor can have put those bytes anywhere, so a name that
--     hands them back is a name reaching the object this side is holding
--     (P55: the append is visible by name, through a junction as well).
--   * THE MEASURED REMOVAL IS ASKED AT THE NAME while the handle is open, which
--     TAKES a junction and says so (P30, P42), refuses a real directory holding
--     this side's own open file (P43), and says a name that has gone is gone.
--   * AND ON WINDOWS, LAST, THE ONE ACT NOTHING CAN REDIRECT AFTERWARDS:
--     os.rename of the name ONTO ITSELF. It answers EACCES for a directory this
--     side is holding a file open inside and TRUE for an unpinned directory,
--     for a junction, and for a file (P46, P51, P56b). A junction cannot
--     survive it, so a refusal is the name being a real directory that a handle
--     is open inside, and this side is holding exactly one, opened through this
--     name.
--
-- AND A REFUSAL IS NOT A PIN, which is round 56's first blocker and the reason
-- that last act is asked THREE TIMES rather than once. B2.4h read every failure
-- but ENOENT as proof of this side's own handle, and the platform does not say
-- that: an ACL that denies this account the delete right and a lock ANOTHER
-- actor holds inside the folder both answer EACCES, code 13, with the same
-- message this side's own handle produces (P66, P67). NOTHING IN THE ANSWER
-- NAMES THE CAUSE, so the cause is established by CHANGING IT AND NOTHING ELSE:
--   * BEFORE this side opens anything, the name must answer FREE. An ACL denial
--     and a stranger's lock both refuse here (P66a, P67a), and the record is
--     kept and the state said in its own words.
--   * WITH this side's handle open, it must REFUSE (P64).
--   * AND AFTER this side lets go, it must answer FREE AGAIN (P64), so the
--     refusal in the middle is bracketed by two answers this side's own acts
--     are the only difference between.
-- A junction answers FREE at all three (P65), an absent name answers ENOENT at
-- the first, and an actor who wants the middle answer for their own reason has
-- to take a lock inside one window and let it go inside the next.
--
-- WHAT IT IS STILL NOT, SAID PLAINLY, AND IT IS TWO THINGS RATHER THAN ONE.
-- The rename is refused while any handle inside the folder is open (P41), so
-- the folder is unpinned at the instant a put-back's rename lands and the
-- handle can only be taken back THROUGH a name; if THAT name was a junction,
-- the handle is on a file in a folder somewhere else and every question below
-- is asked of a name the actor still owns. Two hands reach through that. An
-- actor who can name this run's own file and make a second directory entry for
-- it inside a folder of theirs has this side's own handle pinning THEIR folder,
-- and every question above answers for them (P57a, P58a: the pin follows the
-- entry the handle was opened through); that is the residual round 55 ruled a
-- sheet item of its own. And an actor who holds a file open inside a directory
-- they swap in behind the junction, in the window between this open and the
-- rename probe, is refused by the probe for their reason rather than this
-- side's (P58a). Neither is closed here and neither is claimed away.
--
-- `nonce` IS REQUIRED, and round 56's second blocker is why. B2.4h let a reader
-- with no run in memory pass nil and read the value for the SHAPE this
-- package's minting produces, and a shape is not a nonce: anything that can
-- list a folder can mint a file that answers it. There is no arm here that
-- accepts a likeness. A reader with no run in memory takes the value off the
-- record itself, which is what carries it now.
--
-- Returns true only when every question answered, and the word for what stopped
-- it otherwise: `gone` for a name that is not there, `removed` for a link this
-- question took, `foreign` for a name that refuses this side for a reason that
-- is not this side's own handle, `unproven` for a name with nothing of this
-- run's inside it, and `adrift` for one that stopped answering partway.
function Updater.uninstall_claim_bound(public, leaf, nonce)
  local dir = tostring(public or "")
  local want = tostring(nonce or "")
  if want == "" then return false, "unproven" end
  local path = dir .. RA.SEP .. tostring(leaf or "")
  -- THE NAME IS ASKED BEFORE THIS SIDE IS HOLDING ANYTHING, so that the refusal
  -- further down has something to be a change FROM. A name that already refuses
  -- can never be proven to refuse because of this side.
  if RA.IS_WINDOWS then
    local before = Updater.uninstall_claim_selfrename(dir)
    if before ~= "free" then
      return false, (before == "gone") and "gone" or "foreign"
    end
  end
  local held, seen
  pcall(function() held = io.open(path, "r+b") end)
  if held then pcall(function() seen = held:read("*a") end) end
  local carries = type(seen) == "string" and seen:sub(1, #want) == want
  if not held or not carries then
    if held then pcall(function() held:close() end) end
    return false, "unproven"
  end
  local _, kind = Updater.uninstall_remove_empty_dir_kind(dir)
  if kind ~= "refused" then
    pcall(function() held:close() end)
    return false, kind
  end
  -- THE BINDING QUESTIONS, asked last and together, because between them they
  -- are what makes "refused" a fact about this folder rather than about
  -- whatever is standing at this name. Removing any one of them puts the record
  -- back on the shape of a name.
  local mark = Updater.uninstall_claim_nonce()
  local byname
  local wrote = pcall(function()
    held:seek("end")
    held:write(mark)
    held:flush()
  end)
  if wrote then
    pcall(function()
      local f = io.open(path, "rb")
      if not f then return end
      byname = f:read("*a")
      f:close()
    end)
  end
  if not wrote or byname ~= seen .. mark then
    pcall(function() held:close() end)
    return false, "adrift"
  end
  if RA.IS_WINDOWS then
    local during = Updater.uninstall_claim_selfrename(dir)
    pcall(function() held:close() end)
    if during ~= "held" then return false, "adrift" end
    -- AND THE ANSWER HAS TO COME BACK when the one thing that changed goes
    -- away again. A refusal that outlives this side's own handle was never
    -- this side's, whatever it answered while the handle was open.
    local after = Updater.uninstall_claim_selfrename(dir)
    if after == "held" then return false, "foreign" end
    if after ~= "free" then return false, "adrift" end
    return true, "bound"
  end
  -- AND ON POSIX THE LAST WORD IS THE LINK PROBE ASKED AGAIN, which is the
  -- other half of round 56's first blocker. An open handle pins nothing there,
  -- so the rename above is no question at all and the removal above is the only
  -- act that tells a directory from a link. Asked once, it leaves a single
  -- redirection standing: move the folder after the refusal and put a symbolic
  -- link at the name, and the read-back follows it and matches. Asked AGAIN
  -- after the read-back, that link is TAKEN and said, so an actor needs a link
  -- for the read-back and a real directory of their own for this answer, which
  -- is the two-swap race this lane has already disclosed rather than a single
  -- redirection. Both halves of that rule are MEASURED on the MacBook, at the
  -- remove(3) and stock Lua 5.4.8 os.remove layers alike: the directory half
  -- on 2026-08-16 (a directory holding anything refuses with ENOTEMPTY), the
  -- symlink half on 2026-08-21 (os.remove takes the LINK itself for file,
  -- non-empty-directory and dangling targets, with the target and its
  -- contents untouched in every case). It is the same rule that rule one of
  -- the containment pair already rests on.
  pcall(function() held:close() end)
  local _, again = Updater.uninstall_remove_empty_dir_kind(dir)
  if again ~= "refused" then return false, again end
  return true, "bound"
end

-- WHAT DOES THE NAME SAY WHEN IT IS ASKED TO RENAME ONTO ITSELF? It is the one
-- act on Windows that a junction cannot survive and an unpinned directory
-- answers plainly, and it is asked here as three words rather than two because
-- the platform gives the same failure for causes that are not the same thing.
--
--   free   nothing is holding this name still: an unpinned directory, a
--          junction, a regular file (P63, P65, P68b).
--   gone   there is nothing at the name at all, ENOENT (P68a).
--   held   something is holding it, EACCES. WHAT is holding it is not in the
--          answer: this side's own open handle (P64), an ACL denying this
--          account (P66) and another actor's lock (P67) are one word and one
--          code, so only a caller that can compare two of these answers across
--          a change of its own may read this word as its own doing.
function Updater.uninstall_claim_selfrename(path)
  local renamed, _, code = os.rename(path, path)
  if renamed == true then return "free" end
  if tonumber(code) == 2 then return "gone" end
  return "held"
end

-- Is the file at `path` still the one this run wrote `nonce` into?
function Updater.uninstall_claim_proof(path, nonce)
  local seen
  local ok = pcall(function()
    local f = io.open(path, "rb")
    if not f then return end
    seen = f:read("*a")
    f:close()
  end)
  return ok == true and seen == nonce
end

-- Take a directory out of everybody's reach, and prove it.
--
-- Returns, on success, a table describing the claim:
--   work  the private name everything after this acts on
--   pin   the open handle that is holding it still
--   path  the file that handle is on
--   leaf  that file's own name
--   nonce the value it carries, so the put-back can be proven too
--
-- Returns nil plus the word for what stopped it otherwise. The third value is
-- the name the folder is standing under for the answers that leave one
-- standing; the fourth is this run's own leftover, a path for `breach` and the
-- seed's own leaf name for `linked`; the fifth is the put-back's own note,
-- which says how the folder came to be standing where it is.
function Updater.uninstall_claim_dir(dir)
  local parent = tostring(dir):match("^(.*)[/\\][^/\\]+$")
  if not parent or parent == "" then return nil, "could not be moved aside" end
  local name = Updater.uninstall_claim_name(parent)
  if not name then return nil, "could not be moved aside" end
  local leaf = tostring(name):match("[^/\\]+$") or ""
  local seed = dir .. RA.SEP .. leaf
  if leaf == "" or RA.path_present(seed) then
    return nil, "could not be moved aside"
  end
  -- THE SEED, PLANTED FIRST. This is the one thing this run writes through a
  -- name it has not taken, and it can take nothing away: it is a single file at
  -- a name minted for this claim, refused if anything is already there, and
  -- taken back on every path that does not go on to walk the folder.
  local nonce = Updater.uninstall_claim_nonce()
  local planted = pcall(function()
    local f = io.open(seed, "wb")
    if not f then return end
    f:write(nonce)
    f:close()
  end)
  if not planted or not Updater.uninstall_claim_proof(seed, nonce) then
    os.remove(seed)
    return nil, "could not be moved aside"
  end
  -- RULE ONE AGAIN, WITH THE SEED INSIDE, WHICH IS WHAT MAKES A LINK DECIDABLE
  -- HERE (round 51, blocker one). Rule one before the claim answers for a link
  -- that was already standing; it cannot answer for one that arrives in the
  -- instant between that question and this write, and such a link takes the
  -- seed THROUGH itself into whatever it points at. The rename then carries
  -- that folder off, and an attacker who takes the link away before the
  -- public-name probe leaves this side holding a folder whose seed matches,
  -- because the seed travelled with it.
  --
  -- THE SAME QUESTION ASKED AGAIN NOW HAS A DIFFERENT ANSWER FOR THE TWO CASES,
  -- and both halves are measured on this machine rather than reasoned about. A
  -- REAL directory holds at least the seed, so a non-recursive rmdir refuses it.
  -- A JUNCTION is removed by that same rmdir whatever its target holds. So a
  -- removal that SUCCEEDS here proves the name was a link, and the answer to it
  -- is the answer rule one gives before the claim: the link is gone, everything
  -- it pointed at is untouched, and NOTHING was renamed. A removal that is
  -- REFUSED proves a real directory held this run's seed at that instant, which
  -- is what the rename is allowed to act on.
  --
  -- AND THE SEED IT LEAVES BEHIND IS DISCLOSED RATHER THAN QUIETLY DROPPED. The
  -- seed went through the link into its target, and once the link is gone this
  -- side cannot reach it to take it back, so the report names the name it was
  -- written through and the file it wrote.
  local stood = RA.path_present(dir)
  local took, rule_one = Updater.uninstall_remove_empty_dir_kind(dir)
  if took and rule_one == "removed" then
    return nil, "linked", nil, (stood and leaf or nil)
  end
  -- AND A NAME THAT WENT WHILE THIS SIDE WAS ASKING IS NOT A LINK THIS RUN
  -- TOOK (B2.4g, round 54's second blocker). B2.4f's removal answered true for
  -- a name that was already absent, so a folder somebody carried away in this
  -- instant was reported as a link this run had removed. There is nothing here
  -- to claim, nothing to walk and nothing to say: the walk is done with this
  -- name and claims no removal for it.
  if rule_one == "gone" then return nil, "gone" end
  -- AND A NAME THAT IS A FILE IS NOT A FOLDER TO CLAIM (round 55's second
  -- blocker). Something replaced this name with a regular file between the
  -- listing that named it as a directory and this question; renaming it would
  -- carry a file this run knows nothing about off to a name only this run has
  -- spelled. Nothing is claimed, nothing is moved, and the walk leaves it to be
  -- named in the report.
  if rule_one == "file" then return nil, "could not be moved aside" end
  -- THE RECORD, DURABLE BEFORE THE RENAME IT DESCRIBES. A claim this side
  -- cannot write down is a claim it does not take, because a crash would then
  -- leave the folder under a name nothing on this machine knows.
  --
  -- AND THE SEED'S OWN VALUE GOES ON THE RECORD, which is round 56's second
  -- blocker. It is written before the rename for the same reason the rest of
  -- the line is: the session that has to read it is the one that starts after
  -- this one died, and the only evidence it can ask about is the file this run
  -- has already planted and the value on the line beside it.
  if not Updater.uninstall_claim_record(dir, name, nil, nonce) then
    os.remove(seed)
    return nil, "could not be recorded"
  end
  -- AND THIS IS THE ONE PLACE A RUN EARNS THE RIGHT TO RETIRE A RECORD ON A
  -- VALUE (round 58). The seed is in the folder, the value is in this process's
  -- memory and on the line, and the rename this record describes has not
  -- happened yet, so nothing can have been substituted between the minting and
  -- the object. Every later act that closes this record on that value reaches
  -- back to here; a session that finds the record on disk instead reaches back
  -- to nothing and closes nothing.
  Updater.uninstall_claim_authority(name, true)
  if not os.rename(dir, name) then
    os.remove(seed)
    Updater.uninstall_claim_settle(name)
    return nil, "could not be moved aside"
  end
  -- THE CHECK THAT CATCHES A RENAME THAT FOLLOWED A LINK, asked first because
  -- it is the one whose window this side can make no narrower: a rename that
  -- followed a link leaves the link standing at the old name, so a name that
  -- survived its own rename proves the rename took something that was not it.
  -- The seed travelled through the link into the folder that was carried off,
  -- so it is taken back out and that folder is left exactly as the rename put
  -- it.
  --
  -- AND THE FOLDER THAT WAS CARRIED OFF IS NOT ABANDONED UNDER A PRIVATE NAME,
  -- which is round 51's other half. The rename back is attempted, and while the
  -- link is standing at the folder's own name it cannot land, so the record
  -- stays OPEN and the next session tries again. Nothing is ever moved onto a
  -- name something else is at.
  if RA.path_present(dir) then
    local stray = name .. RA.SEP .. leaf
    os.remove(stray)
    local left_behind = RA.path_present(stray)
    local where, note = Updater.uninstall_claim_restore(name, dir)
    return nil, "breach", where,
      (left_behind and (where .. RA.SEP .. leaf) or nil), note
  end
  -- THE PIN AND THE PROOF, IN ONE ACT. The open is what stops anybody renaming
  -- this folder from here on, and what it hands back is the only evidence that
  -- says whether the folder it is holding is the one that was renamed.
  local pin
  pcall(function() pin = io.open(name .. RA.SEP .. leaf, "rb") end)
  local seen
  if pin then pcall(function() seen = pin:read("*a") end) end
  if pin and seen == nonce then
    return { work = name, pin = pin, path = name .. RA.SEP .. leaf,
      leaf = leaf, nonce = nonce }
  end
  if pin then
    -- The file opened and does not carry the value this run wrote into the
    -- folder it moved, so what is standing at the private name is not what was
    -- renamed to it. Nothing in it is touched and the walk stops.
    --
    -- AND IT IS NOT LEFT UNDER A NAME NOBODY WILL LOOK FOR. B2.4c closed this
    -- record and left the folder standing there, on the reasoning that a later
    -- session must not rename an unproven folder onto one of ReaAssist's own
    -- names. Round 51 named the cost of that: the folder standing there is a
    -- stranger's, and abandoning it under minted litter is worse than putting
    -- it at a name the report can name and the user can see. So the rename back
    -- is attempted into a free name, and when it cannot happen the record stays
    -- open for the consumer.
    Updater.uninstall_unpin(pin)
    local where, note = Updater.uninstall_claim_restore(name, dir)
    return nil, "swapped", where, nil, note
  end
  -- AND AN OPEN THAT DID NOT HAPPEN AT ALL IS NOT EVIDENCE OF ANYTHING. A path
  -- the platform will not accept, a folder this account cannot read into, and a
  -- name somebody swapped all fail here in exactly the same way, so the claim
  -- is UNDONE rather than acted on and rather than raised as a replacement. The
  -- undoing is proven the same way the claim was: the seed is still in the
  -- folder, so after the rename back it has to be at the folder's own name.
  local back = os.rename(name, dir)
  if back and Updater.uninstall_claim_bound(dir, leaf, nonce) then
    -- AND THE SEED STAYS IN THE FOLDER, because the accounting pass asks its
    -- question of that file and of nothing else. It comes out there, after the
    -- record it proved is closed. This put-back does not finish an emptied
    -- folder: the walk never entered this one, so everything the user had in it
    -- is still in it and there is nothing here that could be an empty shell.
    Updater.uninstall_claim_pending(name, leaf, nonce, false)
    return nil, "could not be moved aside"
  end
  if back then
    -- The rename back landed, and what is at the folder's own name now is not
    -- what this run took away from it. That IS the replacement, and it gets the
    -- answer every replacement gets. The folder's own name is where its
    -- contents are, so that is the name the report is given; and the record is
    -- KEPT, because a run that cannot account for the folder must not take away
    -- the only description of where it was put.
    return nil, "swapped", dir
  end
  -- The folder is still under the name this run gave it and this run cannot put
  -- it back. The record stays OPEN, which is exactly what the next session's
  -- consumer restores from, and the walk names it where it really is rather
  -- than touching it.
  os.remove(name .. RA.SEP .. leaf)
  return nil, "moved aside", name
end

-- WHAT THE PUT-BACK OF AN UNPROVEN FOLDER LEFT BEHIND, WRITTEN INTO THE REPORT.
-- The plain answers need no sentence: the folder went back to the name the
-- report already names, or nothing was standing there at all. The other three
-- do, and each is a state the user cannot see by looking in the folder.
--   link    the private name held a link, so the folder is not where this run
--           put it and this side cannot say where it is. One file of this run's
--           went through that link before the question could be asked.
--   breach  the put-back's own rename followed a link swapped in behind the
--           question, so what is at the folder's own name now came from outside
--           this install, this run's rename is what put it there, the link is
--           still standing at the private name and where the folder went is
--           unknown.
--   vanished the private name went while the question was being asked and no
--           rename of this run's landed, so nothing this side did accounts for
--           the folder and nothing standing at its own name can be proven to be
--           it.
--   unproven the rename landed and what is at the folder's own name does not
--           carry the file this run had put inside the folder, so this run
--           moved something it cannot prove is the folder the record describes.
--   redirected the rename landed, and a LINK was standing at the folder's own
--           name when this side asked about it. The question took the link and
--           left everything it pointed at alone, so the folder this run had
--           just put back is somewhere this side cannot name, with one file of
--           this run's inside it.
--   stray   a file of this run's that would not come back out.
function Updater.uninstall_claim_note(out, note, pub)
  if type(out) ~= "table" or type(note) ~= "table" then return end
  if note.outcome == "link" or note.outcome == "redirected" then
    out.claim_lost = out.claim_lost or {}
    out.claim_lost[#out.claim_lost + 1] =
      { path = tostring(pub), moved = tostring(note.private),
        reason = tostring(note.outcome), probe = note.probe }
  elseif note.outcome == "vanished" or note.outcome == "unproven" then
    out.claim_lost = out.claim_lost or {}
    out.claim_lost[#out.claim_lost + 1] =
      { path = tostring(pub), moved = tostring(note.private),
        reason = note.outcome }
  elseif note.outcome == "breach" then
    out.claim_lost = out.claim_lost or {}
    out.claim_lost[#out.claim_lost + 1] =
      { path = tostring(pub), moved = tostring(note.private),
        reason = "breach", probe = note.probe }
    -- Named once, and with the stronger of the two things that are true of it.
    -- The caller has already listed this name as one it could not prove; what
    -- this side now knows is that what is standing there came from outside the
    -- install, and two lines about one folder read as two folders.
    local said = false
    for _, item in ipairs(out.left) do
      if tostring(item.path) == tostring(note.public) then
        item.reason = "not ReaAssist's"
        said = true
      end
    end
    if not said then
      out.left[#out.left + 1] =
        { path = tostring(note.public), reason = "not ReaAssist's" }
    end
  end
  if note.stray then
    out.left[#out.left + 1] =
      { path = tostring(note.stray), reason = "ReaAssist's own" }
  end
end

-- Hold one of this directory's own files open, so nothing can rename the
-- directory or remove it around this walk. A file the walk is going to KEEP is
-- preferred, because then the pin never has to be let go and taken again.
function Updater.uninstall_pin_dir(dir, pub, files, skip)
  for pass = 1, 2 do
    for _, fn in ipairs(files or {}) do
      local kept = skip and skip(pub .. RA.SEP .. fn, fn, false) or nil
      if (pass == 1) == (kept ~= nil) then
        local ok, f = pcall(io.open, dir .. RA.SEP .. fn, "rb")
        if ok and f then return f, dir .. RA.SEP .. fn end
      end
    end
  end
  return nil
end

function Updater.uninstall_unpin(handle)
  if handle then pcall(function() handle:close() end) end
end

-- Say where a leftover really is.
--
-- Entries are recorded under the name a folder had when the walk reached it.
-- If it could not be put back under that name afterwards they are rewritten to
-- the name it has now; and when a CHILD could not be put back, its entries
-- travel the other way as the parent is restored. The two prefixes are always
-- siblings, so no entry can match both.
--
-- THE BREACH RECORD TRAVELS WITH THEM, because the folder a breach carried off
-- sits inside the claim of whatever was above it, and the report has to name
-- the place the user will actually find it.
function Updater.uninstall_repath(out, first, from, to)
  local function moved(path)
    path = tostring(path or "")
    if path == from then return to end
    if path:sub(1, #from + 1) == from .. RA.SEP then
      return to .. path:sub(#from + 1)
    end
    return nil
  end
  for i = first, #(out.left or {}) do
    local item = out.left[i]
    local now = item and moved(item.path)
    if now then item.path = now end
  end
  if type(out.breach) == "table" then
    out.breach.path = moved(out.breach.path) or out.breach.path
    out.breach.moved = moved(out.breach.moved) or out.breach.moved
  end
end

-- The two listings, forced fresh. reaper.EnumerateFiles and
-- EnumerateSubdirectories cache a directory the first time it is walked and
-- answer every later index 0 out of that cache; index -1 is what invalidates
-- it. A claimed directory is spelled with a name no earlier walk can have
-- filled the cache with, but a PINNED one is spelled with its own public name
-- and can have been listed before, so the reset is what keeps the listing the
-- evidence it is supposed to be rather than a guess.
function Updater.uninstall_list_files(dir)
  local out = {}
  if type(reaper.EnumerateFiles) ~= "function" then return out end
  pcall(reaper.EnumerateFiles, dir, -1)
  local idx = 0
  while true do
    local fn = reaper.EnumerateFiles(dir, idx)
    if not fn then break end
    out[#out + 1] = fn
    idx = idx + 1
  end
  return out
end

function Updater.uninstall_list_dirs(dir)
  local out = {}
  if type(reaper.EnumerateSubdirectories) ~= "function" then return out end
  pcall(reaper.EnumerateSubdirectories, dir, -1)
  local idx = 0
  while true do
    local sub = reaper.EnumerateSubdirectories(dir, idx)
    if not sub then break end
    out[#out + 1] = sub
    idx = idx + 1
  end
  return out
end

-- Take a directory apart depth first, then take the directory.
--
-- `opts.skip(path, name, is_dir)` answers with a reason for something this run
-- must not touch, and is always asked with the PUBLIC path, whatever name the
-- entry is really sitting under while the walk runs. A skipped entry keeps
-- every directory above it alive, which is how a kept file survives a tree
-- removal rather than being carried off by a parent's delete: the parent is
-- only ever removed when the walk under it left nothing at all. `opts.shape`
-- is the descent list described above, and a nil shape means the caller is
-- walking a tree whose whole contents it owns.
--
-- CONTAINMENT IS THE CLAIM AND THE PIN described above, plus rule one, plus
-- the shape. The shape is no longer a containment rule and is not kept as one:
-- claiming holds whether or not a name is in it. It is kept because it decides
-- WHOSE files these are, which is a different question, and the answer to that
-- one should not be "everything under App/".
--
-- AND THE DESCENT IS STILL BOUNDED, because nothing here can answer for a link
-- whose own removal the filesystem refuses. The deepest thing ReaAssist ships
-- is four levels, so UNINSTALL_MAX_DEPTH cannot be reached by an ordinary
-- install, and reaching it stops the descent and names the folder as left
-- behind rather than overflowing the stack halfway through a removal.
Updater.UNINSTALL_MAX_DEPTH = 24

-- Returns the accumulator plus whether this directory itself is gone.
--
-- `public` is the name to speak about this directory by. It is the same as
-- `root` until a parent claims itself, and the two part again if a folder
-- cannot be put back under its own name at the end.
function Updater.uninstall_remove_tree(root, opts, out, depth, rel, public)
  out = out or { removed = {}, left = {} }
  opts = opts or {}
  depth = tonumber(depth) or 0
  rel = tostring(rel or "")
  local skip = opts.skip
  local shape = opts.shape
  local dir = tostring(root or ""):gsub("[/\\]+$", "")
  local pub = tostring(public or dir):gsub("[/\\]+$", "")
  if dir == "" then return out, false end
  if out.breach then return out, false end
  if not RA.path_present(dir) then return out, true end
  if depth > Updater.UNINSTALL_MAX_DEPTH then
    out.left[#out.left + 1] = { path = pub, reason = "too deep" }
    return out, false
  end
  -- Rule one, asked before a single entry of this directory is read AND before
  -- the claim, so an ordinary link is taken as a link and never reaches a
  -- rename that would follow it.
  if Updater.uninstall_remove_empty_dir(dir) then
    out.removed[#out.removed + 1] = pub
    return out, true
  end
  local claim, why, moved, stray, note = Updater.uninstall_claim_dir(dir)
  local work, pin, pin_path = dir, nil, nil
  if claim then
    -- Everything from here to the moment the pin comes off happens on a name
    -- the platform is holding still for this run and for everybody else at the
    -- same time. There is no second probe of the claim, and there is nothing
    -- for one to ask: the open that took the pin is the same act that proved
    -- what it took, and an empty claim is removed at the end of the walk like
    -- any other.
    work, pin, pin_path = claim.work, claim.pin, claim.path
  elseif why == "linked" then
    -- RULE ONE, ASKED AGAIN WITH THE SEED INSIDE, TOOK THE NAME. A real folder
    -- holding this run's seed cannot be removed by a non-recursive rmdir, so a
    -- name that went was a link and nothing it pointed at was touched. Nothing
    -- was renamed, so this is the same event rule one answers before the claim
    -- and it gets the same answer: the link is gone and the walk carries on.
    out.removed[#out.removed + 1] = pub
    -- Except for the one file this run had already written through that name.
    -- It went into whatever the link pointed at, and once the link is gone
    -- there is no path from here to it, so it is named rather than left for the
    -- user to find on their own.
    if stray then
      out.link_seeds = out.link_seeds or {}
      out.link_seeds[#out.link_seeds + 1] = { path = pub, leaf = stray }
    end
    return out, true
  elseif why == "gone" then
    -- THE NAME WENT WHILE THE CLAIM WAS BEING TAKEN. Nothing is standing here,
    -- so the walk is finished with it; and this run did not take it, so it is
    -- not counted as a removal and the report claims nothing about it.
    return out, true
  elseif why == "breach" then
    -- The rename followed a link and carried somebody else's folder off. It
    -- is left exactly as it was, under the name the rename gave it, and this
    -- stops the whole run rather than deleting one more thing.
    out.breach = { path = pub, moved = moved, stray = stray }
    out.left[#out.left + 1] = { path = pub, reason = "not ReaAssist's" }
    if moved then
      out.left[#out.left + 1] = { path = moved, reason = "not ReaAssist's" }
    end
    -- The seed was planted through the public name, so a public name that was
    -- a link put it inside the folder the rename carried off. It is taken back
    -- out above; one that would not come out is named here rather than left to
    -- contradict the report's promise that nothing in that folder was touched.
    if stray then
      out.left[#out.left + 1] = { path = stray, reason = "ReaAssist's own" }
    end
    Updater.uninstall_claim_note(out, note, pub)
    return out, false
  elseif why == "swapped" then
    -- The rename landed, and what stood at the private name afterwards did not
    -- carry the value this run had just written into the folder it moved. That
    -- is somebody replacing a name this run had taken, and the answer to it is
    -- the answer to every other one: touch nothing else, name both places, and
    -- stop.
    out.breach = { path = pub, moved = moved, claim = true }
    out.left[#out.left + 1] =
      { path = moved or pub, reason = "could not be proven ReaAssist's" }
    -- AND THE PUT-BACK'S OWN ANSWER IS CARRIED OUT WITH IT. The folder this run
    -- could not prove is put back under the name the report can name, and that
    -- rename asks the junction question before it happens and again afterwards.
    -- Every answer but the plain one is a thing the user has to be told.
    Updater.uninstall_claim_note(out, note, pub)
    return out, false
  elseif why == "moved aside" then
    -- The claim was taken, could not be used, and could not be undone. That is
    -- not a replacement and it does not stop the run: the folder is whole under
    -- the name this run gave it, its record is still open, and the next session
    -- puts it back if its own name is free by then.
    out.left[#out.left + 1] = { path = moved, reason = "moved aside" }
    out.moved_aside = true
    return out, false
  else
    if RA.IS_WINDOWS then
      pin, pin_path = Updater.uninstall_pin_dir(dir, pub,
        Updater.uninstall_list_files(dir), skip)
    end
    if not pin then
      out.left[#out.left + 1] = { path = pub, reason = why }
      return out, false
    end
    -- The pin holds a real directory still. A junction that had arrived would
    -- go here instead, because a handle in its target does not protect it.
    if Updater.uninstall_remove_empty_dir(dir) then
      Updater.uninstall_unpin(pin)
      out.removed[#out.removed + 1] = pub
      return out, true
    end
  end
  local files = Updater.uninstall_list_files(work)
  local subs = Updater.uninstall_list_dirs(work)
  local kept = false
  local first_left = #out.left + 1
  for _, fn in ipairs(files) do
    local path = work .. RA.SEP .. fn
    local pub_path = pub .. RA.SEP .. fn
    -- The pin is what is holding this directory still, so it goes last.
    if not (pin_path and path == pin_path) then
      local held = skip and skip(pub_path, fn, false) or nil
      if held then
        kept = true
        out.left[#out.left + 1] = { path = pub_path, reason = held }
      else
        -- COUNTED ONLY WHEN THIS CALL IS WHAT TOOK IT. A name that was already
        -- gone leaves the folder one entry emptier either way, so the walk
        -- carries on and nothing is kept for it, but it is not one of this
        -- run's own removals and the report does not claim it as one.
        local went, how = Updater.uninstall_remove_file(path)
        if how == "removed" then
          out.removed[#out.removed + 1] = pub_path
        elseif not went then
          kept = true
          out.left[#out.left + 1] = { path = pub_path, reason = "refused" }
        end
      end
    end
  end
  for _, sub in ipairs(subs) do
    if out.breach then kept = true break end
    local child = work .. RA.SEP .. sub
    local child_pub = pub .. RA.SEP .. sub
    local child_rel = (rel == "") and tostring(sub):lower()
      or (rel .. "/" .. tostring(sub):lower())
    local held = skip and skip(child_pub, sub, true) or nil
    if not held and shape and not shape[child_rel] then
      held = "not installed by ReaAssist"
    end
    if held then
      kept = true
      out.left[#out.left + 1] = { path = child_pub, reason = held }
    else
      local _, gone = Updater.uninstall_remove_tree(child, opts, out,
        depth + 1, child_rel, child_pub)
      if not gone then kept = true end
    end
  end
  -- THE PIN COMES OFF HERE, AND NOT ONE ACT EARLIER. Everything above this
  -- line read or emptied the folder with the platform holding its name still.
  -- What is left below is three acts, and the reason each of them is safe on an
  -- unpinned name is written where it happens.
  Updater.uninstall_unpin(pin)
  pin = nil
  -- Put the folder back under its own name if this run moved it aside, and
  -- say where its leftovers really are either way. A name somebody else has
  -- taken in the meantime makes the rename fail rather than write over them,
  -- so the folder keeps the private name and the report says so.
  --
  -- AND THE PUT-BACK IS PROVEN THE SAME WAY THE CLAIM WAS. The seed is still in
  -- the folder at this point, deliberately: after the rename it is read again
  -- through the folder's own name, so a link that arrived at the private name
  -- in the instant the pin came off is caught by the same evidence rather than
  -- quietly moving a stranger's folder to one of ReaAssist's names.
  -- Whether a put-back below left the record marked for the accounting pass.
  -- The seed is that pass's evidence, so a marked record is one whose seed must
  -- still be in the folder when this function returns.
  local marked = false
  local function settle()
    if work == dir then return pub end
    -- THE RECORDS OF EVERYTHING STILL STANDING INSIDE THIS FOLDER GO FIRST, and
    -- a replacement that cannot be written stops the put-back rather than
    -- letting the rename make the old names stale with nothing standing in for
    -- them. That is round 52's second blocker: the folder keeps the name this
    -- run gave it, its record stays open, and the report says so.
    local moves, ready = Updater.uninstall_claim_repath_plan(work, dir)
    if not ready then
      out.records_stuck = true
      Updater.uninstall_repath(out, first_left, pub, work)
      out.moved_aside = true
      return work
    end
    -- THIS RUN'S OWN FILE GOES BACK INSIDE THE FOLDER IF THE LAST ACT HAS
    -- ALREADY TAKEN IT OUT, and it goes in BEFORE the rename, exactly as the
    -- claim's own seed does. A put-back is provable only while the folder
    -- carries a file this run wrote, because the file is what travels with the
    -- rename and answers at the other end of it; without one, this put-back
    -- could prove nothing and would have to call an ordinary outcome a breach.
    -- A plant that cannot be read back leaves this side with no evidence, which
    -- is the state the breach below is for.
    local value = claim and claim.nonce or nil
    if claim and not RA.path_present(work .. RA.SEP .. claim.leaf) then
      local seed = work .. RA.SEP .. claim.leaf
      value = Updater.uninstall_claim_nonce()
      local planted = pcall(function()
        local f = io.open(seed, "wb")
        if not f then return end
        f:write(value)
        f:close()
      end)
      if not planted or not Updater.uninstall_claim_proof(seed, value) then
        os.remove(seed)
        value = nil
      end
    end
    if os.rename(work, dir) then
      -- ASKED WITH THE HANDLE HELD, not read through the name (round 54's first
      -- blocker, the same shape one walk away from the put-back it was found
      -- in). A junction put at the folder's own name in the instant after this
      -- rename would carry a bare read straight through to the folder wherever
      -- it had been moved to.
      local held, held_kind
      if claim and value then
        held, held_kind = Updater.uninstall_claim_bound(dir, claim.leaf, value)
      end
      if claim and not held then
        out.breach = { path = pub, moved = work, claim = true }
        if held_kind == "removed" then
          -- A LINK WAS STANDING AT THE FOLDER'S OWN NAME AND THE QUESTION TOOK
          -- IT. The rename did put the folder back and something moved it on;
          -- nothing is standing at that name now, so it is not named as a
          -- leftover, and what really happened is said instead.
          out.claim_lost = out.claim_lost or {}
          out.claim_lost[#out.claim_lost + 1] =
            { path = pub, moved = work, reason = "redirected",
              probe = claim.leaf }
        else
          out.left[#out.left + 1] =
            { path = pub, reason = "could not be proven ReaAssist's" }
        end
        -- The rename landed, so the folder's contents are at its own name and
        -- the report names them there. The same answer decides which half of
        -- each pair of child records is the true one, and the record itself is
        -- KEPT: this side could not account for the folder, so the only
        -- description of where it went stays on the list.
        Updater.uninstall_claim_repath_commit(moves,
          not RA.path_present(work))
        return pub
      end
      if not RA.path_present(work) then
        Updater.uninstall_repath(out, first_left, work, pub)
        Updater.uninstall_claim_repath_commit(moves, true)
        -- AND THE MARK CARRIES THE VALUE THAT PROVED THIS PUT-BACK, which is
        -- the one the folder really holds: the claim's own seed when it is
        -- still there, and the one planted above when the last act had already
        -- taken it out. The accounting pass asks its question of that file.
        if claim and value then
          marked = Updater.uninstall_claim_pending(work, claim.leaf, value,
            false)
        end
        work = dir
        return pub
      end
    end
    Updater.uninstall_claim_repath_commit(moves, false)
    Updater.uninstall_repath(out, first_left, pub, work)
    out.moved_aside = true
    return work
  end
  if claim then
    -- 1. THE PUT-BACK COMES FIRST when anything at all is staying, because the
    --    seed has to still be in the folder for the put-back to be provable.
    --    settle leaves `work` naming wherever the folder ended up.
    if out.breach or kept then settle() end
    local staying = (out.breach or kept) and true or false
    -- 2. THE FOLDER IS BOUND TO THE FILE INSIDE IT BEFORE THAT FILE COMES OUT,
    --    which is round 55's second blocker. The removal below can only ever
    --    say that this call took whatever was standing at the name; it cannot
    --    say the name was the folder this record describes, and a folder
    --    carried away and replaced with an empty one or a junction answered it
    --    exactly as an emptied claim does. So the binding question is asked
    --    while this run's own file is still in the folder, and the record is
    --    retired only when that question answered AND the removal then took the
    --    name. The window between the two is this run letting go of its own
    --    file, and what it costs is written in the plan: an actor who can name
    --    this run's private folder and swap an empty directory or a junction
    --    into that instant costs the description of a folder this walk had
    --    already emptied.
    local bound = false
    if not staying then
      bound = Updater.uninstall_claim_bound(work, claim.leaf, claim.nonce)
    end
    -- 3. THEN THE SEED GOES, unless the put-back above marked the record: the
    --    accounting pass asks its question of that file, so it stays in the
    --    folder until that pass has closed the record and taken it out. It is
    --    this run's own file and was never the user's, so it is removed rather
    --    than counted as a removal; and a seed that will not go is the one
    --    thing keeping the folder alive, so the folder goes back under its own
    --    name and the file is named.
    if not marked
        and not Updater.uninstall_remove_file(work .. RA.SEP .. claim.leaf) then
      if not staying then
        kept = true
        staying = true
        settle()
      end
      out.left[#out.left + 1] =
        { path = work .. RA.SEP .. claim.leaf, reason = "refused" }
    end
    if staying then return out, false end
    -- 4. RULE ONE, ON THE PRIVATE NAME, as the last act of the walk. It cannot
    --    destroy the contents of anything, so it is safe on a name the pin is
    --    no longer holding: the worst a swap in this instant costs is a link
    --    removed or a removal refused, and a regular file swapped into it is
    --    answered "file" and left exactly as it is.
    --
    --    AND THE ANSWER SETTLES NOTHING ON ITS OWN. "removed" is this call
    --    having taken whatever stood at the name, which is not the same fact as
    --    the folder this record describes having been the thing it took, so the
    --    record closes only when the binding above answered as well. A name
    --    that was already absent was taken away by somebody else in the instant
    --    the pin came off; it is kept, said, and left for the next session's
    --    consumer.
    local _, kind = Updater.uninstall_remove_empty_dir_kind(work)
    if kind == "removed" then
      out.removed[#out.removed + 1] = pub
      if bound then Updater.uninstall_claim_settle(work) end
      return out, true
    end
    if kind == "gone" then
      -- Nothing is claimed about it, in the report or on the list: the name is
      -- gone, so the walk is done here, and the record stays open for the
      -- session that reads the list next, which is the one place that can say
      -- what became of the folder.
      return out, true
    end
    out.left[#out.left + 1] = { path = settle(), reason = "folder" }
    return out, false
  end
  if out.breach then
    -- A breach below this folder ends the run, so nothing else in here is
    -- touched, the file the pin was on included.
    kept = true
  elseif pin_path then
    -- The folder was walked under its own name, so rule one is asked once more
    -- before the last act aimed at a public name. It cannot destroy anything
    -- inside a folder, and a name that goes to it now had become a link in the
    -- instant the pin was let go.
    local fn = tostring(pin_path):match("[^/\\]+$") or ""
    local pub_pin = pub .. RA.SEP .. fn
    local held = skip and skip(pub_pin, fn, false) or nil
    if held then
      kept = true
      out.left[#out.left + 1] = { path = pub_pin, reason = held }
    else
      if not kept and Updater.uninstall_remove_empty_dir(dir) then
        out.removed[#out.removed + 1] = pub
        return out, true
      end
      local went, how = Updater.uninstall_remove_file(pin_path)
      if how == "removed" then
        out.removed[#out.removed + 1] = pub_pin
      elseif not went then
        kept = true
        out.left[#out.left + 1] = { path = pub_pin, reason = "refused" }
      end
    end
  end
  if out.breach or kept then
    settle()
    return out, false
  end
  if Updater.uninstall_remove_empty_dir(work) then
    out.removed[#out.removed + 1] = pub
    return out, true
  end
  out.left[#out.left + 1] = { path = settle(), reason = "folder" }
  return out, false
end

-- What an uninstall would do to THIS install, decided before anything is
-- touched and never re-derived while it runs.
--
-- Every path the execution uses is captured here, and that is deliberate:
-- RA.PACKAGE_DIR is derived from a marker-verified launcher sitting above the
-- body, and the execution removes launchers, so a path re-derived halfway
-- through a run would be answering a question whose inputs this run had
-- already changed. Ownership is the one thing NOT frozen here; it is re-asked
-- at the destructive moment, because a ReaPack synchronization between the
-- confirmation screen and the click is exactly the case that rule exists for.
function Updater.uninstall_plan(opts)
  opts = opts or {}
  local plan = {
    remove_user_data = opts.remove_user_data == true,
    package_dir = tostring(RA.PACKAGE_DIR or ""),
    app_dir = tostring(RA.APP_DIR or ""),
    data_dir = tostring(RA.DATA_DIR or ""),
    temp_dir = tostring(RA.TEMP_DIR or ""),
    recovery_dir = tostring(RA.RECOVERY_DIR or ""),
    jsfx_dir = tostring(RA.JSFX_DIR or ""),
    saved_scripts_dir = tostring(RA.SCRIPT_SAVE_DIR or ""),
    launchers = {},
    launchers_left = false,
    marker_path = Updater.uninstall_marker_path(),
    claim_journal_path = Updater.uninstall_claim_journal_path(),
  }
  plan.custom_prompt_source = tostring(RA.RESOURCES_DIR or "")
    .. "System_Prompt_Custom.md"
  plan.custom_prompt_dest = plan.data_dir .. "System_Prompt_Custom.md"
  plan.custom_prompt_present = RA.path_present(plan.custom_prompt_source)
  -- Frozen here with every other path, and for the same reason: the manifest
  -- it is read from is inside the folder this run removes, so a shape derived
  -- halfway through the walk would be derived from a file the walk had already
  -- deleted.
  plan.app_shape, plan.app_shape_from_manifest = Updater.uninstall_app_shape()
  Updater.launcher_owner_refresh()
  for _, name in ipairs(Updater.LAUNCHER_FILES) do
    local state, detail = Updater.launcher_ownership(name)
    local path = Updater.launcher_path(name)
    local entry = {
      name = name,
      path = path,
      ownership = state,
      detail = detail,
      removable = (state == Updater.OWNERSHIP_UNOWNED),
      present = RA.path_present(path),
    }
    -- Four answers, kept apart. `launchers_left` says only that something is
    -- staying; which of the three reasons it is stays on the entry, because
    -- the copy says a different true sentence for each one and a single flag
    -- would make the ReaPack sentence the answer to all three.
    if not entry.removable then plan.launchers_left = true end
    if state == Updater.OWNERSHIP_OWNED then plan.reapack_owned = true end
    if state == Updater.OWNERSHIP_FOREIGN then plan.foreign_owned = true end
    if state == Updater.OWNERSHIP_UNKNOWN then plan.unknown_owner = true end
    plan.launchers[#plan.launchers + 1] = entry
  end
  plan.blockers = Updater.uninstall_blockers()
  return plan
end

-- The confirmation copy, built from the plan so it can only say what the plan
-- will actually attempt.
--
-- Two rules govern every line of it. It states what is removed AND what is
-- not, because an uninstaller that lists only its removals leaves the user to
-- discover the rest. And it never promises an outcome a guard can decline:
-- where a step can refuse, the copy says what happens then, and the closing
-- line says that nothing is reported as removed unless it is gone.
--
-- ROUND 48 TOOK ONE SENTENCE OUT OF IT AND PUT TWO TRUE ONES IN. It used to
-- say that any file ReaAssist did not install itself stayed, including
-- anything put there by hand, and the walker does not work that way: inside
-- the application and recovery folders it removes every FILE it finds,
-- whoever wrote it. What the walker really refuses is a FOLDER it cannot
-- account for, so that is what the copy now says, and it says plainly that a
-- file the user parked among the application files goes with them.
--
-- AND ROUND 49 FOUND THAT THE REPLACEMENT WAS TRUE OF ONE FOLDER ONLY. The
-- shape is read from the manifest and applied to the APPLICATION folder;
-- Recovery is walked with no shape at all, so "any folder inside the ReaAssist
-- folders that ReaAssist did not install" promised something about Recovery
-- that nothing enforces, and it sat beside a sentence saying every file inside
-- both folders goes. The two folders are now described one at a time, in the
-- terms that are true of each: the application folder keeps what it cannot
-- account for, and the recovery folder goes whole, because everything in it
-- was put there by the launcher.
function Updater.uninstall_copy(plan)
  if type(plan) ~= "table" then return "" end
  local out = {}
  local function line(s) out[#out + 1] = s end
  local function t(key, values, fallback)
    line(Updater.uninstall_t(key, values, fallback))
  end
  t("copy.removes_heading", nil, "What ReaAssist removes")
  line("")
  t("copy.app_files", nil, "  The application files in:")
  line("    " .. plan.app_dir)
  -- One sentence per folder, because the two are not walked on the same
  -- terms and one sentence about both was the untruth round 49 found. The
  -- application folder keeps a folder this release does not install; the
  -- recovery folder has nothing in it but the launcher's own work.
  t("copy.app_files_detail", nil,
    "  Every file in the folders ReaAssist installed there goes, including "
    .. "any file you put among them yourself.")
  t("copy.recovery_folder", nil,
    "  The folder ReaAssist keeps its repair copy and recovery records in:")
  line("    " .. plan.recovery_dir)
  t("copy.recovery_folder_detail", nil,
    "  That folder goes completely, with everything in it. ReaAssist puts "
    .. "nothing there but its own repair copies and records.")
  t("copy.move_out_first", nil,
    "  Move anything you want to keep out of both folders first.")
  local removable = {}
  local left = {}
  for _, entry in ipairs(plan.launchers or {}) do
    if entry.removable then
      removable[#removable + 1] = entry
    else
      left[#left + 1] = entry
    end
  end
  if #removable > 0 then
    t("copy.actions", nil, "  The ReaAssist actions you start it from:")
    for _, entry in ipairs(removable) do
      line("    " .. entry.path)
    end
  end
  line("")
  t("copy.leaves_heading", nil, "What ReaAssist leaves alone")
  line("")
  for _, entry in ipairs(left) do
    if entry.ownership == Updater.OWNERSHIP_OWNED then
      line("  " .. entry.path)
      t("copy.left_owned", nil,
        "    ReaPack installed this action and keeps it. ReaAssist will "
        .. "not delete it, because ReaPack would put it back the next time "
        .. "you synchronize. To remove it, open ReaPack, browse packages, "
        .. "find ReaAssist and choose Uninstall.")
    elseif entry.ownership == Updater.OWNERSHIP_FOREIGN then
      line("  " .. entry.path)
      t("copy.left_foreign", nil,
        "    Another package owns this file, so it is not ReaAssist's to "
        .. "delete.")
    else
      line("  " .. entry.path)
      t("copy.left_unknown", nil,
        "    ReaAssist could not confirm who owns this file, and it only "
        .. "removes an action it knows nobody else installed.")
    end
  end
  if plan.jsfx_dir ~= "" then
    line("  " .. plan.jsfx_dir)
    t("copy.jsfx", nil,
      "    Effects ReaAssist installed into REAPER. Projects you still "
      .. "open may be using them, so they stay.")
  end
  if plan.saved_scripts_dir ~= "" then
    line("  " .. plan.saved_scripts_dir)
    t("copy.saved_scripts", nil,
      "    Scripts ReaAssist saved for you. They are yours and they keep "
      .. "working without ReaAssist.")
  end
  if plan.reapack_owned then
    -- Named because a ReaPack install at the transition release still carries
    -- ReaPack's own copies of the older files beside the launchers, and this
    -- uninstaller will not touch anything ReaPack registered.
    t("copy.reapack_rest", nil,
      "  Anything else ReaPack installed in the ReaAssist folder. It goes "
      .. "when you remove the package in ReaPack.")
  end
  -- Scoped to the one folder it is true of. The shape is read from the
  -- manifest and applied to the application folder only.
  t("copy.foreign_folders", nil,
    "  Any folder inside the application folder that ReaAssist did not "
    .. "install, and everything in it. ReaAssist does not open a folder it "
    .. "cannot account for, and it names each one it left in the report.")
  -- Said here because a user who watches this run and then looks in the
  -- folder should not meet a name they have never seen without warning.
  --
  -- AND THE TWO WAYS THAT CAN END ARE NOW SAID SEPARATELY, which is round 50's
  -- should-fix. One sentence used to say that a folder ReaAssist could not
  -- MOVE and a folder it could not PUT BACK were both "left alone", and only
  -- the first of those is left alone: the second has already had everything
  -- ReaAssist was removing taken out of it, because the put-back is what
  -- happens at the END of the walk.
  t("copy.moved_aside", nil,
    "  ReaAssist moves each folder aside under a name of its own before it "
    .. "empties it, and holds a file open inside it so that nothing can take "
    .. "its place while it works. It puts each one back if anything inside "
    .. "has to stay.")
  t("copy.moved_aside_refused", nil,
    "  A folder it cannot move aside is left exactly as it is, with "
    .. "everything in it, and named in the report.")
  t("copy.moved_aside_stuck", nil,
    "  A folder it moved aside and then could not put back has already had "
    .. "everything ReaAssist was removing taken out of it. It stays beside "
    .. "where it was, under the name ReaAssist gave it, and the report names "
    .. "it there.")
  -- Named on the confirmation screen because it is the answer to the question
  -- the sentence above raises: what happens to those folders if this run never
  -- reaches its own end.
  t("copy.claim_journal", { path = tostring(plan.claim_journal_path or "") },
    "  ReaAssist writes down every folder it moves aside, here:\n    "
    .. tostring(plan.claim_journal_path or "") .. "\n  If the removal is "
    .. "interrupted, the next time ReaAssist starts it puts back every folder "
    .. "on that list whose own name is free again, and names the ones it "
    .. "cannot.")
  if plan.app_shape_from_manifest == false then
    -- Said here rather than discovered in the report. Without its own file
    -- list this run can account for one folder, so more will be left than
    -- usual, and the user is told that before they commit rather than after.
    t("copy.no_manifest", nil,
      "  ReaAssist could not read the list of files it installed, so it will "
      .. "leave more folders inside the application folder than usual and "
      .. "name every one of them in the report. Deleting the ReaAssist folder "
      .. "by hand afterwards finishes the job.")
  end
  t("copy.folder_itself", nil,
    "  The ReaAssist folder itself, and any folder still holding something "
    .. "when this finishes.")
  line("")
  t("copy.data_heading", nil, "Your ReaAssist data")
  line("")
  if plan.remove_user_data then
    t("copy.data_removed_intro", nil,
      "  You asked ReaAssist to remove this too, so it also removes "
      .. "everything in:")
    line("    " .. plan.data_dir)
    t("copy.data_removed_detail", nil,
      "  That is your settings, your saved keys, custom providers, saved "
      .. "chats, logs, caches, downloaded language packs and your custom "
      .. "system prompt, and it clears the values ReaAssist saved in "
      .. "REAPER's own settings file. Anything else you put in that folder "
      .. "goes with it. It cannot be undone.")
  else
    t("copy.data_kept_intro", nil, "  Left exactly where it is:")
    line("    " .. plan.data_dir)
    t("copy.data_kept_detail", nil,
      "  Settings, saved keys, custom providers, saved chats, logs and "
      .. "caches all stay. If you install ReaAssist again it picks them up.")
    if plan.custom_prompt_present then
      t("copy.custom_prompt_intro", nil,
        "  Your custom system prompt lives among the application files, so "
        .. "ReaAssist moves it first, to:")
      line("    " .. plan.custom_prompt_dest)
      t("copy.custom_prompt_stop", nil,
        "  If that move does not succeed, ReaAssist stops and removes "
        .. "nothing.")
    end
  end
  line("")
  -- Named on the confirmation screen rather than sprung in the report: after
  -- this runs, the ReaAssist actions stop starting ReaAssist, and the user is
  -- entitled to know that before they commit and to know how to undo it. All
  -- three of the note's states are described, including the one an interrupted
  -- run leaves, because that is the state whose way out is a manual step.
  t("copy.marker", { path = tostring(plan.marker_path or "") },
    "Before it removes anything, ReaAssist writes a note at the path below. "
    .. "While the removal is running the ReaAssist actions will not start the "
    .. "program at all. When it finishes, the note stays and nothing puts "
    .. "ReaAssist back on its own: running an action then asks whether to "
    .. "install ReaAssist again, and saying yes removes the note. If the "
    .. "removal is interrupted the note stays as it was and the actions keep "
    .. "refusing until you delete it yourself:\n    "
    .. tostring(plan.marker_path or ""))
  line("")
  t("copy.proof", nil,
    "ReaAssist checks every file after it deletes it and reports anything "
    .. "that would not go, with its full path. Nothing is called removed "
    .. "unless it is gone.")
  return table.concat(out, "\n")
end

-- Do it. Synchronous, because the whole job is a few dozen local file
-- operations and a tick-driven version would have to keep its own restartable
-- state on a disk it is in the middle of emptying.
--
-- The result table is the report: what went, what stayed and why, what each
-- launcher's answer was, and where it stopped if it stopped. Nothing in it is
-- inferred from an intention; every entry was probed.
function Updater.uninstall_execute(plan)
  local result = {
    ok = false,
    stopped = nil,
    removed = {},
    left = {},
    -- Files this process is HOLDING rather than files that refused. The two
    -- are different states and folding them together would report a clean run
    -- as a partial one for ever, because a running instance always holds its
    -- own life file. Each of these is asked again after the lock is handed
    -- back, and the ones that really went are moved to `removed`.
    in_use = {},
    launchers = {},
    -- data_removed means "nothing under Data/ is still there", and it is
    -- decided at the end from what the probes found rather than here from what
    -- the run intended. data_attempted is the user's choice, which is a
    -- different fact and gets its own field so the report can tell a complete
    -- removal from a partial one without inferring either.
    data_attempted = false,
    data_removed = false,
    -- The four ownership answers, kept apart. `reapack_left` means ReaPack
    -- owns something that stayed and nothing else; conflating foreign and
    -- unconfirmed into it is what made the report say ReaPack had installed
    -- files ReaPack has never seen.
    reapack_left = false,
    foreign_left = false,
    unknown_left = false,
    -- Action-list rows whose file went but whose registration would not.
    actions_left = {},
  }
  if type(plan) ~= "table" then
    result.stopped = "plan"
    return result
  end
  if Updater.uninstall_barrier() then
    result.stopped = "reentry"
    result.blockers = { {
      code = "reentry",
      message = Updater.uninstall_t("blocked.reentry", nil,
        "An uninstall has already run in this ReaAssist window. Close "
        .. "it and start REAPER again before doing anything else."),
    } }
    return result
  end
  result.plan = plan
  local advisory = Updater.uninstall_blockers()
  if #advisory > 0 then
    result.stopped = "blocked"
    result.blockers = advisory
    return result
  end
  if not Updater.acquire_apply_lock() then
    result.stopped = "lock"
    result.blockers = { Updater.uninstall_lock_blocker() }
    return result
  end
  -- ANYTHING AN EARLIER RUN LEFT MOVED ASIDE GOES BACK BEFORE THIS ONE STARTS,
  -- with the apply lock held, which is the only moment on this install when no
  -- other body is walking or journalling anything. The first tick of every
  -- session has almost certainly done it already; this is the backstop for a
  -- strand that appeared since, and it is the reason the run below never meets
  -- a folder from somebody else's interrupted walk.
  --
  -- It is not a gate. A folder that could not be put back is named rather than
  -- refused: it is beside the tree this run is removing, not in it.
  -- AND THIS ATTEMPT BEGINS WITH NOTHING IT DID NOT EARN. Every exit below
  -- forgets what it minted, and this is the backstop for an exit a later change
  -- forgets to give one to: whatever is in those tables when the lock is
  -- acquired belonged to something that is over, and an attempt that starts by
  -- emptying them cannot inherit an answer. It is asked HERE, before the
  -- recovery pass below, because that pass is the first act of the attempt that
  -- can write an authority of its own.
  Updater.uninstall_claim_attempt_forget()
  result.claims = Updater.uninstall_claim_recover()
  Updater._uninstall_running = true
  -- EVERY STOP CLEARS THE MARKER, whether or not anything was removed. A stop
  -- means this install is still meant to be usable: every refusal's copy tells
  -- the user to fix something and run the uninstall again, or to restart
  -- ReaAssist so startup recovery can run, and a marker left standing would
  -- turn both of those instructions into a second obstacle. The marker's job
  -- is to close the launcher's window for the length of the run, and a stop
  -- ends the run.
  local function stop(code, blockers)
    Updater._uninstall_running = false
    -- AND A CLEAR THAT DID NOT TAKE IS NOT SWALLOWED, which is round 49's
    -- second should-fix. A marker still standing after a refusal stops every
    -- launch on this install, and the refusal's own copy is about something
    -- else entirely, so the report has to say both or the user is left
    -- reading advice they cannot act on.
    if not Updater.uninstall_marker_clear() then
      result.marker_stuck = plan.marker_path
    end
    -- The list of folders this run moved aside goes with the marker, and only
    -- when nothing on it is still open. A stop that happened after a claim
    -- could not be put back leaves the list standing, which is exactly what the
    -- next session's consumer is for. What this run put back is accounted for
    -- first, because a put-back closes no record of its own any more.
    local _, stray_files = Updater.uninstall_claim_account()
    for _, path in ipairs(stray_files) do
      result.left[#result.left + 1] =
        { path = path, reason = "ReaAssist's own" }
    end
    Updater.uninstall_claim_journal_retire()
    -- AND THE ATTEMPT'S OWN AUTHORITY DIES HERE, after its accounting and never
    -- before it (round 59). A stop ends the attempt just as completion does:
    -- the marker comes down, the lock goes back, the folders are put down where
    -- they are, and the barrier will let this window try again. Anything this
    -- attempt minted would be an answer about a name it no longer holds.
    Updater.uninstall_claim_attempt_forget()
    Updater.release_apply_lock()
    result.stopped = code
    if blockers then result.blockers = blockers end
    return result
  end
  -- A walk that found somebody else's folder in its hands stops the run. This
  -- is asked after each of the three walks rather than inside them, so the
  -- refusal reads the same way every other refusal here does.
  local function breach_blockers()
    if not result.breach then return nil end
    -- TWO SHAPES, AND THEY ARE NOT THE SAME EVENT. The first is a link that was
    -- already standing at one of ReaAssist's own names when the walk reached
    -- it, and the rename followed it. The second is a name this run had already
    -- taken and proved, replaced while the run was working on it: there the
    -- folder's contents have already been processed, so a sentence promising
    -- that nothing was touched would be false of it.
    if result.breach.claim then
      return { {
        code = "breach",
        path = result.breach.path,
        message = Updater.uninstall_t("stopped.breach_claim",
          { path = tostring(result.breach.path or ""),
            moved = tostring(result.breach.moved or "") },
          "ReaAssist moves each folder aside under a name of its own before it "
          .. "empties it, and holds a file open inside it so that nothing can "
          .. "take its place. Something replaced the folder standing at one of "
          .. "those names anyway, so ReaAssist stopped and removed nothing "
          .. "more.\n\nThe folder ReaAssist was removing was here:\n"
          .. tostring(result.breach.path or "")
          .. "\n\nWhat ReaAssist could not prove is standing here now:\n"
          .. tostring(result.breach.moved or "")
          .. "\n\nLook at both of those names before you do anything else. "
          .. "ReaAssist stopped the moment it could not prove which folder was "
          .. "which, and it has removed nothing since."),
      } }
    end
    -- AND THE ONE FILE THIS RUN COULD HAVE PUT IN THERE IS NAMED WHEN IT IS
    -- STILL THERE. The seed goes in through the folder's own name, so a name
    -- that was a link put it inside the folder the rename carried off. It is
    -- taken back out on this path, and a sentence promising nothing in that
    -- folder was touched has to answer for the case where it would not go.
    local seed_note = ""
    if result.breach.stray then
      seed_note = "\n\n" .. Updater.uninstall_t("stopped.breach_seed",
        { path = tostring(result.breach.stray) },
        "ReaAssist put one file of its own in that folder before it found "
        .. "out, and could not take it back out again. It is the only thing "
        .. "ReaAssist put there, and it is here:\n"
        .. tostring(result.breach.stray))
    end
    return { {
      code = "breach",
      path = result.breach.path,
      message = Updater.uninstall_t("stopped.breach",
        { path = tostring(result.breach.path or ""),
          moved = tostring(result.breach.moved or "") },
        "One of ReaAssist's own folders was replaced by a link to another "
        .. "folder while the uninstall was running, so ReaAssist stopped and "
        .. "removed nothing more.\n\nIt happened at this name:\n"
        .. tostring(result.breach.path or "")
        .. "\n\nThe folder that link pointed at was moved here, and nothing "
        .. "in it was touched:\n" .. tostring(result.breach.moved or "")
        .. "\n\nPut that folder back where it belongs before you do anything "
        .. "else, then start the uninstall again.") .. seed_note,
    } }
  end
  -- THE LAUNCHER'S LANE IS CLOSED BEFORE THE AUTHORITATIVE GATE FINISHES.
  -- The gate below can see another instance that is already running; it cannot
  -- see a launcher that starts in another REAPER window a moment after it
  -- reads. That launcher would find the body present, take no lock, and start
  -- a live session on files this run then deletes. The marker is what it reads
  -- instead, and it is written FIRST so the gate itself runs behind it.
  --
  -- A marker that will not write is a stop with nothing removed, because
  -- without it this run cannot keep the promise its own copy makes.
  --
  -- IT GOES DOWN IN ITS ACTIVE PHASE. While that stands, a launcher in another
  -- REAPER window refuses outright and is never offered the reinstall
  -- question, so no answer anybody can give from over there clears the
  -- exclusion this run is relying on.
  if not Updater.uninstall_marker_write("active") then
    return stop("marker", { {
      code = "marker",
      path = plan.marker_path,
      message = Updater.uninstall_t("blocked.marker",
        { path = tostring(plan.marker_path or "") },
        "ReaAssist could not write the note that stops its actions from "
        .. "starting the program again while it is being removed, so it "
        .. "removed nothing.\n\nThe note belongs here:\n"
        .. tostring(plan.marker_path or "") .. "\n\nGive your account "
        .. "permission to write in that folder, then start the uninstall "
        .. "again."),
    } })
  end
  result.marker_path = plan.marker_path
  -- The authoritative gate. Taken with the lock held, so no other body can
  -- write a journal or quarantine a record between this and the first removal.
  local blockers = Updater.uninstall_blockers()
  if #blockers > 0 then return stop("blocked", blockers) end
  -- The user's own override sits among the application files, so it is rescued
  -- BEFORE anything is removed. A refusal here costs nothing, because nothing
  -- has been taken yet.
  if not plan.remove_user_data
      and RA.path_present(plan.custom_prompt_source) then
    if RA.path_present(plan.custom_prompt_dest) then
      return stop("custom_prompt", { {
        code = "custom_prompt",
        path = plan.custom_prompt_dest,
        message = Updater.uninstall_t("blocked.custom_prompt_occupied",
          { path = tostring(plan.custom_prompt_dest) },
          "Something is already at the name ReaAssist wanted to move "
          .. "your custom system prompt to, and it will not write over it. "
          .. "Nothing was removed.\n\nThe file in the way is here:\n"
          .. tostring(plan.custom_prompt_dest) .. "\n\nMove or rename it, "
          .. "then start the uninstall again."),
      } })
    end
    local moved = os.rename(plan.custom_prompt_source, plan.custom_prompt_dest)
    if not moved or not RA.path_present(plan.custom_prompt_dest) then
      return stop("custom_prompt", { {
        code = "custom_prompt",
        path = plan.custom_prompt_source,
        message = Updater.uninstall_t("blocked.custom_prompt_move",
          { path = tostring(plan.custom_prompt_source) },
          "ReaAssist could not move your custom system prompt out of "
          .. "the application folder, so it stopped and removed "
          .. "nothing.\n\nThe file is here:\n"
          .. tostring(plan.custom_prompt_source) .. "\n\nCopy it somewhere "
          .. "safe yourself, then start the uninstall again."),
      } })
    end
    result.custom_prompt_moved = plan.custom_prompt_dest
    result.mutated = true
  end
  -- 1. Recovery, first, so nothing can restore the body after step 3. The two
  -- questions that guard this folder are asked once more immediately before
  -- it, because they are the two that can turn a removal into the destruction
  -- of evidence or of somebody else's claim. Each stop names what IT found
  -- rather than re-running the whole gate, so a condition that cleared in the
  -- meantime cannot leave the report with nothing to say.
  local quarantine = Updater.journal_quarantined()
  if quarantine then
    return stop("quarantine", { {
      code = "quarantine",
      path = quarantine,
      message = Updater.uninstall_t("stopped.quarantine",
        { path = tostring(quarantine) },
        "A record of an unfinished update appeared while the "
        .. "uninstall was starting, and it is the only description of which "
        .. "files that update changed. ReaAssist stopped rather than delete "
        .. "it.\n\nThe record is here:\n" .. tostring(quarantine)
        .. "\n\nRestart ReaAssist and take the repair it offers, then run the "
        .. "uninstall again."),
    } })
  end
  local launcher_lock = Updater.uninstall_launcher_lock_path()
  if launcher_lock then
    return stop("launcher_lock", { {
      code = "launcher_lock",
      path = launcher_lock,
      message = Updater.uninstall_t("stopped.launcher_lock",
        { path = tostring(launcher_lock) },
        "A ReaAssist launcher claimed this install while the "
        .. "uninstall was starting. That claim is the launcher's, so "
        .. "ReaAssist stopped rather than remove it.\n\nThe claim is here:\n"
        .. tostring(launcher_lock) .. "\n\nClose any other REAPER window that "
        .. "is starting ReaAssist and try again."),
    } })
  end
  result.mutated = true
  -- Recovery is walked with no shape. It is the launcher's folder end to end,
  -- created and filled only by the launcher, and the parked and candidate
  -- copies mirror whatever version was current when they were written, which
  -- is not a shape this body is entitled to author. Containment here is rule
  -- one: no directory under it is entered until the filesystem has refused to
  -- remove it outright.
  Updater.uninstall_remove_tree(plan.recovery_dir, nil, result)
  local breach = breach_blockers()
  if breach then return stop("breach", breach) end
  -- AND THE PARKED COPY HAS TO BE GONE BEFORE THE BODY IS. Recovery/Body is
  -- the launcher's local copy of the whole application, and a launcher that
  -- finds the body missing restores from it without asking. Removing the body
  -- while that copy still stands would hand the next launch everything it
  -- needs to put ReaAssist back, which is an uninstall the user watches
  -- succeed and then sees undone. Every other leftover under Recovery/ is
  -- inert; this one is not, so it is the one that stops the run.
  --
  -- IT IS ASKED AT THE PUBLIC NAME BECAUSE THAT IS THE ONLY NAME THAT MATTERS.
  -- A launcher restores from Recovery/Body and from nowhere else, so a copy
  -- this walk had to move aside and could not put back is not a copy any
  -- launcher can find. It is still named in the report, because the user is
  -- owed the path, but it is not a reason to stop.
  if RA.path_present(plan.recovery_dir .. "Body") then
    return stop("parked_copy", { {
      code = "parked_copy",
      path = plan.recovery_dir .. "Body",
      message = Updater.uninstall_t("stopped.parked_copy",
        { path = tostring(plan.recovery_dir .. "Body") },
        "ReaAssist could not remove the repair copy it keeps of "
        .. "itself, and it will not remove the program while that copy is "
        .. "still there: the next time you started REAPER it would put "
        .. "ReaAssist back.\n\nThe copy is here:\n"
        .. tostring(plan.recovery_dir .. "Body") .. "\n\nThe actions you "
        .. "start ReaAssist from have not been touched. Delete that folder "
        .. "yourself, then run the uninstall again."),
    } })
  end
  -- 2. The launchers. Confirmed unowned at plan time is not enough: the answer
  -- is taken again here, immediately before the delete, from ReaPack rather
  -- than from the session cache.
  for _, entry in ipairs(plan.launchers or {}) do
    local rec = {
      name = entry.name,
      path = entry.path,
      ownership = entry.ownership,
    }
    -- One answer, one flag, one sentence. FOREIGN is not ReaPack's and
    -- UNKNOWN is not anybody's until it is confirmed, so neither of them may
    -- reach the ReaPack sentence in the report.
    local function record_left(state)
      rec.action = "left"
      if state == Updater.OWNERSHIP_OWNED then
        result.reapack_left = true
      elseif state == Updater.OWNERSHIP_FOREIGN then
        result.foreign_left = true
      else
        result.unknown_left = true
      end
      result.left[#result.left + 1] = { path = entry.path, reason = state }
    end
    if not entry.removable then
      record_left(entry.ownership)
    else
      local writable, state, detail = Updater.launcher_writable_now(entry.name)
      rec.ownership = state
      rec.detail = detail
      if not writable then
        record_left(state)
      elseif not RA.path_present(entry.path) then
        rec.action = "absent"
      elseif Updater.uninstall_remove_file(entry.path) then
        rec.action = "removed"
        result.removed[#result.removed + 1] = entry.path
        -- The action registration goes with the file it pointed at. Left
        -- behind it is a row in REAPER's action list that can only fail.
        --
        -- AND A REFUSAL HERE IS REPORTED RATHER THAN SWALLOWED. The file is
        -- already gone by this point, so there is nothing to undo and nothing
        -- to stop for; what there is, is a row in REAPER's action list that
        -- the user now has to remove by hand, and only the report can tell
        -- them so. The refusal signal is REAPER's own documented one and is
        -- not invented here: AddRemoveReaScript answers with the command id
        -- and with 0 when it failed, so 0, false and nil are the failures and
        -- everything else is the API saying it did the work. A call that
        -- raised, and a REAPER too old to have the entry point at all, are
        -- refusals for the same reason.
        if type(reaper.AddRemoveReaScript) == "function" then
          local called, answer =
            pcall(reaper.AddRemoveReaScript, false, 0, entry.path, true)
          local cleared = called and answer ~= 0 and answer ~= false
            and answer ~= nil
          rec.unregistered = cleared and true or false
          if not cleared then
            result.actions_left[#result.actions_left + 1] = entry.path
          end
        else
          rec.unregistered = false
          result.actions_left[#result.actions_left + 1] = entry.path
        end
      else
        rec.action = "refused"
        result.left[#result.left + 1] =
          { path = entry.path, reason = "refused" }
      end
    end
    result.launchers[#result.launchers + 1] = rec
  end
  -- 3. The body. The containment answer is taken again rather than trusted
  -- from the plan, because this is the step that removes a whole tree and the
  -- step before it removed the launchers the two roots are told apart by.
  local layout_ok, layout_why = Updater.uninstall_layout()
  if not layout_ok then
    return stop("layout", { {
      code = "layout",
      detail = layout_why,
      path = plan.app_dir,
      message = Updater.uninstall_t("stopped.layout",
        { path = tostring(plan.app_dir) },
        "ReaAssist stopped before removing its application files, "
        .. "because it can no longer tell that folder apart from the folder "
        .. "that holds it, and removing one could remove the other.\n\nThe "
        .. "folder is here:\n" .. tostring(plan.app_dir) .. "\n\nClose REAPER "
        .. "and delete the ReaAssist folder by hand to finish."),
    } })
  end
  -- The application tree IS walked to a shape, because this is the one tree
  -- whose contents this release describes: the shape is the set of folders the
  -- body's own manifest installs into, frozen at plan time. A folder inside
  -- App/ that this release does not install is left where it is with
  -- everything in it, and named.
  -- A plan that reached here without a shape is a programming error, not a
  -- user state, and the fail-closed answer to it is to derive one rather than
  -- to walk with none: App/ and its manifest are both still intact at this
  -- point, because only Recovery and the launchers have gone.
  Updater.uninstall_remove_tree(plan.app_dir,
    { shape = plan.app_shape or Updater.uninstall_app_shape() }, result)
  breach = breach_blockers()
  if breach then return stop("breach", breach) end
  -- 4. User data, and only when it was asked for. The lock this run is holding
  -- lives in here and stays until the lock is given back; so does the life
  -- file this process holds open, which the operating system will not release
  -- while ReaAssist is running.
  if plan.remove_user_data then
    pcall(function()
      if Theme and Theme.restore_backups then Theme.restore_backups() end
    end)
    pcall(function()
      if RA.clear_theme_backup_extstate then RA.clear_theme_backup_extstate() end
    end)
    pcall(function()
      if RA.delete_extstate_section then RA.delete_extstate_section(CFG.EXT_NS) end
    end)
    pcall(function()
      reaper.DeleteExtState(CFG.EXT_NS, "running", false)
      reaper.DeleteExtState(CFG.EXT_NS, "request_close", false)
    end)
    local keep = {}
    keep[tostring(tmp.update_lock)] = "in use"
    keep[tostring(tmp.update_lock) .. ".d"] = "in use"
    keep[tostring(RA.temp_life_path())] = "in use"
    keep[tostring(RA.temp_live_marker_path())] = "in use"
    -- Data is walked with no shape, because the offer the user accepted is
    -- "everything in this folder" and a shape would be this body deciding
    -- which of the user's own files count. Containment here is rule one, the
    -- claim and the pin, and this is the tree where the pin does the work:
    -- the life file this process holds open lives under Data/Temp, and on
    -- Windows that one handle is what refuses the claim of both folders and
    -- what makes their names unswappable for everybody at the same time.
    result.data_attempted = true
    local data_left_from = #result.left + 1
    Updater.uninstall_remove_tree(plan.data_dir, {
      skip = function(path) return keep[tostring(path)] end,
    }, result)
    -- MARKED HERE RATHER THAN MATCHED BY PATH LATER. A folder this walk had to
    -- move aside and could not put back is named by the name it has NOW, which
    -- is not under Data/ any more, and a path test would read it as somebody
    -- else's leftover and call the data removal complete.
    for i = data_left_from, #result.left do
      result.left[i].from_data = true
    end
    local data_breach = breach_blockers()
    if data_breach then return stop("breach", data_breach) end
    -- Split the holds out of the refusals before anything reads either list.
    local refused = {}
    for _, item in ipairs(result.left) do
      if item.reason == "in use" then
        result.in_use[#result.in_use + 1] = item
      else
        refused[#refused + 1] = item
      end
    end
    result.left = refused
  end
  Updater._uninstall_running = false
  Updater._uninstalled = true
  -- The list of folders this run moved aside is taken away only when every one
  -- of them was put back or removed. One that is still standing keeps the list
  -- standing with it, so the next session's consumer finds it.
  --
  -- AND THE ACCOUNTING IS DONE HERE, ONCE, OVER THE WHOLE LIST, because no
  -- put-back closes its own record any more (round 54's first blocker). A
  -- record this run put back is retired when the private name is free and the
  -- folder's own name is BOUND to the file this run put inside the folder
  -- (round 55's first blocker); a link standing there is TAKEN by that question
  -- and keeps the record instead, and so does anything this side cannot bind.
  local _, stranded = Updater.uninstall_claim_account()
  for _, path in ipairs(stranded) do
    result.left[#result.left + 1] = { path = path, reason = "ReaAssist's own" }
  end
  result.claims_left = not Updater.uninstall_claim_journal_retire()
  -- AND THE ATTEMPT'S OWN AUTHORITY DIES HERE TOO, after the accounting above
  -- and never before it. Nothing below this line asks a claim question, the
  -- barrier refuses another attempt in this window from here on, and a table
  -- kept past the end of the run it belongs to is an answer waiting for a
  -- question nobody may ask again.
  Updater.uninstall_claim_attempt_forget()
  Updater.release_apply_lock()
  -- The lock artifact was this run's own and release took it, so the holds are
  -- asked again rather than reported from what was true before. Whatever is
  -- really gone stops being a leftover; whatever is still there stays named.
  if #result.in_use > 0 then
    local still = {}
    for _, item in ipairs(result.in_use) do
      if RA.path_present(item.path) then
        still[#still + 1] = item
      else
        result.removed[#result.removed + 1] = item.path
      end
    end
    result.in_use = still
  end
  -- Whatever is left of the two folders the lock lived in is only removable if
  -- it is empty, and the removal proves that rather than assuming it.
  -- The presence probe first, so a folder the walk above already took is not
  -- asked about twice. Since B2.4g the removal answers "gone" rather than true
  -- for a name that is not there, so the probe is no longer what keeps this
  -- tally honest; it is kept because asking a removal about a name this run has
  -- already taken is a question with nothing behind it.
  if plan.remove_user_data then
    if RA.path_present(plan.temp_dir)
        and Updater.uninstall_remove_empty_dir(plan.temp_dir) then
      result.removed[#result.removed + 1] = plan.temp_dir
    end
    if RA.path_present(plan.data_dir)
        and Updater.uninstall_remove_empty_dir(plan.data_dir) then
      result.removed[#result.removed + 1] = plan.data_dir
    end
  end
  -- AND ONLY NOW IS THE DATA ANSWER DECIDED. It used to be set the moment the
  -- walk had been attempted, which made "your data was removed" a statement
  -- about an intention rather than about the disk: a file that refused to go,
  -- a folder somebody else created, or a hold this process could not release
  -- all left data behind while the report said there was none. The answer is
  -- taken from the probes, after the last of them, and it is true only when
  -- nothing under Data/ is still named as left or still held.
  if plan.remove_user_data then
    local residue = false
    for _, item in ipairs(result.left) do
      if item.from_data then residue = true end
    end
    for _, item in ipairs(result.in_use) do
      if item.from_data then residue = true end
    end
    result.data_removed = not residue
  end
  -- AND NOTHING THIS WINDOW DOES FROM HERE MAY WRITE INTO THE INSTALL AGAIN.
  -- Two automatic writers outlive the run: the window geometry saved on close
  -- and the Gemini cache reference persisted at exit. Either would recreate
  -- the Data folder moments after the report said it was gone, so both are
  -- stood down the way Factory Reset stands the first one down.
  if S then
    S._suppress_geometry_save = true
    S.gemini_cache_name = nil
  end
  result.ok = true
  Log.line("UPDATE", string.format(
    "uninstall: removed %d entries, left %d, user data %s",
    #result.removed, #result.left,
    plan.remove_user_data and "removed" or "kept"))
  -- AND THE MARKER MOVES TO ITS DONE PHASE HERE, LAST OF ALL. Everything above
  -- this line can still write or remove something, the log line included, and
  -- the done phase is what tells a launcher in another window that it may
  -- offer to put ReaAssist back. Offering that while anything is still moving
  -- is the whole of round 49's first finding, so the flip comes after the last
  -- of it rather than beside the report.
  --
  -- A FLIP THAT WOULD NOT WRITE LEAVES THE ACTIVE MARKER, which refuses every
  -- launch on this install, so the report says so and gives the way out.
  result.marker_phase =
    Updater.uninstall_marker_write("done") and "done" or "active"
  return result
end

-- The report the user reads afterwards. Same two rules as the confirmation
-- copy: it says what happened to everything, and it claims nothing it did not
-- probe for.
function Updater.uninstall_result_copy(result)
  if type(result) ~= "table" then return "" end
  local out = {}
  local function line(s) out[#out + 1] = s end
  local function t(key, values, fallback)
    line(Updater.uninstall_t(key, values, fallback))
  end
  -- A NOTE THAT WOULD NOT COME BACK OFF IS ITS OWN PROBLEM AND GETS ITS OWN
  -- PARAGRAPH, in both stopped shapes. Every refusal's copy ends by telling
  -- the user to fix something and run the uninstall again, or to restart
  -- ReaAssist, and a note still standing turns both of those into instructions
  -- that cannot be followed: the actions will not start the program while it
  -- is there. Saying only the original refusal would be the report keeping a
  -- secret about the state it left behind.
  local function marker_stuck_block()
    if not result.marker_stuck then return end
    line("")
    t("result.marker_stuck", { path = tostring(result.marker_stuck) },
      "ReaAssist could not take back the note it wrote when it started, and "
      .. "while that note is on disk the ReaAssist actions will not start "
      .. "ReaAssist at all.\n\nThe note is here:\n  "
      .. tostring(result.marker_stuck)
      .. "\n\nDelete that file yourself to use ReaAssist again.")
  end
  -- FOLDERS AN EARLIER RUN LEFT MOVED ASIDE, and what this one could do about
  -- them. Only ever present when a removal on this install died partway and
  -- this run met what it left, and then this is the only place the user hears
  -- about it, because the putting back happened before this run started rather
  -- than inside its own walk.
  local function claims_block()
    local claims = result.claims
    if type(claims) ~= "table" then return end
    if #(claims.left or {}) > 0 then
      local names = {}
      for _, item in ipairs(claims.left) do
        names[#names + 1] = "  " .. tostring(item.path)
      end
      line("")
      t("result.claims_left", { paths = table.concat(names, "\n") },
        "An earlier ReaAssist removal on this install was interrupted. These "
        .. "folders it had moved aside could not be put back, because "
        .. "something else is at the name each of them belongs at, and what is "
        .. "in them is still there:\n" .. table.concat(names, "\n"))
    end
    -- AND THE FOLDERS THAT LIST NAMES WHICH ARE NOT WHERE IT SAYS. Round 52:
    -- an absent name is not a resolution, so these records are kept rather than
    -- erased, and the only thing left that can help is saying which folders
    -- they are.
    if #(claims.lost or {}) > 0 then
      local missing, carried, unproven = {}, {}, {}
      local redirected, unaccounted, unbindable = {}, {}, {}
      local matched, superseded = {}, {}
      for _, item in ipairs(claims.lost) do
        if tostring(item.reason) == "breach" then
          carried[#carried + 1] = "  " .. tostring(item.public)
          carried[#carried + 1] = "  " .. tostring(item.path)
        elseif tostring(item.reason) == "unproven" then
          unproven[#unproven + 1] = "  " .. tostring(item.public)
        elseif tostring(item.reason) == "redirected" then
          redirected[#redirected + 1] = "  " .. tostring(item.public)
        elseif tostring(item.reason) == "unaccounted" then
          unaccounted[#unaccounted + 1] = "  " .. tostring(item.public)
        elseif tostring(item.reason) == "unbindable" then
          unbindable[#unbindable + 1] = "  " .. tostring(item.public)
        elseif tostring(item.reason) == "matched" then
          matched[#matched + 1] = "  " .. tostring(item.public)
            .. "  (" .. tostring(item.probe) .. ")"
        elseif tostring(item.reason) == "superseded" then
          superseded[#superseded + 1] = "  " .. tostring(item.public)
          superseded[#superseded + 1] = "  " .. tostring(item.partner)
        else
          missing[#missing + 1] = "  " .. tostring(item.public)
        end
      end
      -- AND THE FOLDERS WHOSE OWN NAME ANSWERED EVERY QUESTION AND KEPT THEIR
      -- RECORD ANYWAY. Round 57: the value the question is asked against is on
      -- the list, so no later session closes a record on an answer to it.
      --
      -- AND THE FOUR MESSAGES BELOW SAY WHAT THEIR OWN CHECK DID AND NOTHING
      -- ABOUT THE SESSION, which is round 59's should-fix and the same change
      -- the startup message carries. The pass that produced this summary puts
      -- an inherited parent back to its own name and re-spells every record
      -- below it, so the folder a child record names here may be one this very
      -- pass renamed with everything inside it. Each message says what its own
      -- last question found, touched and did not touch, and none of them denies
      -- anything on the session's behalf.
      if #matched > 0 then
        line("")
        t("result.claims_matched",
          { paths = table.concat(matched, "\n"),
            journal = tostring(claims.journal or "") },
          "An earlier ReaAssist removal on this install was interrupted, and "
          .. "nothing is standing under the names it had moved these folders "
          .. "aside to:\n" .. table.concat(matched, "\n")
          .. "\n\nSomething is standing at each folder's own name and it holds "
          .. "a file carrying the value ReaAssist wrote down for the folder it "
          .. "moved aside, which is what a folder that had been put back would "
          .. "look like. ReaAssist will not take the line off its list for "
          .. "that: the value it checks that file against is written in the "
          .. "list itself, so anything that can read the list can put a file "
          .. "carrying it inside a folder of its own. That check renamed "
          .. "nothing and removed nothing: what it did was open the file it "
          .. "asks about inside the folder, add to that file and read it back, "
          .. "and ask the folder's own name questions that leave the name as "
          .. "they find it. It touched nothing else in the folder. "
          .. "Any name in brackets is the file "
          .. "ReaAssist asks about inside that folder. It keeps the list "
          .. "here:\n  "
          .. tostring(claims.journal or ""))
      end
      -- AND THE LINES ANOTHER LINE ON THE SAME LIST DESCRIBES THE SAME FOLDER
      -- AS, which is the pair a crash in the middle of a parent put-back
      -- leaves. Neither is closed on the other, for the same reason.
      if #superseded > 0 then
        line("")
        t("result.claims_superseded",
          { paths = table.concat(superseded, "\n"),
            journal = tostring(claims.journal or "") },
          "An earlier ReaAssist removal on this install was interrupted, and "
          .. "nothing is standing under the names it had moved these folders "
          .. "aside to. Another line on the same list describes each of them "
          .. "under a second name of ReaAssist's own, and a folder is standing "
          .. "there. Each folder's own name comes first below and the name a "
          .. "folder is standing under comes second:\n"
          .. table.concat(superseded, "\n")
          .. "\n\nReaAssist keeps both lines rather than deciding which one is "
          .. "finished, because what it can check either of them against is "
          .. "written in the list itself. Neither check renamed anything or "
          .. "removed anything: each one looked inside for the file ReaAssist "
          .. "asks about there and, where what it found carried the value "
          .. "ReaAssist wrote down, added to that file and read it back, and "
          .. "each asked the name it was standing at questions that leave the "
          .. "name as they find it. They touched nothing else in either "
          .. "folder. It keeps the list here:\n  "
          .. tostring(claims.journal or ""))
      end
      -- AND THE FOLDERS WHOSE OWN NAME REFUSED THE QUESTION FOR A REASON THAT
      -- IS NOT REAASSIST'S. Round 56: a refusal is not a pin, and the platform
      -- gives one word for a permission, for another program's lock and for
      -- this side's own handle alike, so a name that refuses before ReaAssist
      -- holds anything is one it cannot ask about at all.
      if #unbindable > 0 then
        line("")
        t("result.claims_unbindable",
          { paths = table.concat(unbindable, "\n"),
            journal = tostring(claims.journal or "") },
          "An earlier ReaAssist removal on this install was interrupted, and "
          .. "nothing is standing under the names it had moved these folders "
          .. "aside to:\n" .. table.concat(unbindable, "\n")
          .. "\n\nSomething is standing at each folder's own name and it "
          .. "refused ReaAssist's question for a reason of its own, which is "
          .. "usually a permission or another program holding it open, so "
          .. "ReaAssist cannot tell you whether it is the folder it had moved "
          .. "aside. The question renamed nothing and removed nothing: the "
          .. "most it can do at a name that refuses it is open the file "
          .. "ReaAssist asks about inside the folder and add to that file, and "
          .. "it touched nothing else. It "
          .. "keeps the list here:\n  " .. tostring(claims.journal or ""))
      end
      -- AND THE FOLDERS WHOSE OWN NAME IS OCCUPIED BY SOMETHING THIS SIDE
      -- CANNOT BIND TO THEM. Round 55: an occupied name is not evidence about
      -- the folder that belongs at it, so the record is kept and the report
      -- says exactly what is and is not known.
      if #unaccounted > 0 then
        line("")
        t("result.claims_unaccounted",
          { paths = table.concat(unaccounted, "\n"),
            journal = tostring(claims.journal or "") },
          "An earlier ReaAssist removal on this install was interrupted, and "
          .. "nothing is standing under the names it had moved these folders "
          .. "aside to:\n" .. table.concat(unaccounted, "\n")
          .. "\n\nSomething "
          .. "is standing at each folder's own name, and ReaAssist cannot tell "
          .. "you whether it is the folder it had moved aside. The check "
          .. "renamed nothing and removed nothing: it looked inside for the "
          .. "file ReaAssist asks about there and, where what it found carried "
          .. "the value ReaAssist wrote down, added to that file and read it "
          .. "back, and it asked the folder's own name questions that leave the "
          .. "name as they find it. It touched nothing else in the folder. It "
          .. "keeps the list here:\n  "
          .. tostring(claims.journal or ""))
      end
      -- AND THE ONE THAT PROMISED WHAT THE LIST CANNOT SUPPORT (round 57). A
      -- folder somebody carried away, a link ReaAssist removed from one of the
      -- two names, and a folder ReaAssist emptied, could not bind and took the
      -- empty name of all arrive here, and nothing on the list tells them
      -- apart. The uncertainty is said, and the bound on it is that every
      -- removal this lane makes is non-recursive.
      --
      -- AND IT PROMISES NOTHING ABOUT THE CONTENTS (round 58). The bound is on
      -- the act that took the NAME. Under Data the walk has no ownership shape
      -- and empties the folder file by file before its name is ever taken, so a
      -- sentence saying what was in the folder is still where it was would be
      -- false in the tree this package is likeliest to be uninstalling.
      if #missing > 0 then
        line("")
        t("result.claims_lost", { paths = table.concat(missing, "\n"),
          journal = tostring(claims.journal or "") },
          "An earlier ReaAssist removal on this install was interrupted, and "
          .. "ReaAssist cannot find these folders where it had moved them "
          .. "aside:\n" .. table.concat(missing, "\n")
          .. "\n\nWhat became of them after that is not something ReaAssist can "
          .. "tell from here. Something else may have moved or replaced them, "
          .. "and one of ReaAssist's own acts may have taken the name: a "
          .. "removal that has emptied a folder finishes by taking the empty "
          .. "folder, and a link found standing at either of the two names "
          .. "ReaAssist knows for one of these folders is removed rather than "
          .. "followed. Neither of those can take anything that is inside a "
          .. "folder. What a removal had already taken out of one of these "
          .. "folders before it was interrupted is not on this list, which "
          .. "carries what ReaAssist moved and never what it removed, so what "
          .. "is inside one of them now is not something ReaAssist can tell you "
          .. "from here. ReaAssist keeps the list here:\n  "
          .. tostring(claims.journal or ""))
      end
      -- AND THE CELL WHERE THE PUT-BACK'S OWN RENAME MOVED SOMETHING. It
      -- followed a link that had been put at the name the folder was moved
      -- aside to, so a folder from outside this install is standing at the
      -- folder's own name because ReaAssist put it there. Nothing above is
      -- true of that, so it is said on its own.
      if #carried > 0 then
        line("")
        t("result.claims_breach", { paths = table.concat(carried, "\n"),
          journal = tostring(claims.journal or "") },
          "An earlier ReaAssist removal on this install was interrupted, and "
          .. "when ReaAssist went to put a folder back, the name it had moved "
          .. "that folder to had been replaced with a link to somewhere else. "
          .. "Windows follows a link when it renames one, so ReaAssist's own "
          .. "rename moved what that link pointed at. A folder that is not "
          .. "ReaAssist's is standing at the first name below, and the link is "
          .. "still standing at the second, where ReaAssist left it alone:\n"
          .. table.concat(carried, "\n") .. "\n\nReaAssist deleted nothing. "
          .. "The folder ReaAssist had moved aside is at neither name and "
          .. "ReaAssist cannot tell you where it is. The folder that was "
          .. "carried in came from wherever that link points, which is where "
          .. "it was until the rename. ReaAssist keeps the list here:\n  "
          .. tostring(claims.journal or ""))
      end
      -- AND THE CELL WHERE THE PUT-BACK'S RENAME LANDED ON SOMETHING IT COULD
      -- NOT PROVE. The move happened and what it moved cannot be called the
      -- folder, which is neither of the two above.
      if #unproven > 0 then
        line("")
        t("result.claims_unproven", { paths = table.concat(unproven, "\n"),
          journal = tostring(claims.journal or "") },
          "An earlier ReaAssist removal on this install was interrupted, and "
          .. "when ReaAssist went to put a folder back its own rename landed "
          .. "on something ReaAssist cannot prove is the folder. What is "
          .. "standing at each name below arrived there through that rename, "
          .. "and ReaAssist can tell you neither that it is the folder it had "
          .. "moved aside nor where that folder is now. ReaAssist deleted "
          .. "nothing:\n" .. table.concat(unproven, "\n")
          .. "\n\nReaAssist keeps the list here:\n  "
          .. tostring(claims.journal or ""))
      end
      -- AND THE CELL WHERE THE PUT-BACK LANDED AND THE FOLDER'S OWN NAME HAD
      -- BECOME A LINK BY THE TIME ReaAssist LOOKED AT IT AGAIN (B2.4g). The
      -- rename really did put the folder back, so this is neither a folder that
      -- was never found nor a rename that moved a stranger's folder.
      if #redirected > 0 then
        line("")
        t("result.claims_redirected",
          { paths = table.concat(redirected, "\n"),
            journal = tostring(claims.journal or "") },
          "An earlier ReaAssist removal on this install was interrupted, and "
          .. "ReaAssist's own rename did put these folders back. By the time "
          .. "it looked at each folder's own name again, that name was a link "
          .. "to somewhere else rather than the folder, so something other "
          .. "than ReaAssist moved the folder on in between. ReaAssist removed "
          .. "the link, left everything it pointed at alone, and deleted "
          .. "nothing else:\n" .. table.concat(redirected, "\n")
          .. "\n\nWhere each folder is now is not something ReaAssist can tell "
          .. "you. ReaAssist keeps the list here:\n  "
          .. tostring(claims.journal or ""))
      end
    end
    -- LINES ON THAT LIST THIS INSTALL COULD NOT HAVE WRITTEN. Nothing on
    -- this side wrote them, so nothing on this side acted on them, and saying
    -- so is the only honest thing left: the file is the user's to look at and
    -- ReaAssist has left it exactly as it found it.
    if #(claims.foreign or {}) > 0 then
      local strangers = {}
      for _, item in ipairs(claims.foreign) do
        strangers[#strangers + 1] = "  " .. tostring(item.public)
        strangers[#strangers + 1] = "  " .. tostring(item.path)
      end
      line("")
      t("result.claims_foreign", { paths = table.concat(strangers, "\n"),
        journal = tostring(claims.journal or "") },
        "The list ReaAssist keeps of folders it has moved aside carries lines "
        .. "ReaAssist could not have written. Nothing was moved and nothing "
        .. "was deleted for those lines, and they were left exactly as they "
        .. "are:\n" .. table.concat(strangers, "\n") .. "\n\nThe list is "
        .. "here:\n  " .. tostring(claims.journal or ""))
    end
  end
  -- THE ONE FILE A WALK CAN LEAVE SOMEWHERE IT CANNOT REACH. ReaAssist writes a
  -- file of its own inside a folder before it can know whether the name is a
  -- real folder or a link to somewhere else, and it asks the question straight
  -- afterwards. When the answer is "a link", the link is removed and everything
  -- it pointed at is left alone, but the file has already gone through it into
  -- that folder and there is no path from here to it any more. It is named
  -- rather than left for the user to find.
  local function link_seed_block()
    if #(result.link_seeds or {}) == 0 then return end
    local names = {}
    for _, item in ipairs(result.link_seeds) do
      names[#names + 1] = "  " .. tostring(item.path)
        .. "  (" .. tostring(item.leaf) .. ")"
    end
    line("")
    t("result.link_seeds", { paths = table.concat(names, "\n") },
      "ReaAssist puts one file of its own inside a folder before it can tell "
      .. "whether the name is a folder or a link to somewhere else. These "
      .. "names turned out to be links, so ReaAssist removed the link and left "
      .. "everything it pointed at alone, and its own file is inside the "
      .. "folder each link pointed at. It is the only thing ReaAssist put "
      .. "there, and it cannot reach it to take it back. The name, and the "
      .. "file:\n" .. table.concat(names, "\n"))
  end
  -- A FOLDER THIS RUN MOVED ASIDE AND THEN COULD NOT FIND. It asks the same
  -- question of the name it is putting a folder back from that it asks of the
  -- name it took it from, and an answer of "a link" means the folder is not
  -- there any more. Nothing was renamed and nothing was deleted, and where the
  -- folder went is not a question this side can answer.
  local function claim_lost_block()
    if #(result.claim_lost or {}) == 0 then return end
    local names, carried, vanished, unproven = {}, {}, {}, {}
    local redirected = {}
    for _, item in ipairs(result.claim_lost) do
      -- The one file of this run's that went through the link before the
      -- question could be asked is named beside the folder, exactly as the
      -- walker's own link answer names its seed.
      local named = "  " .. tostring(item.path)
        .. (item.probe and ("  (" .. tostring(item.probe) .. ")") or "")
      if tostring(item.reason) == "breach" then
        carried[#carried + 1] = named
        carried[#carried + 1] = "  " .. tostring(item.moved)
      elseif tostring(item.reason) == "vanished" then
        vanished[#vanished + 1] = named
      elseif tostring(item.reason) == "unproven" then
        unproven[#unproven + 1] = named
      elseif tostring(item.reason) == "redirected" then
        redirected[#redirected + 1] = named
      else
        names[#names + 1] = named
      end
    end
    if #names > 0 then
      line("")
      t("result.claim_lost", { paths = table.concat(names, "\n") },
        "ReaAssist moves a folder aside under a name of its own before it "
        .. "empties it, and when it went to put these back the name it had "
        .. "moved them to was a link to somewhere else rather than the folder. "
        .. "ReaAssist removed the link, left everything it pointed at alone, "
        .. "and moved nothing. Where these folders are now is not something "
        .. "ReaAssist can tell you. Any name in brackets is a file of "
        .. "ReaAssist's own that went through the link before it could be "
        .. "asked about, and ReaAssist cannot reach it to take it back:\n"
        .. table.concat(names, "\n"))
    end
    -- AND THE CELL WHERE THE RENAME ITSELF MOVED SOMETHING. A link put at the
    -- private name in the instant before the rename is followed by the rename,
    -- so this run moved a folder from outside the install onto one of its own
    -- names. Saying it moved nothing would be the one untrue sentence in this
    -- report, and it is the sentence round 53 found here.
    if #carried > 0 then
      line("")
      t("result.claim_breach", { paths = table.concat(carried, "\n") },
        "ReaAssist moves a folder aside under a name of its own before it "
        .. "empties it, and when it went to put these back the name it had "
        .. "moved them to had been replaced with a link to somewhere else. "
        .. "Windows follows a link when it renames one, so ReaAssist's own "
        .. "rename moved what that link pointed at: a folder that is not "
        .. "ReaAssist's is standing at the first name below, and the link is "
        .. "still standing at the second, where ReaAssist left it alone. "
        .. "ReaAssist deleted nothing. The folder ReaAssist had moved aside is "
        .. "at neither name and ReaAssist cannot tell you where it is, and any "
        .. "name in brackets is a file of ReaAssist's own that went with it. "
        .. "The folder that was carried in came from wherever that link points, "
        .. "which is where it was until the rename:\n"
        .. table.concat(carried, "\n"))
    end
    -- AND THE CELL WHERE THE NAME ITSELF WENT. Nothing was renamed and nothing
    -- was removed BY THE PUT-BACK: the name this run had the folder under
    -- stopped being there while this run was working on it.
    --
    -- AND THE DENIAL NAMES THAT ACT RATHER THAN THE WHOLE RUN (round 60's
    -- should-fix, and B2.4l's line taken to its last cell). This run DID move
    -- the folder aside, which the sentence before this one says, so a bare
    -- "ReaAssist moved nothing" here contradicted it. What moved nothing and
    -- removed nothing is the put-back that failed: its rename did not happen,
    -- and the one thing it can take at that name, a link standing in the
    -- folder's place, was not there for it to take.
    if #vanished > 0 then
      line("")
      t("result.claim_vanished", { paths = table.concat(vanished, "\n") },
        "ReaAssist moves a folder aside under a name of its own before it "
        .. "empties it, and the name it had moved these to was gone before "
        .. "ReaAssist had finished with them. Something other than ReaAssist "
        .. "took it away. The put-back that failed moved nothing and removed "
        .. "nothing: its rename did not happen, and nothing standing at that "
        .. "name was taken. Where these folders are now is not something "
        .. "ReaAssist can tell you. Whatever is standing at each name below, "
        .. "this run did not put it there:\n" .. table.concat(vanished, "\n"))
    end
    -- AND THE CELL WHERE THE RENAME LANDED ON SOMETHING ELSE. This run moved
    -- what was at the private name onto the folder's own name and it does not
    -- carry the file this run had put inside the folder, so the move happened
    -- and what it moved cannot be called the folder.
    if #unproven > 0 then
      line("")
      t("result.claim_unproven", { paths = table.concat(unproven, "\n") },
        "ReaAssist moves a folder aside under a name of its own before it "
        .. "empties it, and when it went to put these back its own rename "
        .. "landed on something ReaAssist cannot prove is the folder. What is "
        .. "standing at each name below arrived there through that rename, and "
        .. "ReaAssist can tell you neither that it is the folder it had moved "
        .. "aside nor where that folder is now. ReaAssist deleted nothing. "
        .. "Look at each one before you move or delete anything:\n"
        .. table.concat(unproven, "\n"))
    end
    -- AND THE CELL WHERE THE FOLDER'S OWN NAME HAD BECOME A LINK BY THE TIME
    -- THIS RUN LOOKED (B2.4g, round 54's first blocker). The rename really did
    -- put the folder back; something then moved it on and left a link where it
    -- had been, and reading through that name would have gone straight to the
    -- folder and called the link the folder. The question took the link
    -- instead, which is what it does to a link at any of ReaAssist's own names.
    if #redirected > 0 then
      line("")
      t("result.claim_redirected", { paths = table.concat(redirected, "\n") },
        "ReaAssist moves a folder aside under a name of its own before it "
        .. "empties it, and its own rename did put each of these back. By the "
        .. "time ReaAssist looked at the folder's own name again, that name was "
        .. "a link to somewhere else rather than the folder. Something other "
        .. "than ReaAssist moved the folder on in between. ReaAssist removed "
        .. "the link, left everything it pointed at alone, and deleted nothing "
        .. "else, and where each folder is now is not something ReaAssist can "
        .. "tell you. Any name in brackets is a file of ReaAssist's own that is "
        .. "inside the folder wherever it is:\n"
        .. table.concat(redirected, "\n"))
    end
  end
  -- AND A FOLDER THAT STAYED UNDER ITS PRIVATE NAME BECAUSE THE LIST WOULD NOT
  -- TAKE THE WRITE. Putting a folder back changes the name of everything still
  -- standing inside it, so the records of those have to be rewritten before the
  -- rename rather than after it. A write that fails stops the rename, which
  -- leaves the folder under a name the user has never seen, and that is worth a
  -- sentence of its own rather than being counted with the ordinary refusals.
  -- AND THE LIST ITSELF, WHEN IT OUTLIVES THE RUN. Every record this run could
  -- not close on proof keeps the list on disk, and after the last removal there
  -- is no ReaAssist left to read it, so this report is the only place it can be
  -- said. It was said nowhere before B2.4f: a run could finish with a file at
  -- the package root that nothing had mentioned. The lines above name the
  -- folders; this names the file and says what leaving it does, which is
  -- nothing.
  local function claims_kept_block()
    if not result.claims_left then return end
    local path = tostring(result.claim_journal_path
      or (result.plan and result.plan.claim_journal_path) or "")
    line("")
    t("result.claims_kept", { path = path },
      "ReaAssist keeps a list of the folders one of its own removals moved "
      .. "aside, and it could not account for every line on that list, so the "
      .. "list is still on disk:\n  " .. path
      .. "\n\nEach line names a folder and the name ReaAssist moved it to. "
      .. "Leaving that file where it is changes nothing and deletes nothing: "
      .. "it is the only record ReaAssist has of where those folders went. "
      .. "Delete it yourself once you have finished with it.")
  end
  local function records_stuck_block()
    if not result.records_stuck then return end
    line("")
    t("result.records_stuck", { path = tostring(result.claim_journal_path
      or (result.plan and result.plan.claim_journal_path) or "") },
      "ReaAssist could not write to the list it keeps of the folders it has "
      .. "moved aside, so it left one or more of them under the name it gave "
      .. "them rather than renaming folders it would then have no record of. "
      .. "The list is here:\n  " .. tostring(result.claim_journal_path
        or (result.plan and result.plan.claim_journal_path) or ""))
  end
  if result.stopped and not result.mutated then
    t("result.stopped_clean", nil, "ReaAssist stopped before removing anything.")
    line("")
    for _, blocker in ipairs(result.blockers or {}) do
      line(tostring(blocker.message))
      line("")
    end
    marker_stuck_block()
    -- A stop that removed nothing can still have met what an earlier run left
    -- moved aside, because the putting back happens before the first removal
    -- does. "Nothing was changed" is true of this run and says nothing about
    -- that, so this report says both rather than keeping one of them.
    claims_block()
    return (table.concat(out, "\n"):gsub("%s+$", ""))
  end
  if result.stopped then
    -- A stop with removals behind it. Saying "nothing was changed" here would
    -- be the one thing this copy must never do, so it says where it got to and
    -- then reports exactly what went and what stayed.
    t("result.stopped_partway", nil,
      "ReaAssist stopped partway through removing itself.")
    line("")
    for _, blocker in ipairs(result.blockers or {}) do
      line(tostring(blocker.message))
      line("")
    end
    t("result.removed_before_stop", { count = tostring(#result.removed) },
      "Removed " .. tostring(#result.removed) .. " files and folders "
      .. "before stopping.")
    if result.custom_prompt_moved then
      t("result.custom_prompt_moved", nil,
        "Your custom system prompt was moved to:")
      line("  " .. tostring(result.custom_prompt_moved))
    end
    if #result.left > 0 then
      line("")
      t("result.left_heading", nil,
        "These would not go, and are still on disk:")
      for _, item in ipairs(result.left) do
        line("  " .. tostring(item.path) .. "  ("
          .. tostring(item.reason) .. ")")
      end
    end
    -- A stop can happen after the launchers went, so the action-list rows
    -- belong here as well. They are the one leftover the user cannot see by
    -- looking in the folder.
    if #(result.actions_left or {}) > 0 then
      line("")
      t("result.actions_left_heading", nil,
        "ReaAssist deleted these action files, but REAPER did not remove "
        .. "their rows from the action list. Open Actions, Show action list, "
        .. "find each one and remove it there:")
      for _, path in ipairs(result.actions_left) do
        line("  " .. tostring(path))
      end
    end
    marker_stuck_block()
    claims_block()
    link_seed_block()
    claim_lost_block()
    records_stuck_block()
    claims_kept_block()
    if result.moved_aside then
      line("")
      t("result.moved_aside", nil,
        "ReaAssist moves a folder aside under a name of its own before it "
        .. "empties it, and one or more of those could not be put back. "
        .. "Everything ReaAssist was removing is already out of them, and "
        .. "anything that had to stay is listed above under the name it has "
        .. "now. ReaAssist wrote each one down and puts it back the next time "
        .. "it starts, if its own name is free again.")
    end
    line("")
    t("result.finish_by_hand", nil,
      "To finish by hand, close REAPER and delete this folder:")
    line("  " .. tostring(result.plan and result.plan.package_dir or ""))
    return table.concat(out, "\n")
  end
  if #result.left > 0 then
    t("result.partly_removed", nil, "ReaAssist was partly removed.")
  else
    t("result.removed", nil, "ReaAssist was removed.")
  end
  line("")
  t("result.removed_count", { count = tostring(#result.removed) },
    "Removed " .. tostring(#result.removed) .. " files and folders.")
  if result.custom_prompt_moved then
    t("result.custom_prompt_moved", nil,
      "Your custom system prompt was moved to:")
    line("  " .. tostring(result.custom_prompt_moved))
  end
  -- Three states, three sentences, because the middle one used to be reported
  -- as the first: a removal that was asked for and did not finish said the
  -- data was gone while the list above it named data that was still there.
  if not result.data_attempted then
    t("result.data_kept", nil, "Your ReaAssist data was left where it is.")
  elseif result.data_removed then
    t("result.data_removed", nil,
      "Your ReaAssist data was removed, as you asked.")
  else
    t("result.data_partial", nil,
      "Your ReaAssist data was removed except for what is listed below, "
      .. "which is still on disk.")
  end
  if #result.left > 0 then
    line("")
    t("result.left_heading", nil, "These would not go, and are still on disk:")
    for _, item in ipairs(result.left) do
      line("  " .. tostring(item.path) .. "  (" .. tostring(item.reason) .. ")")
    end
  end
  if #(result.in_use or {}) > 0 then
    line("")
    t("result.in_use_heading", nil,
      "ReaAssist still has these open while this window is running, so it "
      .. "could not remove them. They go with the folder named at the end:")
    for _, item in ipairs(result.in_use) do
      line("  " .. tostring(item.path))
    end
  end
  if #(result.actions_left or {}) > 0 then
    line("")
    t("result.actions_left_heading", nil,
      "ReaAssist deleted these action files, but REAPER did not remove their "
      .. "rows from the action list. Open Actions, Show action list, find "
      .. "each one and remove it there:")
    for _, path in ipairs(result.actions_left) do
      line("  " .. tostring(path))
    end
  end
  -- One sentence per ownership answer, and each one true of the answer it
  -- belongs to. ReaPack put its files there and will put them back; a foreign
  -- package's file was never ReaAssist's; an answer that could not be
  -- confirmed is not an answer about ReaPack at all.
  if result.reapack_left then
    line("")
    t("result.reapack_left", nil,
      "ReaPack installed the ReaAssist actions and keeps them, so ReaAssist "
      .. "did not delete them. Open ReaPack, browse packages, find ReaAssist "
      .. "and choose Uninstall to take them away.")
  end
  if result.foreign_left then
    line("")
    t("result.foreign_left", nil,
      "Another package owns one of the ReaAssist actions listed above, so "
      .. "ReaAssist left it alone. Remove it through whatever installed it.")
  end
  if result.unknown_left then
    line("")
    t("result.unknown_left", nil,
      "ReaAssist could not confirm who owns one of the actions listed above, "
      .. "and it only deletes an action it knows nobody else installed. "
      .. "Delete it yourself if you are sure it is ReaAssist's.")
  end
  claims_block()
  link_seed_block()
  claim_lost_block()
  records_stuck_block()
  claims_kept_block()
  if result.moved_aside then
    line("")
    t("result.moved_aside", nil,
      "ReaAssist moves a folder aside under a name of its own before it "
      .. "empties it, and one or more of those could not be put back. "
      .. "Everything ReaAssist was removing is already out of them, and "
      .. "anything that had to stay is listed above under the name it has "
      .. "now. ReaAssist wrote each one down and puts it back the next time "
      .. "it starts, if its own name is free again.")
  end
  -- Two states, two sentences. The note only offers the reinstall question
  -- once it has been moved to its finished form, and a form this run could not
  -- write is a note that refuses every launch until it is deleted, which is
  -- the opposite instruction and must never be given as the other one.
  if result.marker_path and result.marker_phase ~= "done" then
    line("")
    t("result.marker_active", { path = tostring(result.marker_path) },
      "ReaAssist could not finish the note it wrote when it started, so that "
      .. "note still says a removal is in progress. While it does, the "
      .. "ReaAssist actions will not start ReaAssist and will not offer to "
      .. "install it again.\n\nThe note is here:\n  "
      .. tostring(result.marker_path)
      .. "\n\nDelete that file yourself when you want the actions to work "
      .. "again.")
  elseif result.marker_path then
    line("")
    t("result.marker", { path = tostring(result.marker_path) },
      "The ReaAssist actions will not start ReaAssist again while this note "
      .. "is on disk, so nothing reinstalls it on its own. Running an action "
      .. "asks whether to install ReaAssist again, and saying yes removes the "
      .. "note:\n  " .. tostring(result.marker_path))
  end
  line("")
  t("result.close_and_finish", nil,
    "Close ReaAssist now. To finish by hand, close REAPER and delete this "
    .. "folder:")
  line("  " .. tostring(result.plan and result.plan.package_dir or ""))
  return table.concat(out, "\n")
end

-- =============================================================================
-- Probe compatibility surface
-- =============================================================================
-- The historical local-only Temp-Probe module is retired. Keep Probe.* as
-- explicit no-op entries so instrumentation call sites remain harmless and
-- can be removed opportunistically without turning this cleanup into a broad
-- runtime refactor.
do
  local function noop() end
  local function note_validator_retry(_, kind, meta)
    local event
    local is_context = type(meta) == "table"
      and meta.count_as_validator == false
    local aggregate = 0
    if S then
      local events
      if is_context then
        S.context_fetches_this_turn =
          (S.context_fetches_this_turn or 0) + 1
        aggregate = S.context_fetches_this_turn
        if type(S.context_fetch_events_this_turn) ~= "table" then
          S.context_fetch_events_this_turn = {}
        end
        events = S.context_fetch_events_this_turn
      else
        S.validator_retries_this_turn =
          (S.validator_retries_this_turn or 0) + 1
        aggregate = S.validator_retries_this_turn
        if type(S.validator_retry_counts_by_kind) ~= "table" then
          S.validator_retry_counts_by_kind = {}
        end
        local retry_kind = tostring(kind or "unspecified")
        S.validator_retry_counts_by_kind[retry_kind] =
          (tonumber(S.validator_retry_counts_by_kind[retry_kind]) or 0) + 1
        if type(S.validator_retry_events_this_turn) ~= "table" then
          S.validator_retry_events_this_turn = {}
        end
        events = S.validator_retry_events_this_turn
      end
      event = {
        index = aggregate,
        kind = tostring(kind or "unspecified"),
        retry_class = is_context and "context" or "validator",
        ctx_label = type(meta) == "table" and meta.ctx_label or nil,
        api_calls_before_retry = tonumber(S.api_calls_this_turn) or 0,
        model_calls_before_retry = tonumber(S.model_calls_this_turn) or 0,
      }
      if is_context then
        event.reuse_hint_only = type(meta) == "table"
          and meta.reuse_hint_only == true
      end
      if type(meta) == "table" and type(meta.findings) == "table" then
        event.findings = {}
        for finding_index, finding in ipairs(meta.findings) do
          if finding_index > 8 then break end
          if type(finding) == "table" then
            local detail = tostring(finding.detail or "")
            if Net and type(Net._debug_scrub) == "function" then
              detail = tostring(Net._debug_scrub(detail) or "")
            elseif Log and type(Log.scrub_url_secrets) == "function" then
              detail = tostring(Log.scrub_url_secrets(detail) or "")
            end
            if #detail > 512 then detail = detail:sub(1, 512) end
            event.findings[#event.findings + 1] = {
              kind = tostring(finding.kind or "validator_finding"),
              detail = detail,
              line = tonumber(finding.line),
              review_only = finding.review_only == true,
            }
          end
        end
        if #event.findings == 0 then event.findings = nil end
      end
      local candidate = tostring(S.validator_retry_candidate_text or "")
      if candidate ~= "" then
        local scrubbed = candidate
        if Net and type(Net._debug_scrub) == "function" then
          scrubbed = Net._debug_scrub(candidate)
        elseif Log and type(Log.scrub_url_secrets) == "function" then
          scrubbed = Log.scrub_url_secrets(candidate)
        end
        scrubbed = tostring(scrubbed or "")
        local excerpt = scrubbed
        if #excerpt > 2048 then
          if Diag and type(Diag._utf8_truncate_with_marker) == "function" then
            excerpt = Diag._utf8_truncate_with_marker(excerpt, 2048, "")
          else
            excerpt = excerpt:sub(1, 2048)
          end
        end
        event.candidate = {
          code_type = tostring(S.validator_retry_candidate_type
            or "response_text"),
          byte_count = #candidate,
          content_hash = Diag and type(Diag.content_hash) == "function"
            and Diag.content_hash(scrubbed) or nil,
          content_hash_scope = "redacted",
        }
        if not (type(meta) == "table"
            and meta.omit_candidate_excerpt == true) then
          event.candidate.excerpt = excerpt
          event.candidate.excerpt_bytes = #excerpt
          event.candidate.excerpt_truncated = #scrubbed > #excerpt or nil
        end
      end
      events[#events + 1] = event
    end
    if prefs and prefs.debug_logging and Log and Log.line then
      local cap = is_context
        and (CFG.MAX_CONTEXT_FETCHES_PER_TURN or 3)
        or (CFG.MAX_VALIDATOR_RETRIES_PER_TURN or 3)
      Log.line(is_context and "CONTEXT-REFETCH" or "VALIDATOR-RETRY",
        "kind=" .. tostring(kind or "?")
        .. " aggregate=" .. tostring(aggregate)
        .. "/" .. tostring(cap))
    end
    return event
  end
  Probe = {
    enabled = false,
    start_turn = function() return nil end,
    mark_phase_start = noop,
    mark_phase_end = noop,
    add_bytes = noop,
    set_body_total = noop,
    add_request = noop,
    add_request_usage = noop,
    add_validator_retry = note_validator_retry,
    add_fx_cache = noop,
    add_typed_action = noop,
    end_turn = noop,
  }
end

-- =============================================================================
-- Engine module sidecar (optional native transport integration)
-- =============================================================================
-- The single Engine.lua contains the client and installer components.
-- A missing kit is an incomplete app package and goes through verified repair.
-- Runtime transport failures can still use the existing curl fallback.
if ReaAssistEngineSessionEnabled() then
  local engine_path = RA.RESOURCES_DIR .. "Engine.lua"
  local ok, module_or_error = pcall(dofile, engine_path)
  if ok and type(module_or_error) == "table" then
    Engine = module_or_error
  else
    Engine = nil
    Log.line("ENGINE", "Engine.lua unavailable; curl lane active: "
      .. tostring(module_or_error or "module did not return a table"))
  end
else
  Engine = nil
end

-- BEGIN APP DOWNLOAD SUPPORT
RA.SupportDownload = (function()
-- CFG.VERSION compatibility marker for the frozen v1.5 updater.
-- App-owned acquisition. The shared host kit owns installation and recovery.
local Download = {}
Download.__index = Download
Download.TIMEOUT = 180
Download.MAX_BYTES = 64 * 1024 * 1024
local gates = {stage_package="can_stage", replace_package="can_replace", confirm_repair="can_confirm_repair"}

local function read(path, limit)
  local file = io.open(path, "rb")
  if not file then return nil end
  local value = file:read((limit or 65536) + 1)
  local closed = file:close()
  if not closed or type(value) ~= "string" or #value > (limit or 65536) then return nil end
  return value
end

function Download.new(options)
  local self = setmetatable({options=options, sequence=0}, Download)
  local ra = options.ra
  local raw = read(ra.APP_DIR .. "manifest.json", 1024 * 1024)
  self.manifest_raw = raw
  local ok, manifest = pcall(ra.JSON.decode, raw or "")
  if not ok or type(manifest) ~= "table" or manifest.version ~= options.app_version
      or type(manifest.engine) ~= "table" then
    self.error = "delivery-record-unavailable"
    return self
  end
  local metadata = manifest.engine
  local descriptor = metadata.descriptor
  local ref = type(metadata.source_ref) == "string" and metadata.source_ref or ""
  if metadata.schema ~= 1 or metadata.delivery ~= "shared-v1" or type(descriptor) ~= "table"
      or type(descriptor.version) ~= "string" or not descriptor.version:match("^%d+%.%d+%.%d+$")
      or metadata.shared_path ~= "Helper-Engine/" .. descriptor.version
      or not (ref:match("^v%d+%.%d+%.%d+$") or (#ref == 40 and ref:match("^[a-f0-9]+$")))
      or (descriptor.payload_layout ~= nil and descriptor.payload_layout ~= "native-bytes-txt-v1")
      or type(metadata.source) ~= "table"
      or type(metadata.source.commit) ~= "string" or #metadata.source.commit ~= 40
      or not metadata.source.commit:match("^[a-f0-9]+$")
      or type(metadata.source.kit_sha256) ~= "string" or #metadata.source.kit_sha256 ~= 64
      or not metadata.source.kit_sha256:match("^[a-f0-9]+$") then
    self.error = "delivery-record-invalid"
    return self
  end
  local kit_listed, kit_count = false, 0
  for _, entry in ipairs(type(manifest.files) == "table" and manifest.files or {}) do
    if type(entry) == "table" and entry.name == "Resources/Engine.lua" then
      kit_count = kit_count + 1
      kit_listed = entry.sha256 == metadata.source.kit_sha256
    end
  end
  if not kit_listed or kit_count ~= 1 then self.error = "delivery-kit-mismatch"; return self end
  self.metadata, self.descriptor = metadata, descriptor
  self.shared = true
  return self
end

function Download:manifest_current()
  if read(self.options.ra.APP_DIR .. "manifest.json", 1024 * 1024) ~= self.manifest_raw then
    self.error = "delivery-manifest-changed"
    return false
  end
  return true
end

function Download:busy()
  return self.job ~= nil
end

function Download:_finish(error_code)
  local job = self.job
  if job then
    os.remove(job.out_path)
    os.remove(job.exit_path)
  end
  self.job = nil
  self.failure = error_code
  self.failure_reported = nil
  if error_code and self.options.log then self.options.log("INSTALL", error_code) end
end

function Download:ensure(action, retry)
  if not gates[action] then return "ready" end
  if self.error then return "failed", self.error end
  if not self.shared then return "ready" end
  if self.job then return "pending" end
  if self.failure and not retry then return "failed", self.failure end
  if self.options.blocked() then return "blocked" end
  if not self:manifest_current() then return "failed", self.error end
  local host = self.options.host()
  if not host or type(host.cache_package) ~= "function" then return "failed", "installer-unavailable" end
  local view = host:presentation()
  if not view or view[gates[action]] ~= true then return "blocked" end
  local target = host.package_target
  local artifact = target and self.descriptor.artifacts and self.descriptor.artifacts[target.platform]
  if not artifact or artifact.filename ~= target.filename or artifact.sha256 ~= target.sha256 then
    return "failed", "target-unavailable"
  end
  local cached = host:cache_package()
  if type(cached) ~= "table" then return "blocked" end
  if cached.kind == "ready" then self.failure = nil; return "ready" end
  if cached.kind == "busy" then return "blocked" end
  if cached.kind ~= "needed" then return "failed", cached.detail end
  self.sequence = self.sequence + 1
  local ra = self.options.ra
  self.options.reaper.RecursiveCreateDirectory(ra.TEMP_DIR, 0)
  local suffix = ra.instance_file_suffix()
  if type(suffix) ~= "string" or not suffix:match("^[A-Za-z0-9_%-]+$") then return "failed", "instance-invalid" end
  local stem = ra.TEMP_DIR .. "support_" .. tostring(self.sequence) .. "_" .. suffix
  local job = {action=action, target=target.sha256, out_path=stem .. ".part", exit_path=stem .. ".exit"}
  -- Both target fields came from the strict host descriptor, never a response.
  local ref = self.metadata.source_ref
  if ref:sub(1,1) == "v" then ref = "refs/tags/" .. ref end
  local base = "https://raw.githubusercontent.com/michaelbriggsaudio/mbriggs-reaper/"
  if self.options.dev_override == true then
    -- The validated override names the app endpoint. Shared files are its
    -- siblings in the same repository snapshot, without an extra tag prefix.
    local app_base = type(self.options.base_url) == "string"
      and self.options.base_url:gsub("/+$", "") or ""
    local repo_base = app_base:match("^(.-)/ReaAssist/App$")
      or app_base:match("^(.-)/ReaAssist$")
    if not repo_base or repo_base == "" then return "failed", "delivery-override-invalid" end
    base, ref = repo_base .. "/", ""
  else
    ref = ref .. "/"
  end
  local url = base .. ref .. self.metadata.shared_path .. "/"
    .. target.platform .. "/" .. target.filename
    .. (self.descriptor.payload_layout == "native-bytes-txt-v1" and ".txt" or "")
  local started = ra.fire_get_to(url, job.out_path, job.exit_path, Download.TIMEOUT, job,
    "INSTALL", {cache_bust=false, max_bytes=Download.MAX_BYTES})
  if not started then self.job=job; self:_finish("download-start"); return "failed", self.failure end
  job.send_time = job.send_time or self.options.now()
  self.job, self.failure = job, nil
  return "pending"
end

-- A completed transfer is held until app update/deploy exclusion permits cache
-- promotion. The host takes the shared lock again before touching the cache.
function Download:poll()
  local job = self.job
  if not job then return nil end
  local exit_text = read(job.exit_path, 64)
  if not exit_text or not exit_text:match("^%s*%-?%d+%s*$") then
    if self.options.now() - job.send_time > Download.TIMEOUT + 30 then
      self:_finish("download-timeout")
    end
    return nil
  end
  if tonumber(exit_text) ~= 0 then self:_finish("download-http"); return nil end
  if self.options.blocked() then return nil end
  if not self:manifest_current() then self:_finish(self.error); return nil end
  local host = self.options.host()
  if not host or not host.package_target or host.package_target.sha256 ~= job.target then
    self:_finish("download-target-changed"); return nil
  end
  local file = io.open(job.out_path, "rb")
  local length = file and file:seek("end")
  if file then file:close() end
  if not length or length <= 0 or length > Download.MAX_BYTES then
    self:_finish("download-size"); return nil
  end
  local promoted = host:cache_package(job.out_path)
  if type(promoted) ~= "table" then return nil end
  if promoted.kind == "busy" then return nil end
  if promoted.kind ~= "ready" then self:_finish(promoted.detail or "download-invalid"); return nil end
  local action = job.action
  self:_finish()
  local view = host:presentation()
  if view and view[gates[action]] == true then return action end
  return nil
end

return Download
end)()
-- END APP DOWNLOAD SUPPORT

-- =============================================================================
-- Engine installer startup recovery
-- =============================================================================
-- The host adapter stays idle without a durable Engine transaction. Artifact
-- selection and download are separate release inputs, so this startup seam can
-- recover an interrupted transaction without admitting an untrusted binary.
if ReaAssistEngineSessionEnabled() and not RA.UPDATE_CHECKS_DISABLED then
  local ok, module = true, RA.SupportDownload
  if ok and type(module) == "table" and type(module.new) == "function" then
    RA.support_download = module.new({ra=RA, reaper=reaper, now=time_precise, app_version=CFG.VERSION,
      dev_override=CFG.UPDATE_OVERRIDE_MODE == "source", base_url=CFG.UPDATE_OVERRIDE_BASE_URL,
      host=function() return EngineInstallerHost end,
      log=function(category, message) Log.line(category, message) end,
      blocked=function()
        return not ReaAssistEngineSessionEnabled() or S.bootstrap_active
          or Updater.is_busy() or update.show_dialog == true
          or RA.deploy_lock_installer_held() or S.status == "waiting"
          or S.status == "awaiting_confirmation" or S.curl_pid ~= nil
          or S.retry_scheduled == true or S.turn_budget_confirmation ~= nil
      end})
  else
    RA.support_download = nil
    Log.line("INSTALL", "download support unavailable")
  end
end
if ReaAssistEngineSessionEnabled() and not RA.UPDATE_CHECKS_DISABLED then
  function RA.attach_support_installer()
  local kit = type(Engine) == "table" and Engine.Kit
  local host_module = type(kit) == "table" and kit.InstallerHost
  if type(host_module) == "table" and type(host_module.attach) == "function" then
    local controller, attach_why = host_module.attach(
      reaper, RA, RA.JSON, RA.sha256_hex, kit.Installer, kit.InstallerRuntime,
      kit.InstallerPackage,
      function(category, message) Log.line(category, message) end,
      {cache_only=true, require_descriptor=true,
        descriptor=RA.support_download and RA.support_download.descriptor})
    if controller then
      EngineInstallerHost = controller
    else
      EngineInstallerHost = nil
      Log.line("ENGINE-INSTALL", "host unavailable: " .. tostring(attach_why))
    end
  else
    EngineInstallerHost = nil
    Log.line("ENGINE-INSTALL", "recovery sidecar unavailable")
  end
  end
  RA.attach_support_installer()
else
  EngineInstallerHost = nil
end


-- Dependency setup uses the same host and download admission as normal startup.
-- No replacement, repair confirmation or quarantine clearance is automatic.
function RA.bootstrap_support_step(retry)
  if not ReaAssistEngineSessionEnabled() then return "failed", "mode-excluded" end
  if RA.deploy_lock_installer_held() then return "pending" end
  local host, download = EngineInstallerHost, RA.support_download
  if not host or not download then return "failed", "installer-unavailable" end
  RA.write_temp_live_marker(time_precise())
  reaper.SetExtState(CFG.EXT_NS, "running", S.INSTANCE_ID .. "|" .. tostring(time_precise()), false)
  local state = host:tick()
  local view = host:presentation()
  if view.action == "restart-required" or view.action == "current" then return "done" end
  if state and (state.kind == "staged" or state.kind == "advanced"
      or state.kind == "resume" or state.kind == "resumed"
      or state.kind == "probed" or state.kind == "busy") then return "pending" end
  if (view.action ~= "install" and view.action ~= "update") or view.can_stage ~= true then
    return "failed", tostring(view.detail or view.action or "installation-refused")
  end
  if download:busy() then
    download:poll()
    if download:busy() then return "pending" end
    if download.failure then return "failed", download.failure end
  end
  local ready, reason = download:ensure("stage_package", retry == true)
  if ready == "pending" or ready == "blocked" then return "pending" end
  if ready ~= "ready" then return "failed", reason or ready end
  local result = host:stage_package()
  if type(result) ~= "table" then return "failed", "invalid-stage-result" end
  if result.kind == "restart-required" then return "done" end
  if result.kind == "refuse" or result.kind == "recovery-required" then
    return "failed", result.detail or result.kind
  end
  return "pending"
end

if start_pending_dependencies then
  start_pending_dependencies(RA.bootstrap_support_step,
    EngineInstallerHost and EngineInstallerHost.package_target
      and EngineInstallerHost.package_target.version)
  return
end

function RA.refresh_support_metadata()
  local download = RA.support_download
  if RA.UPDATE_CHECKS_DISABLED or not ReaAssistEngineSessionEnabled()
      or not download or download:busy()
      or download.options.blocked() or type(RA.attach_support_installer) ~= "function" then return false end
  if RA._support_metadata_retry_at and time_precise() < RA._support_metadata_retry_at then return false end
  RA._support_metadata_retry_at = time_precise() + 5
  local host = EngineInstallerHost
  if host and type(host.state_root) == "string" then
    for _, name in ipairs({"install_journal.json", "first_load.json", "recovery.json"}) do
      local path = host.state_root .. "/" .. name
      if RA.path_present(path) or RA.path_present(path .. ".tmp") then return false end
    end
  end
  local replacement = RA.SupportDownload.new(download.options)
  RA.support_metadata_refresh = nil
  if replacement.error then return false end
  RA.support_download = replacement
  RA.attach_support_installer()
  S._support_install_checked = nil
  S._engine_installer_ui_error = nil
  return true
end

-- =============================================================================
-- Diag module sidecar (diagnostics and feedback upload)
-- =============================================================================
-- Loaded AFTER the shared RA.JSON / RA.sha256_* helpers above are visible and
-- BEFORE UI.lua (so the in-chat link guard `Diag.uploader_enabled` has a real
-- value when UI renders). Diag (the namespace) is already populated
-- with .errors / .add_error / .build_report from earlier in this file; this
-- dofile extends it with the network-uploader surface.
--
-- The fallback catches a hard load failure, an incompatible payload revision,
-- or a module that loaded but disabled itself (e.g. internal RA.JSON guard
-- tripped). A revision mismatch is the signature of a partial legacy update:
-- fail closed before the old sidecar can emit a payload stamped with the new
-- main script's CFG.VERSION, then route Diag.lua through bootstrap repair.
--
-- Diagnostic sidecar compatibility gate.
Startup.mark("diag_load_start")
do
  local diag_path = RA.RESOURCES_DIR .. "Diag.lua"
  local probe, probe_err = io.open(diag_path, "rb")
  local head
  if probe then
    head = probe:read(8192)
    probe:close()
  end
  local discovered_revision = type(head) == "string"
    and tonumber(head:match("Diag%.PAYLOAD_REVISION%s*=%s*(%d+)")) or nil
  local revision_mismatch =
    discovered_revision ~= CFG.DIAG_PAYLOAD_REVISION
  local ok, err = false, probe_err
  if not revision_mismatch then
    ok, err = pcall(dofile, diag_path)
    revision_mismatch = ok
      and tonumber(Diag.PAYLOAD_REVISION) ~= CFG.DIAG_PAYLOAD_REVISION
  end
  S.diag_repair_required = (not ok) or revision_mismatch
  if not ok or Diag.uploader_enabled ~= true or revision_mismatch then
    Diag.uploader_enabled = false
    if revision_mismatch then
      -- Replace stale implementations instead of merely filling absent
      -- functions. This keeps every direct call inert during repair mode.
      Diag.tick           = function() end
      Diag.rotate_chat_id = function() end
    else
      Diag.tick           = Diag.tick           or function() end
      Diag.rotate_chat_id = Diag.rotate_chat_id or function() end
    end
    if revision_mismatch then
      Log.line("DIAG", string.format(
        "Diag.lua revision mismatch: expected %s, got %s; uploads "
        .. "disabled and repair required.",
        tostring(CFG.DIAG_PAYLOAD_REVISION),
        discovered_revision == nil
          and "missing" or tostring(discovered_revision)))
    elseif not ok then
      Log.line("DIAG", "Diag.lua load failed: " .. tostring(err))
    end
  end
end
-- close diagnostic sidecar compatibility gate
Startup.mark("diag_load_done")

-- =============================================================================
-- Critical-file recovery gate + UI sidecar load
-- =============================================================================
-- Verify every critical file (UI chunk + every font the atlas expects) is
-- present before dofile()'ing the UI file. If anything is missing, flip
-- into bootstrap recovery: skip the dofile, set S.bootstrap_active, and
-- let the kick-off block at the bottom of the file register Bootstrap.loop
-- instead of the normal loop. Bootstrap uses default font / theme and
-- does not touch Render.* / UI.* / TK.* / FONT.* -- any of which may be
-- nil in recovery mode. CRITICAL_FILES is hardcoded (not manifest-driven)
-- because bootstrap has to run BEFORE any network activity.

S.bootstrap_active  = false
S.bootstrap_missing = {}

-- A legacy sequential update can replace ReaAssist.lua before Diag.lua.
-- Seed the existing recovery flow with the exact manifest filename so the
-- bootstrap fast path downloads and verifies the compatible sidecar.
-- Diagnostic repair bootstrap seed.
if S.diag_repair_required then
  S.bootstrap_missing[#S.bootstrap_missing + 1] = "Resources/Diag.lua"
end
-- close diagnostic repair bootstrap seed

function RA.load_i18n()
  local path = RA.RESOURCES_DIR .. "I18N.lua"
  local ok, mod = pcall(dofile, path)
  if ok and type(mod) == "table" then
    I18N = mod
  else
    I18N = {
      fallback_code = "en",
      catalogs = {
        en = {
          _meta = { code = "en", source_version = 1, status = "complete" },
          strings = {
            ["settings.chat_language.label"] = "Chat Language",
            ["settings.chat_language.tooltip"] =
              "Assistant replies and newly localized local reply surfaces use this language. Code, diagnostics, plugin names, and REAPER API names stay unchanged.",
            ["settings.badge.beta"] = "Beta",
            ["local.footer.free_reply"] = "ReaAssist local free reply.",
            ["local.footer.ask_provider_instead"] =
              "Ask {provider} instead.",
            ["local.tempo"] = "Tempo: {bpm} BPM | Time Signature: {num}/{denom}",
          },
        },
      },
    }
    function I18N.t(key, vars)
      local strings = I18N.catalogs.en.strings
      local text = strings[tostring(key or "")] or tostring(key or "")
      if type(vars) == "table" then
        text = text:gsub("{([%w_]+)}", function(name)
          local v = vars[name]
          return v == nil and ("{" .. name .. "}") or tostring(v)
        end)
      end
      return text
    end
    function I18N.prompt_language_name()
      return CFG.prompt_language_name_for_idx
        and CFG.prompt_language_name_for_idx(prefs.reply_language_idx or 1)
        or "English"
    end
    if Log and Log.line then
      Log.line("I18N", "I18N.lua unavailable; using built-in English fallback.")
    end
  end
  if I18N and I18N.reload_language then
    I18N.reload_language(CFG.current_language_code())
  end
  return I18N
end

Startup.mark("i18n_load_start")
RA.load_i18n()
Startup.mark("i18n_load_done")

do
  -- Derive font entries from FONT_FILES (the same table _mkfont calls
  -- consume) so the two lists cannot drift: add a font to FONT_FILES
  -- and the bootstrap check picks it up automatically. Keep core sidecars
  -- explicit because bootstrap repair queues only this missing-file list.
  local CRITICAL_FILES = {
    "Resources/Context.lua",
    "Resources/CodeRuntime.lua",
    "Resources/Engine.lua",
  }
  if not S.screen_reader_startup_intent then
    CRITICAL_FILES[#CRITICAL_FILES + 1] = "Resources/UI.lua"
  end
  if S.screen_reader_startup_intent
      and RA.prefer_screen_reader_enabled() then
    CRITICAL_FILES[#CRITICAL_FILES + 1] =
      "ReaAssist_Screen_Reader_Mode.lua"
  end
  -- Sort font filenames so the bootstrap-missing list is presented in
  -- a stable order across launches. `pairs` order is hash-bucket-
  -- dependent; without sorting, the recovery screen's "first 6 missing"
  -- entries shuffle between launches for the same filesystem state.
  if not S.screen_reader_startup_intent then
    local fnames = {}
    for _, fname in pairs(FONT_FILES) do fnames[#fnames + 1] = fname end
    table.sort(fnames)
    for _, fname in ipairs(fnames) do
      CRITICAL_FILES[#CRITICAL_FILES + 1] = "Resources/fonts/" .. fname
    end
  end
  -- Every entry is a manifest name, so it resolves the way the updater
  -- resolves one: under the app root. The bootstrap-missing list this feeds
  -- is handed straight to the repair queue, which downloads to the same
  -- place.
  for _, rel in ipairs(CRITICAL_FILES) do
    local path = RA.APP_DIR
                 .. (RA.SEP == "/" and rel or rel:gsub("/", RA.SEP))
    local probe = io.open(path, "r")
    if probe then
      probe:close()
    else
      S.bootstrap_missing[#S.bootstrap_missing + 1] = rel
    end
  end
  -- Font objects do not exist yet. RA.init_imgui_runtime creates and validates
  -- them at the final pre-loop boundary so macOS cannot collect the ReaImGui
  -- context first. That initializer routes a present-but-unloadable font back
  -- into this same verified recovery path.
end

if #S.bootstrap_missing > 0 then
  S.bootstrap_active = true
  -- Distinguish "fresh install (stub installer just dropped ReaAssist.lua,
  -- supporting files not yet fetched)" from "existing install with corrupt
  -- or missing files." The former auto-installs without a Repair button;
  -- the latter shows the existing repair prompt. Signal: Config/ExtState
  -- `first_launch_complete` is set once UI has loaded successfully at
  -- least once on this REAPER profile. Missing -> install mode.
  S.bootstrap_install_mode =
    not Store.first_launch_complete()
  Log.line("BOOTSTRAP", string.format(
    "%d critical file%s missing; entering %s mode on this launch.",
    #S.bootstrap_missing,
    #S.bootstrap_missing == 1 and "" or "s",
    S.bootstrap_install_mode and "first-install" or "recovery"))
  for _, rel in ipairs(S.bootstrap_missing) do
    Log.line("BOOTSTRAP", "  missing: " .. rel)
  end
elseif not S.screen_reader_startup_intent and not S.quarantine_gate then
  -- All critical files present; dofile the UI file to populate Render.*
  -- before the main loop is registered below. Wrapped in pcall so a UI
  -- file that exists but is syntactically corrupt or throws a top-level
  -- runtime error routes into bootstrap recovery instead of crashing
  -- before the recovery screen can render.
  --
  -- Skipped entirely under a standing quarantine gate: that launch is going
  -- into the recovery surface no matter what this file looks like, the
  -- surface draws in the default font and theme without it, and loading a
  -- sidecar off an install nobody has vouched for buys nothing.
  Startup.mark("ui_load_start")
  local ok_ui, err_ui = pcall(dofile, RA.RESOURCES_DIR .. "UI.lua")
  Startup.mark("ui_load_done")
  if not ok_ui then
    S.bootstrap_active = true
    S.bootstrap_install_mode =
      not Store.first_launch_complete()
    S.bootstrap_missing[#S.bootstrap_missing + 1] =
      "Resources/UI.lua (load error)"
    -- Log only; do NOT call Updater._set_failure here. Same reason as
    -- the load_system_prompt branches above: this is a load-time
    -- detection of a recoverable file, not a failed repair, and
    -- pre-populating last_error would skip the recovery prompt and
    -- route straight to render_failed.
    Log.line("BOOTSTRAP", string.format(
      "ui_load: UI.lua failed to dofile (%s); routing to recovery prompt.",
      tostring(err_ui)))
  else
    -- The UI chunk loaded cleanly. Persist first-launch completion only after
    -- the late ReaImGui context and every required font also initialize.
    S._ui_loaded_cleanly = true
  end
end

-- A standing quarantine gate enters recovery too, whatever the critical-file
-- probe found (B2.2d requirement 4). The gate says an update record touched
-- this install and nobody has verified it since; the files it names may all be
-- present and still be the wrong versions, half-swapped between two releases.
-- So the launch that finds it runs the recovery surface and nothing else: no
-- chat, no scan, no session. Always the repair mode rather than the
-- first-install mode, because there is an install here, and it is the one the
-- gate is standing in front of.
if S.quarantine_gate then
  S.bootstrap_active = true
  S.bootstrap_install_mode = false
  Log.line("BOOTSTRAP", string.format(
    "quarantine gate standing at %s; entering recovery mode with the full "
    .. "verified repair.", tostring(S.quarantine_gate)))
end

-- The manifest is not a critical file, so the probe above says nothing about
-- it and neither does the launcher's: both start a body that is present, and
-- a body with no manifest beside it starts perfectly well. Notice it here
-- instead, once, in the same place the rest of the install is checked. Skip
-- it in bootstrap recovery, where force_reinstall is already fetching the
-- manifest for a much bigger repair.
if not S.bootstrap_active then
  Updater.try_manifest_restore()
end
Startup.mark("runtime_ready")

-- =============================================================================
-- Main loop
-- =============================================================================
-- Registered via reaper.defer() at the bottom of the file; runs every frame.
-- Handles close-signal handoff, curl polling, auto-retry on transient
-- errors, and dispatches the ImGui draw via Render.main_window (which
-- lives in Resources/UI.lua).
local Loop = {}

-- STARTUP_FIRST_PAINT_STATE_MACHINE_BEGIN
function Loop.post_paint_startup_next(first_frame_submitted, phase)
  phase = phase or "legacy_cleanup"
  if first_frame_submitted ~= true then return nil, phase end
  if phase == "legacy_cleanup" then return "legacy_cleanup", "plugin_pack" end
  if phase == "plugin_pack" then return "plugin_pack", "done" end
  return nil, "done"
end
-- STARTUP_FIRST_PAINT_STATE_MACHINE_END

function Loop.run_post_paint_startup()
  local task, next_phase = Loop.post_paint_startup_next(
    S.startup_first_frame_submitted, S.startup_post_paint_phase)
  if not task then return false end
  S.startup_post_paint_phase = next_phase
  Startup.log_once()

  if task == "legacy_cleanup" then
    if update._legacy_cleanup_done then return true end
    -- Set before the call so a raise cannot turn a one-shot cleanup into a
    -- retry loop. The pass remains best effort and keeps every ownership and
    -- recovery gate inside Updater.legacy_cleanup_run.
    update._legacy_cleanup_done = true
    local swept, err = pcall(Updater.legacy_cleanup_run)
    if not swept then
      Log.line("UPDATE", "legacy cleanup: raised; " .. tostring(err))
    end
    return true
  end

  if task == "plugin_pack" and CTX and CTX.plugin_pack_start then
    -- Startup warm-up uses the Engine checksum when available, then falls back
    -- to bounded Lua work. It never launches the PowerShell checksum path.
    local called, accepted, err = pcall(CTX.plugin_pack_start, {
      avoid_process = true,
      origin = "startup_after_first_paint",
    })
    if not called then
      Log.line("PLUGIN_PACK", "startup warm-up raised: " .. tostring(accepted))
    elseif accepted == false and err ~= "Plugin pack is still loading." then
      Log.line("PLUGIN_PACK", "startup warm-up refused: " .. tostring(err))
    end
  end
  return true
end

-- Second-instance close signal. request_close carries the new instance's ID;
-- a non-empty value that isn't our own triggers a graceful close.
function Loop.finish_support_installation()
  if RA.UPDATE_CHECKS_DISABLED then
    S._support_install_checked = true
    S._support_install_preparing = nil
    S._support_install_preparing_painted = nil
    S._engine_installer_ui_error = nil
    return
  end
  if RA.support_download and (RA.support_metadata_refresh
      or RA.support_download.error == "delivery-manifest-changed") then
    RA.refresh_support_metadata()
  end
  if RA.support_download then
    local polled, action = pcall(RA.support_download.poll, RA.support_download)
    if not polled then
      Log.line("INSTALL", "download poll failed: " .. tostring(action))
      RA.support_download:_finish("download-poll")
      action = nil
    end
    if action then
      S._support_install_preparing = nil
      local result = UI.engine_installer_run(action)
      S._support_install_checked = not (result and result.kind == "preparing")
      return
    end
    if RA.support_download:busy() then
      S._support_install_preparing = true
      return
    end
    if RA.support_download.failure then
      S._support_install_checked = true
      S._support_install_preparing = nil
      if not RA.support_download.failure_reported then
        S._engine_installer_ui_error = UI.engine_installer_download_error("failed", RA.support_download.failure)
        RA.support_download.failure_reported = true
      end
      return
    end
  end
  if S._support_install_checked or not ReaAssistEngineSessionEnabled()
      or S.startup_first_frame_submitted ~= true or S.bootstrap_active
      or S.status == "waiting" or S.status == "awaiting_confirmation"
      or S.curl_pid ~= nil or S.retry_scheduled == true
      or S.turn_budget_confirmation ~= nil or Updater.is_busy()
      or update.show_dialog == true
      or RA.deploy_lock_installer_held() then
    S._support_install_preparing = nil
    S._support_install_preparing_painted = nil
    return
  end
  local host = EngineInstallerHost
  if type(host) ~= "table" or host.session_checked ~= true or host.paused == true
      or type(host.presentation) ~= "function"
      or type(host.stage_package) ~= "function" then
    S._support_install_preparing = nil
    S._support_install_preparing_painted = nil
    return
  end
  -- This dispatch owns no files. The installer rechecks the package, live
  -- identity and recovery state under its transaction lock. Never automate a
  -- repair, same-version replacement or clearance of a rejected version here.
  -- The download continuation above can finish an action the user confirmed.
  local ok, view = pcall(host.presentation, host)
  if not ok or type(view) ~= "table" then
    S._support_install_checked = true
    S._support_install_preparing = nil
    S._engine_installer_ui_error = RA.t("engine.install.unexpected_error", nil,
      "The installation action failed. Check the installation status before trying again.")
    Log.line("ENGINE-INSTALL", "automatic presentation failed")
    return
  end
  if view.package_state ~= "ready" or view.can_stage ~= true
      or (view.action ~= "install" and view.action ~= "update") then
    S._support_install_checked = true
    S._support_install_preparing = nil
    return
  end
  if not S._support_install_preparing_painted then
    S._support_install_preparing = true
    return
  end
  S._support_install_preparing = nil
  local staged, result = pcall(UI.engine_installer_run, "stage_package")
  S._support_install_checked = not (staged and result and result.kind == "preparing")
  if not staged then
    S._engine_installer_ui_error = RA.t("engine.install.unexpected_error", nil,
      "The installation action failed. Check the installation status before trying again.")
    Log.line("ENGINE-INSTALL", "automatic dispatch failed")
  end
end

function Loop.handle_close_signal()
  local close_req = reaper.GetExtState(CFG.EXT_NS, "request_close")
  if close_req ~= "" and close_req ~= S.INSTANCE_ID then
    S.script_open = false
  end
end

-- Dispatch one-shot commands from Dev/ReaAssist_Debug_Helper.lua. The helper
-- writes short strings to this ExtState key for actions it can't reach on its
-- own (in-memory state mutations). Cleared immediately so each signal fires
-- once. Add new arms here as dev-helper buttons are wired up.
function Loop.handle_dev_signal()
  local dev_sig = reaper.GetExtState(CFG.EXT_NS, "dev_signal")
  if dev_sig == "" then return end
  reaper.DeleteExtState(CFG.EXT_NS, "dev_signal", false)
  Log.line("DEV_SIGNAL", "received " .. dev_sig)
  if dev_sig == "clear_chat" then
    Net.clear_conversation()
  elseif dev_sig == "reset_window" then
    Store.clear_window_geometry()
    S._reset_window_size = true
  elseif dev_sig == "refresh_debug_log" then
    -- Match the opt-in pattern at the prefs load site.
    prefs.debug_logging =
      reaper.GetExtState(CFG.EXT_NS, "debug_logging") == "1"
  elseif dev_sig == "refresh_language" then
    local code = reaper.GetExtState(CFG.EXT_NS, "language_code")
    if not (CFG and CFG.is_valid_language_code
        and CFG.is_valid_language_code(code)) then
      code = CFG and CFG.current_language_code and CFG.current_language_code()
        or "en"
    end
    prefs.language_code = code
    prefs.reply_language_idx = (CFG.legacy_idx_for_language_code
        and CFG.legacy_idx_for_language_code(code))
      or prefs.reply_language_idx
      or 1
    if I18N and I18N._cached_pack_miss then
      I18N._cached_pack_miss[code] = nil
    end
    if I18N and I18N.reload_language then I18N.reload_language(code) end
    if S and S.wrap_cache then S.wrap_cache = {} end
    local has_catalog = I18N and I18N.catalog_available
      and I18N.catalog_available(code)
    if code ~= "en" and code ~= "qps-ploc" and LangPacks then
      if not has_catalog and LangPacks.start_language_download then
        LangPacks.start_language_download(code, true)
      elseif has_catalog then
        if LangPacks.start_index_download then
          LangPacks.start_index_download(code, true, true)
        elseif I18N and I18N.remote_index and LangPacks.refresh_language_if_stale then
          LangPacks.refresh_language_if_stale(code)
        end
      end
    end
    Log.line("DEV_LANGUAGE", "refresh_language fired; pref=" .. tostring(code)
      .. " active=" .. tostring(I18N and I18N.lang_code and I18N.lang_code()
        or ""))
  elseif dev_sig == "refresh_fx_filter" then
    -- Dev helper toggled the FabFilter-hide flag. Invalidate the cached
    -- installed-FX lists so populate_installed_fx re-walks REAPER with
    -- the new filter, and drop pref_plugins.initialized so the
    -- Preferred Plugins page reloads rows with the filtered view on
    -- next render. Cache mutation isn't needed -- load_pref_plugins
    -- and CTX.preferred_plugins apply _is_fabfilter_ident as a
    -- read-time filter, reading directly from ExtState, so the flag
    -- takes effect even if this signal never fires (e.g. at boot, when
    -- the flag is already "1" in ExtState).
    Log.line("DEV_FILTER", "refresh_fx_filter fired; hide_fabfilter="
      .. (reaper.GetExtState(CFG.EXT_NS, "dev_hide_fabfilter") == "1"
          and "true" or "false"))
    CTX._installed_fx_list         = nil
    CTX._installed_fx_list_deduped = nil
    pref_plugins.initialized = false
  elseif dev_sig == "refresh_theme" then
    -- Dev helper flipped the saved theme pref. Re-read ExtState and
    -- re-apply the palette live, mirroring what the in-app Settings
    -- footer toggle does (see UI.lua "##fr_theme" handler). apply_palette
    -- swaps COL/TK and invalidates UI palette caches, so the change shows
    -- up on the next render without a restart. Match the boot-time
    -- normalization at the prefs load site so an unrecognized value falls
    -- back to "auto" instead of NULL-ing the palette.
    local v = reaper.GetExtState(CFG.EXT_NS, "theme")
    prefs.theme = (v == "dark" or v == "light") and v or "auto"
    apply_palette(PALETTES[resolve_theme(prefs.theme)])
    Log.line("DEV_THEME", "refresh_theme fired; pref=" .. prefs.theme
      .. " resolved=" .. resolve_theme(prefs.theme))
  end
end

-- Resolve-popup pending resume coordination. When the user picks a plugin in
-- the resolve popup we kick off fx_cache_rescan_start and stash the ident on
-- S.resolve_pending_resume. Once the scan drains, fire resolve_popup_resume so
-- the follow-up turn's preferred_plugins:<type> bucket has fresh params.
--
-- If needs_deep_scan is set and we haven't already tried a deep scan, kick one
-- off first -- some CLAP plugins have display-refresh lag and deliver bare
-- [norm:] data without enum/range annotations until a deep scan completes.
function Loop.handle_resolve_deep_scan()
  if not RA.context_loaded() then
    if S.resolve_pending_resume and not S._resolve_context_unavailable_reported then
      S._resolve_context_unavailable_reported = true
      RA.fail_context_unavailable("before resuming plugin resolution", "idle")
    end
    return
  end

  if S.resolve_pending_resume
     and not fx_cache_ui.rescan.active
     and not deep_scan.active
     and not S._resolve_deep_scan_attempted then
    local pdata = FXCache.get_plugin(S.resolve_pending_resume)
    if pdata and pdata.needs_deep_scan then
      S._resolve_deep_scan_attempted = true
      Log.line("DEEP_SCAN", "popup-resume: auto-triggering deep scan for "
        .. S.resolve_pending_resume)
      CTX.fx_cache_rescan_start(S.resolve_pending_resume, true)
      -- Start-of-deep-scan auto-scroll only fires when origin == "chat";
      -- fx_cache_rescan_start uses origin "fx_cache", so force scroll here.
      S.scroll_to_bottom = true
    end
  end
  if S.resolve_pending_resume
     and not fx_cache_ui.rescan.active
     and not deep_scan.active then
    local ident = S.resolve_pending_resume
    local saved_choice = S.resolve_pending_saved_choice == true
    S.resolve_pending_resume = nil
    S.resolve_pending_saved_choice = false
    S._resolve_deep_scan_attempted = nil
    S._resolve_context_unavailable_reported = nil
    if not RA.code_runtime_loaded() then
      RA.fail_code_runtime_unavailable("before resuming plugin resolution", "idle")
      return
    end
    if not RA.context_loaded() then
      RA.fail_context_unavailable("before resuming plugin resolution", "idle")
      return
    end
    Log.line("RESOLVE", "scan finished; resuming for " .. ident)
    Net.resolve_popup_resume(ident, saved_choice)
  end
end

-- =============================================================================
-- Safety output ceiling: host-side gmem poll + popup state
-- =============================================================================
-- Per-frame defer hook that watches gmem-mirror flags written by the JSFX
-- safety injection. Cheap fast-path via a global "any engagement"
-- sentinel; full per-slot scan only when the sentinel is set.
--
-- gmem layout (set by inject_output_ceiling render template):
--   gmem[1]            : global "any-instance engagement" flag
--   gmem[<slot>+0]     : per-instance engagement flag (latched by JSFX)
--   gmem[<slot>+1]     : per-instance lifetime engagement-sample count
--   gmem[<slot>+4]     : per-instance mute latch (0/1)
-- Tracked slots come from ExtState (Code.ceiling_get_slots).
--
-- State updated:
--   S._ceiling_muted_fx[slot] = { slot=, file=, desc= }   -- currently muted
--   S._ceiling_alert_pending  -- newly muted; popup wants opening
--   S._ceiling_alert_dismissed -- user clicked "Don't show again" this session
--   S._ceiling_gmem_attached   -- one-time gmem_attach guard
local CEILING_POLL_THROTTLE = 0.20   -- seconds between gmem polls

function Loop.handle_ceiling_poll()
  local now = time_precise()
  if S._ceiling_last_poll and (now - S._ceiling_last_poll) < CEILING_POLL_THROTTLE then
    return
  end
  S._ceiling_last_poll = now

  -- Lazy gmem_attach. Older REAPER builds don't have gmem_attach -- in
  -- that case the safety ceiling still works inside the JSFX (uses local
  -- _ra_muted), we just lose the host alert path. Skip silently.
  if not S._ceiling_gmem_attached then
    if not reaper.gmem_attach then return end
    reaper.gmem_attach(Code.CEILING_NS)
    S._ceiling_gmem_attached = true
  end

  -- One-shot slot GC per session. Drops ExtState entries for JSFX files
  -- that were deleted, overwritten without our injection, or re-injected
  -- with a different slot. Without this, `ceiling_get_slots()` grows
  -- without bound (allocation is monotonic) and the per-poll cost rises
  -- because every poll's `Code.ceiling_slot_is_active` walks all tracks
  -- per slot. Once-per-session is enough -- file deletion is rare, and
  -- the active-instance filter handles same-session orphans correctly
  -- until the next launch GCs them out.
  if not S._ceiling_gc_done then
    S._ceiling_gc_done = true
    pcall(Code.ceiling_gc_slots)
  end

  S._ceiling_muted_fx = S._ceiling_muted_fx or {}
  local poll_slots
  local function slots_for_poll()
    if not poll_slots then poll_slots = Code.ceiling_get_slots() end
    return poll_slots
  end

  -- Refresh-and-prune pass over every tracked entry.
  --   * gmem mirror still 1 AND at least one instance is "active"
  --     (track not muted, FX not bypassed, FX still in the chain)
  --     -> keep, mark is_active = true.
  --   * gmem mirror still 1 BUT no instance is active -> the user has
  --     muted the track, bypassed the FX, or removed it. Treat as
  --     user-resolved: clear the gmem mirror so a future re-enable
  --     starts from a clean slate, and drop the entry from the popup.
  --   * gmem mirror is 0 (JSFX-side auto-clear, e.g. slider change)
  --     -> keep entry as a record but mark is_active = false. The
  --     popup keeps it visible until the user dismisses.
  for slot, _entry in pairs(S._ceiling_muted_fx) do
    local mute_val = reaper.gmem_read(slot + Code.CEILING_GMEM_MUTE) or 0
    if mute_val >= 1 then
      if Code.ceiling_slot_is_active(slot, slots_for_poll()) then
        _entry.is_active = true
      else
        -- Stale: track muted, FX bypassed/removed, or all instances
        -- offline. Don't keep showing it in the popup, and clear the
        -- gmem mirror so the next poll doesn't re-detect a phantom
        -- mute when (e.g.) the user re-enables the track later.
        reaper.gmem_write(slot + Code.CEILING_GMEM_MUTE, 0)
        S._ceiling_muted_fx[slot] = nil
      end
    else
      _entry.is_active = false
    end
  end

  -- Cheap fast path: skip the new-mute scan when nothing has fired
  -- anywhere since the last poll.
  local any_eng = reaper.gmem_read(Code.CEILING_GMEM_GLOBAL_ENG)
  if (any_eng or 0) == 0 then return end

  -- Clear sentinel so the next poll detects fresh activity.
  reaper.gmem_write(Code.CEILING_GMEM_GLOBAL_ENG, 0)

  -- Per-slot scan to find newly-muted FX. Iterate every tracked slot
  -- (not just currently-muted ones) so we pick up a fresh trip.
  local slots = slots_for_poll()
  local newly_muted = false

  for _, e in ipairs(slots) do
    local mute_val = reaper.gmem_read(e.slot + Code.CEILING_GMEM_MUTE) or 0
    if mute_val >= 1 and not S._ceiling_muted_fx[e.slot] then
      -- Active-instance check: skip slots whose only instances are on
      -- muted tracks / behind a bypassed FX / no longer in any chain.
      -- A stale gmem `1` from a JSFX that was bypassed BEFORE the host
      -- poll started would otherwise pop a phantom alert on the next
      -- transport play. We also clear the mirror in that case so
      -- subsequent polls don't keep seeing it.
      if Code.ceiling_slot_is_active(e.slot, slots) then
        newly_muted = true
        local locations = Code.ceiling_find_fx_locations(e.slot, slots)
        S._ceiling_muted_fx[e.slot] = {
          slot      = e.slot,
          file      = e.file,
          desc      = e.desc or "",
          locations = locations,
          is_active = true,
        }
        Log.line("CEILING-POLL",
          ("mute detected: slot=%d desc=%s locations=%d"):format(
            e.slot, tostring(e.desc), #locations))
      else
        reaper.gmem_write(e.slot + Code.CEILING_GMEM_MUTE, 0)
      end
    end
  end

  if newly_muted and not S._ceiling_alert_dismissed then
    S._ceiling_alert_pending = true
  end
end

function Code.ceiling_slot_location_cache(slots)
  slots = slots or Code.ceiling_get_slots()
  local sig_parts = {}
  for i, e in ipairs(slots) do
    sig_parts[i] = tostring(e.slot or "") .. "\t" .. tostring(e.file or "")
  end
  local sig = table.concat(sig_parts, "\n")
  local state_count
  if reaper.GetProjectStateChangeCount then
    state_count = reaper.GetProjectStateChangeCount(0)
  end
  local cacheable = type(state_count) == "number"
  local cache = S and S._ceiling_location_cache or nil
  if cacheable and cache
     and cache.state_count == state_count
     and cache.slot_sig == sig then
    return cache
  end

  local targets = {}
  for _, e in ipairs(slots) do
    if e.slot and e.file and e.file ~= "" then
      local fname = e.file:match("[^/\\]+$") or e.file
      targets[#targets + 1] = {
        slot = e.slot,
        fx_ref_low = ("reaassist/" .. fname):lower(),
      }
    end
  end

  local built = {
    state_count = state_count,
    slot_sig = sig,
    locations_by_slot = {},
  }
  for _, target in ipairs(targets) do
    built.locations_by_slot[target.slot] = {}
  end
  if #targets == 0 then
    if cacheable and S then S._ceiling_location_cache = built end
    return built
  end

  local function walk(tr, idx_label, track_name)
    local fxc = reaper.TrackFX_GetCount(tr)
    for fi = 0, fxc - 1 do
      local _, fxname = reaper.TrackFX_GetFXName(tr, fi, "")
      local fx_low = fxname and fxname:lower() or ""
      for _, target in ipairs(targets) do
        if fx_low:find(target.fx_ref_low, 1, true) then
          local locs = built.locations_by_slot[target.slot]
          locs[#locs + 1] = {
            track_idx  = idx_label,
            track_name = track_name or "",
            fx_idx     = fi + 1,
            fx_name    = fxname or "",
          }
        end
      end
    end
  end

  local master = reaper.GetMasterTrack(0)
  if master then
    local _, mname = reaper.GetTrackName(master, "")
    walk(master, "M", mname or "Master")
  end
  local tcount = reaper.CountTracks(0)
  for ti = 0, tcount - 1 do
    local tr = reaper.GetTrack(0, ti)
    if tr then
      local _, tname = reaper.GetTrackName(tr, "")
      walk(tr, ti + 1, tname or "")
    end
  end

  if cacheable and S then S._ceiling_location_cache = built end
  return built
end

-- Walk every track's FX chain to find every instance of the JSFX whose
-- recorded slot matches `slot`. Returns a list of location records:
--   { track_idx (1-based, "M" for master), track_name, fx_idx (1-based),
--     fx_name }
-- The popup uses this to tell the user "Track 5 'Vocal' / FX 2: <name>"
-- per occurrence, since the same .jsfx file can be loaded on multiple
-- tracks and they ALL share one slot/_ra_muted state.
function Code.ceiling_find_fx_locations(slot, slots)
  local cache = Code.ceiling_slot_location_cache(slots)
  -- Read-only shared cache table for the current project-state window.
  return cache.locations_by_slot[slot] or {}
end

-- Returns true if at least one instance of the JSFX bound to this slot
-- is "live" right now -- i.e. its track is not muted AND the FX itself
-- is enabled (not bypassed) AND it is still in a track's FX chain.
--
-- Used by the ceiling poll to filter out stale gmem mute mirrors when
-- the user has muted the track or bypassed the FX. Without this filter,
-- the mute mirror set during a previous run would sit at `1` forever
-- (a non-running JSFX cannot clear its own gmem) and the popup would
-- keep claiming the FX is muted on every replay -- which is the exact
-- bug this addresses.
--
-- Location caches are keyed to `GetProjectStateChangeCount`, so moved or
-- renamed FX refresh on the next project-state change without walking the
-- whole FX graph once per tracked slot.
function Code.ceiling_slot_is_active(slot, slots)
  local locs = Code.ceiling_find_fx_locations(slot, slots)
  if #locs == 0 then return false end
  for _, loc in ipairs(locs) do
    local tr
    if loc.track_idx == "M" then
      tr = reaper.GetMasterTrack(0)
    elseif type(loc.track_idx) == "number" then
      tr = reaper.GetTrack(0, loc.track_idx - 1)
    end
    if tr then
      local muted   = (reaper.GetMediaTrackInfo_Value(tr, "B_MUTE") or 0) > 0.5
      local enabled = reaper.TrackFX_GetEnabled(tr, (loc.fx_idx or 1) - 1)
      if (not muted) and enabled then return true end
    end
  end
  return false
end

-- Diagnose-with-model: attach the JSFX file as an actual attachment and
-- prefill the chat input with a templated diagnostic prompt. Cross-
-- platform via Attach.file (io.open / os.* paths), no shell-out.
function Code.ceiling_diagnose_one(slot)
  local muted = S._ceiling_muted_fx and S._ceiling_muted_fx[slot]
  if not muted or not muted.file then return end

  -- Confirm file still exists before attempting attach (the user could
  -- have deleted it manually since the slot was recorded).
  local f = io.open(muted.file, "rb")
  if not f then
    local fallback = "Could not read JSFX file for diagnosis: "
      .. tostring(muted.file)
    Log.add_error((RA and RA.t and RA.t("jsfx.diagnose.read_failed",
      { path = tostring(muted.file) }, fallback)) or fallback)
    return
  end
  f:close()

  -- Use the existing attach pipeline. Attach.file handles read, size
  -- checks, classification, and queue add. Errors land in
  -- S.attach_error and surface in the chat input bar like any other
  -- failed attach.
  local ok = Attach.file(muted.file)
  if not ok then
    -- attach_error already set by Attach.file. User sees it next frame.
    return
  end

  -- Templated diagnostic prompt; user reviews and sends. Keep it short --
  -- the attached file carries the full code; the prompt just tells the
  -- model what we want analyzed.
  local fname = muted.file:match("[^/\\]+$") or muted.file
  S.input_buf = ([[The attached JSFX (%s%s) is muting itself because ReaAssist's safety output ceiling detected sustained signal above the configured ceiling for >50 ms -- a likely runaway-feedback or DSP math bug producing exponential growth. Please analyze the DSP and identify what's wrong.

What's causing the runaway, and what specific change would fix it? Do NOT modify the safety injection blocks (lines marked `// --- ReaAssist output ceiling`); only fix the user-facing DSP code.]]):format(
    fname,
    (muted.desc ~= "" and muted.desc ~= fname)
      and (' -- "' .. muted.desc .. '"') or "")

  -- Drop the entry so a fresh trip on the same slot later re-opens the
  -- popup. Without this, S._ceiling_muted_fx[slot] would still be set
  -- after Diagnose closes the popup, and the next mute on that slot
  -- wouldn't be flagged "newly muted" by the poll loop.
  S._ceiling_muted_fx     = S._ceiling_muted_fx or {}
  S._ceiling_muted_fx[slot] = nil

  -- Close the popup so the user can see the chat with the attachment.
  S._ceiling_alert_pending = false
  S._ceiling_alert_open    = false
end

-- Dispatch one tick of the curl pump. If an overload retry is scheduled and its
-- deadline has passed, re-fire the saved request body. Otherwise, when a
-- request is in flight, throttle-poll the response file (0.1s minimum).
function Loop.pump_curl_or_retry()
  if S.retry_scheduled then
    local schannel_retry = S.schannel_revocation_retry_pending == true
    local now = time_precise()
    if now >= S.retry_fire_time then
      S.retry_scheduled = false
      S.schannel_revocation_retry_pending = false
      Net._set_pending_request_status("sent", nil, {
        retry_count = schannel_retry and 1 or S.retry_count,
        retry_max = schannel_retry and 1 or S.retry_max,
        clear_display_text = true,
      })
      Code.safe_write(tmp.out, "")
      if S.retry_saved_body then
        local ok, reason = Net.fire_curl(S.retry_saved_body, {
          provider_idx = S.retry_saved_provider_idx,
          model_idx = S.retry_saved_model_idx,
          thinking_idx = S.retry_saved_thinking_idx,
          transport_retry = true,
          ssl_revoke_best_effort = schannel_retry,
        })
        if ok then
          S.status = "waiting"
        else
          if schannel_retry then
            if Net._surface_schannel_revocation_original_error() then
              Net._clear_terminal_curl_state()
            end
          elseif reason ~= "call_cap_exceeded" then
            Log.add_error(
              "The servers are still busy and the automatic retry didn't "
              .. "go through. Please try again in a moment.")
            Net._clear_terminal_curl_state()
          end
          S.retry_count = 0
          S.retry_max = CFG.MAX_RETRIES
        end
      else
        if schannel_retry then
          if Net._surface_schannel_revocation_original_error() then
            Net._clear_terminal_curl_state()
          end
        else
          Log.add_error(
            "The servers are still busy and the automatic retry didn't "
            .. "go through. Please try again in a moment.")
          Net._clear_terminal_curl_state()
        end
        S.retry_count = 0
        S.retry_max = CFG.MAX_RETRIES
      end
    end
  elseif S.status == "waiting" or S.curl_pid or S.gemini_tier_pending then
    local now = time_precise()
    if now - S.last_poll_time >= CFG.POLL_THROTTLE then
      S.last_poll_time = now
      local ok_poll, poll_error = pcall(Net.try_finish_curl)
      if S.google_interactions_pending and not S.curl_pid then
        Net._discard_google_interactions_pending()
      end
      if not ok_poll then error(poll_error, 0) end
    end
  end
end

TypedActionController = TypedActionController or {}

function TypedActionController.t(key, values, fallback)
  return RA.t(key, values, fallback)
end

function TypedActionController.trim_text(text)
  return tostring(text or ""):match("^%s*(.-)%s*$") or ""
end

function TypedActionController.active_provider()
  return PROVIDERS and PROVIDERS.active and PROVIDERS.active() or nil
end

function TypedActionController.active_provider_is_usable()
  local p = TypedActionController.active_provider()
  if not p then return false end
  if p.is_custom then return true end
  return S.api_key ~= nil and tostring(S.api_key) ~= ""
end

function TypedActionController.request_is_active()
  return S.status == "waiting"
    or S.status == "awaiting_confirmation"
    or S.curl_pid ~= nil
    or S.retry_scheduled == true
    or S.turn_budget_confirmation ~= nil
end

function TypedActionController.message_has_typed_actions(msg)
  return type(msg) == "table"
    and type(msg.typed_actions) == "table"
    and msg.typed_actions.present == true
    and not (type(msg.code_block) == "string" and msg.code_block ~= "")
end

function TypedActionController.generated_code_text(msg)
  if not msg then return "" end
  if TypedActionController.message_has_typed_actions(msg) then
    if type(msg.generated_code) == "table"
        and msg.generated_code.content
        and msg.generated_code.content ~= "" then
      return tostring(msg.generated_code.content)
    end
    if msg.typed_actions_artifact and msg.typed_actions_artifact ~= "" then
      return tostring(msg.typed_actions_artifact)
    end
    if msg.code_block and msg.code_block ~= "" then
      return tostring(msg.code_block)
    end
  end
  if msg.code_block and msg.code_block ~= "" then
    return tostring(msg.code_block)
  end
  if type(msg.generated_code) == "table"
      and msg.generated_code.content
      and msg.generated_code.content ~= "" then
    return tostring(msg.generated_code.content)
  end
  if msg.typed_actions_artifact and msg.typed_actions_artifact ~= "" then
    return tostring(msg.typed_actions_artifact)
  end
  return ""
end

function TypedActionController.generated_code_type(msg)
  if not msg then return nil end
  if TypedActionController.message_has_typed_actions(msg) then
    return "typed_actions"
  end
  if type(msg.generated_code) == "table"
      and msg.generated_code.content
      and msg.generated_code.content ~= "" then
    return msg.generated_code.code_type or msg.code_type
  end
  if msg.typed_actions_artifact and msg.typed_actions_artifact ~= "" then
    return "typed_actions"
  end
  return msg.code_type
end

function TypedActionController.typed_action_has_results(msg)
  if not TypedActionController.message_has_typed_actions(msg) then return false end
  local ar = msg.typed_actions and msg.typed_actions.action_results or nil
  return type(ar) == "table" and #ar > 0
end

function TypedActionController.message_undo_sent(msg)
  return type(msg) == "table"
    and (msg.screen_reader_undo_clicked == true
      or msg.typed_action_undo_clicked == true
      or msg.lua_undo_clicked == true)
end

function TypedActionController.message_has_applied_typed_action(msg)
  return TypedActionController.message_has_typed_actions(msg)
    and not TypedActionController.message_undo_sent(msg)
    and (msg.auto_ran == true
      or msg.run_status == "ran_ok"
      or TypedActionController.typed_action_has_results(msg))
end

function TypedActionController.message_can_undo_generated_action(msg)
  if not msg or TypedActionController.message_undo_sent(msg) then return false end
  if TypedActionController.message_has_typed_actions(msg) then
    return TypedActionController.message_has_applied_typed_action(msg)
      and type(Code) == "table"
      and type(Code.project_is_active) == "function"
      and Code.project_is_active(msg._typed_action_run_project)
  end
  local code = TypedActionController.generated_code_text(msg)
  if code == "" then return false end
  local code_type = TypedActionController.generated_code_type(msg)
  if code_type == "lua" then
    return type(Code) == "table"
      and type(Code.run_result_can_undo) == "function"
      and Code.run_result_can_undo(msg.run_result, msg._lua_run_project)
  end
  return false
end

function TypedActionController.apply_typed_action_message(msg, message_idx, opts)
  opts = opts or {}
  if not TypedActionController.message_has_typed_actions(msg) then
    return false, "no_plan", TypedActionController.t(
      "a11y.sr.apply_action_plan_unavailable", nil,
      "There is no validated edit to run.")
  end
  if TypedActionController.message_has_applied_typed_action(msg) then
    return false, "already_applied", TypedActionController.t(
      "a11y.sr.apply_action_plan_already_applied", nil,
      "This structured edit has already been run.")
  end
  if TypedActionController.request_is_active() then
    return false, "request_active", TypedActionController.t(
      "a11y.sr.request_already_running", nil,
      "A request is already running.")
  end
  if msg.run_status == "pending"
      or (msg.typed_actions and msg.typed_actions.deferred_pending == true) then
    return false, "pending", TypedActionController.t(
      "a11y.sr.apply_action_plan_pending", nil,
      "Structured edit is running.")
  end
  if not (Code and type(Code.execute_typed_actions_from_text) == "function") then
    return false, "executor_unavailable", TypedActionController.t(
      "typed_actions.error.executor_unavailable", nil,
      "Structured edit executor is unavailable.")
  end

  if prefs and prefs.auto_backup and not opts.skip_backup
      and Code and Code.safety_backup then
    local _, berr = Code.safety_backup()
    if berr == "unsaved" then
      return false, "backup_unsaved", TypedActionController.t(
        "a11y.sr.apply_action_plan_backup_unsaved", nil,
        "Auto-backup is on, but the project has not been saved.")
    elseif not Code.safety_backup_can_proceed(berr) then
      return false, "backup_failed", TypedActionController.t(
        "a11y.sr.apply_action_plan_backup_failed",
        { error = tostring(berr) },
        "Safety backup failed: " .. tostring(berr))
    end
  end

  local plan_text = TypedActionController.generated_code_text(msg)
  if plan_text == "" then
    return false, "no_plan", TypedActionController.t(
      "a11y.sr.apply_action_plan_unavailable", nil,
      "There is no validated edit to run.")
  end

  local user_text = TypedActionController.user_prompt_before_message(
    message_idx) or ""
  local profile = Code and Code.typed_actions_model_profile
    and Code.typed_actions_model_profile(msg.provider_id, msg.model_id) or nil

  local function apply_result(done_ok, exec_result)
    local completed_result = exec_result
      and (exec_result.result or exec_result) or nil
    local applied_now = completed_result
      and type(completed_result.action_results) == "table"
      and #completed_result.action_results > 0
    msg.auto_run_block_reason = nil
    msg.typed_actions = msg.typed_actions or { present = true }
    msg.typed_actions.deferred_pending = nil
    msg.typed_actions.executed = done_ok == true
    if completed_result and completed_result.action_results then
      msg.typed_actions.action_results = completed_result.action_results
    end
    msg._typed_action_run_project = completed_result
      and completed_result._execution_project or nil
    if done_ok then
      msg.auto_ran = false
      msg.typed_action_undo_clicked = nil
      msg.screen_reader_undo_clicked = nil
      msg.run_status = "ran_ok"
      msg.validation_status = "passed"
      msg.validation_block_kind = nil
      msg.error_kind = nil
      msg.error_debug = nil
      msg.runtime_error = nil
      msg.typed_actions.error = nil
      msg.content = TypedActionController.t(
        "a11y.sr.apply_action_plan_done", nil,
        "Structured edit ran.")
      if type(Code.typed_actions_display_text) == "function" then
        msg.typed_action_summary = Code.typed_actions_display_text(plan_text,
          msg.typed_actions.action_results)
      end
      if type(Code.build_run_result) == "function" then
        msg.run_result = Code.build_run_result("typed_actions", plan_text,
          "ran_ok", "passed", {
            auto_ran = false,
            validation_block_kind = nil,
          })
      end
    else
      local err = exec_result and exec_result.code or "execution_failed"
      msg.auto_ran = false
      if applied_now then
        msg.typed_action_undo_clicked = nil
        msg.screen_reader_undo_clicked = nil
      end
      msg.run_status = "errored"
      msg.validation_status = "failed"
      msg.validation_block_kind = err
      msg.typed_actions.error = err
      msg.content = Code.typed_actions_user_failure_message(exec_result)
      if type(Code.build_run_result) == "function" then
        msg.run_result = Code.build_run_result("typed_actions", plan_text,
          "errored", "failed", {
            auto_ran = false,
            validation_block_kind = err,
            error_kind = "runtime_error",
            runtime_error = tostring(msg.content or err),
            error_debug = {
              failure_kind = "runtime_error",
              source = "typed_action_executor",
              typed_action_error = tostring(err),
            },
          })
      end
    end
    S.status = done_ok and "idle" or "error"
  end

  S.status = "running"
  local exec_ok, exec_result = Code.execute_typed_actions_from_text(plan_text, {
    allow_raw_json = true,
    user_text = user_text,
    profile = profile,
    on_done = function(done_ok, done_result)
      apply_result(done_ok == true, done_result)
      S.scroll_to_bottom = true
      S.refocus_prompt = true
    end,
  })
  local exec_pending = exec_ok and exec_result
    and exec_result.deferred == true
    and exec_result.completed ~= true
  if exec_pending then
    msg.run_status = "pending"
    msg.validation_status = "pending"
    msg.typed_actions = msg.typed_actions or { present = true }
    msg.typed_actions.deferred = true
    msg.typed_actions.deferred_pending = true
    msg.content = TypedActionController.t(
      "a11y.sr.apply_action_plan_pending", nil,
      "Structured edit is running.")
    return true, nil, msg.content
  end

  apply_result(exec_ok == true, exec_result)
  S.refocus_prompt = true
  if exec_ok then
    return true, nil, TypedActionController.t(
      "a11y.sr.apply_action_plan_done", nil,
      "Structured edit ran.")
  end
  return false, "execution_failed",
    Code.typed_actions_user_failure_message(exec_result)
end

function TypedActionController.user_prompt_before_message(message_idx)
  local start_idx = tonumber(message_idx) or #(S.display_messages or {})
  for j = start_idx - 1, 1, -1 do
    local m = S.display_messages and S.display_messages[j] or nil
    if m and m.role == "user" and m.content and m.content ~= "" then
      return tostring(m.content)
    end
  end
  return nil
end

function TypedActionController.typed_action_lua_request_prompt(original_request)
  local lang_note = ""
  local reply_lang = (I18N and I18N.prompt_language_name
      and I18N.prompt_language_name())
    or (CFG.prompt_language_name_for_idx
      and CFG.prompt_language_name_for_idx(prefs.reply_language_idx or 1))
    or (CFG.REPLY_LANGUAGE_CODES
      and CFG.REPLY_LANGUAGE_CODES[prefs.reply_language_idx or 1])
    or "English"
  if reply_lang and reply_lang ~= "" and reply_lang ~= "English" then
    lang_note = "Use " .. reply_lang .. " for visible script comments, "
      .. "script title text, Undo_EndBlock labels, ShowMessageBox text, "
      .. "console/debug text, and other user-visible string literals. "
      .. "Keep REAPER API names, identifiers, plugin names, paths, and "
      .. "user-supplied filenames unchanged.\n\n"
  end
  return lang_note
    .. "Please give me the normal REAPER Lua/ReaScript version of this "
    .. "request instead of a structured edit. Return one complete runnable "
    .. "script inside a ```lua code fence. Do not use structured edits or "
    .. "typed-action JSON.\n\nOriginal request:\n"
    .. tostring(original_request or "")
end

function TypedActionController.current_lua_generation_context()
  local generation = S.pending_typed_action_lua_generation
  if type(generation) ~= "table" then return nil end
  if generation.request_display_idx == nil
      or generation.request_display_idx ~= S.pending_display_idx then
    Net._clear_pending_typed_action_lua_generation(generation)
    return nil
  end
  return generation
end

function TypedActionController.request_lua_for_typed_action_message(msg,
                                                                  message_idx,
                                                                  opts)
  if TypedActionController.request_is_active() then
    return false, TypedActionController.t("a11y.sr.request_already_running", nil,
      "A request is already running.")
  end
  if not TypedActionController.active_provider_is_usable() then
    return false, TypedActionController.t("a11y.sr.provider_not_configured", nil,
      "The selected provider needs an API key before ReaAssist can send.")
  end
  if not TypedActionController.message_has_typed_actions(msg) then
    return false, TypedActionController.t("a11y.sr.request_lua_unavailable", nil,
      "Could not request the Lua/ReaScript version.")
  end
  Net._clear_pending_typed_action_lua_generation()
  if msg.typed_action_lua_requested == true then
    return false, TypedActionController.t("a11y.sr.request_lua_unavailable", nil,
      "Could not request the Lua/ReaScript version.")
  end
  local original_request = TypedActionController.user_prompt_before_message(message_idx)
  if not original_request or original_request == "" then
    return false, TypedActionController.t("typed_actions.no_original_prompt", nil,
      "Could not find the original prompt")
  end
  local generation = {
    source_message = msg,
    source_message_idx = tonumber(message_idx),
  }
  S.pending_typed_action_lua_generation = generation
  msg.typed_action_lua_generation_pending = true
  S.refocus_prompt = true
  S.skip_local_answer_once = true
  S.suppress_user_display_once = true
  local call_ok, sent, reason, send_handling = pcall(Net.send_to_api,
    TypedActionController.typed_action_lua_request_prompt(original_request),
    {
      force_provider = true,
      typed_action_lua_generation = generation,
    })
  if not call_ok or (sent ~= true and S.turn_budget_confirmation == nil) then
    S.skip_local_answer_once = nil
    S.suppress_user_display_once = nil
    Net._clear_pending_typed_action_lua_generation(generation)
    if not call_ok and Log and Log.add_error then
      Log.add_error(TypedActionController.t("typed_actions.request_lua_failed",
        nil, "Could not request the Lua/ReaScript version."), nil, nil, nil,
        Net._send_exception_extra("typed_action_request_lua", sent))
    end
    local failure_handling = call_ok and (send_handling or "boundary")
      or "surfaced"
    local failure_message = reason
    if failure_handling ~= "surfaced" then
      failure_message = TypedActionController.t(
        "typed_actions.request_lua_failed", nil,
        "Could not request the Lua/ReaScript version.")
    end
    return false, failure_message, failure_handling
  end
  return true, TypedActionController.t("a11y.sr.request_lua_sent", nil,
    "Generating and validating the Lua/ReaScript version. The structured edit remains unchanged.")
end

-- Screen Reader Mode's presentation layer lives in
-- ReaAssist_Screen_Reader_Mode.lua. Keep ReaAssist.lua limited to shared
-- app/controller plumbing so the normal visual app stays clean.
local function loop()
  if CFG._PRODUCT:lower() ~= CFG.EXT_NS then return end

  if not S.startup_first_frame_submitted then
    Startup.mark("first_loop_start")
  end

  -- In-frame ReaImGui context check, one-shot. Mirror of the guard at
  -- the top of Bootstrap.loop -- defense in depth for the case where a
  -- freshly-installed ReaImGui dylib lets the script skip bootstrap
  -- entirely (resources already on disk) and lands directly here.
  if not S.imgui_in_frame_validated then
    if not RA.imgui_in_frame_context_ok() then
      S.script_open = false
      return
    end
    S.imgui_in_frame_validated = true
  end

  -- The first direct loop call cannot run deferred startup work because the
  -- frame flag is still false. The next REAPER defer turn runs one task, then
  -- the following turn runs the other, so first-frame submission stays clear.
  Loop.run_post_paint_startup()

  -- The parked copy, offered on the same settled frame and for the same reason
  -- it cannot live in a load-time do-block: it asks the uninstall marker, the
  -- journal and the apply lock, and none of them exists while this file is
  -- still being read. It is a dispatcher rather than a one-shot, because the
  -- startup update check can hold the updater busy past a single turn.
  --
  -- Protected at the call the way the cleanup above is: a raise here would
  -- otherwise take the frame with it, and the dispatcher counts its turn before
  -- it acts, so a swallowed raise still runs out of turns instead of retrying
  -- forever.
  do
    local parked, park_err = pcall(Updater.park_dispatch)
    if not parked then
      Log.line("UPDATE", "parked copy: raised; " .. tostring(park_err))
    end
  end

  -- No step continues while a deploy holds the lock. The tick is what would
  -- write the installer journal, so it is not taken at all rather than taken
  -- and refused inside.
  if EngineInstallerHost and type(EngineInstallerHost.tick) == "function"
      and not RA.deploy_lock_installer_held() then
    local recovered, recovery_err = pcall(
      EngineInstallerHost.tick, EngineInstallerHost)
    if not recovered then
      EngineInstallerHost.paused = true
      Log.line("ENGINE-INSTALL", "recovery tick raised: "
        .. tostring(recovery_err))
    end
  end

  do
    local ok, err = pcall(Loop.finish_support_installation)
    if not ok then
      S._support_install_checked = true
      S._support_install_preparing = nil
      S._engine_installer_ui_error = RA.t("engine.install.unexpected_error", nil,
        "The installation action failed. Check the installation status before trying again.")
      Log.line("ENGINE-INSTALL", "automatic startup failed: " .. tostring(err))
    end
  end
  Loop.handle_close_signal()
  Loop.handle_dev_signal()

  if type(S.openrouter_catalog_operation) == "table" then
    local ok_catalog, catalog_error = pcall(Net.poll_openrouter_catalog)
    if not ok_catalog then
      Net._close_openrouter_catalog_operation(
        S.openrouter_catalog_operation, true)
      local reason = tostring(catalog_error)
      Net._set_openrouter_settings_status("catalog", "failed",
        Net._openrouter_message("settings.openrouter.catalog.poll_failed", {
          reason = reason,
        }, "OpenRouter catalog polling failed: " .. reason))
    end
  end
  if type(S.openrouter_deliberate_test_operation) == "table" then
    local ok_test, test_error = pcall(Net.poll_openrouter_deliberate_test)
    if not ok_test then
      Net._close_openrouter_deliberate_test(
        S.openrouter_deliberate_test_operation, true)
      local reason = tostring(test_error)
      Net._set_openrouter_settings_status("test", "failed",
        Net._openrouter_message("settings.openrouter.test.poll_failed", {
          reason = reason,
        }, "OpenRouter billed test polling failed: " .. reason))
    end
  end

  -- Pump attachment base64 encoding one chunk per frame so large files
  -- don't block the UI thread when the user attaches them. The Send button
  -- stays disabled (via Attach.all_encoded()) until pumping completes.
  Attach.pump_encoding()

  -- Preferred plugins parameter scan: phase 2 runs one frame after phase 1
  -- so that newly added FX have initialised their parameter lists.
  if RA.context_loaded() then
    if pref_plugins.scan.active and pref_plugins.scan.phase == "reading" then
      CTX.pref_plugins_scan_read()
    end
    -- FX cache single-plugin rescan: same deferred pattern.
    if fx_cache_ui.rescan.active and fx_cache_ui.rescan.phase == "reading" then
      CTX.fx_cache_rescan_read()
    end
    Loop.handle_resolve_deep_scan()
    -- Deep FX param scan: resume one coroutine step per frame.
    if deep_scan.active then CTX.pump_deep_scan() end
  else
    if pref_plugins.scan.active then CTX.pref_plugins_scan_read() end
    if fx_cache_ui.rescan.active then
      if fx_cache_ui.rescan.phase == "reading" then
        CTX.fx_cache_rescan_read()
      else
        fx_cache_ui.rescan.status =
          RA.context_unavailable_message("before rescanning FX parameters")
      end
    end
    if deep_scan.active then CTX.cancel_deep_scan() end
  end

  -- Refresh the running lock (instance_id|timestamp) once per second. The
  -- staleness detector's tolerance (STALE_LOCK_SECS = 15) makes per-frame
  -- writes redundant, and SetExtState allocates + formats a new string every
  -- call, so throttling drops ~60 unnecessary writes/sec during normal UI use.
  local now_hb = time_precise()
  if not S._last_heartbeat or now_hb - S._last_heartbeat >= 1.0 then
    S._last_heartbeat = now_hb
    reaper.SetExtState(CFG.EXT_NS, "running",
      S.INSTANCE_ID .. "|" .. tostring(now_hb), false)
    RA.write_temp_live_marker(now_hb)
  end

  Loop.pump_curl_or_retry()
  if OptionalFonts and OptionalFonts.poll then OptionalFonts.poll() end
  -- Do not auto-refresh remote language packs from the interactive loop.
  -- That path can launch PowerShell/curl on Windows and make the first
  -- visible interaction after startup feel blocked. Cached packs render
  -- immediately; explicit language downloads/refreshes still use LangPacks.
  if LangPacks and LangPacks.poll then LangPacks.poll() end
  Loop.handle_ceiling_poll()

  -- Gemini tier auto-retest: armed at startup if the last result was
  -- ambiguous (so persisted tier is nil) and a Google key is configured.
  -- Wait until no other curl is in flight before firing -- the tier test
  -- shares the curl plumbing and would no-op silently otherwise.
  if S.gemini_auto_retest_pending and not S.curl_pid then
    local p = PROVIDERS and PROVIDERS.active and PROVIDERS.active() or nil
    if p and p.id == "google" then
      S.gemini_auto_retest_pending = false
      Net.fire_gemini_tier_test()
    end
  end

  -- Deferred key-test: fire_key_test parked here when curl_pid was busy
  -- (typically because the auto-retest tier test was in flight). Re-fire
  -- once curl clears. 30s armed-at ceiling so a stuck pending state
  -- can't trap the queue indefinitely -- surface the failure through
  -- the normal in-flight error path so the user gets a clear message
  -- instead of waiting forever.
  if S.key_test_armed and not S.curl_pid then
    local armed = S.key_test_armed
    if not api_keys.key_test_context_current(armed.origin,
        armed.generation, armed.screen_context) then
      api_keys.cancel_key_test()
      Code.safe_write(tmp.out, "")
    elseif time_precise() - armed.armed_at > 30 then
      S.key_test_armed = nil
      local label   = armed.provider.label
      local prov_id = armed.provider.id
      api_keys.discard_key_candidate(prov_id)
      local short_msg = RA.t(
        "settings.api_key.error.in_flight_timeout_short", nil,
        "Another request was in progress for too long. Try Test API Keys again.")
      if #api_keys.test_queue > 0
         and (api_keys.screen == "first_run" or api_keys.screen == "settings") then
        Net.advance_key_test_queue(prov_id, false, short_msg)
      elseif (api_keys.screen == "first_run" or api_keys.screen == "settings") then
        api_keys.key_validating = false
        api_keys.key_validating_idx = nil
        api_keys.key_error      = short_msg
        api_keys.show_key_error_popup = true
        api_keys.key_error_provider   = label
        api_keys.key_error_detail     = short_msg
        api_keys.key_error_hint       =
          RA.t("settings.api_key.error.in_flight_timeout_hint", nil,
            "Wait for any in-flight request to finish, then try again.")
        api_keys.key_error_url        = nil
        api_keys.key_error_url_label  = nil
      else
        Log.add_error(short_msg)
      end
      if #api_keys.test_queue == 0 then
        api_keys.restore_key_test_provider()
        api_keys.finish_key_test_session()
      end
    else
      S.key_test_armed = nil
      Net.fire_key_test(armed.provider, {
        api_key_override = armed.api_key_override,
      })
    end
  end

  -- Gemini cache-create poll runs independently of the main send pipeline
  -- (separate tmp files), so a cache create can complete in parallel with a
  -- user send without interfering with the response parse path.
  if S.gemini_cache_creating
      or type(S.gemini_cache_engine_handle) == "table"
      or #(S.gemini_cache_engine_cleanup_handles or {}) > 0 then
    local now = time_precise()
    if now - S.last_cache_poll_time >= CFG.POLL_THROTTLE then
      S.last_cache_poll_time = now
      Net.gemini_cache_tick()
    end
  end

  -- Deferred-kill watchdog: if Cancel was clicked before the launcher finished
  -- writing tmp.pid, retry the kill on every loop tick until the file lands or
  -- the deadline elapses. Cheap (one io.open per frame for ~2s).
  if S.kill_pending then
    Net.try_finish_kill_pending()
  end

  -- Drive diagnostics upload work: polls in-flight POST exit/status files and
  -- lets the idle auto-diagnostics queue advance when no upload is active.
  -- Grouped here with the other network pollers above.
  if Diag.uploader_enabled then Diag.tick() end

  -- Piggyback the once-per-session update check on the first chat-SEND in
  -- this session (transition idle -> waiting), not on the first chat
  -- completion. The reason is purely UX: the manifest fetch plus
  -- incremental SHA verification do real work (CFG.UPDATE_SHA_TIME_BUDGET
  -- per frame, spread across roughly 1-2 seconds total on commodity hardware,
  -- proportionally longer on slower CPUs but with no per-frame stutter). If
  -- that ran AFTER the response was shown, the user would feel subtle
  -- micro-stutters while typing their next message. Running it DURING the
  -- "Thinking..." phase absorbs it into time the user is already waiting,
  -- so by the time the response arrives the verify is usually complete
  -- and the post-response UI stays perfectly smooth.
  --
  -- The check is DEFERRED by CFG.UPDATE_CHECK_DEFER seconds rather than
  -- firing on the very next frame after idle->waiting. The chat curl's
  -- own ExecProcess fires on the send frame and blocks the main thread
  -- for ~1-3 s cold-start of PowerShell; stacking the update-check
  -- ExecProcess (another ~200 ms warm) onto the immediately-following
  -- frame extended the perceived Send-press freeze. Deferring 400 ms
  -- lands the update spawn after PS is warm and after the chat-curl
  -- freeze is fully done, so its 200 ms hitch falls inside "Thinking..."
  -- where the spinner is up and the user expects nothing else to happen.
  -- ExecProcess timeoutmsec must remain >= 0 -- timeoutmsec = -1 (true
  -- async no-wait) flashes a PowerShell/cmd window on Windows because
  -- REAPER's async path skips the hidden-window flag.
  --
  -- _session_check_fired is a session-level guard: it ensures only ONE
  -- piggyback ATTEMPT per ReaAssist launch. The flag is set before
  -- check_start is called, and check_start declines on its busy guards
  -- (updater, font download, language download), so a session can spend its
  -- one attempt without a check happening and nothing retries it. That is
  -- deliberate, and the settings copy says "tries one automatic check"
  -- rather than promising one (Codex round 65, work package B2.5b). Users
  -- who never send a message, and users whose one attempt was declined, can
  -- still check via Settings > Advanced > Check for Updates.
  -- _session_check_armed_at is the time of the idle->waiting edge; the
  -- defer compares against it on each subsequent frame until the budget
  -- elapses, then fires once and clears via _session_check_fired.
  -- check_start itself has a busy guard (Updater.is_busy) so an in-flight
  -- manual check or repair cannot be raced by this trigger.
  if not update._session_check_fired then
    if not update._session_check_armed_at
        and S._prev_status == "idle" and S.status == "waiting" then
      update._session_check_armed_at = time_precise()
    end
    if update._session_check_armed_at
        and (time_precise() - update._session_check_armed_at)
            >= CFG.UPDATE_CHECK_DEFER then
      update._session_check_fired = true
      Updater.check_start()
    end
  end
  S._prev_status = S.status

  -- One-time post-update nudge for power-user prompt overrides. Set by
  -- Updater._apply_finish when an update changed the stock system prompt
  -- while a custom override was active. Fired once per loop, gated so
  -- the toast appears immediately on launch (not after a chat). The
  -- ExtState is cleared the same frame we read it so the toast never
  -- repeats, even if the user closes the window before the toast fades.
  if not S._prompt_nudge_checked then
    S._prompt_nudge_checked = true
    if reaper.GetExtState(CFG.EXT_NS, "prompt_review_pending") == "1" then
      reaper.DeleteExtState(CFG.EXT_NS, "prompt_review_pending", true)
      UI.show_float_toast(
        "System prompt updated. Your custom override is unchanged; "
        .. "review the new stock prompt for changes worth merging.",
        "ok", true)  -- sticky: stays until replaced or window closes
    end
  end

  -- One existence probe per frame across the critical set, so a sync that
  -- deletes files under a live session is noticed before the next request
  -- rather than during it.
  Updater.sentinel_tick()

  -- Auto-update polling (independent of main API pipeline).
  Updater.try_silent_manifest_repair()
  Updater.try_manifest_restore()
  if update.state == "checking" then
    Updater.check_poll()
  elseif update.state == "verifying" then
    -- Dispatch to native-poll or pure-Lua tick based on which mode
    -- start_sha_diff selected (and which mode tick_native_sha may have
    -- since fallen back to). _sha_diff is cleared on completion so the
    -- nil-guard handles the rare "complete-on-this-frame" race.
    local s = update._sha_diff
    if s and s.mode == "native" then
      Updater.tick_native_sha()
    else
      Updater.tick_sha_diff()
    end
  elseif update.state == "downloading_batch" then
    Updater.batch_download_poll()
  elseif update.state == "verifying_download" then
    Updater.download_verify_tick()
  elseif update.state == "applying" then
    Updater.apply_tick()
  end
  Updater.settle_silent_manifest_failure()
  -- Stage 3.4 auto-restart: fires once after the apply completes and a
  -- short grace window elapses so the user sees the "Applied" message
  -- before the script relaunches itself.
  Updater.try_auto_restart()

  -- Main-window ImGui pipeline: style pushes, ImGui_Begin on the
  -- main window, full chat/settings/popup body (including the
  -- after_main_window first-frame boot-guard label), balancing
  -- PopStyleColor/PopStyleVar/PopFont, and the separate
  -- Update-Available / Repair dialog. Lives in
  -- Resources/UI.lua as Render.main_window so the UI half
  -- owns the draw path. Returns `open` so we can still detect the
  -- window's X button below (outside the visible-block scope).
  if UI and UI.apply_remembered_ui_scale then
    UI.apply_remembered_ui_scale()
  end
  if OptionalFonts and OptionalFonts.apply_current_ui_font then
    OptionalFonts.apply_current_ui_font()
  end
  local open = Render.main_window()
  if not S.startup_first_frame_submitted then
    S.startup_first_frame_submitted = true
    Startup.mark("first_frame_submitted")
  end

  -- The open bool (window X button) must be checked OUTSIDE the visible block.
  if not open then S.script_open = false end

  if S.script_open then
    reaper.defer(loop)
  else
    -- Save window geometry for next launch. Skipped after Factory Reset
    -- so freshly-cleared keys don't reappear before the user can verify.
    if update._main_x and not S._suppress_geometry_save then
      Store.save_window_geometry(
        update._main_x, update._main_y, update._main_w, update._main_h)
    end
    -- Intentional close: clean up ExtState (atexit handles crashes).
    set_toolbar(false)
    -- Only clear "running" if it still belongs to this instance. During
    -- auto-restart the new instance has already claimed the lock; we
    -- don't want to wipe its claim on our way out.
    local current = reaper.GetExtState(CFG.EXT_NS, "running")
    if current:match("^([^|]+)") == S.INSTANCE_ID then
      reaper.DeleteExtState(CFG.EXT_NS, "running", false)
    end
    reaper.DeleteExtState(CFG.EXT_NS, "request_close", false)
    -- Delete any hidden temp tracks still owned by in-flight scans so the
    -- user's project doesn't end with a stray hidden track if they close
    -- mid-scan or a second instance forces this one to exit.
    local _inflight = {}
    if pref_plugins.scan  and pref_plugins.scan.track  then _inflight[#_inflight+1] = pref_plugins.scan.track  end
    if fx_cache_ui.rescan and fx_cache_ui.rescan.track then _inflight[#_inflight+1] = fx_cache_ui.rescan.track end
    if S._fx_inspect_tmp  and S._fx_inspect_tmp.tr     then _inflight[#_inflight+1] = S._fx_inspect_tmp.tr     end
    if deep_scan.tr                                    then _inflight[#_inflight+1] = deep_scan.tr             end
    for _, _tr in ipairs(_inflight) do
      if reaper.ValidatePtr2(0, _tr, "MediaTrack*") then
        pcall(reaper.DeleteTrack, _tr)
      end
    end
    -- Release scan cleanup scopes. See the matching block in atexit (above)
    -- for why refresh owners and undo owners are counted separately.
    local _refresh_owners = 0
    if pref_plugins.scan  and pref_plugins.scan.track  then _refresh_owners = _refresh_owners + 1 end
    if fx_cache_ui.rescan and fx_cache_ui.rescan.track then _refresh_owners = _refresh_owners + 1 end
    if S._fx_inspect_tmp                               then _refresh_owners = _refresh_owners + 1 end
    local _undo_owners = 0
    if pref_plugins.scan and pref_plugins.scan.undo_open then
      _undo_owners = _undo_owners + 1
      pref_plugins.scan.undo_open = false
    end
    if fx_cache_ui.rescan and fx_cache_ui.rescan.undo_open then
      _undo_owners = _undo_owners + 1
      fx_cache_ui.rescan.undo_open = false
    end
    if S._fx_inspect_tmp and S._fx_inspect_tmp.undo_open then
      _undo_owners = _undo_owners + 1
      S._fx_inspect_tmp.undo_open = false
    end
    local _refreshes = _refresh_owners
    if deep_scan._ui_refresh_released then _refreshes = _refreshes - 1 end
    if _refreshes < 0 then _refreshes = 0 end
    for _ = 1, _refreshes do pcall(reaper.PreventUIRefresh, -1) end
    for _ = 1, _undo_owners do
      pcall(reaper.Undo_EndBlock, "ReaAssist: scan (closed at exit)", 0)
    end
  end
end

function RA.pump_screen_reader_background()
  Loop.handle_close_signal()
  local now_hb = time_precise()
  if not S._last_heartbeat or now_hb - S._last_heartbeat >= 1.0 then
    S._last_heartbeat = now_hb
    reaper.SetExtState(CFG.EXT_NS, "running",
      S.INSTANCE_ID .. "|" .. tostring(now_hb), false)
    RA.write_temp_live_marker(now_hb)
  end
  Loop.pump_curl_or_retry()
  if S.kill_pending then
    Net.try_finish_kill_pending()
  end
  if Diag and Diag.uploader_enabled and Diag.tick then
    Diag.tick()
  end
  if Attach and Attach.pump_encoding and S.attachments
      and #S.attachments > 0 then
    Attach.pump_encoding()
  end
  if CTX and CTX.pref_plugins_scan_read and pref_plugins
      and pref_plugins.scan and pref_plugins.scan.active then
    CTX.pref_plugins_scan_read()
  end
  if CTX and fx_cache_ui and fx_cache_ui.rescan
      and fx_cache_ui.rescan.active then
    if RA.context_loaded and RA.context_loaded()
        and fx_cache_ui.rescan.phase == "reading" then
      CTX.fx_cache_rescan_read()
    elseif RA.context_loaded and not RA.context_loaded() then
      if fx_cache_ui.rescan.phase == "reading" then
        CTX.fx_cache_rescan_read()
      else
        fx_cache_ui.rescan.status = RA.context_unavailable_message(
          "before rescanning FX parameters")
      end
    end
  end
  if CTX and deep_scan and deep_scan.active then
    if RA.context_loaded and RA.context_loaded() then
      CTX.pump_deep_scan()
    elseif CTX.cancel_deep_scan then
      CTX.cancel_deep_scan()
    end
  end
  if Updater and update then
    Updater.sentinel_tick()
    Updater.try_silent_manifest_repair()
    Updater.try_manifest_restore()
    if update.state == "checking" then
      Updater.check_poll()
    elseif update.state == "verifying" then
      local s = update._sha_diff
      if s and s.mode == "native" then
        Updater.tick_native_sha()
      else
        Updater.tick_sha_diff()
      end
    elseif update.state == "downloading_batch" then
      Updater.batch_download_poll()
    elseif update.state == "verifying_download" then
      Updater.download_verify_tick()
    elseif update.state == "applying" then
      Updater.apply_tick()
    end
    Updater.settle_silent_manifest_failure()
    Updater.try_auto_restart()
  end
  if S.gemini_auto_retest_pending and not S.curl_pid then
    local p = PROVIDERS and PROVIDERS.active and PROVIDERS.active() or nil
    if p and p.id == "google" then
      S.gemini_auto_retest_pending = false
      Net.fire_gemini_tier_test()
    end
  end
  return S.status == "waiting" or S.curl_pid ~= nil
    or S.retry_scheduled == true
end

-- =============================================================================
-- Bootstrap: emergency recovery defer loop
-- =============================================================================
-- Runs in place of the normal loop when critical files are missing
-- (S.bootstrap_active). Uses default font and theme so it can draw
-- without touching Render.*, UI.*, TK.*, or FONT.* (any of which may
-- be nil in this mode) and drives Updater.force_reinstall to pull
-- the manifest files down. Once state reaches "available" or
-- "repair_available", Bootstrap auto-accepts without a user click.

Bootstrap = {}

function Bootstrap.t(key, values, fallback)
  if I18N and I18N.t then
    local text = I18N.t(key, values)
    if type(text) == "string" and text ~= "" and text ~= key then
      return text
    end
  end
  if type(values) == "table" and type(fallback) == "string" then
    return (fallback:gsub("{([%w_]+)}", function(name)
      local v = values[name]
      return v == nil and ("{" .. name .. "}") or tostring(v)
    end))
  end
  return fallback or key
end

-- Self-contained newline-aware TextWrapped used by Bootstrap.* render
-- functions. Bootstrap may run with Resources/UI.lua missing or
-- unloadable, in which case UI.text_multiline does not exist; this
-- helper mirrors the no-newline rule (ImGui_TextWrapped corrupts window
-- state when fed a literal \n) without depending on the UI namespace.
local function bootstrap_text_multiline(text)
  local t = tostring(text or "")
  if #t == 0 then ImGui.ImGui_TextWrapped(RA.ctx, " "); return end
  local pos = 1
  while pos <= #t do
    local nl   = t:find("\n", pos, true)
    local line = nl and t:sub(pos, nl - 1) or t:sub(pos)
    if line == "" then
      ImGui.ImGui_Spacing(RA.ctx)
    else
      ImGui.ImGui_TextWrapped(RA.ctx, line)
    end
    if not nl then break end
    pos = nl + 1
  end
end

-- Theme colors lifted from PALETTE_DARK. Bootstrap may run before COL
-- is built, so we duplicate the values rather than reference COL.
local BS_C = {
  WIN_BG     = 0x1A1A1AFF,
  ACCENT     = 0x83BCEBFF,  -- ASSIST ice-blue ("Assist" half of logo)
  ACCENT_DK  = 0x4A7DA8FF,  -- ASSIST_DK darker ice-blue ("Rea" half of logo)
  TEXT       = 0xFFFFFFFF,
  TEXT_DIM   = 0xB0BEC5FF,  -- CARD_HEAD
  TEXT_VDIM  = 0x78909CFF,  -- CARD_DESC
  ERROR      = 0xFF6060FF,
  SUCCESS    = 0x66CC66FF,
  BTN_BG     = 0x37474FFF,
  BTN_HOV    = 0x455A64FF,
  BTN_ACT    = 0x263238FF,
  PRIMARY    = 0x5D809CFF,
  PRIMARY_H  = 0x7A9BB2FF,
  PRIMARY_A  = 0x4A6A80FF,
  FRAME_BG   = 0x363636FF,
  PROG_FILL  = 0x83BCEBFF,
  BORDER     = 0x37474FFF,
}

-- Push the bootstrap window's chrome styles. Returns counts so the
-- matching pop call can balance the stack exactly.
local function bs_push_styles()
  ImGui.ImGui_PushStyleColor(RA.ctx, ImGui.ImGui_Col_WindowBg(),       BS_C.WIN_BG)
  ImGui.ImGui_PushStyleColor(RA.ctx, ImGui.ImGui_Col_TitleBg(),        BS_C.WIN_BG)
  ImGui.ImGui_PushStyleColor(RA.ctx, ImGui.ImGui_Col_TitleBgActive(),  BS_C.WIN_BG)
  ImGui.ImGui_PushStyleColor(RA.ctx, ImGui.ImGui_Col_FrameBg(),        BS_C.FRAME_BG)
  ImGui.ImGui_PushStyleColor(RA.ctx, ImGui.ImGui_Col_Button(),         BS_C.BTN_BG)
  ImGui.ImGui_PushStyleColor(RA.ctx, ImGui.ImGui_Col_ButtonHovered(),  BS_C.BTN_HOV)
  ImGui.ImGui_PushStyleColor(RA.ctx, ImGui.ImGui_Col_ButtonActive(),   BS_C.BTN_ACT)
  ImGui.ImGui_PushStyleColor(RA.ctx, ImGui.ImGui_Col_PlotHistogram(),  BS_C.PROG_FILL)
  ImGui.ImGui_PushStyleColor(RA.ctx, ImGui.ImGui_Col_Border(),         BS_C.BORDER)
  ImGui.ImGui_PushStyleVar(RA.ctx, ImGui.ImGui_StyleVar_WindowPadding(), 22, 22)
  ImGui.ImGui_PushStyleVar(RA.ctx, ImGui.ImGui_StyleVar_ItemSpacing(),    0, 10)
  ImGui.ImGui_PushStyleVar(RA.ctx, ImGui.ImGui_StyleVar_FrameRounding(),  4)
  ImGui.ImGui_PushStyleVar(RA.ctx, ImGui.ImGui_StyleVar_FramePadding(),  12, 6)
  return 9, 4  -- color count, var count
end

local function bs_pop_styles(n_color, n_var)
  ImGui.ImGui_PopStyleVar(RA.ctx, n_var)
  ImGui.ImGui_PopStyleColor(RA.ctx, n_color)
end

-- Render the ReaAssist wordmark, centered. Approximates the gradient
-- two-tone wordmark used on the TOS screen (UI.logo) but works inside
-- Bootstrap where UI.lua / RA.bold_font may not be loaded -- "Rea" in
-- the darker blue, "Assist" in the brighter ice-blue, both at the
-- default font at a larger size via PushFont(nil, size).
local function bs_logo()
  ImGui.ImGui_PushFont(RA.ctx, nil, 28)
  local rea_w = ImGui.ImGui_CalcTextSize(RA.ctx, "Rea")
  local ass_w = ImGui.ImGui_CalcTextSize(RA.ctx, "Assist")
  local total_w = rea_w + ass_w
  local win_w = ImGui.ImGui_GetWindowWidth(RA.ctx)
  ImGui.ImGui_SetCursorPosX(RA.ctx,
    math.max(0, math.floor((win_w - total_w) / 2)))
  ImGui.ImGui_TextColored(RA.ctx, BS_C.ACCENT_DK, "Rea")
  ImGui.ImGui_SameLine(RA.ctx, 0, 0)
  ImGui.ImGui_TextColored(RA.ctx, BS_C.ACCENT,    "Assist")
  ImGui.ImGui_PopFont(RA.ctx)
  ImGui.ImGui_Spacing(RA.ctx)
end

-- Centered text helper -- measures the string at the (optionally scaled)
-- font, then positions the cursor so the text is horizontally centered
-- in the window before drawing it. `size` is in pixels; nil means use
-- the current font unchanged.
local function bs_text_center(s, color, size)
  if size then ImGui.ImGui_PushFont(RA.ctx, nil, size) end
  local tw = ImGui.ImGui_CalcTextSize(RA.ctx, s)
  local win_w = ImGui.ImGui_GetWindowWidth(RA.ctx)
  ImGui.ImGui_SetCursorPosX(RA.ctx,
    math.max(0, math.floor((win_w - tw) / 2)))
  if color then
    ImGui.ImGui_TextColored(RA.ctx, color, s)
  else
    ImGui.ImGui_Text(RA.ctx, s)
  end
  if size then ImGui.ImGui_PopFont(RA.ctx) end
end

-- Render a title line with bigger font + accent color (left-aligned).
-- Kept for backward compatibility; new code prefers bs_text_center.
local function bs_title_text(s, color)
  ImGui.ImGui_PushFont(RA.ctx, nil, 20)
  ImGui.ImGui_TextColored(RA.ctx, color or BS_C.ACCENT, s)
  ImGui.ImGui_PopFont(RA.ctx)
end

-- Render the primary action button with accent colors.
local function bs_primary_button(label, w, h)
  ImGui.ImGui_PushStyleColor(RA.ctx, ImGui.ImGui_Col_Button(),         BS_C.PRIMARY)
  ImGui.ImGui_PushStyleColor(RA.ctx, ImGui.ImGui_Col_ButtonHovered(),  BS_C.PRIMARY_H)
  ImGui.ImGui_PushStyleColor(RA.ctx, ImGui.ImGui_Col_ButtonActive(),   BS_C.PRIMARY_A)
  local clicked = ImGui.ImGui_Button(RA.ctx, label, w, h)
  ImGui.ImGui_PopStyleColor(RA.ctx, 3)
  return clicked
end

-- Position the cursor for a centered group of buttons. Use total
-- combined width and call this before placing the first button.
local function bs_center_buttons(total_w)
  local win_w = ImGui.ImGui_GetWindowWidth(RA.ctx)
  ImGui.ImGui_SetCursorPosX(RA.ctx,
    math.max(0, math.floor((win_w - total_w) / 2)))
end

-- Discrete-progress cell row used by both the install minimal popup and
-- the styled repair view. One cell per file, fills ice-blue as each
-- file completes. Caller passes total and done counts; if total is 0
-- the row reserves vertical space but draws nothing (so layout above
-- stays anchored across phase changes).
local function bs_progress_cells(total, done)
  local cell_h  = 10
  local gap     = 3
  local cx, cy  = ImGui.ImGui_GetCursorScreenPos(RA.ctx)
  local avail_w = ImGui.ImGui_GetContentRegionAvail(RA.ctx)
  if total > 0 then
    local cell_w  = math.max(4,
      math.floor((avail_w - (total - 1) * gap) / total))
    local total_w = total * cell_w + (total - 1) * gap
    local start_x = cx + math.floor((avail_w - total_w) / 2)
    local dl      = ImGui.ImGui_GetWindowDrawList(RA.ctx)
    for i = 1, total do
      local x = start_x + (i - 1) * (cell_w + gap)
      local color = (i <= done) and BS_C.ACCENT or BS_C.FRAME_BG
      ImGui.ImGui_DrawList_AddRectFilled(dl, x, cy,
                                         x + cell_w, cy + cell_h,
                                         color, 2)
    end
  end
  ImGui.ImGui_Dummy(RA.ctx, avail_w, cell_h)
end

-- Minimal popup for install-mode success path. The auto-restart in
-- Bootstrap.loop will relaunch ReaAssist a moment after state="done",
-- at which point the real app window opens and this popup vanishes.
-- Small ReaAssist wordmark + "Installing..." status + animated band.
function Bootstrap.render_minimal()
  -- Small wordmark for color / polish. Same two-tone treatment as the
  -- styled installer's bigger version, just smaller.
  ImGui.ImGui_PushFont(RA.ctx, nil, 22)
  local rea_w = ImGui.ImGui_CalcTextSize(RA.ctx, "Rea")
  local ass_w = ImGui.ImGui_CalcTextSize(RA.ctx, "Assist")
  local total_w = rea_w + ass_w
  local win_w = ImGui.ImGui_GetWindowWidth(RA.ctx)
  ImGui.ImGui_SetCursorPosX(RA.ctx,
    math.max(0, math.floor((win_w - total_w) / 2)))
  ImGui.ImGui_TextColored(RA.ctx, BS_C.ACCENT_DK, "Rea")
  ImGui.ImGui_SameLine(RA.ctx, 0, 0)
  ImGui.ImGui_TextColored(RA.ctx, BS_C.ACCENT,    "Assist")
  ImGui.ImGui_PopFont(RA.ctx)
  ImGui.ImGui_Spacing(RA.ctx)

  -- Discrete progress: one cell per file in the download queue. Each
  -- cell turns from dim track-color to ice-blue accent as that file
  -- completes. Updates are pure discrete events tied to real install
  -- progress (not animation), so frame-rate stutter is invisible -- a
  -- skipped repaint just means the next cell-fill happens one frame
  -- later, not jumpily. During pre-download phases (checking /
  -- verifying) the queue isn't built yet; show status text only.
  local status_text  = Bootstrap.t("bootstrap.status.installing", nil,
    "Installing...")
  local cells_total  = 0
  local cells_done   = 0

  if update.state == "checking" then
    status_text = Bootstrap.t("bootstrap.status.checking_updates", nil,
      "Checking for updates...")
  elseif update.state == "verifying" then
    status_text = Bootstrap.t("bootstrap.status.verifying_files", nil,
      "Verifying files...")
  elseif update.state == "downloading_batch" or update.state == "applying"
      or update.state == "verifying_download" then
    cells_total = #(update.download_queue or {})
    -- download_idx is the 1-based progress pointer (staged-file count + 1
    -- during the batch download, apply index while applying). Subtract
    -- one so the in-flight file's cell stays empty until it lands.
    cells_done  = math.max(0, math.min((update.download_idx or 0) - 1, cells_total))
    if update.state == "downloading_batch" then
      status_text = Bootstrap.t("bootstrap.status.downloading", nil,
        "Downloading...")
    else
      -- Staged verify + apply both read as "verifying" here: they are
      -- the short local half of the install, and the cell row already
      -- carries the real progress signal.
      status_text = Bootstrap.t("bootstrap.status.verifying_files", nil,
        "Verifying files...")
    end
  elseif update.state == "done" then
    cells_total = #(update.download_queue or {})
    cells_done  = cells_total
    status_text = Bootstrap.t("bootstrap.status.almost_done", nil,
      "Almost done...")
  end

  bs_text_center(status_text, BS_C.TEXT, 17)
  ImGui.ImGui_Spacing(RA.ctx)
  bs_progress_cells(cells_total, cells_done)
end

function Bootstrap.render_prompt()
  -- The install-mode auto-fire moved to Bootstrap.loop so it triggers
  -- regardless of which view (minimal or styled) is being rendered.
  -- This function only handles the repair-mode prompt now; install mode
  -- shouldn't ever reach here in normal flow (it routes to render_minimal
  -- for success path, render_failed for errors).
  if S.bootstrap_install_mode then
    -- Defensive fallback if dispatch routing changes -- show the
    -- minimal view rather than nothing.
    return Bootstrap.render_minimal()
  end

  -- The quarantine gate's own prompt (B2.2d requirement 4). There is no
  -- broken-file list to show here and that is the whole point: an update
  -- record touched this install, nothing could read it afterwards, and so
  -- nobody knows which files are the right ones. The offer is therefore the
  -- full check rather than a list of repairs, and the copy says what will
  -- happen and what it is for.
  if S.quarantine_gate then
    bs_text_center(Bootstrap.t("bootstrap.quarantine.title", nil,
      "Interrupted Update Found"), BS_C.ACCENT, 20)
    ImGui.ImGui_Spacing(RA.ctx)
    bs_text_center(Bootstrap.t("bootstrap.quarantine.body", nil,
      "A pending update record could not be read, so ReaAssist has not "
      .. "started a normal session."), BS_C.TEXT_VDIM)
    bs_text_center(Bootstrap.t("bootstrap.quarantine.kept", nil,
      "The record was kept for support at:"), BS_C.TEXT_VDIM)
    bootstrap_text_multiline(tostring(S.quarantine_gate))
    ImGui.ImGui_Spacing(RA.ctx)
    if CFG.UPDATE_BASE_URL == "" then
      bs_text_center(Bootstrap.t("bootstrap.recovery_unavailable", nil,
        "Automatic recovery is not available (update URL not configured)."),
        BS_C.ERROR)
      bs_text_center(Bootstrap.t("bootstrap.reinstall_manually", nil,
        "Please reinstall ReaAssist manually."), BS_C.TEXT)
      ImGui.ImGui_Spacing(RA.ctx)
      bs_center_buttons(100)
      if ImGui.ImGui_Button(RA.ctx,
          Bootstrap.t("common.close", nil, "Close"), 100, 30) then
        S.script_open = false
      end
      return
    end
    if update.last_error then
      bs_text_center(Bootstrap.t("bootstrap.previous_failed", {
          step = tostring(update.last_step or "unknown"),
        }, "Previous attempt failed ({step}):"), BS_C.ERROR)
      bootstrap_text_multiline(update.last_error)
      ImGui.ImGui_Spacing(RA.ctx)
    end
    bs_text_center(Bootstrap.t("bootstrap.quarantine.prompt", nil,
      "Check every installed file against the current release and repair "
      .. "anything that does not match?"), BS_C.TEXT)
    ImGui.ImGui_Spacing(RA.ctx)
    bs_center_buttons(110 + 12 + 80)
    if bs_primary_button(Bootstrap.t("bootstrap.check_and_repair", nil,
        "Check and Repair"), 110, 32) then
      update.last_error = nil
      update.last_step  = nil
      Updater.force_reinstall()
    end
    ImGui.ImGui_SameLine(RA.ctx, 0, 12)
    if ImGui.ImGui_Button(RA.ctx,
        Bootstrap.t("bootstrap.quit", nil, "Quit"), 80, 32) then
      S.script_open = false
    end
    return
  end

  -- Repair mode: surface the affected-file list + Repair / Quit buttons.
  -- "Some files need repair" covers all detected issues: missing on disk,
  -- present-but-unreadable (font load errors), and SHA mismatches that
  -- the regular update flow routes here as repair_available.
  bs_text_center(Bootstrap.t("bootstrap.prompt.title", nil,
    "Some Files Need Repair"), BS_C.ACCENT, 20)
  ImGui.ImGui_Spacing(RA.ctx)
  do
    local count = #S.bootstrap_missing
    local key = count == 1 and "bootstrap.prompt.files.one"
      or "bootstrap.prompt.files.many"
    local fallback = count == 1
      and "ReaAssist found 1 critical file missing, modified, or unreadable."
      or "ReaAssist found {count} critical files missing, modified, or unreadable."
    bs_text_center(Bootstrap.t(key, { count = count }, fallback),
    BS_C.TEXT_VDIM)
  end
  ImGui.ImGui_Spacing(RA.ctx)

  -- File list. Two-column bulleted layout to halve vertical space.
  -- Drop the "Resources/" prefix on Resources/ entries (header context
  -- already implies it); other entries (e.g. ReaAssist.lua, README.md)
  -- render unchanged. Bullet char is ASCII; see comment by the items[]
  -- construction below for why.
  local n = #S.bootstrap_missing
  local show_n = math.min(n, 10)
  local items = {}
  for i = 1, show_n do
    local p = S.bootstrap_missing[i]:gsub("^Resources/", "")
    -- ASCII bullet (rather than U+2022) so it renders cleanly even on
    -- Mac/Linux where ImGui's default Proggy font is ASCII-only and
    -- would otherwise show a missing-glyph box.
    items[#items + 1] = "*  " .. p
  end
  local more_line = (n > show_n)
    and Bootstrap.t("bootstrap.more", { count = n - show_n },
      "+ {count} more") or nil

  ImGui.ImGui_PushFont(RA.ctx, nil, 12)
  ImGui.ImGui_PushStyleVar(RA.ctx, ImGui.ImGui_StyleVar_ItemSpacing(), 0, 3)

  local rows = math.ceil(#items / 2)
  -- Measure widest entry in each column independently for clean alignment.
  local col_l_w, col_r_w = 0, 0
  for i = 1, rows do
    local w = ImGui.ImGui_CalcTextSize(RA.ctx, items[i])
    if w > col_l_w then col_l_w = w end
  end
  for i = rows + 1, #items do
    local w = ImGui.ImGui_CalcTextSize(RA.ctx, items[i])
    if w > col_r_w then col_r_w = w end
  end
  local col_gap = 30
  local block_w = col_l_w + (col_r_w > 0 and (col_gap + col_r_w) or 0)
  local win_w   = ImGui.ImGui_GetWindowWidth(RA.ctx)
  local block_x = math.max(0, math.floor((win_w - block_w) / 2))
  local right_x = block_x + col_l_w + col_gap

  for r = 1, rows do
    ImGui.ImGui_SetCursorPosX(RA.ctx, block_x)
    ImGui.ImGui_TextColored(RA.ctx, BS_C.TEXT_DIM, items[r])
    local right = items[rows + r]
    if right then
      ImGui.ImGui_SameLine(RA.ctx, right_x, 0)
      ImGui.ImGui_TextColored(RA.ctx, BS_C.TEXT_DIM, right)
    end
  end
  if more_line then
    -- Centered "+ N more" on its own line, in the dimmer color.
    local mw = ImGui.ImGui_CalcTextSize(RA.ctx, more_line)
    ImGui.ImGui_SetCursorPosX(RA.ctx,
      math.max(0, math.floor((win_w - mw) / 2)))
    ImGui.ImGui_TextColored(RA.ctx, BS_C.TEXT_VDIM, more_line)
  end

  ImGui.ImGui_PopStyleVar(RA.ctx, 1)
  ImGui.ImGui_PopFont(RA.ctx)
  -- Extra 15px breathing room between the file list and the action prompt.
  ImGui.ImGui_Dummy(RA.ctx, 0, 15)

  if CFG.UPDATE_BASE_URL == "" then
    bs_text_center(Bootstrap.t("bootstrap.recovery_unavailable", nil,
                     "Automatic recovery is not available (update URL not configured)."),
                   BS_C.ERROR)
    bs_text_center(Bootstrap.t("bootstrap.reinstall_manually", nil,
      "Please reinstall ReaAssist manually."), BS_C.TEXT)
    ImGui.ImGui_Spacing(RA.ctx)
    bs_center_buttons(100)
    if ImGui.ImGui_Button(RA.ctx,
        Bootstrap.t("common.close", nil, "Close"), 100, 30) then
      S.script_open = false
    end
    return
  end

  if update.last_error then
    bs_text_center(Bootstrap.t("bootstrap.previous_failed", {
                                   step = tostring(update.last_step or "unknown"),
                                 },
                                 "Previous attempt failed ({step}):"),
                   BS_C.ERROR)
    bootstrap_text_multiline(update.last_error)
    ImGui.ImGui_Spacing(RA.ctx)
  end

  bs_text_center(Bootstrap.t("bootstrap.repair_prompt", nil,
                   "Repair these and any other modified files from the current release?"),
                 BS_C.TEXT)
  ImGui.ImGui_Spacing(RA.ctx)

  bs_center_buttons(110 + 12 + 80)
  if bs_primary_button(Bootstrap.t("bootstrap.repair", nil, "Repair"), 110, 32) then
    update.last_error = nil
    update.last_step  = nil
    -- Bootstrap fast-path: we already have S.bootstrap_missing from the
    -- critical-files check at startup, so check_poll can skip the full
    -- per-file SHA verify (which re-hashes ~5-7s of fonts and Lua
    -- files for nothing -- those files are confirmed missing/broken
    -- already). Only set in repair mode; install mode needs the full
    -- diff because S.bootstrap_missing only covers critical files.
    -- Never under a standing quarantine gate: the fast path queues only the
    -- files the critical-file probe already found broken, and the gate is
    -- there because nobody can say which files are right. That repair has to
    -- be the FULL manifest verification (B2.2d requirement 4).
    if not S.bootstrap_install_mode and not S.quarantine_gate then
      update._bootstrap_repair = true
    end
    Updater.force_reinstall()
  end
  ImGui.ImGui_SameLine(RA.ctx, 0, 12)
  if ImGui.ImGui_Button(RA.ctx,
      Bootstrap.t("bootstrap.quit", nil, "Quit"), 80, 32) then
    S.script_open = false
  end
end

function Bootstrap.render_progress()
  local title = S.bootstrap_install_mode
    and Bootstrap.t("bootstrap.title.setup", nil, "Setting up ReaAssist")
    or Bootstrap.t("bootstrap.title.repairing", nil, "Repairing Files")
  bs_text_center(title, BS_C.ACCENT, 20)
  ImGui.ImGui_Spacing(RA.ctx)

  bs_text_center(Bootstrap.t("bootstrap.status.downloading", nil,
    "Downloading..."), BS_C.TEXT, 17)
  ImGui.ImGui_Spacing(RA.ctx)

  local idx   = update.download_idx or 0
  local total = #(update.download_queue or {})
  -- idx is the in-flight file's index (1-based); subtract one so the
  -- current file's cell only fills once it actually lands on disk.
  bs_progress_cells(total, math.max(0, math.min(idx - 1, total)))
end

function Bootstrap.render_checking()
  local title = S.bootstrap_install_mode
    and Bootstrap.t("bootstrap.title.setup", nil, "Setting up ReaAssist")
    or Bootstrap.t("bootstrap.title.repairing", nil, "Repairing Files")
  bs_text_center(title, BS_C.ACCENT, 20)
  ImGui.ImGui_Spacing(RA.ctx)

  local status_text = Bootstrap.t("bootstrap.status.checking_updates", nil,
    "Checking for updates...")
  if update.state == "verifying" or update.state == "verifying_download" then
    status_text = Bootstrap.t("bootstrap.status.verifying_files", nil,
      "Verifying files...")
  end
  bs_text_center(status_text, BS_C.TEXT, 17)
  ImGui.ImGui_Spacing(RA.ctx)

  -- Reserve cell-row space even though we don't have a queue yet, so
  -- the status text above stays anchored when the dispatcher transitions
  -- from "checking" -> "downloading" and the cells become populated.
  bs_progress_cells(0, 0)
end

function Bootstrap.render_done()
  local title = S.bootstrap_install_mode
    and Bootstrap.t("bootstrap.title.setup_complete", nil, "Setup Complete")
    or Bootstrap.t("bootstrap.title.repair_complete", nil, "Repair Complete")
  bs_text_center(title, BS_C.SUCCESS, 20)
  ImGui.ImGui_Spacing(RA.ctx)

  -- A launcher the app went ahead without (B2.3, widened in B2.3b to cover a
  -- swap the ownership fence declined). Shown in BOTH endings, above whatever
  -- else this view says, because it is the only part of the result the user has
  -- to act on: one of the two actions that start ReaAssist is missing, or is
  -- still on the previous release, and this body is not allowed to put it
  -- right.
  if S.launcher_notice then
    bootstrap_text_multiline(tostring(S.launcher_notice))
    ImGui.ImGui_Spacing(RA.ctx)
  end

  local n = #(update.applied_files or {})
  if S.quarantine_verified_clean then
    -- The gate's repair found nothing to repair. That is a pass, not a
    -- no-op: every file matched the current release, which is the
    -- verification the gate was waiting for, and the record has been
    -- cleared.
    bs_text_center(Bootstrap.t("bootstrap.quarantine.verified", nil,
      "Every installed file matched the current release."), BS_C.TEXT_DIM)
    bs_text_center(Bootstrap.t("bootstrap.quarantine.cleared", nil,
      "The interrupted update record has been cleared."), BS_C.TEXT_DIM)
    ImGui.ImGui_Spacing(RA.ctx)
    bs_text_center(Bootstrap.t("bootstrap.done.reopen_repair", nil,
      "Close and reopen ReaAssist to finish the repair."), BS_C.TEXT_VDIM)
    ImGui.ImGui_Spacing(RA.ctx)
    bs_center_buttons(100)
    if bs_primary_button(Bootstrap.t("common.ok", nil, "OK"), 100, 32) then
      S.script_open = false
    end
    return
  end
  if n > 0 then
    local mode = S.bootstrap_install_mode and "installed" or "restored"
    local key = "bootstrap.done." .. mode .. "." .. (n == 1 and "one" or "many")
    local fallback = S.bootstrap_install_mode
      and (n == 1
        and "Installed 1 file successfully."
        or "Installed {count} files successfully.")
      or (n == 1
        and "Restored 1 file successfully."
        or "Restored {count} files successfully.")
    bs_text_center(Bootstrap.t(key, { count = n }, fallback), BS_C.TEXT_DIM)
  end

  local auto_restart_pending = update.restart_after and not update.restart_fired
  if auto_restart_pending then
    bs_text_center(Bootstrap.t("bootstrap.status.restarting", nil,
      "Restarting ReaAssist..."), BS_C.TEXT_VDIM)
  else
    bs_text_center(
      S.bootstrap_install_mode
        and Bootstrap.t("bootstrap.done.reopen_setup", nil,
          "Close and reopen ReaAssist to finish setup.")
        or  Bootstrap.t("bootstrap.done.reopen_repair", nil,
          "Close and reopen ReaAssist to finish the repair."),
      BS_C.TEXT_VDIM)
  end
  ImGui.ImGui_Spacing(RA.ctx)

  bs_center_buttons(100)
  if bs_primary_button(Bootstrap.t("common.ok", nil, "OK"), 100, 32) then
    S.script_open = false
  end
end

function Bootstrap.render_failed()
  local title = S.bootstrap_install_mode
    and Bootstrap.t("bootstrap.title.setup_failed", nil, "Setup Failed")
    or Bootstrap.t("bootstrap.title.repair_failed", nil, "Repair Failed")
  -- Nothing failed to repair when the gate's check could not finish: no apply
  -- was started and no installed file was touched. Say what happened instead
  -- of calling it a failed repair (Codex round 20, blocker 1). The Retry
  -- button below is the same full pass, which is what this surface is for.
  if update.last_step == "quarantine_incomplete" then
    title = Bootstrap.t("bootstrap.title.check_incomplete", nil,
      "Check Incomplete")
  end
  bs_text_center(title, BS_C.ERROR, 20)
  ImGui.ImGui_Spacing(RA.ctx)

  if update.last_error then
    bs_text_center(Bootstrap.t("bootstrap.step", {
                                   step = tostring(update.last_step or "unknown"),
                                 },
                                 "Step: {step}"),
                   BS_C.TEXT_DIM)
    ImGui.ImGui_Spacing(RA.ctx)
    -- Centered, compact multi-line: skip empty lines (which would
    -- otherwise add Spacing and waste vertical room) and center each
    -- non-empty line individually instead of using TextWrapped's
    -- left-aligned default.
    for line in tostring(update.last_error):gmatch("[^\n]+") do
      bs_text_center(line, BS_C.TEXT)
    end
  end
  ImGui.ImGui_Spacing(RA.ctx)
  bs_text_center(Bootstrap.t("bootstrap.problem_persists", nil,
                   "If the problem persists, reinstall ReaAssist manually."),
                 BS_C.TEXT_VDIM)
  ImGui.ImGui_Spacing(RA.ctx)

  bs_center_buttons(100 + 12 + 80)
  if bs_primary_button(Bootstrap.t("common.retry", nil, "Retry"), 100, 32) then
    update.last_error = nil
    update.last_step  = nil
    -- Allow install-mode auto-trigger to re-fire on the next prompt pass.
    S.bootstrap_install_fired = false
    -- Repair-mode Retry takes the same fast-path as the Repair button
    -- above (skip the full SHA verify; we already know the broken file
    -- list). Install mode keeps the full diff because S.bootstrap_missing
    -- only covers critical files.
    -- Never under a standing quarantine gate: the fast path queues only the
    -- files the critical-file probe already found broken, and the gate is
    -- there because nobody can say which files are right. That repair has to
    -- be the FULL manifest verification (B2.2d requirement 4).
    if not S.bootstrap_install_mode and not S.quarantine_gate then
      update._bootstrap_repair = true
    end
    Updater.force_reinstall()
  end
  ImGui.ImGui_SameLine(RA.ctx, 0, 12)
  if ImGui.ImGui_Button(RA.ctx,
      Bootstrap.t("common.close", nil, "Close"), 80, 32) then
    S.script_open = false
  end
end

function Bootstrap.loop()
  -- In-frame ReaImGui context check, one-shot. The init-time preflight
  -- can pass on macOS Tahoe even when the freshly-installed dylib isn't
  -- fully loaded; the failure surfaces on the first in-frame ImGui call
  -- below (SetNextWindowSize). Catching it here lets the user see the
  -- friendly "please restart REAPER" dialog instead of a raw Lua error.
  if not S.imgui_in_frame_validated then
    if not RA.imgui_in_frame_context_ok() then
      S.script_open = false
      return
    end
    S.imgui_in_frame_validated = true
  end

  -- Pump the Update state machine so check_poll / the batch pipeline
  -- all advance during bootstrap recovery. The normal main loop does this
  -- in its dev-signal handler; we do it inline here because the normal
  -- loop never runs in bootstrap mode.
  if update.state == "checking"      then Updater.check_poll()       end
  if update.state == "verifying" then
    local s = update._sha_diff
    if s and s.mode == "native" then Updater.tick_native_sha()
    else                             Updater.tick_sha_diff()
    end
  end
  if update.state == "downloading_batch"  then Updater.batch_download_poll()  end
  if update.state == "verifying_download" then Updater.download_verify_tick() end
  if update.state == "applying"           then Updater.apply_tick()           end
  -- Auto-accept: in recovery we do not show an "Update Now" confirm step.
  if update.state == "available" or update.state == "repair_available" then
    Updater.download_start()
  end
  Updater.try_auto_restart()

  -- Install-mode auto-fire: kick off Updater.force_reinstall on the
  -- first tick when the state machine hasn't started yet. Lives here
  -- (rather than inside a render function) so it triggers whether we
  -- end up rendering the minimal popup OR the full styled view on a
  -- subsequent failure.
  if S.bootstrap_install_mode and not S.bootstrap_install_fired
     and (not update.state or update.state == "idle") then
    S.bootstrap_install_fired = true
    update.last_error = nil
    update.last_step  = nil
    Updater.force_reinstall()
  end

  -- View selection:
  --   * install-mode + non-failed state + no error -> minimal popup
  --   * install-mode + failed/error                -> full styled view
  --   * repair-mode (any state)                    -> full styled view
  -- Note we also check update.last_error: check_poll's "could not reach
  -- update server" branch sets last_error and reverts state to "idle"
  -- (rather than "failed") -- without checking last_error here, a network
  -- failure would silently leave the minimal popup stuck on "Installing...".
  local use_minimal = S.bootstrap_install_mode
                      and update.state ~= "failed"
                      and not update.last_error
                      and not (update.state == "done"
                        and not update.restart_after)

  -- Center on the active monitor, but cache the screen bounds on the
  -- FIRST frame only so the popup doesn't follow the mouse around if
  -- the user moves it to another monitor mid-install. We re-center
  -- within the cached screen each frame (so a minimal -> styled view
  -- size change still recenters), but we never re-read mouse position.
  if S.bootstrap_screen_bounds == nil then
    local mx, my = reaper.GetMousePosition()
    local x1, y1, x2, y2 = RA.monitor_work_rect_native(
      mx, my, mx + 1, my + 1)
    S.bootstrap_screen_bounds = x1 and {x1, y1, x2, y2} or false
  end
  local W = use_minimal and 380 or 580
  local H = use_minimal and 175 or 410
  -- Cond_Always so the size + position track view-mode changes (minimal
  -- -> styled on failure). Position uses cached screen bounds so it
  -- doesn't follow the mouse cursor across monitors.
  ImGui.ImGui_SetNextWindowSize(RA.ctx, W, H, ImGui.ImGui_Cond_Always())
  if type(S.bootstrap_screen_bounds) == "table" then
    local sx1, sy1, sx2, sy2 = table.unpack(S.bootstrap_screen_bounds)
    local px = sx1 + math.floor((sx2 - sx1 - W) / 2)
    local py = sy1 + math.floor((sy2 - sy1 - H) / 2)
    ImGui.ImGui_SetNextWindowPos(RA.ctx, px, py, ImGui.ImGui_Cond_Always())
  end
  local n_color, n_var = bs_push_styles()
  local flags = ImGui.ImGui_WindowFlags_NoCollapse()
              + ImGui.ImGui_WindowFlags_NoDocking()
              + ImGui.ImGui_WindowFlags_NoResize()
  -- Minimal popup hides the title bar entirely (no title, no X) -- the
  -- install runs autonomously in 5-15s, no user action expected. The
  -- styled view keeps the title bar so the user can drag/close.
  if use_minimal then
    flags = flags + ImGui.ImGui_WindowFlags_NoTitleBar()
                  + ImGui.ImGui_WindowFlags_NoMove()
  end
  local title = S.bootstrap_install_mode
    and Bootstrap.t("bootstrap.window.installer", nil, "ReaAssist Installer")
    or Bootstrap.t("bootstrap.window.recovery", nil, "ReaAssist Recovery")
  local visible, open = ImGui.ImGui_Begin(RA.ctx, title, true, flags)
  if visible then
    if use_minimal then
      Bootstrap.render_minimal()
    else
      bs_logo()  -- brand wordmark only on the styled view
      -- Route to failed view when EITHER state=failed OR last_error is
      -- set. The latter catches the "manifest_fetch could not reach
      -- update server" case where check_poll sets last_error but
      -- transitions state back to "idle" rather than "failed".
      if update.state == "failed" or update.last_error then
        Bootstrap.render_failed()
      elseif update.state == "downloading_batch"
          or update.state == "applying" then
        Bootstrap.render_progress()
      elseif update.state == "checking" or update.state == "verifying"
          or update.state == "verifying_download" then
        Bootstrap.render_checking()
      elseif update.state == "done" then
        Bootstrap.render_done()
      else
        Bootstrap.render_prompt()
      end
    end
  end
  ImGui.ImGui_End(RA.ctx)
  bs_pop_styles(n_color, n_var)

  if not open then S.script_open = false end
  if S.script_open then reaper.defer(Bootstrap.loop) end
end

function Bootstrap.screen_reader_loop()
  if not S.bootstrap_install_fired then
    S.bootstrap_install_fired = true
    if S.bootstrap_install_mode == nil then
      S.bootstrap_install_mode = not Store.first_launch_complete()
    end
    update.last_error = nil
    update.last_step = nil
    -- Never under a standing quarantine gate: the fast path queues only the
    -- files the critical-file probe already found broken, and the gate is
    -- there because nobody can say which files are right. That repair has to
    -- be the FULL manifest verification (B2.2d requirement 4).
    if not S.bootstrap_install_mode and not S.quarantine_gate then
      update._bootstrap_repair = true
    end
    if not Updater.force_reinstall() then
      update.state = "failed"
      update.last_error = "Could not start the ReaAssist file repair."
    end
  end

  if update.state == "checking" then Updater.check_poll() end
  if update.state == "verifying" then
    local s = update._sha_diff
    if s and s.mode == "native" then Updater.tick_native_sha()
    else Updater.tick_sha_diff() end
  end
  if update.state == "downloading_batch" then Updater.batch_download_poll() end
  if update.state == "verifying_download" then Updater.download_verify_tick() end
  if update.state == "applying" then Updater.apply_tick() end
  if update.state == "available" or update.state == "repair_available" then
    Updater.download_start()
  end
  Updater.try_auto_restart()

  do
    local key, msg
    if update.state == "checking" or update.state == "verifying"
        or update.state == "verifying_download" then
      key = update.state
      msg = "Checking ReaAssist files for Screen Reader Mode."
    elseif update.state == "downloading_batch" then
      key = "downloading"
      msg = "Downloading ReaAssist files for Screen Reader Mode."
    elseif update.state == "applying" then
      key = "applying"
      msg = "Applying ReaAssist files for Screen Reader Mode."
    elseif update.state == "done" and update.restart_after then
      key = "restart"
      msg = "ReaAssist files are ready. Restarting Screen Reader Mode."
    end
    if msg and key ~= S._screen_reader_bootstrap_progress_key
        and reaper.osara_outputMessage then
      S._screen_reader_bootstrap_progress_key = key
      pcall(reaper.osara_outputMessage, msg)
    end
  end

  if update.state == "failed" or update.last_error then
    local msg = "ReaAssist could not repair the files needed for Screen Reader Mode.\n\n"
      .. tostring(update.last_error or "Unknown repair error.")
    -- The gate's check could not finish, which is not a failed repair: nothing
    -- was attempted and nothing was changed. The message already says which
    -- file and why, so announce it as it is and name the way back in
    -- (Codex round 20, blocker 1).
    if update.last_step == "quarantine_incomplete"
        or update.last_step == "quarantine_launcher" then
      -- Neither of these is a failed repair. The check could not finish, or
      -- it finished and one of the two actions is still not there; the
      -- message already says which file and why, so announce it as it is and
      -- name the way back (Codex round 20, blocker 1 and the launcher
      -- serviceability gate).
      msg = tostring(update.last_error or "")
        .. "\n\nRun ReaAssist Screen Reader Mode again to check once more."
    end
    if reaper.osara_outputMessage then
      pcall(reaper.osara_outputMessage, msg)
    else
      reaper.ShowMessageBox(msg, "ReaAssist Screen Reader Mode", 0)
    end
    S.script_open = false
    return
  end

  if update.state == "done" and not update.restart_after then
    local msg =
      "ReaAssist files were repaired. Close and reopen REAPER, then run ReaAssist again."
    if S.quarantine_verified_clean then
      -- The gate's full check passed with nothing to change. Say that,
      -- rather than claiming a repair that did not happen.
      msg = "Every ReaAssist file matched the current release, and the "
        .. "interrupted update record has been cleared. Close and reopen "
        .. "REAPER, then run ReaAssist again."
    end
    -- The launcher the clear went ahead without, announced ahead of the
    -- close-and-reopen instruction, because reopening is exactly what will not
    -- work until it is back (B2.3).
    if S.launcher_notice then
      msg = tostring(S.launcher_notice) .. "\n\n" .. msg
    end
    if reaper.osara_outputMessage then
      pcall(reaper.osara_outputMessage, msg)
    else
      reaper.ShowMessageBox(msg, "ReaAssist Screen Reader Mode", 0)
    end
    S.script_open = false
    return
  end

  if update.state == "idle" and S.bootstrap_install_fired then
    local msg =
      "ReaAssist Screen Reader Mode did not find any files to repair. " ..
      "Close and reopen REAPER, then run ReaAssist again."
    if reaper.osara_outputMessage then
      pcall(reaper.osara_outputMessage, msg)
    else
      reaper.ShowMessageBox(msg, "ReaAssist Screen Reader Mode", 0)
    end
    S.script_open = false
    return
  end

  if S.script_open then reaper.defer(Bootstrap.screen_reader_loop) end
end

-- =============================================================================
-- Kick off
-- =============================================================================
-- Normal path runs full startup + registers loop(); recovery path
-- (S.bootstrap_active) registers Bootstrap.loop instead.
if not S.bootstrap_active then
  -- Defer system prompt load to here so a missing/corrupt stock prompt
  -- can route into bootstrap recovery instead of returning from the main
  -- chunk before recovery has a chance to render. A custom-override
  -- failure cannot be repaired (we don't ship the custom file); in that
  -- case load_system_prompt shows a message and we exit cleanly.
  Startup.mark("system_prompt_load_start")
  if not load_system_prompt() and not S.bootstrap_active then
    return
  end
  Startup.mark("system_prompt_load_done")
end
if S.bootstrap_active then
  -- Bootstrap skips chat/network/scan init - none of it is safe before
  -- the missing files are recovered.
  if S.screen_reader_startup_intent then
    Bootstrap.screen_reader_loop()
  else
    if not RA.init_imgui_runtime() then return end
    Bootstrap.loop()
  end
else
  -- Clear any stale response file from a previous run, then start the defer loop.
  Code.safe_write(tmp.out, "")
  -- Plug-in pack warm-up starts from Loop.run_post_paint_startup after the
  -- first frame. Publishing the verified owner already defers
  -- Code.ensure_preferred_from_chains, so no plug-in work belongs here.
  -- Restore any persisted Gemini explicit cache from a previous session. No-op
  -- if no cache was persisted, expired, or already nil; if valid, the next
  -- send to Gemini will skip the cache-create round trip.
  local ok_gcr, gcr_err = pcall(Net.gemini_cache_restore)
  if not ok_gcr then
    Log.line("GEMINI", "cache_restore (startup) failed: " .. tostring(gcr_err))
  end
  -- Do NOT fire the update check here. Updater.fire_get launches curl
  -- via PowerShell, and PowerShell's .NET cold start blocks the main
  -- thread for ~1-3s the first time it runs in a REAPER session. From
  -- startup that would paint a white window before the first ImGui
  -- frame renders. Instead loop() piggybacks the check on the first
  -- chat-response completion (see `update._session_check_fired`), by
  -- which point PowerShell is already warm from the chat's own curl
  -- launch and the check's ExecProcess cost is ~200ms (imperceptible).
  -- Users who never send a chat can trigger the check via Settings >
  -- Check for Updates, which routes to Updater.manual_check.
  if S.screen_reader_mode then
    if type(REAASSIST_SCREEN_READER_ENTRY) == "function" then
      local ok_sr, sr_err = xpcall(REAASSIST_SCREEN_READER_ENTRY,
        debug.traceback)
      if not ok_sr then
        local msg = "Could not start ReaAssist Screen Reader Mode.\n\n" ..
          tostring(sr_err)
        if reaper.osara_outputMessage then
          local note_path = RA.TEMP_DIR .. "ScreenReader_Startup_Failure.txt"
          local saved = false
          local f = io.open(note_path, "wb")
          if f then
            f:write(msg)
            saved = f:close() == true
          end
          local spoken = "Could not start ReaAssist Screen Reader Mode."
          if saved then
            spoken = spoken .. "\n\nDetails saved to the ReaAssist Temp folder."
          else
            spoken = spoken .. "\n\nReaAssist could not save a text copy of this failure."
          end
          pcall(reaper.osara_outputMessage, spoken)
        else
          reaper.ShowMessageBox(
            msg,
            "ReaAssist - Screen Reader Mode",
            0)
        end
        if AppController and AppController.close_instance then
          AppController.close_instance()
        else
          S.script_open = false
        end
      end
    else
      local msg =
        "Run the ReaAssist_Screen_Reader_Mode.lua action to use the accessible workflow."
      if reaper.osara_outputMessage then
        pcall(reaper.osara_outputMessage, msg)
      else
        reaper.ShowMessageBox(
          msg,
          "ReaAssist - Screen Reader Mode",
          0)
      end
      if AppController and AppController.close_instance then
        AppController.close_instance()
      else
        S.script_open = false
      end
    end
  else
    Startup.mark("imgui_init_start")
    if not RA.init_imgui_runtime() then return end
    Startup.mark("imgui_init_done")
    if S.bootstrap_active then
      Bootstrap.loop()
    else
      if S._ui_loaded_cleanly and not S._factory_reset_clean_boot then
        Store.mark_first_launch_complete()
      end
      loop()
    end
  end
end
